INSERT INTO `app_news` VALUES (11, '2025-10-11 16:07:45.000000', 'admin@gmail.com', 'Sáng 25/4/2023, Thường trực Huyện ủy Lục Nam chỉ đạo tổ chức Hội nghị giao ban Ban Chỉ đạo (BCĐ) xây dựng, thực hiện Quy chế dân chủ (QCDC) ở cơ sở, Ban Chỉ đạo hoạt động Tổ Dân vận cộng đồng huyện Quí I/2023, triển khai nhiệm vụ Quí II/2023 và trong thời gian tới.', 'https://bacgiang.gov.vn/image/journal/article?img_id=16767004', 'Huyện ủy AA tăng cường chỉ đạo thực hiện quy chế dân chủ ở cơ sở, xây dựng chính quyền thân thiện và hoạt động của Tổ Dân vận cộng đồng ở thôn, tổ dân phố trên địa bàn huyện', '2025-10-11 16:08:59.000000', 'admin@gmail.com', 'Sáng 25/4/2023, Thường trực Huyện ủy Lục Nam chỉ đạo tổ chức Hội nghị giao ban Ban Chỉ đạo (BCĐ) xây dựng, thực hiện Quy chế dân chủ (QCDC) ở cơ sở, Ban Chỉ đạo hoạt động Tổ Dân vận cộng đồng huyện Quí I/2023, triển khai nhiệm vụ Quí II/2023 và trong thời gian tới', '2023-07-20 14:56:33.000000', b'1', 11, 2, 'huyen-uy-luc-nam-tang-cuong-chi-ao-thuc-hien-quy-che-dan-chu-o-co-so-xay-dung-chinh-quyen-than-thien-va-hoat-ong-cua-to-dan-van-cong-ong-o-thon-to-dan');
INSERT INTO `app_news` VALUES (14, '2025-10-13 15:41:01.000000', 'admin@gmail.com', 'Sáng 25/4/2023, Thường trực Huyện ủy Lục Nam chỉ đạo tổ chức Hội nghị giao ban Ban Chỉ đạo (BCĐ) xây dựng, thực hiện Quy chế dân chủ (QCDC) ở cơ sở, Ban Chỉ đạo hoạt động Tổ Dân vận cộng đồng huyện Quí I/2023, triển khai nhiệm vụ Quí II/2023 và trong thời gian tới.', 'https://bacgiang.gov.vn/image/journal/article?img_id=16767004', 'Huyện ủy ba tăng cường chỉ đạo thực hiện quy chế dân chủ ở cơ sở, xây dựng chính quyền thân thiện và hoạt động của Tổ Dân vận cộng đồng ở thôn, tổ dân phố trên địa bàn huyện', NULL, NULL, 'Sáng 25/4/2023, Thường trực Huyện ủy Lục Nam chỉ đạo tổ chức Hội nghị giao ban Ban Chỉ đạo (BCĐ) xây dựng, thực hiện Quy chế dân chủ (QCDC) ở cơ sở, Ban Chỉ đạo hoạt động Tổ Dân vận cộng đồng huyện Quí I/2023, triển khai nhiệm vụ Quí II/2023 và trong thời gian tới', '2023-07-20 14:56:33.000000', b'1', 11, 2, 'huyen-uy-luc-nam-tang-cuong-chi-ao-thuc-hien-quy-che-dan-chu-o-co-so-xay-dung-chinh-quyen-than-thien-va-hoat-ong-cua-to-dan-van-cong-ong-o-thon-to-dan');

-- ----------------------------
-- Table structure for app_qas
-- ----------------------------
DROP TABLE IF EXISTS `app_qas`;
CREATE TABLE `app_qas`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `nameq` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `emailq` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `phoneq` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `contentq` mediumtext CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL,
  `timeq` datetime(6) NULL DEFAULT NULL,
  `namea` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `timea` datetime(6) NULL DEFAULT NULL,
  `contenta` mediumtext CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL,
  `created_at` datetime(6) NULL DEFAULT NULL,
  `created_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `updated_at` datetime(6) NULL DEFAULT NULL,
  `updated_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `active` bit(1) NULL DEFAULT NULL,
  `app_id` bigint(20) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `FKc7fv393hmacwpxpgl1d1ivnl6`(`app_id`) USING BTREE,
  CONSTRAINT `FKc7fv393hmacwpxpgl1d1ivnl6` FOREIGN KEY (`app_id`) REFERENCES `apps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_vietnamese_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of app_qas
-- ----------------------------
INSERT INTO `app_qas` VALUES (2, 'Cử tri xã Biển Động, huyện Lục Ngạn', 'ducnv@gmail.com', '84889659863', 'UBND tỉnh kiến nghị Bộ Giao thông vận tải sửa chữa Quốc lộ 31 đoạn dốc Lau nối xã Biển Động với xã Cẩm Đàn, huyện Sơn Động đang xuống cấp do ảnh hưởng của cơn bão số 3 (hiện tại đường bị sạt lở nghiêm trọng) gây mất an toàn giao thông.', '2023-07-20 14:56:33.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2023-10-20 14:56:33.000000', 'UBND tỉnh đã chỉ đạo Sở Giao thông vận tải (nay là Sở Xây dựng) tập trung giải quyết dứt điểm ý kiến, kiến nghị của cử tri, kết quả như sau:\r\n\r\nTiếp thu ý kiến của cử tri, Sở Giao thông vận tải (nay là Sở Xây dựng) đã chỉ đạo đơn vị quản lý đường bộ kiểm tra, rà soát hiện trường và xử lý, khắc phục những vị trí mặt đường bị hư hỏng, xuống cấp do ảnh hưởng của cơn bão số 3 để đảm bảo an toàn giao thông và phục vụ nhu cầu đi lại của nhân dân. Đến nay, công tác khắc phục đã hoàn thành, đảm bảo giao thông đi lại thuận lợi, an toàn.', '2025-10-11 15:29:30.000000', 'admin@gmail.com', '2025-10-11 15:57:01.000000', 'admin@gmail.com', b'1', 11);
INSERT INTO `app_qas` VALUES (3, 'Cử tri xã Lương Phong, huyện Hiệp Hòa', 'haingo@gmail.com', '84635224414', 'UBND tỉnh chỉ đạo cơ quan chức năng kiểm tra thổ nhưỡng đất nông nghiệp trên địa bàn thôn Cấm, xã Lương Phong vì hiện nay sản xuất nông nghiệp không có năng suất và dịch bệnh trên cây trồng bị nhiễm nặng mặc dù đã dùng nhiều biện pháp song không có hiệu quả.', '2023-07-20 14:56:33.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2023-10-20 14:56:33.000000', 'UBND tỉnh đã chỉ đạo Sở Nông nghiệp và PTNT (nay là Sở Nông nghiệp và Môi trường) chủ trì, phối hợp UBND huyện Hiệp Hòa tập trung giải quyết dứt điểm ý kiến, kiến nghị của cử tri, kết quả như sau:\r\n\r\nTổng diện tích cánh đồng của thôn Cấm khoảng 45 ha, hiện nay đang sản xuất lúa 2 vụ/năm, với các giống chủ yếu là VNR20 và TBR 225. Từ năm 2023- 2024, lúa trên cánh đồng có hiện tượng vàng lá, đốm sọc, bạc lá, năng suất giảm dần (Năm 2023 và vụ Chiêm xuân năm 2024 năng suất lúa trung bình khoảng 200 kg/sào; riêng vụ Mùa năm 2024 năng suất giảm mạnh chỉ đạt trên 100 kg/sào). Theo đánh giá ban đầu nguyên nhân năng suất lúa giảm do: Những năm gần đây, ảnh hưởng của biến đổi khí hậu, thời tiết cực đoan nên diễn biến của tình hình sâu bệnh phát sinh và gây hại bất thường, nhất là các bệnh do vi khuẩn gây hại trên lúa (đốm sọc vi khuẩn, bạc lá); vụ Mùa năm 2024 bị ảnh hưởng nặng của cơn bão số 3 vào giai đoạn lúa trỗ bông dẫn đến năng suất lúa của các hộ nông dân tại cánh đồng thôn Cấm của xã Lương Phong giảm mạnh (khoảng 50%).\r\n\r\nVụ Chiêm xuân năm 2024-2025, Sở Nông nghiệp và Môi trường đã chỉ đạo Chi cục Trồng trọt và BVTV phối hợp với đơn vị chuyên môn huyện Hiệp Hoà tập trung hướng dẫn nông dân sử dụng giống lúa có khả năng chống chịu với sâu bệnh (nhất là bệnh đốm sọc vi khuẩn, bạc lá); đẩy mạnh áp dụng cơ giới hoá vào sản xuất, tăng cường sử dụng phân bón hữu cơ, chế phẩm sinh học, thuốc BVTV sinh học nhằm tăng năng suất, chất lượng sản phẩm; làm tốt công tác dự tính dự báo, thường xuyên kiểm tra đồng ruộng để có hướng dẫn kịp thời người nông dân phòng trừ kịp thời các đối tượng sâu bệnh hại trên cây lúa. Hiện nay, diện tích lúa TBR225, VNR20 trên cánh đồng thôn Cấm xã Lương Phong đang sinh trưởng phát triển tốt, dự kiến năng suất ổn định.', '2025-10-11 15:55:49.000000', 'anonymousUser', NULL, NULL, b'1', 11);
INSERT INTO `app_qas` VALUES (4, 'Cử tri xã Xuân Cẩm, huyện Hiệp Hòa', 'sonbnh@gmail.com', '03669936888', ' UBND tỉnh quan tâm chỉ đạo các cơ quan chức năng xem xét không thu tiền đo đạc bản đồ và chi phí khi nhân dân làm thủ tục cấp GCNQSD đất và đẩy nhanh tiến độ cấp giấy theo Chỉ thị số 30-CT/TU ngày 31/01/2024 của Ban Thường vụ Tỉnh ủy.', '2025-10-06 16:22:48.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2025-10-14 16:22:51.000000', 'UBND tỉnh đã chỉ đạo Sở Tài nguyên và Môi trường (nay là Sở Nông nghiệp và Môi trường) chủ trì, phối hợp UBND huyện Hiệp Hòa tập trung giải quyết dứt điểm ý kiến, kiến nghị của cử tri, kết quả như sau:\r\n\r\na) Về nội dung không thu tiền đo đạc bản đồ, chi phí làm thủ tục cấp GCNQSDĐ: Theo quy định của Luật Đất đai 2024 thì đăng ký đất đai là bắt buộc (tại khoản 1 Điều 131) và cấp GCNQSDĐ được cấp theo nhu cầu và đủ điều kiện (khoản 1 Điều 135 Luật Đất đai).', '2025-10-13 16:22:58.000000', 'admin@gmail.com', '2025-10-13 16:23:13.000000', 'admin@gmail.com', b'1', 11);
INSERT INTO `app_qas` VALUES (5, 'Cử tri phường Dĩnh Kế, thành phố Bắc Giang', 'truongnx@gmail.com', '09174592153', 'UBND tỉnh kiến nghị các cơ quan có thẩm quyền xem xét miễn phí dịch vụ đăng ký trả tiền qua tài khoản ngân hàng cho các đối tượng người có công, thân nhân người có công, đối tượng bảo trợ xã hội, đối tượng là cán bộ hưu, trợ cấp BHXH.', '2025-10-13 16:23:24.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2025-10-13 16:23:26.000000', 'UBND tỉnh đã chỉ đạo Ngân hàng Nhà nước Chi nhánh tỉnh Bắc Giang (nay là Ngân hàng Nhà nước Khu vực 5) tập trung giải quyết dứt điểm ý kiến, kiến nghị của cử tri, kết quả như sau:\r\n\r\nHiện nay tại một số ngân hàng như BIDV chi nhánh Bắc Giang có chính sách hỗ trợ với nhóm khách hàng nhận lương hưu, hưởng trợ cấp BHXH hàng tháng như miễn phí mở tài khoản, miễn phí quản lý tài khoản trong 3 năm đầu, miễn phí phát hành thẻ lần đầu, miễn phí rút tiền một năm đầu tại ATM; một số ngân hàng đang xây dựng chính sách ưu đãi dành cho đối tượng khách hàng nêu trên và sẽ triển khai trong thời gian sắp tới.', '2025-10-13 16:23:30.000000', 'admin_portal_bn@gmail.com', NULL, NULL, b'1', 11);
INSERT INTO `app_qas` VALUES (6, 'Cử tri xã Cao Xá, huyện Tân Yên', 'thienvd@gmail.com', '03356942881', 'Đường tỉnh 298 đã được nâng cấp, sửa chữa và đưa vào khai thác, sử dụng. Tuy nhiên, tại các đường đấu nối hiện nay không có biển cảnh báo (đường rẽ vào các thôn: Trung, Hạ, Trại xã Cao Xá; đường vào Trường Tiểu học Cao Xá khu B, Trường Mầm non Cao Xá khu B, đường gần Trạm điện trung gian đi thôn Ngọc Yên,...). Tại các điểm này thường xuyên xảy ra tai nạn giao thông, gây nguy hiểm cho người dân và học sinh. Cử tri đã phản ánh nhiều lần nhưng chưa được giải quyết. Đề nghị UBND tỉnh chỉ đạo cơ quan chuyên môn cho khảo sát, lắp đặt biển cảnh báo để đảm bảo an toàn cho người dân khi tham gia giao thông', '2025-10-13 23:59:56.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2025-10-13 16:27:12.000000', 'UBND tỉnh đã chỉ đạo Sở Giao thông vận tải (nay là Sở Xây dựng) tập trung giải quyết dứt điểm ý kiến, kiến nghị của cử tri, kết quả như sau:\r\n\r\nNgày 13/01/2025, Sở Giao thông vận tải (nay là Sở Xây dựng) đã chỉ đạo đơn vị quản lý đường bộ phối hợp với UBND xã Cao Xá kiểm tra hiện trường tuyến đường tỉnh 298 và xác nhận các vị trí cử tri kiến nghị nêu trên hiện nay đã được cắm đầy đủ các biển cảnh báo giao thông theo QCVN 41:2024/BGTVT.', '2025-10-13 16:27:17.000000', 'admin@gmail.com', NULL, NULL, b'1', 11);
INSERT INTO `app_qas` VALUES (7, 'Cử tri thị trấn Thắng, huyện Hiệp Hòa', 'huyvd@gmail.com', '08883369982', ' Hiện nay trên địa bàn thị trấn Thắng và một số xã lân cận số lượng học sinh có nhu cầu học tại các trường THPT công lập rất lớn. Tuy nhiên tỷ lệ tuyển sinh của các trường này thấp. Đề nghị UBND tỉnh xem xét đầu tư mở rộng quy mô trường, lớp công lập để đảm bảo cháu học sinh được học ở các trường công lập.', '2025-10-13 15:28:14.000000', 'BBT Cổng Thông tin điện tử tỉnh', '2025-10-13 16:29:08.000000', '* Sở Giáo dục và Đào tạo, UBND huyện Hiệp Hòa, các cơ quan, đơn vị liên quan trả lời như sau:\r\n\r\nThực hiện Quyết định số 522/QĐ-TTg ngày 14/5/2018 của Thủ tướng Chính phủ phê duyệt Đề án “Giáo dục hướng nghiệp và định hướng phân luồng học sinh giai đoạn 2018-2025”, UBND tỉnh ban hành Kế hoạch số 2905/KH-UBND ngày 13/8/2019 về triển khai Đề án Giáo dục hướng nghiệp và định hướng phân luồng học sinh giai đoạn 2018-2025, theo đó mục tiêu từ năm 2020 đến 2025 cụ thể là: Học sinh tốt nghiệp THCS tiếp tục học tập tại các cơ sở GDNN đào tạo trình độ sơ cấp, trung cấp phấn đấu có ít nhất 40% học sinh; đối với các địa phương có điều kiện KT-XH đặc biệt khó khăn đạt ít nhất 30%.', '2025-10-13 16:28:31.000000', 'admin@gmail.com', NULL, NULL, b'1', 11);

