INSERT INTO `sync_articles` VALUES (9, '29334604', 'Đại biểu Quốc hội Trần Văn Tuấn: Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư...', 'Đại biểu Quốc hội Trần Văn Tuấn: Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân', '/documents/37632/23566312/%C4%90B+Tu%E1%BA%A5n.jpg/156f1a01-30c0-9fe7-be18-68bcc98c6048?t=1761726717629', '<p>(BNP) - Sáng 29/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường, cho ý kiến vào Báo cáo của Chính phủ về tình hình triển khai Nghị quyết số 16 của Quốc hội về Kế hoạch phát triển kinh tế - xã hội 5 năm 2021 - 2025.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C4%90B+Tu%E1%BA%A5n.jpg/156f1a01-30c0-9fe7-be18-68bcc98c6048?t=1761726717629\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Quốc hội Trần Văn Tuấn thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham luận với chủ đề “Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân, nhất là từ các doanh nghiệp nhỏ và vừa, để thúc đẩy kinh tế phát triển nhanh và bền vững”, Phó trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn khẳng định: Trong giai đoạn 2021 - 2025, bối cảnh thế giới và trong nước có nhiều khó khăn, thách thức, song với sự điều hành linh hoạt, quyết liệt của Chính phủ, dự kiến tốc độ tăng trưởng GDP bình quân đạt khoảng 6,3%. Đầu tư công, đầu tư tư nhân, thu hút đầu tư FDI và xuất khẩu là những động lực chính thúc đẩy sự tăng trưởng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, bên cạnh những kết quả đạt được cũng đã và đang bộc lộ những mặt hạn chế, tiềm ẩn những yếu tố có thể dẫn đến tăng trưởng thiếu sự tự chủ và bền vững, dễ bị “đứt gãy” khi một trong các động lực tăng trưởng từ đầu tư công, FDI, xuất khẩu suy yếu; cơ cấu kinh tế mất cân đối do khu vực kinh tế tư nhân trong nước chưa phát triển tương xứng, cụ thể:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong giai đoạn 2021 - 2025 hiệu quả đầu tư công còn có mặt hạn chế, chưa tương xứng với nguồn lực bỏ ra, thể hiện ở chỉ số ICOR (chi phí vốn để tăng thêm 1 đơn vị GDP) vẫn còn cao (6,4%), chưa có nhiều cải thiện so với giai đoạn trước; một số dự án vẫn gặp khó khăn về tiến độ, đội vốn, đặc biệt do vấn đề đền bù, giải phóng mặt bằng….</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tăng trưởng FDI trong lĩnh vực công nghệ cao chưa đạt mức kỳ vọng (chủ yếu gia công, lắp ráp, sử dụng linh kiện nhập khẩu). Liên kết giữa doanh nghiệp FDI với doanh nghiệp nội địa còn yếu; giá trị gia tăng tại Việt Nam thấp; chuỗi cung ứng nội địa chưa phát triển; chuyển giao công nghệ hạn chế, nhất là công nghệ cao… Đặc biệt, khi FDI chiếm tỷ trọng lớn, tiềm ẩn nguy cơ mất tự chủ, bởi các nhà đầu tư có thể rút vốn hoặc chuyển hướng đầu tư bất cứ lúc nào; rồi rủi ro khi doanh nghiệp FDI có hành vi chuyển giá, trốn thuế…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chất lượng và giá trị gia tăng của hàng hoá xuất khẩu còn thấp, chưa tham gia sâu vào chuỗi giá trị toàn cầu, phụ thuộc nhiều thị trường bên ngoài, tiềm ẩn nguy cơ nền kinh tế dễ bị tổn thương trước những biến động kinh tế, chính trị trong khu vực và thế giới (như cạnh tranh thương mại, biến động giá nguyên liệu, thay đổi chính sách của các nước nhập khẩu)…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, khi xuất khẩu vẫn phụ thuộc nhiều vào khu vực FDI (năm 2024, giá trị kim ngạch xuất khẩu từ khu vực FDI chiếm tỷ trọng 71,7%), tiềm ẩn nguy cơ khi có biến động (như suy giảm đơn hàng, dịch chuyển chuỗi cung ứng toàn cầu…) tăng trưởng xuất khẩu và GDP của Việt Nam sẽ suy giảm. Trong khi đó, kinh tế tư nhân - vốn là động lực dài hạn cho sự phát triển lại đang phải đối mặt với nhiều rào cản kìm hãm, chưa có sự bứt phá về quy mô và năng lực cạnh tranh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Tuấn cho rằng, trong giai đoạn tới, bên cạnh việc tiếp tục phát huy những động lực tăng trưởng từ đầu tư công, thu hút đầu tư FDI và xuất khẩu, chúng ta cần nhanh chóng hiện thực hoá những quan điểm, mục tiêu, nhiệm vụ, giải pháp theo tinh thần Nghị quyết số 68&nbsp;ngày 4/5/2025 của Bộ Chính trị về phát triển kinh tế tư nhân. Qua đó tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân, nhất là từ các doanh nghiệp nhỏ và vừa, để thúc đẩy kinh tế phát triển nhanh và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chú trọng tiếp tục xây dựng, hoàn thiện hệ thống pháp luật&nbsp;với những cơ chế, chính sách đột phá, tạo môi trường thông thoáng, minh bạch, khuyến khích kinh tế tư nhân phát triển (nhất là về: đất đai, hạ tầng, đầu tư, tài chính, tín dụng, thủ tục hành chính, khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số, đào tạo nhân lực…).&nbsp;Cụ thể là cần khẩn trương nghiên cứu sửa đổi Luật Hỗ trợ doanh nghiệp nhỏ và vừa năm 2017 nhằm khắc phục một số bất cập đã bộc lộ sau hơn 7 năm triển khai thực hiện như: Tiêu chí xác định doanh nghiệp nhỏ và vừa còn chung chung; chưa rõ chính sách hỗ trợ chuyên biệt về chuyển đổi số, đổi mới sáng tạo và hội nhập quốc tế; chưa có ưu tiên rõ ràng đối với nhóm doanh nghiệp siêu nhỏ, hộ kinh doanh chuyển thành doanh nghiệp và doanh nghiệp khởi nghiệp sáng tạo…&nbsp;Qua đó tạo sự đột phá về phát triển doanh nghiệp nhỏ và vừa trong giai đoạn tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với việc xác định kinh tế tư nhân là một động lực quan trọng nhất của nền kinh tế quốc gia cũng cần coi doanh nghiệp nhỏ và vừa là “xương sống” của nền kinh tế. Thực tế, cũng như&nbsp;hầu hết các nước trên thế giới, tỷ lệ doanh nghiệp nhỏ và vừa ở Việt Nam trong tổng số doanh nghiệp đang hoạt động trong nền kinh tế luôn rất cao, hiện chiếm khoảng 98%.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-tran-van-tuan-can-tao-ong-luc-manh-me-hon-tu-khu-vuc-kinh-te-tu-nhan-29334604', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 225, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (10, '29265812', 'Hôm nay (29/10), Quốc hội thảo luận kết quả thực hiện kế hoạch phát triển kinh tế -...', 'Hôm nay (29/10), Quốc hội thảo luận kết quả thực hiện kế hoạch phát triển kinh tế - xã hội', '/documents/37632/23566312/z7163263372586_be0e51e3e96d5a0b79c2bcb74e3d4466.jpg/d0340fa1-5fb3-5da0-4409-48fcfd8b9d8e?t=1761700093634', '<p>(BNP) - Theo chương trình Kỳ họp thứ 10, ngày 29/10, Quốc hội dành cả ngày thảo luận tại hội trường về đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội. Phiên họp được truyền hình và phát thanh trực tiếp.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7163263372586_be0e51e3e96d5a0b79c2bcb74e3d4466.jpg/d0340fa1-5fb3-5da0-4409-48fcfd8b9d8e?t=1761700093634\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quốc hội thảo luận tại Hội trường ngày 28/10.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi sáng, Quốc hội thảo luận đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó, Quốc hội thảo luận kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025: phát triển kinh tế - xã hội; cơ cấu lại nền kinh tế.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao về việc ban hành văn bản điều chỉnh nội dung thuộc thẩm quyền của Quốc hội để xử lý vấn đề phát sinh khi thực hiện sắp xếp tổ chức bộ máy Nhà nước, đẩy mạnh phân cấp, phân quyền và tháo gỡ vướng mắc do quy định của pháp luật (theo quy định của Luật Tổ chức Chính phủ, Luật Tổ chức chính quyền địa phương, Nghị quyết số 190/2025/QH15 của Quốc hội quy định về xử lý một số vấn đề liên quan đến sắp xếp tổ chức bộ máy nhà nước, Nghị quyết số 206/2025/QH15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật).</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Tòa án nhân dân tối cao, Viện kiểm sát nhân dân tối cao về tình hình thi hành Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội năm 2025.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-29-10-quoc-hoi-thao-luan-ket-qua-thuc-hien-ke-hoach-phat-trien-kinh-te-xa-hoi-29265812', '', 'BNP', 66, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (18, '29149836', 'Văn phòng Thường trực Ban Chỉ đạo 389 Quốc gia làm việc với Ban Chỉ đạo 389 tỉnh Bắc...', 'Văn phòng Thường trực Ban Chỉ đạo 389 Quốc gia làm việc với Ban Chỉ đạo 389 tỉnh Bắc Ninh về công tác chống buôn lậu, gian lận thương mại và hàng giả', '/documents/37632/23288501/z7164362681652_f36e649ae1b44f0ee8dfcf0f15107806.jpg/30da8331-2919-b0ce-af8e-0e3a1b2bff15?t=1761643542563', '<p>(BNP) – Chiều 28/10,&nbsp;Đoàn công tác của&nbsp;Văn phòng Thường trực&nbsp;Ban Chỉ đạo&nbsp;(BCĐ)&nbsp;389 Quốc gia&nbsp;do đồng chí Trần Đức Đông, Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia làm Trưởng đoàn có buổi làm việc với&nbsp;BCĐ&nbsp;389 tỉnh về công tác chống buôn lậu, gian lận...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164362681652_f36e649ae1b44f0ee8dfcf0f15107806.jpg/30da8331-2919-b0ce-af8e-0e3a1b2bff15?t=1761643542563\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo báo cáo của BCĐ 389 tỉnh<span lang=\"VI\">, thực hiện Chỉ thị số 13/CT-TTg ngày 17/5/2025 của Thủ tướng Chính phủ về tăng cường công tác chống buôn lậu, gian lận thương mại và hàng giả trong tình hình mới, </span>BCĐ <span lang=\"VI\">389 tỉnh ban hành nhiều văn bản chỉ đạo, hướng dẫn triển khai đồng bộ tới các sở, ngành, lực lượng chức năng và địa phương.</span> <span lang=\"VI\">Các đợt cao điểm được tổ chức quyết liệt, bám sát phương châm “4 không: không khoan nhượng, không ngừng nghỉ, không có vùng cấm, không có ngoại lệ”.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Từ ngày 17/5 đến 15/10/2025, các lực lượng chức năng trong tỉnh phát hiện, xử lý 1.662 vụ vi phạm với 1.664 đối tượng, trong đó xử lý hình sự 17 vụ/19 bị can, xử lý hành chính 1.645 vụ, tổng số tiền thu nộp ngân sách Nhà nước hơn 201 tỷ đồng.</span> <span lang=\"VI\">Công an tỉnh khởi tố 17 vụ, xử phạt hành chính 81 vụ; Chi cục Quản lý thị trường xử lý 261 vụ; Cục Thuế tỉnh thanh tra, kiểm tra 727 doanh nghiệp, truy thu và xử phạt hơn 188 tỷ đồng; Chi cục Hải quan khu vực V xử lý 497 vụ, phạt hơn 4 tỷ đồng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">B</span>ên cạnh đó, BCĐ<span lang=\"VI\"> 389 tỉnh</span> <span lang=\"VI\">nhận diện nhiều phương thức, thủ đoạn mới của các đối tượng vi phạm như lợi dụng thương mại điện tử, mạng xã hội, đơn vị vận chuyển trung gian để buôn bán hàng nhập lậu, hàng giả, hàng kém chất lượng</span>; &nbsp;thiết lập đường dây nóng và hộp thư điện tử (0981.027.389 &nbsp;<span lang=\"VI\">duongdaynong389bacninh@gmail.com) để tiếp nhận, xử lý tin báo, góp phần huy động người dân, doanh nghiệp tham gia giám sát, tố giác hành vi vi phạm.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Công tác phối hợp giữa các ngành Công an, Quản lý thị trường, Hải quan, Thuế, Y tế, Nông nghiệp… được duy trì thường xuyên, hiệu quả, góp phần răn đe, ổn định thị trường, bảo vệ quyền lợi người tiêu dùng và doanh nghiệp.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Tuy nhiên, công tác nắm bắt, dự báo tình hình còn hạn chế; lực lượng mỏng, kinh phí và phương tiện phục vụ kiểm tra, tuyên truyền còn thiếu. Một số Ban Chỉ đạo cấp xã, phường mới thành lập nên hoạt động còn lúng túng, chưa phát huy hiệu quả.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, các đại biểu tập trung&nbsp;trao đổi,&nbsp;thảo luận&nbsp;về sự phối hợp, chia sẻ thông tin giữa các ngành, địa phương; những khó khăn, vướng mắc trong kiểm tra, kiểm soát hoạt động sản xuất, kinh doanh hàng hóa, trong phát hiện, xử lý các hành vi vi phạm trong kinh doanh thương mại điện tử…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164362690532_5a7ca69c1cda3a4db7ba443981dcbba1.jpg/c76394a3-ef02-2671-03f4-2ddf9b869a6b?t=1761643860557\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia Trần Đức Đông phát biểu kết luận.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu kết luận buổi làm việc, Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia Trần Đức Đông ghi nhận, đánh giá cao tinh thần trách nhiệm, sự chủ động, sáng tạo của BCĐ 389 tỉnh trong công tác phòng, chống buôn lậu, gian lận thương mại và hàng giả thời gian qua. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị BCĐ 389 tỉnh tiếp tục thực hiện nghiêm túc các chỉ đạo của Chính phủ, Thủ tướng Chính phủ và BCĐ 389 Quốc gia; chỉ đạo các sở, ngành, lực lượng chức năng căn cứ chức năng, nhiệm vụ được giao chủ động xây dựng, tổ chức kế hoạch cao điểm trước, trong và sau Tết Nguyên đán, tập trung kiểm tra, kiểm soát các mặt hàng thiết yếu, hàng hóa có nhu cầu tiêu thụ cao.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, tăng cường công tác phối hợp, chia sẻ thông tin giữa các lực lượng; đẩy mạnh công tác tuyên truyền, truyền thông để nâng cao nhận thức, huy động sự vào cuộc của người dân và doanh nghiệp trong việc phát hiện, tố giác hành vi vi phạm; kiên quyết xử lý nghiêm các tổ chức, cá nhân vi phạm, không để hình thành “điểm nóng” về buôn lậu, gian lận thương mại và hàng giả trên địa bàn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia tin tưởng rằng, với sự vào cuộc đồng bộ, quyết liệt của cả hệ thống chính trị, công tác đấu tranh chống buôn lậu, gian lận thương mại và hàng giả trên địa bàn tỉnh Bắc Ninh tiếp tục đạt nhiều kết quả tích cực, góp phần ổn định thị trường, bảo vệ quyền lợi chính đáng của người tiêu dùng và doanh nghiệp.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164477261237_86dbb624cd38b9a37b2253729bd04448.jpg/ee4a0895-1cdd-9dcd-5f4b-4c39681dec8e?t=1761645413785\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Giám đốc Công an tỉnh, Phó Trưởng BCĐ 389 tỉnh Nguyễn Hữu Bình tặng Bằng khen của Chủ tịch UBND tỉnh cho 02 tập thể.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Nhân dịp này, 02 tập thể và 07 cá nhân vinh dự được </span>tặng Bằng khen của <span lang=\"VI\">Chủ tịch UBND tỉnh Bắc Ninh vì đã có thành tích xuất sắc trong công tác phòng, chống buôn lậu, gian lận thương mại và hàng giả trên địa bàn tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/van-phong-thuong-truc-ban-chi-ao-389-quoc-gia-lam-viec-voi-ban-chi-ao-389-tinh-bac-ninh-ve-cong-tac-chong-buon-lau-gian-lan-thuong-mai-va-hang-gia-29149836', '', 'Diệu Hoa', 167, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (19, '29278551', 'Phối hợp quản lý hoạt động thị trường ngoại hối', 'Phối hợp quản lý hoạt động thị trường ngoại hối', '/documents/37632/23986559/ngoai-hoi.jpeg/10d0b297-7666-4906-ef1e-307e02d74dfd?t=1761705135462', '<p>(BNP) - Ngân hàng Nhà nước Việt Nam vừa có văn bản gửi Bộ Công an, Bộ Công Thương, Thanh tra Chính phủ về việc phối hợp quản lý hoạt động thị trường ngoại hối.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/ngoai-hoi.jpeg/10d0b297-7666-4906-ef1e-307e02d74dfd?t=1761705135462\" style=\"height: 599px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa (nguồn Internet)</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để chủ động các biện pháp ổn định thị trường ngoại hối, hạn chế tối đa rủi ro cho hoạt động của hệ thống ngân hàng, Ngân hàng Nhà nước Việt Nam đề nghị Bộ Công an, Bộ Công Thương, Thanh Tra Chính phủ chỉ đạo các đơn vị chức năng của Cơ quan thực hiện thanh tra, kiểm tra, giám sát, quản lý hoạt động ngoại hối của các tổ chức, cá nhân trong nền kinh tế; kịp thời phát hiện các hành vi vi phạm về quản lý ngoại hối, nhất là hoạt động mua, bán ngoại tệ trái pháp luật, hoạt động của thị trường ngoại hối không chính thức. Thực hiện các biện pháp để xử lý nghiêm các hành vi vi phạm pháp luật (nếu có) theo quy định.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời đề nghị các đơn vị liên quan phối hợp cung cấp thông tin về các vụ việc, các trường hợp vi phạm quy định về quản lý ngoại hối để Ngân hàng Nhà nước Việt Nam kịp thời triển khai các biện pháp quản lý thị trường ngoại hối hiệu quả, đảm bảo an toàn cho hoạt động của hệ thống ngân hàng./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/phoi-hop-quan-ly-hoat-ong-thi-truong-ngoai-hoi-29278551', '', 'BNP', 20, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (20, '27783301', 'Đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn,...', 'Đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn, miền núi, vùng sâu vùng xa', '/documents/37632/23566312/1.jpg/05e4942c-f1fb-4693-5c34-dc4049ceaec9?t=1761209620848', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh vừa ký Công văn số 3901/UBND-KTTH về việc triển khai thực hiện Công điện số 179/CĐ-TTg ngày 29/9/2025 của Thủ tướng Chính phủ trên địa bàn tỉnh.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23566312/1.jpg/05e4942c-f1fb-4693-5c34-dc4049ceaec9?t=1761209620848\" style=\"height: 648px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổ chức các chương trình khuyến mại tập trung, kích cầu tiêu dùng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để đẩy mạnh phát triển thị trường trong nước, kích cầu tiêu dùng những tháng cuối năm 2025, Chủ tịch UBND tỉnh yêu cầu các sở, cơ quan, đơn vị tiếp tục phối hợp với Sở Công Thương triển khai các giải pháp hiệu quả, thực chất gắn với tổ chức chiến dịch truyền thông đặc biệt đẩy mạnh Cuộc vận động “Người Việt Nam ưu tiên dùng hàng Việt Nam” nhằm khẳng định chất lượng sản phẩm, hàng hóa sản xuất trong nước; phát động phong trào tiêu dùng hàng Việt trên các sàn giao dịch thương mại điện tử của Việt Nam và quốc tế. Tổ chức các chương trình xúc tiến thương mại, chương trình khuyến mại tập trung, kích cầu tiêu dùng; đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn, miền núi, vùng sâu vùng xa, vùng kinh tế khó khăn; liên kết với các sàn giao dịch nông sản Việt Nam để luân chuyển hàng hóa đặc sản địa phương và sản phẩm đạt tiêu chuẩn OCOP. Tham gia trưng bày gian hàng tại Hội chợ Mùa Thu năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Tài chính chủ trì, phối hợp với các cơ quan, đơn vị liên quan cân đối nguồn ngân sách địa phương để tham mưu UBND tỉnh bố trí kinh phí thực hiện các hoạt động xúc tiến thương mại nhằm thúc đẩy tiêu thụ xuất khẩu sản phẩm của tỉnh đảm bảo đúng quy định, tiết kiệm, hiệu quả, đặc biệt là các sự kiện lớn như: Hội chợ Mùa Thu 2025; Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. Phối hợp chặt chẽ các cơ quan theo dõi sát tình hình giá cả, nhất là những hàng hóa, dịch vụ thiết yếu, để chủ động triển khai các giải pháp phù hợp, kịp thời, hiệu quả theo quẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Văn hóa, Thể thao và Du lịch chủ trì, phối hợp với các cơ quan, địa phương liên quan tập trung các giải pháp thúc đẩy các chương trình du lịch, kết hợp với các hoạt động, sự kiện văn hóa, lễ hội văn hóa, các chương trình xúc tiến thương mại trên địa bàn tỉnh, gia tăng trải nghiệm, kích cầu tiêu dùng đối với hàng hóa, dịch vụ đến du khách trong và ngoài nước, đặc biệt là các sự kiện lớn như: Hội chợ Mùa Thu 2025; Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. Đẩy mạnh phát triển công nghiệp văn hóa, công nghiệp giải trí để nhân dân được thụ hưởng và tham gia vào quá trình thương mại hóa các sản phẩm văn hóa. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngân hàng Nhà nước chi nhánh khu vực 12 chỉ đạo các tổ chức tín dụng tích cực ứng dụng chuyển đổi số trong quy trình vay vốn, rút ngắn thời gian xử lý, tăng tính minh bạch, tạo điều kiện thuận lợi cho người dân, doanh nghiệp trong tiếp cận vốn vay, nhằm thúc đẩy tiêu dùng trong nước; nghiên cứu cung cấp các gói tín dụng nhằm hỗ trợ sản xuất kinh doanh và tiêu dùng với quy trình, điều kiện vay thuận lợi để có thể giải ngân được. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND các xã, phường đẩy mạnh triển khai các chương trình xúc tiến thương mại nhằm hỗ trợ tiêu thụ sản phẩm hàng hóa sản xuất tại địa phương, đặc biệt là sự kiện Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiệp hội Doanh nghiệp nhỏ và vừa tỉnh; Hội doanh nghiệp trẻ tỉnh kịp thời nắm bắt thông tin, nhu cầu thị trường, các khó khăn, vướng mắc của các doanh nghiệp thành viên để đề xuất các cơ quan chức năng có giải pháp xử lý, tháo gỡ kịp thời, hiệu quả./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ay-manh-cac-hoat-ong-ket-noi-cung-cau-to-chuc-ua-hang-viet-ve-khu-vuc-nong-thon-mien-nui-vung-sau-vung-xa-27783301', '', 'Diệu Hoa', 68, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (40, '29129624', 'Bắc Ninh: Danh sách 270 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 17 -...', 'Bắc Ninh: Danh sách 270 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 17 - 26/10/2025', '/documents/37632/18835561/572259620_122154228092804369_6980704119443601936_n.jpg/9652868f-e978-dafb-2724-ced9d74cddcf?t=1761624343977', '<p>(BNP) - Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 17 - 26/10/2025, ghi nhận 270 trường hợp xe ô tô vi phạm bị phạt nguội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/572259620_122154228092804369_6980704119443601936_n.jpg/9652868f-e978-dafb-2724-ced9d74cddcf?t=1761624343977\" style=\"height: 506px; width: 900px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>46&nbsp;trường hợp <span lang=\"VI\">ô tô </span>không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+1.png/4633456c-a462-17dc-c34d-3987c37d6f1b?t=1761624364825\" style=\"height: 341px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>96 trường hợp <span lang=\"VI\">ô tô </span>không chấp hành hiệu lệnh, chỉ dẫn của vạch kẻ đường:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+2.png/ddbf243d-fa88-56a8-ec63-db8f58e11943?t=1761624402216\" style=\"height: 644px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>122 trường hợp <span lang=\"VI\">ô tô </span>điều khiển xe chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/0/2810+anh+3.png/6c3792a2-9dde-7503-26fb-b646ee6e05d0?t=1761624444342\" style=\"height: 844px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>06 trường hợp <span lang=\"VI\">ô tô </span>rẽ trái tại nơi có biển cấm:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+4+%281%29.png/2d44e78e-d165-79ca-f29c-973c778cc522?t=1761624495847\" style=\"height: 87px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 01 trường hợp ô tô dừng xe dưới gầm cầu vượt: 29C-335.58;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 01 trường hợp quay đầu xe ở phần đường dành cho người đi bộ qua đường: 99A-760.84.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định.</span> <span lang=\"VI\">Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định.</span>/.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-270-truong-hop-xe-o-to-vi-pham-bi-phat-nguoi-tu-ngay-17-26-10-2025-29129624', '', 'BNP', 4746, 'Xã hội', 6, '', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (91, '30181996', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh thảo luận ở tổ về 3 dự án luật', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh thảo luận ở tổ về 3 dự án luật', '/documents/37632/23566312/a11.jpg/a97542cb-9344-e228-3f29-1425a6cd65d3?t=1761964679188', '<p>(BNP) - Chiều 31/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, các đại biểu Quốc hội tham gia thảo luận ở tổ, cho ý kiến vào 3 Dự án: Luật An ninh mạng; Luật Bảo vệ bí mật nhà nước (sửa đổi); Luật sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự. Đoàn Đại...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a11.jpg/a97542cb-9344-e228-3f29-1425a6cd65d3?t=1761964679188\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\">Các đại biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cơ bản nhất trí với các tờ trình và báo cáo thẩm tra về sự cần thiết của 3 dự án luật nhằm kịp thời quán triệt, thể chế các chủ trương, đường lối, quan điểm chỉ đạo của Đảng về an ninh trật tự, an ninh mạng, bảo vệ bí mật nhà nước trong tình hình mới. Đồng thời, các đại biểu cũng tham góp nhiều ý kiến xác đáng để cơ quan soạn thảo tiếp tục hoàn thiện 3 dự án luật bảo đảm tính khả thi cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Góp ý vào dự án Luật Bảo vệ bí mật nhà nước (sửa đổi), đại biểu Leo Thị Lịch, Ủy viên chuyên trách Hội đồng Dân tộc của Quốc hội cho rằng cần quy định rõ hơn về thẩm quyền, trách nhiệm của tổ chức, cá nhân lưu trữ, bảo vệ bí mật nhà nước trong hồ sơ lưu trữ tại địa phương. Hiện nay hệ thống chính quyền địa phương 2 cấp đang vận hành hoạt động trên hệ thống mạng LAN. Nguồn lực để đầu tư cho bảo đảm an ninh mạng cũng là vấn đề đặt ra. Vì vậy, cần tiếp tục rà soát, đánh giá tác động của việc thực hiện bảo vệ bí mật nhà nước thời gian qua để xây dựng các quy định trong quản lý bí mật nhà nước đáp ứng yêu cầu chuyển đổi số theo các cấp chính quyền và ở các cơ quan, đơn vị trong điều kiện hiện nay.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a6.jpg/8a42d8b2-5e3f-21ed-9ae3-50d89e8dc1d7?t=1761964738594\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Leo Thị Lịch phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Kim Anh, Ủy viên Ủy ban Khoa học, Công nghệ và Môi trường của Quốc hội kiến nghị: Tại khoản 3, Điều 4 quy định: “Có cơ chế đặc thù, chính sách ưu đãi để huy động, thu hút và sử dụng nhân tài trong lĩnh vực an ninh mạng”. Ban soạn thảo cần rà soát vì Luật Khoa học công nghệ và đổi mới sáng tạo đã quy định khá đầy đủ về nội dung này với những chính sách rất đột phá nhằm thu hút và sử dụng nguồn nhân lực phát triển khoa học công nghệ, trong đó có lĩnh vực an ninh mạng. Ban soạn thảo nghiên cứu, có thể dẫn chiếu đến Luật Khoa học công nghệ và đổi mới sáng tạo. Trường hợp quy định với cấp độ ưu đãi cao hơn thì có thể quy định tại luật này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đề nghị tại Điều 20 quy định về đối tượng được bảo vệ trên không gian mạng, bên cạnh đối tượng là trẻ em, cần bổ sung một số đối tượng gồm: Người già, phụ nữ, người khuyết tật, người dân tộc thiểu số, người sống trong vùng sâu, vùng xa.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a9.jpg/8f89ad40-ef10-6c33-00dd-5dfb1c028872?t=1761964789637\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Kim Anh phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Điều 40 về nghiên cứu, phát triển an ninh mạng, dự thảo luật quy định cụ thể các nội dung. Đại biểu đề nghị không nên quy định cụ thể như vậy vì khoa học công nghệ liên tục thay đổi với những nội dung rất mới, chỉ cần nêu theo hướng quy định chính sách của nhà nước đối với hoạt động nghiên cứu, phát triển an ninh mạng và tạo điều kiện để cơ quan, tổ chức, cá nhân, người có liên quan được quyền nghiên cứu phát triển an ninh mạng sẽ phù hợp hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng cho ý kiến vào dự án Luật Bảo vệ bí mật nhà nước (sửa đổi), Phó trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn cho biết, tại Điều 7 quy định phạm vi bí mật nhà nước có 13 lĩnh vực cụ thể. Tuy nhiên, trong 13 lĩnh vực cụ thể này có những quy định chung chung, thiếu sự định lượng, như vậy sẽ dễ dẫn đến hệ quả khó quản lý chặt chẽ, cơ quan có thẩm quyền xác định độ mật của tài liệu nhiều khi lúng túng hoặc lạm dụng độ mật, gây khó khăn cho người tiếp nhận, sử dụng. Đề nghị phải định lượng thật cụ thể về độ mật để quản lý chặt chẽ, tránh sự lúng túng hoặc lạm dụng việc xác định độ mật trong sử dụng tài liệu. Đồng thời, cần rà soát, đối chiếu với các luật khác để vừa bảo đảm độ mật, vừa bảo đảm tính công khai, minh bạch về thông tin.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a7.jpg/e2124416-2a8c-930a-d585-ebea6cfc231d?t=1761964842112\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Tuấn phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Điều 19 quy định thời hạn bảo vệ bí mật nhà nước về hoạt động có thể rút ngắn hơn theo quy định nhưng không quy định rõ cơ quan nào, cá nhân nào có quyền có thể rút ngắn thời hạn này. Đề nghị cần bổ sung thêm 1 khoản quy định rõ “Người đứng đầu, cấp phó được ủy quyền của người đứng đầu của cơ quan, tổ chức xác định độ mật nhà nước có thẩm quyền xác định thời hạn bảo vệ bí mật nhà nước có thể ngắn hơn thời hạn theo quy định.”</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Góp ý vào dự thảo Luật Sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự, Phó trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Thị Vân cho biết: Tại khoản 1, Điều 2 của dự thảo (bổ sung khoản 22, Điều 8 của Luật Nhập cảnh, xuất cảnh, quá cảnh, cư trú của người nước ngoài tại Việt Nam) bổ sung loại thị thực UD1 cấp cho người nước ngoài thuộc diện ưu đãi theo quy định của Luật Công nghiệp công nghệ số. Tuy nhiên, việc bổ sung thị thực UD1 lại không đi kèm với các tiêu chí rõ ràng để xác định cụ thể người nước ngoài nào thuộc diện ưu tiên, ưu đãi; không có các tiêu chí, tiêu chuẩn về trình độ chuyên môn, lĩnh vực hoạt động của cơ quan, tổ chức hoặc quy mô dự án mà người nước ngoài làm việc... sẽ gây khó khăn cho cơ quan xét duyệt, dẫn đến tình trạng áp dụng không thống nhất giữa các địa phương, dễ phát sinh tùy tiện và làm giảm hiệu quả việc thu hút nhân tài chất lượng cao vào lĩnh vực này.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a8.jpg/270b904d-7bd9-e840-6708-e88a42753532?t=1761964893211\" style=\"width: 900px; height: 640px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Thị Vân phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đề nghị bổ sung một khoản vào Điều 2 của Dự thảo (sửa đổi Điều 8) với nội dung: “Chính phủ quy định chi tiết tiêu chí xác định người nước ngoài thuộc diện ưu đãi UD1, bao gồm: (1) Lĩnh vực hoạt động ưu tiên; (2) Trình độ chuyên môn, kinh nghiệm; (3) Quy mô và tính chiến lược của các dự án đầu tư; (4) Đóng góp cho chuyển giao công nghệ và phát triển công nghiệp công nghệ số.” Như vậy sẽ bảo đảm&nbsp;tính thống nhất, minh bạch, sàng lọc đúng đối tượng chuyên gia chiến lược, phù hợp với thực tế quản lý và định hướng phát triển kinh tế số.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại khoản 9, Điều 4 (sửa đổi, bổ sung khoản 1, Điều 30 của Luật Cư trú) quy định trách nhiệm thông báo lưu trú trên phương tiện: \"Chủ sở hữu phương tiện hoặc người được giao quản lý phương tiện có trách nhiệm thông báo lưu trú”. Đại biểu cho rằng khái niệm \"phương tiện\" là quá rộng và không rõ ràng, có thể bao gồm cả tàu du lịch, xe khách đường dài, xe camper van, xe tải....Yêu cầu tất cả chủ phương tiện phải thông báo lưu trú là không khả thi và tạo gánh nặng quản lý rất lớn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đề nghị cần chỉ rõ loại phương tiện nào phải thực hiện thông báo lưu trú (ví dụ: tàu du lịch lưu trú qua đêm, phương tiện cho thuê để ở như nhà di động...). Đồng thời, quy định cơ chế thông báo đơn giản, hiệu quả ,ví dụ thông báo qua ứng dụng VNeID thay vì yêu cầu khai báo trực tiếp tại cơ quan công an để&nbsp; bảo đảm tính khả thi trong thực tiễn và giảm gánh nặng thủ tục cho người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về sửa đổi, bổ sung một số điều của Luật Trật tự, an toàn giao thông đường bộ (Điều 7), khoản 1 (sửa đổi điểm h, khoản 1, Điều 7) bổ sung thu thập \"hình ảnh khoang chở khách\". Đại biểu cho rằng, việc thu thập hình ảnh trong khoang chở khách liên quan trực tiếp đến dữ liệu cá nhân nhạy cảm và quyền riêng tư của hành khách. Nếu không có quy định chặt chẽ, dữ liệu này rất dễ bị rò rỉ, lạm dụng, xâm phạm đến quyền riêng tư của cá nhân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đề nghị Ban soạn thảo bổ sung quy định: “Việc thu thập, lưu trữ, khai thác, sử dụng dữ liệu hình ảnh người lái xe, hành khách phải tuân thủ quy định của pháp luật về bảo vệ dữ liệu cá nhân và chỉ được sử dụng cho mục đích bảo đảm an ninh, trật tự, an toàn giao thông.” Nhằm&nbsp; bảo đảm tính đồng nhất với Nghị định số 13/2023/NĐ-CP ngày 17/4/2023 của Chính phủ về bảo vệ dữ liệu cá nhân. Hoặc thiết kế nội dung quy định thể hiện rõ mục đích, thời gian lưu trữ và cơ chế truy cập dữ liệu. Cụ thể: (1) Dữ liệu hình ảnh khoang chở khách chỉ được sử dụng cho mục đích bảo đảm an ninh, an toàn giao thông và phòng, chống tội phạm, không được khai thác cho mục đích thương mại. (2) Thời gian lưu trữ tối đa, phương thức mã hóa, bảo mật và cơ quan có thẩm quyền được truy cập các dữ liệu này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà (Phó Giám đốc Sở Tư pháp tỉnh Bắc Ninh) đề nghị bổ sung vào dự thảo Luật An ninh mạng quy định cụ thể về cơ chế huy động và sử dụng nguồn lực tài chính cho các chương trình đào tạo, nghiên cứu và phát triển sản phẩm an ninh mạng, nhằm&nbsp; bảo đảm tính khả thi và bền vững của chính sách. Đồng thời, cần có chính sách bảo vệ và khuyến khích doanh nghiệp công nghệ trong nước phát triển sản phẩm, dịch vụ an ninh mạng, góp phần giảm sự phụ thuộc vào công nghệ nước ngoài.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a10.jpg/c78854d9-5a01-f421-2250-87c2d7f5c4f5?t=1761964948301\" style=\"width: 900px; height: 604px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Khoản 2, Điều 48 dự thảo luật quy định: Kinh phí bảo vệ an ninh mạng của cơ quan, tổ chức, doanh nghiệp nhà nước, tổ chức chính trị phải bảo đảm tối thiểu 10% trong tổng kinh phí triển khai đề án, dự án, chương trình, kế hoạch đầu tư, ứng dụng, phát triển công nghệ thông tin.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cho rằng, quy định này thể hiện sự ưu tiên và quan tâm cho an ninh mạng, tuy nhiên với tỷ lệ phần trăm cố định có thể không phù hợp với tất cả các cơ quan, tổ chức, doanh nghiệp nhà nước, tổ chức chính trị vì nhu cầu sử dụng, mức độ rủi ro an ninh mạng có thể khác nhau giữa các cơ quan, đơn vị và việc áp dụng một tỷ lệ cứng nhắc (trên 10%) có thể dẫn đến phân bổ nguồn lực không hiệu quả hoặc gây ra những khó khăn về tài chính.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại điểm d khoản 1, điểm e khoản 5, Điều 7 quy định phạm vi bảo vệ bí mật nhà nước về chính trị, kinh tế- xã hội gồm “thông tin có tác động tiêu cực đến tình hình chính trị”; “thông tin có tác động tiêu cực đến tình hình kinh tế - xã hội.” Đại biểu cho rằng việc sử dụng cụm từ \"tác động tiêu cực\" có thể được hiểu theo nhiều cách khác nhau, dẫn đến sự thiếu nhất quán trong việc xác định và áp dụng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đề nghị cơ quan soạn thảo quy định rõ ràng hơn các tiêu chí, mức độ và phạm vi của \"tác động tiêu cực\" đến tình hình chính trị và kinh tế - xã hội. Đồng thời, cần quy định rõ quy trình phân loại bí mật nhà nước&nbsp; bảo đảm chặt chẽ, minh bạch để những thông tin thực sự cần thiết và có nguy cơ gây hại rõ ràng, nghiêm trọng mới được xếp vào danh mục bí mật nhà nước nhằm cân bằng giữa yêu cầu bảo vệ bí mật nhà nước với quyền được cung cấp thông tin của công dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại điểm a, khoản 11 quy định phạm vi bảo vệ bí mật nhà nước về thông tin tổ chức cán bộ gồm: “Chiến lược, kế hoạch, đề án về công tác tổ chức, cán bộ của cơ quan Đảng, Nhà nước, tổ chức chính trị - xã hội; chiến lược, kế hoạch, đề án về cải cách chính sách tiền lương, bảo hiểm xã hội”. Đại biểu cho rằng việc quy định \"chiến lược, kế hoạch, đề án về cải cách chính sách tiền lương, bảo hiểm xã hội\" thuộc phạm vi bảo vệ bí mật nhà nước về thông tin tổ chức cán bộ chỉ phù hợp trong một giai đoạn nhất định nếu các thông tin, định hướng còn chưa rõ ràng, chính thức có thể tác động tiêu cực đến lợi ích quốc gia, dân tộc. Mặt khác, theo quy định tại Điều 33 Luật Ban hành văn bản quy phạm pháp luật, các dự án luật, pháp lệnh, nghị quyết về chính sách tiền lương, bảo hiểm xã hội và các chính sách khác đều phải được công khai và lấy ý kiến rộng rãi Nhân dân. Do đó, đề nghị Ban soạn thảo nghiên cứu, xem xét và quy định cụ thể về nội dung này để vẫn bảo đảm an ninh, an toàn thông tin và đảm bảo nguyên tắc công khai, minh bạch trong quá trình xây dựng chính sách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Góp ý vào dự án Luật An ninh mạng, đại biểu Nguyễn Văn Thi cơ bản nhất trí với Báo cáo thẩm tra của Ủy ban Quốc phòng, An ninh và Đối ngoại: Đề nghị rà soát và bổ sung đầy đủ các hành vi bị nghiêm cấm, đặc biệt là hành vi sử dụng trí tuệ nhân tạo để tạo dựng, chỉnh sửa, lan truyền thông tin sai sự thật; giả mạo danh tính nhằm vu cáo, lừa đảo làm tổn hại uy tín lãnh đạo và an ninh quốc gia; bổ sung 1 khoản trong dự thảo luật quy định rõ trách nhiệm của doanh nghiệp cung cấp dịch vụ trên không gian mạng phải định danh địa chỉ internet đối với từng khách hàng để quản lý.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C3%90B-Thi.jpg/0577ac62-deca-c75b-b8de-4aefdf56f5d8?t=1761965004357\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Văn Thi phát biểu trong phiên thảo luận ở tổ, chiều 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cũng đề nghị Ban soạn thảo tiếp tục nghiên cứu, làm rõ và hoàn thiện một số quy định để bảo đảm tính hiệu quả và khả thi. Tại điểm c khoản 2 Điều 9: Nghiêm cấm các hành vi \"cố ý nghe lén, ghi âm, ghi hình trái phép các cuộc đàm thoại trên không gian mạng\". Vậy, ngoài các cuộc đàm thoại thì các hành vi xem lén các văn&nbsp; bản, tin nhắn, hình ảnh,... trao đổi trên không gian mạng thế nào? Đề nghị nghiên cứu bổ sung các hành vi cho đầy đủ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về việc quản lý gửi thông tin trên mạng, tại khoản 2, Điều 28: \"Tổ chức, cá nhân không được gửi thông tin mang tính thương mại vào địa chỉ điện tử của người tiếp nhận khi chưa được người tiếp nhận đồng ý hoặc khi người tiếp nhận đã từ chối, trừ trường hợp người tiếp nhận có nghĩa vụ phải tiếp nhận thông tin theo quy định của pháp luật\". Đề nghị làm rõ thế nào là \"thông tin mang tính thương mại\" bởi phần giải thích từ ngữ không có thuật ngữ này nên không rõ quy định trên nhằm chống việc gửi các thư rác quảng cáo hay nhằm bảo vệ tổ chức cá nhân có \"thông tin mang tính thương mại\".</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-oan-ai-bieu-quoc-hoi-tinh-bac-ninh-thao-luan-o-to-ve-3-du-an-luat-30181996', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 47, 'Chính trị', 2, 'true', '38762', '{}', '2025-11-01 07:12:47.386433', 2, 11);
INSERT INTO `sync_articles` VALUES (92, '29869302', 'Thống nhất nội dung, chương trình kỳ họp thứ 6 (chuyên đề) HĐND tỉnh Bắc Ninh khóa XIX', 'Thống nhất nội dung, chương trình kỳ họp thứ 6 (chuyên đề) HĐND tỉnh Bắc Ninh khóa XIX', '/documents/37632/23566312/z7174617919945_d85525f13a4c84dec2e2c5b92dd611f6.jpg/b6804662-28a3-f8c5-9215-e4884a74a686?t=1761896039688', '<p>(BNP) - Chiều 31/10, đồng chí Trần Thị Hằng, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực HĐND tỉnh chủ trì Hội nghị thống nhất nội dung, chương trình Kỳ họp thứ 6 (chuyên đề) HĐND tỉnh khóa XIX, nhiệm kỳ 2021 - 2026.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23566312/z7174617919945_d85525f13a4c84dec2e2c5b92dd611f6.jpg/b6804662-28a3-f8c5-9215-e4884a74a686?t=1761896039688\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng chủ trì hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự có các đồng chí: Lâm Thị Hương Thành, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch HĐND tỉnh; Đào Quang Khải, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh; các đồng chí Phó Chủ tịch HĐND tỉnh: Nghiêm Xuân Hưởng, Nguyễn Anh Tuấn; đại diện lãnh đạo Ủy ban MTTQ tỉnh; các sở, ngành liên quan và các Ban HĐND tỉnh; Văn phòng Đoàn Đại biểu Quốc hội&nbsp;và HĐND tỉnh, Văn phòng UBND tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo chương trình, Kỳ họp thứ 6 (chuyên đề) dự kiến diễn ra vào lúc 14 giờ&nbsp;ngày 12/11/2025 tại Hội trường Tỉnh ủy - HĐND tỉnh.</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"> <span lang=\"ES\"></span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23566312/z7174617904582_edaf1ee16838f736b1d0f430637a7883.jpg/c1fab4a8-4cbe-c09f-7a79-7e7552bb6c36?t=1761896105797\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch HĐND tỉnh Lâm Thị Hương Thành phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kỳ họp thứ 6 (chuyên đề) tập trung xem xét, cho ý kiến và thông qua nhiều dự thảo Nghị quyết về: <span lang=\"ES\">Quy định phân cấp nguồn thu, nhiệm vụ chi và tỷ lệ phân chia phần trăm (%) các khoản thu giữa ngân sách cấp tỉnh và ngân sách cấp xã trên địa bàn tỉnh Bắc Ninh; Quy định định mức chi thường xuyên ngân sách địa phương năm 2026 tỉnh Bắc Ninh; Điều chỉnh, phân bổ, thu hồi dự toán của các cơ quan, đơn vị, địa phương năm 2025; Điều chỉnh, bổ sung và phân bổ chi tiết kế hoạch đầu tư công trung hạn giai đoạn 2021-2025 và năm 2025 cho các công trình dự án cấp tỉnh quản lý; bổ sung hỗ trợ các xã, phường thanh toán khối lượng hoàn thành các dự án - lần 2 (nguồn vốn ngân sách tỉnh)…</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng đó, xem xét, cho ý kiến và thông qua các dự thảo Nghị quyết: <span lang=\"ES\">Quy định mức quà tặng đối với người có công với cách mạng, thân nhân người có công với cách mạng, người cao tuổi, hộ nghèo và các đối tượng bảo trợ xã hội trên địa bàn tỉnh Bắc Ninh; Quy định hỗ trợ chế độ điều dưỡng, phục hồi sức khỏe; hỗ trợ phục vụ công tác điều dưỡng, đón tiếp người có công với cách mạng và thân nhân người có công với cách mạng trên địa bàn tỉnh Bắc Ninh; Quy định chính sách hỗ trợ kinh phí quản lý, khai thác và sử dụng bể bơi trong các trường công lập trên địa bàn tỉnh Bắc Ninh; Quy định giá dịch vụ khám bệnh, chữa bệnh áp dụng tại các cơ sở khám bệnh, chữa bệnh của Nhà nước trên địa bàn tỉnh Bắc Ninh; Quy định một số chính sách hỗ trợ bảo tồn, phát huy tiếng dân tộc thiểu số trên địa bàn tỉnh Bắc Ninh, giai đoạn 2025-2030; </span><span lang=\"VI\">Quy định một số chính sách về hỗ trợ đào tạo nhân lực trong giáo dục nghề nghiệp, giáo dục đại học và hợp tác quốc tế đào tạo nhân lực phục vụ các ngành công nghiệp mũi nhọn, công nghiệp bán dẫn, trí tuệ nhân tạo, công nghiệp số trên địa bàn tỉnh Bắc Ninh, giai đoạn 2025</span> - <span lang=\"VI\">2030</span>…</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23566312/z7174617922853_988f114a3db9bd872bfb18ae5d3ee52b.jpg/8f0b963e-ac5f-c0fd-2908-3a80d5537420?t=1761896138550\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Đào Quang Khải phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Qua thảo luận tại Hội nghị, các đại biểu nhất trí cao về thời gian, địa điểm, nội dung, chương trình Kỳ họp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-top:8px; margin-bottom:16px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu kết luận Hội nghị,&nbsp;Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng đề nghị cơ quan được giao chủ trì chuẩn bị nội dung khẩn trương hoàn thiện hồ sơ, tài liệu bảo đảm chất lượng, tiến độ, đồng thời phối hợp chặt chẽ với các Ban của HĐND tỉnh trong quá trình thẩm tra, rà soát để Kỳ họp diễn ra đúng kế hoạch, hiệu quả, thiết thực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể, đồng chí đề nghị Ban Kinh tế - Ngân sách thẩm tra 13 dự thảo Nghị quyết; Ban Pháp chế thẩm tra 7 dự thảo Nghị quyết; Ban Văn hóa - Xã hội thẩm tra 5 dự thảo Nghị quyết.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để Kỳ họp diễn ra đúng tiến độ, bảo đảm chất lượng, đồng chí đề nghị UBND tỉnh chỉ đạo các sở, ngành, đơn vị liên quan chủ động phối hợp với các Ban của HĐND tỉnh trong việc nghiên cứu tài liệu, chuẩn bị nội dung và tổ chức thẩm tra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, giao Văn phòng Đoàn ĐBQH và HĐND tỉnh tham mưu, giúp Đảng ủy HĐND tỉnh hoàn thiện các báo cáo, tờ trình gửi Thường trực các cơ quan Đảng ủy để xem xét, cho ý kiến theo quy định, góp phần chuẩn bị tốt nội dung phục vụ Kỳ họp HĐND tỉnh sắp tới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-top:8px; margin-bottom:16px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thong-nhat-noi-dung-chuong-trinh-ky-hop-thu-6-chuyen-e-h-nd-tinh-bac-ninh-khoa-xix-29869302', '', 'Diệu Hoa', 380, 'Chính trị', 2, 'true', '38762', '{}', '2025-11-01 07:12:47.445049', 2, 11);
INSERT INTO `sync_articles` VALUES (93, '29966127', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến tham gia thảo luận ở tổ', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến tham gia thảo luận ở tổ', '/documents/37632/23566312/a1.jpg/f4d6e3ea-3c22-ddf4-fff5-6304a8ddd215?t=1761895057203', '<p>(BNP) - Sáng 31/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, sau khi nghe các báo cáo, tờ trình, các đại biểu Quốc hội tham gia thảo luận ở tổ, cho ý kiến vào các Dự án: Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế; Luật sửa đổi, bổ sung một số điều của Luật Công...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a1.jpg/f4d6e3ea-3c22-ddf4-fff5-6304a8ddd215?t=1761895057203\" style=\"width: 900px; height: 596px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh phiên thảo luận ở tổ của Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cơ bản nhất trí với các tờ trình và báo cáo thẩm tra về sự cần thiết của 2 dự án luật nhằm kịp thời quán triệt, thể chế các chủ trương, đường lối, quan điểm chỉ đạo của Đảng về ngoại giao và phát triển công nghiệp quốc phòng, anh ninh. Nội dung của 2 dự thảo luật phù hợp với chủ trương, đường lối, quan điểm chỉ đạo của Đảng; bảo đảm tính hợp hiến, hợp pháp, thống nhất trong hệ thống pháp luật. Qua đó, tạo hành lang pháp lý để tạo lập môi trường phát triển công nghiệp an ninh, đáp ứng yêu cầu cấp bách của tình hình thực tiễn; đồng thời đáp ứng yêu cầu chính trị, công tác đối ngoại, hội nhập quốc tế của Đảng và Nhà nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu cũng tham góp nhiều ý kiến xác đáng để cơ quan soạn thảo tiếp tục hoàn thiện 2 dự án luật bảo đảm tính khả thi cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Góp ý vào dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp, đại biểu Trần Văn Lâm, Ủy viên chuyên trách Ủy ban Công tác đại biểu của Quốc hội cơ bản nhất trí với các quy định về Quỹ đầu tư phát triển công nghiệp an ninh, Tổ hợp công nghiệp an ninh quốc gia, với các cơ chế, chính sách đặc thù, vượt trội nhằm tạo lập môi trường phát triển công nghiệp an ninh, đáp ứng yêu cầu cấp bách của tình hình thực tiễn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a5.jpg/b295eaa3-b8bd-c44a-646d-fe1239e170f4?t=1761895116198\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm phát biểu thảo luận tại tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, đại biểu cũng đề nghị Ban soạn thảo tiếp tục nghiên cứu, làm rõ và hoàn thiện một số quy định để bảo đảm tính hiệu quả và khả thi. Khi xây dựng cơ chế phải tính toán tận dụng hiệu quả các nguồn lực đầu tư để công nghệ quốc phòng có thể sử dụng cho an ninh và ngược lại công nghệ của an ninh có thể sử dụng cho quốc phòng. Cần có cơ chế phối hợp giữa hai quỹ này để khi cần huy động nguồn lực tổng hợp thì có thể cả hai quỹ này cùng hỗ trợ được, còn trong điều kiện bình thường thì các bên chủ động. Từ đó, tạo sức mạnh tổng hợp quốc gia phát triển các lĩnh vực công nghiệp quốc phòng, an ninh một cách hiệu quả nhất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Thị Vân cũng nhất trí về sự cần thiết và các nội dung lớn của dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp. Đồng thời góp ý một số nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về chức năng, nhiệm vụ của tổ hợp công nghiệp an ninh, đại biểu đề nghị Ban soạn thảo rà soát kỹ để bảo đảm không bỏ sót nội dung quan trọng và tránh chồng chéo với các cơ quan, tổ chức, doanh nghiệp hiện có. Xem xét bổ sung khái niệm “công nghệ chiến lược” trong phần giải thích từ ngữ của dự thảo Luật, bao quát phạm vi điều chỉnh của Luật. Luật hiện hành đã giải thích tương đối rõ các khái niệm “công nghệ nền” và “công nghệ lõi”. Trên thực tế, quá trình triển khai công nghiệp quốc phòng, an ninh cho thấy cần xác định thêm một nhóm “công nghệ chiến lược”, có ý nghĩa định hướng, chi phối, bảo đảm ưu thế công nghệ và khả năng tự chủ quốc gia trong lĩnh vực quốc phòng, an ninh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về thành phần của tổ hợp công nghiệp an ninh quốc gia, đề nghị Ban soạn thảo bổ sung khái niệm “Hội đồng quản lý phát triển công nghiệp an ninh” trong phần giải thích từ ngữ của dự thảo Luật, nhằm làm rõ vị trí pháp lý, chức năng, nhiệm vụ và thẩm quyền của tổ chức này trong hệ thống cơ quan quản lý nhà nước về công nghiệp an ninh, tránh tình trạng lúng túng trong thực thi và chồng chéo với các cơ quan quản lý, điều phối khác trong lĩnh vực công nghiệp an ninh.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a4+copy.jpg/322d4dca-0a2e-b20a-4b2d-74e43feeb521?t=1761895170266\" style=\"width: 900px; height: 649px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Thị Vân tham gia thảo luận ở tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cũng đề nghị bổ sung quy định về tiêu chí lựa chọn doanh nghiệp, tổ chức tham gia Tổ hợp công nghiệp an ninh quốc gia nhằm bảo đảm tính minh bạch, khách quan và thống nhất trong quá trình lựa chọn, tránh tình trạng áp dụng tùy tiện hoặc mang tính hành chính, hình thức. Đây cũng là giải pháp quan trọng nhằm nâng cao hiệu quả hoạt động của Tổ hợp công nghiệp an ninh quốc gia, bảo đảm Tổ hợp thực sự quy tụ được các đơn vị có năng lực, uy tín, đủ sức tham gia thực hiện các nhiệm vụ trọng yếu, chiến lược về công nghiệp an ninh trong tình hình mới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về thành viên tham gia tổ hợp công nghiệp an ninh quốc gia, đại biểu cho rằng một số nội dung cần được quy định cụ thể, rõ ràng hơn để bảo đảm tính khả thi và đồng bộ với hệ thống pháp luật hiện hành:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Về tiêu chí và cơ chế lựa chọn thành viên: Hiện dự thảo mới dừng ở quy định “thành viên tham gia là tổ chức, doanh nghiệp trong và ngoài Công an nhân dân có năng lực, tiềm lực khoa học và công nghệ”. Quy định này còn chung chung, thiếu tiêu chí định lượng và cơ chế đánh giá năng lực. Đề nghị Ban soạn thảo nghiên cứu, bổ sung quy định cụ thể tiêu chí lựa chọn thành viên, bao gồm: năng lực nghiên cứu - sản xuất, tiềm lực tài chính, năng lực công nghệ, uy tín, kinh nghiệm hợp tác trong lĩnh vực an ninh, bảo đảm an ninh thông tin và bí mật nhà nước; đồng thời có quy định nhằm khuyến khích doanh nghiệp tư nhân công nghệ cao, doanh nghiệp khởi nghiệp sáng tạo, viện nghiên cứu, cơ sở giáo dục đại học đủ năng lực tham gia, tạo điều kiện mở rộng hệ sinh thái đổi mới sáng tạo trong lĩnh vực công nghiệp an ninh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Về&nbsp;cơ chế phối hợp, điều hành và chia sẻ thông tin: Hiện dự thảo chưa quy định rõ cơ chế phối hợp giữa các thành viên trong Tổ hợp. Đề nghị bổ sung quy định cụ thể cơ chế điều phối, liên kết sản xuất - nghiên cứu - thử nghiệm - thương mại hóa sản phẩm giữa các thành viên, bảo đảm hoạt động theo chuỗi giá trị, tránh trùng lặp hoặc cạnh tranh không lành mạnh; thiết lập cơ chế chia sẻ thông tin, dữ liệu và kết quả nghiên cứu trong phạm vi được phép, có cơ chế bảo vệ bí mật nhà nước và bảo mật thương mại, bảo đảm an toàn thông tin và quyền sở hữu trí tuệ; xây dựng hệ thống đánh giá, xếp hạng và kiểm tra định kỳ đối với các thành viên Tổ hợp, làm căn cứ xem xét duy trì hoặc rút tư cách thành viên, bảo đảm tính kỷ luật, chuyên nghiệp và hiệu quả trong hoạt động.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà (Phó Giám đốc Sở Tư pháp tỉnh Bắc Ninh) đóng góp ý kiến vào 3 nội dung lớn trong dự án Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a2+%281%29.jpg/ca69b020-8cea-d835-dee6-dabcf65515b1?t=1761895220926\" style=\"width: 900px; height: 616px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Việt Hà tham gia thảo luận tại tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về hồ sơ trình về việc đàm phán điều ước quốc tế, tại khoản 3, Điều 1 dự thảo Luật bổ sung khoản 1a Điều 11 của Luật Điều ước quốc tế quy định: “Trường hợp cơ quan có thẩm quyền của Đảng, Chủ tịch nước, Thủ tướng Chính phủ đã có chỉ đạo bằng văn bản về việc quyết định đàm phán điều ước quốc tế, hồ sơ trình về việc đàm phán chỉ cần bao gồm nội dung kiến nghị ủy quyền đàm phán.”. Đồng thời, sửa đổi khoản 2 Điều 11 của Luật Điều ước quốc tế: “Trong trường hợp cần thiết, cơ quan đề xuất kiến nghị kết thúc đàm phán điều ước quốc tế. Hồ sơ trình về việc kết thúc đàm phán điều ước quốc tế phải bao gồm dự thảo điều ước quốc tế thể hiện phương án kết thúc đàm phán.” Những quy định mới này nhằm rút gọn thủ tục, tăng tính chủ động cho cơ quan đề xuất, phù hợp với chủ trương phân quyền, phân cấp trong công tác đối ngoại, đồng thời đáp ứng những tình huống thực tế phát sinh trong đàm phán quốc tế - đặc biệt là các cuộc đàm phán đa phương, hoặc đàm phán cấp cao được tiến hành trong thời gian ngắn theo chỉ đạo trực tiếp của Bộ Chính trị, Ban Bí thư, Chủ tịch nước hay Thủ tướng Chính phủ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, để bảo đảm tính minh bạch, hợp pháp và tránh bị lạm dụng, đại biểu đề nghị cần quy định cụ thể loại văn bản nào được coi là “chỉ đạo bằng văn bản” nhằm tránh trường hợp áp dụng tùy tiện các văn bản hành chính thông thường có thể ảnh hưởng đến tính pháp lý và tính chính thống của quy trình đàm phán. Về phạm vi áp dụng, cần xác định rõ những loại điều ước quốc tế nào được phép áp dụng quy định rút gọn này, không nên áp dụng đối với điều ước có nội dung tạo nghĩa vụ tài chính hoặc làm phát sinh cam kết pháp lý quốc tế phức tạp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về quy định “trong trường hợp cần thiết”, đại biểu cho rằng đây là cụm từ mang tính định tính, nếu không quy định rõ, có thể dẫn đến tùy nghi áp dụng, ảnh hưởng đến tính thống nhất và trách nhiệm giải trình. Vì vậy, đề nghị Ban soạn thảo nghiên cứu, quy định tiêu chí rõ ràng về các trường hợp cần thiết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về chấp nhận hoặc phản đối bảo lưu của bên ký kết nước ngoài (khoản 13, Điều 1, dự thảo luật), đại biểu cho rằng cần thiết phải bổ sung nguyên tắc pháp lý rõ ràng làm cơ sở cho việc quyết định chấp nhận hay phản đối bảo lưu, đồng thời quy định rõ cơ chế phối hợp giữa Bộ Ngoại giao và các bộ, ngành trong quá trình tham mưu, đề xuất phương án xử lý để bảo đảm&nbsp;thống nhất, minh bạch và bảo vệ lợi ích quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo luật cho phép Bộ Ngoại giao kịp thời thông báo khi bên nước ngoài đưa ra bảo lưu đối với điều ước quốc tế mà Việt Nam là thành viên, nhằm&nbsp;bảo đảm&nbsp;các cơ quan, tổ chức liên quan nắm bắt kịp thời, chủ động trong xử lý. Đây là quy định tiến bộ, thể hiện sự hoàn thiện về mặt quy trình trong công tác quản lý, thực thi điều ước quốc tế, đặc biệt trong bối cảnh số lượng và phạm vi điều ước mà Việt Nam tham gia ngày càng mở rộng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, dự thảo mới chỉ dừng lại ở cơ chế thông báo, mà chưa quy định cụ thể nguyên tắc, tiêu chí và thẩm quyền trong việc xem xét, quyết định chấp nhận hoặc phản đối bảo lưu của bên nước ngoài. Thực tiễn cho thấy, việc xác định quan điểm đối với bảo lưu của các quốc gia đối tác có thể ảnh hưởng trực tiếp đến hiệu lực áp dụng của điều ước quốc tế tại Việt Nam, cũng như tác động đến lợi ích, nghĩa vụ pháp lý của nước ta. Nếu thiếu căn cứ rõ ràng và thống nhất, dễ dẫn đến cách hiểu và áp dụng tùy tiện giữa các cơ quan, thậm chí tạo ra rủi ro pháp lý hoặc xung đột trong thực thi điều ước. Do đó, cần thiết phải bổ sung nguyên tắc pháp lý rõ ràng làm cơ sở cho việc quyết định chấp nhận hay phản đối bảo lưu, đồng thời quy định rõ cơ chế phối hợp giữa Bộ Ngoại giao và các bộ, ngành trong quá trình tham mưu, đề xuất phương án xử lý để đảm bảo thống nhất, minh bạch và bảo vệ lợi ích quốc gia. Đề nghị Ban soạn thảo nghiên cứu, bổ sung điểm mới vào cuối khoản 13, Điều 1 dự thảo Luật quy định về nguyên tắc bảo lưu, với nội dung: “Việc chấp nhận hoặc phản đối bảo lưu của nước ngoài được thực hiện trên cơ sở nguyên tắc bảo đảm chủ quyền, an ninh, lợi ích quốc gia, phù hợp với mục tiêu, phạm vi điều ước và thông lệ pháp lý quốc tế.”</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về đăng tải điều ước quốc tế (khoản 16, Điều 1, dự thảo luật), đại biểu tán thành với hướng sửa đổi Điều 60 của luật hiện hành. Đề nghị hoàn thiện cơ chế bảo mật, xác thực điện tử và phối hợp liên ngành để quy định này thực sự khả thi, hiệu quả và phù hợp với xu thế quản trị quốc gia hiện đại. Đề nghị Ban soạn thảo nghiên cứu, bổ sung tiêu chí rõ ràng cho việc không đăng tải công khai (điều ước liên quan đến quốc phòng, tình báo, an ninh hoặc nội dung thuộc danh mục bí mật nhà nước…); đồng thời bổ sung quy định yêu cầu cơ quan được miễn công bố phải lưu trữ và quản lý bản gốc trong hệ thống hồ sơ mật của Bộ Ngoại giao, bảo đảm truy xuất phục vụ kiểm tra, giám sát.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-oan-ai-bieu-quoc-hoi-tinh-bac-ninh-nhieu-y-kien-tham-gia-thao-luan-o-to-29966127', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 170, 'Chính trị', 2, 'true', '38762', '{}', '2025-11-01 07:12:47.519079', 2, 11);
INSERT INTO `sync_articles` VALUES (94, '29859613', 'Hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật...', 'Hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật lĩnh vực an ninh, trật tự và thảo luận ở tổ', '/documents/37632/23566312/z7169768632174_aa88d188e5b26bb764ae5fb05a3f7c25.jpg/cc35e685-2429-d7e8-0ca3-30fe488d28d7?t=1761873754805', '<p>(BNP) - Theo chương trình kỳ họp thứ 10, hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật lĩnh vực an ninh, trật tự và thảo luận ở tổ.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7169768632174_aa88d188e5b26bb764ae5fb05a3f7c25.jpg/cc35e685-2429-d7e8-0ca3-30fe488d28d7?t=1761873754805\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh họp tại hội trường ngày 30/10.</span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong buổi sáng, Quốc hội họp phiên toàn thể tại hội trường, nghe Tờ trình và Báo cáo thẩm tra về 04 dự án: Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp; Luật An ninh mạng; Luật Bảo vệ bí mật nhà nước (sửa đổi); Luật sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự; nghe Tờ trình và Báo cáo thẩm tra về dự thảo Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế. Tiếp đó, Quốc hội nghe Tờ trình và Báo cáo thẩm tra về 03 dự án: Luật Chuyển đổi số, Luật Công nghệ cao (sửa đổi), Luật sửa đổi, bổ sung một số điều của Luật Chuyển giao công nghệ. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Quốc hội thảo luận ở tổ về Dự án Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế; Dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi chiều, Quốc hội tiếp tục thảo luận ở tổ về Luật An ninh mạng; Luật Bảo vệ bí mật nhà nước (sửa đổi) và Luật sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng nay, Quốc hội sẽ nghe tờ trình về 16 dự thảo luật. Sau đó, Quốc hội dành thời gian còn lại của buổi sáng và cả buổi chiều để thảo luận về các luật liên quan đến lĩnh vực an ninh, trật tự.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-31-10-quoc-hoi-nghe-to-trinh-bao-cao-tham-tra-ve-mot-so-du-an-luat-linh-vuc-an-ninh-trat-tu-va-thao-luan-o-to-29859613', '', 'BNP', 39, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.617980', 2, 11);
INSERT INTO `sync_articles` VALUES (95, '29507401', 'Thành lập Hội đồng Giáo dục quốc phòng và an ninh tỉnh Bắc Ninh', 'Thành lập Hội đồng Giáo dục quốc phòng và an ninh tỉnh Bắc Ninh', '/documents/37632/200616/IMG_8222.jpg/cc40d36b-0393-1d31-aabd-3b174fea4c78?t=1761809845419', '<p>(BNP) - Chủ tịch UBND tỉnh Vương Quốc Tuấn vừa ký, ban hành Quyết định số 1266/QĐ-UBND về thành lập Hội đồng Giáo dục quốc phòng và an ninh (QP&amp;AN) tỉnh Bắc Ninh.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200616/IMG_8222.jpg/cc40d36b-0393-1d31-aabd-3b174fea4c78?t=1761809845419\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh có nhiệm vụ tham mưu, thực hiện công tác giáo dục QP&amp;AN trên địa bàn tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Theo Quyết định, Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh do Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn làm Chủ tịch; 04 Phó Chủ tịch Hội đồng và các thành viên là lãnh đạo các Sở, ban, ngành, tổ chức chính trị - xã hội liên quan của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Thành lập Ban Thường trực Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh gồm 15 thành viên là lãnh đạo các Sở, ban, ngành, tổ chức chính trị - xã hội liên quan của tỉnh do Đại tá Phạm Văn Tạo, Chỉ huy trưởng Bộ CHQS tỉnh làm Trưởng ban.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh có nhiệm vụ tham mưu, đề xuất giúp Tỉnh ủy, HĐND, UBND tỉnh chỉ đạo thực hiện nhiệm vụ công tác giáo dục QP&amp;AN của tỉnh; kiến nghị với các cơ quan chức năng cấp trên hoặc trình Chủ tịch Hội đồng Giáo dục QP&amp;AN cấp trên giải quyết những vấn đề liên quan trong quá trình thực hiện nhiệm vụ giáo dục QP&amp;AN của tỉnh. Xây dựng kế hoạch, đề án, nhiệm vụ quan trọng về công tác giá dục QP&amp;AN trình UBND tỉnh, Chủ tịch UBND tỉnh phê duyệt. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Chỉ đạo các sở, ban, ngành, đoàn thể tỉnh và Hội đồng Giáo dục QP&amp;AN các xã, phường tổ chức triển khai, thực hiện có hiệu quả các chủ trương, chính sách của Đảng, pháp luật của Nhà nước; các văn bản chỉ đạo, hướng dẫn của các Bộ, ngành Trung ương, của Tỉnh ủy, HĐND, UBND tỉnh về thực hiện công tác giáo dục QP&amp;AN. Hằng năm chỉ đạo cơ quan Thường trực Hội đồng giáo dục QP&amp;AN tỉnh phối hợp sở, ban, ngành, đoàn thể tỉnh và Hội đồng Giáo dục QP&amp;AN các xã, phường xây dựng kế hoạch, tổ chức bồi dưỡng kiến thức QP&amp;AN cho đối tượng 3, đối tượng 4 theo quy định. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh có quyền yêu cầu các cơ quan, đơn vị, địa phương, nhà trường báo cáo tình hình, cung cấp thông tin các vấn đề liên quan đến việc thực hiện nhiệm vụ giáo dục QP&amp;AN. Định kỳ hằng tháng hoặc đột xuất báo cáo kết quả giáo dục QP&amp;AN với Tỉnh ủy, UBND tỉnh, Hội đồng Giáo dục QP&amp;AN Quân khu 1, Hội đồng Giáo dục QP&amp;AN Trung ương.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thanh-lap-hoi-ong-giao-duc-quoc-phong-va-an-ninh-tinh-bac-ninh-29507401', '', 'Hữu Thắng', 61, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.672708', 2, 11);
INSERT INTO `sync_articles` VALUES (96, '29496706', 'Đại biểu Quốc hội Trần Văn Lâm: Nghiên cứu đổi mới khâu dự toán để nâng cao hiệu quả...', 'Đại biểu Quốc hội Trần Văn Lâm: Nghiên cứu đổi mới khâu dự toán để nâng cao hiệu quả sử dụng ngân sách', '/documents/37632/23566312/%C3%90B-L%C3%A2m-1.jpg/4508f0a7-706f-36f7-fce4-2ddfcfa68f62?t=1761807080224', '<p>(BNP) - Sáng 30/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường về tình hình kinh tế - xã hội. Ủy viên Ủy ban Công tác đại biểu của Quốc hội Trần Văn Lâm (đại biểu Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) tham luận về việc xây dựng và quản lý, sử dụng...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C3%90B-L%C3%A2m-1.jpg/4508f0a7-706f-36f7-fce4-2ddfcfa68f62?t=1761807080224\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm trong phiên thảo luận tại hội trường của Quốc hội, sáng 30/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm nhất trí với báo cáo của Chính phủ và báo cáo thẩm tra của Ủy ban Kinh tế - Tài chính của Quốc hội về tình hình tài chính - ngân sách quốc gia 1 năm và 5 năm; khẳng định việc xây dựng và thực hiện có hiệu quả các chính sách tài khóa trong thời gian qua đã góp phần quan trọng ở giữ vững ổn định vĩ mô, đưa nền kinh tế đất nước ta vượt qua các khó khăn, thách thức chưa từng có để đạt được kết quả rất tích cực như đánh giá của Quốc hội trong kỳ họp lần này. Đây cũng là cơ sở để hoạch định chiến lược phát triển đất nước trong nhiệm kỳ tới với những mục tiêu to lớn hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cho rằng, trong các yếu tố vĩ mô thì chỉ số bội chi và nợ công trong nhiều năm qua luôn được bảo đảm&nbsp;ở mức thấp hơn kế hoạch. Đây là một thành công lớn trong điều hành của Chính phủ. Nền kinh tế đất nước ta dưới sự điều hành linh hoạt và chắc tay của Chính phủ đã duy trì được bội chi ở mức thấp hơn dự toán và cho phép có dư địa cho tăng đầu tư công, hỗ trợ cho tăng trưởng cao hơn trong giai đoạn sau. Tuy nhiên, đây mới chỉ là nhìn nhận ở một khía cạnh là mở rộng tăng trưởng về mặt lượng. Vì nếu tăng trưởng trước mắt mà tăng bội chi nhưng các dự án đầu tư kém hiệu quả thì hệ lụy là khả năng trả nợ kém, gánh nặng nợ công lớn sẽ tạo áp lực lên nền kinh tế và kìm hãm tăng trưởng trong dài hạn. Thực tế thì lĩnh vực đầu tư công trong những năm qua đã có tiến bộ và đạt nhiều kết quả tích cực. Song bên cạnh đó vẫn còn nhiều hạn chế, bất cập đã được chỉ ra trong báo cáo của Chính phủ và báo cáo thẩm tra của Ủy ban Kinh tế -Tài chính, như: Khâu chuẩn bị dự án còn yếu nên còn tình trạng khó giao và chậm giao vốn đầu tư hoặc giao vốn nhiều lần; tỷ lệ giải ngân ở một số lĩnh vực, một số địa bàn còn thấp, đặc biệt là giải ngân ODA và giải ngân chương trình mục tiêu quốc gia; số chuyển nguồn vốn đầu tư hằng năm còn cao và có xu thế năm sau cao hơn năm trước, làm giảm hiệu quả đầu tư; mục tiêu đầu tư công dẫn dắt thu hút đầu tư tư đạt kết quả hạn chế, chưa được như kỳ vọng. Những điều này cho thấy chất lượng, hiệu quả đầu tư công vẫn còn là vấn đề cần phải đặc biệt quan tâm trong thời gian tới. Trong nhiệm kỳ tới, với việc đất nước sẽ triển khai nhiều dự án quan trọng quốc gia đòi hỏi nguồn lực đầu tư rất lớn nên việc nới rộng bội chi, tăng nợ công để tăng nguồn đầu tư là nhu cầu khách quan.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, việc nới rộng chính sách tài khóa này cần phải được xem xét, tính toán, cân nhắc một cách thận trọng, kỹ lưỡng, đi đôi với việc tăng cường chất lượng, hiệu quả đầu tư. Trong đó, những yếu kém ở tất cả các khâu, lĩnh vực đầu tư cần phải sớm được khắc phục, từ việc lựa chọn các dự án đầu tư phải thật sự cần thiết, có tiềm năng hỗ trợ tăng trưởng kinh tế bền vững đến các khâu chuẩn bị dự án, chuẩn bị đầu tư, tổ chức triển khai, thực hiện giải ngân để đưa nguồn vốn sớm phát huy hiệu quả, giảm thiểu tối đa các lãng phí do chậm giải ngân, chuyển nguồn sang năm sau. Có như vậy thì áp lực về bội chi nợ công mới được giải tỏa, các cân đối vĩ mô mới được&nbsp;bảo đảm&nbsp;vững chắc và tăng trưởng kinh tế mới thực sự đi vào chiều sâu, chất lượng và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về vấn đề dự toán ngân sách, trong báo cáo thẩm tra của Ủy ban Kinh tế - Tài chính và phát biểu của một số đại biểu đã đánh giá về hạn chế trong khâu dự toán thu ngân sách những năm qua không sát, dự toán thấp, vượt thu cao, đại biểu Trần Văn Lâm cho rằng cần nhìn nhận vấn đề này ở những khía cạnh khác để có giải pháp cho phù hợp. Nguồn lực tài chính là quan trọng hàng đầu, làm cơ sở cho xây dựng và thực hiện các kế hoạch phát triển kinh tế xã hội. Nguồn lực này đến chủ yếu từ thuế, từ kết quả nội tại của nền kinh tế, trong khi nền kinh tế của đất nước ta không phải lúc nào cũng có thể dự báo và có những biện pháp ứng phó đủ hiệu quả đối với những diễn biến phức tạp của các yếu tố tác động liên quan, do vậy khi xây dựng dự toán ngân sách cần phải cân nhắc để đảm bảo hệ số an toàn cao, không để xảy ra thiếu nguồn lực cho thực hiện các nhiệm vụ của đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Viện dẫn thông tin kế hoạch thu thường đặt ở cận dưới trong khung dao động có thể xảy ra để&nbsp;bảo đảm&nbsp;an toàn, nếu có điều kiện vượt thu thì việc xử lý cũng dễ hơn, vui vẻ hơn so với xử lý hụt thu dự toán. Đại biểu cho rằng tư duy này có lẽ đặc biệt phù hợp trong thực tiễn của nhiệm kỳ qua khi những lúc dịch bệnh diễn biến phức tạp, nguy cơ đổ vỡ cả nền kinh tế chứ không riêng gì khâu thu ngân sách. Tuy nhiên thực tế cho thấy khi dự toán thu thấp, nhiều địa phương vượt thu thì việc sử dụng số vượt thu chưa được căn cơ, hiệu quả, nhiều khi bố trí dàn trải cho các nhiệm vụ, các công trình, các dự án chưa thật sự cần thiết, thậm chí cả các dự án chưa có trong kế hoạch. Khâu chuẩn bị dự án vội vàng, chất lượng kém nên khó và chậm giải ngân, buộc phải chuyển nguồn. Hệ quả là nguồn lực đầu tư công bị phân tán, lãng phí, kém hiệu quả.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đề xuất trong nhiệm kỳ tới nên nghiên cứu đổi mới khâu dự toán để vừa đặt dự toán ở mức an toàn, khả thi cao, đồng thời xác định mức dự phòng vượt thu nếu điều kiện thuận lợi cho phép. Bên cạnh dự toán thu thì cũng phải xác lập ngay dự toán chi một cách đồng bộ, tương ứng để có kế hoạch bố trí, sử dụng nguồn vượt thu dự toán cho các nhiệm vụ, các dự án theo thứ tự ưu tiên đã được xác lập ngay từ đầu. Như vậy sẽ nâng cao hiệu quả sử dụng ngân sách và cũng bớt đi nỗi băn khoăn cao thấp trong khâu lập và phê duyệt dự toán ngân sách hàng năm.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-tran-van-lam-nghien-cuu-oi-moi-khau-du-toan-e-nang-cao-hieu-qua-su-dung-ngan-sach-29496706', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 183, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.717186', 2, 11);
INSERT INTO `sync_articles` VALUES (97, '29492101', 'Hôm nay (30/10), Quốc hội tiếp tục thảo luận về kết quả và kế hoạch phát triển kinh...', 'Hôm nay (30/10), Quốc hội tiếp tục thảo luận về kết quả và kế hoạch phát triển kinh tế - xã hội', '/documents/37632/23566312/z7169765952098_8ba9ae48079d201d42680b5a5e11029a.jpg/a56b68d7-6713-9bb5-5a1c-2f56e28d283b?t=1761805618783', '<p>(BNP) - Theo chương trình kỳ họp thứ 10, ngày 30/10 Quốc hội tiếp tục thảo luận ở hội trường về kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7169765952098_8ba9ae48079d201d42680b5a5e11029a.jpg/a56b68d7-6713-9bb5-5a1c-2f56e28d283b?t=1761805618783\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh tại phiên họp sáng ngày 30/10.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong phiên buổi sáng, từ 8 giờ đến 9 giờ 30 phút, Quốc hội tiếp tục thảo luận ở hội trường về: Đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021-2025: phát triển kinh tế - xã hội; cơ cấu lại nền kinh tế.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao về việc ban hành văn bản điều chỉnh nội dung thuộc thẩm quyền của Quốc hội để xử lý vấn đề phát sinh khi thực hiện sắp xếp tổ chức bộ máy nhà nước, đẩy mạnh phân cấp, phân quyền và tháo gỡ vướng mắc do quy định của pháp luật (theo quy định của Luật Tổ chức Chính phủ, Luật Tổ chức chính quyền địa phương, Nghị quyết số 190/2025/QH15 của Quốc hội quy định về xử lý một số vấn đề liên quan đến sắp xếp tổ chức bộ máy nhà nước, Nghị quyết số 206/2025/QH15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Tòa án nhân dân tối cao, Viện kiểm sát nhân dân tối cao về tình hình thi hành Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ 9 giờ 50, Quốc hội tiếp tục thảo luận ở hội trường về: Tình hình thực hiện ngân sách nhà nước năm 2025, dự toán ngân sách nhà nước, phương án phân bổ ngân sách trung ương năm 2026 (trong đó có Kế hoạch tài chính - ngân sách nhà nước 3 năm 2026 - 2028; tình hình thực hiện kế hoạch đầu tư công vốn ngân sách nhà nước năm 2025, dự kiến kế hoạch đầu tư công vốn ngân sách nhà nước năm 2026; tình hình thực hiện kế hoạch tài chính năm 2025, dự kiến kế hoạch tài chính năm 2026 của các quỹ tài chính nhà nước ngoài ngân sách do trung ương quản lý).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025 đầu tư công trung hạn; tài chính quốc gia và vay, trả nợ công; dự kiến các kế hoạch tài chính 5 năm quốc gia giai đoạn 2026 - 2030; đầu tư công trung hạn giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong phiên họp buổi chiều, Quốc hội tiếp tục thảo luận ở hội trường về: Tình hình thực hiện ngân sách nhà nước năm 2025, dự toán ngân sách nhà nước, phương án phân bổ ngân sách trung ương năm 2026 (trong đó có Kế hoạch tài chính - ngân sách nhà nước 3 năm 2026 - 2028; tình hình thực hiện kế hoạch đầu tư công vốn ngân sách nhà nước năm 2025, dự kiến kế hoạch đầu tư công vốn ngân sách nhà nước năm 2026; tình hình thực hiện kế hoạch tài chính năm 2025, dự kiến kế hoạch tài chính năm 2026 của các quỹ tài chính nhà nước ngoài ngân sách do trung ương quản lý).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025: đầu tư công trung hạn; tài chính quốc gia và vay, trả nợ công; dự kiến các kế hoạch tài chính 5 năm quốc gia giai đoạn 2026 - 2030; đầu tư công trung hạn giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-30-10-quoc-hoi-tiep-tuc-thao-luan-ve-ket-qua-va-ke-hoach-phat-trien-kinh-te-xa-hoi-29492101', '', 'BNP', 23, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.768794', 2, 11);
INSERT INTO `sync_articles` VALUES (98, '29504304', 'Đại biểu Quốc hội Nguyễn Thị Hà: Bạo lực học đường vẫn diễn biến phức tạp', 'Đại biểu Quốc hội Nguyễn Thị Hà: Bạo lực học đường vẫn diễn biến phức tạp', '/documents/37632/23566312/%C4%90B+Ha.jpg/9a44d826-ee1a-1391-75df-3dd0222a1ab8?t=1761809243428', '<p>(BNP) - Sáng 29/10, tham gia phiên thảo luận tại hội trường của kỳ họp thứ 10, Quốc hội khóa XV, đại biểu Nguyễn Thị Hà (Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) tham góp nhiều ý kiến xác đáng về phòng, chống bạo lực học đường.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C4%90B+Ha.jpg/9a44d826-ee1a-1391-75df-3dd0222a1ab8?t=1761809243428\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Hà thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Hà khẳng định: Bạo lực học đường vẫn diễn biến phức tạp, gây bức xúc và lo lắng cho toàn xã hội. Bạo lực học đường hiện nay không chỉ là câu chuyện của học sinh với học sinh, mà đã mở rộng, phức tạp hơn, nguy hiểm hơn khi giáo viên trở thành nạn nhân, phụ huynh và học sinh trở thành người gây bạo lực, và bạo lực còn diễn biến phức tạp trên không gian mạng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hệ lụy của bạo lực học đường là vô cùng nghiêm trọng và lâu dài. Về thể chất, nhiều học sinh bị thương tật, thậm chí tử vong. Về tinh thần, nhiều em mang sang chấn, rối loạn tâm lý, trầm cảm, tự cô lập. Những giáo viên bị bạo lực phải sống trong lo sợ, dễ tổn thương&nbsp;và mất dần niềm tin vào giá trị tôn sư trọng đạo. Những vụ việc bạo lực học đường không còn là hiện tượng đơn lẻ, không chỉ gây bàng hoàng dư luận mà còn đặt ra câu hỏi nhức nhối: Phải chăng kỷ cương học đường đang dần bị xem nhẹ? Áp lực lớn nhất của nhiều thầy cô hôm nay không phải là đồng lương, mà là nỗi sợ hãi trong chính môi trường làm việc của mình.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều đáng nói, xã hội có xu hướng đẩy mọi trách nhiệm về phía nhà trường, xem việc ngăn chặn bạo lực là trách nhiệm của giáo viên, mà quên rằng bạo lực học đường không sinh ra từ một phía. Nó là kết quả của sự tác động đan xen từ ba trụ cột: gia đình - nhà trường - xã hội. Gia đình là trường học đầu tiên của mỗi người, là nền tảng hình thành nhân cách, nhưng một số cha mẹ ngày nay lại thiếu thời gian, thiếu kỹ năng giáo dục cảm xúc, không kiểm soát được việc con xem những sách báo, phim ảnh, game có tính bạo lực cao; thậm chí có người thể hiện hành vi bạo lực trước mặt con. Một số trường còn nặng về thành tích, chưa chú trọng giáo dục đạo đức, kỹ năng sống; các biện pháp kỷ luật chưa thực sự có hiệu quả với tình huống “bắt nạt” xảy ra, còn có giáo viên thiếu kỹ năng quản lý cảm xúc và xử lý tình huống bạo lực. Chúng ta đang sống trong thời đại truyền thông mạng xã hội bùng nổ, nơi một hành vi bạo lực có thể được tán thưởng bằng lượt xem và lượt like; xã hội thiếu gắn kết, thờ ơ và đổ lỗi cho nhà trường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dẫn thông tin Bộ Giáo dục và Đào tạo vừa ban hành Thông tư số 19&nbsp;chính thức có hiệu lực&nbsp;ngày 31/10/2025, đại biểu Nguyễn Thị Hà cho rằng, Thông tư quy định hình thức kỷ luật cao nhất là viết bản kiểm điểm hoặc phê bình với tinh thần nhân văn, hướng đến giáo dục phục hồi thay vì trừng phạt là đáng trân trọng. Tuy nhiên, sự nhân văn trong kỷ luật học sinh chỉ phát huy hiệu quả khi được bảo đảm bằng hệ thống hỗ trợ và tư vấn tâm lý học đường chuyên nghiệp. Thông tư 19 đề cập đến hoạt động “khuyên bảo, theo dõi, tư vấn, phối hợp với gia đình”, nhưng hiện nay phần lớn trường học Việt Nam chưa có đội ngũ tư vấn tâm lý chuyên nghiệp. Nhiều nơi, “phòng tư vấn học đường” chỉ tồn tại trên danh nghĩa; giáo viên chủ nhiệm phải tự xoay xở trong khi chưa được đào tạo chuyên sâu kỹ năng xử lý xung đột.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ đó, đại biểu kiến nghị một số giải pháp: Cần quy định trách nhiệm liên đới với phụ huynh khi con em là học sinh vi phạm bạo lực nghiêm trọng; đưa giáo dục kỹ năng làm cha mẹ, giáo dục cảm xúc vào chương trình đào tạo cộng đồng, coi đây là nội dung bắt buộc trong các hoạt động dân cư, công đoàn, hội phụ nữ, đoàn thể; tăng cường tư vấn tâm lý học đường thực chất, mỗi cụm trường nên có tối thiểu 1 chuyên gia tâm lý được đào tạo bài bản; xây dựng cơ chế phản ứng nhanh trong trường học, kết nối với công an, chính quyền địa phương, cơ sở y tế khi xảy ra bạo lực; các nền tảng mạng xã hội cần có trách nhiệm pháp lý trong việc đưa thông tin nhằm kiểm soát nội dung bạo lực mạng và bạo lực học đường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cơ quan chức năng cần rà soát, đánh giá tính khả thi và hiệu quả khi triển khai Thông tư 19 nhằm cân bằng giữa nhân văn và kỷ luật, theo hướng bổ sung các hình thức kỷ luật mang tính phục hồi nhưng vẫn đủ sức răn đe, điều chỉnh hành vi, giúp học sinh nhận thức được lỗi sai và không tái phạm, như: Tổ chức hoạt động lao động cộng đồng, tham gia chương trình tư vấn bắt buộc, thực hiện cam kết hành vi tích cực, hoặc hình thức xin lỗi công khai dưới sự hướng dẫn của nhà trường; xây dựng bộ tiêu chí kiểm định năng lực tư vấn tâm lý học đường - cần coi đây là cơ sở để bảo đảm tính chuyên nghiệp và hiệu quả của công tác hỗ trợ học sinh trong nhà trường.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-nguyen-thi-ha-bao-luc-hoc-uong-van-dien-bien-phuc-tap-29504304', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 44, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.823723', 2, 11);
INSERT INTO `sync_articles` VALUES (99, '29337601', 'Đại biểu Đỗ Thị Việt Hà: Tháo gỡ những điểm nghẽn pháp lý, hoàn thiện hệ thống chính...', 'Đại biểu Đỗ Thị Việt Hà: Tháo gỡ những điểm nghẽn pháp lý, hoàn thiện hệ thống chính sách, pháp luật để vận hành tốt chính quyền địa phương 2 cấp', '/documents/37632/23566312/a2.jpg/deaa8be3-5f4c-c40b-c0a0-9187eb452075?t=1761727769142', '<p>(BNP) - Sáng 29/10, tham gia phiên thảo luận tại hội trường của kỳ họp thứ 10, Quốc hội khóa XV, đại biểu Đỗ Thị Việt Hà (Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) đóng góp nhiều ý kiến về công tác xây dựng thể chế, thi hành Hiến pháp, luật, nghị quyết của Quốc hội và xử lý vấn đề phát sinh khi sắp...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a2.jpg/deaa8be3-5f4c-c40b-c0a0-9187eb452075?t=1761727769142\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà thảo luận tại hội trường của Quốc hội, sáng&nbsp;29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà khẳng định: Thời gian qua, Chính phủ, Thủ tướng Chính phủ,&nbsp;sự chủ động, tích cực, trách nhiệm của Bộ Tư pháp trong việc tham mưu đã chỉ đạo quyết liệt, dành nhiều thời gian, nguồn lực cho công tác xây dựng, hoàn thiện thể chế, tổ chức thi hành pháp luật theo yêu cầu tại Nghị quyết số 66 - NQ/TW của Bộ Chính trị và những quy định mới của Luật Ban hành văn bản quy phạm pháp luật năm 2025; đã hoàn thành khối lượng công việc đặc biệt lớn liên quan đến công tác lập pháp, trong khoảng thời gian rất ngắn đã&nbsp;thể chế hóa kịp thời chủ trương, đường lối của Đảng, tạo hành lang pháp lý đồng bộ, kịp thời cho việc thực hiện chính quyền địa phương 2 cấp. Công tác hoàn thiện, tháo gỡ các rào cản, điểm nghẽn về thể chế, pháp luật được triển khai quyết liệt, góp phần khơi thông nguồn lực cho phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ đã bám sát yêu cầu của Luật Hoạt động giám sát của Quốc hội, đánh giá cụ thể những kết quả đạt được, thẳng thắn chỉ ra những tồn tại, hạn chế, nguyên nhân, xác định nhiệm vụ cụ thể đối với công tác xây dựng, thi hành pháp luật và đưa ra giải pháp để tiếp tục nâng cao chất lượng công tác triển khai thi hành luật, pháp lệnh, nghị quyết và ban hành văn bản quy định chi tiết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để góp phần phát huy những kết quả đạt được, khắc phục những tồn tại, hạn chế trong công tác xây dựng thể chế, thi hành Hiến pháp, luật, nghị quyết, tiếp tục giải quyết, xử lý tốt các vấn đề phát sinh khi thực hiện mô hình chính quyền địa phương 2 cấp, đại biểu Đỗ Thị Việt Hà đề xuất, kiến nghị với Chính phủ 3 nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước hết, tiếp tục tập trung, quyết liệt cho việc thực hiện có hiệu quả Nghị quyết số 66-NQ/TW, Nghị quyết số 197/2025/NQ-QH15 về cơ chế, chính sách đột phá trong công tác xây dựng, tổ chức thi hành pháp luật. Trong đó, đề nghị tập trung cho việc xây dựng, ban hành 3 văn bản gồm Quyết định của Thủ tướng Chính phủ hướng dẫn trách nhiệm, quy trình xin ý kiến các cơ quan có thẩm quyền của Đảng về nội dung văn bản quy phạm pháp luật; Nghị định quy định chi tiết, hướng dẫn thi hành Nghị quyết 197/2025/NQ-QH15 và Đề án soạn thảo văn bản quy phạm pháp luật tập trung, chuyên nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai, tiếp tục tăng cường phân cấp, phân quyền nhưng phải phù hợp với khả năng, bảo đảm được điều kiện, năng lực của các cơ quan, chủ thể được phân cấp, phân quyền. Đồng thời kịp thời ban hành văn bản hướng dẫn thực hiện các nội dung phân cấp, phân quyền.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vừa qua, khi thực hiện chính quyền địa phương 2 cấp, Chính phủ đã kịp thời ban hành 29 Nghị định về phân cấp, phân quyền từ Trung ương xuống cho địa phương; phân định thẩm quyền chuyển từ cấp cấp huyện lên cấp tỉnh, xuống cấp xã trên các lĩnh vực. Rà soát, thống kê sơ bộ thấy có khoảng 291 nội dung giao cho UBND cấp tỉnh, 206 nội dung giao Chủ tịch UBND cấp tỉnh, 95 nội dung giao cho các sở, ngành; riêng với cấp xã, có đến 204 nội dung giao cho UBND cấp xã và 103 nội dung giao cho Chủ tịch UBND cấp xã.&nbsp;Cùng với đó, có 63 nhiệm vụ được chính quyền cấp tỉnh phân cấp cho chính quyền cấp xã. Riêng về thủ tục hành chính, có 556 thủ tục hành chính được phân cấp, phân quyền từ trung ương xuống cho địa phương, chuyển từ cấp huyện lên cấp tỉnh là 18 thủ tục hành chính và số lượng thủ tục hành chính chuyển về cấp xã lên tới 278. Như vậy&nbsp;khối lượng nhiệm vụ được phân cấp, phân quyền cho cấp xã và thủ tục hành chính được chuyển về cấp xã là rất lớn. Thời gian qua đã xảy ra tình trạng quá tải trong công việc, chất lượng, hiệu quả còn thấp của chính quyền cấp xã do nhiều nguyên nhân, trong đó có nguyên nhân về khả năng thực hiện, về nguồn nhân lực, điều kiện cơ sở vật chất, trang thiết bị, phương tiện làm việc, tài chính chưa được bảo đảm, chưa đáp ứng yêu cầu nhiệm vụ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, một số quy định được phân cấp, phân quyền chưa rõ ràng, chưa được hướng dẫn, còn nhiều cách hiểu khác nhau, gây khó khăn trong áp dụng, rất cần có văn bản hướng dẫn thực hiện. Còn có những quy định về thủ tục hành chính rườm rà, phức tạp và chồng chéo; các địa phương vẫn còn gặp một số khó khăn, bất cập trong triển khai thủ tục hành chính cho người dân, doanh nghiệp, các khó khăn chủ yếu liên quan đến hạ tầng kỹ thuật như hệ thống phần mềm, dịch vụ công, kết nối dữ liệu, chữ ký số, con dấu điện tử và quy trình vận hành chưa ổn định, thông suốt, cơ sở dữ liệu chưa đồng bộ, liên thông; hạ tầng công nghệ chưa ổn định, thông suốt...</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Do đó, đề nghị Chính phủ rà soát, đánh giá kỹ lưỡng toàn diện tình hình thi hành 29 Nghị định về phân cấp, phân quyền, phân định thẩm quyền đã ban hành, trong đó có các quy định về thủ tục hành chính; đồng thời khi phân cấp, phân quyền cần đánh giá kỹ lưỡng về khả năng, điều kiện thực hiện phân cấp, phân quyền cũng như có cơ chế kiểm tra, giám sát để kịp thời có giải pháp phù hợp bảo đảm việc phân cấp, phân quyền hiệu quả.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ ba, tiếp tục thực hiện có hiệu quả công tác rà soát văn bản quy phạm pháp luật và xử lý, khắc phục các nội dung mâu thuẫn, chồng chéo, vướng mắc, bất cập phát hiện qua rà soát và đặc biệt cần tiếp tục thực hiện tốt Nghị quyết số 206/2025/NQ15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật. Trong đó đề nghị Chính phủ quan tâm 2 nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác rà soát văn bản quy phạm pháp luật có khối lượng cần thực hiện rất lớn, là một trong những nhiệm vụ được Quốc hội, Chính phủ, đặc biệt là Bộ Tư pháp cùng các bộ, ngành, các địa phương đặc biệt quan tâm, chú trọng, triển khai nhiều hoạt động rà soát; đã nghiêm túc, tích cực áp dụng nhiều giải pháp mới để kịp thời phát hiện và xử lý, khắc phục các nội dung mâu thuẫn, chồng chéo, vướng mắc, góp phần tháo gỡ những điểm nghẽn pháp lý, sơ hở, bất cập trong cơ chế, chính sách, pháp luật.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với 2.092 kiến nghị, phản ánh về các khó khăn, vướng mắc của 789 văn bản quy phạm pháp luật, các cơ quan đã xác định chỉ có 834 kiến nghị, phản ánh có cơ sở và một số cơ quan đã có văn bản gửi về địa phương trao đổi, hướng dẫn; khi địa phương nhận được văn bản hướng dẫn, trao đổi của bộ, ngành thì đều gửi đến tất cả các cơ quan, địa phương để biết và thực hiện. Hiện còn số lượng lớn là 1.237 kiến nghị, phản ánh xác định không nhất trí và còn 21 kiến nghị, phản ánh chưa có sự thống nhất giữa các cơ quan. Với các kiến nghị, phản ánh này, địa phương rất cần có văn bản của bộ, ngành để biết và thống nhất trong quá trình tổ chức thi hành. Do đó, đề nghị Chính phủ chỉ đạo các bộ, ngành có văn bản gửi các địa phương đối với cả các kiến nghị, phản ánh không nhất trí.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Căn cứ Nghị quyết số 206/2025/QH15 của Quốc hội khóa XV, vừa qua Chính phủ đã ban hành chùm các Nghị quyết từ 66.1 đến 66.5 quy định xử lý khó khăn, vướng mắc, cơ chế, chính sách đặc thù về pháp luật trong một số lĩnh vực như quy hoạch, địa chất khoáng sản, ngân sách... Đây là những văn bản&nbsp; cơ sở pháp lý rất quan trọng để tháo gỡ những khó khăn, vướng mắc của quy định hiện hành. Tuy nhiên, việc quy định những cơ chế, chính sách đặc thù đang khác với quy định hiện hành như các Nghị quyết này cũng rất cần có văn bản hướng dẫn thực hiện của Chính phủ, bộ, ngành có liên quan. Đề nghị Chính phủ giao các bộ, ngành có liên quan kịp thời tham mưu ban hành hoặc ban hành văn bản theo thẩm quyền để hướng dẫn việc thực hiện các Nghị quyết trên thực tế được bảo đảm kịp thời, thống nhất, đồng bộ, khả thi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà khẳng định, việc ban hành Nghị quyết của Chính phủ theo Nghị quyết số 206 của Quốc hội khóa XV chỉ là giải pháp đặc biệt tạm thời để xử lý khó khăn, vướng mắc trong quy định của pháp luật; việc quy định các nội dung khác với quy định hiện hành cũng cần được hạn chế tối đa để bảo đảm tính đồng bộ, thống nhất của hệ thống pháp luật. Do đó, đề nghị Chính phủ tăng cường hơn nữa chất lượng các dự thảo luật, pháp lệnh, nghị quyết khi trình Quốc hội, Ủy ban Thường vụ Quốc hội để tránh tình trạng mâu thuẫn, chồng chéo, bảo đảm tính hợp hiến, hợp pháp, thống nhất, khả thi ngay khi ban hành luật, pháp lệnh, nghị quyết.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-o-thi-viet-ha-thao-go-nhung-iem-nghen-phap-ly-hoan-thien-he-thong-chinh-sach-phap-luat-e-van-hanh-tot-chinh-quyen-ia-phuong-2-cap-29337601', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 378, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.874899', 2, 11);
INSERT INTO `sync_articles` VALUES (100, '29335337', 'Đại biểu Quốc hội Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực...', 'Đại biểu Quốc hội Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực doanh nghiệp tư nhân', '/documents/37632/23566312/ongSo.jpg/9daa3894-af62-9155-b0ad-c85bbe7c26a8?t=1761726957505', '<p>(BNP) - Sáng 29/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường, cho ý kiến vào Báo cáo của Chính phủ về tình hình triển khai Nghị quyết số 16 của Quốc hội về Kế hoạch phát triển kinh tế - xã hội 5 năm 2021 - 2025.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/ongSo.jpg/9daa3894-af62-9155-b0ad-c85bbe7c26a8?t=1761726957505\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Như So thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham gia thảo luận, đại biểu Nguyễn Như So (Đoàn&nbsp;Bắc Ninh) khẳng định: Trong bối cảnh kinh tế toàn cầu biến động bởi xung đột, thuế quan và khí hậu, Việt Nam vẫn vươn lên như “hải đăng kinh tế” của khu vực: GDP quý III tăng 8,23%, xuất siêu đạt 16,82 tỷ USD, thu hút FDI đạt con số kỷ lục với 28,54 tỷ USD - minh chứng cho niềm tin quốc tế vào sức bật Việt Nam. Song để biến thành tựu ngắn hạn thành năng lực bền vững, chúng ta cần một chiến lược phát triển lấy kinh tế tư nhân làm “động cơ phản lực”. Khu vực này là mũi nhọn sáng tạo, là lực đẩy năng suất và nền tảng tự chủ quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực doanh nghiệp tư nhân, đưa Việt Nam tiến vững chắc trên con đường tăng trưởng xanh, độc lập và thịnh vượng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Một là</strong></em>, cần đột phá thực chất trong cải cách thể chế, với trọng tâm là khâu thực thi chính sách - nút thắt của mọi nút thắt trong phát triển kinh tế hiện nay. Chúng ta không thiếu chính sách, mà thiếu cách thực thi hiệu quả. Nhiều chủ trương, nghị quyết đúng đắn của Đảng và Quốc hội như “bộ tứ” Nghị quyết 57, 59, 66, 68 của Bộ Chính trị hay Nghị quyết 198 đã mở hướng khơi thông nguồn lực, song kết quả thực tế lại cho thấy khoảng cách lớn giữa “chính sách trên giấy” và “đời sống doanh nghiệp”. Chỉ trong 9 tháng&nbsp;năm 2025, hơn 175 nghìn doanh nghiệp rút lui khỏi thị trường - con số phản ánh rõ độ vênh giữa ý chí chính sách và hiệu quả thực thi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đại biểu, vấn đề không nằm ở thiết kế chính sách, mà ở nút thắt thực thi. Một chính sách tốt, nếu thiếu đồng bộ, cơ chế phối hợp, hướng dẫn cụ thể, trách nhiệm cá nhân sẽ nằm lại trên bàn giấy. Gói hỗ trợ lãi suất 2% của Nghị quyết 43 là ví dụ điển hình. Mặc dù được thiết kế đúng mục tiêu&nbsp;nhưng giải ngân chỉ đạt 1,95% vì quy trình phức tạp, tiêu chí mập mờ, ngân hàng sợ rủi ro… Hệ quả là vốn không đến được nền kinh tế thực, doanh nghiệp kiệt sức, còn chính sách bị coi là “không hiệu quả”.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, đột phá thể chế phải bắt đầu từ cải cách thực thi. Mỗi chính sách ban hành cần có hướng dẫn chi tiết, thời hạn rõ ràng, tiêu chí định lượng, cơ chế giám sát công khai và người chịu trách nhiệm cụ thể. Cần số hóa toàn bộ quy trình hành chính và xóa bỏ triệt để cơ chế xin - cho. Quan trọng hơn, cần đo hiệu quả cải cách bằng trải nghiệm của doanh nghiệp, không chỉ bằng báo cáo hành chính.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chỉ khi thực thi trở thành khâu đột phá, chuyển từ “quản lý” sang “phục vụ”, từ “đúng quy trình” sang “đúng kết quả”, thể chế mới thật sự trở thành động lực tăng trưởng và củng cố niềm tin của doanh nghiệp vào chính quyền kiến tạo.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Hai là</strong></em>, cần tái cơ cấu mạnh mẽ thị trường vốn, đưa dòng tiền trở lại nền kinh tế thực, thay vì cuốn vào những chu kỳ đầu cơ ngắn hạn không tạo ra giá trị bền vững. Thị trường vốn phải trở thành mạch máu của sản xuất, không phải sân chơi của đầu cơ. Dòng vốn cần được định hướng chiến lược vào các lĩnh vực sản xuất, chế biến chế tạo, hàng tiêu dùng thiết yếu, công nghệ cao và kinh tế xanh - những trụ cột tạo giá trị gia tăng và việc làm ổn định cho đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ cần phát triển các kênh dẫn vốn dài hạn như quỹ đầu tư, trái phiếu doanh nghiệp, thị trường vốn mạo hiểm - nơi các quỹ đầu tư chấp nhận rủi ro để tài trợ cho đổi mới công nghệ, khởi nghiệp sáng tạo và sản xuất giá trị cao, giảm phụ thuộc vào tín dụng ngắn hạn của ngân hàng. Đồng thời, nên thiết lập cơ chế tái cấp vốn ưu đãi 2 - 5%/năm cho các dự án đổi mới công nghệ, sản xuất xanh và chuyển đổi số - qua đó giúp doanh nghiệp dễ dàng tiếp cận vốn rẻ, đầu tư cho năng suất và giá trị dài hạn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song song, cần thiết kế gói kích cầu thuế “Sản xuất xanh”, ưu tiên miễn, giảm thuế cho doanh nghiệp đầu tư vào công nghệ 4.0, năng lượng tái tạo, kinh tế tuần hoàn. Đây không chỉ là chính sách hỗ trợ tài chính, mà còn là đòn bẩy chuyển hướng dòng vốn từ đầu cơ sang sáng tạo, gắn lợi ích doanh nghiệp với tăng trưởng bền vững và trách nhiệm môi trường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một thị trường vốn phát triển theo hướng sản xuất - sáng tạo - dài hạn, sẽ tạo nền tảng nội lực vững chắc, nâng cao năng suất quốc gia và củng cố sức chống chịu chiến lược của nền kinh tế Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Ba là</strong></em>, cần tái cấu trúc mạnh mẽ sản xuất và xuất khẩu theo hướng nâng cao giá trị gia tăng nội địa, coi đây là nhiệm vụ chiến lược để xây dựng nền kinh tế độc lập, tự chủ. Trong bối cảnh chủ nghĩa bảo hộ lan rộng và thương mại toàn cầu thu hẹp, Việt Nam không thể tiếp tục dựa vào mở rộng quy mô xuất khẩu, mà phải chuyển trọng tâm sang tăng hàm lượng giá trị trong nước. Hiện tỷ lệ nội địa hóa mới đạt 36,6%, thấp hơn đáng kể so với Trung Quốc (67,1%), Thái Lan (58,4%) hay Ấn Độ (53,3%), khiến Việt Nam dễ bị lệ thuộc, hoặc rơi vào vai trò “công xưởng trung chuyển”, khó đáp ứng tiêu chí FTA, đối mặt nguy cơ bị áp thuế cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, cần ưu tiên hình thành lực lượng doanh nghiệp nội địa đủ quy mô và năng lực làm trụ cột cho nền kinh tế. Chính sách hỗ trợ phải tập trung vào tăng tỷ lệ nội địa hoá nguyên liệu, sản phẩm; thúc đẩy chuyển giao công nghệ, đào tạo nhân lực và phát triển năng lực thiết kế, chế tạo trong nước. Trong thu hút FDI, cần quy định rõ cam kết nội địa hóa, chuyển giao công nghệ và liên kết với doanh nghiệp Việt Nam. FDI phải là chất xúc tác cho năng lực sản xuất trong nước, nâng tầm giá trị “Make in Vietnam”, giúp doanh nghiệp Việt vươn lên làm chủ các khâu có giá trị cao trong chuỗi cung ứng toàn cầu - nền tảng cho một nền kinh tế tự chủ và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Bốn là</strong></em>, phát triển nguồn nhân lực chất lượng cao như “lõi thép” của tăng trưởng, coi trí tuệ Việt Nam là lợi thế cạnh tranh cốt lõi trong kỷ nguyên công nghệ và chuyển đổi số.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam đang đối mặt với điểm nghẽn nghiêm trọng: 63% lao động làm việc phi chính thức, 38 triệu người chưa qua đào tạo nghề, và chỉ 11,67% có trình độ cao - khiến năng suất lao động chỉ bằng 1/10 Singapore, 1/2 Trung Quốc. Đây không chỉ là thiếu hụt kỹ năng mà còn là “độ trễ thể chế” trong giáo dục -&nbsp;đào tạo. Để bứt phá, cần triển khai thực chất Nghị quyết 71-NQ/TW, lấy giáo dục và đào tạo làm khâu đột phá chiến lược.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ cần đầu tư có trọng tâm cho “Giáo dục tinh hoa”, xây dựng các trung tâm nghiên cứu -&nbsp;đào tạo xuất sắc trong các lĩnh vực mũi nhọn như AI, bán dẫn, năng lượng tái tạo và kinh tế số. Đồng thời, khuyến khích khu vực tư nhân tham gia sâu vào đào tạo thông qua cơ chế đặt hàng nhân lực, liên kết chặt chẽ Doanh nghiệp - Trường học - Viện nghiên cứu và ưu đãi thuế mạnh cho hoạt động R&amp;D và phát triển kỹ năng. Khi nguồn nhân lực trở thành nền tảng tri thức tự chủ, Việt Nam mới có thể vượt qua “bẫy thu nhập trung bình” và tạo vị thế vững vàng trong chuỗi giá trị toàn cầu.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-nguyen-nhu-so-e-xuat-4-giai-phap-trong-tam-nham-khoi-day-tiem-luc-doanh-nghiep-tu-nhan-29335337', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 678, 'Chính trị', 2, '', '38762', '{}', '2025-11-01 07:12:47.930869', 2, 11);
INSERT INTO `sync_articles` VALUES (101, '29467701', 'Hội thảo “Hợp lực Nhà nước – Doanh nghiệp – Hiệp hội xây dựng chiến lược phát triển...', 'Hội thảo “Hợp lực Nhà nước – Doanh nghiệp – Hiệp hội xây dựng chiến lược phát triển công nghiệp gắn với ứng dụng khoa học công nghệ cao”', '/documents/37632/23288501/z7177267612269_4ab5aaf011f7fd704daf8f263069f57e+%281%29.jpg/3f805ad5-b835-c22b-0404-bb7f153ef318?t=1761973325323', '<p>(BNP) – Sáng 01/11, tại Công ty Cổ phần chế tạo thiết bị tự động, khuôn và tools Automech (Khu công nghiệp Đình Trám, phường Việt Yên, tỉnh Bắc Ninh), Sở Công Thương tổ chức Hội thảo “Hợp lực Nhà nước – Doanh nghiệp – Hiệp hội xây dựng chiến lược phát triển công nghiệp gắn với ứng dụng khoa học...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7177267587143_23c1cf04a6e84bbc64f96d81cdd685ef.jpg/ef8d8d05-b4ab-8578-6921-463a1ade46ca?t=1761966940707\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Tham dự hội thảo có đồng chí Phạm Văn Thịnh, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn Đại biểu Quốc hội tỉnh;&nbsp;<span lang=\"VI\">TS. Võ Trí Thành, Nguyên Phó Viện trưởng Viện Nghiên cứu và Quản lý Kinh tế Trung ương; đại diện lãnh đạo Văn phòng UBND tỉnh, các sở, ban, ngành liên quan <span lang=\"VI\">cùng đông đảo doanh nghiệp, Hiệp hội&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">sản xuất công nghiệp tỉnh</span></span></span>.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Hội thảo được tổ chức nhằm cụ thể hóa các nội dung triển khai Nghị quyết số 57-NQ/TW của Bộ Chính trị về phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia; Nghị quyết số 68-NQ/TW về phát triển kinh tế tư nhân; Kế hoạch số 11-KH/TU của Ban Thường vụ Tỉnh ủy Bắc Ninh về phát triển kinh tế tư nhân trở thành động lực quan trọng của nền kinh tế.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Thông qua Hội thảo, Sở Công Thương mong muốn tạo diễn đàn trao đổi giữa Nhà nước – Doanh nghiệp – Hiệp hội về tình hình ứng dụng khoa học công nghệ, chuyển đổi số trong sản xuất công nghiệp; lắng nghe ý kiến, đề xuất của các doanh nhân và chuyên gia để hình thành các cơ chế, chính sách khuyến khích doanh nghiệp đổi mới công nghệ, phát triển công nghiệp hỗ trợ theo hướng xanh và bền vững.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7177267612269_4ab5aaf011f7fd704daf8f263069f57e+%281%29.jpg/3f805ad5-b835-c22b-0404-bb7f153ef318?t=1761973325323\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu tham gia toạ đàm.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Tại Hội thảo, các đại biểu tham gia tọa đàm thảo luận mở:</span>&nbsp;<span style=\"line-height:1.3;\">“Hợp lực Nhà nước – Doanh nghiệp – Hiệp hội: Giải pháp phát triển bền vững cho doanh nghiệp công nghiệp hỗ trợ đón vận hội mới”.&nbsp;Các đại biểu&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">tập trun</span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">g đánh giá thực trạng năng lực sản xuất, công nghệ, nhân lực và khả năng tham gia chuỗi cung ứng của doanh nghiệp công nghiệp hỗ trợ Bắc Ninh; Nhận diện cơ hội và thách thức trong bối cảnh mới; chia sẻ các kinh nghiệm thành công về đổi mới công nghệ và đề xuất các nội dung cụ thể về tài chính, đất đai, đào tạo nhân lực và kết nối giữa FDI - doanh nghiệp nội địa.</span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7177267586934_bfefc4187fc0c226d40648ecc9bc38f5+%281%29.jpg/d22b0f98-91d6-6839-75db-e570221ce8fd?t=1761971591973\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh phát biểu tại hội thảo.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 18px;\">Phát biểu tại hội thảo, Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh cho biết, t</span><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 18px;\">rong bối cảnh mới, Bắc Ninh đang triển khai quyết liệt các mục tiêu: Xây dựng tỉnh công nghiệp theo hướng công nghệ cao, trung tâm sản xuất điện tử - công nghệ thông tin hàng đầu khu vực châu Á; phát triển công nghiệp xanh, bền vững, gắn với nâng cao chất lượng nguồn nhân lực, chuyển đổi số, đổi mới sáng tạo.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:black\">Đồng chí nhấn mạnh, việc trao đổi với doanh nghiệp, các chuyên gia về lĩnh vực công nghiệp, <span style=\"line-height:1.3;\"><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 18px;\">chuyển đổi số</span></span> về tình hình ứng dụng khoa học công nghệ, lắng nghe ý kiến của doanh nhân, cộng đồng doanh nghiệp và các chuyên gia để hình thành các cơ chế, chính sách và giải pháp khuyến khích áp dụng khoa học công nghệ, <span style=\"line-height:1.3;\"><span style=\"font-family: Arial, Helvetica, sans-serif; font-size: 18px;\">chuyển đổi số</span></span> trong sản xuất, phát triển công nghiệp, công nghiệp hỗ trợ, tạo động lực phát triển kinh tế tư nhân thành động lực phát triển kinh tế - xã hội là nội dung quan trọng để từ đó có các chính sách, cơ chế phù hợp với đặc thù của tỉnh, kịp thời hỗ trợ cho doanh nghiệp.</span></span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên cơ sở các ý kiến tại hội thảo, đồng chí giao Sở Công Thương chủ trì phối hợp với Sở Khoa học và Công nghệ, Ban quản lý các Khu công nghiệp tỉnh và các sở, ngành nghiên cứu, tham mưu đề xuất HĐND tỉnh ban hành cơ chế đặc thù của tỉnh về việc hỗ trợ cho các doanh nghiệp sản xuất công nghiệp ứng dụng khoa học công nghệ cao quy mô lớn (báo cáo Chủ tịch UBND tỉnh trong tháng 12/2025). </span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước mắt, nghiên cứu cơ chế triển khai ứng dụng thí điểm các sản phẩm có hàm lượng khoa học công nghệ cao do các doanh nghiệp công nghiệp của tỉnh đã làm chủ công nghệ sản xuất, để từ đó, đánh giá, rút kinh nghiệm để xem xét nhân rộng trên địa bàn toàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7177660581822_b341f0211cf68172a500e4592622b367.jpg/6aa79242-473b-fe6c-251d-744ac6ccad98?t=1761973584168\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh và các đại biểu chúc mừng ký kết Biên bản ghi nhớ (MOU).</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-top:8px; margin-bottom:16px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khuôn khổ hội thảo, Sở Công Thương và Hiệp hội sản xuất công nghiệp tỉnh ký Biên bản ghi nhớ (MOU) về hợp tác phát triển công nghiệp hỗ trợ, mở ra cơ chế phối hợp thường xuyên giữa Nhà nước – Doanh nghiệp – Hiệp hội trong triển khai chính sách, xúc tiến thương mại, hỗ trợ nghiên cứu và phát triển, đào tạo nhân lực và chuyển đổi số.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 16px; text-align: center;\"><img src=\"/documents/37632/23288501/z7177714617529_c777290f75499f313c8db052976d6e09.jpg/14abab63-b3a3-6c0b-fef7-749cb77a5571?t=1761974673772\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 16px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh và các đại biểu tham quan dây chuyền sản xuất của Công ty Automech.</span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:115%\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hoi-thao-hop-luc-nha-nuoc-doanh-nghiep-hiep-hoi-xay-dung-chien-luoc-phat-trien-cong-nghiep-gan-voi-ung-dung-khoa-hoc-cong-nghe-cao-29467701', '', 'Diệu Hoa', 31, 'Kinh tế', 3, 'true', '38762', '{}', '2025-11-01 07:12:48.344405', 3, 11);
INSERT INTO `sync_articles` VALUES (102, '30166928', 'Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh tiếp và làm việc với Đoàn doanh nghiệp tỉnh Sơn...', 'Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh tiếp và làm việc với Đoàn doanh nghiệp tỉnh Sơn Đông (Trung Quốc)', '/documents/37632/23288501/31-10-2.png/e52e8c1c-4266-dcb2-07bd-879b94870900?t=1761954675816', '<p>(BNP) – Chiều tối ngày 31/10, đồng chí Phạm Văn Thịnh, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn đại biểu Quốc hội tỉnh đồng chủ trì cùng đồng chí Lê Thu Hà, Phó Chủ nhiệm Văn phòng Quốc hội tiếp và làm việc với Đoàn doanh nghiệp tỉnh Sơn Đông (Trung Quốc) đến thăm, tìm...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/23288501/31-10-2.png/e52e8c1c-4266-dcb2-07bd-879b94870900?t=1761954675816\" style=\"height: 537px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"color:#0000ff;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh chụp ảnh lưu niệm cùng Đoàn doanh nghiệp tỉnh Sơn Đông.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại buổi tiếp, Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh bày tỏ vui mừng được tiếp đón Đoàn doanh nghiệp tỉnh Sơn Đông đến tìm hiểu cơ hội đầu tư tại tỉnh, đồng thời, khẳng định tỉnh Bắc Ninh luôn hoan nghênh và tạo điều kiện thuận lợi nhất cho nhà đầu tư nước ngoài đến tìm hiểu, hợp tác và phát triển.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Khái quát về các tiềm năng, thế mạnh của tỉnh Bắc Ninh cũng như các cơ chế ưu việt, thông thoáng, thuận lợi, nhanh chóng nhất cho doanh nghiệp khi đầu tư vào tỉnh, Phó Chủ tịch UBND tỉnh mong muốn các doanh nghiệp tỉnh Sơn Đông quan tâm, nhanh chóng thực hiện các thủ tục có liên quan theo quy định của pháp luật Việt Nam để đầu tư vào các lĩnh vực như: logistics, hàng không, thương mại dịch vụ, y tế, giáo dục...</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/23288501/31-10-3.png/7600271f-a72e-5e88-8a58-65735289e045?t=1761957571844\" style=\"height: 545px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"color:#0000ff;\">Toàn cảnh buổi tiếp.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại buổi tiếp, đại diện Đoàn doanh nghiệp tỉnh Sơn Đông, Trung Quốc <span lang=\"VI\">trân trọng cảm ơn sự quan tâm, tiếp đón của lãnh đạo tỉnh</span>. Đồng thời, bày tỏ ấn tượng trước sự phát triển nhanh chóng và sức hấp dẫn rất cao của tỉnh Bắc Ninh đối với cộng đồng doanh nghiệp tỉnh Sơn Đông. Trong thời gian tới, các doanh nghiệp mong muốn sẽ được tỉnh tạo điều kiện để tổ chức thăm quan thực tế, làm việc với một số chủ đầu tư hạ tầng Khu công nghiệp và thực hiện các trình tự thủ tục đầu tư. Đồng thời, tích cực kêu gọi các doanh nghiệp Trung Quốc đến đầu tư tại tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-pham-van-thinh-tiep-va-lam-viec-voi-oan-doanh-nghiep-tinh-son-ong-trung-quoc-30166928', '', 'P.V', 61, 'Kinh tế', 3, 'true', '38762', '{}', '2025-11-01 07:12:48.387108', 3, 11);
INSERT INTO `sync_articles` VALUES (103, '30024213', 'Thúc đẩy phát triển nguồn điện mặt trời mái nhà tự sản xuất, tự tiêu thụ trên địa bàn...', 'Thúc đẩy phát triển nguồn điện mặt trời mái nhà tự sản xuất, tự tiêu thụ trên địa bàn tỉnh', '/documents/37632/23288501/31-2.png/898f6ec0-69e6-21ae-e25c-6ae4c036d1ee?t=1761900811332', '<p>(BNP) - Chiều 31/10, UBND tỉnh Bắc Ninh tổ chức hội thảo phát triển nguồn điện mặt trời mái nhà tự sản xuất, tự tiêu thụ trên địa bàn tỉnh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288501/31-2.png/898f6ec0-69e6-21ae-e25c-6ae4c036d1ee?t=1761900811332\" style=\"height: 594px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh (hàng đầu, thứ 5 bên phải) cùng lãnh đạo Cục Điện lực, Sở Công Thương chụp ảnh lưu niệm với các doanh nghiệp tham gia hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham dự hội thảo có các đồng chí: Phạm Văn Thịnh, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn Đại biểu Quốc hội tỉnh; lãnh đạo Cục Điện lực (Bộ Công Thương); lãnh đạo một số sở, ban, ngành, địa phương trong tỉnh; đại diện ngân hàng, tổ chức tín dụng; đơn vị điện lực; doanh nghiệp cung ứng thiết bị, dịch vụ kỹ thuật và các doanh nghiệp sử dụng điện lớn trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288501/31-4.png/c7bf270a-b9b2-d416-daad-f5e3acb53e44?t=1761900989427\" style=\"height: 614px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giám đốc Sở Công Thương Nguyễn Minh Hiếu phát biểu khai mạc hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phát biểu khai mạc hội thảo, Giám đốc Sở Công Thương Nguyễn Minh Hiếu nhấn mạnh phát triển năng lượng tái tạo, trong đó có điện mặt trời mái nhà là xu thế tất yếu, phù hợp với định hướng Quốc gia về chuyển dịch năng lượng và cam kết NetZero vào năm 2050. Đối với một tỉnh công nghiệp có tốc độ phát triển nhanh như Bắc Ninh, việc đảm bảo an ninh năng lượng, giảm phát thải khí nhà kính và tối ưu hóa chi phí sản xuất cho doanh nghiệp là nhiệm vụ vô cùng quan trọng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tháng 8/2025, UBND tỉnh đã có Thư ngỏ kêu gọi chung tay phát triển điện mặt trời mái nhà. Trong đó khẳng định, Bắc Ninh có tiềm năng rất lớn với khoảng 6.800ha mái nhà xưởng và mục tiêu là phát triển 3.392 MW công suất. Mô hình \"tự sản xuất, tự tiêu thụ\" mở ra giải pháp đột phá, giúp doanh nghiệp chủ động nguồn cung, giảm tải cho lưới điện Quốc gia và thể hiện trách nhiệm xã hội về bảo vệ môi trường.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tuy nhiên, trong quá trình triển khai, vẫn còn một số vướng mắc về cơ chế chính sách, tiêu chuẩn kỹ thuật, phòng cháy chữa cháy và tiếp cận nguồn vốn… Vì vậy, mong muốn các đại biểu, nhất là các doanh nghiệp tham gia tích cực trao đổi, chia sẻ kinh nghiệm, góp phần vào thành công của hội thảo. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288501/31-7.png/dca317b3-5b32-0231-b978-b33f019ad56f?t=1761901180593\" style=\"height: 658px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại diện Công ty TNHH FuHong Precision Component chia sẻ tại hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại hội thảo, các đại biểu được nghe đại diện Cục Điện lực (Bộ Công Thương) triển khai, hướng dẫn các văn bản quy phạm pháp luật và cơ chế, chính sách liên quan đến điện mặt trời mái nhà. Đồng thời, trao đổi, thảo luận và giải đáp các khó khă, vướng mắc trong quá trình triển khai thực tế. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, các doanh nghiệp, ngân hàng, tổ chức tín dụng cũng giới thiệu giải pháp, công nghệ và mô hình kỹ thuật thiết kế, lắp đặt điện mặt trời mái nhà; tấm pin năng lượng mặt trời; giải pháp tín dụng đầu tư phát triển điện mặt trời mái nhà tự sản xuất, tự tiêu thụ; chia sẻ kinh nghiệm thực tiễn trong lắp đặt, vận hành hệ thống…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288501/31-6.png/fbb27382-3eab-6116-46cc-f1a5e36075e3?t=1761901089314\" style=\"height: 662px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"> </span></span></span><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh phát biểu tại hội thảo.</span></span></span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phát biểu tại hội thảo, nhấn mạnh xu hướng phát triển điện mặt trời mái nhà hiện nay, Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh cho biết tốc độ phát triển kinh tế nhanh dẫn đến nhu cầu điện của Bắc Ninh tăng rất mạnh. Cụ thể, trong giai đoạn 2021 - 2025, tăng trưởng điện bình quân khoảng 13,5%/năm, sản lượng điện thương phẩm đạt 72,7 tỷ kWh; dự báo 2026 - 2030 tiếp tục tăng khoảng 12,2%/năm, sản lượng ước 129,7 tỷ kWh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Định hướng phát triển điện mặt trời mái nhà tự sản xuất, tự tiêu thụ trên địa bàn tỉnh thời gian tới, Phó Chủ tịch UBND tỉnh yêu cầu Sở Công Thương với vai trò là cơ quan đầu mối thường trực, chủ trì, phối hợp chặt chẽ với các sở, ngành liên quan chủ động hướng dẫn, tháo gỡ kịp thời mọi vướng mắc, rút ngắn thời gian giải quyết thủ tục hành chính trong triển khai điện mặt trời mái nhà. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288501/31-5.png/8b8c77f5-36a4-8c7a-7aef-a0388b956739?t=1761901127500\" style=\"height: 609px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, khẩn trương xây dựng kế hoạch phát triển điện mặt trời mái nhà trên địa bàn tỉnh; trong đó giao chỉ tiêu cụ thể cho từng doanh nghiệp, nhất là các doanh nghiệp sử dụng điện lớn trên địa bàn; yêu cầu đăng kí sử dụng điện mặt trời áp mái tự sản xuất, tự tiêu thụ, đưa vào tiêu chí đánh giá hàng năm. Qua đó, góp phần hoàn thành mục tiêu phát triển 3.392 MW điện mặt trời mái nhà vào năm 2026, đóng góp quan trọng vào đảm bảo an ninh năng lượng, thúc đẩy sự nghiệp công nghiệp hóa, hiện đại hóa xanh và bền vững của tỉnh. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/31-3.png/67d9ab59-db00-6431-f444-a13496d449fc?t=1761901291475\" style=\"height: 653px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh cùng các đại biểu tham quan gian trưng bày về sản phẩm năng lượng mặt trời tại hội thảo.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh cũng kêu gọi cộng đồng doanh nghiệp trên địa bàn tỉnh mạnh dạn tiên phong đầu tư vào điện mặt trời mái nhà, xem đây là một chiến lược then chốt để nâng cao năng lực cạnh tranh \"xanh\", giảm chi phí vận hành và đáp ứng các tiêu chuẩn xuất khẩu khắt khe. Tỉnh Bắc Ninh cam kết tạo mọi điều kiện thuận lợi, minh bạch và nhanh chóng nhất cho các dự án điện mặt trời mái nhà; đồng thời, duy trì cơ chế lắng nghe, đối thoại thường xuyên và tháo gỡ đến cùng mọi rào cản./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thuc-ay-phat-trien-nguon-ien-mat-troi-mai-nha-tu-san-xuat-tu-tieu-thu-tren-ia-ban-tinh-30024213', '', 'Linh Ngọc', 364, 'Kinh tế', 3, 'true', '38762', '{}', '2025-11-01 07:12:48.453826', 3, 11);
INSERT INTO `sync_articles` VALUES (104, '29900401', 'Bắc Ninh: Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông', 'Bắc Ninh: Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông', '/documents/37632/23288501/IMG_0515.jpg/b32ecd82-b595-cc4c-3b39-915bc8bb61f3?t=1761882689274', '<p>(BNP) - HĐND tỉnh Bắc Ninh vừa ban hành Nghị quyết Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông trên địa bàn tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/23288501/IMG_0515.jpg/b32ecd82-b595-cc4c-3b39-915bc8bb61f3?t=1761882689274\" style=\"height: 600px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các tổ chức, cá nhân có liên quan đến hoạt động khuyến nông và chuyển giao công nghệ trong nông nghiệp được hỗ trợ kinh phí.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, Nghị quyết quy định cụ thể các nội dung chi, mức chi hỗ trợ cho các hoạt động khuyến nông, chuyển giao công nghệ trong nông nghiệp bao gồm: Đào tạo, tập huấn, thông tin tuyên truyền, xây dựng mô hình trình diễn, tư vấn - dịch vụ khuyến nông, hợp tác quốc tế và các nội dung chi khác.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối tượng áp dụng là các tổ chức, cá nhân có liên quan đến hoạt động khuyến nông và chuyển giao công nghệ trong nông nghiệp; cơ quan quản lý nhà nước về hoạt động khuyến nông trên địa bàn tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể, hỗ trợ 100% chi phí tài liệu học, tiền ăn, tiền đi lại và nơi ở cho người dân, chủ trang trại, hợp tác xã, doanh nghiệp nhỏ trực tiếp tham gia đào tạo, tập huấn, nhận chuyển giao công nghệ nông nghiệp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hỗ trợ tối đa 100% kinh phí xây dựng mô hình trình diễn tại địa bàn khó khăn, không quá 2 tỷ đồng/mô hình; mô hình ứng dụng công nghệ cao được hỗ trợ tối đa 40% tổng kinh phí, tối đa 2 tỷ đồng/mô hình.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chi phí cho hoạt động thông tin, tuyên truyền, hội chợ, hội thảo, diễn đàn, khảo sát học tập và các chương trình khuyến nông khác thực hiện theo các quy định hiện hành và hướng dẫn của Bộ Tài chính, Bộ Nông nghiệp và Môi trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguồn kinh phí thực hiện được bố trí từ ngân sách cấp tỉnh, cấp xã và các nguồn hợp pháp khác, bảo đảm sử dụng đúng mục đích, công khai, minh bạch và theo quy định tài chính hiện hành.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghị quyết có hiệu lực từ ngày 01/11/2025</span></span></span>; đồng thời bãi bỏ Nghị quyết số 06/2021/NQ-HĐND ngày 16/7/2021 của HĐND tỉnh về quy định nội dung, mức chi hỗ trợ hoạt động khuyến nông từ ngân sách nhà nước./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\">&nbsp;</p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-quy-inh-noi-dung-chi-va-muc-chi-ho-tro-hoat-ong-khuyen-nong-29900401', '', 'BNP', 259, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.497957', 3, 11);
INSERT INTO `sync_articles` VALUES (105, '29889461', 'Các xã, phường trong tỉnh chủ động áp dụng các biện pháp phòng, chống dịch bệnh Cúm...', 'Các xã, phường trong tỉnh chủ động áp dụng các biện pháp phòng, chống dịch bệnh Cúm gia cầm phù hợp với điều kiện thực tế tại địa phương', '/documents/37632/23288501/2+%284%29.jpg/40a8a434-551c-909c-8d20-44590bfe656e?t=1761879902232', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Lê Xuân Lợi vừa ký văn bản số 4187/UBND-NN yêu cầu các sở, ngành, địa phương tăng cường công tác phòng, chống dịch bệnh Cúm gia cầm.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288501/2+%284%29.jpg/40a8a434-551c-909c-8d20-44590bfe656e?t=1761879902232\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh họa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Cụ thể, Phó Chủ tịch UBND tỉnh Lê Xuân Lợi yêu cầu UBND các xã, phường tập trung nguồn lực phòng, chống dịch Cúm gia cầm; bảo đảm kinh phí để tổ chức triển khai kịp thời, khống chế hiệu quả khi dịch bệnh xảy ra. Chỉ đạo bộ phận chuyên môn phối hợp với Chi cục Chăn nuôi Thú y và Thủy sản quản lý chặt chẽ hoạt động giết mổ, kinh doanh, vận chuyển động vật, sản phẩm động vật trên địa bàn; xử lý nghiêm các trường hợp vi phạm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Hướng dẫn người chăn nuôi gia cầm tăng cường áp dụng nghiêm ngặt các biện pháp chăn nuôi an toàn sinh học, chủ động phòng dịch; thường xuyên vệ sinh, sát trùng bằng vôi bột, hóa chất để tiêu diệt mầm bệnh. Rà soát, tổ chức tiêm vắc xin Cúm phòng bệnh cho đàn gia cầm, bảo đảm đạt tỷ lệ trên 80% tổng đàn tại thời điểm tiêm; thường xuyên rà soát, tiêm phòng bổ sung cho đàn gia cầm mới phát sinh và chưa được tiêm phòng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tăng cường kiểm tra việc bảo đảm an toàn vệ sinh thực phẩm, các khu vực có nguy cơ tiêu hủy, vứt bỏ xác động vật trái phép như ao, hồ, sông suối; tăng cường các biện pháp vệ sinh môi trường, khơi thông cống rãnh, loại bỏ rác thải tồn đọng sau thiên tai.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tổ chức tuyên truyền sâu rộng cho người dân thực hiện nghiêm các biện pháp phòng, chống dịch bệnh Cúm gia cầm. Không buôn bán, giết mổ, tiêu thụ gia cầm mắc bệnh, nghi mắc bệnh, vứt xác gia cầm, chất thải chưa qua xử lý ra môi trường. Không sử dụng gia cầm không rõ nguồn gốc, gia cầm, sản phẩm gia cầm chưa qua kiểm dịch; khi sử dụng sản phẩm gia cầm phải nấu chín; không tham gia vào hoạt động buôn bán, vận chuyển lậu gia cầm, sản phẩm gia cầm… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các xã Yên Thế, Bố Hạ, Đồng Kỳ, Xuân Lương và Tam Tiến chỉ đạo phòng chuyên môn phối hợp với đơn vị chuyên môn của Sở Nông nghiệp và Môi trường tiếp tục thực hiện các nội dung thuộc Đề án “Xây dựng vùng an toàn dịch bệnh Cúm gia cầm và Niu-cát-xơn đối với gà trên địa bàn huyện Yên Thế, tỉnh Bắc Giang giai đoạn 2021-2025”, nhất là tập trung công tác tiêm phòng vắc xin Cúm cho đàn gà theo kế hoạch của Đề án xong trước 30/11/2025, kết hợp vệ sinh tiêu độc khử trùng môi trường phòng, chống dịch bệnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Sở Nông nghiệp và Môi trường chỉ đạo Chi cục Chăn nuôi, Thú y và Thủy sản thực hiện nghiêm, có hiệu quả các giải pháp phòng, chống dịch bệnh Cúm gia cầm A/H5N1, A/H5N6, A/H5N8 và các chủng vi rút Cúm gia cầm khác. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phối hợp với các địa phương tăng cường quản lý, giám sát chặt chẽ tình hình dịch bệnh Cúm gia cầm trên địa bàn; tổ chức tiêm phòng vắc xin Cúm cho đàn gia cầm; chủ động lấy mẫu của gia cầm có dấu hiệu mắc bệnh, nghi mắc bệnh Cúm gia cầm, gia cầm tại các địa bàn có nguy cơ cao để xét nghiệm xác định nguyên nhân gây bệnh để kịp thời cảnh báo, xử lý, tiêu hủy đàn gia cầm mắc bệnh, nghi mắc bệnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tổ chức các Đoàn kiểm tra công tác phòng, chống dịch bệnh Cúm gia cầm đối với các xã, phường, chủ động áp dụng các biện pháp phòng, chống dịch phù hợp với điều kiện thực tế tại địa phương được kiểm tra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đoàn kiểm tra liên ngành cơ động phòng, chống dịch động vật tăng cường kiểm tra công tác vận chuyển, kinh doanh động vật, sản phẩm động vật trên địa bàn tỉnh. Giám sát chặt chẽ hoạt động của các chợ đầu mối, các địa điểm tập kết, vận chuyển, buôn bán, giết mổ gia súc gia cầm. Xử lý nghiêm các trường hợp nhập lậu, vận chuyển động vật, sản phẩm động vật không rõ nguồn gốc, chưa qua kiểm dịch vận chuyển ra vào địa bàn tỉnh.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/cac-xa-phuong-trong-tinh-chu-ong-ap-dung-cac-bien-phap-phong-chong-dich-benh-cum-gia-cam-phu-hop-voi-ieu-kien-thuc-te-tai-ia-phuong-29889461', '', 'Nguyễn Miền', 69, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.545527', 3, 11);
INSERT INTO `sync_articles` VALUES (106, '29557302', 'Chủ tịch UBND tỉnh Vương Quốc Tuấn: Nghiên cứu xây dựng chính sách và ứng dụng các...', 'Chủ tịch UBND tỉnh Vương Quốc Tuấn: Nghiên cứu xây dựng chính sách và ứng dụng các thành tựu khoa học công nghệ vào sản xuất, chế biến nông sản chủ lực của tỉnh', '/documents/37632/23288501/2+%283%29.jpg/568de42d-db61-daed-23c9-7de24de0bd77?t=1761824780235', '<p>(BNP) - Chiều 30/10, đồng chí Vương Quốc Tuấn, Uỷ viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh. Cùng đi có đại diện lãnh đạo các sở, ngành, cơ quan của tỉnh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/2+%283%29.jpg/568de42d-db61-daed-23c9-7de24de0bd77?t=1761824780235\" style=\"height: 606px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Chủ tịch&nbsp;UBND tỉnh Vương Quốc Tuấn và đoàn công tác của tỉnh đến thăm Công ty Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch UBND tỉnh Vương Quốc Tuấn và đoàn công tác của tỉnh đến thăm Công ty Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu (phường Phượng Sơn). Đây là doanh nghiệp chuyên chế biến, bảo quản và kinh doanh nông sản sơ biến xuất khẩu tươi, đông lạnh, nước trái cây như: Vải thiều, đậu tương rau, ngô ngọt, rau các loại. Quy mô sản lượng mỗi sản phẩm đạt 3 nghìn - 5 nghìn tấn mỗi năm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các vùng nguyên liệu của doanh nghiệp được canh tác theo hướng giảm phát thải, organic. Đặc biệt, sản phẩm vải thiều do doanh nghiệp chế biến có vùng liên kết được chứng nhân Organic Việt Nam. Hiện nay, 80% sản lượng chế biến của doanh nghiệp được xuất khẩu vào thị trường lớn như: Nhật, Mỹ, Hàn Quốc, Châu Âu, Úc...; doanh thu hàng năm đạt ngưỡng 5,5 triệu USD; duy trì mức tăng trưởng hàng năm 6 - 10%. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/1+%288%29.jpg/5192dad0-f5e6-fb43-7dd9-0b5ccbab3fe9?t=1761824879269\" style=\"height: 491px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh buổi làm việc với Công ty&nbsp;Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thăm Công ty Cổ phần xuất nhập khẩu Vifoco (phường Bắc Giang) được thành lập năm 2008, hoạt động trong lĩnh vực sản xuất, chế biến và xuất khẩu nông sản.&nbsp;Hiện tại, doanh nghiệp áp dụng chặt chẽ quy trình chế biến khép kín, từ trồng trọt, chăm sóc đến thu hoạch, chế biến đảm bảo vệ sinh an toàn thực phẩm gắn với bảo vệ môi trường. Vifoco cũng chủ động liên kết sản xuất với nhiều địa phương thuộc các tỉnh miền núi Trung du phía Bắc; xây dựng, sản xuất thành vùng chuyên canh hàng hóa tập trung với nhiều nông sản chủ lực như: Bí đỏ, ngô ngọt, khoai lang, vải thiều, dưa chuột… đảm bảo vận hành khép kín, có thể chế biến, cung cấp khoảng 8 nghìn - 10 nghìn tấn/năm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Để góp phần nâng tầm sản phẩm nông sản Việt Nam, Công ty Vifoco xây dựng chiến lược phát triển theo hướng ưu tiên các sản phẩm nông sản đặc trưng đạt chứng nhận OCOP từ 3 sao trở lên như: Ngô ngọt nguyên hạt, khoai tây sợi IQF, vải thiều IQF, vải thiều đóng hộp, nhãn…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/3.jpg/4c1a0ff3-2df2-6976-d801-ddf3567323c6?t=1761824962421\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Vương Quốc Tuấn và đoàn công tác thăm&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"> Công ty Cổ phần xuất nhập khẩu Vifoco.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Qua thăm, tìm hiểu mô hình sản xuất, Chủ tịch UBND tỉnh Vương Quốc Tuấn đánh giá cao những nỗ lực của các doanh nghiệp trong quá trình hoạt động, dù còn nhiều khó khăn nhưng các doanh nghiệp vẫn đạt được những con số ấn tượng, mở rộng thị phần xuất khẩu ở những thị trường khó tính, tăng doanh thu, tạo nhiều việc làm cho nhiều người lao động; xây dựng được uy tín, thương hiệu trên thị trường, đóng góp quan trọng vào dịch chuyển cơ cấu kinh tế của tỉnh, gia tăng giá trị xuất khẩu nông sản.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Ghi nhận kiến nghị của doanh nghiệp, Chủ tịch UBND tỉnh đánh giá cao khát vọng và chiến lược của các doanh nghiệp, đề nghị các doanh nghiệp tiếp tục nghiên cứu, đánh giá kỹ thị trường, mở rộng vùng nguyên liệu, nâng cao chất lượng chế biến nông sản. Đặc biệt, đối với sản phẩm vải thiều của tỉnh, Chủ tịch UBND tỉnh cho rằng, các doanh nghiệp cần đi theo hướng chuyên sâu, hiệu quả. Tỉnh giao cho Sở Khoa học và Công nghệ đóng vai trò “hiến kế, gác cửa” nhằm nghiên cứu, ứng dụng thành tựu khoa học công nghệ vào sản xuất, chế biến vải thiều nói riêng, các nông sản chủ lực nói chung. Tỉnh đặt quyết tâm đưa sản phẩm vải thiều trở thành thương hiệu mang tầm quốc tế, được xây dựng trên cơ sở giá trị thực và hướng đi bền vững. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Chủ tịch UBND tỉnh yêu cầu Sở Nông nghiệp và Môi trường, Sở Công thương phối hợp tham mưu HĐND tỉnh xây dựng một Nghị quyết riêng về phát triển cây vải thiều, bao gồm quy hoạch vùng trồng, xác định xuất xứ thương hiệu, định vị rõ thương hiệu đặc trưng cho vải thiều Bắc Ninh, hướng tới mở rộng quy mô, nâng cao giá trị sản phẩm. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/5+%281%29.jpg/dc34824b-0bf7-7143-1c5b-26c71411acd9?t=1761825038355\" style=\"height: 555px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các doanh nghiệp&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">áp dụng chặt chẽ quy trình chế biến khép kín.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các sở, ngành liên quan tập trung nghiên cứu, hỗ trợ chế biến, nhằm tạo ra sản phẩm vải thiều trái vụ. Trước mắt, cần nghiên cứu kéo dài thời gian thu hoạch vụ vải thiều hiện có, phát triển đa dạng các sản phẩm chế biến từ vải thiều như: Nước ép, sấy khô, đông lạnh, tinh dầu, mỹ phẩm, đồ uống tự nhiên,… nhằm tăng giá trị và sức cạnh tranh quốc tế.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Ngoài ra, từ quy hoạch tổng thể của tỉnh, các ngành, địa phương phải quyết liệt hơn trong việc quy hoạch vùng trồng, tạo dựng những vùng sản xuất có giá trị thực sự. Cùng đó, nghiên cứu cơ chế, chính sách cụ thể nhằm thu hút các doanh nghiệp đầu tư quy mô lớn, hỗ trợ truy xuất nguồn gốc, xây dựng thương hiệu vùng trồng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Chủ tịch UBND tỉnh cũng đề nghị các sở, ngành liên quan tiếp tục rà soát, đánh giá tính phù hợp của các quy định hỗ trợ phát triển nông nghiệp hiện hành, tham mưu điều chỉnh, khuyến khích đổi mới sáng tạo, chuyển đổi số trong lĩnh vực nông nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tỉnh cũng sẽ hỗ trợ doanh nghiệp, hợp tác xã triển khai truy xuất nguồn gốc, xây dựng mã số vùng trồng, tạo điều kiện cho nông sản địa phương khẳng định uy tín trên thị trường quốc tế. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/chu-tich-ubnd-tinh-vuong-quoc-tuan-nghien-cuu-xay-dung-chinh-sach-va-ung-dung-cac-thanh-tuu-khoa-hoc-cong-nghe-vao-san-xuat-che-bien-nong-san-chu-luc-cua-tinh-29557302', '', 'Nguyễn Miền', 477, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.600969', 3, 11);
INSERT INTO `sync_articles` VALUES (107, '29494918', 'Điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050', 'Điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/29/duongsat-17617350052801071929828.jpg', '<p>(BNP) - Phó Thủ tướng Trần Hồng Hà vừa ký Quyết định số 2404/QĐ-TTg phê duyệt điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050.</p>', '<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quyết định nêu rõ, điều chỉnh, bổ sung một số nội dung về mạng lưới quy hoạch:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Đối với tuyến đường sắt hiện hữu</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh phạm vi 02 tuyến: Hà Nội - Thành phố Hồ Chí Minh, Hà Nội - Lào Cai</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh lộ trình chuyển đổi công năng tuyến đường sắt Hà Nội - Hải Phòng đoạn sau ga Hải Phòng đến cảng Chùa Vẽ sau khi hoàn thành đầu tư, đưa vào khai thác ga Vật Cách.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Đối với tuyến đường sắt mới</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh tên, quy mô, lộ trình đầu tư tuyến đường sắt tốc độ cao trên trục Bắc - Nam; bổ sung tuyến đường sắt tốc độ cao Hà Nội - Quảng Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh quy mô, lộ trình đầu tư 02 tuyến: Lào Cai - Hà Nội - Hải Phòng, Thành phố Hồ Chí Minh - Lộc Ninh; điều chỉnh lộ trình đầu tư 03 tuyến: Hà Nội - Đồng Đăng, Hải Phòng - Hạ Long - Móng Cái, Tháp Chàm - Đà Lạt.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh phạm vi, quy mô 07 tuyến: Yên Viên - Phả Lại - Hạ Long - Cái Lân, vành đai phía Đông Thành phố Hà Nội, Nam Định - Thái Bình - Hải Phòng, Vũng Áng - Mụ Giạ, Biên Hòa - Vũng Tàu, Thành phố Hồ Chí Minh - Cần Thơ - Cà Mau, Đà Nẵng - Kon Tum - Gia Lai - Đắk Lắk - Đắk Nông - Bình Phước.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh không đưa vào quy hoạch tuyến Thủ Thiêm - Long Thành và chuyển thành đường sắt đô thị; giao Thành phố Hồ Chí Minh và tỉnh Đồng Nai cập nhật vào quy hoạch tỉnh và các quy hoạch liên quan.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Bổ sung tuyến đường sắt An Bình - Sài Gòn (Hòa Hưng) - Tân Kiên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Quyết định, bổ sung kết nối với đường sắt Trung Quốc tại cửa khẩu Móng Cái thông qua tuyến đường sắt Hải Phòng - Hạ Long - Móng Cái; bổ sung kết nối với Campuchia tại cửa khẩu Mộc Bài thông qua tuyến đường sắt Thành phố Hồ Chí Minh - Tây Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều chỉnh, bổ sung về kết nối các đô thị, đầu mối giao thông lớn:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu đầu mối Hà Nội</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu đầu mối Thành phố Hồ Chí Minh</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu vực thành phố Đà Nẵng bổ sung lộ trình di dời ga Đà Nẵng thực hiện trước năm 2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh định hướng kết nối đường sắt với 02 cảng biển Nghi Sơn (Thanh Hóa), Hiệp Phước (Thành phố Hồ Chí Minh), Cảng hàng không quốc tế Tân Sơn Nhất (Thành phố Hồ Chí Minh), Cảng hàng không quốc tế Long Thành (Đồng Nai), Cảng hàng không quốc tế thứ hai Hà Nội, Cảng hàng không quốc tế Gia Bình, Cảng cạn Văn Lâm (Hưng Yên), Gia Bình (Bắc Ninh).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các nội dung khác giữ nguyên theo Quyết định số 1769/QĐ-TTg ngày 19/10/2021 của Thủ tướng Chính phủ phê duyệt Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ieu-chinh-quy-hoach-mang-luoi-uong-sat-thoi-ky-2021-2030-tam-nhin-en-nam-2050-29494918', '', 'BNP', 73, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.640035', 3, 11);
INSERT INTO `sync_articles` VALUES (108, '29289801', 'Tăng cường kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025', 'Tăng cường kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025', '/documents/37632/23986559/IMG_2264.jpg/67ee492f-498f-688a-ac94-e2d2ed8280fd?t=1761708589640', '<p>(BNP) - Ban Tổ chức Hội chợ Mùa Thu 2025 vừa có văn bản đề nghị UBND các tỉnh, thành phố kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/IMG_2264.jpg/67ee492f-498f-688a-ac94-e2d2ed8280fd?t=1761708589640\" style=\"height: 629px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ Mùa Thu 2025 được tổ chức từ ngày 25/10 đến ngày 04/11/2025. Trong 3 ngày đầu diễn ra, Hội chợ đã tiếp đón lượng lớn các đối tác thương mại, khách tham quan trong và ngoài nước tới giao thương và mua sắm. Tuy nhiên, qua phản ánh của lực lượng Quản lý thị trường còn một số vấn đề tồn tại như: Một số hộ kinh doanh thực phẩm chế biến sẵn chưa ghi rõ tên cơ sở sản xuất, địa chỉ và hạn sử dụng trên bao bì sản phẩm theo quy định. Một số gian hàng kinh doanh nông sản, thực phẩm không ghi rõ tên sản phẩm, số công bố sản phẩm, thành phần hoặc hạn sử dụng; bao bì chưa đảm bảo thông tin bắt buộc theo quy định về ghi nhãn hàng hóa. Một số gian hàng kinh doanh đồ ăn tại chỗ hoặc mang đi chưa có Giấy chứng nhận đủ điều kiện an toàn thực phẩm... Bên cạnh đó còn có hiện tượng một số gian hàng tham gia Hội chợ bán sản phẩm, hàng hóa không đúng với giá niêm yết hoặc không công khai giá niêm yết; giá bán cao hơn giá thị trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm bảo đảm hoạt động thương mại, trưng bày, giới thiệu sản phẩm tại Hội chợ được diễn ra văn minh, đúng quy định pháp luật, Ban Tổ chức đề nghị UBND các tỉnh, thành phố quan tâm, chỉ đạo Sở Công Thương, Chi cục Quản lý thị trường các tỉnh, thành phố phối hợp với Ban Tổ chức kiểm tra, xử lý các hành vi vi phạm pháp luật trong lĩnh vực công thương tại hội chợ, bao gồm: Hàng giả, hàng nhái, hàng kém chất lượng, xâm phạm quyền sở hữu trí tuệ; gian lận thương mại, không niêm yết giá hoặc bán hàng không theo giá niêm yết; vi phạm quy định về an toàn thực phẩm (đối với các gian hàng kinh 2 doanh thực phẩm); vi phạm quy định về xúc tiến thương mại và các quy định khác liên quan. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng đó, xử lý hoặc kiến nghị xử lý theo quy định hiện hành đối với các trường hợp vi phạm; đồng thời nhắc nhở, tuyên truyền, hướng dẫn các doanh nghiệp, đơn vị tham gia Hội chợ thực hiện nghiêm quy định pháp luật trong các lĩnh vực nêu trên./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/tang-cuong-kiem-tra-kiem-soat-va-xu-ly-vi-pham-tai-hoi-cho-mua-thu-2025-29289801', '', 'BNP', 149, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.684744', 3, 11);
INSERT INTO `sync_articles` VALUES (110, '29164840', 'Tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026', 'Tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026', '/documents/37632/23986559/IMG_6600.jpg/eea2f8e6-8b12-ac27-9a37-44733fdb4e51?t=1761638150525', '<p>(BNP) - Các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam sẽ bắt đầu từ đầu năm 2026 (tháng 1) được tập trung tổ chức trong tháng 3 (tháng cao điểm) và kéo dài trong cả năm 2026.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/IMG_6600.jpg/eea2f8e6-8b12-ac27-9a37-44733fdb4e51?t=1761638150525\" style=\"height: 646px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hoạt động vì quyền lợi người tiêu dùng tổ chức tập trung vào Tết Dương lịch, Tết Âm lịch, các mùa mua sắm hoặc các ngày cao điểm mua sắm trên thị trường.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ Công Thương vừa ban hành Kế hoạch tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, chủ đề cho các hoạt động Ngày Quyền của người tiêu dùng Việt Nam năm 2026 là “An toàn thông tin - Gắn kết niềm tin - Tiêu dùng bền vững”. Các hoạt động vì quyền lợi người tiêu dùng được khuyến khích tổ chức và thực hiện trong suốt cả năm 2026 trong đó tập trung vào các khoảng thời gian cao điểm về kinh doanh và tiêu dùng như: Tết Dương lịch, Tết Âm lịch, các mùa mua sắm hoặc các ngày cao điểm mua sắm trên thị trường. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong Tháng cao điểm hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 sẽ diễn ra Lễ phát động Ngày Quyền của người tiêu dùng Việt Nam năm 2026. Ngay sau Lễ phát động, triển khai các hoạt động nổi bật mang tính cộng đồng, hướng đến sự tham gia rộng rãi của người dân và sự lan tỏa trên môi trường số như: Giải chạy cộng đồng; Khu trải nghiệm xanh và số; Không gian Doanh nghiệp xanh và minh bạch là khu vực trưng bày và giới thiệu sản phẩm xanh, thân thiện môi trường. Bên cạnh trưng bày thực tế, chương trình huy động sự tham gia của các sàn giao dịch trực tuyến và doanh nghiệp thương mại điện tử.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh những hoạt động trọng tâm, tạo điểm nhấn còn diễn ra các hoạt động hưởng ứng khác như: Công tác tuyên truyền, truyền thông; Hoạt động nghiên cứu, tập huấn, phổ biến kiến thức và nâng cao hiểu biết pháp luật; Chương trình tri ân và hỗ trợ người tiêu dùng; Hoạt động xúc tiến thương mại và củng cố niềm tin của người tiêu dùng vào doanh nghiệp và sản phẩm uy tín.</span></span></span></p>\n\n<p class=\"MsoBodyText\" style=\"text-align:justify; text-indent:0cm; margin-bottom:12px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:black\">Tại các địa phương ngoài các hoạt động trên còn diễn ra các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 bao gồm:&nbsp;</span>M<span style=\"color:black\">ít tinh, tuần hành, diễu hành; tổ chức các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam tại các chợ, siêu thị, trung tâm thương mại, cơ sở sản xuất, kinh doanh của các doanh nghiệp tại địa phương; tổ chức các chương trình tư vấn, hỗ trợ và tuyên truyền pháp luật về bảo vệ người tiêu dùng; các hoạt động thúc đẩy sự hiểu biết và tương tác giữa doanh nghiệp và người tiêu dùng; các chương trình, hoạt động tri ân người tiêu dùng; chương trình ký cam kết doanh nghiệp sản xuất, cung cấp dịch vụ đảm bảo an toàn, chất lượng vì người tiêu dùng; tuyên dương các doanh nghiệp có nhiều hoạt động hướng tới người tiêu dùng.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 được tổ chức nhằm kêu gọi, động viên, khuyến khích sự tham gia của các cơ quan nhà nước, tổ chức xã hội, doanh nghiệp và người tiêu dùng vào các hoạt động liên quan; từng bước đưa Ngày Quyền của người tiêu dùng thành động lực và điểm nhấn quan trọng trong đời sống kinh tế - xã hội, góp phần xây dựng môi trường kinh doanh, tiêu dùng lành mạnh cho đất nước./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/to-chuc-cac-hoat-ong-huong-ung-ngay-quyen-cua-nguoi-tieu-dung-viet-nam-nam-2026-29164840', '', 'BNP', 99, 'Kinh tế', 3, '', '38762', '{}', '2025-11-01 07:12:48.772212', 3, 11);
INSERT INTO `sync_articles` VALUES (111, '28202001', 'Bắc Ninh tổ chức xe miễn phí đưa, đón Nhân dân và du khách tham quan Hội chợ Mùa Thu...', 'Bắc Ninh tổ chức xe miễn phí đưa, đón Nhân dân và du khách tham quan Hội chợ Mùa Thu từ ngày 26/10 - 4/11/2025', '/documents/37632/18152201/hoi-cho-mua-thu-17611208863751845302975.png/14d098af-4dae-27e6-d48c-f8fcc1118388?t=1761277531805', '<p>(BNP) - Nhằm tạo điều kiện thuận lợi cho Nhân dân và du khách tham quan Hội chợ Mùa Thu 2025 với chủ đề “Kết nối con người với sản xuất, kinh doanh” - “Nơi văn hoá và giao thương hội tụ”, Sở Văn hoá, Thể thao và Du lịch tỉnh Bắc Ninh tổ chức chương trình xe đưa, đón miễn phí từ Bắc Ninh đến...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><img src=\"/documents/37632/18152201/hoi-cho-mua-thu-17611208863751845302975.png/14d098af-4dae-27e6-d48c-f8fcc1118388?t=1761277531805\" style=\"height: 522px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh hoạ: Nguồn baochinhphu.vn.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xe đưa đón xuất phát tại 2 địa điểm: Quảng trường 3/2 (phường Bắc Giang, thành phố Bắc Ninh) và Bảo tàng Bắc Ninh số 2 (số 2, đường Lý Thái Tổ, phường Kinh Bắc, thành phố Bắc Ninh). Điểm đến là Trung tâm Triển lãm Việt Nam (VEC) - Hà Nội.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian hoạt động cụ thể:</span></span></span></p>\n\n<table class=\"Table\" style=\"width:625px; border-collapse:collapse; border:none\" width=\"625\">\n	<tbody>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:1px solid black\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Địa điểm</b></span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Buổi sáng (đi -về)</b></span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Buổi chiều (đi -về)</b></span></span></span></p>\n			</td>\n		</tr>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:1px solid black\">\n			<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quảng trường 3/2</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">7h30 - 13h00</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">15h00 - 21h00</span></span></span></p>\n			</td>\n		</tr>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:1px solid black\">\n			<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bảo tàng Bắc Ninh số 2</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">8h00 - 13h00</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">15h00 - 21h00</span></span></span></p>\n			</td>\n		</tr>\n	</tbody>\n</table>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng cộng có 144 chuyến xe phục vụ trong 10 ngày, chia đều cho 2 điểm đón.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thông tin về Hội chợ Mùa Thu 2025</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ Mùa Thu 2025 là hội chợ cấp quốc gia đầu tiên do Thủ tướng Chính phủ trực tiếp chỉ đạo triển khai. Sự kiện được mệnh danh là “Siêu hội chợ 6 nhất” với: Quy mô lớn nhất, không gian hiện đại nhất, sản phẩm phong phú nhất, chất lượng cao nhất, hoạt động hấp dẫn nhất và ưu đãi tốt nhất.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ quy tụ 34 tỉnh, thành, hơn 2.500 doanh nghiệp, trong đó có 100 doanh nghiệp nước ngoài đến từ nhiều châu lục. Toàn bộ khu vực triển lãm có 3.000 gian hàng với hơn 10.000 sản phẩm được trưng bày, giao thương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không gian hội chợ được thiết kế như hành trình xuyên Việt qua 5 phân khu chủ đề, giới thiệu những câu chuyện sống động về con người, văn hóa và kinh tế của đất nước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh không gian trưng bày trong nhà, chuỗi hoạt động ngoài trời diễn ra sôi động với các trò chơi, concert, biểu diễn nghệ thuật, trình diễn thời trang, giao lưu văn hoá. Điểm nhấn nổi bật là Lễ hội Ẩm thực “Thu Mỹ Vị” tại Sân Nam, gồm hai phân khu đặc sắc: “Cheer Fest - Bia &amp; Nướng Xuyên Biên Giới” và “Một Vòng Việt Nam”, mang đến không gian rực rỡ sắc thu và đậm đà hương vị Việt.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Hội chợ Mùa Thu 2025, tỉnh Bắc Ninh tham gia với gian hàng quy mô 200m² thuộc phân khu “Thu đất Việt - Sắc nước hương Thu” do Bộ Công Thương chủ trì.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại đây, Bắc Ninh sẽ trình diễn di sản văn hóa Quan họ, trưng bày và quảng bá các sản phẩm đặc trưng, sản phẩm mang nhãn hiệu tập thể, nhãn hiệu chứng nhận, chỉ dẫn địa lý của địa phương. Ngoài ra, tỉnh còn giới thiệu các món ăn truyền thống và đặc sản tiêu biểu tại Khu Ẩm thực do Công ty Triển lãm Hội chợ Việt Nam (VEC) tổ chức.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Hướng dẫn đăng ký tham gia xe đưa đón</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Người dân và du khách đăng ký online qua đường link:&nbsp;<a href=\"https://forms.gle/ehK5Dq7FEfyvmdyd9\" style=\"color:#0563c1; text-decoration:underline\" target=\"_blank\">https://forms.gle/ehK5Dq7FEfyvmdyd9</a>&nbsp;hoặc quét mã QR được cung cấp.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/M%C3%A3.png/8b58362b-0433-d644-1e89-ea95cb532ff7?t=1761277265875\" style=\"height: 300px; width: 300px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Khi đủ số lượng đăng ký, cổng đăng ký sẽ tự động đóng. Danh sách hành khách được chốt vào 22h hàng ngày và thông báo trực tiếp trên đường link đăng ký.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>* Lưu ý:</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ưu tiên đăng ký online, chỉ nhận đăng ký trực tiếp khi còn chỗ trống.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mỗi lần đăng ký chỉ áp dụng cho 01 người (bao gồm cả trẻ em đi kèm).</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu không thể tham gia sau khi đăng ký, vui lòng nhắn tin báo hủy đến hotline 0985 284 920, ghi rõ: Họ tên - Điểm đón - Thời gian - Người đi cùng (nếu có).</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mọi thắc mắc liên hệ hotline 0985 284 920, từ 5h00 đến 23h00 hàng ngày.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-to-chuc-xe-mien-phi-ua-on-nhan-dan-va-du-khach-tham-quan-hoi-cho-mua-thu-tu-ngay-26-10-4-11-2025-28202001', '', 'Dương Thuỷ', 11268, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.095681', 5, 11);
INSERT INTO `sync_articles` VALUES (112, '27896501', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải tiếp và làm việc với Hiệp hội Du lịch Việt Nam', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải tiếp và làm việc với Hiệp hội Du lịch Việt Nam', '/documents/37632/18152201/HHDL+1.jpg/2de85117-59b4-39ce-283a-2574bd00303c?t=1761216398641', '<p>(BNP) - Chiều 23/10, đồng chí Đào Quang Khải, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh Bắc Ninh tiếp và làm việc với Đoàn công tác Hiệp hội Du lịch Việt Nam do&nbsp;Chủ tịch Hiệp hội&nbsp;Vũ Thế Bình làm trưởng đoàn về khảo sát thực tế Khu du lịch tâm linh - sinh thái Tây Yên Tử (xã...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/HHDL+1.jpg/2de85117-59b4-39ce-283a-2574bd00303c?t=1761216398641\" style=\"height: 478px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi tiếp và làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, Chủ tịch Hiệp hội Du lịch Việt Nam Vũ Thế Bình cho biết, chương trình khảo sát nằm trong chuỗi hoạt động phối hợp giữa Hiệp hội và Chương trình Phát triển Liên Hợp Quốc (UNDP), nhằm thúc đẩy mô hình du lịch xanh, phát triển sản phẩm du lịch bền vững, gắn với bảo tồn giá trị văn hóa và thiên nhiên của địa phương. Theo Chủ tịch Hiệp hội, Khu du lịch tâm linh - sinh thái Tây Yên Tử không chỉ là điểm đến tâm linh nổi bật mà còn là khu vực có tiềm năng lớn phát triển các loại hình du lịch sinh thái, cộng đồng và nông nghiệp xanh - phù hợp với xu hướng phát triển du lịch bền vững mà Việt Nam đang hướng tới.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Hiệp hội Du lịch Việt Nam đánh giá cao nỗ lực của tỉnh Bắc Ninh trong quy hoạch, đầu tư hạ tầng du lịch tại khu vực Tây Yên Tử, hình thành tuyến du lịch “Hành trình về miền Trúc Lâm”, tái hiện hành trình hoằng dương Phật pháp của Phật hoàng Trần Nhân Tông. Tuyến du lịch này, nếu được đầu tư đồng bộ về hạ tầng, dịch vụ và truyền thông, sẽ trở thành sản phẩm đặc trưng vùng, thu hút đông đảo du khách trong nước và quốc tế.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Hiệp hội Du lịch Việt Nam Vũ Thế Bình cũng trao đổi một số định hướng phát triển thương mại, dịch vụ và du lịch của tỉnh Bắc Ninh. Theo đó, tỉnh cần tập trung tăng tỷ trọng thương mại - dịch vụ, phát triển các loại hình đô thị kết hợp du lịch, khai thác thế mạnh ẩm thực và sản phẩm văn hóa truyền thống. Đồng thời, cần quan tâm xây dựng sản phẩm du lịch xanh, phát huy vai trò cộng đồng địa phương, hướng tới công nhận khu sinh quyển, góp phần nâng cao nhận thức và gìn giữ giá trị văn hóa bản địa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Phó Chủ tịch UBND tỉnh Đào Quang Khải khẳng định, Bắc Ninh luôn quan tâm phát triển du lịch theo hướng xanh - bền vững - có trách nhiệm với môi trường, gắn với bảo tồn các giá trị văn hóa, lịch sử vùng đất Tây Yên Tử. Tỉnh đã tập trung đầu tư hạ tầng, cảnh quan và kết nối giao thông thuận lợi, tạo nền tảng cho việc hình thành Khu du lịch xanh Tây Yên Tử - điểm nhấn quan trọng trong chiến lược phát triển du lịch của địa phương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh mong muốn, thông qua chuyến khảo sát lần này, Hiệp hội Du lịch Việt Nam sẽ hỗ trợ Bắc Ninh trong công tác quảng bá, xúc tiến, giới thiệu sản phẩm du lịch mới; qua đó thu hút thêm nhiều doanh nghiệp lữ hành và du khách đến với Tây Yên Tử.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng tại buổi làm việc, Phó Chủ tịch UBND tỉnh Đào Quang Khải thông tin thêm về các mục tiêu và dự án trọng điểm trong lĩnh vực môi trường của tỉnh. Bắc Ninh đã cơ bản xử lý các điểm nóng ô nhiễm làng nghề, hướng đến mục tiêu môi trường sống an toàn, bền vững cho thế hệ tương lai.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện tỉnh có 4 nhà máy đốt rác phát điện, sử dụng công nghệ hiện đại, công suất cao, đảm bảo xử lý toàn bộ lượng rác thải của tỉnh vào năm 2027. Các nhà máy được đầu tư theo hình thức xã hội hóa, có sự tham gia của doanh nghiệp trong và ngoài nước, góp phần đưa Bắc Ninh trở thành địa phương đi đầu trong ứng dụng công nghệ xử lý rác tiên tiến, thân thiện với môi trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Bắc Ninh khẳng định luôn ưu tiên, đầu tư phát triển du lịch bền vững gắn với bảo vệ môi trường và bảo tồn giá trị văn hóa, qua đó đưa du lịch trở thành ngành kinh tế quan trọng, xây dựng Bắc Ninh trở thành điểm đến hấp dẫn của du khách trong nước và quốc tế.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:14pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-ao-quang-khai-tiep-va-lam-viec-voi-hiep-hoi-du-lich-viet-nam-27896501', '', 'Dương Thuỷ', 601, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.143080', 5, 11);
INSERT INTO `sync_articles` VALUES (113, '27033903', 'Giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 diễn ra tại Bắc...', 'Giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 diễn ra tại Bắc Ninh từ ngày 28/10 - 02/11/2025', '/documents/37632/18152201/z7144997552335_3e7eef478751324bfe69de592efd52e8.jpg/de22c61b-8c13-4cef-2f12-01d9d0a830cb?t=1761141512550', '<p>Ngày 22/10, tại Sở Văn hóa, Thể thao và Du lịch, Ban Tổ chức địa phương họp bàn về công tác chuẩn bị tổ chức giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 sắp diễn ra tại Bắc Ninh.</p>', '<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dự họp có đại diện lãnh đạo các Sở: Văn hóa, Thể thao và Du lịch, Giáo dục và Đào tạo, Khoa học và Công nghệ, Y tế; Công an tỉnh, Công ty Điện lực, Báo và Phát TTH tỉnh, UBND phường Bắc Giang.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/18152201/z7144997552335_3e7eef478751324bfe69de592efd52e8.jpg/de22c61b-8c13-4cef-2f12-01d9d0a830cb?t=1761141512550\" style=\"height: 540px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh cuộc họp</span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tại cuộc họp, lãnh đạo Sở Văn hóa, Thể thao và Du lịch (cơ quan Thường trực Ban Tổ chức) thông tin tóm tắt về công tác triển khai&nbsp;chuẩn bị cho Giải Cầu lông quốc tế <span style=\"letter-spacing:-.3pt\">Felet Vietnam International </span>Series <span style=\"letter-spacing:-.3pt\">năm </span>2025. Sở đã chủ động báo cáo, xin ý kiến UBND tỉnh về công tác tổ chức giải; phối hợp với các sở, ngành, đơn vị liên quan tham mưu xây dựng Kế hoạch triển khai thực hiện; Quyết định thành lập Ban Tổ chức cấp tỉnh để tổ chức giải.&nbsp;Đồng thời chủ động phối hợp Liên đoàn Cầu lông Việt Nam thống nhất các nội dung; tiến hành kiểm tra, rà soát toàn bộ cơ sở vật chất hiện có tại Nhà Thi đấu thể thao tỉnh, Nhà tập luyện và Thi đấu thể dục thể thao tỉnh; bố trí đủ cơ sở vật chất,&nbsp;các điều kiện liên quan để tổ chức giải đấu như: Chuẩn bị 4 sân thi đấu (có thảm viền, ghế trọng tài, thước đo lưới, cây lau sàn, báo tỷ số…); chuẩn bị máy phát điện dự phòng, điều hòa nhiệt độ; bố trí bàn, ghế, nước uống, điều hòa tại các phòng chức năng...&nbsp;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Từ ngày 28/10 - 02/11/2025, Liên đoàn Cầu lông Việt Nam phối hợp với Sở Văn hóa, Thể thao và Du lịch Bắc Ninh tổ chức Giải Cầu lông quốc tế <span style=\"letter-spacing:-.3pt\">Felet Vietnam International </span>Series <span style=\"letter-spacing:-.3pt\">năm </span>2025 tại Nhà Thi đấu thể thao tỉnh Bắc Ninh (khu đô thị phía Nam, phường Bắc Giang). Các đoàn vận động viên sẽ tập luyện tại Nhà tập luyện và Thi đấu thể dục thể thao tỉnh, ăn nghỉ tại Khách sạn Mường Thanh.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dự kiến có hơn 300 thành viên tham dự, trong đó có 18 quốc gia đăng ký tham gia thi đấu với tổng số 260 vận động viên, huấn luyện viên, quan chức kỹ thuật quốc tế, trọng tài Việt Nam, Ban Tổ chức trung ương, nhân viên kỹ thuật... Đây là giải đấu mạnh, quy tụ những vận động viên hàng đầu, hứa hẹn mang đến nhiều trận đấu hay, kịch tính và hấp dẫn./.</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"></span></span></span></p>\n\n<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b><i></i></b></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify; text-indent:36.0pt\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/giai-cau-long-quoc-te-felet-vietnam-international-series-nam-2025-dien-ra-tai-bac-ninh-tu-ngay-28-10-02-11-2025-27033903', '', 'Hà Phương', 1608, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.182382', 5, 11);
INSERT INTO `sync_articles` VALUES (114, '26318252', 'Khai mạc Liên hoan Chèo toàn quốc năm 2025', 'Khai mạc Liên hoan Chèo toàn quốc năm 2025', '/documents/37632/18152201/KhaimacCheo+4.jpg/a816e98e-5022-2bab-6ff5-03b002a303d8?t=1760977815112', '<p>(BNP) - Tối 20/10, tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh, Bộ Văn hóa, Thể thao và Du lịch phối hợp với UBND tỉnh Bắc Ninh tổ chức khai mạc Liên hoan Chèo toàn quốc năm 2025 với sự tham gia của 12 đoàn nghệ thuật Chèo chuyên nghiệp đến từ nhiều tỉnh, thành phố trên cả nước.</p>', '<p><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+4.jpg/a816e98e-5022-2bab-6ff5-03b002a303d8?t=1760977815112\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ VH,TT&amp;DL Tạ Quang Đông (ảnh phải), Chủ tịch UBND tỉnh Bắc Ninh Vương Quốc Tuấn (thứ 5 từ trái qua) tặng hoa Hội đồng Nghệ thuật.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự lễ khai mạc có đồng chí Tạ Quang Đông, Thứ trưởng Bộ Văn hóa, Thể thao và Du lịch, Trưởng Ban Chỉ đạo Liên hoan; Nghệ sĩ Nhân dân Nguyễn Xuân Bắc, Cục trưởng Cục Nghệ thuật Biểu diễn, Thành viên Ban Chỉ đạo, Trưởng Ban Tổ chức Liên hoan Chèo toàn quốc năm 2025; đồng chí Lê Trọng Nin, Phó Vụ trưởng Vụ Văn hóa - Văn nghệ, Ban Tuyên giáo và Dân vận Trung ương; Nghệ sĩ Nhân dân Trịnh Thúy Mùi, Chủ tịch Hội Nghệ sĩ Sân khấu Việt Nam; Nghệ sĩ Nhân dân Giang Mạnh Hà, Phó Chủ tịch Hội Nghệ sĩ Sân khấu Việt Nam, thành viên Ban Chỉ đạo Liên hoan; đồng chí Đặng Trần Cường, Cục trưởng Cục Điện ảnh, Văn hóa, Thể thao và Du lịch (Bộ VHTT&amp;DL).</span></span></span><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+0.jpg/575cf18a-6421-606c-9870-07384d1e0a10?t=1760977520201\" style=\"height: 507px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"line-height:1.3;\">Hàng đầu: Chủ tịch UBND tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\">Vương Quốc Tuấn (thứ 2 từ trái qua),&nbsp;</span><span style=\"line-height:1.3;\">Thứ trưởng Bộ Văn hóa, Thể thao và Du lịch<span style=\"line-height:1.3;\">Tạ Quang Đông (ảnh trái),&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"line-height:1.3;\">Nghệ sĩ Nhân dân Nguyễn Xuân Bắc (ảnh phải) cùng c</span></span></span></span></span></span>ác đại biểu dự&nbsp;Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về phía tỉnh Bắc Ninh có các đồng chí: Vương Quốc Tuấn, Ủy viên dự khuyết Ban Chấp hành Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Bắc Ninh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; Nguyễn Văn Linh, nguyên Phó Bí thư Tỉnh uỷ Bắc Giang, Chủ tịch UBND tỉnh Bắc Giang; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Trần Thị Hằng, Phó Chủ tịch Thường trực HĐND tỉnh; Lâm Thị Hương Thành, Phó Chủ tịch HĐND tỉnh; Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy; <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lê Xuân Lợi, Phó Chủ tịch UBND tỉnh;&nbsp;</span></span></span>Tạ Đăng Đoan, Bí thư Đảng uỷ phường Kinh Bắc; cùng đại diện lãnh đạo các sở, ban, ngành, đoàn thể của tỉnh.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+00.jpg/d0c8723a-99b8-b163-96f3-7ad4983f097f?t=1760977557856\" style=\"height: 611px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ phải qua: Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Việt Oanh;</span></span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">&nbsp;Phó Chủ tịch Thường trực HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trần Thị Hằng</span></span></span></span></span></span></span>; Phó Chủ tịch HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lâm Thị Hương Thành</span></span></span></span></span></span></span>; <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"> Phó Chủ tịch UBND tỉnh</span></span></span></span> <span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lê Xuân Lợi;&nbsp;</span></span></span></span></span></span></span></span></span></span></span>Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Đình Lợi và c</span></span></span></span></span></span></span></span></span></span></span>ác đại biểu dự&nbsp;Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan còn có sự tham dự của đại diện lãnh đạo các Cục, Vụ thuộc Bộ VHTT&amp;DL; lãnh đạo các Sở VHTT&amp;DL các tỉnh, thành phố; các nghệ sĩ, diễn viên của 12 đoàn nghệ thuật Chèo chuyên nghiệp trong cả nước; cùng đông đảo khán giả yêu nghệ thuật Chèo.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình được truyền hình trực tiếp trên sóng Báo và Phát thanh truyền hình Bắc Ninh, đồng thời được tiếp sóng bởi các cơ quan Báo và Phát thanh truyền hình của 18 tỉnh, thành phố trong cả nước, giúp lan tỏa không khí của Liên hoan rộng khắp, đến với đông đảo khán giả yêu nghệ thuật Chèo.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+1.jpg/85609320-d772-1dc7-86bb-28b660ec56cf?t=1760977582774\" style=\"height: 648px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Tạ Quang Đông p<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">hát biểu khai mạc Liên hoan.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu khai mạc, Thứ trưởng <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ VHTT&amp;DL&nbsp;</span></span></span>Tạ Quang Đông khẳng định, Liên hoan Chèo toàn quốc là sự kiện nghệ thuật chuyên nghiệp quan trọng, góp phần giữ gìn và phát huy giá trị của nghệ thuật Chèo - loại hình sân khấu truyền thống độc đáo của dân tộc. Đồng thời ghi nhận sự chuẩn bị chu đáo của các đơn vị nghệ thuật và sự phối hợp tích cực, hiệu quả của UBND tỉnh Bắc Ninh - địa phương đăng cai tổ chức.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span>Thứ trưởng <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ VHTT&amp;DL&nbsp;</span></span></span></span></span></span>nhấn mạnh, việc sắp xếp, kiện toàn hệ thống các đơn vị nghệ thuật công lập là bước đi cần thiết nhằm xây dựng nền nghệ thuật chuyên nghiệp, tinh gọn, hiệu quả và phát triển bền vững. Đảng và Nhà nước luôn coi bảo tồn, phát huy giá trị văn hóa truyền thống - trong đó có nghệ thuật Chèo - là trách nhiệm và sứ mệnh trong xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, Bộ Chính trị và Chính phủ đang giao Bộ VH,TT&amp;DL chủ trì xây dựng Nghị quyết chuyên đề về chấn hưng và phát triển văn hóa Việt Nam trong thời kỳ mới, thể hiện sự quan tâm sâu sắc của Đảng, Nhà nước đối với lĩnh vực văn hóa - coi văn hóa là nền tảng tinh thần và động lực phát triển đất nước.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+2.jpg/632060db-9ec8-491c-47d6-8a3a94d04111?t=1760977641487\" style=\"height: 638px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi p<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">hát biểu chào mừng Liên hoan.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu chào mừng Liên hoan, Phó Chủ tịch UBND tỉnh Lê Xuân Lợi bày tỏ niềm vinh dự, tự hào khi Bắc Ninh được lựa chọn đăng cai tổ chức sự kiện quy mô quốc gia này. Đồng chí nhấn mạnh, Liên hoan Chèo toàn quốc năm 2025 là ngày hội lớn của sân khấu Chèo cả nước, là dịp để các nghệ sĩ giao lưu, học hỏi, trao đổi kinh nghiệm, đồng thời mang đến cho nhân dân cơ hội thưởng thức những tác phẩm đặc sắc, góp phần gìn giữ và phát huy giá trị nghệ thuật Chèo truyền thống.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh cũng giới thiệu về Bắc Ninh - vùng đất “địa linh nhân kiệt”, giàu truyền thống văn hiến, nơi khởi nguồn của dân ca Quan họ và chiếu chèo xứ Bắc - một trong “tứ chiếu chèo” nổi tiếng của Việt Nam. Bắc Ninh luôn quan tâm công tác bảo tồn, phát triển Chèo thông qua việc tổ chức hội thi, liên hoan, hội thảo; mở lớp bồi dưỡng nghệ nhân; đưa nghệ thuật Chèo vào trường học và khôi phục các làng Chèo cổ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí khẳng định, việc tổ chức Liên hoan tại Bắc Ninh thể hiện sự quan tâm của Đảng, Nhà nước và Bộ VH,TT&amp;DL đối với công tác bảo tồn nghệ thuật truyền thống; đồng thời là nguồn động viên to lớn cho các nghệ sĩ và công chúng yêu Chèo.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+3.jpg/133278d0-8dcd-62b8-a2d9-df2c94865b65?t=1760977674066\" style=\"height: 532px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghệ sĩ Nhân dân Nguyễn Xuân Bắc,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở VH,TT&amp;DL</span></span></span></span>&nbsp;tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bùi Thị Thu Thủy&nbsp;</span></span></span></span></span></span>tặng hoa cho các đoàn nghệ thuật.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại lễ khai mạc, Ban Tổ chức đã tặng hoa cho các đoàn nghệ thuật và Hội đồng Nghệ thuật tham gia Liên hoan. Các đoàn nghệ thuật cũng ủng hộ 210 triệu đồng hỗ trợ đồng bào bị ảnh hưởng bởi bão lũ tại Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc là hoạt động nghệ thuật quy mô quốc gia, được tổ chức 3 năm một lần nhằm đánh giá, tổng kết chất lượng sáng tạo, dàn dựng và biểu diễn của các đơn vị nghệ thuật chèo trên toàn quốc. Đây cũng là dịp tôn vinh các tập thể, cá nhân có nhiều đóng góp trong công tác bảo tồn và phát huy giá trị nghệ thuật Chèo - loại hình sân khấu dân tộc đặc sắc, đậm đà bản sắc văn hóa Việt Nam. </span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+5.jpg/8051670d-e5c4-0d47-9cc6-2c6c37725565?t=1760977845408\" style=\"height: 659px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở VH,TT&amp;DL</span></span></span></span>&nbsp;tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bùi Thị Thu Thủy tiếp nhận ủng hộ của các đoàn nghệ thuật tham gia Liên hoan.</span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan năm nay quy tụ gần 900 nghệ sĩ, diễn viên và nhạc công, với 21 vở diễn được đầu tư công phu, phản ánh sâu sắc đời sống xã hội, ca ngợi quê hương, đất nước và con người Việt Nam. Công tác chấm giải được thực hiện theo Quy chế của Cục Nghệ thuật Biểu diễn, với các hạng mục Huy chương Vàng, Huy chương Bạc và Giải Xuất sắc cho tập thể, cá nhân đạt thành tích cao.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+6.jpg/451444bd-6605-3b49-0f88-cfcb0361f4d6?t=1760977884019\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vở diễn “Thiên mệnh” do Nhà hát Chèo Bắc Ninh biểu diễn tại Lễ khai mạc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 đến 02/11/2025 tại tỉnh Bắc Ninh - vùng đất giàu truyền thống văn hóa và nghệ thuật dân gian, góp phần quảng bá hình ảnh địa phương, thúc đẩy giao lưu văn hóa, du lịch và lan tỏa giá trị nghệ thuật Chèo đến đông đảo công chúng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay sau lễ khai mạc, khán giả đã được thưởng thức vở diễn “Thiên mệnh” do Nhà hát Chèo Bắc Ninh biểu diễn.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+000.jpg/be329009-cc4b-5430-e307-472e00b684c6?t=1760977454211\" style=\"height: 496px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình nghệ thuật chào mừng Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/khai-mac-lien-hoan-cheo-toan-quoc-nam-2025-26318252', '', 'Dương Thuỷ', 747, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.221877', 5, 11);
INSERT INTO `sync_articles` VALUES (115, '25904813', 'Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 - 02/11/2025 tại Trung tâm...', 'Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 - 02/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh', '/documents/37632/18152201/LienhoanCheo.jpg/473aa723-5266-64c6-1aa2-c1c75e2f3c85?t=1760685215903', '<p>(BNP) - Thừa lệnh Chủ tịch UBND tỉnh, Phó Chánh Văn phòng UBND tỉnh Phạm Văn Đà vừa ký ban hành Công văn số 3700/UBND-KGVX về việc huy động khán giả xem, động viên, cổ vũ Liên hoan Chèo toàn quốc năm 2025 tại tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/18152201/LienhoanCheo.jpg/473aa723-5266-64c6-1aa2-c1c75e2f3c85?t=1760685215903\" style=\"height: 524px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc - 2025 do Bộ Văn hóa, Thể thao và Du lịch phối hợp với UBND tỉnh Bắc Ninh tổ chức, diễn ra từ ngày 20/10 đến ngày 02/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh (đường Nguyễn Thị Định, phường Bắc Giang, thành phố Bắc Ninh). Đây là hoạt động văn hóa có ý nghĩa quan trọng, góp phần tôn vinh nghệ thuật Chèo, quảng bá hình ảnh vùng đất, văn hóa, con người Bắc Ninh - Kinh Bắc đến bạn bè trong và ngoài nước, lan tỏa giá trị di sản văn hóa dân tộc tới đông đảo Nhân dân, nhất là thế hệ trẻ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để Liên hoan Chèo toàn quốc - 2025 tại tỉnh Bắc Ninh thành công tốt đẹp, để lại ấn tượng sâu sắc đối với các đơn vị nghệ thuật tham dự, Chủ tịch UBND tỉnh đề nghị các sở, ban, ngành, đoàn thể và địa phương căn cứ chức năng, nhiệm vụ huy động cán bộ, công chức, viên chức, đoàn viên, hội viên, học sinh và Nhân dân tham dự, cổ vũ các đoàn nghệ thuật tham gia Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Giáo dục và Đào tạo chỉ đạo các trường THPT, THCS, Trung tâm Giáo dục thường xuyên, Trường Phổ thông Dân tộc nội trú tỉnh tổ chức cho học sinh, giáo viên tham dự, xem biểu diễn, coi đây là hoạt động ngoại khóa có ý nghĩa giáo dục. Riêng lễ khai mạc, huy động từ 200 học sinh, giáo viên trở lên tham dự, đảm bảo an toàn và không ảnh hưởng đến hoạt động dạy học chính khóa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên đoàn Lao động tỉnh, Hội Nông dân, Hội Liên hiệp Phụ nữ, Tỉnh Đoàn, Hội Cựu Chiến binh, Hội Người cao tuổi, Hội Cựu Thanh niên xung phong và Hội Văn học Nghệ thuật tỉnh huy động mỗi buổi biểu diễn ít nhất 50 hội viên, đoàn viên tham dự, góp phần tạo không khí sôi nổi, lan tỏa phong trào văn hóa, văn nghệ trong cộng đồng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND phường Bắc Giang và phường Tân Tiến đẩy mạnh tuyên truyền, huy động cán bộ và Nhân dân tham dự, đảm bảo mỗi buổi diễn có từ 150 người trở lên đến xem biểu diễn tại Trung tâm Văn hóa - Triển lãm tỉnh. Các xã, phường khác trên địa bàn tỉnh thông tin rộng rãi để Nhân dân biết, tham dự cổ vũ Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chi tiết lịch diễn của các đơn vị tham gia Liên hoan Chèo toàn quốc - 2025:&nbsp;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/Lich+dien+1.jpg/b025ec0a-7e04-5f36-eb46-97667f54b9bd?t=1760685673097\" style=\"height: 613px; width: 900px;\" /><br />\n<img src=\"/documents/37632/18152201/Lich-2.jpg/fb84a554-1293-4cf5-4229-f989b0287c93?t=1760685784072\" style=\"height: 613px; width: 900px;\" /><br />\n&nbsp;</p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/lien-hoan-cheo-toan-quoc-nam-2025-dien-ra-tu-ngay-20-10-02-11-2025-tai-trung-tam-van-hoa-trien-lam-tinh-bac-ninh-25904813', '', 'Dương Thuỷ', 376, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.263968', 5, 11);
INSERT INTO `sync_articles` VALUES (116, '25344832', 'Hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần...', 'Hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh', '/documents/37632/18152201/20230910113755-1bch.jpg/fd7e639e-85b7-1833-1024-a5ab0d21feea?t=1760343970355', '<p>(BNP) - Chủ tịch UBND tỉnh Bắc Ninh Vương Quốc Tuấn vừa ký ban hành Quyết định số 1150/QĐ-UBND về việc cho phép hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và Liên đoàn Quần vợt tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/20230910113755-1bch.jpg/fd7e639e-85b7-1833-1024-a5ab0d21feea?t=1760343970355\" style=\"height: 507px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ (Nguồn BaoBacninh).</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh là tổ chức xã hội - nghề nghiệp, hoạt động theo Điều lệ được cấp có thẩm quyền phê duyệt, tuân thủ pháp luật và chịu sự quản lý của Sở Văn hóa, Thể thao và Du lịch cùng các cơ quan liên quan. Liên đoàn có tư cách pháp nhân, con dấu và tài khoản riêng, thực hiện các quy định về trụ sở, kinh phí, phương tiện hoạt động theo pháp luật hiện hành.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh yêu cầu, trong vòng 30 ngày kể từ ngày Quyết định có hiệu lực, hai Liên đoàn Quần vợt của Bắc Giang và Bắc Ninh (cũ) phải chuyển giao toàn bộ tài sản, tài chính, nhân sự, tổ chức và các quyền, nghĩa vụ liên quan cho Liên đoàn mới; đồng thời chấm dứt hoạt động và nộp lại con dấu cho cơ quan có thẩm quyền.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh được nhất trí về nhân sự Ban Chấp hành, Chủ tịch và các Phó Chủ tịch theo Đề án hợp nhất. Trong 60 ngày làm việc, Liên đoàn có trách nhiệm tổ chức Đại hội và báo cáo kết quả lên UBND tỉnh theo quy định.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hop-nhat-lien-oan-quan-vot-tinh-bac-giang-va-tinh-bac-ninh-cu-thanh-lien-oan-quan-vot-pickleball-tinh-bac-ninh-25344832', '', 'Dương Thuỷ', 979, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.301565', 5, 11);
INSERT INTO `sync_articles` VALUES (117, '25291381', 'Khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long', 'Khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long', '/documents/37632/18152201/23+copy.jpg/4b675ddf-a248-9986-8f6d-3e66c88b0c28?t=1760319584694', '<p>(BNP) - Ngày 12/10, tại chùa Hàm Long, UBND phường Nam Sơn tổ chức Lễ khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/23+copy.jpg/4b675ddf-a248-9986-8f6d-3e66c88b0c28?t=1760319584694\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh tặng hoa chúc mừng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự buổi lễ có đồng chí Vương Quốc Tuấn, Ủy viên dự khuyết Ban Chấp hành Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Trần Thị Hằng, Phó Chủ tịch Thường trực HĐND tỉnh; Lê Xuân Lợi, Phó Chủ tịch UBND tỉnh; Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy; Đại lão Hòa Thượng Thích Thanh Dũng, Phó Pháp chủ, Chánh Thư ký Hội đồng Chứng minh Trung ương Giáo hội Phật giáo Việt Nam, Phó Trưởng ban trị sự kiêm Trưởng Ban pháp chế Giáo hội Phật giáo tỉnh Bắc Ninh, Viện chủ Tổ đình chùa Hàm Long; các đồng chí lãnh đạo HĐND, UBND, Đoàn Đại biểu Quốc hội tỉnh; lãnh đạo các sở, ban, ngành, địa phương trong tỉnh cùng đông đảo tăng ni, phật tử và Nhân dân địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Chùa Hàm Long là một trong những ngôi cổ tự nổi tiếng của xứ Kinh Bắc, được khởi dựng từ thế kỷ XII thời nhà Lý, tọa lạc dưới chân núi Dạm thuộc thôn Thái Bảo, phường Nam Sơn. Chùa được xếp hạng di tích lịch sử văn hóa cấp quốc gia năm 1988, gắn liền với sinh hoạt văn hóa, tín ngưỡng và đời sống tinh thần của Nhân dân Bắc Ninh. Hiện nay, di tích còn lưu trữ nhiều di vật, cổ vật quý như: Tượng Phật cổ và 14 tháp mộ cổ từ thời Trần, Hậu Lê, Nguyễn; các bức hoành phi, câu đối, cửa võng cổ...</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/20.jpg/04ead231-4599-4751-4e56-89e0cc631b8e?t=1760319612701\" style=\"height: 476px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đại biểu thực hiện nghi lễ khởi động dự án.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Những năm qua, di tích chùa Hàm Long được chính quyền các cấp, Nhân dân địa phương và phật tử gần xa quan tâm, trùng tu, tôn tạo nhiều hạng mục quan trọng. Tuy nhiên, trải qua thời gian, nhiều hạng mục chính của chùa đã xuống cấp nghiêm trọng như: Tòa Tam bảo, nhà thờ Tổ và hai dãy hành lang... Một số cấu kiện gỗ, mái ngói, nền móng bị mối mọt, lún nứt; cảnh quan chưa được quy hoạch đồng bộ; khuôn viên chùa chật hẹp, không đáp ứng nhu cầu sinh hoạt tín ngưỡng của tăng ni, phật tử và du khách.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/21.jpg/aa077144-c5a0-6343-05ea-8bc0e5feada1?t=1760319634802\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Vương Quốc Tuấn và đại diện Ban Trị sự Giáo hội Phật giáo Việt Nam tỉnh Bắc Ninh thực hiện nghi lễ phạt mộc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự án tu bổ, tôn tạo chùa Hàm Long được triển khai với quy mô diện tích 1,62 ha gồm các hạng mục: Tam bảo, hai dãy hành lang, Nhà thờ tổ, Tam quan nội, Tháp sư trụ trì, Miếu Địa tạng, Nhà bia, khu vệ sinh công cộng và hệ thống sân vườn nội bộ. Trong đó, các hạng mục kiến trúc chính được phục dựng theo phong cách truyền thống, sử dụng vật liệu tự nhiên như gỗ lim, đá xanh, ngói mũi hài, gạch Bát Tràng phục chế, bảo đảm tính nguyên gốc và giá trị thẩm mỹ cổ truyền. Ngoài ra, hạng mục Miếu Địa tạng được xây mới nhằm đáp ứng nhu cầu tín ngưỡng của đông đảo phật tử gần xa đến cầu siêu, cầu an... Thời gian thi công dự án từ năm 2025 đến 2027 bằng nguồn vốn xã hội hóa.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/22.jpg/9d0bc2e9-907f-5362-b564-d6898dc0ea97?t=1760319658113\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phối cảnh tổng thể dự án tu bổ, tôn tạo di tích Quốc gia chùa Hàm Long. </span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Việc trùng tu, tôn tạo chùa Hàm Long không chỉ mang ý nghĩa bảo tồn giá trị lịch sử, kiến trúc, nghệ thuật của di tích mà còn tạo điểm nhấn trong chuỗi không gian văn hóa lịch sử vùng núi Dạm. Công trình sau khi hoàn thành sẽ trở thành điểm đến hành hương, tham quan và chiêm bái của du khách trong và ngoài nước, đồng thời là nơi giáo dục truyền thống, hướng con người đến các giá trị chân, thiện, mỹ./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/khoi-ong-du-an-trung-tu-ton-tao-di-tich-lich-su-quoc-gia-chua-ham-long-25291381', '', 'Báo và Phát thanh, Truyền hình Bắc Ninh', 634, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.345906', 5, 11);
INSERT INTO `sync_articles` VALUES (118, '23520206', 'Phó Chủ tịch UBND tỉnh Bắc Ninh Ngô Tân Phượng dự kỷ niệm Ngày Quốc khánh Hàn Quốc...', 'Phó Chủ tịch UBND tỉnh Bắc Ninh Ngô Tân Phượng dự kỷ niệm Ngày Quốc khánh Hàn Quốc tại Hà Nội', '/documents/37632/210849/z7075687939647_3288e01f220469f9fc6e9024fded1002.jpg/b18e9d27-212a-b4c8-e433-47f3f83c3924?t=1759454882452', '<p>(BNP) – Nhận lời mời của Đại sứ quán Hàn Quốc tại Việt Nam, tối ngày 02/10, Đoàn đại biểu tỉnh Bắc Ninh do đồng chí Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh làm trưởng đoàn đến tham dự Lễ kỷ niệm Ngày Quốc khánh của Hàn Quốc tại Hà Nội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687885951_34b82551b435785017d18fe2f5c38ac2.jpg/38448c45-3fa0-1cab-7e35-1144182d5a98?t=1759454767718\" style=\"width: 900px; height: 719px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Ngô Tân Phượng (ảnh phải) chúc mừng kỷ niệm Ngày Quốc khánh Hàn Quốc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự có <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Tài chính Nguyễn Văn Thắng;&nbsp;</span></span></span>Thượng tướng Phùng Sĩ Tấn, Phó Tổng Tham mưu trưởng Quân đội nhân dân Việt Nam; cùng đại diện lãnh đạo các Bộ, ban, ngành Trung ương và địa phương của Việt Nam, cùng đại diện đoàn ngoại giao nước ngoài tại Việt Nam.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687939647_3288e01f220469f9fc6e9024fded1002.jpg/b18e9d27-212a-b4c8-e433-47f3f83c3924?t=1759454882452\" style=\"width: 900px; height: 583px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Choi Young Sam và các khách mời tại buổi tiệc. Phó Chủ tịch UBND tỉnh Ngô Tân Phượng (thứ 4 từ phải qua) tham dự chiêu đãi.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại tiệc chiêu đãi, Đại sứ Hàn Quốc Choi Young Sam bày tỏ vui mừng trước sự phát triển của mối quan hệ Hàn Quốc - Việt Nam trong những năm qua, nhất là sau khi hai nước nâng cấp quan hệ lên Đối tác chiến lược toàn diện năm 2022; đồng thời cho rằng tiềm năng hợp tác giữa hai nước vẫn rộng mở.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Choi Young Sam bày tỏ tin tưởng, với sự nhất trí của lãnh đạo cấp cao hai nước, Việt Nam và Hàn Quốc sẽ tiếp tục hợp tác, hướng tới một bước tiến mới trong quan hệ song phương.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687829774_cacf592754d1095564ee675616058d24.jpg/38b00ed0-cde4-7fa5-cc0b-cc75b14b8e76?t=1759455073865\" style=\"width: 900px; height: 824px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Ngô Tân Phượng tặng hoa chúc mừng Đại sứ Hàn Quốc Choi Young Sam.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Tài chính Nguyễn Văn Thắng gửi lời chúc mừng nồng nhiệt tới Chính phủ và nhân dân Hàn Quốc nhân Ngày Quốc khánh; khẳng định Việt Nam nhất quán coi trọng quan hệ với Hàn Quốc, sẵn sàng hợp tác chặt chẽ với Hàn Quốc, nhằm thúc đẩy mối quan hệ Đối tác chiến lược toàn diện phát triển thực chất, hiệu quả và lâu dài, phù hợp với nguyện vọng của nhân dân hai nước, góp phần duy trì môi trường hòa bình, ổn định, hợp tác và phát triển ở khu vực cũng như trên thế giới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687801100_82a0f7ad0df95f05f7f21c8e921b0258.jpg/e12ecd8b-046b-ede4-bc2a-c04705779acf?t=1759455174255\" style=\"width: 900px; height: 598px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu tham dự Lễ kỷ niệm Ngày Quốc khánh Hàn Quốc.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Luỹ kế đến tháng 9/2025, Hàn Quốc có 1.139 dự án đầu tư tại tỉnh Bắc Ninh, tổng vốn đầu tư sau điều chỉnh đạt khoảng 20 tỷ USD (chiếm khoảng 43.5% tổng vốn đầu tư nước ngoài trên địa bàn tỉnh), là quốc gia có số vốn đầu tư cao nhất vào tỉnh. Các doanh nghiệp Hàn Quốc hoạt động hiệu quả và ổn định, tạo việc làm cho khoảng 90.000 lao động và thu hút nhiều lao động đến từ các tỉnh thành khác, đóng góp tích cực đối với phát triển kinh tế - xã hội của tỉnh. Các doanh nghiệp điển hình của Hàn Quốc đầu tư vào Bắc Ninh thời gian qua đều có sự đóng góp vào sự phát triển của địa phương như: Tổ hợp Samsung, Intops, Hanwha Techwin, Amkor, Hana Micron, Hyosung... Ngoài ra,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"background:white\"><span style=\"color:#001d35\">Bắc Ninh không chỉ là quê hương của vua Lý, n<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">ơi đây còn là điểm đến của Lý Xương Căn (hậu duệ đời thứ 31 của Lý Thái Tổ) và nhiều hậu duệ khác từ Hàn Quốc về Việt Nam tìm lại nguồn cội&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"background:white\"><span style=\"color:#001d35\">để tưởng nhớ tổ tiên.</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-bac-ninh-ngo-tan-phuong-du-ky-niem-ngay-quoc-khanh-han-quoc-tai-ha-noi-23520206', '', 'BNP', 383, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.382923', 5, 11);
INSERT INTO `sync_articles` VALUES (119, '23104204', 'Gặp mặt Phóng viên thông tin về Đại hội Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ...', 'Gặp mặt Phóng viên thông tin về Đại hội Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', '/documents/37632/200616/IMG_7426.jpg/fce97ccb-b58c-1ac1-b727-e620ad88c9dd?t=1759147822954', '<p>(BNP) - Chiều 29/9, ngay sau phiên trù bị Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030 đã diễn ra Chương trình gặp mặt Phóng viên thông tin về Đại hội. Các đồng chí: Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh; Nguyễn Đình Lợi, Ủy viên Ban...', '<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><em><img src=\"/documents/37632/200616/IMG_7426.jpg/fce97ccb-b58c-1ac1-b727-e620ad88c9dd?t=1759147822954\" style=\"height: 600px; width: 900px;\" /></em></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh (ảnh giữa); Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy <span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nguyễn Đình Lợi&nbsp;</span></span></span></span>(ảnh phải); Giám đốc Sở Văn hóa, Thể thao và Du lịch&nbsp;<span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bùi Thị Thu Thủy</span></span></span></span>.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tham dự có đai diện lãnh đạo, phóng viên các cơ quan báo chí - truyền thông của Trung ương và tỉnh đưa tin về Đại hội. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại buổi gặp mặt, Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn thông tin đến các Phóng viên về kết quả phiên thứ Nhất, Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030 diễn ra vào chiều 29/9 tại Trung tâm Hội nghị tỉnh. Tại phiên thứ Nhất, Đại hội đã đã hoàn thành toàn bộ nội dung đề ra trong không khí đoàn kết, dân chủ, trách nhiệm. Đại hội đã bầu Đoàn Chủ tịch, Đoàn Thư ký, Ban Thẩm tra tư cách đại biểu; thông qua Chương trình, Nội quy, Quy chế làm việc và thành lập 08 Tổ thảo luận. Các Tổ đã làm việc sôi nổi, thẳng thắn, trách nhiệm, đóng góp nhiều ý kiến tâm huyết vào các dự thảo Văn kiện của Trung ương và của tỉnh.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7401.jpg/cf725c39-7a58-ed8e-81c5-d6c3e088f4de?t=1759147871714\" style=\"height: 606px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn thông tin kết quả phiên thứ Nhất, Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I.</span></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Sáng ngày 30/9/2025, Đại hội tiến hành phiên khai mạc. Đồng chí Nguyễn Duy Ngọc, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ nhiệm UBKT Trung ương sẽ thay mặt Bộ Chính trị, Ban Bí thư dự và phát biểu chỉ đạo Đại hội.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Đại hội cũng sẽ thực hiện một số nội dung trọng tâm: Thông qua và thảo luận về các văn kiện: Báo cáo chính trị; Báo cáo kiểm điểm sự lãnh đạo, chỉ đạo của Ban Chấp hành Đảng bộ tỉnh nhiệm kỳ 2020 - 2025; Chương trình hành động thực hiện Nghị quyết Đại hội; công bố và trao các Quyết định chỉ định Ban Chấp hành, Ban Thường vụ, Bí thư, Phó Bí thư Tỉnh ủy; Ủy ban Kiểm tra, Chủ nhiệm, Phó Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy, nhiệm kỳ 2025 - 2030; Quyết định chỉ định đại biểu dự Đại hội đại biểu toàn quốc lần thứ XIV của Đảng; thông qua dự thảo Nghị quyết Đại hội và bế mạc Đại hội vào chiều ngày 30/9/2025.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7455.jpg/4b29b0a4-6bb3-2012-ac92-8e885510f34a?t=1759147915543\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy Nguyễn Đình Lợi phát biểu tại buổi gặp mặt.</span></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Để góp phần vào thành công chung của Đại hội, Phó Chủ tịch Thường trực UBND tỉnh đề nghị các phóng viên báo chí của Trung ương, tỉnh tập trung tuyên truyền làm nổi bật ý nghĩa lịch sử và tầm quan trọng của Đại hội lần thứ I - dấu mốc mở ra khát vọng phát triển mới, thể hiện tầm nhìn chiến lược của Ban Chấp hành Đảng bộ tỉnh và niềm tin, kỳ vọng của Nhân dân vào tương lai Bắc Ninh.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tuyên truyền làm nổi bật tầm vóc, phương châm, mục tiêu của Đại hội “Đoàn kết - Dân chủ - Kỷ cương - Sáng tạo - Phát triển”; nhấn mạnh quyết tâm chính trị, thông qua chủ đề Đại hội: “Xây dựng Đảng và hệ thống chính trị tỉnh - gọn - mạnh, hoạt động hiệu năng, hiệu lực, hiệu quả; phát huy tiềm năng, lợi thế, bản sắc văn hóa Kinh Bắc; đoàn kết, tự lực, tự cường, tự tin xây dựng tỉnh Bắc Ninh phát triển nhanh, toàn diện, bền vững, trở thành thành phố trực thuộc Trung ương trước năm 2030”.</span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7429.jpg/868ee109-88eb-c3e6-3ebf-23e93bd713ce?t=1759147946073\" style=\"height: 603px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhà báo Phùng Đô, Báo Xây dựng.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cùng với đó, phản ánh đậm nét quá trình tổ chức Đại hội, sự thành công của Đại hội và nhất là phản ánh tình cảm, sự tin tưởng, khí thế phấn khởi, quyết tâm của cán bộ, đảng viên, các tầng lớp nhân dân hướng về Đại hội, ra sức thi đua lập thành tích chào mừng thành công của Đại hội và sớm đưa Nghị quyết của Đại hội vào cuộc sống. Đồng thời, tích cực, chủ động đấu tranh, phản bác thông tin sai lệch, xuyên tạc, góp phần củng cố niềm tin của nhân dân với Đảng, Nhà nước và sự lãnh đạo của Ban Chấp hành Đảng bộ tỉnh khóa I, nhiệm kỳ 2025-2030.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại buổi gặp mặt, các phóng viên báo chí của Trung ương, tỉnh đánh giá cao công tác chuẩn bị, tổ chức Đại hội của Ban Chấp hành Đảng bộ tỉnh, nhất là tạo điều kiện thuận lợi nhất để các phóng viên tác nghiệp, đưa tin về Đại hội. Đồng thời, đề nghị tỉnh làm rõ <span style=\"background:white\"><span style=\"color:#333333\">hơn định hướng lớn đưa ra của tỉnh Bắc Ninh về 3 khâu đột phá trong nhiệm kỳ 2025 - 2030, đặc biệt là đột phá về hạ tầng giao thông và công nghệ thông tin; phát triển hạ tầng tại các khu công nghiệp nhằm giảm thiểu tình trạng ùng tắc giao thông hiện nay; quy hoạch, phát triển đường sắt của tỉnh…</span></span></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200616/IMG_7441.jpg/049365f0-64ca-0485-9bf5-bfcba9d8c8e0?t=1759147993378\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"background:white\">Đại diện </span>lãnh đạo, phóng viên các cơ quan báo chí - truyền thông của Trung ương và tỉnh tham dự buổi gặp mặt.<span style=\"background:white\"></span></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"background:white\"><span style=\"color:#333333\">Các ý kiến của phóng viên được đồng chí </span></span>Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh và đồng chí Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy<span style=\"background:white\"><span style=\"color:#333333\"> trực tiếp trao đổi, làm rõ.</span></span> Đồng thời, mong muốn tiếp tục nhận được sự phối hợp, đồng hành của các cơ quan báo chí, phóng viên, nhà báo trong và ngoài tỉnh, góp phần lan tỏa tinh thần Đại hội, đưa Nghị quyết vào cuộc sống, xây dựng tỉnh Bắc Ninh ngày càng phát triển giàu đẹp, văn minh.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/gap-mat-phong-vien-thong-tin-ve-ai-hoi-ang-bo-tinh-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-23104204', '', 'Hữu Thắng', 797, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.420695', 5, 11);
INSERT INTO `sync_articles` VALUES (120, '22833504', 'Bắc Ninh FC khởi tranh với Khatoco Khánh Hòa tại Giải bóng đá hạng Nhất Quốc gia 2025...', 'Bắc Ninh FC khởi tranh với Khatoco Khánh Hòa tại Giải bóng đá hạng Nhất Quốc gia 2025 - 2026 trên Sân vận động Việt Yên (Bắc Ninh)', '/documents/37632/18152201/b7.jpg/77e15f4c-e61c-d3f8-a3bf-73572aecbfb3?t=1758972160429', '<p>(BNP) - Chiều 27/9, tại Sân vận động Việt Yên, Câu lạc bộ bóng đá Bắc Ninh (Bắc Ninh FC) đã có trận đấu với Câu lạc bộ Khatoco Khánh Hòa. Đây là trận đấu tại vòng 2, trong khuôn khổ Giải bóng đá hạng Nhất Quốc gia 2025 - 2026.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/10721208/b2+%283%29.jpg/4f4002ef-c837-047b-9611-677fa34e3858?t=1758971495784\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các cầu thủ&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh FC ra sân thi đấu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự và cổ vũ&nbsp;trận đấu có đồng chí&nbsp;Vương Quốc Tuấn, Ủy viên dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; các đồng chí Ủy&nbsp;viên Ban Thường vụ Tỉnh ủy: Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh; Phạm Văn Thịnh, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn đại biểu Quốc hội tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Giải bóng đá hạng Nhất Quốc gia 2025 - 2026 do Liên đoàn Bóng đá Việt Nam tổ chức, chính thức khởi tranh từ ngày 19/9, với sự tham gia của 12 đội bóng chuyên nghiệp trong cả nước; thi đấu theo thể thức vòng tròn 2 lượt tính điểm sân nhà -&nbsp;sân khách. Giải đấu có tổng cộng 22 vòng với 132 trận đấu, thi đấu theo thể thức đấu bốc thăm chia cặp đấu loại trực tiếp từng vòng.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b7.jpg/77e15f4c-e61c-d3f8-a3bf-73572aecbfb3?t=1758972160429\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các cầu thủ Bắc Ninh FC thực hiện nghi thức chào cờ, hát Quốc ca trước khi trận đấu diễn ra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Câu lạc bộ bóng đá Bắc Ninh (Bắc Ninh FC) lần đầu tiên góp mặt tại giải song đã nhận được sự quan tâm, cổ vũ rất lớn từ người hâm mộ. Bắc Ninh FC sẽ có 11 trận trên sân vận động Việt Yên (phường Việt Yên). </span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b3.jpg/78d9433b-c537-c985-74a4-9d94f736c55a?t=1758971767454\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Trọng tài điều khiển trận đấu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Trận đấu tại vòng 2 giữa Bắc Ninh FC với Khatoco Khánh Hòa trong chiều nay, được đánh giá là trận đấu đầy kịch tính, chất lượng, thể hiện sự chuyên nghiệp của các cầu thủ, đáp ứng người hâm mộ bóng đá tỉnh Bắc Ninh. </span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Kết quả giành chiến <span style=\"color:#000000;\">thắng 1-0</span><span style=\"color:#000000;\">,</span><span style=\"color:red\"> </span>các cầu Bắc Ninh FC đã thể hiện thi đấu hết mình trước đội <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Khatoco Khánh Hòa</span></span></span></span>; là cơ hội, động lực để&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Bắc Ninh FC</span></span></span></span> hướng tới những chiến thắng tiếp theo và mục tiêu thăng hạng lên hạng V- League trong một ngày không xa.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b5.jpg/823504ec-d1a4-4c17-8bc4-ae7bbfa099bc?t=1758971839612\" style=\"height: 571px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Sự&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">chuyên nghiệp của các cầu thủ, đáp ứng người hâm mộ bóng đá tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Được biết, Sân vận động Việt Yên là công trình thể thao mới, tổng diện tích hơn 8.000m² với 7.500 chỗ ngồi, sân có mặt cỏ tự nhiên, hạ tầng đồng bộ, hiện đại. Sở Văn hóa, Thể thao và Du lịch phối hợp với UBND phường Việt Yên, Công ty Cổ phần bóng đá Bắc Ninh rà soát toàn bộ cơ sở vật chất, trang thiết bị, kỹ thuật phục vụ chuyên môn, phòng chức năng của sân bảo đảm đáp ứng tốt các nhiệm vụ tổ chức giải. Để bảo đảm an ninh, an toàn cho các trận đấu, Công an tỉnh đã lên phương án cụ thể, tính toán chi tiết cho từng tình huống có thể phát sinh, bố trí lực lượng sẵn sàng thực hiện nhiệm vụ. </span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b1.jpg/36a4d65b-b6a5-638e-ea1b-d703b98bb243?t=1758971962481\" style=\"height: 559px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Người hâm mộ xếp hàng tại quầy soát vé để xem trận đấu.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Các trận đấu của Bắc Ninh FC trên Sân vận động Việt Yên sẽ mở cửa tự do phục vụ khán giả, người hâm mộ; hứa hẹn sẽ là ngày hội bóng đá chung của người hâm mộ thể thao trong tỉnh. Qua đó, tiếp tục quảng bá hình ảnh tỉnh Bắc Ninh năng động, giàu bản sắc tới bạn bè trong nước và quốc tế.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b6.jpg/52e84e57-e367-af2b-fd34-a0881ac0d443?t=1758972078456\" style=\"height: 593px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Cổ động viên trên Sân vận động Việt Yên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-fc-khoi-tranh-voi-khatoco-khanh-hoa-tai-giai-bong-a-hang-nhat-quoc-gia-2025-2026-tren-san-van-ong-viet-yen-bac-ninh-22833504', '', 'Nguyễn Miền', 1708, 'Văn hóa', 5, '', '38762', '{}', '2025-11-01 07:12:49.455089', 5, 11);
INSERT INTO `sync_articles` VALUES (121, '30184601', 'Chính sách mới có hiệu lực từ tháng 11/2025', 'Chính sách mới có hiệu lực từ tháng 11/2025', 'https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/29/screenshot20251029093601chrome-17617054706081696275381.jpg', '<p>(BNP) - Trong tháng 11/2025, nhiều chính sách mới có hiệu lực liên quan đến tài chính, bảo hiểm, ngân hàng như: siết chặt xử lý chậm đóng, trốn đóng bảo hiểm xã hội bắt buộc; quy định về thanh toán không tiền mặt; tăng cường quản lý phòng, chống rửa tiền trong lĩnh vực ngân hàng; ngân hàng...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/29/screenshot20251029093601chrome-17617054706081696275381.jpg\" style=\"width: 900px; height: 664px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Các trường hợp không bị coi là trốn đóng BHXH bắt buộc</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 16/10/2025, Chính phủ ban hành Nghị định số 274/2025/NĐ-CP quy định chi tiết một số điều của Luật bảo hiểm xã hội về chậm đóng, trốn đóng bảo hiểm xã hội bắt buộc, bảo hiểm thất nghiệp; khiếu nại, tố cáo về bảo hiểm xã hội, có hiệu lực từ 30/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các trường hợp không bị coi là trốn đóng bảo hiểm xã hội bắt buộc, bảo hiểm thất nghiệp khi có một trong các lý do theo công bố của cơ quan có thẩm quyền về phòng, tránh thiên tai, tình trạng khẩn cấp, phòng thủ dân sự và phòng, chống dịch bệnh là:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Bão, lũ, ngập lụt, động đất, hỏa hoạn lớn, hạn hán kéo dài và các loại thiên tai khác ảnh hưởng trực tiếp và nghiêm trọng đến hoạt động sản xuất, kinh doanh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Dịch bệnh nguy hiểm được cơ quan nhà nước có thẩm quyền công bố, gây ảnh hưởng nghiêm trọng đến hoạt động sản xuất, kinh doanh và khả năng tài chính của cơ quan, tổ chức, người sử dụng lao động.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Tình trạng khẩn cấp theo quy định của pháp luật gây ảnh hưởng đột xuất, bất ngờ đến hoạt động của cơ quan, tổ chức, người sử dụng lao động.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Các sự kiện bất khả kháng khác theo quy định của pháp luật dân sự.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Tiêu chí xác định các dân tộc còn gặp nhiều khó khăn, có khó khăn đặc thù</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ ban hành Nghị định số 255/2025/NĐ-CP ngày 29/9/2025 xác định các dân tộc còn gặp nhiều khó khăn, có khó khăn đặc thù giai đoạn 2026-2030. Nghị định này có hiệu lực từ ngày 15/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Dân tộc còn gặp nhiều khó khăn là dân tộc có tỷ lệ nghèo đa chiều lớn hơn tỷ lệ nghèo đa chiều dân tộc thiểu số chung cả nước.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Dân tộc có khó khăn đặc thù là dân tộc có dân số trong phạm vi toàn quốc dưới 10.000 người theo dữ liệu quản lý dân cư và đáp ứng ít nhất 01 trong 02 tiêu chí sau:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">+ Có tỷ lệ nghèo đa chiều lớn hơn tỷ lệ nghèo đa chiều dân tộc thiểu số chung cả nước;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">+ Có dân số trong phạm vi toàn quốc theo dữ liệu quản lý dân cư giảm so với dân số trong phạm vi toàn quốc theo kết quả Tổng điều tra dân số và nhà ở năm 2019.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Không phải xuất trình giấy tờ có trên VNeID</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Nghị định 280/2025 có hiệu lực từ 1/11, trường hợp người dân đề nghị chứng thực mà cơ quan Nhà nước có thể khai thác thông tin, giấy tờ từ Cơ sở dữ liệu quốc gia về dân cư hoặc các cơ sở dữ liệu khác thì phải sử dụng thông tin đó, thay vì yêu cầu người dân xuất trình bản chính, bản sao từ sổ gốc hoặc bản sao có chứng thực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ quy định các chủ thể có thẩm quyền chứng thực gồm: chủ tịch UBND xã, phường, đặc khu; người được ủy quyền hoặc phân công làm nhiệm vụ chứng thực; công chứng viên của phòng công chứng, văn phòng công chứng; viên chức ngoại giao, viên chức lãnh sự của Cơ quan đại diện ngoại giao, Cơ quan đại diện lãnh sự và cơ quan khác được ủy quyền thực hiện chức năng lãnh sự của Việt Nam ở nước ngoài.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Như vậy, so với quy định cũ, diện được phép thực hiện chứng thực được mở rộng thêm người được ủy quyền hoặc phân công làm nhiệm vụ chứng thực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch UBND cấp xã có quyền chứng thực bản sao từ bản chính các giấy tờ, văn bản do cơ quan, tổ chức có thẩm quyền của Việt Nam; cơ quan, tổ chức có thẩm quyền của nước ngoài; cơ quan, tổ chức có thẩm quyền của Việt Nam liên kết với cơ quan, tổ chức có thẩm quyền của nước ngoài cấp hoặc chứng nhận. Ngoài ra, có thể chứng thực chữ ký trong các giấy tờ, văn bản; chữ ký của người dịch trong giấy tờ, văn bản tiếng nước ngoài dịch sang tiếng Việt hoặc ngược lại.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch xã cũng được chứng thực các giao dịch liên quan đến tài sản là bất động sản; giao dịch về quyền sử dụng đất; di chúc; văn bản từ chối nhận di sản; văn bản phân chia di sản là tài sản.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Chuyển hình phạt tử hình thành tù chung thân</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghị quyết 03/2025 của Hội đồng Thẩm phán có hiệu lực từ 1/11 quy định người bị kết án tử hình trước ngày 1/7/2025 mà chưa thi hành án sẽ được chuyển hình phạt sang tù chung thân nếu thuộc một số trường hợp: Người mắc bệnh ung thư giai đoạn cuối hoặc bị kết án tử hình về một trong 8 tội đã được sửa đổi, bỏ án tử hình trong Bộ luật Hình sự sửa đổi được Quốc hội thông qua tại kỳ họp 9 giữa năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các tội này gồm: hoạt động nhằm lật đổ chính quyền nhân dân; gián điệp; phá hoại cơ sở vật chất - kỹ thuật của nước Cộng hòa xã hội chủ nghĩa Việt Nam; sản xuất, buôn bán hàng giả là thuốc chữa bệnh, thuốc phòng bệnh; vận chuyển trái phép chất ma túy; tham ô tài sản; nhận hối lộ; và phá hoại hòa bình, gây chiến tranh xâm lược.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngoài ra, người bị kết án tử hình về tội sản xuất hoặc mua bán trái phép chất ma túy cũng có thể được chuyển sang hình phạt tù chung thân nếu đáp ứng điều kiện về khối lượng, thể tích ma túy cụ thể và không có từ hai tình tiết tăng nặng trở lên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Xếp hạng tổ chức tín dụng theo tiêu chuẩn mới </b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 10/9/2025, Ngân hàng Nhà nước Việt Nam ban hành Thông tư số 21/2025/TT-NHNN quy định về xếp hạng tổ chức tín dụng và chi nhánh ngân hàng nước ngoài, có hiệu lực từ ngày 1/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mục tiêu nhằm đánh giá toàn diện sức khỏe tài chính của tổ chức tín dụng, tăng tính minh bạch trong hoạt động ngân hàng, đồng thời tạo cơ sở để cơ quan quản lý có biện pháp giám sát phù hợp. Việc xếp hạng được thực hiện định kỳ hằng năm, căn cứ trên các tiêu chí về an toàn vốn, chất lượng tài sản, năng lực quản trị, kết quả kinh doanh và khả năng thanh khoản.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả xếp hạng được chia thành nhiều mức, là căn cứ để xem xét cấp phép mở rộng mạng lưới, triển khai sản phẩm dịch vụ mới và xác định mức độ rủi ro trong quản lý tín dụng. Các ngân hàng thương mại, đặc biệt là chi nhánh ngân hàng nước ngoài, được yêu cầu chuẩn bị hồ sơ và rà soát lại hệ thống quản trị, kiểm soát nội bộ để đáp ứng tiêu chí mới. Quy định này được kỳ vọng góp phần nâng cao chất lượng hệ thống ngân hàng và củng cố niềm tin thị trường tài chính.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Chuyển tiền từ 500 triệu đồng trở lên phải báo cáo Cục Phòng, chống rửa tiền</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể, Thông tư quy định chế độ báo cáo giao dịch chuyển tiền điện tử đến Cục Phòng, chống rửa tiền bằng dữ liệu điện tử gồm:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Giao dịch chuyển tiền điện tử trong nước: Các giao dịch có giá trị từ 500 triệu đồng đồng trở lên hoặc bằng ngoại tệ có giá trị tương đương mà tất cả các tổ chức tài chính tham gia giao dịch chuyển tiền điện tử cùng ở Việt Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Giao dịch chuyển tiền điện tử quốc tế: Các giao dịch chuyển tiền điện tử mà có ít nhất một tổ chức tài chính tham gia ở ngoài Việt Nam thực hiện ở các quốc gia, vùng lãnh thổ ngoài VIệt Nam có giá trị từ 1.000 đô la Mỹ trở lên hoặc tương đương bằng ngoại tệ khác.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, nếu đối tượng báo cáo là tổ chức tài chính trung gian trong giao dịch chuyển tiền điện tử không phải thực hiện báo cáo như trên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Quy định về cung ứng dịch vụ thanh toán không dùng tiền mặt </b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 30/9/2025, Thống đốc Ngân hàng Nhà nước Việt Nam ký ban hành Thông tư 30/2025/TT-NHNN ngày 30/9/2025 sửa đổi, bổ sung một số điều của Thông tư 15/2024/TT-NHNN quy định về cung ứng dịch vụ thanh toán không dùng tiền mặt. Thông tư 30/2025/TT-NHNN có hiệu lực từ ngày 18/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, Thông tư 30/2025/TT-NHNN sửa đổi, bổ sung khoản 10 Điều 3 Thông tư 15/2024/TT-NHNN quy định giấy tờ tùy thân dùng trong dịch vụ thanh toán không dùng tiền mặt bao gồm:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đối với cá nhân là công dân Việt Nam: thẻ căn cước công dân, thẻ căn cước hoặc căn cước điện tử.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đối với cá nhân là người gốc Việt Nam chưa xác định được quốc tịch: giấy chứng nhận căn cước.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đối với người nước ngoài cư trú tại Việt Nam: hộ chiếu hoặc giấy tờ khác chứng minh được nhân thân do cơ quan có thẩm quyền nước ngoài cấp kèm theo thị thực nhập cảnh hoặc giấy tờ có giá trị thay thị thực hoặc giấy tờ chứng minh được miễn thị thực nhập cảnh; hoặc danh tính điện tử (thông qua việc truy cập vào tài khoản định danh điện tử mức độ 02) (nếu có).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lưu ý: Giấy tờ tùy thân dùng trong dịch vụ thanh toán không dùng tiền mặt phải còn hiệu lực và thời hạn sử dụng trong quá trình sử dụng dịch vụ thanh toán.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ngân hàng thương mại được giao nhận vàng miếng</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Thông tư 33/2025/TT-NHNN của Ngân hàng Nhà nước Việt Nam ban hành thì từ ngày 15/11, tổ chức tín dụng được phép nhận và giao vàng miếng cho khách hàng, thực hiện theo từng miếng, thay vì chỉ có Ngân hàng Nhà nước thực hiện như trước đây.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thông tư cũng quy định cụ thể tiêu chuẩn phân loại vàng gồm 3 nhóm gồm: vàng trang sức - mỹ nghệ (hàm lượng từ 8 kara trở lên), vàng miếng (có ký mã hiệu, thông số, tiêu chuẩn rõ ràng) và vàng nguyên liệu (dưới dạng thỏi, hạt, miếng). Bao bì vàng miếng phải được chống giả theo quy chuẩn của ngân hàng thương mại hoặc doanh nghiệp được phép sản xuất vàng miếng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đáng chú ý, việc đóng gói và niêm phong vàng được quy định chặt chẽ hơn: vàng miếng cùng chất lượng được đóng thành lô 100 hoặc bội số của 100 miếng (tối đa 500 miếng), vàng nguyên liệu đóng thành lô 5 hoặc bội số của 5 thỏi (tối đa 25 thỏi), trong hộp kim loại không gỉ, có niêm phong và ghi rõ thông tin kiểm nhận.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo thông tư này thì các ngân hàng thương mại được phép giao nhận vàng miếng với khách hàng kèm theo biên bản giao nhận, hợp đồng hoặc văn bản xác nhận giao dịch. Việc này nhằm bảo đảm tính minh bạch, truy xuất nguồn gốc và chất lượng từng sản phẩm vàng miếng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ban hành hệ thống ngành kinh tế Việt Nam mới</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ vừa ký Quyết định số 36/2025/QĐ-TTg ngày 29/9/2025, ban hành Hệ thống ngành kinh tế Việt Nam, có hiệu lực từ ngày 15/11/2025, thay thế Quyết định số 27/2018/QĐ-TTg.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hệ thống ngành mới cập nhật, chuẩn hóa danh mục mã ngành phù hợp với xu hướng chuyển đổi số, phát triển kinh tế xanh và hội nhập quốc tế. Quyết định quy định rõ nguyên tắc sử dụng mã ngành trong đăng ký doanh nghiệp, đăng ký đầu tư, thống kê nhà nước và các cơ sở dữ liệu hành chính.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, các doanh nghiệp cần rà soát, cập nhật lại mã ngành đăng ký kinh doanh để bảo đảm thống nhất, tránh sai lệch trong thủ tục hành chính và báo cáo thống kê. Việc áp dụng hệ thống mới được kỳ vọng giúp đồng bộ hóa dữ liệu kinh tế quốc gia và nâng cao hiệu quả hoạch định chính sách.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thủ tục xóa đăng ký quốc tịch tàu bay theo đề nghị của người được chỉ định tại văn bản IDERA</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 15/9/2025, Chính phủ ban hành Nghị định 246/2025/NĐ-CP sửa đổi, bổ sung Nghị định số 68/2015/NĐ-CP ngày 18/8/2015 của Chính phủ quy định đăng ký quốc tịch và đăng ký các quyền đối với tàu bay đã được sửa đổi, bổ sung bởi Nghị định số 64/2022/NĐ-CP ngày 15/9/2022 của Chính phủ sửa đổi, bổ sung một số điều của các nghị định quy định liên quan đến hoạt động kinh doanh trong lĩnh vực hàng không dân dụng. Nghị định này có hiệu lực từ ngày 1/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, Nghị định 246/2025/NĐ-CP bổ sung khoản 3 vào Điều 8 Nghị định 68/2015/NĐ-CP quy định về các trường hợp xóa đăng ký quốc tịch tàu bay.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghị định 246/2025/NĐ-CP quy định: trường hợp văn bản IDERA đã được đăng ký theo quy định tại Nghị định này thì chỉ người được chỉ định tại văn bản IDERA có quyền đề nghị xóa đăng ký quốc tịch tàu bay.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, Nghị định 246/2025/NĐ-CP cũng bổ sung một số quy định về thủ tục xóa đăng ký quốc tịch tàu bay theo đề nghị của người được chỉ định tại văn bản IDERA vào Điều 9 Nghị định 68/2015/NĐ-CP…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Văn bản IDERA (Irrevocable De-registration and Export Request Authorisation) là văn bản được ban hành theo quy định của Công ước Cape Town, trong đó chỉ rõ người có quyền yêu cầu xóa đăng ký hoặc xuất khẩu tàu bay.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/chinh-sach-moi-co-hieu-luc-tu-thang-11-2025-30184601', '', 'BNP', 939, 'Xã hội', 6, 'true', '38762', '{}', '2025-11-01 07:12:49.761037', 6, 11);
INSERT INTO `sync_articles` VALUES (122, '29966801', 'Bắc Ninh triển khai kế hoạch thực hiện giải pháp IMO cho sản xuất vải thiều', 'Bắc Ninh triển khai kế hoạch thực hiện giải pháp IMO cho sản xuất vải thiều', '/documents/37632/23288501/3+%281%29.jpg/22374664-3ff2-d51b-5575-5f40ec51a675?t=1761895050100', '<p>(BNP) - Sở Khoa học và Công nghệ Bắc Ninh vừa ban hành Kế hoạch triển khai thí điểm mô hình thực hiện giải pháp IMO cho sản xuất vải thiều tại tỉnh.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288501/3+%281%29.jpg/22374664-3ff2-d51b-5575-5f40ec51a675?t=1761895050100\" style=\"height: 521px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh họa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch triển khai thực hiện giải pháp IMO cho sản xuất vải thiều nhằm nâng cao năng lực cho cán bộ kỹ thuật và nông dân về quy trình ứng dụng chế phẩm sinh học IMO trong sản xuất vải thiều tại tỉnh Bắc Ninh. Qua đó, xây dựng mô hình thí điểm áp dụng công nghệ sinh học IMO trong canh tác vải thiều, giảm thiểu việc sử dụng thuốc bảo vệ thực vật hóa học, góp phần nâng cao chất lượng và giá trị sản phẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đơn vị chủ trì lựa chọn diện tích điểm với quy mô 5 ha tại 03 hộ dân trên địa bàn xã Lục Ngạn và 02 hộ xã Phúc Hòa (1ha/hộ dân). Các hộ dân được lựa chọn phải đáp ứng yêu cầu có diện tích sản xuất vải thiều từ 01ha trở lên, cây vải thiều đang thời kỳ kinh doanh. Có nhu cầu áp dụng công nghệ vi sinh trong sản xuất vải thiều, theo hướng hạn chế sử dụng phân bón hóa học và thuốc bảo vệ thực vật. Cam kết thực hiện đúng theo quy trình hướng dẫn của chuyên gia.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những diện tích chọn điểm áp dụng công nghệ sinh học IMO được sử dụng men vi sinh giống công nghiệp đa chủng, men vi sinh y tế, men rượu để lên men các nguyên liệu tạo men vi sinh IMO. Kiểm tra tính an toàn của các loại men vi sinh IMO sản xuất được và phân tích chất lượng sản phẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Khoa học và Công nghệ triển khai dùng thử sản phẩm men IMO trên các giai đoạn của chu kỳ sản xuất cây vải thiều từ tháng 11/2025 - tháng 6/2025. Đồng thời theo dõi, đánh giá hiệu quả kỹ thuật, kinh tế, mức độ kiểm soát sâu bệnh và phản hồi từ nông dân.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quá trình triển khai mô hình được ghi chép, tổng hợp, đánh giá hiệu quả, làm cơ sở khoa học để UBND tỉnh xem xét, chỉ đạo nhân rộng việc ứng dụng công nghệ sinh học trong sản xuất nông nghiệp theo hướng an toàn và bền vững./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-ke-hoach-thuc-hien-giai-phap-imo-cho-san-xuat-vai-thieu-29966801', '', 'Nguyễn Miền', 42, 'Xã hội', 6, 'true', '38762', '{}', '2025-11-01 07:12:49.813581', 6, 11);
INSERT INTO `sync_articles` VALUES (123, '29928666', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 - 31/10/2025', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 - 31/10/2025', '/documents/37632/23555751/ghep-anh-31-10.png/72353e82-cc2a-fd04-1274-42f7a359b046?t=1761893921635', '<p>(BNP) - Đoàn công tác Quân khu 1 thăm, chúc mừng Đảng bộ tỉnh Bắc Ninh; Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh; Trường Đại học Limoges (Cộng hòa Pháp) làm việc tại Bắc Ninh… là những hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 -...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200616/IMG_9135+%281%29.jpg/7625a32a-3d16-3260-c2a0-e15f43e6e79d?t=1761654608975\" style=\"width: 900px; height: 590px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều tối ngày 28/10, tại trụ sở Tỉnh ủy, đồng chí Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy có buổi tiếp và làm việc với Đoàn công tác do Thiếu tướng Trương Mạnh Dũng, Tư lệnh Quân khu 1 dẫn đầu về thăm, chúc mừng Đảng bộ tỉnh Bắc Ninh vừa tổ chức thành công Đại hội đại biểu Đảng bộ tỉnh lần thứ I, nhiệm kỳ 2025 - 2030. Tham gia Đoàn công tác có các đồng chí: Thiếu tướng La Công Phương, Chính ủy Quân khu 1; Thiếu tướng Trần Xuân Mạnh, Phó Tư lệnh, Tham mưu trưởng Quân khu 1. Tỉnh Bắc Ninh có các đồng chí: Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí trong Ban Thường vụ Tỉnh ủy, Thường trực HĐND, UBND, Ủy ban MTTQ, Đoàn ĐBQH tỉnh; lãnh đạo Bộ CHQS tỉnh, Văn phòng Tỉnh ủy, Văn phòng UBND tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288878/mt10.png/c3c7ed53-aa2f-2c29-fa01-e083eeca2535?t=1761718990364\" style=\"width: 900px; height: 551px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong 2 ngày (28 và 29/10), tại Trung tâm Hội nghị tỉnh, Ủy ban MTTQ Việt Nam tỉnh Bắc Ninh long trọng tổ chức Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030. Tham dự Đại hội, đại biểu Trung ương có đồng chí Đỗ Văn Chiến, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam; lãnh đạo Ủy ban Trung ương MTTQ Việt Nam. Đại biểu tỉnh Bắc Ninh có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy; Thường trực HĐND, lãnh đạo UBND, lãnh đạo Đoàn ĐBQH tỉnh; các đồng chí nguyên Thường trực Tỉnh ủy, UBND tỉnh qua các thời kỳ; Mẹ Việt Nam Anh hùng, Anh hùng Lực lượng vũ trang Nhân dân, Anh hùng Lao động; các đồng chí nguyên lãnh đạo Ủy ban MTTQ tỉnh qua các thời kỳ, lãnh đạo Ủy ban MTTQ một số tỉnh lân cận; lãnh đạo các sở, ban, ngành, địa phương của tỉnh cùng 358 đại biểu chính thức đại diện cho các tầng lớp Nhân dân, các dân tộc, tôn giáo, lực lượng vũ trang, người con Bắc Ninh trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288501/3.jpg/4c1a0ff3-2df2-6976-d801-ddf3567323c6?t=1761824962421\" style=\"width: 900px; height: 561px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, đồng chí Vương Quốc Tuấn, Uỷ viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh. Cùng đi có đại diện lãnh đạo các sở, ngành, cơ quan của tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288823/30-11.png/e2862176-c9f0-8191-b2df-b9b0a89b3766?t=1761814487649\" style=\"width: 900px; height: 632px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Giáo sư Veronique Blanquet, Phó Hiệu trưởng Trường Đại học Limoges (Cộng hòa Pháp) đến trao đổi thúc đẩy hợp tác trong các lĩnh vực giáo dục, công nghệ cao, bán dẫn, đổi mới sáng tạo.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288823/2+%286%29.jpg/92ec3c8e-decf-3b02-953f-978d7d89930a?t=1761821866420\" style=\"width: 900px; height: 548px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, tại Bệnh viện Đa khoa Bắc Ninh số 1, Sở Y tế Bắc Ninh phối hợp với Tập đoàn Vingroup và các đơn vị liên quan tổ chức công bố Quyết định thành lập Trung tâm Cấp cứu và vận chuyển 115; bàn giao xe cấp cứu và trang thiết bị y tế do Tập đoàn Vingroup tài trợ. Dự buổi lễ có các đồng chí: Giáo sư, Tiến sỹ Trần Văn Thuấn, Thứ trưởng Bộ Y tế; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; đại diện Tập đoàn Vingroup, Quỹ Thiện Tâm cùng lãnh đạo một số sở, ngành, đơn vị liên quan.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200628/DoanGSBoTuphap+6.jpg/279786d8-b558-8a83-8aff-da6ccf33f959?t=1761800489504\" style=\"width: 900px; height: 556px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 30/10, tại Bắc Ninh, Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính (TTHC) dựa trên dữ liệu do Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh làm Trưởng đoàn, đã có buổi làm việc với UBND tỉnh Bắc Ninh nhằm nắm bắt, tháo gỡ những khó khăn, vướng mắc phát sinh trong quá trình cắt giảm, đơn giản hóa TTHC dựa trên dữ liệu. Tham gia Đoàn công tác có đại diện lãnh đạo Trung tâm Dữ liệu quốc gia, Bộ Công an; Trung tâm Dữ liệu quốc gia về dân cư; Cục Cảnh sát quản lý hành chính về trật tự xã hội (Bộ Công an); cùng đại diện Văn phòng Chính phủ, Bộ Nội vụ, Bộ Tư pháp. Tiếp và làm việc với Đoàn có đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh, cùng đại diện lãnh đạo các sở, ban, ngành của tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288878/26-3.png/9fb3140a-47c9-3801-fb38-cb1f3bb5bdb3?t=1761453274827\" style=\"width: 900px; height: 593px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 26/10, Hội Chiến sỹ cách mạng bị địch bắt tù đày tỉnh Bắc Ninh tổ chức Đại hội lần thứ I, nhiệm kỳ 2025 - 2030. Dự và chúc mừng Đại hội có các đồng chí: Trương Mỹ Hoa, nguyên Bí thư Trung ương Đảng, nguyên Phó Chủ tịch nước; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; lãnh đạo Ban Liên lạc toàn quốc chiến sĩ cách mạng Việt Nam bị địch bắt tù đày và Hội Chiến sỹ cách mạng bị địch bắt tù đày một số tỉnh bạn; lãnh đạo một số sở, ban, ngành của tỉnh cùng 160 đại biểu đại diện cho hơn 300 hội viên trong toàn tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hoat-ong-noi-bat-cua-lanh-ao-tinh-tu-ngay-25-31-10-2025-29928666', '', 'BNP', 161, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:49.848597', 6, 11);
INSERT INTO `sync_articles` VALUES (124, '29923930', 'Đẩy nhanh tiến độ thực hiện tuyến đường kết nối Sân bay Gia Bình với thủ đô Hà Nội', 'Đẩy nhanh tiến độ thực hiện tuyến đường kết nối Sân bay Gia Bình với thủ đô Hà Nội', '/documents/37632/23288823/31-1.png/e9016b20-7127-678f-50d3-2b4d5e32cf49?t=1761890702608', '<p>(BNP) - Tại Văn bản số 4237/UBND-KTN, Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh chỉ đạo đẩy nhanh tiến độ thực hiện tuyến đường kết nối Cảng hàng không quốc tế Gia Bình với thủ đô Hà Nội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/31-1.png/e9016b20-7127-678f-50d3-2b4d5e32cf49?t=1761890702608\" style=\"height: 600px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Sở Xây dựng tăng cường công tác phối hợp, bám sát cơ quan chuyên môn của Bộ Xây dựng và Viện Kỹ thuật Công trình Đặc biệt - Học viện Kỹ thuật Quân sự sớm có ý kiến tham gia. Đồng thời, đôn đốc nhà đầu tư hoàn thiện hồ sơ, khẩn trương hoàn thành thẩm định Báo cáo nghiên cứu khả thi xong trước ngày 05/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Tài chính tiếp tục đôn đốc, phối hợp với các cơ quan, địa phương hoàn thiện thẩm định của Hội đồng thẩm định, tham mưu phê duyệt dự án, phê duyệt nhà đầu tư xong trước ngày 10/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ban Quản lý dự án Giao thông và Nông nghiệp tỉnh Bắc Ninh số 2 phối hợp chặt chẽ với nhà đầu tư hoàn thành cắm mốc, bàn giao phạm vi giải phóng mặt bằng (đợt 1) đối với khu vực có đất ở, nhà ở, xong chậm nhất trong ngày 01/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">UBND xã, phường ban hành thông báo thu hồi đất (đợt 1) đối với toàn bộ khu vực thu hồi có đất ở xong trước ngày 04/11/2025, gửi Chủ tịch UBND tỉnh. Thông báo thu hồi đất (đợt 1) cho phép có sai sót về diện tích, quy chủ và sẽ được tiếp tục hiệu chỉnh trong thời hạn 30 ngày. Chủ tịch UBND xã, phường chịu trách nhiệm về các hậu quả xảy ra nếu chậm ban hành thông báo thu hồi đất (đợt 1).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">UBND xã, phường phối hợp, cung cấp các tài liệu, số liệu có liên quan đến công tác lập dự án (như bản đồ địa chính, thống kê sử dụng đất…) cho Liên danh Công ty Cổ phần Đầu tư và Xây dựng giao thông Công Thành - Công ty TNHH Mặt trời Cẩm Phả xong trước ngày 02/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Liên danh Công ty Cổ phần Đầu tư và Xây dựng giao thông Công Thành - Công ty TNHH Mặt trời Cẩm Phả chủ động phối hợp với các cơ quan chuyên môn của tỉnh và các địa phương hoàn thiện, bổ sung đầy đủ hồ sơ trình thẩm định gửi Sở Xây dựng để tổ chức thẩm định Báo cáo nghiên cứu khả thi theo đúng quy định. Cùng với đó, nghiên cứu, tiếp thu, giải trình và hoàn thiện hồ sơ trên cơ sở các ý kiến góp ý của các thành viên Hội đồng thẩm định và các cơ quan, đơn vị, địa phương liên quan. Phối hợp với Ban Quản lý dự án Giao thông và Nông nghiệp tỉnh Bắc Ninh số 2 hoàn thành cắm mốc phạm vi giải phóng mặt bằng xong chậm nhất trong ngày 01/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các sở ngành, địa phương căn cứ chức năng, nhiệm vụ chủ động phối hợp, triển khai thực hiện các công việc có liên quan đảm bảo hoàn thành phê duyệt dự án trước 10/11/2025; hoàn thành giải phóng mặt bằng đất nông nghiệp xong trước ngày 21/12/2025./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ay-nhanh-tien-o-thuc-hien-tuyen-uong-ket-noi-san-bay-gia-binh-voi-thu-o-ha-noi-29923930', '', 'Linh Ngọc', 444, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:49.888053', 6, 11);
INSERT INTO `sync_articles` VALUES (125, '29892703', 'Bắc Ninh phê duyệt Chiến lược Chuyển đổi số giai đoạn 2025-2030', 'Bắc Ninh phê duyệt Chiến lược Chuyển đổi số giai đoạn 2025-2030', '/documents/37632/23288823/1+%284%29.jpg/5718592d-462b-b237-a8dc-ed82f2dc660f?t=1761880734965', '<p>(BNP) - Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh vừa ký Quyết định số 1305/QĐ-UBND phê duyệt Chiến lược Chuyển đổi số tỉnh Bắc Ninh giai đoạn 2025-2030.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288823/1+%284%29.jpg/5718592d-462b-b237-a8dc-ed82f2dc660f?t=1761880734965\" style=\"height: 519px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Đoàn thanh niên xã Yên Thế tuyên truyền phong trào bình dân học vụ số.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Chiến lược ban hành nhằm mục đích xây dựng và triển khai đồng bộ kiến trúc hệ thống, nền tảng dùng chung trong toàn bộ hệ thống chính trị, xuyên suốt từ Trung ương đến địa phương bảo đảm kết nối, liên thông, chia sẻ dữ liệu thông suốt bảo đảm đồng bộ, thống nhất toàn hệ thống chính trị, thực hiện các mục tiêu của Nghị quyết số 57-NQ/TW của Bộ Chính trị. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Phấn đấu 100% hệ thống công nghệ thông tin (CNTT), nền tảng dùng chung cùng với cơ sở dữ liệu của tỉnh được rà soát, đánh giá, tiếp tục xây dựng, bổ sung và chuẩn hóa toàn diện theo tiêu chuẩn chung, bảo đảm bao quát tất cả các lĩnh vực quản lý nhà nước, khả năng liên thông, kết nối, chia sẻ, tích hợp. Nâng cao chất lượng cung cấp dịch vụ công trực tuyến, phục vụ hiệu quả công tác chỉ đạo, điều hành và cải cách thủ tục hành chính dựa trên dữ liệu, đáp ứng yêu cầu thiết thực của người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Để đạt mục tiêu Chiến lược Chuyển đổi số tỉnh Bắc Ninh giai đoạn 2025-2030, UBND tỉnh tập trung triển khai 4 nhóm nhiệm vụ trọng tâm gồm: Tăng cường sự lãnh đạo, chỉ đạo của các cấp ủy Đảng, Chính quyền nhằm đổi mới tư duy, thống nhất nhận thức, tạo nền tảng chuyển đổi số; phát triển Chính quyền số; phát triển kinh tế số; phát triển xã hội số.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Phó Chủ tịch Thường trực UBND tỉnh giao Sở Khoa học và Công nghệ &nbsp;xây dựng Kế hoạch truyền thông nhằm chuyển đổi nhận thức của các cấp, các ngành, cán bộ, công chức viên chức, người dân và doanh nghiệp về chuyển đổi số gắn với Kế hoạch truyền thông Nghị quyết số 57-NQ-TW.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Các sở, ban, ngành, UBND các xã, phường gắn các mục tiêu, nhiệm vụ về chuyển đổi số lồng ghép vào trong nhiệm vụ phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh của từng ngành, địa phương, đơn vị. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tạo lập chuyên trang, chuyên mục về chuyển đổi số trên Trang, Cổng Thông tin điện tử thành phần của cơ quan, đơn vị, địa phương. Quán triệt tới từng cán bộ, đảng viên, công chức, viên chức và người lao động về sự cần thiết và tính cấp thiết của chuyển đổi số trong cơ quan, đơn vị, địa phương mình. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">UBND các xã, phường rà soát, kiện toàn Ban chỉ đạo về phát triển khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số và Đề án 06 của địa phương để lãnh đạo, chỉ đạo công tác triển khai chuyển đổi số. Nghiên cứu xây dựng cơ chế, chính sách của tỉnh và đẩy mạnh phát triển nguồn nhân lực nhằm thúc đẩy quá trình chuyển đổi số. Chủ động liên kết với các cơ sở giáo dục đào tạo, trung tâm nghiên cứu, các đối tác trong và ngoài nước để đào tạo nguồn nhân lực, chuyển giao công nghệ phục vụ quá trình chuyển đổi số.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Chủ động rà soát, đăng ký cán bộ, công chức, viên chức tham dự đầy đủ các chương trình bồi dưỡng, nâng cao kiến thức về CNTT, chuyển đổi số. Ưu tiên bố trí sắp xếp cán bộ chuyên trách, kiêm nhiệm CNTT trong định biên của đơn vị để đảm bảo triển khai các ứng dụng CNTT và thực thi nhiệm vụ chuyển đổi số của cơ quan đạt hiệu quả./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-phe-duyet-chien-luoc-chuyen-oi-so-giai-oan-2025-2030-29892703', '', 'Nguyễn Miền', 118, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:49.927745', 6, 11);
INSERT INTO `sync_articles` VALUES (126, '29456621', 'Bắc Ninh công bố thành lập Trung tâm Cấp cứu và vận chuyển 115 - Tăng cường năng lực...', 'Bắc Ninh công bố thành lập Trung tâm Cấp cứu và vận chuyển 115 - Tăng cường năng lực cấp cứu ngoại viện', '/documents/37632/23288823/4+%283%29.jpg/bbd705e4-f081-7d89-fc00-f6372a19f8a8?t=1761821992737', '<p>(BNP) – Chiều 30/10, tại Bệnh viện Đa khoa Bắc Ninh số 1, Sở Y tế Bắc Ninh phối hợp với Tập đoàn Vingroup và các đơn vị liên quan tổ chức công bố Quyết định thành lập Trung tâm Cấp cứu và vận chuyển 115; bàn giao xe cấp cứu và trang thiết bị y tế do Tập đoàn Vingroup tài trợ.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/4+%283%29.jpg/bbd705e4-f081-7d89-fc00-f6372a19f8a8?t=1761821992737\" style=\"height: 462px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tập đoàn Vingroup trao biểu trưng tặng 15 xe cấp cứu cho Sở Y tế tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự buổi lễ có các đồng chí: Giáo sư, Tiến sỹ Trần Văn Thuấn, Thứ trưởng Bộ Y tế; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; đại diện Tập đoàn Vingroup, <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quỹ Thiện Tâm cùng&nbsp;</span></span></span>lãnh đạo một số sở, ngành, đơn vị liên quan.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/2+%286%29.jpg/92ec3c8e-decf-3b02-953f-978d7d89930a?t=1761821866420\" style=\"height: 548px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi trao quyết định và chúc mừng Bệnh viện Đa khoa Bắc Ninh số 1.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi lễ, Sở Y tế công bố&nbsp;Quyết định số 373/QĐ-UBND ngày 24/10/2025 của UBND tỉnh Bắc Ninh về việc tổ chức lại Trung tâm Cấp cứu ngoại viện và Khoa Cấp cứu thành Trung tâm Cấp cứu và vận chuyển 115 trực thuộc Bệnh viện Đa khoa Bắc Ninh số 1.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trung tâm Cấp cứu và vận chuyển 115 (gọi tắt là Trung tâm) có chức năng thực hiện toàn diện công tác khám bệnh, chữa bệnh cấp cứu và vận chuyển người bệnh; tổ chức thực hiện nhiệm vụ cấp cứu thường trực 24/7; thực hiện tiếp nhận và phân loại người bệnh, thăm dò chức năng cấp cứu, can thiệp cấp cứu, theo dõi và cấp cứu người bệnh nặng, cách ly, điều trị người bệnh đột quỵ theo quy định; thực hiện nhiệm vụ cấp cứu ngoại viện, vận chuyển người bệnh giữa các tuyến hoặc về gia đình đáp ứng nhu cầu của xã hội và của người dân bằng xe cứu thương chuyên dụng, đảm bảo nhanh chóng, kịp thời, an toàn, hợp lý, hiệu quả, góp phần xây dựng, hoàn thiện mô hình và vận hành hệ thống cấp cứu đồng bộ trên địa bàn tỉnh, nâng cao chất lượng công tác bảo vệ, chăm sóc sức khỏe nhân dân.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/5+%283%29.jpg/d2244b6c-e6ac-89e6-ccae-bebec2ab4454?t=1761822036043\" style=\"height: 558px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Y tế Trần Văn Thuấn tặng hoa chúc mừng Sở Y tế.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi lễ, Thứ trưởng Bộ Y tế Trần Văn Thuấn ghi nhận và đánh giá cao sự chủ động của tỉnh Bắc Ninh trong hiện đại hóa hệ thống y tế, đặc biệt là lĩnh vực cấp cứu ngoại viện – khâu quan trọng trong chăm sóc sức khỏe Nhân dân. Việc thành lập Trung tâm là dấu mốc quan trọng, thể hiện quyết tâm của tỉnh trong triển khai Đề án phát triển hệ thống cấp cứu y tế giai đoạn 2025 – 2030, hướng tới mô hình cấp cứu thông minh, nhân văn và hiện đại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng cho biết, công tác cấp cứu ngoại viện đang nhận được sự quan tâm đặc biệt của Đảng, Chính phủ và Bộ Y tế, với nhiều chính sách, nghị quyết mới được ban hành, tạo hành lang pháp lý cho việc tổ chức và vận hành thống nhất trên toàn quốc. Đồng chí đề nghị tỉnh Bắc Ninh quan tâm chỉ đạo sâu sát 5 định hướng trọng tâm: Hoàn thiện chỉ huy, điều phối liên ngành, tích hợp công nghệ sớm, GPS, bản đồ nguy cơ; chuẩn hóa năng lực tuyến đầu và thời gian phản ứng, xây dựng đội hình \"paramedic\" đạt chuẩn; phát triển truyền thông cộng đồng, huấn luyện sơ cứu đại trà; xây dựng cơ chế tài chính đa nguồn, đảm bảo không ai bị từ chối vì thiếu chi phí vận chuyển và liên kết chặt chẽ với hệ thống cấp cứu quốc gia và trung tâm điều phối cấp cứu thông minh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ Y tế cam kết tiếp tục đồng hành cùng Bắc Ninh trên mọi phương diện: kỹ thuật chuyên môn, cơ chế chính sách, điều phối hệ thống, hợp tác quốc tế, đào tạo nhân lực và kết nối tài chính.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/1+%283%29.jpg/e6329f1b-3db0-fe29-0903-9a090f23145d?t=1761822069720\" style=\"height: 638px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi phát biểu tại buổi lễ.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo UBND tỉnh, Phó Chủ tịch UBND tỉnh Bắc Ninh Lê Xuân Lợi biểu dương và cảm ơn Tập đoàn Vingroup, Quỹ Thiện Tâm đã tài trợ xe cứu thương, trang thiết bị cấp cứu, kinh phí đào tạo nhân lực cho tỉnh. Việc tiếp nhận xe cứu thương, trang thiết bị góp phần hoàn thiện hệ thống cấp cứu y tế theo hướng chuyên nghiệp, đồng bộ từ tỉnh đến cơ sở; đảm bảo người dân được tiếp cận dịch vụ cấp cứu nhanh nhất, hiệu quả nhất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để vận hành Hệ thống cấp cứu ngoại viện hiệu quả, Phó Chủ tịch UBND tỉnh Bắc Ninh đề nghị Sở Y tế khẩn trương đưa Trung tâm trực thuộc Bệnh viện Đa khoa Bắc Ninh số 1 vào hoạt động hiệu quả, an toàn, đúng quy định; bố trí, đào tạo đội ngũ chuyên trách có chuyên môn, trách nhiệm và đạo đức nghề nghiệp. Đồng thời, hướng dẫn các cơ sở y tế trong mạng lưới Hệ thống cấp cứu ngoại viện bảo đảm trực cấp cứu, vận chuyển người bệnh thông suốt, kịp thời, lấy người bệnh làm trung tâm. Sở cũng cần xây dựng quy trình tiếp nhận, xử lý thông tin cấp cứu và kết nối hệ thống xe cứu thương.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trung tâm cần phát huy tinh thần chủ động, kỷ luật, tận tâm; tổ chức tốt công tác thường trực, điều phối, phối hợp chặt chẽ với lực lượng y tế, công an, giao thông, phòng cháy chữa cháy… để bảo đảm cấp cứu nhanh, chính xác, an toàn, phục vụ tốt nhất cho nhân dân trong mọi tình huống.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/6+%282%29.jpg/5ef97eae-b400-4b95-0231-cde6de532b65?t=1761822100907\" style=\"height: 616px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xe cứu thương do Tập đoàn Vingroup tài trợ&nbsp;phục vụ công tác vận chuyển, cấp cứu ngoại viện cho tỉnh Bắc Ninh. </span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi lễ, đại diện Tập đoàn Vingroup và Quỹ Thiện Tâm đã bàn giao 15 xe cứu thương và nhiều trang thiết bị y tế hiện đại phục vụ công tác vận chuyển, cấp cứu ngoại viện cho tỉnh Bắc Ninh. Mỗi xe được trang bị máy thở, máy sốc điện tích hợp monitor, siêu âm xách tay FAST exam, điện tim 12 đạo trình kết nối từ xa, bộ đặt nội khí quản có camera, nẹp cố định chấn thương và đầy đủ dụng cụ hồi sức.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc tài trợ xe cứu thương và trang thiết bị y tế hiện đại cho Bắc Ninh là một phần trong chương trình “Tăng cường năng lực cấp cứu ngoại viện” do Quỹ Thiện Tâm – Tập đoàn Vingroup triển khai tại nhiều địa phương trên cả nước. Mục tiêu của chương trình là hỗ trợ ngành Y tế các tỉnh, thành xây dựng hệ thống cấp cứu đồng bộ, chuyên nghiệp, góp phần giảm tỷ lệ tử vong và di chứng do chậm cấp cứu, đồng thời nâng cao chất lượng chăm sóc sức khỏe ban đầu cho người dân.</span></span></span></p>\n\n<p style=\"margin-bottom:8px; text-align:justify\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:115%\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:115%\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-cong-bo-thanh-lap-trung-tam-cap-cuu-va-van-chuyen-115-tang-cuong-nang-luc-cap-cuu-ngoai-vien-29456621', '', 'Diệu Hoa', 1001, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:49.976078', 6, 11);
INSERT INTO `sync_articles` VALUES (127, '29533801', 'Hỗ trợ cán bộ chưa có nhà ở, đã có nhà ở nhưng cách xa nơi làm việc mua nhà ở xã hội', 'Hỗ trợ cán bộ chưa có nhà ở, đã có nhà ở nhưng cách xa nơi làm việc mua nhà ở xã hội', '/documents/37632/23288823/30-14.png/0baf16b7-0900-744c-abf9-211e53e50388?t=1761816876014', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh vừa ký Văn bản số 4161/UBND-XDCB về việc hỗ trợ cán bộ, công chức, viên chức chưa có nhà ở, đã có nhà ở thuộc sở hữu của mình nhưng cách xa địa điểm làm việc đáp ứng yêu cầu, điều kiện mua nhà ở xã hội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-14.png/0baf16b7-0900-744c-abf9-211e53e50388?t=1761816876014\" style=\"height: 622px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án nhà ở xã hội Cát Tường Thống Nhất, phường Võ Cường, tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Sở Xây dựng chủ trì, phối hợp với các cơ quan, đơn vị liên quan thông tin về các dự án nhà ở xã hội đủ điều kiện bán/cho thuê/cho thuê mua nhà ở hình thành trong tương lai đến các cơ quan nhà Đảng, Nhà nước đóng trên địa bàn tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hướng dẫn về thành phần hồ sơ đăng ký mua/thuê/thuê mua nhà ở xã hội; tổng hợp danh sách (kèm theo hồ sơ đã được hướng dẫn) về nhu cầu của cán bộ, công chức, viên chức chưa có nhà ở; đã có nhà ở thuộc sở hữu của mình nhưng cách xa địa điểm làm việc. Đồng thời, xác minh việc đáp ứng yêu cầu đối tượng, điều kiện được mua/thuê/thuê mua nhà ở xã hội theo quy định của pháp luật; gửi danh sách đủ điều kiện đến các chủ đầu tư dự án nhà ở xã hội để tổ chức thực hiện việc bán/cho thuê/cho thuê mua nhà ở hình thành trong tương lai theo quy định pháp luật.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thời gian hoàn thành chậm nhất vào ngày 15/11/2025./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/ho-tro-can-bo-chua-co-nha-o-a-co-nha-o-nhung-cach-xa-noi-lam-viec-mua-nha-o-xa-hoi-29533801', '', 'Linh Ngọc', 1874, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:50.026203', 6, 11);
INSERT INTO `sync_articles` VALUES (128, '29525512', 'Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Trường Đại...', 'Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Trường Đại học Limoges (Cộng hòa Pháp)', '/documents/37632/23288823/30-10.png/b5cf462c-c30c-a0c7-a43d-60680c0bba58?t=1761814391208', '<p>(BNP) - Chiều 30/10, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Giáo sư Veronique Blanquet, Phó Hiệu trưởng Trường Đại học Limoges (Cộng hòa Pháp) đến trao đổi thúc đẩy hợp tác trong các lĩnh vực giáo dục, công nghệ cao, bán dẫn, đổi...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-10.png/b5cf462c-c30c-a0c7-a43d-60680c0bba58?t=1761814391208\" style=\"height: 620px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh chụp ảnh lưu niệm với&nbsp;Giáo sư Veronique Blanquet.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Vui mừng chào đón đoàn công tác của Trường Đại học Limoges đến thăm và làm việc tại Bắc Ninh, đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh giới thiệu khái quát tình hình phát triển kinh tế - xã hội của tỉnh, nhất là sau khi sáp nhập 02 tỉnh Bắc Giang - Bắc Ninh (cũ). Với quy mô kinh tế đứng thứ 5 toàn quốc, lợi thế về vị trí địa lý, tiềm năng phát triển, Bắc Ninh được xác định là trung tâm công nghiệp bán dẫn của cả nước. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bắc Ninh hiện có trên 30 khu công nghiệp tập trung đã đi vào hoạt động, thu hút hàng nghìn doanh nghiệp trong và ngoài nước. Tổng vốn đầu tư nước ngoài FDI ở tất cả các ngành nghề trên địa bàn tỉnh hiện đạt khoảng 45 tỷ USD, đứng thứ 2 cả nước. Trong đó, vốn đầu tư của Pháp là hơn 135 triệu USD, tập trung vào lĩnh vực dược phẩm, may mặc…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-11.png/e2862176-c9f0-8191-b2df-b9b0a89b3766?t=1761814487649\" style=\"height: 632px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh giới thiệu và tặng tranh dân gian Đông Hồ cho&nbsp;Giáo sư Veronique Blanquet.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bên cạnh phát triển kinh tế, Bắc Ninh còn là vùng đất có truyền thống khoa bảng, hiếu học; chất lượng giáo dục của tỉnh luôn nằm trong tốp các tỉnh đứng đầu cả nước với nhiều học sinh đạt giải học sinh giỏi quốc gia, quốc tế. Ngoài ra, trên địa bàn tỉnh hiện có 01 trường Đại học; nhiều chi nhánh, cơ sở 2 của các trường Đại học lớn đầu tư tại tỉnh cùng 18 trường Cao đẳng và các trường trung cấp, trung tâm giáo dục nghề nghiệp… mỗi năm đào tạo hàng nghìn sinh viên. Để tạo bước đột phá về chất lượng nguồn lao động của tỉnh, Bắc Ninh đã ban hành nhiều chính sách hỗ trợ cho học sinh, sinh viên, giáo viên; hỗ trợ đào tạo nhân lực phục vụ các ngành công nghiệp mũi nhọn, công nghiệp bán dẫn, trí tuệ nhân tạo; hỗ trợ học sinh tốt nghiệp THPT đi học ở nước ngoài đối với các ngành điện tử, bán dẫn…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh mong muốn trong thời gian tới, Trường Đại học Limoges sẽ hợp tác với tỉnh Bắc Ninh trong các chương trình đào tạo nguồn nhân lực chất lượng cao ngành công nghệ bán dẫn, vật liệu điện tử, năng lượng và tự động hóa; phát triển các chương trình đào tạo tại chỗ; có chính sách học bổng đối với sinh viên đi du học… Từ đó, nghiên cứu, triển khai ký kết biên bản hợp tác trong đào tạo nguồn nhân lực chất lượng cao với tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh cũng mong muốn Giáo sư Veronique Blanquet bằng uy tín và mối quan hệ của mình, sẽ là cầu nối, kết nối các doanh nghiệp Pháp về tìm hiểu, đầu tư tại Bắc Ninh và liên kết với doanh nghiệp tại Bắc Ninh trong thúc đẩy hợp tác chuỗi cung ứng và ứng dụng công nghệ mới…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-13.png/ce54907a-1b9c-a869-5e19-78dd9f21a30f?t=1761814600756\" style=\"height: 607px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giáo sư Veronique Blanquet giới thiệu khái quát về Trường&nbsp;Đại học Limoges.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trân trọng cảm ơn sự đón tiếp trọng thị của lãnh đạo tỉnh Bắc Ninh, Giáo sư Veronique Blanquet bày tỏ ấn tượng trước sự phát triển của tỉnh trong công cuộc hội nhập, nhất là vào chuỗi giá trị công nghệ cao toàn cầu. Đồng thời cho biết, Trường Đại học Limoges được thành lập vào năm 1968, có truyền thống sản xuất đồ gốm sứ. Trường có quy mô hơn 18.000 sinh viên, trong đó gần 2.000 sinh viên quốc tế, chiếm 10,8%; đào tạo đa ngành, nổi bật với các chương trình đào tạo đa dạng từ khoa học xã hội nhân văn đến khoa học tự nhiên và ứng dụng; trong đó, đặc biệt mạnh về các ngành: Y, Dược, Luật, Kinh tế, Khoa học và Kỹ thuật, các chương trình về Kỹ thuật Dân dụng và Quản lý…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Vượt lên trên vai trò là một hệ thống đào tạo đa ngành toàn diện, Trường Đại học Limoges còn là trung tâm đổi mới sáng tạo hàng đầu châu Âu với 05 viện nghiên cứu, đóng góp vào chuỗi giá trị công nghệ chủ chốt toàn cầu về chất bán dẫn, vật liệu sinh học, năng lượng, công nghệ hạt nhân và công nghệ thông tin.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-12.png/c60c7f3b-8791-3b9e-e224-bf5d75333af5?t=1761814667474\" style=\"height: 595px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh buổi tiếp và làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhấn mạnh, chuyến thăm và làm việc tại tỉnh Bắc Ninh diễn ra trong bối cảnh quan hệ giữa 02 quốc gia Pháp - Việt Nam vừa được nâng cấp lên Đối tác Chiến lược toàn diện, Phó Hiệu trưởng Trường Đại học Limoges tin tưởng vào tiềm năng hợp tác về giáo dục, nghiên cứu và công nghệ cao, hướng tới việc kiến tạo các giá trị bổ trợ lẫn nhau, đóng góp vào các mục tiêu chiến lược chung của hai bên. Đồng thời, mong muốn được chào đón các sinh viên tỉnh Bắc Ninh đến học tập, nghiên cứu tại Trường.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giáo sư Veronique Blanquet cũng trân trọng gửi lời mời tới các đồng chí lãnh đạo tỉnh; lãnh đạo các sở, ngành liên quan đến thăm và làm việc tại Trường Đại học Limoges trong thời gian tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngay sau buổi làm việc, đoàn công tác của Trường Đại học Limoges đến thăm quan cơ sở vật chất, mô hình đào tạo một số ngành thế mạnh tại Trường Cao đẳng Công nghiệp Bắc Ninh./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ong-chi-mai-son-pho-chu-tich-thuong-truc-ubnd-tinh-tiep-va-lam-viec-voi-truong-ai-hoc-limoges-cong-hoa-phap-29525512', '', 'Linh Ngọc', 380, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:50.069846', 6, 11);
INSERT INTO `sync_articles` VALUES (129, '29509201', 'Bắc Ninh hỗ trợ 9 tỷ đồng cho thành phố Huế, Đà Nẵng, Quảng Trị, Quảng Ngãi bị thiệt...', 'Bắc Ninh hỗ trợ 9 tỷ đồng cho thành phố Huế, Đà Nẵng, Quảng Trị, Quảng Ngãi bị thiệt hại do bão lũ gây ra', 'https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/28/5712750021221476795906834372194270522638716475n-17616258236281709798788.jpg', '<p>(BNP) – Ban Vận động Cứu trợ tỉnh Bắc Ninh vừa ban hành Quyết định số 06/QĐ-BVĐCT về việc hỗ trợ các tỉnh, thành phố bị thiệt hại do bão lũ gây ra.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/28/5712750021221476795906834372194270522638716475n-17616258236281709798788.jpg\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kinh thành Huế sáng nay 28.10</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, được sự nhất chí của Thường trực Tỉnh ủy về việc hỗ trợ các đơn vị bị ảnh hưởng do bão lũ gây ra, Ban Vận động cứu trợ tỉnh quyết định phân bổ số tiền 9 tỷ đồng từ nguồn Quỹ của Ban vận động cứu trợ tỉnh Bắc Ninh vào tài khoản của Ban vận động cứu trợ các tỉnh, thành phố bị thiệt hại do bão lũ gây ra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể: hỗ trợ thành phố Huế 3 tỷ đồng; thành phố Đà Nẵng 2 tỷ đồng; tỉnh Quảng Trị 2 tỷ đồng; tỉnh <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quảng Ngãi&nbsp;</span></span></span>2 tỷ đồng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ban Vận động cứu trợ - Ủy ban MTTQ các đơn vị có trách nhiệm hỗ trợ đảm bảo phù hợp, đúng mục đích, công khai, minh bạch, hiệu quả và thanh quyết toán theo quy định của pháp luật hiện hành.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-ho-tro-9-ty-ong-cho-thanh-pho-hue-a-nang-quang-tri-quang-ngai-bi-thiet-hai-do-bao-lu-gay-ra-29509201', '', 'Nguyễn Nhàn', 192, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:50.116268', 6, 11);
INSERT INTO `sync_articles` VALUES (130, '29130241', 'Bắc Ninh: Danh sách 342 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 17...', 'Bắc Ninh: Danh sách 342 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 17 - 26/10/2025', '/documents/37632/18835561/566329315_122153219672804369_8563098369294465191_n.jpg/e5b45c7e-16cd-42b8-e068-c71146a956bd?t=1761624627432', '<p>(BNP) - Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 17 - 26/10/2025, ghi nhận 342 trường hợp xe mô tô (xe máy)<strong> </strong>vi phạm bị phạt nguội.</p>', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/566329315_122153219672804369_8563098369294465191_n.jpg/e5b45c7e-16cd-42b8-e068-c71146a956bd?t=1761624627432\" style=\"width: 900px; height: 488px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>320 trường hợp m<span lang=\"VI\">ô tô </span>(xe máy) không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+xe+may+1+%281%29.png/4bdd0e95-2948-6377-ad41-4857395bfce5?t=1761624655996\" style=\"height: 922px;\" /><br />\n<img src=\"/documents/37632/18835561/2810+xe+may+2.png/8d26a99c-8138-e008-6ef5-1d55719f2014?t=1761624670326\" style=\"height: 1223px; width: 800px;\" /><br />\n<img src=\"/documents/37632/0/2810+xe+may+3+%281%29.png/318b14ad-f8d0-e43b-f6cd-5340e60b32be?t=1761624697027\" style=\"height: 137px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 22 trường hợp mô tô (xe máy) chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/0/2810+xe+may+4.png/e0cfb830-7781-44ca-dbc4-bc41e98d49cb?t=1761624733247\" style=\"height: 185px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-bottom: 11px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định.</span> <span lang=\"VI\">Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định.</span>/.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-342-truong-hop-xe-mo-to-xe-may-vi-pham-bi-phat-nguoi-tu-ngay-17-26-10-2025-29130241', '', 'BNP', 4815, 'Xã hội', 6, '', '38762', '{}', '2025-11-01 07:12:50.173185', 6, 11);
INSERT INTO `sync_articles` VALUES (131, '29906460', 'Bắc Ninh: Tổng kết và trao giải Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ...', 'Bắc Ninh: Tổng kết và trao giải Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21', '/documents/37632/23288878/31-10-3+%281%29.png/79351be0-452e-4edf-9830-d44d919a37db?t=1761892235498', '<p>(BNP) – Sáng 31/10, tại Trường THPT Ngô Sĩ Liên, Ban Tổ chức Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng tỉnh Bắc Ninh tổ chức Tổng kết Cuộc thi lần thứ 21, năm 2025 và trao giải cho các mô hình, sản phẩm xuất sắc. Dự chương trình có đồng chí Trần Thị Hằng, Ủy viên Ban Thường vụ Tỉnh ủy, Phó...', '<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-3+%281%29.png/79351be0-452e-4edf-9830-d44d919a37db?t=1761892235498\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng (ngoài cùng bên trái) và&nbsp;Chủ tịch Liên hiệp Các hội Khoa học và Kỹ thuật tỉnh Ngô Chí Vinh (ngoài cùng bên phải) trao giải Nhất cho các tác giả, nhóm tác giả Cuộc thi&nbsp;Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21, năm 2025 do UBND tỉnh chỉ đạo, Liên hiệp các hội Khoa học và Kỹ thuật tỉnh chủ trì, phối hợp với Tỉnh Đoàn và các Sở Khoa học và Công nghệ, Giáo dục và Đào tạo, Tài chính; Báo và Phát thanh, Truyền hình tỉnh tổ chức. Cuộc thi nhằm khơi dậy tiềm năng và phát huy tư duy sáng tạo của đoàn viên, thanh thiếu niên, nhi đồng toàn tỉnh; giúp các em trau dồi kiến thức, rèn luyện kỹ năng sáng tạo và đào tạo nguồn nhân lực trẻ có chất lượng cao đáp ứng nhu cầu công nghiệp hóa, hiện đại hóa. </span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Đối tượng dự thi là đoàn viên, thanh thiếu niên và nhi đồng có độ tuổi từ 06 đến 19 tuổi. Cuộc thi có 5 lĩnh vực dự thi gồm: Đồ dùng dành cho học tập; phần mềm tin học; sản phẩm thân thiện với môi trường; các dụng cụ sinh hoạt gia đình, đồ dùng giải trí và đồ chơi trẻ em; các giải pháp nhằm ứng phó biến đổi khí hậu, bảo vệ môi trường và phát triển kinh tế. </span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-1.png/3849bca8-bdec-8cb0-f65f-25972e9cc253?t=1761892500951\" style=\"height: 530px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng trao Bằng khen của Chủ tịch UBND tỉnh cho các tập thể, cá nhân có thành tích xuất sắc.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Qua các vòng tuyển chọn, Hội đồng Giám khảo đã lựa chọn được 60 mô hình, sản phẩm vào vòng chung khảo Cuộc thi. Kết quả, có 33 mô hình, sản phẩm của 95 tác giả, đồng tác giả được trao giải. Đây đều là những mô hình mới, có hàm lượng sáng tạo cao, có khả năng ứng dụng để giải quyết những vấn đề thực tiễn đang diễn ra trong cuộc sống, học tập. Điển hình như mô hình “Chuyển đổi số, nâng cao hiệu quả trong công tác quản lý phương tiện đi lại của học sinh” của nhóm tác giả Trường THPT Tân Yên số 2; mô hình “Chế tạo vật liệu hút ẩm từ lõi cây sắn (khoai mì) bảo quản nông sản, thực phẩm” của tác giả Trường Tiểu học Phồn Xương, xã Yên Thế; mô hình “Khung xương hỗ trợ phục hồi chức năng vận động cho người đột quỵ” của nhóm tác giả Trường THPT Yên Dũng số 1; mô hình “Chiến thắng Xương Giang - Muôn thuở hào hùng” của nhóm tác giả Trường Tiểu học Đông Thành, phường Bắc Giang... </span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-2.png/fca99717-2587-bcd9-94f9-e74ad48e8025?t=1761892587495\" style=\"height: 547px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng trao Bằng khen của Chủ tịch UBND tỉnh cho các tác giả, nhóm tác giả đạt giải Nhất 2 cuộc thi.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại chương trình, Ban Tổ chức Cuộc thi đã trao 02 giải nhất, 04 giải nhì, 06 giải ba và 21 giải khuyến khích với tổng trị giá tiền thưởng là 176 triệu đồng. Các tập thể, cá nhân có thành tích tiêu biểu trong tuyên truyền, tổ chức Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng năm 2025 và Cuộc thi Robocon tỉnh Bắc Ninh năm 2025 được trao tặng Bằng khen Chủ tịch UBND tỉnh. </span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Nhân dịp này, Trung ương Đoàn TNCS Hồ Chí Minh trao tặng Huy hiệu Tuổi trẻ sáng tạo cho 21 cá nhân là thanh thiếu niên tỉnh Bắc Ninh là các tác giả, nhóm tác giả đạt giải Nhất Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng và giải Nhất Cuộc thi Robocon tỉnh Bắc Ninh lần thứ 2, năm 2025; Hội Khuyến học tỉnh trao thưởng 2,5 triệu đồng cho mỗi tác giả, nhóm tác giả đạt giải Nhất 02 Cuộc thi.</span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-7.png/3c4247a2-3939-e66e-fec0-e458c53e3015?t=1761893048122\" style=\"height: 563px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Các tác giả, nhóm tác giả được nhận&nbsp;Huy hiệu Tuổi trẻ sáng tạo.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size: 18px; font-family: Arial, Helvetica, sans-serif;\">Cùng ngày, Ban Tổ chức phát động Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng tỉnh Bắc Ninh lần thứ 22, năm 2026. Cuộc thi diễn ra từ tháng 10/2025 đến tháng 10/2026. Cuộc thi sẽ bao gồm 3 bảng thi là khối THPT, bảng khối THCS và bảng khối Tiểu học; cơ cấu giải thưởng gồm 41 giải (tăng 7 giải so với năm 2025).</span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-6.png/740ef1b5-d5f6-3702-fe04-b8a98c9db4d2?t=1761893069063\" style=\"height: 564px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Các em học sinh hào hứng tham gia trải nghiệm vận hành robot tại Ngày hội.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cũng trong buổi sáng, Liên hiệp các hội Khoa học và Kỹ thuật tỉnh phối hợp với các đơn vị liên quan tổ chức Ngày hội Sáng tạo năm 2025 với các nội dung: Trải nghiệm robot, tham gia lập trình và vận hành robot, tham gia các trò chơi vận động, gắn với các trò chơi đòi hỏi trí tuệ, tinh thần làm việc nhóm…/.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"line-height:130%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:130%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-tong-ket-va-trao-giai-cuoc-thi-sang-tao-thanh-thieu-nien-nhi-ong-lan-thu-21-29906460', '', 'Nguyễn Nhàn', 160, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.497813', 7, 11);
INSERT INTO `sync_articles` VALUES (132, '29855320', 'Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường trong tỉnh đạt “không ma túy”', 'Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường trong tỉnh đạt “không ma túy”', '/documents/37632/200628/PCMT.jpg/cfdfc639-24de-cdc4-fe6d-d588ffb04e5d?t=1761876972454', '<p>(BNP) - Chủ tịch UBND tỉnh Bắc Ninh vừa ký ban hành <a href=\"/documents/37632/23288878/116-KH-UBND.pdf/92f8bf15-c0c6-b64b-0840-3e6a166d8621?t=1761877068580\">Kế hoạch số 116/KH-UBND</a> thực hiện Chương trình mục tiêu quốc gia về phòng, chống ma túy đến năm 2030 trên địa bàn tỉnh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/PCMT.jpg/cfdfc639-24de-cdc4-fe6d-d588ffb04e5d?t=1761876972454\" style=\"height: 572px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát huy sức mạnh của cả hệ thống chính trị và toàn dân tham gia công tác phòng, chống ma túy.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mục tiêu của Kế hoạch là phát huy sức mạnh của cả hệ thống chính trị và toàn dân tham gia công tác phòng, chống ma túy; lấy phòng ngừa là chính, đấu tranh ngăn chặn từ sớm, từ xa, giảm cung, giảm cầu, giảm tác hại ma túy, góp phần xây dựng xã hội an toàn, lành mạnh, phát triển bền vững. Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường đạt “không ma túy”, giảm người nghiện, người sử dụng trái phép chất ma túy và nâng cao chất lượng công tác cai nghiện, quản lý sau cai nghiện.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch đề ra nhiều chỉ tiêu cụ thể: 100% điểm tổ chức, chứa chấp, mua bán trái phép chất ma túy được phát hiện, triệt phá; trên 80% lực lượng chuyên trách được trang bị phương tiện kỹ thuật hiện đại; 100% trạm y tế cấp xã đủ điều kiện xác định tình trạng nghiện; 100% cơ sở cai nghiện ma túy công lập đủ điều kiện hoạt động; trên 80% cơ quan báo chí có chuyên trang, chuyên mục tuyên truyền phòng, chống ma túy.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình được triển khai từ năm 2025 đến năm 2030, trên phạm vi toàn tỉnh, gồm 9 dự án và nhiều tiểu dự án thành phần, tập trung vào các nội dung: Phòng ngừa, đấu tranh tội phạm ma túy; ứng dụng khoa học công nghệ; nâng cao hiệu quả cai nghiện và quản lý sau cai; tăng cường truyền thông, giáo dục, y tế, trợ giúp pháp lý; giám sát, đánh giá kết quả thực hiện.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch xác định 6 nhóm nhiệm vụ, giải pháp trọng tâm gồm: Nâng cao hiệu quả lãnh đạo, chỉ đạo; nâng cao hiệu quả, chất lượng công tác tuyên truyền, phổ biến giáo dục phòng, chống ma túy và phát động phong trào toàn dân tham gia bảo vệ an ninh Tổ quốc; nâng cao chất lượng, hiệu quả công tác phòng ngừa, đấu tranh với tội phạm, tệ nạn ma tuý; đổi mới, nâng cao hiệu quả công tác quản lý người sử dụng trái phép chất ma túy, người nghiện ma túy, công tác cai nghiện và quản lý sau cai nghiện ma túy; nâng cao hiệu quả hợp tác quốc tế về phòng, chống ma túy; ứng dụng khoa học và công nghệ trong phòng, chống ma túy; thực hiện quản lý, giám sát, đánh giá Chương trình</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh giao Công an tỉnh là cơ quan thường trực, chủ trì tham mưu, theo dõi, đôn đốc, kiểm tra và tổng hợp kết quả thực hiện; các sở, ban, ngành, địa phương căn cứ chức năng, nhiệm vụ được phân công xây dựng kế hoạch cụ thể, bảo đảm hoàn thành các mục tiêu, chỉ tiêu đã đề ra.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/phan-au-en-nam-2030-co-it-nhat-50-so-xa-phuong-trong-tinh-at-khong-ma-tuy-29855320', '', 'Dương Thuỷ', 58, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.538031', 7, 11);
INSERT INTO `sync_articles` VALUES (133, '29478603', 'Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính dựa trên dữ liệu làm...', 'Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính dựa trên dữ liệu làm việc tại tỉnh Bắc Ninh', '/documents/37632/200628/DoanGSBoTuphap+2.jpg/7e994fe0-30e1-ec78-d663-1e901951747c?t=1761800512635', '<p>(BNP) - Sáng 30/10, tại Bắc Ninh, Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính (TTHC) dựa trên dữ liệu do Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh làm Trưởng đoàn, đã có buổi làm việc với UBND tỉnh Bắc Ninh nhằm nắm bắt, tháo gỡ những khó khăn, vướng mắc phát sinh trong quá...', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+1.jpg/4400eea6-d533-bc24-992a-fc488156b566?t=1761799981519\" style=\"height: 503px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham gia Đoàn công tác có đại diện lãnh đạo Trung tâm Dữ liệu quốc gia, Bộ Công an; Trung tâm Dữ liệu quốc gia về dân cư; Cục Cảnh sát quản lý hành chính về trật tự xã hội (Bộ Công an); cùng đại diện Văn phòng Chính phủ, Bộ Nội vụ, Bộ Tư pháp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp và làm việc với Đoàn có đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh, cùng đại diện lãnh đạo các sở, ban, ngành của tỉnh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Thứ trưởng Nguyễn Thanh Tịnh nhấn mạnh, t</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">heo tinh thần chung của Bộ Tư pháp và Bộ Công an, kết quả rà soát,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">cắt giảm, đơn giản hóa TTHC dựa trên dữ liệu đảm bảo&nbsp;</span></span></span>phản ánh thực chất, lấy dữ liệu làm căn cứ thay thế giấy tờ truyền thống. Hiện có 15 nhóm giấy tờ có thể được thay thế bằng dữ liệu từ các cơ sở dữ liệu quốc gia như dân cư, hộ tịch, lý lịch tư pháp, đất đai, tài chính. Bắc Ninh là một trong những địa phương triển khai sớm với hơn 30 thủ tục thuộc danh mục này.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Tư pháp nêu 6 điều kiện bảo đảm thành công, gồm: cơ sở pháp lý rõ ràng; dữ liệu “đúng - đủ - sạch - sống - thống nhất”; hệ thống công nghệ kết nối ổn định; lộ trình cụ thể; cơ chế tiếp nhận, xử lý phản ánh của người dân và đội ngũ cán bộ am hiểu nghiệp vụ, công nghệ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị Bắc Ninh thành lập tổ tư vấn công nghệ tại Trung tâm Phục vụ hành chính công và cấp xã, hỗ trợ người dân trong quá trình thực hiện thủ tục số.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+3.jpg/b4de1419-824d-db9c-9dc9-3db01246a0da?t=1761800060786\" style=\"height: 588px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở Tư pháp Bắc Ninh Lưu Đình Thực&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">báo cáo tại buổi làm việc.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo tại buổi làm việc, Giám đốc Sở Tư pháp Bắc Ninh Lưu Đình Thực cho biết: Năm 2025, công tác cải cách TTHC của tỉnh đạt nhiều kết quả nổi bật, tiếp tục giữ vững vị trí nhóm đầu cả nước về chỉ số chỉ đạo, điều hành và chất lượng phục vụ người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh đã triển khai đồng bộ nhiều mô hình sáng tạo như “Ngày thứ Sáu không hẹn”, “Luồng xanh 24 giờ”, “Ngày Chủ nhật vì dân”… góp phần rút ngắn thời gian xử lý hồ sơ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện, 100% TTHC (trừ lĩnh vực thanh tra) được thực hiện phi địa giới hành chính; 982 dịch vụ công trực tuyến hoạt động thực chất; tỷ lệ hài lòng đạt trên 90%; tỷ lệ giải quyết hồ sơ đúng và trước hạn đạt 99,95%, qua đó đưa Bắc Ninh trong 06 tuần liên tiếp dẫn đầu cả nước với 91,73/100 điểm trên Cổng Dịch vụ công quốc gia.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, trong triển khai Đề án 06, Bắc Ninh là 1 trong 16 tỉnh hoàn thành kết nối hệ thống IOC với Cơ sở dữ liệu quốc gia về dân cư; làm sạch hơn 3 triệu dữ liệu đất đai, 2,8 triệu dữ liệu hộ tịch; thực hiện chính sách “0 đồng” cho 42 thủ tục trực tuyến, khuyến khích người dân sử dụng dịch vụ công số.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh Bắc Ninh đã rà soát 734 TTHC thuộc 16 lĩnh vực, trong đó hàng trăm thủ tục được đề xuất thay thế hồ sơ bằng dữ liệu từ các cơ sở dữ liệu quốc gia, cùng 53 TTHC đặc thù địa phương được đề xuất cắt giảm, đơn giản hóa. Tỉnh kiến nghị Văn phòng Chính phủ tiếp tục hướng dẫn, bổ sung danh mục TTHC có thể thay thế hồ sơ bằng dữ liệu, đồng thời cho phép cập nhật kết quả sau khi hoàn thiện cơ sở dữ liệu chuyên ngành.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+4.jpg/34eea1e4-0447-ec6b-e718-a84b1a97e2eb?t=1761800428502\" style=\"height: 559px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện lãnh đạo Văn phòng UBND tỉnh phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong quá trình triển khai, Bắc Ninh gặp một số khó khăn như: Thay đổi cán bộ phụ trách cải cách TTHC, nhiều công chức kiêm nhiệm nên việc cập nhật hướng dẫn còn chậm; khối lượng rà soát lớn, nhiều thủ tục chưa phát sinh hồ sơ thực tế; thời gian thực hiện gấp nên một số đơn vị lúng túng khi đối chiếu quy định với thực tế; cơ sở dữ liệu chuyên ngành chưa liên thông đầy đủ, gây hạn chế trong khai thác dữ liệu thay thế giấy tờ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh kiến nghị Văn phòng Chính phủ hướng dẫn, bổ sung danh mục TTHC có thể thay thế bằng dữ liệu và cho phép cập nhật kết quả sau khi đồng bộ cơ sở dữ liệu; đề nghị các bộ, ngành Trung ương sớm sửa đổi quy định pháp luật, tăng cường kết nối, chia sẻ dữ liệu, bỏ yêu cầu nộp hồ sơ bản giấy với thủ tục đã xác thực điện tử, đồng thời thống nhất tính thời gian giải quyết theo ngày làm việc để thuận tiện cho người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, đại diện lãnh đạo sở, ngành, đơn vị tỉnh Bắc Ninh nêu, trao đổi những khó khăn, vướng mắc trong quá trình thực hiện TTHC của ngành, lĩnh vực thời gian qua. Các thành viên trong Đoàn công tác đã trực tiếp trao đổi, giải đáp nhiều vấn đề mà UBND tỉnh Bắc Ninh nêu; đồng thời ghi nhận những kiến nghị, đề xuất của tỉnh để tổng hợp, báo cáo.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+6.jpg/279786d8-b558-8a83-8aff-da6ccf33f959?t=1761800489504\" style=\"height: 556px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn bày tỏ cảm ơn Đoàn công tác, coi đây là cơ hội để tỉnh nâng cao nhận thức, tháo gỡ vướng mắc và kiến nghị Trung ương hoàn thiện cơ chế pháp lý. Đồng chí đề xuất Trung ương quan tâm 3 nhóm vấn đề lớn: Hoàn thiện quy định pháp lý, điều khoản chuyển tiếp để linh hoạt xử lý trường hợp người dân chưa có dữ liệu. Xây dựng trung tâm dữ liệu cấp tỉnh với cơ chế phân định rõ thẩm quyền giữa Trung ương và địa phương. Nghiên cứu cơ chế khuyến khích doanh nghiệp tham gia cung cấp dịch vụ công, giảm thủ tục trực tiếp, nâng cao hiệu quả phục vụ.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+2.jpg/7e994fe0-30e1-ec78-d663-1e901951747c?t=1761800512635\" style=\"height: 583px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Tư Pháp Nguyễn Thanh Tịnh k<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">ết luận buổi làm việc.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết luận buổi làm việc, Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh đánh giá cao cách làm quyết liệt, bài bản của Bắc Ninh, khẳng định chủ trương cắt giảm TTHC dựa trên dữ liệu là bước đi tất yếu trong chuyển đổi số quốc gia.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị UBND tỉnh tiếp tục hoàn thiện báo cáo, nêu rõ các vướng mắc về hành chính, công nghệ, pháp lý để Bộ Tư pháp tổng hợp, báo cáo Chính phủ, bảo đảm hoàn thành rà soát, cắt giảm, đơn giản hóa thủ tục trước ngày 15/11/2025.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn công tác xác định Bắc Ninh là địa phương trọng điểm, có thể làm điểm triển khai mô hình cải cách hành chính dựa trên dữ liệu, đồng thời khuyến nghị tỉnh sớm tổ chức công tác tuyên truyền để người dân hiểu, đồng thuận và tham gia giám sát quá trình thực hiện.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-oan-cong-tac-lien-nganh-ve-ra-soat-anh-gia-thu-tuc-hanh-chinh-dua-tren-du-lieu-lam-viec-tai-tinh-bac-ninh-29478603', '', 'Dương Thuỷ', 275, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.571964', 7, 11);
INSERT INTO `sync_articles` VALUES (134, '29472846', 'Đại hội đại biểu Công đoàn Công ty Điện lực Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', 'Đại hội đại biểu Công đoàn Công ty Điện lực Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', '/documents/37632/23288878/30-2.png/73a7313d-fa07-d0e8-5632-b3f3b9f42334?t=1761797051407', '<p>(BNP) - Sáng 30/10, Công đoàn Công ty Điện lực Bắc Ninh tổ chức Đại hội đại biểu lần thứ I, nhiệm kỳ 2025 - 2030.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-2.png/73a7313d-fa07-d0e8-5632-b3f3b9f42334?t=1761797051407\" style=\"height: 576px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Lãnh đạo Công đoàn Tổng Công ty Điện lực miền Bắc chúc mừng&nbsp;Ban Chấp hành Công đoàn Công ty Điện lực Bắc Ninh khóa I.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham dự Đại hội có lãnh đạo Công đoàn Tổng Công ty Điện lực miền Bắc; Ban Giám đốc Công ty Điện lực Bắc Ninh cùng 151 đại biểu đại diện cho gần 1.870 đoàn viên các công đoàn cơ sở thành viên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhiệm kỳ 2021 - 2026, Công đoàn Công ty Điện lực Bắc Ninh luôn bám sát chức năng, nhiệm vụ hoạt động với nội dung “Xây dựng tổ chức Công đoàn vững mạnh”; phát huy tinh thần đoàn kết, chủ động, sáng tạo, đạt được nhiều kết quả tích cực, góp phần thiết thực hoàn thành nhiệm vụ sản xuất kinh doanh, nâng cao đời sống người lao động. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Công đoàn chú trọng đổi mới nội dung, phương thức hoạt động; thực hiện tốt chức năng đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của người lao động. Đồng thời, phối hợp chặt chẽ với bộ phận chuyên môn đẩy mạnh các phong trào thi đua trong lao động sản xuất, phát huy sáng kiến cải tiến kỹ thuật. Các phong trào thi đua thường xuyên được phát động và đẩy mạnh như: Quản lý kỹ thuật; An toàn bảo hộ lao động; Kinh doanh điện; Điện lực quản lý kinh doanh giỏi; Chương trình 5S từ Văn phòng ra lưới điện; Văn hóa an toàn lao động…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, nắm bắt kịp thời tâm tư nguyện vọng và giải quyết những vấn đề bức xúc, cấp bách, nổi cộm của người lao động; các chế độ, chính sách được quan tâm thực hiện, giải quyết nhanh chóng, đúng quy định. Đời sống vật chất, tinh thần của cán bộ công nhân viên được nâng lên rõ rệt, thu nhập bình quân ổn định. Qua đó, tạo động lực, niềm tin để người lao động đoàn kết, gắn bó, hăng say thi đua lao động sản xuất, hoàn thành tốt nhiệm vụ được giao. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-3.png/29f6459e-454f-5bf1-d1e9-e5fc8c770208?t=1761797160101\" style=\"height: 633px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch phụ trách Công đoàn Tổng Công ty Điện lực miền Bắc Trần Tuấn Khanh tặng Giấy khen cho các tập thể xuất sắc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhiều hoạt động an sinh xã hội, đền ơn đáp nghĩa, phụng dưỡng Mẹ Việt Nam Anh hùng, khen thưởng con cán bộ công nhân viên chức, lao động đạt thành tích tốt trong học tập… được duy trì hiệu quả, lan tỏa sâu rộng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, chú trọng nâng cao, kiện toàn tổ chức công đoàn vững mạnh, tập hợp và phát triển đoàn viên, đổi mới nội dung, phương thức hoạt động của tổ chức công đoàn. Hàng năm, có hơn 90% đoàn viên Công đoàn hoàn thành tốt nhiệm vụ trở lên; hơn 90% Công đoàn cơ sở thành viên hoàn thành tốt nhiệm vụ trở lên. Công đoàn Công ty đạt vững mạnh xuất sắc hàng năm…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại hội tập trung thảo luận, chỉ ra những hạn chế, vướng mắc và nguyên nhân; từ đó, đề ra biện pháp khắc phục trong các hoạt động của Công đoàn nhiệm kỳ tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ghi nhận và đánh giá cao những kết quả đạt được của Công đoàn Công ty Điện lực Bắc Ninh trong nhiệm kỳ vừa qua, Phó Chủ tịch phụ trách Công đoàn Tổng Công ty Điện lực miền Bắc Trần Tuấn Khanh đề nghị Công đoàn Công ty tiếp tục giữ vững vai trò đại diện, chăm lo thực chất cho người lao động; chủ động đổi mới phương thức hoạt động công đoàn trong bối cảnh chuyển đổi số; ứng dụng công nghệ thông tin trong điều hành, nâng cao kỹ năng, bản lĩnh cán bộ công đoàn, xứng đáng là chỗ dựa tin cậy cho người lao động… Cùng với đó, thường xuyên đồng hành cùng bộ phận chuyên môn thực hiện thắng lợi nhiệm vụ sản xuất, kinh doanh; đẩy mạnh các phong trào thi đua gắn với các chủ đề năm của Tổng Công ty và Công ty như: “Lao động giỏi, lao động sáng tạo, chuyển đổi số”; “Phát huy sáng kiến cải tiến kỹ thuật”… Tiếp tục thực hiện hiệu quả chương trình 5S, văn hóa doanh nghiệp; đảm bảo an toàn trong vận hành, xử lý sự cố, nói không với tai nạn lao động.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-4.png/ae4bfbea-2e5f-154c-abfb-ef2a54d3f63a?t=1761797353870\" style=\"height: 596px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại biểu biểu quyết thống nhất thông qua Nghị quyết Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại hội được nghe công bố Quyết định chỉ định Ban Chấp hành Công đoàn Công ty Điện lực Bắc Ninh khóa I, nhiệm kỳ 2025 - 2030 gồm 13 đồng chí; chỉ định 09 đại biểu chính thức đi dự Đại hội Công đoàn Tổng Công ty Điện lực miền Bắc, nhiệm kỳ 2025 - 2030. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhân dịp này, 3 tập thể, 6 cá nhân có thành tích xuất sắc trong hoạt động Công đoàn, nhiệm kỳ 2021 - 2026 được nhận Giấy khen của Ban Chấp hành Công đoàn Tổng Công ty Điện lực miền Bắc./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-hoi-ai-bieu-cong-oan-cong-ty-ien-luc-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-29472846', '', 'Linh Ngọc', 189, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.605595', 7, 11);
INSERT INTO `sync_articles` VALUES (135, '29335398', 'Tổ chức phi chính phủ DIVA (Hàn Quốc) làm việc tại tỉnh Bắc Ninh', 'Tổ chức phi chính phủ DIVA (Hàn Quốc) làm việc tại tỉnh Bắc Ninh', '/documents/37632/23288878/2+%285%29.jpg/8fb49834-bab8-7367-89a6-c35fffd6fd00?t=1761726871443', '<p>(BNP) - Chiều 29/10, Tổ chức phi chính phủ DIVA (Hàn Quốc) do ông Kim Wan Yong, Giám đốc đại diện tại Việt Nam làm trưởng đoàn đến thảo luận về định hướng, chương trình, dự án của Tổ chức phi chính phủ DIVA triển khai tại tỉnh Bắc Ninh thời gian tới. Phó Chánh Văn phòng UBND tỉnh Phạm Dương...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/1+%288%29.jpg/2cd60780-410a-606d-5a0f-3beb55fbaf36?t=1761726807073\" style=\"height: 547px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\">Toàn cảnh buổi tiếp.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trao đổi tại buổi tiếp, ông Kim Wan Yong, Giám đốc Tổ chức phi chính phủ DIVA tại Việt Nam cho biết, Tổ chức DIVA là tổ chức phi chính phủ nước ngoài hoạt động trong lĩnh vực cung cấp học bổng và dạy tiếng Hàn, xây nhà cho người nghèo, hỗ trợ vật tư y tế, nước sạch và vệ sinh môi trường, khám chữa bệnh miễn phí với phạm vi hoạt động tại các tỉnh Thái Nguyên, Bắc Giang và Lạng Sơn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ năm 2015, tổ chức DIVA đã bắt đầu thực hiện các hoạt động hỗ trợ tại Việt Nam và chính thức nhận được Giấy đăng ký hoạt động do Cục Ngoại vụ (Bộ Ngoại giao) cấp vào năm 2018.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh là địa phương đang có tốc độ phát triển kinh tế nhanh, nhằm góp phần quan trọng trong chiến lược tăng trưởng&nbsp;kinh tế&nbsp;đi&nbsp;đôi&nbsp;với bảo vệ&nbsp;môi trường, ông Kim Wan Yong mong muốn sẽ được triển khai nhiều dự án nước sạch trên địa bàn tỉnh Bắc Ninh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Do vậy, để triển khai một số dự án của Tổ chức DIVA trên địa bàn tỉnh, Đoàn công tác đã tiến hành khảo sát tại các xã: Xuân Cẩm, Hoàng Vân và Hợp Thịnh và các Trường mầm non: Xuân Cẩm (xã Xuân Cẩm); Ngọc Sơn (xã Hoàng Vân); Mai Trung 2 ( xã Hợp Thịnh) liên quan đến lĩnh vực cải thiện nước sạch vệ sinh cho trường học trên địa bàn tỉnh. Qua đây, phía Tổ chức DIVA mong muốn tỉnh sẽ cung cấp các thông tin chi tiết bằng các cuộc làm việc và văn bản để các dự án được triển khai thiết thực, mang lại lợi ích cho người dân. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/2+%285%29.jpg/8fb49834-bab8-7367-89a6-c35fffd6fd00?t=1761726871443\" style=\"height: 520px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Phó Chánh Văn phòng UBND tỉnh Phạm Dương Tuyến tặng tranh dân gian Đông Hồ cho Đoàn công tác.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo Văn phòng UBND tỉnh, đồng chí Phạm Dương Tuyến bày tỏ vui mừng được đón tiếp ông Kim Wan Yong cùng các thành viên đoàn đến thăm, làm việc. Đồng thời, thông tin đến đoàn công tác một số nét cơ bản về tình hình phát triển kinh tế - xã hội tỉnh Bắc Ninh mới và một số nội dung liên quan đến hoạt động của Tổ chức tại tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những năm gần đây, Bắc Ninh có bước phát triển vượt bậc, vững chắc. Tốc độ tăng trưởng kinh tế hàng năm luôn nằm trong nhóm các tỉnh dẫn đầu cả nước. Trong 9 tháng năm 2025, tỉnh có 09 khu công nghiệp mới được phê duyệt chủ trương đầu tư. Đặc biệt, tỉnh đang được đầu tư xây dựng Sân bay quốc tế Gia Bình, với công suất hàng hoá dự kiến lên tới 2,5 triệu tấn/năm, dự kiến khánh thành vào cuối năm 2026, là tiền đề quan trọng để tiếp tục thúc đẩy kinh tế - xã hội của tỉnh trong giai đoạn tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng UBND tỉnh cũng cho biết, hiện trên địa bàn tỉnh có khoảng 30 tổ chức đăng ký hoạt động. Trong đó có nhiều dự án lớn của các tổ chức phi chính phủ Hàn Quốc tài trợ tại tỉnh. Các chương trình, dự án, khoản viện trợ của các tổ chức phi chính phủ và doanh nghiệp Hàn Quốc triển khai thực hiện tại tỉnh góp phần nâng cao công tác an sinh xã hội, hỗ trợ các đối tượng hưởng lợi là trẻ em, người già, người có hoàn cảnh khó khăn trên địa bàn tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đánh giá cao những đóng góp tích cực từ các dự án viện trợ Tổ chức phi chính phủ DIVA mang lại cho người dân và cộng đồng trong thời gian qua; đề nghị Tổ chức tiếp tục phối hợp với các sở, ban, ngành liên quan của tỉnh để triển khai các dự án, đồng thời tỉnh sẽ tạo điều kiện thuận lợi cho Tổ chức trong việc triển khai các dự án, đảm bảo hiệu quả, phù hợp với nhu cầu thực tiễn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/to-chuc-phi-chinh-phu-diva-han-quoc-lam-viec-tai-tinh-bac-ninh-29335398', '', 'Nguyễn Miền', 145, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.645449', 7, 11);
INSERT INTO `sync_articles` VALUES (136, '29296644', '101 Đảng bộ trực thuộc Tỉnh ủy Bắc Ninh dự hội nghị tập huấn triển khai ứng dụng Sổ...', '101 Đảng bộ trực thuộc Tỉnh ủy Bắc Ninh dự hội nghị tập huấn triển khai ứng dụng Sổ tay đảng viên điện tử', '/documents/37632/23288878/29-1.png/67cd7417-e234-af27-b145-303b2466c7c9?t=1761711477368', '<p>(BNP) - Sáng 29/10, tại Hà Nội, Văn phòng Trung ương Đảng phối hợp với Ban Tổ chức Trung ương tổ chức hội nghị tập huấn triển khai ứng dụng Sổ tay đảng viên điện tử theo hình thức trực tuyến kết nối tới điểm cầu các tỉnh, thành phố trong cả nước.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-1.png/67cd7417-e234-af27-b145-303b2466c7c9?t=1761711477368\" style=\"height: 579px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu Đảng ủy Văn phòng UBND tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại tỉnh Bắc Ninh, hội nghị được kết nối tới 294 điểm cầu tại 101 Đảng bộ trực thuộc Tỉnh ủy với hơn 18.000 đảng viên tham dự.&nbsp; </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự và chủ trì tại điểm cầu Đảng ủy Văn phòng UBND tỉnh có đồng chí Ngô Văn Luyến, Ủy viên Ban Thường vụ Đảng ủy Văn phòng UBND tỉnh, Phó Chánh Văn phòng UBND tỉnh; cấp ủy các chi bộ trực thuộc Đảng ủy Văn phòng UBND tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hội nghị tập huấn cho các cán bộ làm công tác xây dựng Đảng, công tác chuyển đổi số của các cơ quan Đảng trực thuộc Trung ương, Tỉnh ủy, Thành ủy; cấp ủy thuộc tổ chức Đảng cấp trên cơ sở, Đảng bộ cơ sở, chi bộ cơ sở, chi bộ trực thuộc Đảng bộ cấp trên cơ sở, chi bộ trực thuộc Đảng bộ cơ sở.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-3.png/0096f653-60f8-2e1d-4161-e056eb2ab85e?t=1761711530086\" style=\"height: 586px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu Văn phòng Tỉnh ủy Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại hội nghị, các đại biểu được nghe đại diện Cục Chuyển đổi số, Văn phòng Trung ương Đảng phổ biến, quán triệt các nội dung liên quan đến triển khai ứng dụng Sổ tay đảng viên điện tử như: Tổng quan về hệ thống Sổ tay đảng viên điện tử; mô hình và kiến trúc triển khai, hệ thống cài đặt tập trung, thống nhất trong toàn Đảng, sử dụng mọi lúc, mọi nơi trên 2 giao diện Web và Mobile, tích hợp AI hỗ trợ trong công tác Đảng; các chức năng chính của hệ thống và nhóm tính năng theo từng vai trò… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, hướng dẫn cách cài đặt ứng dụng trên các hệ điều hành IOS, ANDROID, trên App điện thoại thông minh; cách đăng nhập trên web bằng tài khoản, đăng nhập bằng VneID; trải nghiệm các tính năng của Sổ tay đảng viên điện tử… Qua đó, giúp cán bộ, đảng viên nắm vững quy trình, kỹ năng sử dụng, sẵn sàng triển khai áp dụng hiệu quả trong thực tiễn.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-4.png/27459f3d-5cac-5dc5-1d4b-e252f077884b?t=1761711584385\" style=\"height: 606px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu xã Văn Môn, tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thông qua hội nghị nhằm tạo sự đồng bộ, thống nhất trong các cơ quan, tổ chức Đảng; hỗ trợ đảng viên trong sinh hoạt Đảng; cung cấp chính xác, kịp thời văn bản, tài liệu của Đảng, Nhà nước, các cấp ủy, tổ chức Đảng; phục vụ việc học tập nghị quyết, thực hiện nhiệm vụ đảng viên… Qua đó, góp phần nâng cao năng lực, trình độ, đạo đức, sức chiến đấu, trách nhiệm nêu gương của đảng viên và thống nhất một nền tảng ứng dụng số, tránh đầu tư dàn trải, lãng phí./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/101-ang-bo-truc-thuoc-tinh-uy-bac-ninh-du-hoi-nghi-tap-huan-trien-khai-ung-dung-so-tay-ang-vien-ien-tu-29296644', '', 'Linh Ngọc', 248, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.680416', 7, 11);
INSERT INTO `sync_articles` VALUES (137, '29278401', 'Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 – 2030 thành...', 'Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 – 2030 thành công tốt đẹp', '/documents/37632/23288878/mt11.png/c84871e7-3d67-4b38-b3c9-4a1ce0a9ea4c?t=1761718741640', '<p>(BNP) – Trong 2 ngày (28 và 29/10), tại Trung tâm Hội nghị tỉnh, Ủy ban MTTQ Việt Nam tỉnh Bắc Ninh long trọng tổ chức Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt11.png/c84871e7-3d67-4b38-b3c9-4a1ce0a9ea4c?t=1761718741640\" style=\"height: 512px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đồng chí lãnh đạo Ủy ban Trung ương MTTQ Việt Nam và tỉnh tặng hoa chúc mừng&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025 - 2030.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự Đại hội, đại biểu Trung ương có đồng chí Đỗ Văn Chiến, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam; lãnh đạo Ủy ban Trung ương MTTQ Việt Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu tỉnh có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy; Thường trực HĐND, lãnh đạo UBND, lãnh đạo Đoàn ĐBQH tỉnh; các đồng chí nguyên Thường trực Tỉnh ủy, UBND tỉnh qua các thời kỳ; Mẹ Việt Nam Anh hùng, Anh hùng Lực lượng vũ trang Nhân dân, Anh hùng Lao động; các đồng chí nguyên lãnh đạo Ủy ban MTTQ tỉnh qua các thời kỳ, lãnh đạo Ủy ban MTTQ một số tỉnh lân cận; lãnh đạo các sở, ban, ngành, địa phương của tỉnh cùng 358 đại biểu chính thức đại diện cho các tầng lớp Nhân dân, các dân tộc, tôn giáo, lực lượng vũ trang, người con Bắc Ninh trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/MTTQ.png/9f168839-a82c-05fd-dac3-d8d4d6b55355?t=1761719427581\" style=\"height: 583px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến tặng Đại hội bức tranh Bác Hồ, Bác Tôn</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiệm kỳ 2024 - 2029, Ủy ban MTTQ tỉnh Bắc Ninh và các tổ chức thành viên đã nỗ lực đổi mới, phát huy vai trò nòng cốt chính trị trong xây dựng khối đại đoàn kết toàn dân, góp phần thực hiện thắng lợi các nhiệm vụ chính trị, thúc đẩy phát triển kinh tế - xã hội, giữ vững quốc phòng - an ninh, nâng cao đời sống Nhân dân; đã hoàn thành và hoàn thành vượt mức nhiều chỉ tiêu, nhiệm vụ nhiệm kỳ đề ra. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, khối Đại đoàn kết toàn dân không ngừng được củng cố, mở rộng và phát huy. Ủy ban MTTQ tỉnh đổi mới mạnh mẽ về nội dung, phương thức, đa dạng các hình thức vận động, gắn với những phong trào thi đua yêu nước, các cuộc vận động thiết thực; chú trọng phát huy vai trò của cá nhân tiêu biểu, người có uy tín, chức sắc tôn giáo trong tuyên truyền, vận động. Qua đó, tinh thần đoàn kết, gắn bó cộng đồng, ý thức tự lực, tự cường trong Nhân dân được khơi dậy mạnh mẽ. Người dân đồng thuận thực hiện các chủ trương đường lối của Đảng, chính sách pháp luật của Nhà nước, góp phần thay đổi diện mạo nông thôn, đô thị ngày càng văn minh, hiện đại.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt10.png/c3c7ed53-aa2f-2c29-fa01-e083eeca2535?t=1761718990364\" style=\"height: 551px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái, Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương, Chủ tịch UBND tỉnh Vương Quốc Tuấn, Chủ tịch HĐND tỉnh Nguyễn Việt Oanh và Phó Chủ tịch UBND tỉnh, Trưởng Đoàn ĐBQH tỉnh Phạm Văn Thịnh (<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">bên phải)&nbsp;</span></span></span></span></span></span></span></span>trao tặng Đại hội bức Trướng \"Đoàn kết - Dân chủ - Đổi mới - Phát triển\".</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cuộc vận động, phong trào thi đua được MTTQ triển khai có trọng tâm, trọng điểm với nhiều mô hình, phần việc cụ thể, thiết thực, khơi dậy mạnh mẽ tinh thần lao động sáng tạo của Nhân dân. Cuộc vận động “Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh\" tiếp tục giữ vai trò nòng cốt, trở thành cuộc vận động mang tính toàn dân, toàn diện, từng bước thay đổi diện mạo đô thị, nông thôn, nâng cao chất lượng đời sống Nhân dân.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong nhiệm kỳ, MTTQ các cấp phối hợp vận động người dân hiến trên 21 nghìn m² đất, đóng góp gần 40 tỷ đồng và trên 33 nghìn ngày công làm các công trình phúc lợi công cộng, góp phần xây dựng hạ tầng nông thôn, đô thị khang trang, hiện đại. Cùng với đó, tích cực chăm lo giáo dục; chăm sóc sức khỏe Nhân dân; xây dựng đời sống văn hóa; xây dựng khu dân cư an toàn, không có tội phạm, tệ nạn xã hội. Năm 2024, toàn tỉnh có 88,2% phường, thị trấn đạt chuẩn văn minh đô thị; 82,5% làng, bản, tổ dân phố văn hóa; 100% thôn, tổ dân phố thực hiện hương ước, quy ước, thực hiện nếp sống mới trong việc cưới, việc tang, lễ hội, xây dựng cộng đồng dân cư an ninh, an toàn, văn minh, hạnh phúc.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt14.png/f381553d-a214-7a3c-47cf-218d36d6ea71?t=1761719764509\" style=\"height: 540px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Chủ tịch điều hành Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác an sinh xã hội, chăm lo người nghèo, người yếu thế cũng để lại nhiều dấu ấn. Bắc Ninh là một trong những tỉnh đi đầu trong cả nước về thực hiện chương trình xóa nhà tạm, nhà dột nát cho hộ nghèo, cận nghèo và gia đình chính sách khó khăn về nhà ở. Sau 15 tháng triển khai, toàn tỉnh hỗ trợ xây dựng, sửa chữa và bàn giao hơn 2.500 nhà trị giá 150 tỷ đồng cho các hộ nghèo, cận nghèo, hộ khó khăn và gia đình chính sách. Qua đó, tạo niềm tin, động lực giúp người nghèo, người có hoàn cảnh đặc biệt khó khăn ổn định cuộc sống, vươn lên thoát nghèo. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hưởng ứng phong trào “Vì người nghèo - Không để ai bị bỏ lại phía sau\", MTTQ các cấp đã tích cực vận động các cơ quan, tổ chức, cá nhân, doanh nghiệp, nhà hảo tâm tham gia xây dựng quỹ “Vì người nghèo” và chương trình an sinh xã hội; hằng năm 100% hộ nghèo được thăm, tặng quà Tết. Công tác tham gia xây dựng Đảng, chính quyền, giám sát và phản biện xã hội tiếp tục được tăng cường, thể hiện rõ hơn vai trò đại diện bảo vệ quyền và lợi ích hợp pháp, chính đáng của đoàn viên, hội viên và Nhân dân.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt7.png/e138038f-2725-7826-de30-9d821ed163cb?t=1761719324995\" style=\"height: 578px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến phát biểu chỉ đạo tại Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với chủ đề “Đoàn kết - Dân chủ - Đổi mới - Phát triển”, nhiệm kỳ 2025 - 2030, Ủy ban MTTQ tỉnh tiếp tục phát huy truyền thống, sức mạnh đại đoàn kết toàn dân; lấy nhân tố con người là trung tâm, là chủ thể, nguồn động lực, mục tiêu chủ yếu của đại đoàn kết dân tộc; tăng cường củng cố liên minh chính trị, tạo đồng thuận xã hội. Đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của Nhân dân. Thực hiện dân chủ, giám sát, phản biện xã hội, tham gia góp ý xây dựng Đảng, xây dựng chính quyền, phòng chống tham nhũng, tiêu cực. Đổi mới mạnh mẽ nội dung, phương thức hoạt động của MTTQ; xây dựng đội ngũ cán bộ Mặt trận đủ năng lực, phẩm chất, sáng tạo, tâm huyết, bản lĩnh, dám làm, dám chịu trách nhiệm, dám đương đầu với khó khăn, thử thách, giỏi dân vận và có khát vọng cống hiến. MTTQ các cấp tích cực vận động các tầng lớp Nhân dân cùng với cấp ủy, chính quyền tự tin, tiến mạnh trong kỷ nguyên phát triển mới của dân tộc; thực hiện thành công mục tiêu đưa Bắc Ninh phát triển nhanh, toàn diện, bền vững, trở thành thành phố trực thuộc Trung ương trước năm 2030 theo hướng văn minh, hiện đại. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt8.png/07f7c3f9-b868-16f4-e773-c24ee89b7e8d?t=1761719498619\" style=\"height: 589px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái phát biểu chỉ đạo tại Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, phấn đấu 100% cán bộ Ủy ban MTTQ và các tổ chức thành viên các cấp được quán triệt, học tập, phổ biến, tuyên truyền các chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước, Chương trình công tác của Mặt trận; 100% khu dân cư tổ chức Ngày hội Đại đoàn kết toàn dân tộc; hằng tháng, hằng quý 100% Ủy ban MTTQ các cấp và các tổ chức thành viên có báo cáo phản ánh kịp thời tình hình Nhân dân và đề xuất giải pháp, phương hướng giải quyết. Hằng năm, Ủy ban MTTQ cấp tỉnh tổ chức giám sát ít nhất 05 chương trình, nội dung; phản biện xã hội ít nhất 05 dự thảo văn bản. MTTQ cấp xã tổ chức giám sát ít nhất 03 chương trình, nội dung; phản biện xã hội ít nhất 03 dự thảo văn bản; tổ chức giám sát các nội dung theo chỉ đạo của cấp trên và những vấn đề được đông đảo quần chúng Nhân dân quan tâm. Hằng năm, tổ chức hoạt động vận động, quyên góp nguồn lực ủng hộ Quỹ “Vì người nghèo” và an sinh xã hội đạt trên 66 tỷ đồng; vận động ủng hộ Tết vì người nghèo đạt 100% hộ nghèo được nhận quà Tết; các hộ khó khăn đặc biệt được hỗ trợ thường xuyên. Phấn đấu đến hết năm 2027, toàn tỉnh không còn hộ nghèo theo chuẩn nghèo đa chiều giai đoạn 2021-2025…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu chỉ đạo tại Đại hội, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến ghi nhận, biểu dương, chúc mừng những kết quả mà Ủy ban MTTQ tỉnh Bắc Ninh đã đạt được trong thời gian vừa qua. Đồng thời, đề nghị thời gian tới, MTTQ tỉnh Bắc Ninh tiếp tục quán triệt sâu sắc nội dung Nghị quyết số 43 của Ban Chấp hành Trung ương Đảng khóa XIII về tiếp tục phát huy truyền thống sức mạnh đại đoàn kết toàn dân tộc, xây dựng đất nước ta ngày càng phồn vinh hạnh phúc. Quán triệt sâu sắc chủ trương quan điểm của Đảng: Dân là gốc, Nhân dân là trung tâm, chủ thể, mục tiêu và động lực của đổi mới. Tập hợp đoàn kết rộng rãi công nhân, nông dân, trí thức, thanh niên, phụ nữ, cựu chiến binh, cựu Công an Nhân dân, doanh nhân, đồng bào dân tộc, đồng bào tôn giáo, người Bắc Ninh sinh sống ngoài tỉnh, đóng góp trí tuệ, công sức, nguồn lực để xây dựng tỉnh Bắc Ninh giàu đẹp, văn minh hiện đại, giàu bản sắc và phấn đấu trở thành thành phố trực thuộc Trung ương trước năm 2030 và đến năm 2045 là thành phố xanh, văn minh hiện đại. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt4.jpg/6478d812-3cb3-9e28-ea19-76fd8c6e5958?t=1761707006326\" style=\"height: 626px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Đồng chí Nguyễn Thị Hà tái cử Chủ tịch Ủy ban MTTQ tỉnh khóa I, nhiệm kỳ 2025 - 2030.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đẩy mạnh công tác giáo dục lịch sử truyền thống, bồi đắp niềm tự hào, khát vọng vươn lên, tinh thần yêu nước, đoàn kết của các tầng lớp Nhân dân tỉnh Bắc Ninh. Phát huy mạnh mẽ dân chủ đồng thuận xã hội, củng cố vững chắc niềm tin của Nhân dân với các cấp ủy Đảng, chính quyền; đẩy mạnh các phong trào thi đua yêu nước, xây dựng khu dân cư đoàn kết, ấm no, hạnh phúc; nâng cao chất lượng công tác giám sát phản biện xã hội, tích cực tham gia xây dựng Đảng, xây dựng chính quyền và hệ thống chính trị trong sạch, vững mạnh. Chủ động đề xuất phối hợp tham gia giải quyết những vấn đề phức tạp, nảy sinh trong thực tiễn, tổ chức đối thoại xã hội, tổ chức \"Tháng nghe dân nói\", tích cực tham gia phòng chống tham nhũng, lãng phí, tiêu cực. Phối hợp giám sát các hoạt động chính quyền, cán bộ đảng viên, người đứng đầu đảm bảo công khai minh bạch, hiệu quả. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, đẩy mạnh thực hiện các cuộc vận động, các phong trào thi đua yêu nước trong các tầng lớp Nhân dân một cách thực chất. Trong đó, tập trung thực hiện tốt Cuộc vận động \"Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh\", Cuộc vận động \"Cả nước chung tay vì người nghèo, không để ai bị bỏ lại phía sau\", Cuộc vận động \"Người Việt Nam ưu tiên dùng hàng Việt Nam\", phong trào \"Bình dân học vụ số\", phong trào \"Cả nước đồng lòng chung sức xây dựng cơ sở hạ tầng đồng bộ hiện đại\"; tích cực đổi mới nội dung phương thức hoạt động của Mặt trận, chú trọng đào tạo, bồi dưỡng, rèn luyện đội ngũ cán bộ có bản lĩnh, tinh thông nghiệp vụ, sát dân, chủ động phục vụ Nhân dân, nhất là đội ngũ cán bộ cấp xã. Triển khai thực hiện hiệu quả Nghị quyết số 57 của Bộ Chính trị về đột phá phát triển khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia. Ứng dụng công nghệ số sâu rộng trong mọi mặt hoạt động của MTTQ Việt Nam, nhất là trong việc nắm tâm tư nguyện vọng của Nhân dân, chuyển tải chủ trương đường lối của Đảng, chính sách pháp luật của Nhà nước đến với Nhân dân. Đồng thời, tham gia tổ chức cuộc bầu cử đại biểu Quốc hội và HĐND các cấp nhiệm kỳ 2026 - 2031, theo chức năng nhiệm vụ của Mặt trận đã được pháp luật quy định, lựa chọn những người đủ đức, đủ tài, đủ sức gánh vác nhiệm vụ đại diện Nhân dân.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt1+%281%29.png/468ca254-2ff9-5601-841a-002883e90f01?t=1761705114569\" style=\"height: 527px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Đồng chí Nguyễn Thị Hà trao Bằng khen của Chủ tịch UBND tỉnh cho các tập thể có thành tích xuất sắc.</span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại Đại hội, thay mặt Ban Chấp hành Đảng bộ tỉnh, Bí thư Tỉnh ủy Nguyễn Hồng Thái ghi nhận, biểu dương và chúc mừng những thành tích mà Ủy ban MTTQ tỉnh, MTTQ các cấp đã đạt được trong nhiệm kỳ vừa qua. Đồng thời, đề nghị thời gian tới, MTTQ các cấp bám sát Nghị quyết số 43 của Ban Chấp hành Trung ương Đảng khóa XIII về “Tiếp tục phát huy truyền thống, sức mạnh đại đoàn kết toàn dân tộc, xây dựng đất nước ta ngày càng phồn vinh, hạnh phúc\"; Dự thảo Văn kiện Đại hội Trung ương MTTQ Việt Nam, Nghị quyết Đại hội đại biểu Đảng bộ tỉnh lần thứ I, nhiệm kỳ 2025-2030 và các Nghị quyết, chỉ thị, kế hoạch của tỉnh để xác định đúng trọng tâm, trọng điểm trong nhiệm kỳ mới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp tục phát huy vai trò nòng cốt của MTTQ trong xây dựng, củng cố, tăng cường và phát huy sức mạnh khối đại đoàn kết toàn dân; xác định rõ đây là nhiệm vụ quan trọng hàng đầu của MTTQ các cấp; tích cực đổi mới phương thức, cơ chế hoạt động của MTTQ và các tổ chức chính trị - xã hội theo hướng sâu sát với dân; hướng mạnh về cơ sở, đa dạng hóa các hình thức tập hợp và giải quyết tốt mối quan hệ lợi ích giữa các tầng lớp Nhân dân; phát huy vai trò của lực lượng nòng cốt, các cá nhân tiêu biểu, có uy tín trong các dân tộc, tôn giáo. Đồng thời, quan tâm đẩy mạnh và đổi mới, năng cao chất lượng, hiệu quả các cuộc vận động, phong trào thi đua yêu nước theo hướng thiết thực, phù hợp với từng khu vực, đối tượng, điều kiện thực tiễn, đáp ứng nguyện vọng của Nhân dân. Triển khai đa dạng, linh hoạt, sáng tạo các hoạt động nhằm phát huy tiềm năng, trí tuệ, hiệu triệu mọi tầng lớp Nhân dân thể hiện khát vọng vươn lên, cống hiến, tham gia thực hiện các nhiệm vụ phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt2+%282%29.png/73141c69-6e99-3dd9-6f3c-5d334085ed84?t=1761720120970\" style=\"height: 528px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Các tập thể có thành tích xuất sắc nhận Bằng khen của Chủ tịch UBND tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, tích cực phối hợp với các cấp, các ngành đẩy mạnh cải cách hành chính, chuyển đổi số trong quản lý, điều hành, kết nối thông tin với Nhân dân; đẩy mạnh phong trào “bình dân học vụ số\" tại các khu dân cư. Tăng cường vai trò giám sát, phản biện xã hội của MTTQ và các đoàn thể. Phát huy vai trò MTTQ trong thực hiện dân chủ ở cơ sở. Phát huy ngày càng hiệu quả bài học lớn về “Trọng dân, gần dân, sát dân, hiểu dân, an dân”, tạo sự đồng thuận trong xã hội, hướng tới mục tiêu “Đảng nói dân tin, chính quyền làm dân ủng hộ, MTTQ và các đoàn thể vận động dân theo”, xứng đáng là cầu nối giữa Nhân dân với Đảng, chính quyền. Đồng thời, quan tâm chăm lo công tác cán bộ MTTQ, nhất là cán bộ cơ sở thực sự nhiệt huyết, năng lực, uy tín và am hiểu thực tiễn, “Tận tụy để dân mến - Trách nhiệm để dân thương - Kỷ cương để dân trọng - Năng động để dân được nhờ\"; mỗi cán bộ Mặt trận phải là hạt nhân đoàn kết, mở rộng các hoạt động đối ngoại Nhân dân, tích cực vận động, tập hợp, đoàn kết, phát huy vai trò của cộng đồng người Bắc Ninh ở trong nước và ở nước ngoài hướng về xây dựng quê hương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại hội tiến hành hiệp thương cử 119 đại biểu tham gia Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025-2030; hiệp thương cử 16 đại biểu chính thức và 02 đại biểu dự khuyết dự Đại hội đại biểu MTTQ Việt Nam lần thứ XI, nhiệm kỳ 2026 - 2031.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Hội nghị lần thứ Nhất của Ủy ban MTTQ tỉnh khóa I, nhiệm kỳ 2025-2030 đã hiệp thương cử các chức danh trong Ban Thường trực Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025-2030. Trong đó, đồng chí Nguyễn Thị Hà tái cử Chủ tịch Ủy ban MTTQ tỉnh; các Phó Chủ tịch gồm các đồng chí: Ngụy Thị Tuyến, Nguyễn Nhân Chinh, Thạch Văn Chung, Nguyễn Hoàng Trung, Nguyễn Phương Mai, Nguyễn Đức Thuận, Trần Văn Đăng, Trần Quang Đạo, Ngô Biên Cương, Nguyễn Văn Triển, Thái Hải Anh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt5+%281%29.png/dffc3d37-6bde-c9ce-84ba-5bc2561a7b28?t=1761719943041\" style=\"height: 522px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiết mục văn nghệ chào mừng Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, Chủ tịch UBND tỉnh tặng Bằng khen cho 15 tập thể, 20 cá nhân có thành tích xuất sắc trong thực hiện Chương trình phối hợp, thống nhất hành động và triển khai&nbsp;thực hiện Nghị quyết Đại hội đại biểu MTTQ&nbsp;Việt Nam các cấp tỉnh Bắc Ninh nhiệm kỳ 2024-2029; Ủy ban MTTQ tỉnh tặng Bằng khen cho 20 tập thể, 13 cá nhân đã có thành tích xuất sắc tiêu biểu trong công tác xây dựng khối Đại đoàn kết toàn dân tộc giai đoạn 2024-2029./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-ai-hoi-ai-bieu-mttq-viet-nam-tinh-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-thanh-cong-tot-ep-29278401', '', 'Nguyễn Nhàn', 295, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.736725', 7, 11);
INSERT INTO `sync_articles` VALUES (138, '29188141', 'Tòa án Nhân dân tỉnh Bắc Ninh – Phát huy truyền thống, vững bước tương lai', 'Tòa án Nhân dân tỉnh Bắc Ninh – Phát huy truyền thống, vững bước tương lai', '/documents/37632/23288878/pv-1-final.jpg/a5293144-50a6-4813-bd19-92063e6a8626?t=1761650414537', '<p>Từ những ngày đầu gian khó của chính quyền cách mạng non trẻ, đến nay, TAND hai cấp tỉnh Bắc Ninh (sau sáp nhập) đã trở thành một biểu tượng của công lý, vững mạnh về tổ chức,&nbsp;tinh thông&nbsp;về nghiệp vụ và luôn tận tâm phục vụ nhân dân.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv-1-final.jpg/a5293144-50a6-4813-bd19-92063e6a8626?t=1761650414537\" style=\"height: 474px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Một chặng đường lịch sử nhiều dấu mốc quan trọng</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với sự ra đời và phát triển của ngành TAND, TAND hai cấp tỉnh Bắc Ninh trải qua một chặng đường lịch sử với nhiều dấu mốc quan trọng. Trải qua các giai đoạn sáp nhập, chia tách, hợp nhất địa giới hành chính, tên gọi và tổ chức bộ máy của TAND tỉnh cũng có những thay đổi để phù hợp với yêu cầu thực tiễn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song hành cùng với sự ra đời của nhà nước ta, TAND tỉnh Bắc Giang và TAND tỉnh Bắc Ninh được thành lập. Năm 1962, Quốc hội khóa II thông qua Nghị quyết hợp nhất hai tỉnh Bắc Ninh và Bắc Giang thành tỉnh Hà Bắc. Tòa án nhân dân tỉnh Hà Bắc chính thức làm việc từ ngày 01/4/1963. Năm 1996, Quốc hội khóa IX ban hành Nghị quyết chia tách địa giới hành chính của tỉnh Hà Bắc thành hai tỉnh Bắc Giang và Bắc Ninh. Tòa án nhân dân tỉnh Bắc Giang, TAND tỉnh Bắc Ninh được tái lập và hoạt động từ ngày 01/01/1997.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với sự nghiệp công nghiệp hóa, hiện đại hóa của cả nước, tỉnh Bắc Ninh (cũ) và Bắc Giang (cũ) đã có sự phát triển vượt bậc về kinh tế - xã hội, văn hóa, an ninh chính trị; trật tự an toàn xã hội được giữ vững. Trải qua gần 20 năm xây dựng và trưởng thành, hàng năm TAND tỉnh Bắc Ninh (cũ), TAND tỉnh Bắc Giang (cũ) đã trực tiếp và chỉ đạo các TAND huyện, thị xã, thành phố trên địa bàn tỉnh xét xử, giải quyết hàng nghìn vụ việc các loại, góp phần giữ vững an ninh chính trị, trật tự an toàn xã hội, tạo môi trường pháp lý thuận lợi cho phát triển kinh tế - xã hội tại địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thực hiện Nghị quyết của Bộ Chính trị và Quốc hội, từ ngày 01/7/2025, hai tỉnh Bắc Ninh và Bắc Giang chính thức hợp nhất thành một đơn vị hành chính mới - tỉnh Bắc Ninh. Đây là sự kiện chính trị - hành chính có ý nghĩa lịch sử, mở ra một giai đoạn phát triển mới cho vùng đất giàu truyền thống cách mạng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">TAND hai cấp tỉnh Bắc Ninh mới được kiện toàn trên cơ sở hợp nhất TAND tỉnh Bắc Ninh và TAND tỉnh Bắc Giang trước đây; các TAND cấp huyện kết thúc hoạt động, thành lập 9 TAND khu vực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Chánh án TAND tỉnh Bắc Ninh - Mai Anh Tài, đây là một dấu mốc lịch sử là bước chuyển quan trọng trong tiến trình đổi mới tổ chức bộ máy Tòa án theo tinh thần cải cách tư pháp và sắp xếp lại đơn vị hành chính; thể hiện quyết tâm cải cách, hiện đại hóa nền tư pháp, đáp ứng yêu cầu xây dựng Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc sáp nhập tỉnh Bắc Giang và tỉnh Bắc Ninh là một chủ trương lớn, mang tính chiến lược của Đảng và Nhà nước nhằm tinh gọn bộ máy, nâng cao hiệu lực, hiệu quả hoạt động của hệ thống chính trị. Với vai trò là cơ quan xét xử ở địa phương, TAND tỉnh Bắc Ninh đã chủ động triển khai đồng bộ các giải pháp để bảo đảm sớm ổn định tổ chức bộ máy, duy trì hiệu quả công tác xét xử trong giai đoạn chuyển tiếp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ổn định nhanh sau sáp nhập, giữ vững nhịp cầu công lý</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay từ khi có chủ trương, TAND hai tỉnh Bắc Giang và Bắc Ninh cũ đã phối hợp chặt chẽ để chuẩn bị tốt các điều kiện sáp nhập, bảo đảm tính đồng bộ, thống nhất và ổn định. TAND hai tỉnh đã đề ra lộ trình, từ sắp xếp cán bộ, cơ sở vật chất, đến quản trị nội bộ với mục tiêu xuyên suốt là không để công tác xét xử bị gián đoạn, đảm bảo tốt quyền và lợi ích hợp pháp của người dân trong mọi hoàn cảnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chia sẻ với phóng viên, Chánh án Mai Anh Tài cho biết, TAND tỉnh đã thực hiện nghiêm túc việc rà soát, đánh giá tổng thể đội ngũ cán bộ, công chức, từ đó bố trí, phân công hợp lý theo năng lực, sở trường, bảo đảm không có tình trạng xáo trộn gây ảnh hưởng đến công việc.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>“Chúng tôi đặt trọng tâm vào xây dựng khối đoàn kết nội bộ, phát huy truyền thống tốt đẹp của hai đơn vị cũ, đồng thời xây dựng văn hóa Tòa án mới - thống nhất, dân chủ, kỷ cương và trách nhiệm. Bầu không khí đoàn kết, sẻ chia, vì nhiệm vụ chung đã được duy trì ngay từ đầu, giúp quá trình chuyển tiếp diễn ra trong tinh thần chủ động, tích cực và trách nhiệm cao”,&nbsp;</i>Chánh án Mai Anh Tài chia sẻ<i>.</i></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các vị trí lãnh đạo chủ chốt được kiện toàn kịp thời, bảo đảm sự chỉ đạo xuyên suốt, đồng bộ trong Tòa án hai cấp. Bên cạnh đó, các đơn vị chuyên môn, tổ chức Đảng, đoàn thể cũng được củng cố nhanh chóng, giữ vững kỷ luật, kỷ cương công vụ trong toàn hệ thống. Tinh thần đổi mới, trách nhiệm và sáng tạo đã được lan tỏa rộng khắp trong đội ngũ cán bộ, công chức TAND tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv2-final.jpg/59d6b04f-f234-9ec9-977c-920d14f39b5a?t=1761650544196\" style=\"height: 486px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay trong thời điểm sáp nhập, đơn vị xác định việc bảo đảm xét xử thông suốt là nhiệm vụ ưu tiên hàng đầu. Do đó, Tòa án đã thực hiện song song hai việc: ổn định tổ chức bộ máy và duy trì tiến độ giải quyết, xét xử các vụ việc theo kế hoạch. Các bộ phận duy trì hoạt động bình thường, không để bất kỳ vụ việc nào bị đình trệ.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>“Chúng tôi thực hiện đúng lịch xét xử, đảm bảo quyền tiếp cận công lý của người dân không bị gián đoạn dù có nhiều khó khăn trong thời điểm sáp nhập đồng thời là cuối năm công tác. Để giữ vững nhịp cầu công lý, hoàn thành chỉ tiêu đăng ký, chúng tôi đã làm việc không quản ngày đêm,</i>&nbsp;<i>xét xử cả ngày thứ 7 và chủ nhật”</i>, Chánh án Mai Anh Tài nhấn mạnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, TAND tỉnh cũng triển khai ứng dụng công nghệ thông tin vào công tác điều hành, quản lý hồ sơ và xét xử. Đơn vị đẩy mạnh xử lý văn bản điện tử, tổ chức các phiên họp và xét xử trực tuyến trong điều kiện phù hợp, góp phần nâng cao hiệu quả công việc, tiết kiệm thời gian và chi phí cho người dân cũng như các cơ quan tiến hành tố tụng. Đây là bước chuyển đổi quan trọng, giúp Tòa án thích ứng linh hoạt với yêu cầu cải cách tư pháp trong bối cảnh mới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Phát huy truyền thống, viết tiếp trang sử vàng</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trải qua 80 năm xây dựng và trưởng thành, dưới sự lãnh đạo của Đảng, TANDTC, Tỉnh ủy, sự phối hợp của HĐND, UBND cùng sự đồng hành của các cơ quan, đoàn thể, TAND hai cấp tỉnh Bắc Ninh đã trưởng thành về nhiều mặt. Từ khi thành lập đến nay, TAND hai cấp tỉnh Bắc Ninh luôn bám sát yêu cầu nhiệm vụ cách mạng, thường xuyên gắn việc thực hiện nhiệm vụ chính trị của Tòa án với nhiệm vụ chính trị của địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong công tác xét xử, các Tòa án luôn chú trọng nâng cao chất lượng tranh tụng tại phiên tòa theo hướng thực chất, bảo đảm tính dân chủ, công khai, đúng quy định pháp luật, qua đó bảo vệ quyền và lợi ích hợp pháp của Nhà nước, tổ chức, cá nhân . Đối với các vụ việc dân sự, hành chính, Tòa án hai cấp đặc biệt coi trọng công tác hòa giải, đối thoại, giúp đương sự rút ngắn thời gian giải quyết tranh chấp và hiệu quả hơn do các bên tự giác thực hiện thỏa thuận.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/phien-xet-xu.jpg/75fa222b-a95b-91d7-4b9d-0ddcb9cf0787?t=1761650593353\" style=\"height: 630px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác thi hành án hình sự đảm bảo 100% người bị kết án khi bản án có hiệu lực pháp luật đều được ra quyết định thi hành án, việc giảm thời hạn chấp hành hình phạt tù đối với phạm nhân đang cải tạo đều được thực hiện đúng quy định của pháp luật. Tòa án hai cấp tỉnh đã hoàn thành xuất sắc nhiệm vụ xét xử các loại án, góp phần thực hiện thắng lợi nhiệm vụ chính trị của địa phương và bảo đảm an ninh trật tự trên địa bàn. Đặc biệt, thực hiện việc triển khai cập nhật dữ liệu lên phần mềm quản lý án, TAND tỉnh Bắc Ninh là đơn vị hoàn thành 100% khối lượng công việc và báo cáo sớm nhất trước ngày 31/8/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bước sang giai đoạn mới, công tác cải cách tư pháp đang được tiến hành mạnh mẽ; tình hình an ninh, trật tự an toàn xã hội và tội phạm có nhiều diễn biến phức tạp, đòi hỏi đội ngũ Thẩm phán, cán bộ, công chức TAND tỉnh Bắc Ninh phải giữ vững phẩm chất, bản lĩnh chính trị, không ngừng rèn luyện, nâng cao trình độ chuyên môn, nghiệp vụ để hoàn thành tốt nhiệm vụ mà Đảng và nhân dân giao phó, đáp ứng tốt những yêu cầu đặt ra đối với công tác TAND trong tình hình mới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv3-final.jpg/fde9e74b-c49d-47c7-befc-d29b1f83a4f6?t=1761650658138\" style=\"height: 438px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Chánh án Mai Anh Tài, TAND tỉnh Bắc Ninh sẽ tiếp tục nâng cao chất lượng xét xử; đẩy mạnh cải cách tư pháp, ứng dụng mạnh mẽ chuyển đổi số, xây dựng Tòa án điện tử, nâng cao tính minh bạch, hiệu quả và phục vụ nhân dân ngày càng tốt hơn; chú trọng công tác đào tạo, bồi dưỡng đội ngũ cán bộ nhằm đáp ứng yêu cầu ngày càng cao của công tác Tòa án. Tăng cường phối hợp với các cơ quan tố tụng, chính quyền, đoàn thể để hoàn thành tốt nhiệm vụ chính trị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước bối cảnh số lượng án Tòa án hai cấp thụ lý, giải quyết hàng năm tăng, tính chất các loại vụ án ngày càng phức tạp, cùng với một số khó khăn về cơ sở vật chất, trụ sở làm việc… sau sáp nhập là thách thức lớn với đơn vị.&nbsp;<i>“Nhưng để viết tiếp trang sử vàng của ngành, chúng tôi đã vượt qua khó khăn,</i>&nbsp;<i>thách thức bằng sự đoàn kết, quyết tâm và sáng tạo,&nbsp;giữ vững kỷ cương, kỷ luật trong công việc”</i>, Chánh án Tài khẳng định.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/co-thi-dua-tand-bac-ninh.jpg/033706e8-31fd-370e-8c00-c1027fa98845?t=1761650728549\" style=\"height: 682px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với những kết quả đã đạt được trong nhiều năm phấn đấu, nỗ lực của các thế hệ cán bộ công chức, nhiều đơn vị trong TAND hai cấp tỉnh Bắc Ninh đã vinh dự được tặng thưởng: Huân chương lao động hạng Nhất, Cờ thi đuacủa Chính phủ, Cờ thi đua TAND, Cờ thi đua của UBND tỉnh.... Và mới đây, tại Đại hội thi đua yêu nước TAND lần thứ V, Tòa án tỉnh Bắc Ninh tiếp tục vinh dự được nhận “Cờ thi đua Tòa án nhân dân” giai đoạn 2020-2025 vì có thành tích xuất sắc trong công tác. Đây là sự ghi nhận của Đảng, Nhà nước đối với những đóng góp quan trọng của TAND hai cấp tỉnh Bắc Ninh; đồng thời cũng là nguồn cổ vũ, động viên to lớn, là niềm tự hào sâu sắc của các thế hệ cán bộ, công chức, người lao động trong đơn vị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát huy truyền thống vẻ vang 80 năm xây dựng và phát triển, TAND hai cấp tỉnh Bắc Ninh quyết tâm thực hiện tốt lời dạy của Chủ tịch Hồ Chí Minh đối với cán bộ Tòa án: “Phụng công, thủ pháp, chí công, vô tư”. Với khẩu hiệu “liêm chính, công bằng, trách nhiệm, vượt khó, đổi mới, hiệu quả”, tin tưởng rằng TAND tỉnh Bắc Ninh sẽ tiếp tục là một trong những đơn vị dẫn đầu, nối dài trang sử vàng, cùng hệ thống Tòa án nói riêng và đất nước nói chung vững bước tiến vào kỷ nguyên vươn mình của dân tộc.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/toa-an-nhan-dan-tinh-bac-ninh-phat-huy-truyen-thong-vung-buoc-tuong-lai-29188141', '', 'Congly.vn', 307, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.787232', 7, 11);
INSERT INTO `sync_articles` VALUES (139, '29168064', 'Bắc Ninh triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính dựa trên thành...', 'Bắc Ninh triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính dựa trên thành phần hồ sơ thay thế bằng dữ liệu', '/documents/37632/23288878/TTHC.jpg/62a71b7f-4a26-8c98-7f53-88305accd5b0?t=1761639592455', '<p>(BNP) - Chủ tịch UBND tỉnh vừa ban hành&nbsp;<a href=\"/documents/37632/23288878/4049-UBND-HCC.pdf/73c3c70e-423e-a795-51c9-67ca6ade83a0?t=1761639423807\">Công văn số 4049/UBND-HCC </a>về việc triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính (TTHC) dựa trên thành phần hồ sơ thay thế...', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><img src=\"/documents/37632/23288878/TTHC.jpg/62a71b7f-4a26-8c98-7f53-88305accd5b0?t=1761639592455\" style=\"width: 900px; height: 596px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm tạo thuận lợi, cắt giảm thời gian, chi phí cho cá nhân, tổ chức, góp phần thúc đẩy phát triển kinh tế, Chủ tịch UBND tỉnh yêu cầu các sở, ban, ngành thuộc UBND tỉnh trên cơ sở hướng dẫn của Bộ Tư pháp khẩn trương rà soát đối với 734 TTHC kèm theo Công văn số 6723/BTP-CTXDVBQPPL, Công văn số 4735/TCT và các TTHC khác có chứa 01 trong 153 loại giấy tờ đã có thông tin trên các cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành có thể cắt giảm ngay; đề xuất phương án cắt giảm, đơn giản hóa TTHC, trong đó xác định rõ điều, khoản, điểm tại các văn bản quy phạm pháp luật có chứa TTHC của tỉnh cần sửa đổi, bổ sung để bảo đảm thực thi phương án đơn giản hóa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với các TTHC đặc thù do địa phương ban hành, các đơn vị rà soát, tham mưu cơ quan có thẩm quyền sửa đổi, bổ sung các văn bản quy phạm pháp luật để thực hiện việc cắt giảm hoặc không yêu cầu cá nhân, tổ chức cung cấp thành phần hồ sơ mà thông tin đã có trong các cơ sở dữ liệu, thời hạn hoàn thành trước ngày 15/11/2025 hoặc trong kỳ họp HĐND gần nhất.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong quá trình triển khai thực hiện các nhiệm vụ về bố trí kinh phí chuyển đổi số của các sở, ban, ngành về giải quyết TTHC cho người dân, doanh nghiệp và các lĩnh vực khác có liên quan, nếu gặp khó khăn, vướng mắc gửi Văn phòng UBND tỉnh (Trung tâm Phục vụ hành chính công) tổng hợp, báo cáo về Công an tỉnh để tổng hợp, hoàn thiện báo cáo Bộ Công an.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Tư pháp chủ trì, hướng dẫn các sở, ban, ngành thực hiện rà soát cụ thể đối với các TTHC có thành phần hồ sơ là 01 trong 15 loại giấy tờ đã có trong dữ liệu, có thể cắt giảm trên cơ sở hướng dẫn của Bộ Tư pháp tại Công văn số 6723/BTP-CTXDVBQPPL; kịp thời báo cáo, tham mưu, đề xuất UBND tỉnh xem xét, chỉ đạo đối với những khó khăn, vướng mắc vượt thẩm quyền.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Văn phòng UBND tỉnh (Trung tâm Phục vụ hành chính công tỉnh) phối hợp với Sở Tư pháp trong việc hướng dẫn, đôn đốc các sở, ban, ngành thuộc UBND tỉnh thực hiện các nội dung theo yêu cầu tại Công văn này, bảo đảm đầy đủ nội dung và thời gian quy định./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-ra-soat-cat-giam-on-gian-hoa-thu-tuc-hanh-chinh-dua-tren-thanh-phan-ho-so-thay-the-bang-du-lieu-29168064', '', 'Dương Thuỷ', 129, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.823982', 7, 11);
INSERT INTO `sync_articles` VALUES (140, '29169454', 'Đoàn công tác Công ty QXQ Inc, Hoa Kỳ đến tìm hiểu môi trường đầu tư tại tỉnh Bắc Ninh', 'Đoàn công tác Công ty QXQ Inc, Hoa Kỳ đến tìm hiểu môi trường đầu tư tại tỉnh Bắc Ninh', '/documents/37632/23288878/2+%284%29.jpg/64304d96-4f21-f93d-f676-8ac8613b5ceb?t=1761639386449', '<p>(BNP) - Chiều 28/10, tại Văn phòng UBND tỉnh, Đoàn công tác do ông Quan Roger Chi, Chủ tịch Công ty QXQ Inc, Hoa Kỳ đã đến tìm hiểu môi trường đầu tư tỉnh Bắc Ninh. Phó Giám đốc Sở Tài chính Vũ Thị Phương Thảo chủ trì buổi tiếp và làm việc với đoàn. Cùng dự có đại diện lãnh đạo Văn phòng UBND...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/2+%284%29.jpg/64304d96-4f21-f93d-f676-8ac8613b5ceb?t=1761639386449\" style=\"height: 485px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh buổi tiếp.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo tỉnh, Phó Giám đốc Sở Tài chính Vũ Thị Phương Thảo bày tỏ vui mừng&nbsp;được đón tiếp và&nbsp;làm việc với Đoàn công tác Công ty QXQ Inc. Đồng thời thông tin khái quát về tình hình thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025, kế hoạch phát triển kinh tế - xã hội năm 2026 của tỉnh. Trong đó nhấn mạnh về lợi thế của tỉnh trong phát triển công nghiệp điện tử, công nghệ cao, công nghệ bán dẫn và các chính sách hỗ trợ đầu tư, định hướng thu hút đầu tư của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh là tỉnh tiếp giáp thủ đô Hà Nội, có mạng lưới giao thông thuận tiện dễ dàng kết nối với sân bay, cảng biển và sang Trung Quốc (cách sân bay Nội Bài 40 km, cách cảng Hải Phòng khoảng 90 km, cách cửa khẩu Quốc tế Hữu Nghị quan sang Trung Quốc khoảng 100 km). Đặc biệt, tỉnh đang được đầu tư xây dựng sân bay quốc tế Gia Bình, với công suất hàng hóa dự kiến lên tới 2,5 triệu tấn/năm, dự kiến khánh thành vào cuối năm 2026.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Bắc Ninh đã quy hoạch có 52 KCN với tổng diện tích 15.202ha; 43 KCN được phê duyệt Quy hoạch với diện tích 13.141ha; 35 KCN được được chấp thuận chủ trương đầu tư với tổng diện tích khoảng 10.495,86 ha; 17 dự án hạ tầng KCN cơ bản lấp đầy. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lũy kế đến thời điểm hiện tại, Ban Quản lý các KCN tỉnh đã cấp phép cho 2.881 dự án đầu tư thứ cấp, với tổng vốn cấp mới và điều chỉnh đạt 46.456,08 triệu USD. Các tập đoàn lớn đầu tư tại các KCN sử dụng công nghệ hiện đại, có dây chuyền sản xuất lớn đã làm thay đổi cơ cấu sản phẩm công nghiệp của&nbsp;tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2026, dự kiến doanh thu của các doanh nghiệp KCN năm 2026 đạt khoảng 2.097.000 tỷ đồng; giá trị xuất nhập khẩu của các doanh nghiệp KCN năm 2026 đạt khoảng 126,4 tỷ USD. Tỉnh tiếp tục tập trung phát triển công nghiệp mũi nhọn đi đôi với bảo vệ môi trường, đảm bảo 100% KCN đi vào hoạt động có hệ thống xử lý nước thải tập trung đạt chuẩn môi trường. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song song với phát triển kinh tế, tỉnh luôn quan tâm, ưu tiên phát triển chính sách giáo dục, đào tạo để cung cấp nguồn nhân lực chất lượng cao. Hạ tầng khu, cụm công nghiệp được đầu tư đồng bộ, mạnh mẽ, bao gồm hệ thống điện, nước, kết nối giao thông, đảm bảo sản xuất ổn định cho các doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với việc cải cách mạnh mẽ thủ tục hành chính, các chính sách ưu đãi, hỗ trợ nhà đầu tư được lãnh đạo UBND tỉnh đặc biệt quan tâm. Những năm gần đây, Bắc Ninh luôn đứng trong top đầu cả nước về thu hút đầu tư FDI, với sự có mặt của tập đoàn lớn trên thế giới như: Samsung, Canon, Amkor, Goertek, Hana Micron.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/3+%283%29.jpg/c350e422-ecfc-e210-90d1-dfb075db2ab0?t=1761639573080\" style=\"height: 527px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Các đại biểu chụp ảnh lưu niệm với đại diện&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\">Công ty QXQ Inc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi tiếp, ông Quan Roger Chi, Chủ tịch QXQ Inc cho biết Công ty QXQ Inc chuyên thiết kế và sản xuất công cụ kiểm thử cho các ngành điện tử, tiêu dùng, ô tô, hàng không vũ trụ, R&amp;D... Đây là lĩnh vực đang được nhiều khách hàng lớn tin tưởng, đặt hàng tìm hiểu thị trường, đầu tư, sản xuất, chuyển giao công nghệ.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Qua buổi tiếp, làm việc với lãnh đạo sở, ban, ngành của tỉnh, ông Quan Roger Chi mong muốn được trao đổi, tìm hiểu sâu hơn về quy trình thủ tục tài chính liên quan đến hoạt động đầu tư, tình hình phát triển hạ tầng, quy hoạch đất cho các khu, cụm công nghiệp, các ưu đãi đầu tư… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, các nội dung câu hỏi của Đoàn công tác được lãnh đạo Sở Tài chính, Ban Quản lý các KCN tỉnh trao đổi cởi mở, trực tiếp giải đáp đầy đủ, thể hiện tinh thần hợp tác, trách nhiệm, cam kết đồng hành, tạo điều kiện thuận lợi nhất để các nhà đầu tư, các tập đoàn kinh tế có môi trường đầu tư, kinh doanh thông thoáng, minh bạch, ổn định lâu dài, đóng góp cho sự phát triển kinh tế - xã hội của tỉnh./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/-oan-cong-tac-cong-ty-qxq-inc-hoa-ky-en-tim-hieu-moi-truong-au-tu-tai-tinh-bac-ninh-29169454', '', 'Nguyễn Miền', 603, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-11-01 07:12:50.860324', 7, 11);
INSERT INTO `sync_articles` VALUES (141, '29177402', 'HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN', 'HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/2/17/ktvn-1739759304211364774278-0-52-446-766-crop-17397593207611335673681.jpeg', '<p>Ngân hàng HSBC đánh giá Việt Nam đang duy trì tốc độ tăng trưởng hàng đầu khu vực. Sau khi GDP quý III/2025 tăng 8,2%, HSBC nâng dự báo tăng trưởng GDP năm 2025 lên 7,9%, cho thấy nền kinh tế đang phục hồi toàn diện.</p>', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"justify-content:space-between\"></span></span></span></span><span style=\"font-size:17px\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:column\"><span style=\"position:relative\"><span style=\"transition:0.3s ease-in-out\"><span style=\"z-index:96\"><span style=\"overflow-wrap:break-word\"><span style=\"cursor:default\"><span style=\"color:#333333\"><span style=\"font-family:NotoSerif\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"font-weight:400\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><span style=\"box-sizing:border-box\"><span style=\"float:right\"><span style=\"display:block\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:row\"></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style=\"font-size:17px\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:column\"><span style=\"position:relative\"><span style=\"transition:0.3s ease-in-out\"><span style=\"z-index:96\"><span style=\"overflow-wrap:break-word\"><span style=\"cursor:default\"><span style=\"color:#333333\"><span style=\"font-family:NotoSerif\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"font-weight:400\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><span style=\"box-sizing:border-box\"><span style=\"float:right\"><span style=\"display:block\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:row\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"justify-content:space-between\"><a class=\"kbwscwlrl-thumb-avata\" href=\"https://baochinhphu.vn/hsbc-ky-vong-viet-nam-tang-truong-nhanh-nhat-asean-trong-nam-2025-102250217093019447.htm\" style=\"box-sizing:border-box; padding:0px; text-decoration:none; color:-webkit-link; flex-basis:100px; flex-shrink:0; display:inline-block\" target=\"_blank\"><img alt=\"HSBC: Kỳ vọng Việt Nam tăng trưởng nhanh nhất ASEAN trong năm 2025\" loading=\"lazy\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/2/17/ktvn-1739759304211364774278-0-52-446-766-crop-17397593207611335673681.jpeg\" style=\"box-sizing: border-box; padding: 0px; width: 100%; max-width: 100%; display: block; text-align: justify;\" title=\"HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN- Ảnh 2.\" /></a></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style:normal\"><span style=\"font-variant:normal\"><span style=\"font-size-adjust:none\"><span style=\"font-kerning:auto\"><span style=\"font-optical-sizing:auto\"><span style=\"font-feature-settings:normal\"><span style=\"font-variation-settings:normal\"><span style=\"font-weight:normal\"><span style=\"font-stretch:normal\">Ngân hàng HSBC đánh giá Việt Nam đang duy trì tốc độ tăng trưởng hàng đầu khu vực</span></span></span></span></span></span></span></span></span></span></span></span></span></p>\n\n<figure class=\"VCSortableInPreviewMode\" style=\"box-sizing:border-box; padding:0px; display:inline-block; flex-direction:column; position:relative; transition:0.3s ease-in-out; width:776.997px; z-index:96; overflow-wrap:break-word; cursor:default; color:#333333; font-family:NotoSerif; font-size:17px; font-style:normal; font-variant-ligatures:normal; font-weight:400; text-align:start; white-space:normal; background-color:#ffffff; text-decoration-thickness:initial; text-decoration-style:initial; text-decoration-color:initial; margin-bottom:15px\" type=\"Photo\">\n<figcaption class=\"PhotoCMS_Caption\" style=\"box-sizing:border-box; padding:5px 8px; background:#e9e9e9; margin-bottom:24px\">\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"padding: 0px; text-align: justify;\">&nbsp;</p>\n</figcaption>\n</figure>\n\n<h2 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><b style=\"box-sizing:border-box; padding:0px\"><font style=\"box-sizing:border-box; padding:0px; font-size:22px\">Đầu tư công và FDI tiếp sức tăng trưởng</font></b></span></span></span></span></span></span></span></span></span></span></span></span></h2>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Báo cáo \"Vietnam at a glance - Không ngừng sải bước\" của Bộ phận Nghiên cứu Đầu tư Toàn cầu HSBC công bố ngày 28/10 cho thấy Việt Nam tiếp tục ghi nhận mức tăng trưởng nổi bật trong khu vực. GDP quý III tăng 8,2%, vượt xa dự báo của thị trường và duy trì vị thế nền kinh tế tăng trưởng nhanh nhất Đông Nam Á. Đây là quý thứ hai liên tiếp mức tăng vượt 8%, khẳng định đà phục hồi bền vững.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Theo HSBC, kết quả này phản ánh sự phục hồi toàn diện của nền kinh tế, không chỉ trong sản xuất mà cả dịch vụ và tiêu dùng. Trong khi nhiều quốc gia ASEAN chứng kiến xuất khẩu giảm tốc do hoạt động \"đặt hàng sớm\" (frontloading) chững lại, thương mại Việt Nam vẫn tăng hai con số, cho thấy năng lực thích ứng linh hoạt và khả năng mở rộng thị trường hiệu quả.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Sản xuất công nghiệp quý III tăng 10% so với cùng kỳ; kim ngạch xuất nhập khẩu tăng gần 20%. Thặng dư thương mại gấp đôi nửa đầu năm nhờ mở rộng xuất khẩu sang các thị trường ngoài Mỹ. HSBC đánh giá đây là minh chứng cho vai trò trung tâm của Việt Nam trong chuỗi cung ứng khu vực.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Nhóm hàng điện tử, đặc biệt là thiết bị tiêu dùng và linh kiện, tiếp tục dẫn dắt tăng trưởng. Xuất khẩu sang Mỹ tăng gần 30% nhờ nhu cầu mạnh với sản phẩm phục vụ trí tuệ nhân tạo. \"Việt Nam đang trở thành mắt xích quan trọng trong chuỗi cung ứng công nghệ toàn cầu,\" báo cáo nêu.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Song song, khu vực dịch vụ và tiêu dùng nội địa phục hồi rõ nét. Doanh thu bán lẻ quý III tăng 12%, phản ánh niềm tin tiêu dùng cải thiện. Du lịch dẫn đầu khu vực với 15 triệu lượt khách quốc tế, tương đương 120% mức trước dịch. Đáng chú ý, lượng khách Trung Quốc tăng mạnh dù chưa được miễn thị thực, khẳng định sức hấp dẫn và năng lực cạnh tranh của điểm đến Việt Nam.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Theo HSBC, đầu tư công và vốn đầu tư trực tiếp nước ngoài (FDI) tiếp tục là động lực then chốt. Trong quý III, đầu tư thực tế tăng gần 10% so với cùng kỳ, nhưng tiến độ giải ngân mới đạt khoảng 50% kế hoạch năm. FDI tăng 15% so với cùng kỳ, trong đó Singapore, Trung Quốc và Mỹ là ba nhà đầu tư lớn nhất.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Cơ cấu FDI năm nay có sự thay đổi đáng chú ý: Singapore và Trung Quốc đại lục mỗi nước chiếm khoảng 25% tổng vốn đăng ký mới, trong khi thị phần của Hàn Quốc giảm, nhường chỗ cho Mỹ. Sự dịch chuyển này cho thấy Việt Nam vẫn là điểm đến an toàn, hấp dẫn giữa bối cảnh thương mại toàn cầu biến động.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Mặt khác, tiêu dùng thực tế quý III tăng hơn 8% so với cùng kỳ, cho thấy sức cầu nội địa vững vàng. Các lĩnh vực vận tải, lưu trú và du lịch tiếp tục ghi nhận tăng trưởng cao, góp phần củng cố đà phục hồi chung.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Môi trường vĩ mô duy trì ổn định: lạm phát ở mức 3,4%, tín dụng tăng cao. Chính sách tiền tệ linh hoạt giúp cân bằng giữa ổn định kinh tế và hỗ trợ tăng trưởng. Ngân hàng Nhà nước định hướng tăng tín dụng năm 2025 ở mức 19–20% nhằm tiếp sức cho nền kinh tế, nhất là khu vực sản xuất và tiêu dùng.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<h3 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><b style=\"box-sizing:border-box; padding:0px\"><font style=\"box-sizing:border-box; padding:0px; font-size:20px\">HSBC nâng dự báo GDP Việt Nam lên 7,9% - cao nhất ASEAN</font></b></span></span></span></span></span></span></span></span></span></span></span></span></h3>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Trước kết quả tích cực, HSBC đã nâng mạnh dự báo tăng trưởng GDP Việt Nam năm 2025 từ 6,6% lên 7,9% và năm 2026 từ 5,8% lên 6,7% - mức cao nhất trong số các nền kinh tế ASEAN. Đồng thời, ngân hàng này điều chỉnh nhẹ dự báo lạm phát lên 3,3% cho năm 2025 và 3,5% cho năm 2026.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">HSBC nhận định, Việt Nam nổi bật nhờ sự cân bằng giữa ba trụ cột: sản xuất, dịch vụ và đầu tư. Các chính sách ổn định kinh tế vĩ mô, kiểm soát giá cả và thúc đẩy hạ tầng đã giúp duy trì tốc độ tăng trưởng cao, đồng thời thu hút dòng vốn FDI chất lượng.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Đặc biệt, việc đón đầu làn sóng công nghệ mới, nhất là trong lĩnh vực điện tử và AI, đang mở ra cơ hội để Việt Nam vươn lên trong chuỗi giá trị toàn cầu. HSBC đánh giá, nếu cải thiện tốc độ giải ngân đầu tư công và duy trì ổn định tài chính, Việt Nam hoàn toàn có thể đạt tăng trưởng 8% trong năm tới - tiến gần mục tiêu 10% cho giai đoạn 2026.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">\"Việt Nam tiếp tục chứng minh khả năng thích ứng nhanh và bền bỉ trước biến động toàn cầu. Sự kết hợp giữa năng lực sản xuất, sức tiêu dùng và chính sách ổn định đã giúp Việt Nam duy trì tốc độ phát triển hàng đầu châu Á\", các chuyên gia của HSBC nhận định.</span></span></span></span></span></span></span></span></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/hsbc-nang-du-bao-tang-truong-viet-nam-len-gan-8-dan-au-asean-29177402', '', 'Theo Chinhphu.vn', 68, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.143968', 8, 11);
INSERT INTO `sync_articles` VALUES (142, '29178759', 'Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục', 'Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg', '<p>Tin từ Cục Hàng không Việt Nam (Bộ Xây dựng), sau giai đoạn bị sụt giảm nghiêm trọng do đại dịch, hoạt động vận tải hàng không đã từng bước phục hồi và tăng trưởng trở lại mạnh mẽ.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" target=\"_blank\" title=\"Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách\"><img alt=\"Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" h=\"734\" id=\"img_907168993063587840\" loading=\"lazy\" photoid=\"907168993063587840\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" style=\"width: 900px; height: 543px;\" title=\"Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục- Ảnh 1.\" type=\"photo\" w=\"1216\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2021, tổng thị trường vận chuyển hàng không chỉ đạt gần 16 triệu hành khách; đến năm 2024, con số này đã tăng trưởng gấp gần 5 lần, đạt hơn 75 triệu hành khách.&nbsp;Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày càng nhiều hành khách lựa chọn di chuyển bằng đường hàng không</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cục Hàng không Việt Nam nhìn nhận: Việc ngày càng nhiều khách lựa chọn hàng không làm phương thức di chuyển cho thấy nhu cầu đi lại, giao thương quốc tế tăng cao và vai trò tích cực của hoạt động vận tải hàng không, góp phần vào sự phát triển kinh tế - xã hội, du lịch Việt Nam.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về mở rộng mạng bay quốc tế, số liệu từ Cục Hàng không Việt Nam cho thấy đến năm 2025, mạng đường bay quốc tế của Việt Nam đã không những được khôi phục hoàn toàn mà còn tăng từ 130 đường bay (trước đại dịch COVID-19) lên con số 150 đường bay kết nối với hơn 30 quốc gia và vùng lãnh thổ.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều đường bay thẳng đến các thị trường xa như châu Âu, Bắc Mỹ đã được Cục Hàng không Việt Nam nghiên cứu và ký kết các hiệp định mới, tạo tiền đề cho việc khai thác trong tương lai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong nước, mạng bay nội địa được tối ưu hóa, tần suất khai thác trên các đường bay trục chính tăng lên và các hãng hàng không cũng liên tục mở mới các đường bay đến các địa phương có tiềm năng du lịch.</span></span></span></p>\n\n<h3 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thêm hãng bay, hành khách thêm lựa chọn</span></span></span></h3>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh các hãng hàng không Việt Nam đã tham gia thị trường trước đó (Vietnam Airlines, Vietjet Air, Pacific Airlines, Bamboo Airways), một điểm sáng thể hiện sức sống và tiềm năng của thị trường hàng không Việt Nam là sự ra đời của hai hãng hàng không mới: VietravelAirlines và SunPhuQuoc Airways.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cục trưởng Cục Hàng không Việt Nam Uông Việt Dũng đánh giá: Việc ra đời của hai hãng hàng không mới cho thấy sức hấp dẫn của thị trường hàng không Việt Nam. Đồng thời, mở ra những cơ hội phát triển mới, góp phần đa dạng hóa thị trường, tạo ra sự cạnh tranh lành mạnh, thúc đẩy các hãng hàng không cải thiện chất lượng dịch vụ, đa dạng hóa sản phẩm và giảm giá vé đến tay hành khách. Đồng thời, hoạt động vận tải hàng không phát triển cũng sẽ có tác động lan toả, thúc đẩy việc tiếp tục đầu tư, phát triển hạ tầng giao thông và kích thích du lịch góp phần phát triển kinh tế địa phương và khu vực.&nbsp;</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/vuot-qua-kho-khan-hang-khong-viet-nam-phuc-hoi-ngoan-muc-29178759', '', 'Theo Chinhphu.vn', 37, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.188382', 8, 11);
INSERT INTO `sync_articles` VALUES (143, '29178428', 'Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương', 'Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg', '<p>Ngày thứ hai của Hội chợ mùa Thu lần thứ nhất – năm 2025 chứng kiến sự chuyển dịch rõ rệt trong hoạt động của các doanh nghiệp: Từ thu hút khách tham quan sang tăng cường kết nối, tìm kiếm cơ hội hợp tác và mở rộng giao thương.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" target=\"_blank\" title=\"Các gian hành công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" h=\"1331\" id=\"img_907156085085904896\" loading=\"lazy\" photoid=\"907156085085904896\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" style=\"width: 900px; height: 599px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hành công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo thống kê sơ bộ của Ban Tổ chức, trong 2 ngày đầu, đã có hơn 40 biên bản ghi nhớ và thỏa thuận hợp tác được ký kết, hàng chục doanh nghiệp đạt doanh số vượt kỳ vọng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không chỉ là nơi trưng bày sản phẩm, Hội chợ mà còn phản ánh sự chuyên nghiệp trong cách tiếp cận thị trường của doanh nghiệp Việt. Nhiều gian hàng thể hiện năng lực quản trị, công nghệ, quy trình sản xuất và dịch vụ hậu mãi, hướng tới tiêu chuẩn quốc tế. Đây cũng là cơ hội để doanh nghiệp giới thiệu năng lực sản xuất, chất lượng sản phẩm và khả năng tham gia chuỗi cung ứng toàn cầu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một số doanh nghiệp tham gia Hội chợ đang tập trung vào việc nâng cao tiêu chuẩn sản xuất và quản lý chất lượng, nhằm phục vụ cả thị trường trong nước lẫn xuất khẩu. Việc chuẩn hóa quy trình, áp dụng tiêu chuẩn quốc tế và nâng cấp dịch vụ hậu mãi được coi là các yếu tố then chốt để tăng sức cạnh tranh và xây dựng niềm tin với khách hàng, đặc biệt là đối tác nước ngoài.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hàng được đầu tư bài bản hơn, từ thiết kế, trưng bày sản phẩm đến đội ngũ tư vấn và dịch vụ hậu mãi, nhằm tạo ấn tượng và thúc đẩy hợp tác lâu dài. Đây là minh chứng cho việc doanh nghiệp Việt ngày càng nhìn nhận hội chợ như một kênh xúc tiến thương mại chuyên nghiệp, gắn với chiến lược phát triển dài hạn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại gian hàng của Dekko, đại diện doanh nghiệp cho biết lượng khách tham quan khá đông, tập trung vào các sản phẩm nhựa và thiết bị dân dụng. Khách hàng trung niên chủ yếu quan tâm đến sản phẩm phục vụ xây dựng và vật tư điện nước, trong khi nhóm khách lớn tuổi chú ý hơn đến thiết bị dân dụng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">\"Hội chợ là dịp để chúng tôi giới thiệu năng lực sản xuất, khả năng cung ứng và chính sách hậu mãi, đồng thời tạo cơ hội kết nối với các đối tác trong nước và quốc tế, hướng tới mở rộng giao thương trong khu vực\", đại diện Dekko cho biết.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" target=\"_blank\" title=\"Đông đảo du khách tham quan các gian hàng công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" h=\"1331\" id=\"img_907155874622853120\" loading=\"lazy\" photoid=\"907155874622853120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" style=\"width: 900px; height: 599px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 2.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đông đảo du khách tham quan các gian hàng công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một trong những điểm nổi bật của Hội chợ là sự chuyển dịch rõ ràng trong cách doanh nghiệp nhìn nhận hoạt động xúc tiến thương mại. Không còn dừng ở việc \"đem hàng ra bán\", nhiều doanh nghiệp đã coi đây là \"phòng trưng bày năng lực\", nơi thể hiện bản sắc, trình độ và định hướng phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện Công ty Cổ phần Thép Nam Kim, cho rằng: \"Hội chợ năm nay có quy mô cực lớn, lượng khách rất đông cả trong và ngoài nước. Đây là cơ hội tuyệt vời để Công ty quảng bá dòng sản phẩm mới. Chúng tôi mong muốn Bộ Công Thương tiếp tục duy trì và mở rộng các \"sân chơi xúc tiến thương mại quy mô lớn\", tạo điều kiện cho doanh nghiệp Việt tiếp cận khách hàng chuyên ngành, mở rộng hợp tác quốc tế\".</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" target=\"_blank\" title=\"Các gian hàng bày bán hàng Việt thu hút đông đảo người tiêu dùng mua sắm - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" h=\"1500\" id=\"img_907154236142616576\" loading=\"lazy\" photoid=\"907154236142616576\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" style=\"width: 900px; height: 675px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hàng bày bán hàng Việt thu hút đông đảo người tiêu dùng mua sắm - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Niềm tự hào hàng Việt</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày thứ 2 Hội chợ, không gian tại đây vẫn ngập tràn âm thanh và sắc màu của mùa thu Hà Nội. Các gian hàng được trang trí bắt mắt, mang đậm bản sắc vùng miền: Từ những gian hàng nông sản vùng cao Tây Bắc, sản phẩm thủ công mỹ nghệ miền Trung, đến khu vực hàng tiêu dùng và thực phẩm chế biến của các tập đoàn, doanh nghiệp lớn. Không khí mua sắm tấp nập, nhộn nhịp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện WinMart cho biết, chỉ trong hai ngày đầu, lượng khách đến mua sắm tăng gấp đôi so với dự kiến. \"Điều khiến chúng tôi vui nhất là người tiêu dùng đến không chỉ để mua hàng, mà còn để trải nghiệm tinh thần Người Việt Nam ưu tiên dùng hàng Việt Nam\", đại diện WinMart nói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ cũng quy tụ hàng loạt thương hiệu OCOP 4 sao, 5 sao, sản phẩm đặc sản vùng miền, từ trà La Bằng (Thái Nguyên), mật ong Mường Lát (Thanh Hóa), đến tinh dầu quế Bắc Giang, khẳng định vị thế hàng Việt trên bản đồ tiêu dùng trong nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ mùa Thu lần thứ nhất - 2025 sẽ diễn ra đến ngày 4/11/2025 tại Trung tâm Triển lãm Quốc gia Việt Nam (VEC) - Đông Anh - Hà Nội.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/ngay-thu-hai-hoi-cho-mua-thu-2025-doanh-nghiep-tap-trung-ket-noi-giao-thuong-29178428', '', 'Theo Chinhphu.vn', 38, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.227722', 8, 11);
INSERT INTO `sync_articles` VALUES (144, '29029501', 'Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình', 'Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg', '<p>Là nước láng giềng của Campuchia và Thái Lan và là thành viên ASEAN, Việt Nam quan tâm và hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình ngày 26/10/2025.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" target=\"_blank\" title=\"Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng\"><img alt=\"Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" h=\"570\" id=\"img_906862359364214784\" loading=\"lazy\" photoid=\"906862359364214784\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" style=\"width: 854px; height: 570px;\" title=\"Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình- Ảnh 1.\" type=\"photo\" w=\"854\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 26/10/2025, trả lời câu hỏi của phóng viên đề nghị cho biết phản ứng của Việt Nam trước việc Campuchia và Thái Lan ký kết văn kiện hòa bình nhân dịp tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các hội nghị cấp cao liên quan được tổ chức tại Malaysia, Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng nêu rõ:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">“Là nước láng giềng của Campuchia và Thái Lan và là thành viên ASEAN, Việt Nam quan tâm và hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình ngày 26/10/2025. Đây là bước tiến quan trọng, tích cực, thể hiện cam kết của hai nước đối với hòa bình, hợp tác và phát triển, phù hợp với Hiến chương ASEAN và Hiệp ước Thân thiện và Hợp tác ở Đông Nam Á (TAC). Chúng tôi đánh giá cao nỗ lực của các nước, trong đó có Malaysia, Chủ tịch ASEAN 2025 và Thủ tướng Anwar Ibrahim, Hoa Kỳ và Tổng thống Donald Trump, và các bên liên quan trong quá trình tìm kiếm một giải pháp hòa bình cho vấn đề.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam tin rằng văn kiện hòa bình sẽ tạo cơ sở để củng cố lòng tin và hướng tới giải pháp hòa bình lâu dài. Việt Nam tiếp tục tích cực tham gia các nỗ lực chung của ASEAN hỗ trợ Campuchia và Thái Lan triển khai đầy đủ, hiệu quả văn kiện này.”./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-hoan-nghenh-campuchia-va-thai-lan-ky-van-kien-hoa-binh-29029501', '', 'Theo Chinhphu.vn', 32, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.262523', 8, 11);
INSERT INTO `sync_articles` VALUES (145, '29179537', 'Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng', 'Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg', '<p>Theo thông tin từ Bộ Công Thương, ngày 26/10, Việt Nam và Hoa Kỳ đã đồng ý công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng, công bằng và cân bằng (Tuyên bố chung) nhân dịp Thủ tướng Chính phủ Phạm Minh Chính và Tổng thống Donald Trump tham dự Hội nghị Cấp cao ASEAN tổ chức từ...', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính có cuộc tiếp xúc ngắn với Tổng thống Hoa Kỳ Donald Trump bên lề Hội nghị Cấp cao ASEAN - Hoa Kỳ - Ảnh: VGP\"><img alt=\"Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" h=\"1334\" id=\"img_906864523261059072\" loading=\"lazy\" photoid=\"906864523261059072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" style=\"width: 900px; height: 600px;\" title=\"Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính có cuộc tiếp xúc ngắn với Tổng thống Hoa Kỳ Donald Trump bên lề Hội nghị Cấp cao ASEAN - Hoa Kỳ - Ảnh: VGP</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuyên bố chung là văn bản mà Việt Nam và Hoa Kỳ thống nhất đưa ra để thể hiện kết quả về đàm phán thương mại đối ứng giữa hai nước cho đến nay cũng như để ghi nhận nỗ lực của các cơ quan chính phủ, doanh nghiệp Việt Nam và Hoa Kỳ trong việc xây dựng quan hệ kinh tế, thương mại trên cơ sở cân bằng, ổn định và bền vững, phù hợp với mối quan hệ Đối tác Chiến lược Toàn diện Việt Nam - Hoa Kỳ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuyên bố chung đề cập đến các nội dung chính của Hiệp định Thương mại đối ứng, công bằng và cân bằng, theo đó cả Việt Nam và Hoa Kỳ sẽ cùng hợp tác trên tinh thần xây dựng để giải quyết mối quan tâm của cả hai bên liên quan đến các rào cản phi thuế quan, thống nhất các cam kết liên quan đến thương mại số, dịch vụ và đầu tư; thảo luận về sở hữu trí tuệ, phát triển bền vững cũng như tăng cường hợp tác để nâng cao khả năng chống chịu của chuỗi cung ứng…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thời gian tới, hai bên sẽ tiếp tục thảo luận và triển khai các công việc tiếp theo hướng đến hoàn thành Hiệp định Thương mại đối ứng, công bằng và cân bằng trên nguyên tắc cởi mở, xây dựng, bình đẳng, tôn trọng độc lập, tự chủ, thể chế chính trị, cùng có lợi và cân nhắc tới trình độ phát triển của nhau.&nbsp;</span></span></span></p>\n\n<p id=\"\" style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xem toàn văn Tuyên bố chung&nbsp;</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/2025-10-25-us-vn-joint-sttement-on-reciprocal-trade-finall-v-version-176147713457454924216.docx\" ref=\"nofollow\" rel=\"nofollow\" target=\"_blank\" title=\"tại đây\"><i>tại đây</i><i></i></a></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Từ cuối tháng 4/2025, Việt Nam và Hoa Kỳ đã tổ chức nhiều phiên đàm phán thương mại đối ứng ở cả cấp kỹ thuật và cấp Bộ trưởng. Đoàn đàm phán Chính phủ Việt Nam do Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên làm Trưởng đoàn, thành viên gồm lãnh đạo và cán bộ của các bộ và cơ quan: Công Thương, Ngoại giao, Công an, Tài chính, Tư pháp, Nông nghiệp và Môi trường, Khoa học Công nghệ, Nội vụ, Xây dựng, Y tế, Ngân hàng Nhà nước và Đại sứ quán Việt Nam tại Hoa Kỳ. Nhiều phiên đàm phán trực tiếp và trực tuyến đã diễn ra giữa Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên với Trưởng Cơ quan Đại diện thương mại Hoa Kỳ (USTR) Jamieson Greer và Bộ trưởng Thương mại Hoa Kỳ Howard Lutnick.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Rạng sáng ngày 1/8/2025 (giờ Việt Nam), Nhà Trắng đã đăng tải Sắc lệnh của Tổng thống Donald Trump về việc điều chỉnh mức thuế đối ứng, theo đó Hoa Kỳ điều chỉnh mức thuế đối ứng cho 69 nước và vùng lãnh thổ được liệt kê trong Phụ lục I. Theo Phụ lục này, mức thuế đối ứng dành cho Việt Nam giảm từ 46% xuống còn 20%.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Theo số liệu của Hải quan Việt Nam tính đến hết tháng 9 năm 2025, tổng kim ngạch trao đổi thương mại song phương đạt khoảng 126,4 tỷ USD.</i></span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-hoa-ky-cong-bo-tuyen-bo-chung-ve-khuon-kho-hiep-inh-thuong-mai-oi-ung-29179537', '', 'Theo Chinhphu.vn', 37, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.292162', 8, 11);
INSERT INTO `sync_articles` VALUES (146, '29180021', 'Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng', 'Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg', '<p>Ngành sầu riêng Việt Nam đang ở thời điểm vừa có tiềm năng lớn, vừa đối mặt nhiều thách thức. Việc các phòng kiểm nghiệm được GACC công nhận hoạt động tốt chính là một khâu then chốt để mở lại \"cánh cửa\" thị trường Trung Quốc - thị trường lớn nhất hiện nay.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" target=\"_blank\" title=\"Dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD - Ảnh: VGP/Đỗ Hương\"><img alt=\"Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" h=\"797\" id=\"img_906825742407507968\" loading=\"lazy\" photoid=\"906825742407507968\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" style=\"width: 900px; height: 521px;\" title=\"Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng- Ảnh 1.\" type=\"photo\" w=\"1375\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD - Ảnh: VGP/Đỗ Hương</span></span></span></p>\n</figcaption>\n</figure>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Siết chặt quy trình kiểm nghiệm, bảo vệ uy tín hàng Việt</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Sau giai đoạn bùng nổ năm 2024 với kim ngạch 3,3 tỷ USD, sầu riêng trở thành \"ngôi sao\" của ngành trái cây Việt Nam, chiếm gần 46% tổng giá trị xuất khẩu rau quả cả nước. Trong đó, thị trường Trung Quốc chiếm tới 97% tổng lượng sầu riêng xuất khẩu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tuy nhiên, bước sang năm 2025, ngành hàng này đối mặt cú sốc lớn. Chỉ trong 4 tháng đầu năm, giá trị xuất khẩu sầu riêng của Việt Nam chỉ đạt khoảng 183 triệu USD, giảm tới hơn 60% so với cùng kỳ năm trước. Nguyên nhân chủ yếu đến từ việc Trung Quốc siết chặt kiểm tra an toàn thực phẩm, truy xuất nguồn gốc và tăng cường xét nghiệm dư lượng kim loại nặng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Một phần khác đến từ năng lực kiểm nghiệm trong nước chưa ổn định, dẫn tới thời gian chờ kết quả kéo dài, làm chậm tiến độ giao hàng. Nhiều doanh nghiệp phản ánh việc chờ kết quả kiểm nghiệm khiến sầu riêng chín vượt thời hạn bảo quản, buộc phải tiêu thụ nội địa với giá thấp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Trước những biến động mạnh của thị trường sầu riêng, ngày 24/10 vừa qua, Thứ trưởng Bộ Nông nghiệp và Môi trường Hoàng Trung vừa yêu cầu các phòng kiểm nghiệm được Tổng cục Hải quan Trung Quốc (GACC) công nhận đủ điều kiện phải hoạt động hết công suất, bảo đảm thông suốt cho hoạt động xuất khẩu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo chỉ đạo của Thứ trưởng Hoàng Trung, Cục Chất lượng, Chế biến và Phát triển thị trường cần rà soát toàn bộ các trung tâm kiểm nghiệm đang được GACC công nhận; xác định rõ đơn vị còn hoạt động, đơn vị tạm dừng, cũng như năng lực kiểm tra thực tế với các chỉ tiêu đặc biệt như Cadimi và Vàng O.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Thứ trưởng nhấn mạnh, các trung tâm kiểm nghiệm phải thực hiện nghiêm túc, chính xác và nhanh chóng toàn bộ quy trình, từ lấy mẫu, tiếp nhận, phân tích đến trả kết quả. \"Việc kiểm nghiệm phải tránh tối đa sai sót, vì chỉ một lỗi nhỏ cũng có thể làm ảnh hưởng uy tín của hàng sầu riêng Việt Nam tại thị trường quốc tế,\" ông Hoàng Trung nói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo ông Phạm Văn Duy, Phó Cục trưởng Cục Chất lượng, Chế biến và Phát triển thị trường, hiện Việt Nam có 24 phòng kiểm nghiệm được GACC công nhận phục vụ kiểm tra dư lượng Cadimi và Vàng O, với tổng công suất xử lý khoảng 3.200 mẫu/ngày. Về lý thuyết, con số này đủ đáp ứng nhu cầu thực tế. Tuy nhiên, nhiều phòng thử nghiệm đang tạm ngừng do bảo trì, sửa chữa hoặc chờ đánh giá công nhận lại, khiến hệ thống bị \"nghẽn mạch\" cục bộ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Việc Trung Quốc yêu cầu kiểm soát nghiêm ngặt chỉ tiêu Cadimi (kim loại nặng tích tụ trong đất) và Vàng O (phẩm màu bị cấm sử dụng trong nông sản) đã tạo áp lực lớn cho toàn chuỗi xuất khẩu. Nếu quy trình kiểm nghiệm trong nước không đảm bảo, doanh nghiệp có thể bị trả hàng hoặc đình chỉ thông quan, kéo theo thiệt hại lớn cho cả ngành.</span></span></span></p>\n\n<h4 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Cơ hội phục hồi từ xuất khẩu chế biến và đa dạng hóa thị trường</span></span></span></h4>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dù gặp khó với hàng tươi, xuất khẩu sầu riêng chế biến, đông lạnh của Việt Nam lại đang tăng mạnh. Trong quý I/2025, Việt Nam xuất khoảng 8.700 tấn sầu riêng đông lạnh, tăng hơn 60% so với cùng kỳ 2024, đạt giá trị hơn 31 triệu USD.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Các chuyên gia nhận định, đây là hướng đi khả thi giúp ngành giảm phụ thuộc vào thị trường Trung Quốc và kéo dài thời gian tiêu thụ sản phẩm. Cùng với đó, nhu cầu sầu riêng tại các thị trường mới như Mỹ, Nhật Bản, Hàn Quốc, UAE… đang tăng nhanh, mở ra cơ hội mở rộng xuất khẩu cho Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo thống kê của Bộ Nông nghiệp và Môi trường, đến nay Việt Nam đã được Trung Quốc phê duyệt 829 mã vùng trồng và 131 cơ sở đóng gói sầu riêng. Bộ cũng đang tiếp tục làm việc với phía bạn để mở rộng thêm vùng trồng, đồng thời thúc đẩy công nhận thêm các phòng kiểm nghiệm đạt chuẩn nhằm giảm tải cho hệ thống hiện nay.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Nếu các \"nút thắt\" về kiểm nghiệm, truy xuất nguồn gốc và chất lượng được tháo gỡ, nhiều chuyên gia dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD, tiếp tục khẳng định vị thế của Việt Nam trên bản đồ sầu riêng thế giới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo Thứ trưởng Hoàng Trung, để tận dụng cơ hội này, các đơn vị kiểm nghiệm cần \"vào guồng\" ngay, hoạt động hết công suất, nâng cao tính chính xác và tốc độ trả kết quả. Bộ Nông nghiệp và Môi trường yêu cầu Cục Chất lượng, Chế biến và Phát triển thị trường phối hợp chặt với các địa phương, doanh nghiệp, đảm bảo mẫu kiểm nghiệm được xử lý kịp thời, tránh dồn ứ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Bên cạnh đó, Bộ cũng yêu cầu tăng cường đào tạo và hướng dẫn doanh nghiệp, hợp tác xã, nhà vườn về quy trình kiểm soát chất lượng, sử dụng phân bón hợp lý để tránh tích tụ Cadimi, tuân thủ quy định về mã số vùng trồng và cơ sở đóng gói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Đồng thời, ngành nông nghiệp cũng đang đẩy nhanh chuyển đổi sang mô hình sản xuất xanh, giảm phát thải, tăng giá trị xuất khẩu bền vững, phù hợp với xu hướng tiêu dùng và yêu cầu nhập khẩu của các thị trường lớn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Từ câu chuyện của sầu riêng có thể thấy rõ, năng lực kiểm nghiệm không chỉ là vấn đề kỹ thuật mà là \"chìa khóa chiến lược\" quyết định thành bại của xuất khẩu nông sản. Khi các phòng thí nghiệm vận hành hiệu quả, quy trình kiểm soát chất lượng chặt chẽ, hàng Việt Nam mới đủ sức cạnh tranh, đáp ứng tiêu chuẩn cao của những thị trường khó tính.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Việc Bộ Nông nghiệp và Môi trường yêu cầu hệ thống kiểm nghiệm hoạt động hết công suất không chỉ nhằm tháo gỡ khó khăn trước mắt, mà còn hướng tới xây dựng chuỗi giá trị nông sản an toàn - minh bạch - bền vững, để trái sầu riêng Việt Nam không chỉ đứng vững tại Trung Quốc mà .</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/nang-cao-chat-luong-kiem-nghiem-e-phuc-vu-xuat-khau-sau-rieng-29180021', '', 'Theo Chinhphu.vn', 37, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.321704', 8, 11);
INSERT INTO `sync_articles` VALUES (147, '29030402', 'Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7', 'Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg', '<p>Sáng 26/10, tại Trụ sở Trung ương Đảng, Tổng Bí thư Tô Lâm đã tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và các đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7 - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" h=\"489\" height=\"489\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 1.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và các đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7 - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lịch sử hình thành, xây dựng, bảo vệ và phát triển dân tộc liên tục hàng nghìn năm đã tạo nên bản sắc đặc biệt, một nền văn hiến lâu đời, lấy lòng dân làm gốc, lấy đạo lý nhân nghĩa làm nền, lấy tinh thần độc lập và tự chủ làm mạch sống. Văn hóa Việt Nam là kết tinh của bản sắc dân tộc và sự giao thoa với nhân loại; là nền tảng tinh thần của xã hội, là sức mạnh mềm, là “căn cước phát triển” của quốc gia. Sức sống ấy đã giúp dân tộc vượt qua chiến tranh, tái sinh sau đổ nát và bước vào thời kỳ phát triển mới với tư thế ngày càng tự tin.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh hai dấu mốc lịch sử mang tính bước ngoặt của dân tộc: Trước tiên là sự ra đời của Đảng Cộng sản Việt Nam năm 1930, lãnh đạo nhân dân Việt Nam giành độc lập, thống nhất đất nước, mở ra con đường phát triển theo định hướng xã hội chủ nghĩa; tiếp theo là Đổi mới - quyết định chiến lược, tạo ra bước phát triển nhảy vọt, đưa Việt Nam vươn lên thành nền kinh tế năng động, hội nhập sâu, tham gia tích cực vào các chuỗi giá trị khu vực và toàn cầu.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" h=\"464\" height=\"464\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 2.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đánh giá cao chủ đề hội thảo: \"Việt Nam: phát triển bền vững trong kỷ nguyên mới\", Tổng Bí thư nhấn mạnh Việt Nam chủ trương phát triển dựa trên 3 trụ cột gắn bó chặt chẽ:&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ nhất, phát triển thể chế, chính sách, quản trị quốc gia theo hướng tự chủ chiến lược, hiện đại, minh bạch, liêm chính, hiệu lực, hiệu quả; xây dựng Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân, một Nhà nước kiến tạo phát triển.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai, phát triển con người Việt Nam toàn diện; tài nguyên quý nhất của Việt Nam là 106 triệu người Việt Nam cần cù, sáng tạo, giàu lòng yêu nước, giàu ý thức cộng đồng, ham học hỏi và biết vươn lên trong hoàn cảnh khó khăn.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ ba, phát triển kinh tế xanh, kinh tế tuần hoàn, kinh tế tri thức, kinh tế số, gắn với khoa học - công nghệ và đổi mới sáng tạo, chuyển đổi số. Đặc biệt, phát triển bền vững không chỉ là vấn đề kinh tế và môi trường mà còn là vấn đề văn hóa, xã hội, con người, đạo lý.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư đánh giá&nbsp;cao các nhà khoa học, học giả đã đi sâu vào những chủ đề có tính cấu trúc, có ý nghĩa chiến lược đối với tương lai đất nước; khẳng định trong quá trình hoạch định đường lối, chủ trương, chính sách phát triển đất nước, Đảng và Nhà nước luôn lắng nghe những ý kiến phản biện khoa học độc lập, nghiêm túc, thiện chí.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21, khẳng định đó là lời cam kết trước nhân dân Việt Nam hôm nay và trước thế hệ mai sau, cũng là cam kết trước bạn bè quốc tế: Việt Nam muốn lớn mạnh bằng tri thức, bằng sáng tạo, bằng hợp tác bình đẳng và tôn trọng lẫn nhau; Việt Nam muốn đóng góp vào tiến bộ chung của nhân loại, cùng tạo ra thành quả qua lao động sáng tạo và cùng hưởng thụ những thành quả đó.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" target=\"_blank\" title=\"Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21 - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" h=\"509\" height=\"509\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 3.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21 - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư khẳng định đất nước bước vào giai đoạn phát triển mới với tư duy mới, nhưng với những giá trị không bao giờ thay đổi. Một là, độc lập dân tộc, chủ quyền quốc gia, toàn vẹn lãnh thổ là thiêng liêng, là bất khả xâm phạm. Hai là, hạnh phúc của nhân dân, mọi quyết sách đều hướng tới nâng cao đời sống thực của người dân. Ba là, sức mạnh Việt Nam trước hết là sức mạnh đại đoàn kết toàn dân tộc.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong giai đoạn phát triển mới, đại đoàn kết phải được mở rộng hơn nữa, bao gồm đội ngũ trí thức trong và ngoài nước, cộng đồng doanh nghiệp, đội ngũ văn nghệ sĩ, thanh niên, phụ nữ, đồng bào các dân tộc anh em, các tôn giáo, người Việt Nam ở nước ngoài, bạn quốc tế gắn bó với Việt Nam bằng thiện chí và sự tôn trọng lẫn nhau.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư cảm ơn cộng đồng các nhà Việt Nam học đã dành tâm huyết cho Việt Nam nhiều năm qua, bày tỏ mong muốn các chuyên gia, học giả tiếp tục đồng hành, không chỉ bằng tình cảm mà bằng tri thức khoa học, phân tích chính sách dựa trên chứng cứ khoa học, khuyến nghị cụ thể, thiết thực, có thể triển khai được. Đồng thời, Tổng Bí thư kỳ vọng và đặt hàng các nghiên cứu về Việt Nam sẽ ngày càng gắn với các vấn đề đang đặt ra một cách cấp bách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhất trí tổ chức thường xuyên hơn hội thảo quốc tế Việt Nam học ở Việt Nam và nước ngoài, thành lập Quỹ Việt Nam trong năm nay; đề nghị giới nghiên cứu quốc tế, các nghiên cứu sinh, các nhà khoa học đến Việt Nam nhiều hơn, ở lại Việt Nam lâu hơn, làm việc cùng các đồng nghiệp Việt Nam bình đẳng hơn và lắng nghe tiếng nói từ cơ sở, từ địa phương, từ cộng đồng, chứ không chỉ nhìn Việt Nam qua các số liệu tổng hợp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với khát vọng rất lớn, nhưng cũng với tâm thế khiêm tốn, cầu thị, lắng nghe, Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" target=\"_blank\" title=\"Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" h=\"510\" id=\"img_906806440988131328\" loading=\"lazy\" photoid=\"906806440988131328\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" style=\"width: 665px; height: 510px;\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại cuộc gặp, các nhà khoa học tiêu biểu đại diện cho gần 1.300 đại biểu tham dự hội thảo bày tỏ cảm kích, đánh giá cao sự quan tâm của cá nhân Tổng Bí thư Tô Lâm và lãnh đạo Đảng, Nhà nước Việt Nam đối với mạng lưới toàn cầu các nhà khoa học và chuyên gia nghiên cứu về Việt Nam nói chung và hội thảo lần này nói riêng.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các học giả bày tỏ ấn tượng về sự phát triển năng động của Việt Nam, cũng như tầm nhìn và sự lãnh đạo sáng suốt của Đảng, đồng tình những chủ trương, quyết sách mà Đảng và Nhà nước đang quyết liệt triển khai nhận được sự đồng thuận cao của người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong không khí trao đổi cởi mở, nhiều ý kiến tâm huyết khuyến nghị các biện pháp cụ thể nhằm kịp thời hiện thực hóa&nbsp;các nghị quyết đúng đắn của Đảng mới ban hành, đồng thời bày tỏ niềm tin với quyết tâm và sự chỉ đạo sát sao của lãnh đạo Đảng và Nhà nước, sự đoàn kết, đồng lòng của đông đảo nhân dân, đất nước Việt Nam sẽ sớm đạt các mục tiêu phát triển toàn diện đã đề ra.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-tiep-oan-ai-bieu-tham-du-hoi-thao-quoc-te-viet-nam-hoc-lan-thu-7-29030402', '', 'Theo Chinhphu.vn', 25, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.355911', 8, 11);
INSERT INTO `sync_articles` VALUES (148, '29031610', 'Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn', 'Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg', '<p>Sáng 26/10, Phó Thủ tướng Chính phủ Bùi Thanh Sơn đã tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký công ước Liên Hợp Quốc về chống tội phạm mạng (Công ước Hà Nội).</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" target=\"_blank\" title=\"Phó Thủ tướng Bùi Thanh Sơn tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký Công ước Liên Hợp Quốc về chống tội phạm mạng - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" h=\"1502\" id=\"img_906767351245062144\" loading=\"lazy\" photoid=\"906767351245062144\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" style=\"width: 900px; height: 676px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Bùi Thanh Sơn tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký Công ước Liên Hợp Quốc về chống tội phạm mạng - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, Phó Thủ tướng Bùi Thanh Sơn chúc mừng những thành tựu to lớn trong phát triển kinh tế-xã hội, nâng cao vị thế đất nước mà nhân dân Campuchia đã đạt được dưới sự trị vì của Quốc vương Norodom Sihamoni, sự lãnh đạo của Chính phủ do Đảng Nhân dân Campuchia làm nòng cốt, đứng đầu là Chủ tịch Hun Sen; tin tưởng Campuchia sẽ tiếp tục gặt hái được nhiều thành công hơn nữa trong công cuộc xây dựng và phát triển đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Bùi Thanh Sơn cảm ơn Phó Thủ tướng Sok Chenda Sophea đã dẫn đầu đoàn Đại biểu Campuchia tham dự Lễ mở ký Công ước Hà Nội, thể hiện sự ủng hộ của Campuchia đối với Việt Nam, đồng thời góp phần vào thành công chung của Lễ mở ký - sự kiện có ý nghĩa lịch sử của cộng đồng quốc tế trong cuộc chiến chống tội phạm mạng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng cho biết, Tổng Bí thư Tô Lâm và các nhà lãnh đạo cấp cao Việt Nam đánh giá cao việc Campuchia cử Đoàn đại biểu cấp cao do Chủ tịch Hun Sen dẫn đầu và sự tham gia diễu binh của lực lượng vũ trang Campuchia tại Lễ kỷ niệm 50 năm giải phóng miền Nam, thống nhất đất nước (30/4/1975-30/4/2025) và Lễ kỷ niệm 80 năm Cách mạng tháng Tám và Quốc khánh Việt Nam (2/9/1945-2/9/2025).</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" target=\"_blank\" title=\"Phó Thủ tướng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" h=\"1368\" id=\"img_906767352292298752\" loading=\"lazy\" photoid=\"906767352292298752\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" style=\"width: 900px; height: 615px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 2.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng vui mừng nhận thấy quan hệ hai nước thời gian qua tiếp tục được củng cố và phát triển, trong đó hợp tác kênh Đảng giúp củng cố tin cậy lẫn nhau, hợp tác an ninh-quốc phòng giữ vai trò trụ cột, kim ngạch thương mại đạt trung bình trên 10 tỷ USD/năm, trong đó 9 tháng năm 2025 đạt gần 9 tỷ USD, số lượng khách du lịch giữa hai nước tăng cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thời gian tới, Phó Thủ tướng đề nghị hai bên tập trung tạo đột phát trong hợp tác kinh tế để đạt mục tiêu nâng kim ngạch thương mại song phương lên 20 tỷ USD vào năm 2030 thông qua đẩy nhanh kết nối hạ tầng giao thông đặc biệt là dự án kết nối cao tốc TPHCM-Mộc Bài-Bavet-Phnom Penh; đề ra các biện pháp dài hạn thúc đẩy hợp tác kinh tế; phát triển hệ thống cửa khẩu và hạ tầng thương mại biên giới, trong đó có việc sớm tổ chức khánh thành cặp cửa khẩu quốc tế Tân Nam-Meun Chey; tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam đầu tư vào Campuchia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng cũng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" target=\"_blank\" title=\"Phó Thủ tướng Campuchia Sok Chenda Sophea chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" h=\"1377\" id=\"img_906767352232796160\" loading=\"lazy\" photoid=\"906767352232796160\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" style=\"width: 900px; height: 620px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Campuchia Sok Chenda Sophea chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Campuchia Sok Chenda Sophea bày tỏ vui mừng gặp lại Phó Thủ tướng Bùi Thanh Sơn; chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Sok Chenda Sophea cho hay, trong Lễ mở ký Công ước, ông ngồi cạnh Phó Thủ tướng Ba Lan Krzysztof Gawkowski và Phó Tổng thống Ecuador Maria Jose Pinto Gonzalez Artigas. Cả hai vị trưởng đoàn của Ba Lan và Ecuador đều đánh giá cao cương vị của Việt Nam trong tổ chức đăng cai Lễ mở ký, cũng như đà phát triển nhanh chóng của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bày tỏ ấn tượng với những thành tựu và định hướng phát triển của Việt Nam, Phó Thủ tướng Sok Chenda Sophea tin tưởng Việt Nam sẽ hiện thực hoá những mục tiêu phát triển của mình nhờ đi đúng hướng trong việc tập trung phát triển cơ sở hạ tầng cứng và đa dạng hoá phương thức phát triển nguồn nhân lực; khẳng định Campuchia mong muốn tiếp tục hợp tác chặt chẽ với Việt Nam để cùng phát triển.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-to-chuc-le-mo-ky-cong-uoc-ha-noi-thanh-cong-my-man-29031610', '', 'Theo Chinhphu.vn', 23, 'Tin trong nước', 8, '', '38762', '{}', '2025-11-01 07:12:51.393144', 8, 11);
INSERT INTO `sync_articles` VALUES (149, '29278299', 'PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD', 'PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland, Tổng Bí thư Tô Lâm có bài phát biểu chính sách quan trọng tại Đại học Oxford - trung tâm nghiên cứu đào tạo hàng đầu của Anh - về tầm nhìn cho khuôn khổ quan hệ Việt Nam - Anh và công cuộc đổi mới, định hướng phát...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm: Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" h=\"1054\" id=\"img_907670501442048000\" loading=\"lazy\" photoid=\"907670501442048000\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" style=\"width: 700px; height: 495px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 1.\" type=\"photo\" w=\"1492\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm: Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa bà&nbsp;</i><i>H</i><i>iệu trưởng, các vị lãnh đạo Nhà trường,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các giáo sư, giảng viên, các nhà nghiên cứu, các sinh viên và bạn bè của Việt Nam tại Đại học Oxford,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa toàn thể quý vị,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi cùng đoàn đại biểu Việt Nam rất vui khi có mặt tại trường Đại học có truyền thống lâu đời trong việc thúc đẩy tự do học thuật và khai phóng tri thức toàn cầu. Oxford là một trong những trung tâm giáo dục Đại học hàng đầu của thế giới, là biểu tượng tri thức của nước Anh, là nơi đã đào tạo nhiều thế hệ những con người dấn thân cho hòa bình, công lý và sự tiến bộ của nhân loại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Được chia sẻ tầm nhìn của Việt Nam trong kỷ nguyên mới với các bạn, đặc biệt là với những người trẻ đang chuẩn bị định hình tương lai thế giới, với các nhà khoa học và hoạch định chính sách tương lai là một vinh dự đối với chúng tôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong buổi gặp mặt hôm nay, tôi muốn nói với các bạn ba nội dung:&nbsp;<i>Thứ nhất</i>: thế giới đang bước vào một giai đoạn cạnh tranh chiến lược gay gắt, đầy rủi ro nhưng cũng mở ra các cơ hội phát triển mới.&nbsp;<i>Thứ hai</i>: Việt Nam lựa chọn con đường phát triển hòa bình, độc lập, tự chủ, tự cường, sáng tạo, vì con người, không chỉ để xây dựng một đất nước giàu mạnh cho nhân dân mình, mà còn để đóng góp có trách nhiệm cho ổn định khu vực và trật tự quốc tế dựa trên luật pháp quốc tế.&nbsp;<i>Thứ ba:</i>&nbsp;Quan hệ Đối tác Chiến lược Toàn diện giữa Việt Nam và Vương quốc Anh, cấp độ hợp tác cao nhất trong chính sách đối ngoại của Việt Nam, cần và sẽ trở thành một hình mẫu hợp tác mới, thực chất, bình đẳng, cùng có lợi, cùng phát triển.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm phát biểu chính sách tại Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" h=\"1003\" id=\"img_907672005582757888\" loading=\"lazy\" photoid=\"907672005582757888\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" style=\"width: 700px; height: 439px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 2.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm phát biểu chính sách tại Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các quý</i><i>&nbsp;</i><i>vị</i><i>,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng ta đang sống trong một thời kỳ mà các đường biên giới và khái niệm quyền lực đang thay đổi từng ngày, thậm chí từng giờ. Cục diện địa chính trị đang chứng kiến cạnh tranh chiến lược giữa các trung tâm quyền lực lớn, không chỉ về ảnh hưởng chính trị-an ninh mà cả trong kinh tế, công nghệ, chuỗi cung ứng, tiêu chuẩn dữ liệu, trí tuệ nhân tạo và công nghệ sinh học. Cạnh tranh trong đổi mới sáng tạo, trong quyền kiểm soát các công nghệ lõi, trong năng lượng sạch, trong hạ tầng số, đã trở thành cuộc đua quyền lực mới. Nói một cách thẳng thắn: ai làm chủ chiến lược, ai nắm công nghệ chiến lược, người đó sẽ định hình luật chơi và nhiều khả năng đó là người chiến thắng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng lúc đó, các nguy cơ xung đột cục bộ, tranh chấp chủ quyền, lãnh thổ, va chạm lợi ích trên biển, trên không gian mạng, trong không gian số, gia tăng cả về tần suất lẫn mức độ phức tạp. Áp lực \"chọn bên\", \"phân cực\", \"liên minh để kiềm chế nhau\" xuất hiện trở lại dưới những hình thức tinh vi hơn. Những đường ranh mới không chỉ nằm ở lãnh thổ, kinh tuyến, vĩ tuyến mà nằm trong dữ liệu, trong công nghệ, trong chuỗi giá trị. Thế giới dường như đang<b>&nbsp;</b>vận hành đồng thời theo hai xu hướng: vừa kết nối sâu hơn, vừa chia rẽ nhanh hơn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" target=\"_blank\" title=\"Các đại biểu dự buổi phát biểu chính sách của Tổng Bí thư Tô Lâm tại Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" h=\"1066\" id=\"img_907672105477570560\" loading=\"lazy\" photoid=\"907672105477570560\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" style=\"width: 700px; height: 467px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 3.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu dự buổi phát biểu chính sách của Tổng Bí thư Tô Lâm tại Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những thách thức an ninh truyền thống và phi truyền thống đan xen: an ninh năng lượng, an ninh lương thực, an ninh nguồn nước, biến đổi khí hậu, dịch bệnh toàn cầu, tội phạm công nghệ cao, tấn công mạng vào các hệ thống trọng yếu. Không một quốc gia nào, dù lớn hay nhỏ, có thể tự mình xử lý tất cả các rủi ro này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cạnh tranh địa kinh tế ngày nay không chỉ là vấn đề thị trường, thuế quan hay thâm hụt thương mại. Đó là cạnh tranh giành chuỗi cung ứng chiến lược, giành quyền tiếp cận khoáng sản quan trọng, giành quyền đặt chuẩn mực công nghệ mới. Nhiều nước đang điều chỉnh chiến lược công nghiệp, thúc đẩy \"tự cường\", \"đa dạng hóa\", \"giảm phụ thuộc\", \"an ninh chuỗi cung ứng\". Điều đó đang định hình lại bản đồ sản xuất toàn cầu và tái cấu trúc luồng đầu tư.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong bối cảnh đó, câu hỏi đặt ra cho các quốc gia không chỉ là \"đứng về phía ai, đứng ở đâu\", mà là \"đứng vững bằng cách nào, tự chủ như thế nào\". Đối với Việt Nam, đó cũng là câu hỏi sinh tử.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam chọn con đường hòa bình, độc lập, tự chủ, hợp tác cùng phát triển. Việt Nam là một dân tộc đã phải giành độc lập bằng xương máu và đã trả giá cho chiến tranh để có hòa bình. Chúng tôi hiểu rõ giá trị tối thượng của hòa bình. Chân lý&nbsp;<i>\"không có gì quý hơn độc lập, tự do\"</i>&nbsp;của Chủ tịch Hồ Chí Minh là kim chỉ nam cho hành động của dân tộc tôi. Đó là nền tảng đạo lý và nguyên tắc sống của chúng tôi trong đời sống xã hội và quan hệ quốc tế hôm nay.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam trong khuôn viên trường Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" h=\"1099\" id=\"img_907672261116534784\" loading=\"lazy\" photoid=\"907672261116534784\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" style=\"width: 700px; height: 481px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 4.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam trong khuôn viên trường Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong một thế giới đầy sức ép chọn bên, Việt Nam kiên trì đường lối đối ngoại độc lập, tự chủ, đa phương hóa, đa dạng hóa quan hệ đối ngoại; Việt Nam mong muốn là bạn, là đối tác tin cậy, là thành viên có trách nhiệm của cộng đồng quốc tế. Việt Nam nỗ lực xây dựng \"trong ấm, ngoài êm\": giữ ổn định chính trị- phát triển kinh tế, xã hội bên trong, giữ môi trường hòa bình, hợp tác, tôn trọng lẫn nhau bên ngoài; xử lý khác biệt bằng biện pháp hòa bình và luật pháp quốc tế; đặt con người, lợi ích chính đáng của nhân dân lên trên hết, trước hết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi kiên định nguyên tắc: bảo vệ vững chắc độc lập, chủ quyền, toàn vẹn lãnh thổ; đồng thời tạo dựng môi trường bên ngoài thuận lợi nhất để phát triển đất nước, nâng cao chất lượng cuộc sống của người dân, thu hẹp khoảng cách phát triển, đóng góp vào hòa bình, ổn định chung của khu vực và&nbsp;<b>phạm</b><b>&nbsp;vi toàn</b>&nbsp;thế giới. Chúng tôi bảo vệ Tổ quốc bằng hòa bình, bằng luật pháp quốc tế, bằng văn hóa, truyền thống dân tộc, bằng hợp tác cùng có lợi. Đó là lựa chọn chiến lược chủ động, có trách nhiệm&nbsp;<b>của Việt Nam chúng tôi.</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi muốn nhấn mạnh rằng: Việt Nam không cổ vũ đối đầu. Việt Nam không chọn cách phát triển dựa trên xung đột hay đối kháng. Chúng tôi tin vào đối thoại bình đẳng, tin vào luật pháp quốc tế, tin rằng chủ quyền không nên được khẳng định bằng súng đạn, bằng áp đặt, mà bằng sự tôn trọng lẫn nhau, bằng thỏa thuận tôn trọng luật lệ chung và bằng lợi ích cùng chia sẻ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tinh thần đó đã giúp Việt Nam vừa giữ được ổn định chính trị-xã hội, vừa chủ động hội nhập kinh tế quốc tế, tham gia các hiệp định thương mại tự do thế hệ mới, mở rộng hợp tác nhiều tầng nấc với các đối tác ở mọi khu vực, trong đó có Vương quốc Anh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa</i><i>&nbsp;các bạn</i><i>,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Muốn tiến xa, tiến nhanh, ổn định, bền vững và chủ động, chúng tôi hiểu rằng không thể chỉ dựa vào tài nguyên thiên nhiên, lao động giá rẻ, hay lợi thế về nguồn nhân công... Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi đang thúc đẩy mạnh mẽ chiến lược chuyển đổi số quốc gia, phát triển kinh tế số, kinh tế xanh, kinh tế tuần hoàn, kinh tế carbon thấp. Chúng tôi coi đổi mới sáng tạo không chỉ là phòng thí nghiệm khoa học thuần túy, mà là sức sống của nền kinh tế, là năng lực cạnh tranh quốc gia, là khả năng đứng vững trước các cú sốc địa chính trị và địa kinh tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều đó kéo theo yêu cầu cải cách thể chế. Chúng tôi tiếp tục xây dựng và hoàn thiện mô hình&nbsp;<i>\"kinh tế thị trường định hướng xã hội chủ nghĩa\"</i>: một nền kinh tế vận hành theo quy luật thị trường, khuyến khích cạnh tranh lành mạnh, tôn trọng vai trò của doanh nghiệp tư nhân như một động lực quan trọng của tăng trưởng; đồng thời khẳng định vai trò định hướng, dẫn dắt, điều tiết của Nhà nước pháp quyền xã hội chủ nghĩa, dưới sự lãnh đạo của Đảng Cộng sản Việt Nam, nhằm bảo đảm phát triển đi đôi với tiến bộ và công bằng xã hội.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nói ngắn gọn: chúng tôi coi kinh tế tư nhân là động lực quan trọng nhất để thúc đẩy tốc độ phát triển kinh tế; coi khu vực kinh tế nhà nước là lực lượng giữ vai trò dẫn dắt, bảo đảm ổn định vĩ mô, an ninh kinh tế, an ninh năng lượng, an ninh lương thực; coi Nhà nước pháp quyền, quản trị liêm chính, phòng chống tham nhũng, lãng phí, lợi ích nhóm là điều kiện để xã hội tin tưởng, để nguồn lực xã hội được phân bổ hiệu quả, để mọi&nbsp;<b>n</b>gười dân được hưởng thành quả phát triển một cách công bằng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng lúc, chúng tôi đặt con người ở vị trí trung tâm của mọi chiến lược phát triển. Mục tiêu chính không phải là những con số thống kê tăng trưởng, mà là nâng cao thực sự chất lượng cuộc sống của người dân: thu nhập, nhà ở, y tế công, giáo dục chất lượng, an sinh xã hội, cơ hội phát triển cá nhân, môi trường sống an toàn, trong lành. Chúng tôi muốn tăng trưởng mà không đánh đổi môi trường. Chúng tôi muốn công nghiệp hóa mà không đánh mất văn hóa. Chúng tôi muốn đô thị hóa nhưng không để ai bị bỏ lại phía sau.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đây là điểm rất căn bản trong tư duy phát triển của Việt Nam: tăng trưởng nhanh phải gắn liền với phát triển bền vững; phát triển bền vững phải dựa trên tri thức, khoa học-công nghệ và đổi mới sáng tạo; đổi mới sáng tạo chỉ có ý nghĩa khi người dân được hưởng lợi thực chất, công bằng, bình đẳng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên nền tảng đó, Việt Nam đặt ra hai mục tiêu chiến lược rất rõ ràng, chúng tôi gọi đó là hai mục tiêu 100 năm. Mục tiêu thứ nhất: đến năm 2030, đánh dấu 100 năm đất nước phát triển dưới sự lãnh đạo của Đảng Cộng sản Việt Nam, chúng tôi quyết tâm trở thành nước đang phát triển có công nghiệp hiện đại, thu nhập trung bình cao. Mục tiêu thứ hai: đến năm 2045, kỷ niệm 100 năm thành lập nước CHXHCN Việt Nam, Việt Nam phấn đấu trở thành nước phát triển, thu nhập cao, có nền kinh tế hiện đại, xã hội văn minh, người dân có đời sống vật chất và tinh thần ở mức cao, đất nước có vị thế xứng đáng trong cộng đồng quốc tế. Đây là cam kết chính trị-lịch sử mà chúng tôi tuyên bố trước nhân dân mình và trước cộng đồng quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa</i><i>&nbsp;các bạn,</i><i></i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam và Vương quốc Anh thiết lập quan hệ ngoại giao vào năm 1973. Từ đó đến nay, hai bên đã đi một chặng đường dài và đầy ý nghĩa, bất chấp những khác biệt về địa lý, trình độ phát triển và hệ thống chính trị.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2010, hai nước ký Tuyên bố chung thiết lập Quan hệ Đối tác Chiến lược. Đây là một bước ngoặt lớn, mở ra hợp tác sâu rộng trên nhiều lĩnh vực như chính trị-ngoại giao, thương mại-đầu tư, giáo dục-đào tạo, khoa học- công nghệ, quốc phòng-an ninh, phát triển bền vững và giao lưu nhân dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đến nay, hợp tác kinh tế-thương mại giữa Việt Nam và Vương quốc Anh ngày càng mang tính chiến lược cao. Sau khi Vương quốc Anh rời Liên minh châu Âu, hai nước đã ký hiệp định thương mại tự do song phương dựa trên nền tảng các cam kết chất lượng cao, qua đó bảo đảm tính liên tục của dòng thương mại và đầu tư. Đồng thời, Vương quốc Anh đã tham gia Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP), nơi Việt Nam là một trong các thành viên sáng lập, tạo thêm một cấu trúc hợp tác kinh tế mở, dựa trên tiêu chuẩn cao về thương mại số, sở hữu trí tuệ, dịch vụ và đầu tư.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hợp tác giáo dục là một trụ cột rất nổi bật. Hàng chục nghìn sinh viên Việt Nam đã, đang học tập tại Anh trên các lĩnh vực từ khoa học kỹ thuật, công nghệ thông tin, tài chính, y khoa, y sinh học, đến chính sách công và đào tạo nguồn nhân lực chất lượng cao chính là chiếc cầu tri thức nối hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày hôm nay, chúng ta đứng trước một bước phát triển mới: hai nước đang thúc đẩy nâng cấp quan hệ lên Đối tác Chiến lược Toàn diện-cấp độ cao nhất trong hệ thống đối ngoại của Việt Nam. Đây là sự khẳng định rõ ràng rằng Việt Nam coi Anh không chỉ là một đối tác thương mại, một đối tác giáo dục, một đối tác về khoa học công nghệ, mà là một đối tác chiến lược dài hạn để cùng nhau định hình các chuẩn mực hợp tác trong thế kỷ XXI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Tôi muốn nhấn mạnh hai điều.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ nhất:&nbsp;</i>Quan hệ Việt Nam-Vương quốc Anh là mối quan hệ hữu nghị, hợp tác và cùng phát triển. Đây là một quan hệ đối tác mà cả hai bên đều có lợi ích căn bản trong việc duy trì hòa bình, ổn định, tôn trọng luật pháp quốc tế, bảo đảm tự do hàng hải, bảo vệ chuỗi cung ứng toàn cầu, thúc đẩy thương mại công bằng và bền vững, ứng phó biến đổi khí hậu, phát triển xanh, phát triển bao trùm. Nói cách khác, đây là sự gặp nhau giữa nhu cầu tham gia sâu hơn vào khu vực châu Á-Thái Bình Dương của Anh và nhu cầu mở rộng không gian chiến lược, công nghệ, giáo dục, tài chính chất lượng cao của Việt Nam với Anh, với châu Âu, với cộng đồng quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai:</i>&nbsp;chúng ta cần một mô hình hợp tác mới-thiết thực, có thể đo đếm, lan tỏa lợi ích trực tiếp tới người dân hai nước. Khi tôi nói \"một hình mẫu hợp tác mới\", tôi muốn nói đến sự hợp tác giữa thế mạnh khoa học cơ bản, khoa học ứng dụng, công nghệ cao, y sinh, y tế cộng đồng, giáo dục đại học, quản trị đô thị, chuyển đổi năng lượng, dịch vụ tài chính, của Vương quốc Anh với nhu cầu chuyển đổi số, chuyển đổi xanh, nâng cao chất lượng nguồn nhân lực, đổi mới quản trị phát triển, hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đó không chỉ là hợp tác \"chuyển giao công nghệ\". Đó là đồng kiến tạo tương lai. Tôi tin rằng chính Oxford-với truyền thống kết nối tri thức và chính sách công, với mạng lưới cựu sinh viên có ảnh hưởng trên toàn thế giới- có thể đóng vai trò rất cụ thể trong quá trình này. Tôi hình dung ít nhất bốn hướng: (1) Hợp tác đào tạo và nghiên cứu chung trong các lĩnh vực then chốt như y tế cộng đồng<b>,</b>&nbsp;công nghệ sinh học, khoa học hạt nhân, khoa học cơ bản, trí tuệ nhân tạo có trách nhiệm, biến đổi khí hậu, chính sách năng lượng sạch. (2) Chương trình trao đổi chuyên gia giữa các viện nghiên cứu chính sách của Việt Nam và các trung tâm nghiên cứu chính sách, quản trị công, phát triển bền vững tại Anh, để cùng xây dựng khuyến nghị chính sách có thể áp dụng được vào thực tiễn, đem lại những kết quả hữu hiệu, cụ thể cho những nơi áp dụng, ứng dụng những khuyến nghị của các bạn. (3) Hợp tác hỗ trợ đổi mới sáng tạo và khởi nghiệp công nghệ cho doanh nghiệp Việt Nam, đặc biệt là doanh nghiệp vừa và nhỏ, doanh nghiệp khởi nghiệp đổi mới sáng tạo, những chủ thể sẽ quyết định tốc độ chuyển đổi số và chuyển đổi xanh của nền kinh tế Việt Nam trong thập kỷ tới. (4) Cùng nhau thử nghiệm các mô hình phát triển đô thị bền vững, tài chính xanh, giáo dục mở, y tế số và chăm sóc sức khỏe cộng đồng, những lĩnh vực mà cả hai bên đều quan tâm và đều có nhu cầu cấp bách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu chúng ta làm được những điều đó, thì quan hệ Việt Nam-Vương quốc Anh sẽ không chỉ là những tuyên bố chính trị cấp cao. Nó sẽ trở thành một nguồn lực sống, một mạng lưới tri thức và công nghệ trải dài từ Hà Nội đến London, từ Thành phố Hồ Chí Minh đến Oxford, giữa các viện nghiên cứu, trường Đại học, doanh nghiệp, thậm chí từ người dân đến người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các bạn,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam bước vào giai đoạn phát triển mới với khát vọng mạnh mẽ: xây dựng một đất nước hùng cường, thịnh vượng, nhân ái; một nền kinh tế hiện đại, xanh, thông minh; một xã hội công bằng, văn minh, nơi người dân được bảo đảm an ninh con người, được tạo điều kiện phát triển toàn diện. Chúng tôi phấn đấu vì mục tiêu \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\". Đây là định hướng nhất quán trong chiến lược phát triển quốc gia của chúng tôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi tin vào sức mạnh của nhân nghĩa. Từ lịch sử, dân tộc Việt Nam luôn lấy nhân nghĩa để thắng hung tàn, lấy chí nhân để thay cường bạo. Chúng tôi tin rằng sức mạnh bền vững nhất của một quốc gia không chỉ là sức mạnh quân sự hay tài chính, mà là sức mạnh đạo lý, sức mạnh gắn kết lòng dân, sức mạnh tạo dựng niềm tin với bạn bè quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi yêu chuộng hòa bình, khát vọng tự do và phát triển. Chúng tôi tìm kiếm hợp tác bình đẳng. Chúng tôi không chấp nhận áp đặt. Chúng tôi tôn trọng luật pháp quốc tế. Chúng tôi không muốn thế giới chia rẽ thành các khối đối đầu mà mong mỏi một thế giới đoàn kết vì \"trái đất này là của chúng ta\". Chúng tôi muốn thế giới cùng nhau phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên tinh thần đó, tôi mong muốn rằng thế hệ trẻ tại Anh, các viện nghiên cứu, các trường đại học, các doanh nghiệp đổi mới sáng tạo, các tổ chức xã hội dân sự, các nhà hoạch định chính sách tương lai-&nbsp;<b>hãy luôn</b><b>&nbsp;tin rằng có một người bạn</b>&nbsp;<b>Việt Nam</b>&nbsp;là một đối tác chân thành, đáng tin cậy, cùng chia sẻ trách nhiệm và lợi ích trong một trật tự thế giới đang tái định hình.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi tin rằng nếu chúng ta cùng chung tay xây dựng một khuôn khổ hợp tác chiến lược toàn diện, thực chất, dựa trên tôn trọng lẫn nhau, dựa trên cùng có lợi, dựa trên tầm nhìn dài hạn, thì quan hệ Việt Nam-Vương quốc Anh không chỉ tiến thêm một nấc mới trên bản đồ ngoại giao thời đại mới. Đó sẽ trở thành một lực đẩy, một hình mẫu, một câu chuyện thành công chung- không chỉ cho hai nước chúng ta, mà cho cả hòa bình, ổn định và phát triển bền vững trong thế kỷ XXI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xin trân trọng cảm ơn các quý vị.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xin cảm ơn Đại học Oxford đã tạo không gian để chúng ta trao đổi thẳng thắn, cởi mở, khách quan, cùng nhau nghĩ về một tương lai tốt đẹp hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi xin trân trọng cảm ơn.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/phat-bieu-cua-tong-bi-thu-to-lam-tai-ai-hoc-oxford-29278299', '', 'chinhphu.vn', 33, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.690869', 9, 11);
INSERT INTO `sync_articles` VALUES (150, '29279415', 'Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh', 'Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland từ ngày 28 - 30/10, Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam đã dự buổi tọa đàm với các nhà chiến lược về trí tuệ nhân tạo (AI) và công nghệ hàng đầu của Anh cũng như thế giới.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm dự toạ đàm với các chuyên gia công nghệ của Anh và thế giới về AI và chip bán dẫn - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" h=\"541\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" style=\"width: 700px; height: 569px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 1.\" type=\"photo\" w=\"665\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm dự toạ đàm với các chuyên gia công nghệ của Anh và thế giới về AI và chip bán dẫn - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tọa đàm diễn ra sáng 28/10 theo giờ địa phương tại thủ đô London, do Diễn đàn Toàn cầu Boston (BGF) phối hợp tổ chức và là bước đi chiến lược nhằm thúc đẩy hợp tác giữa Việt Nam và các cường quốc công nghệ trong kỷ nguyên AI, đồng thời khẳng định vị thế của Việt Nam trong chuyển đổi số toàn cầu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sự kiện diễn ra trong bối cảnh thế giới đang chứng kiến sự bùng nổ của AI và chip bán dẫn, hai lĩnh vực định hình tương lai kinh tế toàn cầu. Với khát vọng trở thành quốc gia tiên phong trong kinh tế số, Việt Nam mong muốn học hỏi kinh nghiệm từ Anh - cái nôi của Cách mạng công nghiệp và quê hương của những trí tuệ vĩ đại như Isaac Newton, John Locke, Adam Smith, Alan Turing, William Shakespeare và Charles Dickens - để xây dựng một hệ sinh thái công nghệ sáng tạo, nhân văn và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu mở đầu tọa đàm, Tổng Bí thư Tô Lâm bày tỏ vui mừng khi gặp gỡ và lắng nghe những ý kiến tâm huyết, thiết thực của các chuyên gia và các nhà chiến lược tại London, một trung tâm công nghệ và sáng tạo của thế giới. Tổng Bí thư nhấn mạnh thế giới đang chứng kiến sự phát triển vượt bậc của khoa học công nghệ, nhất là khi AI trở thành động lực then chốt thúc đẩy tăng trưởng kinh tế và đổi mới sáng tạo.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" h=\"462\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" style=\"width: 700px; height: 486px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 2.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: justify;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam cũng đã xác định khoa học công nghệ và chuyển đổi số là điểm đột phá hàng đầu để phát triển nhanh, bền vững và vươn lên trong chuỗi giá trị toàn cầu. Vì vậy, Việt Nam mong muốn đồng hành cùng các nước tiên tiến nhằm chia sẻ tầm nhìn và giá trị chung, qua đó xây dựng một thế giới tốt đẹp hơn, nơi AI phục vụ con người, thúc đẩy sáng tạo, nhân ái, hòa bình và thịnh vượng. Tổng Bí thư nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam. Chỉ trong vòng một thế hệ, Việt Nam đã đưa hàng triệu người thoát nghèo, xây dựng một trong những nền kinh tế sản xuất cạnh tranh nhất châu Á và có lực lượng lao động trẻ, thành thạo kỹ năng số. Đặc biệt, những tiến bộ trong cải cách hành chính của Việt Nam, sự cởi mở trong hợp tác quốc tế đã định vị Việt Nam trở thành một đối tác chủ chốt trong mạng lưới toàn cầu của những quốc gia số đáng tin cậy. Một số ý kiến cũng khuyến nghị, để AI thực sự phục vụ cho quá trình phát triển kinh tế - xã hội nhằm mang lại cuộc sống tốt hơn cho người dân, chính phủ các nước cần chú trọng xây dựng hạ tầng số tin cậy, phát triển các tiêu chuẩn AI có trách nhiệm bảo vệ quyền riêng tư, công bằng và minh bạch…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" target=\"_blank\" title=\"Các chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" h=\"483\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" style=\"width: 700px; height: 508px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 3.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu kết luận tọa đàm, Tổng Bí thư Tô Lâm bày tỏ ấn tượng với các vấn đề và ý tưởng được các chuyên gia, nhà quản lý có nhiều kinh nghiệm trong lĩnh vực AI trình bày, đồng thời cho rằng những giải pháp, khuyến nghị đã nêu rất phù hợp với định hướng, mục tiêu phát triển của Việt Nam. Tổng Bí thư cho biết sẽ giao cơ quan chức năng nghiên cứu, phối hợp làm rõ nội dung, tiến tới triển khai các bước cụ thể nhằm biến ý tưởng thành các dự án, chương trình tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh buổi tọa đàm là bước khởi đầu đầy ý nghĩa và sẽ mở ra hành trình hợp tác lâu dài, sâu sắc giữa Việt Nam với các trí tuệ, tinh hoa của Vương quốc Anh và thế giới. Tổng Bí thư mong muốn trong thời gian tới, các chuyên gia tiếp tục đồng hành, hỗ trợ Việt Nam phát triển về AI nói riêng và khoa học - công nghệ nói chung, đặc biệt trong ba lĩnh vực ưu tiên gồm chia sẻ tri thức và kinh nghiệm trong hoạch định chiến lược AI quốc gia, phát triển hạ tầng số và hệ sinh thái đổi mới sáng tạo; thúc đẩy đầu tư và chuyển giao công nghệ, ứng dụng AI trong các lĩnh vực trọng điểm như y tế, nông nghiệp thông minh và giáo dục số; và cùng Việt Nam triển khai thành công các chương trình trọng điểm về khoa học công nghệ, nhất là các lĩnh vực mới, tiên phong nhằm giúp Việt Nam xây dựng nền kinh tế sáng tạo, tự cường.</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 4.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" h=\"445\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" style=\"width: 700px; height: 468px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></span></span></span></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam để có thêm nhiều thời gian trao đổi và điều kiện làm việc trực tiếp với các cơ quan hoạch định, thực thi chính sách khoa học công nghệ của Việt Nam nhằm sớm đưa những ý tưởng được thảo luận trong cuộc tọa đàm trở thành hiện thực, mang lại nhiều giá trị mới, mô hình mới và niềm tin mới cho nhân loại trong kỷ nguyên AI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi tọa đàm không chỉ góp phần củng cố quan hệ hợp tác toàn diện giữa Việt Nam và Anh mà còn mở ra triển vọng phát triển trong lĩnh vực AI và chip bán dẫn cho nền kinh tế Việt Nam. Sự kiện đánh dấu bước tiến quan trọng trong hành trình đưa Việt Nam trở thành quốc gia tiên phong trong kinh tế số và sáng tạo toàn cầu, đồng thời góp phần xây dựng một thế giới nơi công nghệ phục vụ con người, thúc đẩy hòa bình và thịnh vượng.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-du-toa-am-ve-cong-nghe-ai-va-chip-ban-dan-tai-anh-29279415', '', 'chinhphu.vn', 25, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.730380', 9, 11);
INSERT INTO `sync_articles` VALUES (151, '29280301', 'Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản', 'Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland, sáng 28/10 (giờ địa phương), Tổng Bí thư Tô Lâm và Phu nhân Ngô Phương Ly cùng Đoàn đại biểu cấp cao Việt Nam đã đến viếng mộ Lãnh tụ giai cấp vô sản, Karl Marx, tại nghĩa trang Highgate, thủ đô London.</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm đặt vòng hoa viếng tại mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" h=\"535\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" style=\"width: 700px; height: 563px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 1.\" type=\"photo\" w=\"665\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm đặt vòng hoa viếng tại mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhà triết học Karl Marx sinh năm 1818 tại Đức, định cư tại London năm 1849 cho tới khi ông qua đời năm 1883. Ông là lãnh tụ kiệt xuất của giai cấp công nhân, nhân dân lao động, các dân tộc bị áp bức và loài người tiến bộ nói chung.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngôi mộ của Karl Marx tọa lạc tại Nghĩa trang Highgate, là điểm dừng chân vừa mang đậm ý nghĩa lịch sử - tư tưởng, vừa là địa danh tham quan nổi bật của thủ đô nước Anh. Ban đầu, vào năm 1883, nhà tư tưởng Karl Marx được chôn cất tại một vị trí khiêm tốn trong nghĩa trang này. Sau đó, năm 1954, thi hài ông và các thành viên trong gia đình được di chuyển vào cùng một khu vực và đặt dưới một đài tưởng niệm lớn hơn, được khánh thành năm 1956.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam tưởng niệm trước mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" h=\"507\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" style=\"width: 700px; height: 533px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 2.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam tưởng niệm trước mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đài mộ do nhà điêu khắc Laurence Bradshaw thiết kế gồm một bức phù điêu bán thân bằng đồng của Karl Marx đặt trên bệ đá cẩm thạch khắc dòng khẩu hiệu nổi tiếng \"Workers of all lands, unite\" (Vô sản toàn thế giới, liên hiệp lại) - được trích từ tác phẩm The Communist Manifesto (Tuyên ngôn của Đảng Cộng sản) của ông. Vị trí hiện tại của ngôi mộ đã được xếp hạng “Grade I listed\" - hạng cao nhất dành cho các di sản có giá trị xuất sắc về kiến trúc, lịch sử tại Anh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngôi mộ không chỉ là nơi an nghỉ mà còn mang tính biểu tượng mạnh mẽ. Nhiều người theo tư tưởng Marxist, học giả và du khách quốc tế đến đây như một cuộc hành hương tinh thần để tưởng nhớ tác giả của những ý tưởng ảnh hưởng sâu rộng đến chính trị, xã hội thế giới.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam viếng mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" h=\"485\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" style=\"width: 700px; height: 511px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 3.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam viếng mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghĩa trang Highgate nằm trên một quả đồi ở vùng ngoại ô phía Bắc London, tạo cho người đến viếng thăm một cảm giác thanh bình, trầm lắng. Đây cũng là nơi an nghỉ của nhiều nhân vật nổi tiếng như nhà vật lý học Michael Faraday, cha mẹ của nhà văn Charles Dickens, nhà triết học, xã hội học, chính trị học Herbert Spencer, nhà văn George Eliot…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và các đại biểu tại mộ Karl Marx ở nghĩa trang Highgate, thủ đô London - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 4.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" h=\"463\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" style=\"width: 700px; height: 487px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và các đại biểu tại mộ Karl Marx ở nghĩa trang Highgate, thủ đô London - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghĩa trang mở cửa đón du khách với thời gian và quy định riêng. Khi đến Nghĩa trang Highgate, du khách có thể tìm đến phần phía Đông (East Side) để nhìn thấy rõ đài mộ Karl Marx, nổi bật giữa không gian tĩnh lặng, xanh mướt./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-vieng-karl-marx-lanh-tu-cua-giai-cap-vo-san-29280301', '', 'chinhphu.vn', 11, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.764126', 9, 11);
INSERT INTO `sync_articles` VALUES (152, '29281340', 'Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng', 'Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg', '<p>Trả lời phỏng vấn báo chí ngay sau khi Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan tại Malaysia vừa kết thúc, Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang cho biết đoàn Việt Nam do Thủ tướng Phạm Minh Chính dẫn đầu đã tiếp tục thể hiện vai trò thành viên tích cực, có trách nhiệm với...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị Cấp cao ASEAN-Trung Quốc 28  - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" h=\"1334\" id=\"img_907459773483909120\" loading=\"lazy\" photoid=\"907459773483909120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị Cấp cao ASEAN-Trung Quốc 28 - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin&nbsp;</i><i>Thứ trưởng cho biết kết quả các Hội nghị Cấp cao ASEAN và giữa ASEAN với các đối tác?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Diễn ra trong bối cảnh thế giới có nhiều biến động, đặt ra thách thức cho toàn cầu và khu vực, Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan vừa khép lại với nhiều kết quả quan trọng. Trong đó có những điểm nhấn nổi bật như sau:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Trước hết,</i>&nbsp;Hội nghị ghi nhận thành quả 10 năm xây dựng cộng đồng thông qua triển khai Tầm nhìn ASEAN 2025, là cơ sở để ASEAN triển khai thành công Tầm nhìn Cộng đồng ASEAN (ACV) 2045 cùng các Kế hoạch Chiến lược về chính trị-an ninh, kinh tế, văn hóa-xã hội và kết nối ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội nghị đã thông qua gần 70 văn kiện thuộc ba trụ cột chính trị-an ninh, kinh tế và văn hóa-xã hội, cụ thể hóa cam kết của ASEAN với tiến trình xây dựng cộng đồng và thúc đẩy quan hệ đối tác thời gian tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc kết nạp Timor-Leste là một dấu mốc đáng nhớ, đánh dấu lần mở rộng thứ hai của ASEAN sau 30 năm (đợt thứ nhất bắt đầu với Việt Nam năm 1995). Đây là sự bổ sung đúng thời điểm nhằm mở rộng không gian phát triển, tạo thế và lực mới cho tiến trình phát triển của Hiệp hội.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai</i>, ASEAN tiếp tục thể hiện vai trò trung tâm và dẫn dắt trong việc duy trì hoà bình, ổn định ở khu vực, thể hiện qua việc hỗ trợ Campuchia và Thái Lan đã ký Tuyên bố chung triển khai các thỏa thuận đảm bảo hòa bình và bình thường hóa quan hệ tại biên giới, góp phần củng cố an ninh, ổn định chung của khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các nước cũng đánh giá cao vai trò và nỗ lực của Chủ tịch Malaysia trong thúc đẩy thực thi Đồng thuận 5 điểm về Myanmar; nhất trí Đồng thuận tiếp tục là định hướng chính cho các nỗ lực can dự của ASEAN thời gian tới, trong đó ưu tiên ngừng bắn và chấm dứt các hành động bạo lực, nối lại đối thoại và triển khai viện trợ nhân đạo đến người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sự tham gia đông đảo của lãnh đạo cấp cao các nước đối tác và các tổ chức quốc tế như Tổng thống Hoa Kỳ, Thủ tướng Trung Quốc, Tổng Thư ký Liên hợp quốc, Chủ tịch Hội đồng châu Âu... cũng một lần nữa khẳng định vị thế của ASEAN trong chính sách của các nước đối tác lớn, các nước lớn trên thế giới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ ba,</i>&nbsp;Hội nghị một lần nữa khẳng định vị thế của ASEAN với tư cách một động lực tăng trưởng và mắt xích không thể thiếu trong chuỗi cung ứng, kết nối thương mại và đầu tư toàn cầu, với GDP 3,8 nghìn tỷ USD (2023), đầu tư nước ngoài 226 tỷ USD (2024) và mạng lưới 08 hiệp định thương mại bao trùm cả khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm nâng cao tự chủ về kinh tế, củng cố liên kết nội khối, ASEAN đã nâng cấp Hiệp định thương mại hàng hóa (ATIGA), cơ bản hoàn tất Hiệp định khung kinh tế số (DEFA), và thúc đẩy kết nối Lưới điện ASEAN (APG). Đồng thời ASEAN cũng thống nhất về chiến lược tranh thủ các xu thế lớn như kinh tế xanh, kinh tế số, trí tuệ nhân tạo, ứng phó các thách thức nổi lên như tội phạm xuyên quốc gia, tội phạm mạng, biến đổi khí hậu…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội nghị đã thể hiện cam kết dài hạn của ASEAN với chủ nghĩa đa phương thông qua thực hiện hiệu quả các Hiệp định Thương mại Tự do (FTA) với đối tác, mà điểm nhấn là nâng cấp FTA ASEAN-Trung Quốc (ACFTA 3.0), xúc tiến nâng cấp FTA với Hàn Quốc và nghiên cứu đàm phán FTA với EU và GCC…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị ASEAN – Australia - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" h=\"518\" id=\"img_907600895319187456\" loading=\"lazy\" photoid=\"907600895319187456\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 2.\" type=\"photo\" w=\"777\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" id=\"\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị ASEAN – Australia - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng trong dịp này, Việt Nam tiếp tục thể hiện vai trò thành viên tích cực, có trách nhiệm với hai đóng góp quan trọng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ nhất là dưới sự điều phối của Việt Nam, ASEAN và New Zealand ra Tuyên bố chung nâng cấp quan hệ lên Đối tác Chiến lược Toàn diện và thông qua Kế hoạch hành động 2026-2030 triển khai khuôn khổ vừa thiết lập.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai là trên cương vị Chủ tịch Nhóm đặc trách Sáng kiến hội nhập ASEAN (IAI), Việt Nam chủ trì xây dựng Kế hoạch công tác IAI 2026-2030, được Hội nghị cấp cao thông qua. Văn kiện này hướng tới mục tiêu thu hẹp khoảng cách phát triển, củng cố đoàn kết, ưu tiên hỗ trợ Timor-Leste bắt kịp tiến trình hội nhập chung của ASEAN. Vai trò, nỗ lực của Việt Nam được các nước cảm ơn và đánh giá cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thành công chung, những phát biểu sâu sắc, chân tình, thẳng thắn của Thủ tướng Chính phủ Phạm Minh Chính tại các hội nghị đã nhấn mạnh tầm quan trọng của hòa bình, ổn định, nêu rõ đây là điều kiện tiên quyết cho phát triển, đề cao ý nghĩa của đoàn kết ASEAN, khẳng định cam kết của Việt Nam đóng góp cho ASEAN, vì lợi ích thiết thân của người dân và doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những chia sẻ của Thủ tướng Chính phủ, đặc biệt là đề xuất ASEAN phát huy mạnh mẽ ba nguồn lực chiến lược – sức mạnh đoàn kết, sức sống năng động và sức bật đổi mới – đã được các nước thành viên và đối tác ghi nhận, đánh giá cao về tinh thần trách nhiệm, tính đúng đắn của nội dung và tính khả thi, hiệu quả của phương hướng triển khai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin Thứ trưởng chia sẻ những kết quả chính của các cuộc tiếp xúc song phương của Đoàn Việt Nam với các nước, các đối tác trong dịp này?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Chỉ trong 3 ngày dự Hội nghị, Thủ tướng Chính phủ Phạm Minh Chính đã có các cuộc gặp, tiếp xúc song phương với lãnh đạo khoảng hơn 20 đối tác từ bao gồm toàn bộ các quốc gia ASEAN, nhiều lãnh đạo các nước đối tác lớn, lãnh đạo các tổ chức quốc tế và khu vực. Các cuộc gặp, trao đổi tuy ngắn nhưng đạt nhiều kết quả cụ thể và thực chất, nổi bật nhất là:</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Tổng thống Hoa Kỳ Donald Trump - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" h=\"518\" id=\"img_907602656663584768\" loading=\"lazy\" photoid=\"907602656663584768\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 3.\" type=\"photo\" w=\"777\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Tổng thống Hoa Kỳ Donald Trump - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ nhất, tin cậy chính trị giữa Việt Nam và các nước được tăng cường.</i>&nbsp;Các nước đều mong muốn đẩy mạnh quan hệ với Việt Nam. Việc Tổng thống Hoa Kỳ Donald Trump, Thủ tướng Trung Quốc Lý Cường, tân Thủ tướng Nhật Takaichi Sanae, Tổng thống Brazil Lula da Silva, Thủ tướng Canada Mark Carney và nhiều lãnh đạo khác đều nhất trí với đề nghị của Việt Nam về tăng cường trao đổi đoàn cấp cao thời gian tới cho thấy các nước nhìn nhận, đánh giá cao vai trò của Việt Nam ở khu vực, ủng hộ Việt Nam ổn định, phát triển, đóng vai trò ngày càng quan trọng trong ASEAN và trên trường quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai, Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng</i>&nbsp;phản ánh lợi ích chung của Việt Nam với các đối tác. Thủ tướng Trung Quốc Lý Cường nhất trí tích cực thúc đẩy việc khởi công tuyến đường sắt cao tốc Hà Nội – Hải Phòng – Lào Cai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Canada Mark Carney cho biết sẽ sớm công bố dự án trị giá 20 triệu USD xây dựng thành phố thông minh ven biển thích ứng với thiên tai, biến đổi khí hậu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Ngân hàng Thế giới Carlos Felipe Jaramillo khẳng định sẽ đáp ứng các đề nghị của Việt Nam về việc huy động nguồn lực nhanh, hiệu quả hơn trong hỗ trợ các mục tiêu phát triển kinh tế - xã hội của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, điểm nhấn rất quan trọng dịp này là Việt Nam và Hoa Kỳ đã công bố Tuyên bố chung về Hiệp định thương mại đối ứng, công bằng và cân bằng ngày 26/10/2025.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đó đều là những bước tiến quan trọng góp phần tạo nền tảng ổn định, bền vững trong quan hệ của Việt Nam với các đối tác quan trọng, chủ chốt, góp phần huy động thêm nguồn lực bên ngoài để hiện thực hóa các mục tiêu chiến lược của đất nước, đặc biệt là mục tiêu tăng trưởng hai con số từ sau Đại hội Đảng XIV.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Singapore Lawrence Wong - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" h=\"1069\" id=\"img_907503859865079808\" loading=\"lazy\" photoid=\"907503859865079808\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 4.\" type=\"photo\" w=\"1604\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Singapore Lawrence Wong - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ ba, trong trao đổi, có thể thấy các đối tác thực sự ủng hộ, mong muốn Việt Nam đóng vai trò lớn hơn trong ASEAN, ở khu vực Châu Á-Thái Bình Dương cũng như trên trường quốc tế.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lãnh đạo nhiều nước và tổ chức quốc tế rất ấn tượng với tốc độ phát triển của Việt Nam trong mấy chục năm qua. Các đối tác đều khẳng định coi trọng vai trò, vị thế của Việt Nam, mong muốn Việt Nam ủng hộ thúc đẩy quan hệ hợp tác giữa các nước với ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều này cho thấy các nước nhìn nhận Việt Nam là một trong những quốc gia thành viên chủ chốt, có khả năng dẫn dắt trong ASEAN. Trong bối cảnh Việt Nam đang đẩy mạnh triển khai Nghị quyết 59 của Bộ Chính trị về hội nhập quốc tế trong tình hình mới và nâng tầm đối ngoại đa phương, sự tin cậy, ủng hộ của bạn bè quốc tế là vốn chính trị rất quý báu để Việt Nam đóng góp lớn hơn vào nền chính trị thế giới, kinh tế toàn cầu và văn minh nhân loại như Đảng ta và Tổng Bí thư Tô Lâm nhiều lần nhấn mạnh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin ông cho biết các định hướng cụ thể triển khai kết quả của việc Việt Nam tham dự Hội nghị Cấp cao ASEAN lần này?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Hội nghị lần này khép lại năm ASEAN 2025, năm bản lề đánh dấu ASEAN bước sang giai đoạn phát triển mới. Các kết quả đạt được trong các cuộc gặp gỡ, trao đổi của Thủ tướng Chính phủ với lãnh đạo các nước, tổ chức cũng cần được đôn đốc. Bởi vậy việc triển khai các kết quả nhiều mặt có ý nghĩa đặc biệt quan trọng, đòi hỏi sự tham gia chủ động và đồng bộ từ tất cả các Bộ, ngành, địa phương.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Về chỉ đạo – điều hành,</i>&nbsp;chúng ta cần sớm xây dựng Đề án Tổng thể và các chương trình hành động tương ứng để triển khai Tầm nhìn Cộng đồng ASEAN (ACV) 2045, lồng ghép định hướng lớn của các Nghị quyết trụ cột được Bộ Chính trị ban hành, từ đó triển khai đồng bộ, toàn diện ACV 2045, cùng ASEAN bắt kịp các xu thế lớn và bứt lên trong kỷ nguyên phát triển mới của dân tộc.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác triển khai cần đảm bảo hai tiêu chí, một là không chỉ tập trung về lượng mà phải đi sâu về chất, hai là không chỉ là nhiệm vụ của riêng các cơ quan chủ trì các trụ cột hay chuyên ngành, mà là nhiệm vụ chung của hệ thống chính trị, nhằm đảm bảo tính gắn kết liên ngành trong nước và hiệu quả điều phối liên trụ cột trong ASEAN. Do đó, cũng cần chú trọng nâng cao nhận thức của các Bộ, ngành, địa phương về vai trò và trách nhiệm thực thi trong dài hạn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim- Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 5.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" h=\"1069\" id=\"img_907495201910915072\" loading=\"lazy\" photoid=\"907495201910915072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 5.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, các Bộ ngành cần chủ động có kế hoạch đưa các văn kiện đã hoặc sắp hoàn tất như ATIGA, ACFTA 3.0, DEFA vào thực thi, nhằm khai mở tiềm năng của các cam kết, thỏa thuận, mang lại lợi ích trực tiếp, thiết thân cho doanh nghiệp và người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Về nhiệm vụ cụ thể,&nbsp;</i>trước mắt, ta cần đóng góp tích cực vào xây dựng đoàn kết ASEAN, nhất là trong nỗ lực giải quyết vấn đề Myanmar, triển khai thỏa thuận hòa bình Campuchia và Thái Lan, góp phần duy trì môi trường hòa bình, ổn định trong khu vực, thuận lợi cho ASEAN, trong đó có Việt Nam, theo đuổi các mục tiêu dài hạn được vạch ra trong ACV 2045.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, cần chú trọng hỗ trợ Timor-Leste nâng cao năng lực, hội nhập ASEAN hiệu quả trên cả ba trụ cột. Là nước gia nhập trước và đạt nhiều thành tựu sau 30 năm tham gia ASEAN, Việt Nam có vị thế phù hợp để chia sẻ kinh nghiệm và hỗ trợ toàn diện Timor-Leste trong tiến trình này. Bộ Ngoại giao cũng đang xúc tiến sớm mở Đại sứ quán tại Timor-Leste, góp phần triển khai hiệu quả nhiệm vụ này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cuối cùng, cần khẩn trương triển khai các thỏa thuận, cam kết mà Việt Nam và các đối tác đã đạt được tại các cuộc gặp song phương trong khuôn khổ Hội nghị, trong đó có trao đổi đoàn, thúc đẩy hợp tác kinh tế - thương mại, an ninh lương thực, năng lượng, và đặc biệt là giải quyết dứt điểm các vấn đề tồn tại để gỡ thẻ vàng IUU của EU. Các bộ, ngành, địa phương, doanh nghiệp cần phối hợp chặt chẽ, tích cực và khẩn trương để bảo đảm triển khai đồng bộ, hiệu quả các kết quả đạt được với các đối tác./.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-va-cac-oi-tac-quan-trong-chu-chot-a-chot-uoc-nhieu-van-e-quan-trong-29281340', '', 'chinhphu.vn', 15, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.796224', 9, 11);
INSERT INTO `sync_articles` VALUES (153, '29282427', 'Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN...', 'Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg', '<p>Chiều 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính cùng Lãnh đạo các nước ASEAN tham dự Lễ bế mạc Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị Cấp cao liên quan, Lễ chuyển giao cương vị Chủ tịch ASEAN từ Malaysia sang Philippines. Đoàn Việt Nam đã tham gia gần 20...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" target=\"_blank\" title=\"Thủ tướng Malaysia Anwar Ibrahim phát biểu bế mạc Hội nghị- Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" h=\"1069\" id=\"img_907558372477698048\" loading=\"lazy\" photoid=\"907558372477698048\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Malaysia Anwar Ibrahim phát biểu bế mạc Hội nghị- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau ba ngày làm việc khẩn trương với hơn 20 hoạt động, Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan đã thành công tốt đẹp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu bế mạc Hội nghị, Thủ tướng Malaysia Anwar Ibrahim cảm ơn tất cả nước thành viên và các đối tác về những đóng góp thực chất và những nỗ lực bền bỉ góp phần làm nên thành công của Hội nghị, một sự kiện \"được dẫn dắt bởi lòng kiên trì và lý trí sáng suốt trong một thời khắc đầy biến động\", một kết quả tiêu biểu cho \"phương cách ASEAN.\"</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những kết quả quan trọng đạt được sẽ tiếp thêm sức sống cho tiến trình liên kết khu vực, gia tăng sức mạnh tổng hợp và vị thế của Cộng đồng ASEAN \"bao trùm và bền vững\" theo đúng chủ đề của năm 2025, giúp ASEAN sẵn sàng vững bước trên chặng đường phát triển mới với 11 thành viên.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả của các Hội nghị giữa ASEAN và các nước Đối tác cũng khẳng định vị thế, vai trò trung tâm của ASEAN và giúp tiếp tục củng cố và mở rộng quan hệ đối ngoại của ASEAN vì hòa bình, ổn định và phát triển.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" target=\"_blank\" title=\"Tổng thống Philippines Ferdinand Marcos Jr. tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" h=\"1069\" id=\"img_907558372409155584\" loading=\"lazy\" photoid=\"907558372409155584\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng thống Philippines Ferdinand Marcos Jr. tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia, Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là \"Cùng chèo lái tới tương lai\" (Navigating our future together) với ba ưu tiên lớn là củng cố hòa bình và an ninh, tăng cường các hành lang thịnh vượng, và thúc đẩy trao quyền cho người dân.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" target=\"_blank\" title=\"Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là &quot;Cùng chèo lái tới tương lai&quot; - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" h=\"1069\" id=\"img_907558372600045568\" loading=\"lazy\" photoid=\"907558372600045568\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 3.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là \"Cùng chèo lái tới tương lai\" - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Việt Nam do Thủ tướng Chính phủ Phạm Minh Chính dẫn đầu đã tham gia tích cực, đóng góp hiệu quả vào gần 20 hoạt động đa phương trong khuôn khổ Hội nghị, chia sẻ nhiều định hướng quan trọng định hình tương lai của ASEAN. Quan hệ hữu nghị và hợp tác thực chất giữa Việt Nam với các đối tác cũng được thúc đẩy thực chất thông qua hơn 20 cuộc tiếp xúc song phương.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" target=\"_blank\" title=\"Chương trình văn nghệ tại Lễ bế mạc - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" h=\"1069\" id=\"img_907558372543447040\" loading=\"lazy\" photoid=\"907558372543447040\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 4.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình văn nghệ tại Lễ bế mạc - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đóng góp, đề xuất và sáng kiến của Việt Nam tập trung thúc đẩy xây dựng Cộng đồng ASEAN đoàn kết, tự cường, bao trùm và bền vững, lấy người dân làm trung tâm, gắn kết phát triển quốc gia với phát triển khu vực. Qua đó, Việt Nam tiếp tục thể hiện vai trò thành viên chủ động, tích cực và có trách nhiệm, đóng góp thiết thực vào củng cố đoàn kết nội khối, nâng cao vai trò trung tâm của ASEAN, vì hòa bình, ổn định, hợp tác và phát triển trong khu vực.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 7.\" data-author=\"\" data-mobile-url=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" h=\"1653\" id=\"img_907606293057970176\" loading=\"lazy\" photoid=\"907606293057970176\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" style=\"width: 700px; height: 578px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 7.\" type=\"photo\" w=\"2000\" /></a></p>\n\n<figure allow-zoom=\"true\" type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tối 28/10, Thủ tướng Chính phủ Phạm Minh Chính và Đoàn Việt Nam đã rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan từ ngày 25 đến ngày 28/10/2025 theo lời mời của Thủ tướng Malaysia Anwar Ibrahim, Chủ tịch ASEAN 2025.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-hoan-thanh-hon-40-hoat-ong-trong-chuyen-cong-tac-du-hoi-nghi-cap-cao-asean-47-29282427', '', 'chinhphu.vn', 11, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.840008', 9, 11);
INSERT INTO `sync_articles` VALUES (154, '29283201', 'Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal', 'Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã gặp Thủ tướng Malaysia Anwar Ibrahim nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" h=\"1069\" id=\"img_907495201721221120\" loading=\"lazy\" photoid=\"907495201721221120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo đánh giá cao những nỗ lực của các bộ, ngành hai nước trong khẩn trương triển khai các lĩnh vực hợp tác, góp phần đưa quan hệ Đối tác Chiến lược toàn diện Việt Nam – Malaysia ngày càng đi vào chiều sâu và thực chất và xác định hợp tác kinh tế vẫn là trụ cột quan trọng trong quan hệ hai nước thời gian tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vui mừng gặp lại Thủ tướng Anwar Ibrahim sau chuyến thăm chính thức Malaysia nhân dịp dự Hội nghị cấp cao ASEAN lần thứ 46 (5/2025), Thủ tướng Chính phủ Phạm Minh Chính đánh giá cao các bước tiến lớn trong hợp tác kinh tế hai nước thời gian qua, theo đó kim ngạch thương mại hai chiều tính tới tháng 9/2025 đã đạt hơn 12 tỷ USD, tăng 12,9% so với cùng kỳ năm trước.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" h=\"1069\" id=\"img_907495201910915072\" loading=\"lazy\" photoid=\"907495201910915072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Anwar Ibrahim ủng hộ đề xuất của Thủ tướng Chính phủ Phạm Minh Chính về việc hai bên sớm ký văn kiện hợp tác trong lĩnh vực phát triển công nghiệp Halal và khẳng định Malaysia sẵn sàng hỗ trợ Việt Nam tổ chức các hoạt động xúc tiến quảng bá hàng nông sản để tăng độ nhận diện tại thị trường Malaysia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương ký tháng 12/2023.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" h=\"1069\" id=\"img_907495201830985728\" loading=\"lazy\" photoid=\"907495201830985728\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" style=\"width: 700px; height: 450px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 3.\" type=\"photo\" w=\"1660\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không; thúc đẩy mở rộng hợp tác trong các lĩnh vực kinh tế số, kinh tế xanh, khoa học công nghệ, đổi mới sáng tạo, nông nghiệp thông minh, chính phủ điện tử, an ninh mạng, đào tạo nhân lực AI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Anwar Ibrahim nhất trí hai nước thiết lập cơ chế tham vấn và quản lý về biển, phối hợp với các nước ASEAN triển khai hợp tác thiết thực về biển và đại dương, hợp tác ngư nghiệp và hoan nghênh nỗ lực của Việt Nam trong công tác phòng chống khai thác hải sản trái phép, không báo cáo và không theo quy định (IUU), nhất trí sẽ phối hợp chặt chẽ, hướng tới gỡ \"thẻ vàng\" của EU.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Malaysia tổ chức Hội nghị cấp cao ASEAN 47 thành công về mọi mặt, phát huy vai trò trung tâm của ASEAN trong giải quyết các vấn đề khu vực và giữ vững đoàn kết nội khối, góp phần vào hòa bình, an ninh và phát triển khu vực.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-malaysia-ung-ho-som-ky-van-kien-hop-tac-voi-viet-nam-ve-halal-29283201', '', 'chinhphu.vn', 15, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.881768', 9, 11);
INSERT INTO `sync_articles` VALUES (155, '29283811', 'Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam', 'Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah- Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" h=\"1337\" id=\"img_907570557481766912\" loading=\"lazy\" photoid=\"907570557481766912\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" style=\"width: 700px; height: 495px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 1.\" type=\"photo\" w=\"1888\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính trân trọng chuyển lời thăm hỏi của Tổng Bí thư Tô Lâm, Chủ tịch nước Lương Cường, Chủ tịch Quốc hội Trần Thanh Mẫn tới Quốc vương Brunei.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ khẳng định các bộ, ngành hữu quan của Việt Nam sẽ tích cực phối hợp với phía Brunei để chuẩn bị mọi mặt cho chuyến thăm Việt Nam của Quốc vương và Hoàng hậu trong thời gian tới, đạt những kết quả tốt đẹp, thực chất.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" h=\"1360\" id=\"img_907570557674160128\" loading=\"lazy\" photoid=\"907570557674160128\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" style=\"width: 700px; height: 505px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 2.\" type=\"photo\" w=\"1888\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quốc vương Brunei vui mừng nhận thấy quan hệ giữa Việt Nam và Brunei Darussalam tiếp tục phát triển tốt đẹp. Đánh giá tiềm năng thúc đẩy hợp tác trong thời gian tới, Quốc vương Brunei cho rằng hai nước còn nhiều dư địa, tiềm năng cần khai thác, phát huy tốt hơn nữa như dầu khí, thủy hải sản, du lịch, đặc biệt là liên doanh chế biến thực phẩm Halal tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về định hướng hợp tác song phương, Thủ tướng Chính phủ Phạm Minh Chính nhấn mạnh hai nền kinh tế có tính bổ sung cao, đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi; cấp thêm giấy phép cho các tàu cá, ngư dân Việt Nam được đánh bắt thủy, hải sản tại vùng biển Brunei; đồng thời hỗ trợ Việt Nam cấp chứng chỉ, sản xuất thực phẩm Halal và tận dụng lợi thế nguyên liệu phong phú, dồi dào của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" target=\"_blank\" title=\"Hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027 - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" h=\"1207\" id=\"img_907570557617250304\" loading=\"lazy\" photoid=\"907570557617250304\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" style=\"width: 700px; height: 448px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 3.\" type=\"photo\" w=\"1888\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027 - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027, tăng cường tiếp xúc, trao đổi ở các cấp và thúc đẩy giao lưu nhân dân, góp phần tạo đà và làm sâu sắc hơn quan hệ song phương trong thời gian tới.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-e-nghi-brunei-cap-them-giay-phep-anh-bat-cho-cac-tau-ca-viet-nam-29283811', '', 'chinhphu.vn', 15, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.917397', 9, 11);
INSERT INTO `sync_articles` VALUES (156, '29283991', 'Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN', 'Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã gặp Thủ tướng Timor-Leste Xanana Gusmão nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Timor-Leste Xanana Gusmão - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" h=\"1069\" id=\"img_907561952438267904\" loading=\"lazy\" photoid=\"907561952438267904\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Timor-Leste Xanana Gusmão - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN, đánh dấu bước ngoặt lịch sử trong tiến trình hội nhập của nước này, cũng là dấu mốc lịch sử trong tiến trình phát triển của ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ khẳng định Việt Nam sẽ tiếp tục đồng hành, sẵn sàng hỗ trợ, chia sẻ kinh nghiệm để Timor-Leste tham gia một cách hiệu quả và đóng góp tích cực vào Cộng đồng ASEAN.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" h=\"1069\" id=\"img_907561952496517120\" loading=\"lazy\" photoid=\"907561952496517120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng hai nước đánh giá quan hệ hữu nghị, hợp tác giữa Việt Nam và Timor-Leste thời gian qua tiếp tục phát triển tích cực, đặc biệt trong các lĩnh vực kinh tế - thương mại, nông nghiệp, viễn thông và giáo dục.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai bên nhất trí tăng cường trao đổi đoàn các cấp, thúc đẩy triển khai hiệu quả các thỏa thuận hợp tác đã ký kết; mở rộng hợp tác trong các lĩnh vực tiềm năng như kinh tế xanh, kinh tế số, năng lượng sạch, đổi mới sáng tạo, trí tuệ thông minh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới, thúc đẩy các chuyến thăm cấp cao và các cấp, sớm tổ chức cuộc họp đầu tiên của Uỷ ban hỗn hợp Việt Nam - Timor-Leste cấp Bộ trưởng Ngoại giao, triển khai hiệu quả các thỏa thuận đã ký kết; khai thác các tiềm năng hợp tác kinh tế, đặc biệt là thương mại đầu tư, và tạo điều kiện thuận lệ, cho doanh nghiệp hai nước kinh doanh, hoạt động tại thị trường của nhau.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" target=\"_blank\" title=\"Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" h=\"1069\" id=\"img_907561952610476032\" loading=\"lazy\" photoid=\"907561952610476032\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 3.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai bên cùng nhất trí đẩy mạnh hợp tác văn hóa, du lịch, giáo dục, đóng góp tích cực vào việc triển khai giao lưu nhân dân và thúc đẩy quan hệ hữu nghị và hợp tác nhiều mặt giữa hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trao đổi về các vấn đề quốc tế và khu vực, hai bên nhất trí tiếp tục phối hợp chặt chẽ và ủng hộ lẫn nhau tại các diễn đàn đa phương. Thủ tướng Chính phủ Phạm Mình Chính nhấn mạnh Việt Nam cam kết tiếp tục hỗ trợ Timor-Leste tham gia hiệu quả vào các hoạt động của ASEAN; mong Timor-Leste, với tư cách là một quốc gia thành viên UNCLOS 1982 và là một thành viên thứ 11 của ASEAN, tiếp tục ủng hộ lập trường chung của ASEAN về vấn đề Biển Đông và cùng nỗ lực đạt được một COC thực sự hiệu lực, thực chất, phù hợp với luật pháp quốc tế, nhất là UNCLOS 1982, góp phần xây dựng Biển Đông thành vùng biển hòa bình. ổn định, hợp tác và phát triển.</span></span></span></p>', '2025-11-07 06:26:00.000000', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-san-sang-ho-tro-timor-leste-tham-gia-hieu-qua-vao-cong-ong-asean-29283991', '', 'chinhphu.vn', 17, 'Tin quốc tế', 9, '', '38762', '{}', '2025-11-01 07:12:51.966618', 9, 11);
INSERT INTO `sync_articles` VALUES (289, '81007801', 'Hội nghị toàn quốc tổng kết công tác Tổ chức xây dựng Đảng năm 2025', 'Hội nghị toàn quốc tổng kết công tác Tổ chức xây dựng Đảng năm 2025', '/documents/37632/54780701/8-2.png/1b3f1140-85e7-63b3-71ac-e2c2e947fb63?t=1765175688950', '<p>(BNP) - Sáng 8/12, tại Hà Nội, Ban Tổ chức Trung ương tổ chức hội nghị toàn quốc tổng kết công tác tổ chức xây dựng Đảng năm 2025; nhiệm vụ trọng tâm năm 2026. Đồng chí Trần Cẩm Tú, Ủy viên Bộ Chính trị, Thường trực Ban Bí thư dự và chỉ đạo hội nghị.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/54780701/8-2.png/1b3f1140-85e7-63b3-71ac-e2c2e947fb63?t=1765175688950\" style=\"height: 605px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Lê Minh Hưng, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Trưởng ban Tổ chức Trung ương và các Phó Trưởng ban Tổ chức Trung ương chủ trì hội nghị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hội nghị được tổ chức trực tiếp kết hợp trực tuyến tới 40 điểm cầu Tỉnh ủy, Đảng ủy trực thuộc Trung ương và hơn 2.800 điểm cầu Đảng ủy cấp xã trong cả nước. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự và chủ trì hội nghị tại điểm cầu tỉnh Bắc Ninh có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Vũ Minh Hiếu, Ủy viên Ban Thường vụ Tỉnh ủy, Trưởng Ban Tổ chức Tỉnh ủy; lãnh đạo các Đảng ủy trực thuộc và các điểm cầu xã, phường trong toàn tỉnh. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/54780701/8-3.png/60bdae9c-1290-9605-8edb-af88d2d7bc50?t=1765176042450\" style=\"height: 585px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo Ban Tổ chức Tỉnh ủy dự hội nghị tại điểm cầu tỉnh Bắc Ninh.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Năm 2025, toàn ngành Tổ chức xây dựng Đảng đã bám sát Nghị quyết Đại hội XIII của Đảng, các nghị quyết của Trung ương, cấp ủy các cấp để triển khai thực hiện nhiệm vụ với quyết tâm chính trị cao nhất, hoàn thành tốt một khối lượng công việc lớn, nhiều việc mới, đột xuất, phức tạp. Trong đó, trọng tâm là tham mưu triển khai quyết liệt việc sắp xếp, tinh gọn tổ chức bộ máy một cách tổng thể, triệt để, sâu rộng và đồng bộ trong cả nước với quy mô lớn nhất trong lịch sử hiện đại, góp phần kiến tạo mô hình phát triển mới mang tính chiến lược, dài hạn. Tính đến nay, cả nước giảm hơn 50.000 tổ chức từ Trung ương đến địa phương và hơn 46.000 cán bộ, công chức, viên chức, lao động; nhiều đầu mối bên trong được tinh gọn, hoạt động hiệu lực, hiệu quả…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, phối hợp tham mưu chỉ đạo tổ chức thành công Đại hội Đảng bộ các cấp, nhiệm kỳ 2025 - 2030, góp phần quan trọng vào công tác chuẩn bị Đại hội toàn quốc lần thứ XIV của Đảng. Tham mưu ban hành phương hướng công tác nhân sự Đại hội toàn quốc lần thứ XIV của Đảng; quy hoạch Ban Chấp hành Trung ương, Bộ Chính trị, Ban Bí thư khóa XIV. Việc tham mưu, giới thiệu nhân sự được thực hiện kỹ lưỡng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Công tác cán bộ có nhiều đổi mới, góp phần xây dựng đội ngũ cán bộ các cấp từng bước trưởng thành, đáp ứng yêu cầu nhiệm vụ. Kịp thời kiện toàn, bổ sung lãnh đạo chủ chốt các cơ quan, địa phương, đơn vị và cấp cao của Đảng. Đặc biệt, lần đầu tiên, bố trí 100% Bí thư Tỉnh ủy, Chủ tịch UBND các tỉnh, thành phố không phải là người địa phương. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Việc củng cố, xây dựng tổ chức cơ sở Đảng và nâng cao chất lượng đảng viên ngày càng đi vào chiều sâu và có nhiều chuyển biến tích cực. Tích cực sắp xếp tổ chức bộ máy, tinh giản biên chế, cơ cấu lại đội ngũ cán bộ ngành Tổ chức xây dựng Đảng sau sáp nhập, hợp nhất.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/54780701/8-4.png/3d45c434-d540-8dbe-e69a-0ed78ba78c30?t=1765176192785\" style=\"height: 629px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Lãnh đạo các Đảng ủy trực thuộc Tỉnh ủy dự hội nghị tại điểm cầu Bắc Ninh.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham luận tại hội nghị, các bộ, ngành, địa phương tập trung đánh giá kết quả đạt được, phân tích những tồn tại, khó khăn, hạn chế. Từ đó, đề xuất, kiến nghị một số nội dung liên quan đến đẩy mạnh phân cấp, phân quyền gắn với nguồn lực cho địa phương thực hiện; ưu tiên nguồn lực đầu tư hạ tầng số đến tận cấp xã; tiếp tục hoàn thiện các nền tảng, phần mềm dùng chung để phát huy hiệu quả công tác chuyển đổi số trong Đảng…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phát biểu chỉ đạo hội nghị, Thường trực Ban Bí thư Trần Cẩm Tú ghi nhận và biểu dương các kết quả ngành Tổ chức Xây dựng Đảng đạt được trong năm 2025. Đồng thời, thẳng thắn chỉ rõ những hạn chế còn tồn tại. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trong thời gian tới, Thường trực Ban Bí thư đề nghị ngành Tổ chức xây dựng Đảng tập trung tham mưu chuẩn bị nội dung về nhân sự, các điều kiện cần thiết để tổ chức thành công Đại hội XIV của Đảng; phối hợp để chuẩn bị bầu cử đại biểu Quốc hội khóa XVI và HĐND các cấp nhiệm kỳ 2026 - 2031. Hoàn thiện, triển khai hiệu quả mô hình tổ chức bộ máy mới. Trong đó, khẩn trương tham mưu rà soát, bổ sung, hoàn thiện các thể chế, chức năng, nhiệm vụ của các cơ quan, đơn vị, tổ chức trong hệ thống chính trị. Triển khai có hiệu quả cơ chế phân cấp, phân quyền từ Trung ương đến địa phương, gắn với nâng cao năng lực tự chủ, tự quyết và tự chịu trách nhiệm của địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, tiếp tục tham mưu sắp xếp tổ chức bộ máy; trọng tâm là rà soát, sắp xếp, tinh gọn các tổ chức bên trong của các cơ quan, đơn vị trong hệ thống chính trị, đảm bảo hoạt động, hiệu năng, hiệu lực, hiệu quả, thông suốt, đáp ứng yêu cầu phát triển của đất nước trong giai đoạn mới. Quan tâm phát hiện, đào tạo, bồi dưỡng và trọng dụng nhân tài; tăng cường cán bộ cho địa bàn khó khăn, những lĩnh vực trọng yếu. Tăng cường công tác kiểm soát quyền lực, kiên quyết khắc phục những bất cập trong công tác cán bộ. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhân dịp này, Ban Tổ chức Tỉnh ủy Bắc Ninh và 4 tập thể được nhận Cờ thi đua của ngành Tổ chức Xây dựng Đảng; nhiều tập thể, cá nhân được nhận Cờ thi đua và Bằng khen của Ban Tổ chức Trung ương. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/54780701/8-1.png/b1047899-2002-5aa0-dc9b-f58e412e9798?t=1765175858548\" style=\"width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái kết luận hội nghị tại điểm cầu Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngay sau hội nghị, kết luận tại điểm cầu tỉnh Bắc Ninh, Bí thư Tỉnh ủy Nguyễn Hồng Thái đề nghị các cấp ủy, tổ chức Đảng trong toàn tỉnh nghiêm túc tiếp thu các ý kiến chỉ đạo tại hội nghị. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bày tỏ chia sẻ với những khó khăn, vướng mắc khi thực hiện mô hình chính quyền địa phương 02 cấp, Bí thư Tỉnh ủy đề nghị các cấp ủy, chính quyền cơ sở trong tỉnh tiếp tục đồng lòng, chung sức triển khai thực hiện tốt các nhiệm vụ đề ra. Trong đó, trọng tâm là định hướng tốt dư luận xã hội; tránh gây hoang mang, mất đoàn kết trong nội bộ. Đồng thời, chú trọng tuyên truyền, giải quyết kiến nghị của người dân ở cơ sở; những vấn đề vượt thẩm quyền báo cáo lãnh đạo tỉnh để cùng bàn và có giải pháp tháo gỡ, tránh tồn đọng những vấn đề phức tạp kéo dài./.</span></span></span></p>', '2025-12-08 06:34:00', 'https://bacninh.gov.vn/news/-/details/37632/hoi-nghi-toan-quoc-tong-ket-cong-tac-to-chuc-xay-dung-ang-nam-2025-81007801', '', 'Linh Ngọc', 114, 'Chính trị', 2, 'true', '38762', '{}', '2025-12-08 08:18:04.661996', 2, 11);
INSERT INTO `sync_articles` VALUES (290, '81006301', 'Hiệp thương thống nhất cơ cấu, thành phần, số lượng người ứng cử đại biểu Quốc hội...', 'Hiệp thương thống nhất cơ cấu, thành phần, số lượng người ứng cử đại biểu Quốc hội khóa XVI và đại biểu HĐND tỉnh khóa XX, nhiệm kỳ 2026 - 2031', '/documents/37632/30456144/IMG_1777.jpg/d550dc3b-e8f7-5522-1a27-0e6b0d0fe683?t=1765175190701', '<p>(BNP) - Sáng 8/12, tại Trung tâm Hội nghị tỉnh, Ủy ban MTTQ tỉnh Bắc Ninh tổ chức Hội nghị hiệp thương lần thứ nhất, thảo luận, thống nhất cơ cấu, thành phần, số lượng người ứng cử đại biểu Quốc hội khóa XVI và đại biểu HĐND tỉnh khóa XX, nhiệm kỳ 2026 - 2031.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/30456144/IMG_1777.jpg/d550dc3b-e8f7-5522-1a27-0e6b0d0fe683?t=1765175190701\" style=\"height: 600px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Toàn cảnh hội nghị.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự hội nghị có các đồng chí: Trần Huy Phương, Phó Bí Thư Tỉnh ủy, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy; Trần Thị Hằng, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực HĐND tỉnh; Nguyễn Thị Hà, Ủy viên Ban Thường vụ Tỉnh ủy, Chủ tịch Ủy ban MTTQ tỉnh; Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh; Trần &nbsp;Văn Tuấn, Phó Trưởng Đoàn đại biểu Quốc hội tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại hội nghị, các đại biểu đã tiến hành hiệp thương thỏa thuận bằng hình thức biểu quyết với 100% đại biểu có mặt tại hội nghị thống nhất: Tổng số <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">đại biểu Quốc hội</span></span></span> được bầu là 16 đại biểu; số lượng Ban Thường trực Ủy ban MTTQ tỉnh dự kiến giới thiệu là 34 đại biểu để bầu.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/mt1.png/33acbbc8-a84d-c681-8106-c57e6ba960de?t=1765175305602\" style=\"height: 558px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đồng chí lãnh đạo tỉnh dự hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về cơ cấu, dự kiến có 7 đại biểu Trung ương; 1 đại biểu lãnh đạo chủ chốt của tỉnh; 4 đại biểu chuyên trách; 5 đại biểu khối Đảng - chính quyền; 4 đại biểu Đoàn TNCS Hồ Chí Minh; 2 đại biểu doanh nghiệp, ngành nghề; 5 đại biểu lĩnh vực tài chính; 3 đại biểu khối văn hóa - văn nghệ và 3 đại biểu khối khoa học - công nghệ.</span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cơ cấu kết hợp bảo đảm tỷ lệ nữ 29,41%, đại biểu dân tộc thiểu số 11,76%, ngoài Đảng 2,94%, đại biểu trẻ tuổi 8,82% và đại biểu tái cử 20,58%.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/mt3.png/93c145dc-843d-3e54-d9d6-9840230ffa2c?t=1765175373555\" style=\"height: 605px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng thông tin, quán triệt các Nghị quyết của Ủy ban Thường vụ Quốc hội liên quan đến phân bổ số lượng và cơ cấu đại biểu Quốc hội khóa XVI.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội nghị cũng thống nhất cơ cấu, thành phần, số lượng đại biểu HĐND tỉnh khóa XX, nhiệm kỳ 2026 - 2031 gồm 85 đại biểu. Ban Thường trực Ủy ban MTTQ tỉnh dự kiến giới thiệu 155 người ứng cử để lập danh sách sơ bộ, bảo đảm phân bổ hợp lý giữa các khối: Đảng 25,16%; chính quyền và đơn vị sự nghiệp 40,6%; MTTQ và các tổ chức chính trị - xã hội 24,5%; lực lượng vũ trang và cơ quan tư pháp 5,08%; doanh nghiệp và tôn giáo 3,87%...</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cơ cấu kết hợp được chú trọng với tỷ lệ đại biểu nữ 38,06%, đại biểu dân tộc thiểu số 9,7%, ngoài Đảng 11,6%; trẻ tuổi 17,4%, có tôn giáo 3,2% và bảo đảm ít nhất 30% đại biểu tái cử.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/mt4.png/4d251a6f-1f2b-e6b6-58e3-72c69435d436?t=1765175422044\" style=\"height: 586px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Ủy ban MTTQ tỉnh Nguyễn Thị Hà phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND tỉnh khóa XIX nhiệm kỳ 2026-2031 là sự kiện chính trị quan trọng của đất nước nhằm lựa chọn, bầu ra những đại biểu tiêu biểu, xứng đáng đại diện cho ý chí, nguyện vọng và quyền làm chủ của Nhân dân trong Quốc hội và HĐND các cấp nhiệm kỳ mới, góp phần tích cực vào việc xây dựng, củng cố và hoàn thiện Nhà nước pháp quyền xã hội chủ nghĩa của Nhân dân, do Nhân dân, vì Nhân dân dưới sự lãnh đạo của Đảng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/mt7.png/fc91658f-1344-d1e1-ecd5-ba5bcb4298b1?t=1765175463472\" style=\"height: 593px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu biểu quyết thông qua nội dung hiệp thương tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc tổ chức thành công Hội nghị hiệp thương lần thứ Nhất có vai trò đặc biệt quan trọng, là bước khởi đầu mang tính tiền đề để dự kiến đưa ra cơ cấu, thành phần, số lượng người được giới thiệu ứng cử đại biểu Quốc hội khóa XVI và đại biểu HĐND tỉnh khóa XIX, nhiệm kỳ 2026-2031 của tổ chức chính trị, Ủy ban MTTQ Việt Nam, tổ chức chính trị - xã hội, tổ chức xã hội, đơn vị vũ trang Nhân dân, cơ quan Nhà nước cùng cấp tỉnh và của đơn vị sự nghiệp, tổ chức kinh tế, các đơn vị hành chính cấp xã. Đây là cơ sở quan trọng để các bước tiếp theo của quy trình hiệp thương được triển khai thuận lợi, chặt chẽ, bảo đảm tính đại diện, khách quan, đúng pháp luật của quy trình hiệp thương, giới thiệu người ứng cử./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-12-08 06:23:00', 'https://bacninh.gov.vn/news/-/details/37632/hiep-thuong-thong-nhat-co-cau-thanh-phan-so-luong-nguoi-ung-cu-ai-bieu-quoc-hoi-khoa-xvi-va-ai-bieu-h-nd-tinh-khoa-xx-nhiem-ky-2026-2031-81006301', '', 'Nguyễn Nhàn', 121, 'Chính trị', 2, 'true', '38762', '{}', '2025-12-08 08:18:04.691352', 2, 11);
INSERT INTO `sync_articles` VALUES (291, '80976405', 'Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn: Cần quy định rõ về...', 'Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn: Cần quy định rõ về thời hạn tạm đình chỉ giải quyết khiếu nại', '/documents/37632/54780701/a11.jpg/3ce46f49-32e4-8767-85b6-c0bbf64c4cae?t=1765156945671', '<p>(BNP) - Đó là ý kiến của Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn trong phiên thảo luận tại hội trường Quốc hội, chiều 5/12.&nbsp;</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a11.jpg/3ce46f49-32e4-8767-85b6-c0bbf64c4cae?t=1765156945671\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn phát biểu trong phiên thảo luận tại hội trường Quốc hội, chiều 5/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, chiều 5/12 các đại biểu Quốc hội thảo luận tại hội trường, cho ý kiến vào dự án Luật sửa đổi, bổ sung một số điều của 3 luật: Luật Tiếp công dân, Luật Khiếu nại và Luật Tố cáo.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn cho biết: Tại khoản 4, Điều 2 của dự thảo Luật đã bổ sung Điều 11a vào sau Điều 11 của Luật Khiếu nại năm 2011 quy định về: “Tạm đình chỉ, đình chỉ giải quyết khiếu nại”. Theo đó, có trường hợp tạm đình chỉ giải quyết khiếu nại: “Do sự kiện bất khả kháng hoặc trở ngại khách quan” (được quy định tại điểm a).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đề nghị cơ quan soạn thảo nghiên cứu, bổ sung quy định cụ thể ngay trong Luật này hoặc giao cho Chính phủ quy định cụ thể các trường hợp tạm đình chỉ giải quyết khiếu nại do “sự kiện bất khả kháng hoặc trở ngại khách quan” là như thế nào? Đồng thời cần bổ sung quy định cụ thể về thời hạn tạm đình chỉ tối đa.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Qua nghiên cứu cho thấy, theo quy định tại Điều 156 của Bộ luật Dân sự năm 2015 thì “Sự kiện bất khả kháng là sự kiện xảy ra một cách khách quan, không thể lường trước được và không thể khắc phục được, mặc dù đã áp dụng mọi biện pháp cần thiết và khả năng cho phép” và “Trở ngại khách quan là trở ngại do hoàn cảnh khách quan tác động làm cho người có quyền, nghĩa vụ dân sự không thể biết về việc quyền, lợi ích hợp pháp của mình bị xâm phạm, hoặc không thể thực hiện được quyền, nghĩa vụ dân sự của mình”. Đây là quy định chung, trên cơ sở đó các luật chuyên ngành tiếp tục quy định về trường hợp bất khả kháng cho phù hợp với phạm vi, đối tượng điều chỉnh của luật, hoặc viện dẫn đến quy định của Bộ luật Dân sự.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, trong Luật này cũng cần quy định rõ thế nào là “sự kiện bất khả kháng hay trở ngại khách quan” trong giải quyết khiếu nại; đồng thời cần bổ sung quy định cụ thể về thời hạn tạm đình chỉ tối đa nhằm tránh việc lạm dụng tạm đình chỉ giải quyết khiếu nại. (Nếu không quy định rõ có thể dẫn đến việc tạm đình chỉ giải quyết khiếu nại trong trường hợp mới chỉ là có một số khó&nbsp;khăn nhất định, chưa đến mức được xác định là trường hợp bất khả kháng hay trở ngại khách quan). Hậu quả của việc lạm dụng này là vụ việc khiếu nại không được giải quyết hoặc kéo dài, đùn đẩy, né tránh giải quyết, gây bất lợi, bức xúc cho công dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại khoản 7, Điều 2 của dự thảo Luật đã sửa đổi, bổ sung Điều 17 của Luật Khiếu nại năm 2011 về “Thẩm quyền của Chủ tịch UBND cấp xã,…” Theo đó, Chủ tịch UBND cấp xã có thẩm quyền giải quyết khiếu nại lần đầu đối với các quyết định hành chính do mình ban hành. Tuy nhiên, theo luật hiện hành cũng như trong dự thảo Luật này đều chưa quy định đầy đủ về thẩm quyền giải quyết khiếu nại đối với các quyết định hành chính do cơ quan, tổ chức ban hành, trong đó có UBND cấp mình. (Thực tế hiện nay dù không có quy định thì Chủ tịch UBND các cấp vẫn đang không chỉ giải quyết khiếu nại lần đầu đối với quyết định hành chính, hành vi hành chính của mình mà còn phải giải quyết khiếu nại lần đầu đối với quyết định hành chính của UBND cấp mình).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, để có đầy đủ cơ sở pháp lý trong thực hiện, đại biểu đề nghị sửa đổi, bổ sung Điều 17 về thẩm quyền của Chủ tịch UBND cấp xã trong giải quyết khiếu nại lần đầu như sau: “Chủ tịch UBND cấp xã có thẩm quyền giải quyết khiếu nại lần đầu đối với quyết định hành chính, hành vi hành chính của mình, của UBND cấp xã, của người đứng đầu cơ quan chuyên môn, tổ chức hành chính khác thuộc UBND cấp xã, của công chức, viên chức do mình quản lý trực tiếp”.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tương tự, đại biểu cũng đề nghị Ban Soạn thảo nghiên cứu sửa đổi khoản 1, Điều 21 của Luật Khiếu nại năm 2011, quy định về thẩm quyền của Chủ tịch UBND cấp tỉnh trong giải quyết khiếu nại lần đầu. Trong đó, cần quy định rõ Chủ tịch UBND cấp tỉnh có thẩm quyền “Giải quyết khiếu nại lần đầu đối với quyết định hành chính, hành vi hành chính của mình, của UBND cấp tỉnh”.</span></span></span></p>', '2025-12-08 01:21:00', 'https://bacninh.gov.vn/news/-/details/37632/pho-truong-oan-ai-bieu-quoc-hoi-tinh-bac-ninh-tran-van-tuan-can-quy-inh-ro-ve-thoi-han-tam-inh-chi-giai-quyet-khieu-nai-80976405', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 65, 'Chính trị', 2, 'true', '38762', '{}', '2025-12-08 08:18:04.717215', 2, 11);
INSERT INTO `sync_articles` VALUES (292, '80974203', 'Hôm nay (8/12), Quốc hội thảo luận về cơ chế đặc thù cho các dự án lớn tại Hà Nội, TP...', 'Hôm nay (8/12), Quốc hội thảo luận về cơ chế đặc thù cho các dự án lớn tại Hà Nội, TP Hồ Chí Minh, Đà Nẵng', '/documents/37632/54780701/z7291932134078_42fb3254938763bd7273d4ca959b6d6b.jpg/c686c4db-8904-a61a-13bd-47b880a44059?t=1765155953305', '<p>(BNP) - Theo chương trình Kỳ họp thứ 10, Quốc hội khóa XV, ngày 8/12, Quốc hội thảo luận về cơ chế, chính sách đặc thù để triển khai các dự án lớn tại địa bàn Thủ đô; dự thảo Nghị quyết về thí điểm một số cơ chế, chính sách đặc thù phát triển Thành phố Hồ Chí Minh và Đà Nẵng.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/z7291932134078_42fb3254938763bd7273d4ca959b6d6b.jpg/c686c4db-8904-a61a-13bd-47b880a44059?t=1765155953305\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh thảo luận tại tổ ngày 5/12.</span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong buổi sáng, Quốc hội nghe Bộ trưởng Bộ Xây dựng, thừa ủy quyền của Thủ tướng Chính phủ trình bày Tờ trình về việc điều chỉnh nội dung Nghị quyết số 94/2015/QH13 của Quốc hội về chủ trương đầu tư Cảng hàng không quốc tế Long Thành.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó, Bộ trưởng Bộ Tài chính, thừa ủy quyền của Thủ tướng Chính phủ trình bày Tờ trình về dự án Luật sửa đổi, bổ sung một số điều của Luật Thuế giá trị gia tăng; dự thảo Nghị quyết của Quốc hội về những cơ chế, chính sách đặc thù để triển khai các dự án lớn tại địa bàn Thủ đô; về bổ sung ngân sách nhà nước đợt 2 (nguồn vốn không hoàn lại nước ngoài) năm 2025; việc sửa đổi, bổ sung Nghị quyết số 170/2024/QH15 ngày 30/11/2024 của Quốc hội về cơ chế, chính sách đặc thù để tháo gỡ khó khăn, vướng mắc đối với các dự án, đất đai trong kết luận thanh tra, kiểm tra, bản án tại Thành phố Hồ Chí Minh, thành phố Đà Nẵng và tỉnh Khánh Hòa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Chủ nhiệm Ủy ban Kinh tế và Tài chính của Quốc hội trình bày Báo cáo thẩm tra về 5 nội dung: Dự án Luật sửa đổi, bổ sung một số điều của Luật Thuế giá trị gia tăng; dự thảo Nghị quyết của Quốc hội về những cơ chế, chính sách đặc thù để triển khai các dự án lớn tại địa bàn Thủ đô; việc điều chỉnh nội dung Nghị quyết số 94/2015/QH13 của Quốc hội về chủ trương đầu tư Cảng hàng không quốc tế Long Thành; về bổ sung ngân sách nhà nước đợt 2 (nguồn vốn không hoàn lại nước ngoài) năm 2025; việc sửa đổi, bổ sung Nghị quyết số 170/2024/QH15 ngày 30/11/2024 của Quốc hội về cơ chế, chính sách đặc thù để tháo gỡ khó khăn, vướng mắc đối với các dự án, đất đai trong kết luận thanh tra, kiểm tra, bản án tại Thành phố Hồ Chí Minh, thành phố Đà Nẵng và tỉnh Khánh Hòa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó, Quốc hội thảo luận ở hội trường về: Dự thảo Nghị quyết của Quốc hội về những cơ chế, chính sách đặc thù để triển khai các dự án lớn tại địa bàn Thủ đô. Dự thảo Nghị quyết của Quốc hội sửa đổi, bổ sung một số điều Nghị quyết số 98/2023/QH15 về thí điểm một số cơ chế, chính sách đặc thù phát triển Thành phố Hồ Chí Minh. Dự thảo Nghị quyết của Quốc hội sửa đổi, bổ sung một số điều Nghị quyết số 136/2024/QH15 về tổ chức chính quyền đô thị và thí điểm một số cơ chế, chính sách đặc thù phát triển thành phố Đà Nẵng. Về việc bổ sung ngân sách nhà nước đợt 2 (nguồn vốn không hoàn lại nước ngoài) năm 2025. Bộ trưởng Bộ Tài chính giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Quốc hội thảo luận ở tổ về dự án Luật sửa đổi, bổ sung một số điều của Luật Thuế giá trị gia tăng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi chiều, Quốc hội nghe Bộ trưởng Bộ Xây dựng, thừa ủy quyền của Thủ tướng Chính phủ trình bày Tờ trình về một số cơ chế, chính sách đặc thù, đặc biệt áp dụng cho dự án đường sắt tốc độ cao trên trục Bắc - Nam. Chủ nhiệm Ủy ban Kinh tế và Tài chính của Quốc hội trình bày Báo cáo thẩm tra về một số cơ chế, chính sách đặc thù, đặc biệt áp dụng cho dự án đường sắt tốc độ cao trên trục Bắc - Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Quốc hội thảo luận về dự thảo Nghị quyết của Quốc hội về cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026 - 2030. Bộ trưởng Bộ Công thương giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó, Quốc hội thảo luận về một số cơ chế, chính sách đặc thù, đặc biệt áp dụng cho dự án đường sắt tốc độ cao trên trục Bắc - Nam. Chủ trương đầu tư Dự án đầu tư xây dựng Cảng hàng không quốc tế Gia Bình. Chủ trương đầu tư Dự án đầu tư xây dựng đường bộ cao tốc Vinh - Thanh Thủy. Việc điều chỉnh nội dung Nghị quyết số 94/2015/QH13 của Quốc hội về chủ trương đầu tư Cảng hàng không quốc tế Long Thành. Việc sửa đổi, bổ sung Nghị quyết số 170/2024/QH15 ngày 30/11/2024 của Quốc hội về cơ chế, chính sách đặc thù để tháo gỡ khó khăn, vướng mắc đối với các dự án, đất đai trong kết luận thanh tra, kiểm tra, bản án tại Thành phố Hồ Chí Minh, thành phố Đà Nẵng và tỉnh Khánh Hòa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cuối phiên họp, Quốc hội nghe Bộ trưởng Bộ Xây dựng, Bộ trưởng Bộ Tài chính giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '2025-12-08 01:04:00', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-8-12-quoc-hoi-thao-luan-ve-co-che-ac-thu-cho-cac-du-an-lon-tai-ha-noi-tp-ho-chi-minh-a-nang-80974203', '', 'BNP', 29, 'Chính trị', 2, 'true', '38762', '{}', '2025-12-08 08:18:04.750552', 2, 11);
INSERT INTO `sync_articles` VALUES (293, '77139301', 'Thực hiện chương trình hành động Nghị quyết Đại hội Đảng bộ tỉnh Bắc Ninh khóa I,...', 'Thực hiện chương trình hành động Nghị quyết Đại hội Đảng bộ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025-2030', '/documents/37632/200616/1+%288%29.jpg/cf6f368c-b84e-8f19-4b9b-c28af4cd0642?t=1764925416467', '<p>(BNP) &nbsp;- Tại văn bản số 5495/UBND-THĐT, Chủ tịch UBND tỉnh chỉ đạo thực hiện Chương trình hành động Nghị quyết Đại hội Đảng bộ tỉnh Bắc Ninh và Chương trình công tác toàn khóa của Ban Chấp hành Đảng bộ tỉnh khóa I, nhiệm kỳ 2025-2030.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200616/1+%288%29.jpg/cf6f368c-b84e-8f19-4b9b-c28af4cd0642?t=1764925416467\" style=\"height: 562px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trung tâm phường Kinh Bắc, tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Chủ tịch UBND tỉnh yêu cầu các sở, ngành, cơ quan thuộc UBND tỉnh; UBND các xã, phường &nbsp;phổ biến, quán triệt nghiêm túc các nội dung tại Chương trình hành động của Ban Chấp hành Đảng bộ tỉnh thực hiện Nghị quyết Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025-2030.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham mưu UBND tỉnh xây dựng các chương trình, đề án, kế hoạch bám sát nội dung Chương trình hành động, chương trình công tác toàn khóa của Ban Chấp hành Đảng bộ tỉnh khóa I, nhiệm kỳ 2025-2030 để tổ chức triển khai, thực hiện.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giao Sở Nội vụ chủ trì, tham mưu ban hành Chương trình cải cách hành chính nhà nước tỉnh Bắc Ninh giai đoạn 2026 - 2030; Chương trình xây dựng tỉnh Bắc Ninh trở thành thành phố trực thuộc Trung ương trước năm 2030; Đề án thành lập thành phố Bắc Ninh trực thuộc Trung ương và thành lập các phường thuộc thành phố Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Xây dựng chủ trì, tham mưu ban hành Đồ án Quy hoạch chung đô thị Bắc Ninh đến năm 2050, tầm nhìn đến năm 2075; Chương trình phát triển đô thị Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Nông nghiệp và Môi trường chủ trì, tham mưu ban hành Chương trình Phát triển nông nghiệp, nông thôn; Đề án tổng thể bảo vệ môi trường tỉnh Bắc Ninh giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Khoa học và Công nghệ chủ trì, tham mưu ban hành Chương trình đột phá về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số; Sở Dân tộc và Tôn giáo tham mưu ban hành Chương trình phát triển vùng dân tộc thiểu số và miền núi.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Văn hóa, Thể thao và Du lịch chủ trì, tham mưu ban hành Nghị quyết về xây dựng và phát triển văn hóa, con người Bắc Ninh đến năm 2030, đáp ứng yêu cầu phát triển bền vững; Đề án tổng thể phát triển du lịch tỉnh Bắc Ninh giai đoạn 2026-2030; </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Giáo dục và Đào tạo tham mưu ban hành Chương trình hành động thực hiện Nghị quyết số 71-NQ/TW ngày 22/8/2025 của Bộ Chính trị về đột phá phát triển giáo dục và đào tạo; </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Y tế tham mưu ban hành Chương trình hành động thực hiện Nghị quyết số 72-NQ/TW ngày 09/9/2025 của Bộ Chính trị về một số giải pháp đột phá, tăng cường bảo vệ, chăm sóc và nâng cao sức khỏe Nhân dân.<span lang=\"VI\"></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giao Sở Tài chính chủ trì, phối hợp với các ngành, đơn vị liên quan <span lang=\"VI\">tham mưu UBND tỉnh cụ thể hóa nội dung Chương trình hành động thành nhiệm vụ trong Kế hoạch phát triển kinh tế - xã hội 5 năm và hằng năm; giao các cơ quan, đơn vị liên quan tổ chức thực hiện (trong đó xác định rõ nội dung, cơ quan chủ trì, cơ quan phối hợp, thời gian thực hiện hoàn thành)</span>.<span lang=\"VI\"></span></span></span></span></p>', '2025-12-08 00:30:00', 'https://bacninh.gov.vn/news/-/details/37632/thuc-hien-chuong-trinh-hanh-ong-nghi-quyet-ai-hoi-ang-bo-tinh-bac-ninh-khoa-i-nhiem-ky-2025-2030-77139301', '', 'Hữu Thắng', 29, 'Chính trị', 2, 'true', '38762', '{}', '2025-12-08 08:18:04.782128', 2, 11);
INSERT INTO `sync_articles` VALUES (294, '76474011', 'Hội nghị Ban Chấp hành Đảng bộ tỉnh thông qua dự thảo Báo cáo phát triển kinh tế - xã...', 'Hội nghị Ban Chấp hành Đảng bộ tỉnh thông qua dự thảo Báo cáo phát triển kinh tế - xã hội tỉnh năm 2025; thảo luận, xem xét một số dự thảo Nghị quyết, báo cáo quan trọng', '/documents/37632/54780701/1+%281%29.jpg/15c4e12e-39f9-89a4-f773-065bc153a902?t=1764918002089', '<p>(BNP) - Sáng 5/12, Ban Chấp hành Đảng bộ tỉnh khóa I tổ chức Hội nghị lần thứ hai về tình hình thực hiện nhiệm vụ phát triển kinh tế - xã hội (KT - XH) năm 2025; phương hướng, mục tiêu, nhiệm vụ và giải pháp thực hiện kế hoạch năm 2026. Đồng chí Nguyễn Hồng Thái, Ủy viên Ban Chấp hành Trung ương...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/1+%281%29.jpg/15c4e12e-39f9-89a4-f773-065bc153a902?t=1764918002089\" style=\"height: 517px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\">Quang cảnh&nbsp;hội nghị.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><b>Kinh tế - xã hội năm 2025 &nbsp;nhiều chỉ tiêu đạt và vượt, tạo bứt phá toàn diện năm 2026 </b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Dự thảo báo cáo về tình hình thực hiện nhiệm vụ phát triển KT -XH năm 2025; phương hướng, mục tiêu, nhiệm vụ và giải pháp thực hiện kế hoạch năm 2026 cho thấy, năm 2025, trong bối cảnh các địa phương triển khai thực hiện sáp nhập mô hình chính quyền địa phương 02 cấp và tiến hành Đại hội Đảng bộ các cấp, Đại hội Đảng bộ tỉnh lần thứ I, với tinh thần đoàn kết, chủ động, sáng tạo, bức tranh kinh tế tỉnh Bắc Ninh đạt được nhiều kết quả nổi bật; 10/18 chỉ tiêu KT- XH ước vượt kế hoạch, 07/18 chỉ tiêu ước đạt kế hoạch. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Quy mô kinh tế ước đạt 522.618 tỷ đồng, nằm trong nhóm 5 tỉnh, thành phố đứng đầu cả nước về quy mô kinh tế. Tốc độ tăng trưởng GRDP (theo giá hiện hành) ước đạt 10,27%, bám sát kế hoạch do Chính phủ giao và đứng thứ 5 cả nước về tốc độ tăng trưởng; GRDP bình quân đầu người đạt 5.852 USD/năm (vượt kế hoạch 5.500-5.700 USD/năm), gấp 1,16 lần bình quân cả nước. Tổng thu ngân sách nhà nước ước đạt 72.497 tỷ đồng, (vượt kế hoạch 56.834 tỷ đồng). Thu hút vốn FDI ước đạt 5,2 tỷ USD, (vượt kế hoạch 4,3 tỷ USD)….</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Nhiều công trình hạ tầng lớn được khởi công, nhất là dự án Cảng hàng không quốc tế Gia Bình cùng các tuyến giao thông kết nối, định hình không gian phát triển mới. Công tác thu hút đầu tư có đột phá, tổng vốn đầu tư trong nước và FDI ước đạt 17,6 tỷ USD; cơ chế luồng xanh 24 giờ và luồng xanh 60%&nbsp; được tỉnh triển khai quyết liệt, nhằm rút ngắn thời gian xử lý thủ tục hành chính cho người dân doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Bên cạnh đó, tỉnh luôn tập trung chú trọng phát triển kinh tế gắn liền với đảm bảo an sinh xã hội, nâng cao đời sống vật chất và tinh thần của người dân. Chương trình xoá nhà tạm, nhà dột nát, xây dựng nhà ở xã hội năm 2025 cơ bản hoàn thành theo kế hoạch, giúp người dân an cư lập nghiệp. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tỷ lệ hộ nghèo theo chuẩn đa chiều chỉ còn 0,56%. Chất lượng giáo dục mũi nhọn tiếp tục khẳng định vị thế tốp đầu cả nước; tỷ lệ người dân có thẻ Bảo hiểm y tế đạt 95,38%; công tác bảo tồn và phát huy giá trị văn hóa lịch sử được triển khai hiệu quả, trong năm toàn tỉnh thu hút 6,3 triệu lượt khách du lịch; công tác quốc phòng, an ninh được tăng cường củng cố, góp phần thúc đẩy phát triển KT- XH của tỉnh. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/3+%281%29.jpg/bd74f86c-5b89-228b-88aa-90abd5d81ec3?t=1764918112773\" style=\"height: 444px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh dự hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Căn cứ vào định hướng phát triển KT - XH giai đoạn 2026-2030, kết quả thực hiện các mục tiêu năm 2025, Ban Chấp hành Đảng bộ tỉnh cũng xác định các khó khăn, hạn chế, phân tích nguyên nhân; đồng thời đề xuất các chỉ tiêu phát triển KT- XH. &nbsp;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Theo đó, năm 2026, toàn tỉnh phấn đấu tăng trưởng GRDP 2026 đạt 12,5-13%; &nbsp;GRDP bình quân đầu người đạt 6.350 USD; tổng kim ngạch xuất nhập khẩu đạt 212 tỷ USD; thu ngân sách nhà nước trên địa bàn đạt 72.350 tỷ đồng; tỷ lệ đô thị hóa đạt 43,6% … </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Giai đoạn 2026- 2030, tỉnh phấn tăng trưởng GRDP đạt 11-12%; GRDP bình quân đầu người đạt từ 8.700 - 9.200 USD; tổng kim ngạch xuất nhập khẩu đạt 1.425 tỷ USD; tỷ lệ đô thị hóa đạt 65%; tỷ lệ lao động đã qua đào tạo đạt 90%; đến hết năm 2027 trên địa bàn tỉnh không còn hộ nghèo; tỷ lệ xã được công nhận đạt chuẩn nông thôn mới (theo tiêu chí dự kiến giai đoạn 2026-2030) 69,7 %...</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tiếp tục hoàn thiện hạ tầng giao thông; đẩy mạnh chuyển đổi số; thu hút đầu tư chất lượng cao; củng cố an ninh, quốc phòng, giữ vững an ninh chính trị, trật tự, an toàn xã hội, tạo môi trường ổn định cho phát triển KT - XH. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/210896/5.jpg/3c8982d5-53e9-3ee5-249c-851824b69c9d?t=1764918222458\" style=\"height: 553px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các đồng chí Phó Bí thư Tỉnh ủy: Nguyễn Thị Hương; Trần Huy Phương dự hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><b>Xây dựng các chính sách đảm bảo phát triển KT - XH toàn diện</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thảo luận tại hội nghị, các đại biểu đã cho ý kiến thống nhất vào một số nội dung quan trọng về định hướng phát triển KT -XH giai đoạn tới như: Dự thảo về dự toán và phân bổ dự toán ngân sách nhà nước năm 2026; kế hoạch tài chính NSNN 3 năm 2026-2028; kế hoạch đầu tư công năm 2026, kế hoạch KT-XH 5 năm giai đoạn 2026-2030; &nbsp;kế hoạch tài chính 05 năm giai đoạn 2026-2030 tỉnh … </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đồng thời, xem xét một số dự thảo Nghị quyết của HĐND tỉnh về Ban hành Quy định về nguyên tắc, tiêu chí và định mức phân bổ vốn đầu tư công nguồn ngân sách tỉnh Bắc Ninh, giai đoạn 2026-2030; Nghị quyết Quy định tiêu chí cụ thể để xác định vị trí đối với từng loại đất, số lượng vị trí đất trong bảng giá đất và quyết định bảng giá các loại đất trên địa bàn tỉnh Bắc Ninh…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Hội nghị cũng nghe báo cáo của Đảng ủy UBND tỉnh về tình hình, kết quả thực hiện nhiệm vụ quốc phòng, quân sự địa phương năm 2025, phương hướng, nhiệm vụ năm 2026; kết quả lãnh đạo và tổ chức thực hiện nhiệm vụ kiểm tra, giám sát và thi hành kỷ luật của Đảng trong Đảng bộ tỉnh năm 2025; phương hướng, nhiệm vụ năm 2026 và Báo cáo kết quả thực hiện nhiệm vụ kiểm tra, giám sát của Ủy ban kiểm tra các cấp năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Báo cáo tổng kết công tác lãnh đạo của Tỉnh ủy năm 2025; mục tiêu, nhiệm vụ và giải pháp chủ yếu năm 2026; Nghị quyết của Tỉnh ủy về nhiệm vụ lãnh đạo năm 2026; Chương trình công tác của Tỉnh ủy năm 2026.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/2+%281%29.jpg/3406be49-d9ae-523c-bc87-1975da90306f?t=1764918340424\" style=\"height: 590px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái kết luận hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><b>Tập trung tháo gỡ điểm nghẽn, tạo động lực phát triển kinh tế</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Kết luận hội nghị, Bí thư Tỉnh ủy Nguyễn Hồng Thái đánh giá cao tinh thần triển khai các nhiệm vụ phát triển KT - XH năm 2025 của toàn Đảng bộ tỉnh. Trong bối cảnh còn nhiều khó khăn, phức tạp song, Đảng bộ tỉnh Bắc Ninh đã nỗ lực, quyết tâm lãnh đạo, chỉ đạo đạt được nhiều kết quả tích cực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Trên cơ sở nhìn nhận những tồn tại hạn chế, cùng một số nhiệm vụ trọng tâm trong thời gian tới, nhất là công tác chuẩn bị Đại hội đại biểu toàn quốc lần thứ XIV của Đảng, Bí thư Tỉnh ủy cho rằng mỗi cán bộ, đảng viên trong Ban Chấp hành Đảng bộ tỉnh cần tiếp tục nâng cao vai trò người đứng đầu, quyết tâm chính trị cao để lãnh đạo, chỉ đạo làm tốt công tác chuẩn bị cho các sự kiện chính trị quan trọng sẽ diễn ra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các sở, ngành, cơ quan, đơn vị, địa phương làm tốt công tác tham mưu, chủ động, khoa học, bám sát yêu cầu thực tiễn, bảo đảm sự chỉ đạo thông suốt từ tỉnh đến cơ sở, tránh tư tưởng trông chờ hoặc có biểu hiện trì trệ.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đối với nhiệm vụ phát triển KT - XH, Bí thư Tỉnh ủy yêu cầu các sở, ngành, đơn vị liên quan phải tiếp tục rà soát, tháo gỡ vướng mắc về thủ tục đầu tư, giải phóng mặt bằng, hạ tầng kỹ thuật và tiếp cận đất đai. Thường xuyên bám sát cơ sở, kịp thời tháo gỡ khó khăn vướng mắc, đảm bảo phát triển hài hòa, bền vững mục tiêu KT- XH, tạo không gian mở để kết nối kinh tế liên vùng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Về những tồn tại, khó khăn trong thực hiện các dự án trọng điểm, Bí thư Tỉnh ủy yêu cầu các sở, ngành liên quan tham mưu xây dựng cơ chế giải quyết các vấn đề về nguồn vật liệu san lấp mặt bằng, giải phóng mặt bằng, tái định cư cho nhân dân, bảo đảm linh hoạt, phù hợp với thực tiễn. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các sở, ngành, địa phương trong tỉnh tiếp tục phát huy tinh thần đoàn kết, đổi mới trong chỉ đạo điều hành; tăng cường kiểm tra, giám sát, đôn đốc thực hiện các nhiệm vụ trọng tâm. Làm tốt công tác phối hợp trong triển khai các nhiệm vụ về: Đầu tư công, quy hoạch, phát triển hạ tầng, chuyển đổi số, bảo vệ môi trường, cải cách thủ tục hành chính…. tạo động lực tiếp tục thúc đẩy KT- XH của tỉnh phát triển toàn diện trong thời gian tới./.</span></span></span><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-12-05 06:58:00', 'https://bacninh.gov.vn/news/-/details/37632/hoi-nghi-ban-chap-hanh-ang-bo-tinh-thong-qua-du-thao-bao-cao-phat-trien-kinh-te-xa-hoi-tinh-nam-2025-thao-luan-xem-xet-mot-so-du-thao-nghi-quyet-bao-cao-quan-trong-76474011', '', 'Nguyễn Miền', 487, 'Chính trị', 2, '', '38762', '{}', '2025-12-08 08:18:04.808012', 2, 11);
INSERT INTO `sync_articles` VALUES (295, '75844808', 'Đồng chí Trần Huy Phương, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy được bầu giữ chức Phó Bí...', 'Đồng chí Trần Huy Phương, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy được bầu giữ chức Phó Bí thư Tỉnh ủy Bắc Ninh', '/documents/37632/54780701/b1.jpg/8f7b3b0c-ac67-9655-af53-4925535a2906?t=1764900317909', '<p>(BNP) - Sáng 5/12, Ban Chấp hành Đảng bộ tỉnh Bắc Ninh khóa I tổ chức Hội nghị lần thứ hai, nhiệm kỳ 2025-2030.&nbsp;Đồng chí Nguyễn Hồng Thái, Ủy viên Ban Chấp hành Trung ương Đảng, Bí thư Tỉnh ủy chủ trì hội nghị.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/a1+%281%29.jpg/cb0dc2f4-c884-1627-9436-887a4583531b?t=1764901656793\" style=\"height: 505px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Dự hội nghị có các đồng chí: Nguyễn Văn Tùng, Vụ trưởng Vụ địa phương I, Ban Tổ chức Trung ương; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; đại diện lãnh đạo một số Ban Đảng Trung ương và các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy, Ban Chấp hành Đảng bộ tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/a3+%281%29.jpg/037bae62-41d6-345b-a58f-db3435e1de0a?t=1764900411987\" style=\"height: 479px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái và các đồng chí lãnh đạo tỉnh bỏ phiếu&nbsp;bầu chức danh Phó Bí thư Tỉnh ủy nhiệm kỳ 2025 - 2030.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại hội nghị, &nbsp;Ban Chấp hành Đảng bộ tỉnh đã thông qua Tờ trình của Ban Thường vụ Tỉnh ủy Bắc Ninh về việc bầu cử chức danh Phó Bí thư Tỉnh ủy nhiệm kỳ 2025-2030. Theo đó, đồng chí Trần Huy Phương, Ủy viên Ban Thường vụ Tỉnh ủy, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy Bắc Ninh được giới thiệu để bầu vào chức danh Phó Bí thư Tỉnh ủy Bắc Ninh nhiệm kỳ 2025- 2030. Đồng chí Trần Huy Phương được tín nhiệm với số phiếu tuyệt đối 67/67 (đạt 100%).</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/54780701/b1+%281%29.jpg/c6fa2dbf-ceac-4b54-c810-cd3e8f248373?t=1764901567720\" style=\"height: 521px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các đồng chí lãnh đạo tỉnh chúc mừng đồng chí Trần Huy Phương.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đồng chí Trần Huy Phương, sinh năm 1981, quê quán xã Bình Giang, tỉnh Ninh Bình; hiện cư trú tại phường Hà Đông, thành phố Hà Nội. Đồng chí vào Đảng Cộng sản Việt Nam ngày 28/4/2010. Đồng chí có trình độ Thạc sĩ Kinh tế Chính trị, Cao cấp lý luận chính trị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đồng chí từng trải qua các vị trí công tác: Chuyên viên, Kiểm tra viên, Văn phòng Cơ quan Ủy ban Kiểm tra Trung ương; Vụ trưởng, Thư ký đồng chí Chủ nhiệm Ủy ban Kiểm tra Trung ương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại tỉnh Bắc Ninh (cũ), đồng chí là Ủy viên Ban Thường vụ Tỉnh ủy, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy, Thủ trưởng Cơ quan Ủy ban Kiểm tra Tỉnh ủy.&nbsp;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"></span></span></span><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Từ tháng 7/2025 đến nay, đồng chí tiếp tục giữ chức Ủy viên Ban Thường vụ Tỉnh ủy, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy, Thủ trưởng Cơ quan Ủy ban Kiểm tra Tỉnh ủy Bắc Ninh.</span></span></span><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"></span></span></span><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-12-05 02:03:00', 'https://bacninh.gov.vn/news/-/details/37632/-ong-chi-tran-huy-phuong-chu-nhiem-uy-ban-kiem-tra-tinh-uy-uoc-bau-giu-chuc-pho-bi-thu-tinh-uy-bac-ninh-75844808', '', 'Nguyễn Miền', 2810, 'Chính trị', 2, '', '38762', '{}', '2025-12-08 08:18:04.835465', 2, 11);
INSERT INTO `sync_articles` VALUES (296, '75548002', 'Đoàn đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến đóng góp vào dự thảo Luật Toà án...', 'Đoàn đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến đóng góp vào dự thảo Luật Toà án chuyên biệt tại Trung tâm Tài chính quốc tế', '/documents/37632/54780701/a1.jpg/753bdf2b-cd3b-34a7-5d8a-9b0935ca3e2b?t=1764896310558', '<p>(BNP) - Tiếp tục chương trình làm việc, chiều 4/12, các đại biểu Quốc hội thảo luận ở tổ, cho ý kiến vào dự thảo Luật Toà án chuyên biệt tại Trung tâm Tài chính quốc tế.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a1.jpg/753bdf2b-cd3b-34a7-5d8a-9b0935ca3e2b?t=1764896310558\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn phát biểu trong phiên thảo luận ở tổ, chiều 4/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu Đoàn đại biểu Quốc hội tỉnh Bắc Ninh cơ bản nhất trí về sự cần thiết ban hành luật với các cơ sở chính trị, pháp lý và thực tiễn cũng như yêu cầu phát triển đất nước. Đồng thời, đóng góp nhiều ý kiến nhằm hoàn thiện nội dung của dự thảo luật.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn cho biết, tại điểm a, khoản 2, Điều 5 quy định về áp dụng pháp luật tại toà án chuyên biệt: “Trường hợp các bên không có thỏa thuận về việc áp dụng pháp luật thì áp dụng pháp luật của nước có mối liên hệ gắn bó nhất với quan hệ tranh chấp”.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu không đưa ra tiêu chí cụ thể để xác định, làm rõ thế nào là “gắn bó nhất với quan hệ tranh chấp” có thể phụ thuộc nhiều vào nhận định chủ quan của thẩm phán, dẫn tới cách hiểu và á</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">p dụng không thống nhất giữa các vụ việc có tính chất tương tự. Điều này đặc biệt rủi ro trong môi trường tranh chấp tài chính quốc tế, nơi các giao dịch thường được thiết kế đa tầng, có các điểm kết nối pháp lý ở nhiều quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mặt khác, việc áp dụng pháp luật nước ngoài trong các quan hệ phức tạp đòi hỏi các bên phải có trách nhiệm cung cấp, chứng minh nội dung pháp luật nước ngoài mà họ đề nghị tòa án áp dụng. Trên thực tế, không hiếm trường hợp các bên không thể cung cấp đầy đủ hoặc cung cấp không chính xác nội dung pháp luật nước ngoài, dẫn đến khó khăn cho tòa án trong việc xác minh. Nếu không quy định rõ trách nhiệm và quy trình xác minh, tòa án sẽ phải tự tìm kiếm, thu thập hoặc đánh giá pháp luật nước ngoài, làm kéo dài thời gian tố tụng và có nguy cơ áp dụng sai hoặc thiếu cơ sở xác minh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, đề nghị Ban soạn thảo nghiên cứu bổ sung tiêu chí xác định “pháp luật của nước có mối liên hệ gắn bó nhất” được quy định tại điểm a khoản 2 Điều 5 để tránh cách hiểu và áp dụng tùy nghi. Đồng thời, cần quy định rõ trách nhiệm của các bên trong việc cung cấp thông tin, tài liệu về các yếu tố kết nối pháp lý và làm rõ nguyên tắc xử lý khi không xác định được pháp luật gắn bó nhất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại khoản 1, Điều 12 liệt kê các loại vụ việc thuộc thẩm quyền của tòa án chuyên biệt nhưng loại trừ “các vụ việc liên quan đến lợi ích công cộng, lợi ích của Nhà nước”. Đại biểu cho rằng việc thiếu định nghĩa hoặc hướng dẫn cụ thể thế nào là “các vụ việc liên quan đến lợi ích công cộng, lợi ích của Nhà nước” sẽ dẫn đến tình trạng áp dụng tùy nghi, gây lúng túng cho cơ quan thụ lý cũng như dễ phát sinh mâu thuẫn về thẩm quyền giữa tòa án chuyên biệt và các tòa án nhân dân khác. Vì vậy, đề nghị cơ quan soạn thảo nghiên cứu, bổ sung định nghĩa hoặc tiêu chí xác định các vụ việc được coi là “liên quan đến lợi ích công cộng, lợi ích của Nhà nước” để bảo đảm thống nhất khi áp dụng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về người đại diện, tại khoản 3, Điều 18 quy định: pháp nhân khởi kiện hoặc bị kiện tại tòa án chuyên biệt phải được đại diện bởi luật sư, trừ trường hợp quy tắc tố tụng có quy định khác. Đại biểu cho rằng, đây là quy định phù hợp với chuẩn mực quốc tế, bảo đảm chất lượng tranh tụng và tính chuyên nghiệp của quá trình giải quyết tranh chấp tại Trung tâm Tài chính quốc tế. Tuy nhiên, quy định bắt buộc này có thể dẫn đến khó khăn cho các doanh nghiệp nhỏ, siêu nhỏ và doanh nghiệp khởi nghiệp, vốn có khả năng tài chính hạn chế. Việc thuê luật sư trong toàn bộ quá trình tố tụng có thể làm tăng đáng kể chi phí tuân thủ, ảnh hưởng đến khả năng tiếp cận công lý.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để bảo đảm tính khả thi và cân bằng giữa yêu cầu chuyên nghiệp với điều kiện thực tiễn của doanh nghiệp, đề nghị Ban soạn thảo nghiên cứu, bổ sung quy định hướng dẫn cụ thể các trường hợp ngoại lệ, theo đó doanh nghiệp nhỏ, siêu nhỏ có thể cử người đại diện theo pháp luật hoặc đại diện theo ủy quyền tham gia tố tụng khi vụ việc có tính chất đơn giản hoặc giá trị tranh chấp không lớn. Hoặc cho phép áp dụng mô hình đại diện giới hạn, theo đó doanh nghiệp có thể thuê luật sư thực hiện một phần thủ tục tố tụng quan trọng thay vì bắt buộc thuê toàn diện, nhằm giảm chi phí nhưng vẫn bảo đảm chuẩn mực pháp lý. Và xem xét cơ chế hỗ trợ pháp lý phù hợp hoặc xây dựng danh sách luật sư có mức thù lao phù hợp với khả năng của doanh nghiệp nhỏ khi tham gia tranh chấp tại tòa án chuyên biệt.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a2.jpg/67679ddf-8e14-e7e8-bfd2-596561557a5d?t=1764896367657\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Thị Vân phát biểu trong phiên thảo luận ở tổ, chiều 4/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó trưởng Đoàn đại biểu Quốc hội tỉnh Bắc Ninh Trần Thị Vân tán thành quy định về thẩm phán như trong dự thảo Luật: Thẩm phán của Tòa án chuyên biệt bao gồm cả công dân Việt Nam và người nước ngoài. Đây là bước tiến quan trọng để nâng cao tính quốc tế, sự tin cậy và tính độc lập của tòa án chuyên biệt. Tuy nhiên, đại biểu cho rằng cần bổ sung các quy định chặt chẽ về nghĩa vụ, trách nhiệm, tiêu chuẩn đạo đức và cơ chế xử lý vi phạm để tránh khoảng trống pháp lý khi vận hành.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cần quy định rõ nghĩa vụ bảo mật của thẩm phán bởi phạm vi thông tin mà họ tiếp cận có thể bao gồm bí mật kinh doanh của doanh nghiệp, tài liệu nội bộ của Trung tâm Tài chính quốc tế, dữ liệu tố tụng điện tử, thậm chí cả bí mật nhà nước trong một số giao dịch đặc biệt, cùng với toàn bộ hồ sơ vụ án, chứng cứ và quyết định xét xử. Đặc biệt, đối với thẩm phán nước ngoài, nguy cơ rò rỉ thông tin nhạy cảm hoặc phát sinh xung đột giữa nghĩa vụ giữ bí mật theo pháp luật Việt Nam và nghĩa vụ theo pháp luật nước sở tại là hoàn toàn có thể xảy ra.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cho rằng do thẩm phán nước ngoài có thể đang hoạt động nghề nghiệp tại quốc gia khác hoặc giữ vị trí trong các tổ chức luật quốc tế, nguy cơ phát sinh xung đột lợi ích là hoàn toàn có thể xảy ra nếu họ được phân công xét xử các tranh chấp liên quan đến các tổ chức, doanh nghiệp có quan hệ lợi ích với họ. Điều này có thể ảnh hưởng trực tiếp đến tính độc lập, khách quan của Tòa án chuyên biệt và làm giảm niềm tin của các bên khi tham gia tranh tụng. Vì vậy, đề nghị Ban soạn thảo nghiên cứu bổ sung quy định rõ ràng về tiêu chuẩn phòng tránh xung đột lợi ích. Theo đó, thẩm phán không được tham gia xét xử nếu có lợi ích trực tiếp hoặc gián tiếp đối với bất kỳ bên nào trong các vụ tranh chấp, hoặc nếu họ đang đảm nhiệm một công việc, chức vụ hay vị trí nghề nghiệp khác có khả năng tác động, chi phối hoặc làm suy giảm tính độc lập và vô tư trong quá trình xét xử.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều 13 hiện quy định ngôn ngữ sử dụng trước Tòa án chuyên biệt là tiếng Anh hoặc tiếng Anh kèm theo bản dịch tiếng Việt. Tuy nhiên, việc xác định cứng ngôn ngữ như vậy có thể gây hạn chế cho các bên tham gia giao dịch, đặc biệt trong các vụ việc có yếu tố quốc tế hoặc khi một bên là tổ chức, cá nhân Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để đảm bảo quyền lựa chọn ngôn ngữ trong quá trình tranh chấp, đề nghị Ban soạn thảo nghiên cứu quy định cho phép các bên tự do lựa chọn ngôn ngữ tranh tụng mà họ thấy phù hợp. Cụ thể, các bên có thể lựa chọn sử dụng tiếng Anh, tiếng Việt, hoặc song ngữ Anh–Việt. Đồng thời, cần bổ sung quy định về dịch thuật và chứng thực tài liệu, bao gồm: hồ sơ, tài liệu, lời khai nếu được trình bày bằng ngôn ngữ khác tiếng Việt phải được dịch sang tiếng Việt bởi phiên dịch viên được chứng nhận hoặc dịch thuật công chứng, nhằm đảm bảo tính minh bạch, chính xác và hợp pháp của quá trình tố tụng.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a3.jpg/53915e12-3d3a-2ac3-73b1-527adfca4829?t=1764896451180\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Quốc hội Nguyễn Thị Kim Anh phát biểu trong phiên thảo luận ở tổ, chiều 4/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Kim Anh cho rằng về việc mở rộng đối tượng lựa chọn thẩm phán, bao gồm cả công chức, viên chức, nhà khoa học, giảng viên, chuyên gia nghiên cứu… cần được nghiên cứu tiếp. Dự thảo yêu cầu tối thiểu 10 năm kinh nghiệm xét xử, giải quyết vụ việc liên quan đến đầu tư – kinh doanh, nhưng nhóm đối tượng này thực tiễn không có điều kiện tham gia xét xử để tích lũy thâm niên. Đề nghị điều chỉnh theo hướng tập trung vào tiêu chí đạo đức, sức khỏe, uy tín, trình độ chuyên môn sâu và khả năng tiếng Anh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về giải quyết, xét xử vụ việc trên môi trường điện tử (Điều 15), đại biểu đánh giá cao tinh thần thể chế hóa Nghị quyết 27 về khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số trong hoạt động tố tụng. Tuy nhiên, dự thảo cần bổ sung quy định về xây dựng hệ thống hạ tầng điện tử thống nhất, bao gồm quản lý hồ sơ điện tử, chia sẻ tài liệu bảo mật, lưu trữ an toàn theo chuẩn mực quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo quy định Nhà nước đầu tư cơ sở vật chất và bố trí kinh phí hoạt động cho Tòa án chuyên biệt; đồng thời có bố trí ngân sách địa phương. Tuy nhiên, cần cơ chế phân định rõ khi nào sử dụng ngân sách trung ương, khi nào sử dụng ngân sách địa phương để tránh chồng chéo và bảo đảm bố trí nguồn lực kịp thời.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo dự kiến luật có hiệu lực từ 1/1/2026, thời gian chuẩn bị rất ngắn. Tòa án chuyên biệt là mô hình hoàn toàn mới; nhiều nội dung cụ thể còn phải quy định chi tiết trong nghị định. Vì vậy, đề nghị xem xét lùi thời điểm có hiệu lực để Tòa án nhân dân tối cao có đủ thời gian chuẩn bị nhân sự, quy trình và cơ sở vật chất.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a4.jpg/2076f5b6-75a0-4eef-6769-b449a2dda087?t=1764896504774\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Quốc hội Đỗ Thị Việt Hà phát biểu trong phiên thảo luận ở tổ, chiều 4/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về thành phần xét xử sơ thẩm, phúc thẩm của tòa án chuyên biệt, tại khoản 1 Điều 14 dự thảo Luật hiện có 2 quan điểm khác nhau. Đại biểu Đỗ Thị Việt Hà tán thành quan điểm 1: Việc xét xử sơ thẩm bằng 1 thẩm phán, không có sự tham gia của hội thẩm nhân dân; trường hợp vụ việc phức tạp, theo đề nghị của các bên, Chánh án tòa án quyết định việc xét xử sơ thẩm bằng hội đồng gồm 3 thẩm phán. Việc xét xử phúc thẩm bằng hội đồng có 3 thẩm phán.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đại biểu, quy định này phù hợp với Hiến pháp và yêu cầu đặc thù của thủ tục tố tụng tại tòa án chuyên biệt và tương đồng với thông lệ quốc tế. Do thủ tục tố tụng tại tòa án được quy định theo nguyên tắc của hệ thống thông luật, khác với pháp luật về tố tụng dân sự của Việt Nam, rút ngắn về thời gian, rút gọn về trình tự và linh hoạt để đáp ứng thực tiễn đầu tư, kinh doanh quốc tế. Trong một số trường hợp thì thẩm phán có thể bỏ bớt một số thủ tục, ra ngay quyết định giải quyết vụ việc mà không cần phải mở phiên tòa.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, đề nghị Tòa án nhân dân tối cao nghiên cứu thêm, có thể quy định theo hướng thành phần xét xử phúc thẩm có ít nhất 3 thẩm phán (thay vì quy định cứng là 3 thẩm phán) để có cơ sở pháp lý bổ sung thêm thẩm phán xét xử đối với các vụ việc phức tạp khi cần thiết, vì bản án, quyết định của tòa phúc thẩm là quyết định chung thẩm, có hiệu lực thi hành và không bị xem xét lại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng trong chiều 4/12, các đại biểu Quốc hội thảo luận về dự thảo Nghị quyết của Quốc hội về cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/54780701/a5.jpg/b2d23b3d-8ae5-16db-ee7c-8d7c880a05a0?t=1764896551213\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Quốc hội Trần Văn Lâm phát biểu trong phiên thảo luận ở tổ, chiều 4/12.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cho ý kiến vào dự thảo Nghị quyết này, đại biểu Trần Văn Lâm đề nghị cơ quan soạn thảo nghiên cứu, bảo đảm quán triệt đầy đủ tinh thần Nghị quyết 70 và Nghị quyết 68.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong quan điểm chỉ đạo của Nghị quyết 70, đã xác định rõ: Nhà nước kiến tạo, giữ vai trò chủ thể hoạch định chính sách và kiểm soát hạ tầng năng lượng chiến lược; người dân và doanh nghiệp là trung tâm, là chủ thể phát triển năng lượng quốc gia, trong đó kinh tế nhà nước giữ vai trò chủ đạo, còn khu vực tư nhân là một trong những động lực quan trọng nhất. Đồng thời, Nghị quyết 68 cũng nhấn mạnh việc xóa bỏ phân biệt đối xử giữa các thành phần kinh tế, coi kinh tế tư nhân là một động lực quan trọng của nền kinh tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, tại Điều 8 của dự thảo Nghị quyết, khoản 1 và khoản 2 đều đưa ra các chính sách đặc thù chỉ dành cho doanh nghiệp nhà nước. Như vậy là đang khoanh vùng những dự án mà chỉ doanh nghiệp nhà nước được tham gia, không tạo điều kiện bình đẳng cho doanh nghiệp tư nhân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu kiến nghị xem xét điều chỉnh quy định tại Điều 8, bảo đảm phù hợp chủ trương khuyến khích mọi thành phần kinh tế tham gia phát triển năng lượng quốc gia. Ngay cả với những công trình đặc biệt như nhà máy điện nguyên tử, nếu doanh nghiệp tư nhân đủ năng lực và chịu trách nhiệm thì cũng nên được xem xét, thay vì loại bỏ chỉ vì lý do về sở hữu vốn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đồng tình với mục tiêu tăng cường năng lực dự trữ xăng dầu quốc gia để bảo đảm an ninh năng lượng và phục vụ điều tiết kinh tế. Tuy nhiên, hiện nay Quốc hội cũng đang thảo luận sửa Luật Dự trữ quốc gia. Trong đó xác định dự trữ quốc gia không chỉ nhằm phòng, chống thiên tai, tình huống đột xuất, mà còn hướng tới hình thành dự trữ chiến lược để điều tiết nền kinh tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự trữ xăng dầu là một trong những nội dung dự trữ chiến lược quan trọng. Tuy nhiên, việc đưa quy định về dự trữ xăng dầu quốc gia vào dự thảo Nghị quyết này cùng thời điểm nước ta đang sửa Luật Dự trữ quốc gia sẽ dẫn đến trùng lặp, chồng chéo về phạm vi điều chỉnh, nguy cơ thiếu thống nhất trong hệ thống pháp luật. Do đó, đề nghị chuyển toàn bộ nội dung Chương VII về dự trữ xăng dầu sang dự thảo Luật Dự trữ quốc gia để bảo đảm thống nhất, đồng bộ.</span></span></span></p>', '2025-12-05 00:56:00', 'https://bacninh.gov.vn/news/-/details/37632/-oan-ai-bieu-quoc-hoi-tinh-bac-ninh-nhieu-y-kien-ong-gop-vao-du-thao-luat-toa-an-chuyen-biet-tai-trung-tam-tai-chinh-quoc-te-75548002', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 266, 'Chính trị', 2, '', '38762', '{}', '2025-12-08 08:18:04.863207', 2, 11);
INSERT INTO `sync_articles` VALUES (297, '75529807', 'Hôm nay (5/12), Quốc hội biểu quyết thông qua 3 dự án luật liên quan đến lĩnh vực tư...', 'Hôm nay (5/12), Quốc hội biểu quyết thông qua 3 dự án luật liên quan đến lĩnh vực tư pháp', '/documents/37632/54780701/z7291794578137_a821a101f08e1af7d1b08100e0e17cb8.jpg/2024276d-ad71-a68e-4c3e-25176f687fa2?t=1764895939498', '<p>(BNP) - Theo chương trình làm việc của Kỳ họp thứ 10, Quốc hội khóa XV, sáng nay, 5/12, Quốc hội sẽ thảo luận ở hội trường về chủ trương đầu tư Chương trình mục tiêu quốc gia về nông thôn mới, giảm nghèo bền vững, phát triển kinh tế - xã hội vùng đồng bào dân tộc thiểu số và miền núi đến năm...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/54780701/z7291794578137_a821a101f08e1af7d1b08100e0e17cb8.jpg/2024276d-ad71-a68e-4c3e-25176f687fa2?t=1764895939498\" style=\"width: 900px; height: 675px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh thảo luận tại tổ ngày 4/12.</span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Nông nghiệp và Môi trường giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi chiều, từ 14 giờ đến 16 giờ, Quốc hội biểu quyết thông qua Luật Giám định tư pháp (sửa đổi); Luật Thi hành án dân sự (sửa đổi); Luật sửa đổi, bổ sung một số điều của Luật Lý lịch tư pháp.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Quốc hội thảo luận ở hội trường về dự án Luật sửa đổi, bổ sung một số điều của Luật Tiếp công dân, Luật Khiếu nại, Luật Tố cáo. Tổng Thanh tra Chính phủ giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ 16 giờ đến 17 giờ 30, Quốc hội thảo luận ở hội trường về dự án Luật Toà án chuyên biệt tại Trung tâm tài chính quốc tế. Chánh án Tòa án nhân dân tối cao giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '2025-12-05 00:50:00', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-5-12-quoc-hoi-bieu-quyet-thong-qua-3-du-an-luat-lien-quan-en-linh-vuc-tu-phap-75529807', '', 'BNP', 52, 'Chính trị', 2, '', '38762', '{}', '2025-12-08 08:18:04.891361', 2, 11);
INSERT INTO `sync_articles` VALUES (298, '65340802', 'Bắc Ninh triển khai nhiệm vụ trọng tâm công tác bầu cử đại biểu Quốc hội khóa XVI và...', 'Bắc Ninh triển khai nhiệm vụ trọng tâm công tác bầu cử đại biểu Quốc hội khóa XVI và HĐND các cấp', '/documents/37632/200628/AnhBC.jpg/f4db7861-70aa-ab5c-03ed-b53fccf13588?t=1764834011129', '<p>(BNP) - Ủy ban bầu cử tỉnh Bắc Ninh vừa ban hành Công văn số 11/UBBC-TT yêu cầu các cơ quan, ban, ngành tỉnh và UBND, Uỷ ban MTTQ, Uỷ ban bầu cử các xã, phường tập trung triển khai thực hiện nhiệm vụ công tác bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026-2031.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/AnhBC.jpg/f4db7861-70aa-ab5c-03ed-b53fccf13588?t=1764834011129\" style=\"height: 584px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ. Nguồn ảnh: hcc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm chủ động triển khai thực hiện tốt công tác bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp trên địa bàn tỉnh, Ủy ban bầu cử tỉnh đề nghị các cơ quan, ban, ngành, đơn vị cấp tỉnh, Đảng ủy, HĐND, UBND, Ủy ban MTTQ Việt Nam, Ủy ban bầu cử đại biểu HĐND cấp xã tập trung triển khai thực hiện một số nhiệm vụ trọng tâm: </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ trưởng các cơ quan, ngành, đơn vị cấp tỉnh theo chức năng, nhiệm vụ tập trung triển khai công tác bầu cử theo quy định; tổ chức tuyên truyền, quán triệt đến toàn thể đội ngũ cán bộ, công chức, viên chức, người lao động hiểu rõ nội dung, mục đích yêu cầu cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp. Phát động phong trào thi đua trong các cơ quan, đơn vị và nhân dân, tạo sức lan tỏa, hưởng ứng mạnh mẽ, tích cực tham gia cuộc bầu cử. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cơ quan, đơn vị tổ chức hội nghị giới thiệu người của cơ quan, đơn vị mình ứng cử bảo đảm cơ cấu, số lượng, trình tự thủ tục theo Nghị quyết liên tịch số 102/2025/NQLT-UBTVQH15- ĐCTUBTƯMTTQVN ngày 26/9/2025.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với cấp xã, Thường trực HĐND sau khi thống nhất với Uỷ ban MTTQ và UBND cùng cấp phải hoàn thành dự kiến cơ cấu, thành phần, phân bổ số lượng người được giới thiệu ứng cử đại biểu HĐND, bảo đảm theo Nghị quyết số 107/2025/NQ-UBTVQH15 ngày 16/10/2025 của Ủy ban Thường vụ Quốc hội; đồng thời dự kiến thành phần giới thiệu tham gia ứng cử đảm bảo cân đối, hài hòa giữa đại biểu các khối Đảng, chính quyền, MTTQ, tổ chức chính trị - xã hội, thôn, tổ dân phố, đơn vị sự nghiệp và doanh nghiệp trên địa bàn.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc xác định số người ứng cử trong danh sách thực hiện theo khoản 3, Điều 58, Luật Bầu cử: “Số người trong danh sách ứng cử đại biểu Hội đồng nhân dân ở mỗi đơn vị bầu cử phải nhiều hơn số lượng đại biểu được bầu đã ấn định cho đơn vị bầu cử đó; nếu đơn vị bầu được bầu 03 đại biểu thì số người trong danh sách ứng cử phải nhiều hơn số lượng đại biểu được bầu ít nhất là 2 người; nếu đơn vị bầu cử được bầu từ 4 đại biểu trở lên thì số người trong danh sách ứng cử phải nhiều hơn số lượng đại biểu được bầu ít nhất là 3 người”. Các đơn vị hạn chế ấn định các đơn vị bầu cử bầu 01 hoặc bầu 02 đại biểu.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND, Ủy ban bầu cử cấp xã chủ động lập dự toán kinh phí chi bầu cử theo quy định tại Nghị quyết của HĐND tỉnh quy định nội dung, định mức chi bầu cử nhiệm kỳ 2026-2031 và các văn bản quy định hiện hành; tiếp nhận nguồn ngân sách từ Trung ương, cấp tỉnh chuyển về, cân đối ngân sách của địa phương để cấp đến các tổ chức phụ trách bầu cử, đảm bảo đầy đủ điều kiện, cơ sở vật chất phục vụ bầu cử trên địa bàn.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ động phân công người tiếp nhận hồ sơ ứng cử từ ngày 15/12/2025 đến 17h ngày 01/02/2026; lập danh sách trích ngang và tiểu sử tóm tắt để niêm yết; phối hợp tổ chức hội nghị tiếp xúc cử tri, tạo điều kiện để ứng cử viên vận động bầu cử theo quy định.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban bầu cử tỉnh giao Sở Nội vụ - Cơ quan thường trực Ủy ban bầu cử tỉnh, phối hợp Sở Tài chính tham mưu phân bổ ngân sách và phát động phong trào thi đua thực hiện tốt công tác bầu cử; lựa chọn các tập thể, cá nhân tiêu biểu trình cấp có thẩm quyền khen thưởng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban bầu cử tỉnh đề nghị các cơ quan, đơn vị nghiêm túc triển khai các nhiệm vụ theo đúng quy định pháp luật, bảo đảm tổ chức thành công cuộc bầu cử trên địa bàn tỉnh.</span></span></span></p>', '2025-12-04 08:30:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-nhiem-vu-trong-tam-cong-tac-bau-cu-ai-bieu-quoc-hoi-khoa-xvi-va-h-nd-cac-cap-65340802', '', 'Dương Thuỷ', 66, 'Chính trị', 2, '', '38762', '{}', '2025-12-08 08:18:04.917300', 2, 11);
INSERT INTO `sync_articles` VALUES (299, '80975979', 'Thủ tướng Chính phủ ra Công điện chỉ đạo đẩy nhanh tiến độ giải ngân vốn đầu tư công...', 'Thủ tướng Chính phủ ra Công điện chỉ đạo đẩy nhanh tiến độ giải ngân vốn đầu tư công những tháng cuối năm 2025', 'https://bacninh.gov.vn/documents/37632/41409701/1-2.png/6088251d-9820-eb54-8f19-2967c9bf97bc?t=1764581652690', '<p>(BNP) - Thủ tướng Chính phủ Phạm Minh Chính ký Công điện số 237/CĐ-TTg về việc đẩy nhanh tiến độ giải ngân vốn đầu tư công những tháng cuối năm 2025.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/41409701/1-2.png/6088251d-9820-eb54-8f19-2967c9bf97bc?t=1764581652690\" style=\"width: 900px; height: 590px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Công điện, nhằm tăng tốc, bứt phá, phấn đấu hoàn thành mục tiêu giải ngân 100% kế hoạch vốn đầu tư công năm 2025, góp phần ổn định kinh tế vĩ mô, thúc đẩy tăng trưởng, đảm bảo các cân đối lớn của nền kinh tế, tạo công ăn, việc làm, sinh kế cho người dân, thực hiện hoàn thành các mục tiêu phát triển kinh tế - xã hội, Thủ tướng Chính phủ yêu cầu Bộ trưởng, Thủ trưởng cơ quan trung ương, Chủ tịch UBND các tỉnh, thành phố trực thuộc Trung ương và đề nghị các đồng chí Bí thư Tỉnh ủy, Thành ủy, Chủ tịch Hội đồng nhân dân, Trưởng Đoàn đại biểu Quốc hội các tỉnh, thành phố trực thuộc Trung ương đề cao trách nhiệm, tập trung chỉ đạo triển khai thực hiện quyết liệt, đồng bộ, kịp thời, hiệu quả hơn nữa các nhiệm vụ, giải pháp trọng tâm sau:</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Bộ trưởng, Thủ trưởng cơ quan ngang bộ, cơ quan thuộc Chính phủ, các cơ quan khác ở Trung ương, Chủ tịch UBND các tỉnh, thành phố trực thuộc Trung ương</b> chịu trách nhiệm toàn diện trước Thủ tướng Chính phủ trong việc chỉ đạo thực hiện đồng bộ các nhiệm vụ, giải pháp đã đề ra trong các Nghị quyết, kết luận của Đảng, Quốc hội, Chính phủ, các Công điện, Chỉ thị, văn bản chỉ đạo Thủ tướng Chính phủ về đẩy mạnh phân bổ, giải ngân vốn đầu tư công. Xác định nhiệm vụ thúc đẩy đầu tư công là một trong những nhiệm vụ chính trị quan trọng hàng đầu, là một trong các tiêu chí đánh giá cán bộ theo Quy định 366-QĐ/TW của Bộ Chính trị; do đó trong lãnh đạo, chỉ đạo phải có quyết tâm cao, nỗ lực lớn, hành động quyết liệt, làm việc nào ra việc đó, làm việc nào dứt việc đó, phân công phải bảo đảm \"6 rõ: rõ người, rõ việc, rõ trách nhiệm, rõ thẩm quyền, rõ thời gian, rõ kết quả\".</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Các bộ, cơ quan Trung ương và địa phương:</b></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Khẩn trương phân bổ số vốn kế hoạch năm 2025 còn lại chưa giao chi tiết cho các nhiệm vụ, dự án và có giải pháp quyết liệt, kịp thời đẩy mạnh thực hiện và giải ngân số vốn đầu tư công, vốn chương trình mục tiêu quốc gia đã được giao; đẩy nhanh tiến độ triển khai các công trình, dự án đầu tư công trọng điểm, quan trọng quốc gia, đường cao tốc, công trình trọng điểm, liên vùng, dự án có tác động lan tỏa,... </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quyết liệt, chủ động xử lý, tháo gỡ những vướng mắc, khó khăn một cách kịp thời, hiệu quả theo chức năng, nhiệm vụ được giao; thực hiện cơ chế phân công, phối hợp rõ ràng, cụ thể về thẩm quyền, trách nhiệm giữa các cơ quan, đơn vị trong việc hoàn thiện thủ tục đầu tư dự án. Tiếp tục đẩy mạnh, nâng cao hiệu quả hoạt động tổ công tác đặc biệt do Chủ tịch UBND cấp tỉnh làm Tổ trưởng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tăng cường kỷ luật, kỷ cương trong giải ngân vốn đầu tư công; tập trung đẩy nhanh tiến độ giải phóng mặt bằng, tiến độ thi công, tháo gỡ các khó khăn vướng mắc về đất đai, tài nguyên...; có chế tài xử lý nghiêm theo quy định pháp luật các chủ đầu tư, Ban quản lý dự án, tổ chức, cá nhân cố tình gây khó khăn, cản trở, làm chậm tiến độ giao vốn, thực hiện và giải ngân vốn đầu tư công. Thay thế kịp thời những cán bộ, công chức, viên chức yếu kém về năng lực, trì trệ, gây nhũng nhiễu, phiền hà, kiên quyết xử lý các hành vi tiêu cực trong quản lý đầu tư công. Thực hiện thanh tra, kiểm tra, xử lý nghiêm tình trạng giao mỏ không đúng đối tượng làm nảy sinh hoạt động mua đi bán lại tăng giá vật liệu.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lập kế hoạch giải ngân chi tiết từng dự án và tuân thủ nghiêm kế hoạch giải ngân theo từng tuần, từng tháng; phân công cụ thể lãnh đạo chịu trách nhiệm theo dõi tiến độ thực hiện dự án để kịp thời tháo gỡ khó khăn, vướng mắc và chịu trách nhiệm về kết quả giải ngân của từng dự án, coi đây là căn cứ đánh giá xếp loại mức độ hoàn thành nhiệm vụ được giao trong năm 2025; thực hiện rà soát ngay tiến độ giải ngân từng dự án để có phương án điều chuyển vốn từ dự án giải ngân không hết, còn dư vốn đã giao sang bổ sung cho các dự án giải ngân tốt và có nhu cầu bổ sung vốn trong năm 2025 theo thẩm quyền. Tăng cường công tác kiểm tra, giám sát hiện trường, đôn đốc các nhà thầu, tư vấn đẩy nhanh tiến độ.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các địa phương tập trung tháo gỡ khó khăn liên quan đến đền bù giải phóng mặt bằng, cấp phép mỏ, khai thác nguyên vật liệu đá, cát, đất, phục vụ các dự án; công bố giá các loại vật liệu xây dựng phổ biến trên địa bàn theo thẩm quyền và quy định của pháp luật; kiểm tra, rà soát, quản lý chặt chẽ giá vật liệu xây dựng; chỉ đạo các cơ quan, đơn vị trực thuộc thường xuyên theo dõi, bám sát diễn biến thị trường xây dựng để kịp thời cập nhật, công bố giá vật liệu xây dựng theo quy định của pháp luật. Đẩy mạnh công tác thanh toán, quyết toán vốn đầu tư công, không để tồn đọng khối lượng đã thực hiện nhưng không được thanh toán.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Tổ trưởng các Tổ công tác của Thủ tướng Chính phủ, các Thành viên Chính phủ</b>: Tăng cường kiểm tra, giám sát, triển khai hoạt động thường xuyên của các Tổ công tác của Thủ tướng Chính phủ, các Thành viên Chính phủ theo phân công chủ động làm việc với các bộ, cơ quan trung ương, địa phương để kiểm tra, đôn đốc, tháo gỡ kịp thời các khó khăn vướng mắc trong giải ngân vốn đầu tư công.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Bộ Tài chính</b>: Áp dụng chuyển đổi số trong giám sát, kiểm tra, theo dõi đôn đốc tiến độ thực hiện giải ngân của các bộ, cơ quan trung ương và địa phương, kịp thời báo cáo Thủ tướng Chính phủ những cơ quan, đơn vị, địa phương giải ngân chậm và đề xuất ban hành các giải pháp điều hành linh hoạt, sát với tình hình thực tiễn nhằm hoàn thành mục tiêu giải ngân vốn đầu tư công năm 2025. Hằng tuần, công khai tình hình thực hiện và tỷ lệ giải ngân của các bộ, cơ quan trung ương, địa phương trên các phương tiện thông tin đại chúng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Bộ Xây dựng</b>: Chủ trì, phối hợp với các cơ quan liên quan theo dõi sát tình hình, diễn biến thị trường vật liệu xây dựng, đặc biệt là các vật liệu chủ yếu, kịp thời đề xuất, báo cáo Thủ tướng Chính phủ các giải pháp tháo gỡ khó khăn, vướng mắc trong việc bảo đảm cung cầu, kiểm soát giá vật liệu xây dựng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Bộ Nông nghiệp và Môi trường</b>: Tiếp tục hướng dẫn, tháo gỡ ngay khó khăn, vướng mắc liên quan đến quy trình cấp phép mỏ, khai thác nguyên vật liệu đá, cát, đất, sỏi phục vụ dự án đầu tư công, bảo đảm tiến độ, hiệu quả, đúng quy định pháp luật. Hướng dẫn triển khai tháo gỡ ngay các khó khăn, vướng mắc về pháp lý và trình tự, thủ tục liên quan đến đất đai, giải phóng mặt bằng phục vụ triển khai các dự án phát triển kinh tế - xã hội và các dự án giao thông trọng điểm.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Các Bộ, cơ quan chủ chương trình mục tiêu quốc gia</b> kịp thời xử lý, tháo gỡ các khó khăn, vướng mắc của các bộ, ngành, địa phương để thúc đẩy tiến độ giải ngân vốn của các Chương trình.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Các cơ quan truyền thông báo chí ở Trung ương và địa phương</b> tích cực triển khai công tác chuyên môn nghiệp vụ báo chí góp phần tuyên truyền những gương điển hình tiên tiến, cách làm hay và phát hiện những nơi chậm tiến độ kéo dài, những tập thể, cá nhân trì trệ, có biểu hiện tiêu cực...</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Các bộ, cơ quan Trung ương và địa phương</b> chủ động lựa chọn bố trí vốn năm 2026 các dự án đã đủ thủ tục đầu tư, đủ điều kiện giải ngân. Khẩn trương phân bổ và giao chi tiết kế hoạch đầu tư vốn ngân sách nhà nước năm 2026 ngay sau khi được Thủ tướng Chính phủ giao kế hoạch, bảo đảm đúng quy định tại Luật Đầu tư công, Nghị quyết của Quốc hội, chỉ đạo của Thủ tướng Chính phủ về dự toán ngân sách nhà nước năm 2026. Chủ động có kế hoạch và giải pháp cụ thể tháo gỡ khó khăn, vướng mắc trong việc đền bù, giải phóng mặt bằng, đấu thầu,... đẩy nhanh tiến độ thi công dự án.</span></span></span></p>', '2025-12-08 01:17:00', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-chinh-phu-ra-cong-ien-chi-ao-ay-nhanh-tien-o-giai-ngan-von-au-tu-cong-nhung-thang-cuoi-nam-2025-80975979', '', 'BNP', 26, 'Kinh tế', 3, 'true', '38762', '{}', '2025-12-08 08:18:05.848314', 3, 11);
INSERT INTO `sync_articles` VALUES (300, '80874680', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn kiểm tra tiến độ thực hiện Khu đền thờ Bác Hồ thuộc...', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn kiểm tra tiến độ thực hiện Khu đền thờ Bác Hồ thuộc dự án Công viên Văn Miếu', '/documents/37632/75763001/7-1.png/def86d9b-21c7-3156-6a51-6c51eff4de1b?t=1765074886482', '<p>(BNP) - Sáng 7/12, đồng chí Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đi kiểm tra tiến độ thực hiện Khu đền thờ Bác Hồ thuộc dự án đầu tư xây dựng hạ tầng kỹ thuật và các công trình phụ trợ Công viên Văn Miếu, thuộc phường Kinh Bắc và Võ Cường, tỉnh Bắc Ninh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/75763001/7-1.png/def86d9b-21c7-3156-6a51-6c51eff4de1b?t=1765074886482\" style=\"height: 640px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Phạm Hoàng Sơn (thứ 2 từ trái sang); Phó Chủ tịch UBND tỉnh Lê Xuân Lợi (thứ 2 từ phải sang) xem bản vẽ công trình.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng đi có đồng chí Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; Tạ Đăng Đoan, Ủy viên Ban Thường vụ Tỉnh ủy, Bí thư Đảng ủy phường Kinh Bắc; lãnh đạo một số sở, ngành, địa phương liên quan.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án Đầu tư xây dựng hạ tầng kỹ thuật và các công trình phụ trợ Công viên Văn Miếu do Ban Quản lý dự án xây dựng Kinh Bắc làm chủ đầu tư với tổng mức đầu tư gần 700 tỷ đồng. Dự án được khởi công từ tháng 1/2025, xây dựng trên khu vực có diện tích khoảng 4,7ha; chia thành 3 khu; trong đó, Khu Đền thờ Bác Hồ, hồ sen, sân xung quanh hồ sen và khu sân kết đoàn có diện tích khoảng 0,44ha. Đến nay, dự án đã giải ngân vốn được gần 75% kế hoạch.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trong đó, đối với khu Đền thờ Bác Hồ và hồ sen (thực hiện bằng nguồn vốn xã hội hóa), Sở Xây dựng đã thẩm định thiết kế bản vẽ thi công; chủ đầu tư đang hoàn thiện thủ tục đối với các nhà tài trợ; phấn đấu thi công hoàn thành trước ngày 30/4/2026. Bức Phù điêu đang thực hiện triển khai thiết kế bản vẽ thi công. Về Tượng đài Chủ tịch Hồ Chí Minh, sau khi có ý kiến chấp thuận của Trung ương, UBND tỉnh chỉ đạo tổ chức thực hiện theo kế hoạch. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/75763001/7-2.png/264df513-bf64-5653-c879-12660d62b203?t=1765075068123\" style=\"height: 643px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh kiểm tra thực tế một số hạng mục của Dự án.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Về kết quả giải phóng mặt bằng đối với 59 hộ có đất ở nằm trong dự án, đã phê duyệt phương án bồi thường, hỗ trợ 54 hộ; trong đó, 45 hộ đã nhận tiền bồi thường, 37 hộ đã bàn giao mặt bằng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án còn gặp một số khó khăn, vướng mắc do hạng mục Tượng đài Chủ tịch Hồ Chí Minh và Bức phù điêu tại Sân Kết đoàn phải thực hiện theo trình tự do vậy cần thời gian để thực hiện các bước theo quy định; nguồn cung một số vật liệu khan hiếm; nhiều hộ gia đình đã phê duyệt phương án bồi thường, hỗ trợ nhưng chưa nhận tiền dù đã vận động nhiều lần, chưa thể cưỡng chế do hiện nay chưa bàn giao được đất tái định cư; đường dây điện và trạm biến áp chưa được dịch chuyển do đó phần móng Đền thờ Bác Hồ, hồ sen và hạ tầng kỹ thuật xung quanh khu vực Đền thờ Bác Hồ chưa có đủ mặt bằng để triển khai thi công…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trực tiếp kiểm tra thực địa công trình và phân tích những nguyên nhân khách quan, chủ quan dẫn đến việc chậm tiến độ của Dự án, Chủ tịch UBND tỉnh Phạm Hoàng Sơn nhấn mạnh đây là công trình có yếu tố tâm linh với ý nghĩa đặc biệt quan trọng nằm ở vị trí chiến lược của tỉnh; do đó yếu tố thẩm mỹ, mỹ quan và chất lượng công trình rất quan trọng. Vì vậy, đề nghị chủ đầu tư dự án tiếp tục tập trung triển khai thực hiện với quyết tâm cao nhất nhằm nâng cao chất lượng công trình, đảm bảo tiến độ đề ra. Đồng thời, xem xét quy hoạch cây xanh đảm bảo thẩm mỹ, ý tưởng phù hợp với văn hóa và có ý nghĩa. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/75763001/7-3.png/a6157cee-6741-b99d-1505-78f0bc509785?t=1765075140865\" style=\"height: 639px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh kiểm tra thực địa công trình dự án.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Về công tác giải phóng mặt bằng, Chủ tịch UBND tỉnh giao Trung tâm phát triển Quỹ đất chi nhánh Kinh Bắc khẩn trương hoàn thiện hạ tầng tái định cư để giải phóng mặt bằng đối với các hộ còn lại, đảm bảo bàn giao mặt bằng cho chủ đầu tư.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phường Kinh Bắc và Võ Cường chủ động phối hợp chặt chẽ với chủ đầu tư,&nbsp;<span style=\"line-height:1.3;\"><span lang=\"VI\">Trung tâm</span> <span lang=\"VI\">phát triển quỹ đất tỉnh, Chi nhánh Trung tâm phát triển quỹ đất Kinh Bắc</span></span> trong việc triển khai thực hiện dự án, nhất là&nbsp;<span lang=\"VI\">tích cực</span> <span lang=\"VI\">tuyên truyền vận động Nhân dân tiếp tục nhận kinh phí bồi thường và bàn giao mặt</span> <span lang=\"VI\">bằng cho chủ đầu tư để tổ chức thi công, đảm bảo mỹ quan đô thị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh giao Phó Chủ tịch UBND tỉnh Lê Xuân Lợi bám sát tiến độ công trình; Ban Tuyên giáo và Dân vận Tỉnh ủy, Sở Văn hóa, Thể thao và Du lịch khẩn trương báo cáo, xin ý kiến Ban Thường vụ, Thường trực Tỉnh ủy; từ đó, xin ý kiến các Bộ, ngành, Trung ương về hạng mục Tượng đài Chủ tịch Hồ Chí Minh./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-12-07 02:34:00', 'https://bacninh.gov.vn/news/-/details/37632/chu-tich-ubnd-tinh-pham-hoang-son-kiem-tra-tien-o-thuc-hien-khu-en-tho-bac-ho-thuoc-du-an-cong-vien-van-mieu-80874680', '', 'Linh Ngọc', 802, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:05.876084', 3, 11);
INSERT INTO `sync_articles` VALUES (301, '80989216', 'Bắc Ninh: Chỉ số sản xuất công nghiệp tiếp tục duy trì đà tăng trưởng cao', 'Bắc Ninh: Chỉ số sản xuất công nghiệp tiếp tục duy trì đà tăng trưởng cao', '/documents/37632/75763001/IMG_5642.jpg/c10a5d67-cda6-5dbb-fb77-d741b76568e5?t=1765163859500', '<p>(BNP) - Tháng 11/2025, chỉ số sản xuất công nghiệp (IIP) của tỉnh Bắc Ninh tiếp tục duy trì đà tăng trưởng cao (20,94%) so với tháng cùng kỳ năm trước.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/75763001/IMG_5642.jpg/c10a5d67-cda6-5dbb-fb77-d741b76568e5?t=1765163859500\" /></span></span><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tháng 11/2025, chỉ số sản xuất công nghiệp (IIP) của tỉnh Bắc Ninh tiếp tục duy trì đà tăng trưởng cao (20,94%).</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, ngành khai khoáng ước giảm 6,78%; ngành công nghiệp chế biến, chế tạo ước tăng 21,13%; ngành sản xuất và phân phối điện, khí đốt, nước nóng, hơi nước và điều hòa không khí ước giảm 3,22%; ngành cung cấp nước, hoạt động quản lý và xử lý rác thải, nước thải ước tăng cao 30,4%.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyên nhân chỉ số IIP tháng 11 tăng so với tháng cùng kỳ là do Bắc Ninh hiện vẫn đang là điểm đến hấp dẫn cho các nhà đầu tư trong và ngoài nước, các dự án đầu tư trực tiếp nước ngoài (FDI) liên tục tăng, nhất là trong ngành công nghiệp chế biến, chế tạo tại các khu công nghiệp trọng điểm đã đóng góp đáng kể vào tăng trưởng chung. Bên cạnh đó, các tập đoàn lớn về sản xuất linh kiện điện tử tiếp tục duy trì sản xuất ổn định, một số mở rộng dây chuyền, củng cố vị thế của ngành sản xuất này cũng như của tỉnh trong chuỗi cung ứng toàn cầu.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tính chung 11 tháng, chỉ số IIP ước tăng 16,79%. Trong đó, ngành công nghiệp chế biến chế tạo là ngành chiếm tỷ trọng lớn tiếp tục giữ vững vai trò quan trọng với mức tăng 16,94%; khai khoáng giảm 8,21%; sản xuất và phân phối điện, khí đốt, nước nóng, hơi nước và điều hòa không khí tăng 1,63%; cung cấp nước, hoạt động quản lý và xử lý rác thải, nước thải tăng 21,54%.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chỉ số sản xuất công nghiệp của tỉnh tăng cao phản ánh mức tăng trưởng kinh tế ổn định, cho thấy việc bám sát tình hình sản xuất kinh doanh, nắm bắt những khó khăn của doanh nghiệp, kịp thời đưa ra các giải pháp chỉ đạo, điều hành của chính quyền tỉnh, đã tháo gỡ được vướng mắc và thúc đẩy sản xuất trên địa bàn phát triển./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '2025-12-06 03:16:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-chi-so-san-xuat-cong-nghiep-tiep-tuc-duy-tri-a-tang-truong-cao-80989216', '', 'BNP', 6, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:05.908057', 3, 11);
INSERT INTO `sync_articles` VALUES (302, '72235601', 'Hội nghị Hải quan - Doanh nghiệp năm 2025, đánh dấu kim ngạch xuất nhập khẩu vượt mốc...', 'Hội nghị Hải quan - Doanh nghiệp năm 2025, đánh dấu kim ngạch xuất nhập khẩu vượt mốc 200 tỷ USD của Chi cục Hải quan khu vực V', '/documents/37632/30456144/4-5.png/adf4b837-8779-fe7c-0555-e60e36fcb6e7?t=1764841791116', '<p>(BNP) - Chiều 04/12, tại Trung tâm Văn hóa Kinh Bắc (phường Vũ Ninh, tỉnh Bắc Ninh), Chi cục Hải quan khu vực V tổ chức hội nghị Hải quan - Doanh nghiệp năm 2025, đánh dấu kim ngạch xuất nhập khẩu vượt mốc 200 tỷ USD và vinh danh các doanh nghiệp tiêu biểu trên địa bàn quản lý (2 tỉnh Bắc Ninh,...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/4-5.png/adf4b837-8779-fe7c-0555-e60e36fcb6e7?t=1764841791116\" style=\"height: 570px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo chúc mừng 20 doanh nghiệp tiêu biểu được vinh danh tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự hội nghị có các đồng chí: Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Bắc Ninh; Nguyễn Thanh Bình, Phó Bí thư Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh Thái Nguyên; Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh Bắc Ninh; Trần Đức Hùng, Phó Cục trưởng Cục Hải quan; đại diện lãnh đạo một số sở, ban, ngành của tỉnh cùng hơn 120 doanh nghiệp đại diện cho cộng đồng doanh nghiệp của 02 tỉnh Bắc Ninh, Thái Nguyên. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/4-4.png/db442c7e-e41e-3c18-f011-523764b8e344?t=1764841481292\" style=\"height: 613px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Từ trái qua: Phó Chủ tịch UBND tỉnh Bắc Ninh Ngô Tân Phượng; Chủ tịch UBND tỉnh Bắc Ninh Phạm Hoàng Sơn; Phó Chủ tịch Thường trực UBND tỉnh Thái Nguyên Nguyễn Thanh Bình;&nbsp;Phó Cục trưởng Cục Hải quan Trần Đức Hùng dự hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thời gian qua, kim ngạch xuất nhập khẩu và số thu ngân sách Nhà nước của Chi cục Hải quan Khu vực V luôn ở mức tăng trưởng cao, khẳng định vị thế là đầu mối quan trọng trong quản lý hoạt động xuất nhập khẩu của các tỉnh công nghiệp trọng điểm phía Bắc. Đặc biệt, kim ngạch xuất nhập khẩu 11 tháng năm 2025 trên địa bàn quản lý đạt 208,118 tỷ USD, đạt 126,42% so với năm 2024. Đây là lần đầu tiên kim ngạch xuất nhập khẩu trên địa bàn quản lý của Chi cục vượt mốc 200 tỷ USD. Qua đó, thể hiện sự lớn mạnh và đóng góp nổi bật của doanh nghiệp trong địa bàn 2 tỉnh cũng như vai trò trung tâm sản xuất - xuất khẩu của Bắc Ninh, Thái Nguyên và các tỉnh lân cận trong chuỗi cung ứng toàn cầu.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/4-3+%281%29.png/e9963035-38cb-7438-789f-273dea9aed9e?t=1764841427516\" style=\"height: 661px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Cục trưởng Cục Hải quan Trần Đức Hùng chỉ đạo một số nhiệm vụ trọng tâm.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chỉ đạo một số nhiệm vụ trọng tâm của ngành tại hội nghị, Phó Cục trưởng Cục Hải quan Trần Đức Hùng đề nghị tập thể lãnh đạo, cán bộ, công chức, người lao động Chi cục Hải quan khu vục V tiếp tục thực hiện các giải pháp cải tiến, sáng kiến để thực hiện các thủ tục hành chính nhanh nhất cho doanh nghiệp; tiếp tục giảm thời gian thông quan hàng hóa; giảm chi phí hành chính. Đồng thời, hỗ trợ kiến thức pháp luật để nâng cao tính tuân thủ cho cộng đồng doanh nghiệp, tạo môi trường thân thiện, động lực ủng hộ doanh nghiệp phát triển bền vững; nghiêm cấm mọi hành vi nhũng nhiễu, cửa quyền làm ảnh hưởng đến uy tín của đơn vị và ngành Hải quan.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Cục trưởng Cục Hải quan cũng mong muốn UBND 2 tỉnh Bắc Ninh và Thái Nguyên tiếp tục quan tâm, tạo điều kiện, hỗ trợ hơn nữa để Chi cục Hải quan khu vực V tiếp tục hoạt động hiệu quả, đạt được nhiều kết quả tích cực trong thời gian tới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/4-2.png/b7604508-f23e-4609-c675-101559b5eb8c?t=1764841148582\" style=\"height: 665px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Ngô Tân Phượng phát biểu chúc mừng tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phát biểu chúc mừng những kết quả Chi cục Hải quan khu vực V đạt được, thay mặt lãnh đạo tỉnh Bắc Ninh, Phó Chủ tịch UBND tỉnh Ngô Tân Phượng nhấn mạnh, con số 200 tỷ USD không chỉ thể hiện quy mô thương mại lớn mạnh mà còn thể hiện sự chuyển mình mạnh mẽ về chất của nền kinh tế, khẳng định sức bền, khả năng thích ứng và tinh thần đổi mới của cộng đồng doanh nghiệp. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh khẳng định, với quan điểm nhất quán là “thành công của doanh nghiệp là thành công của tỉnh, khó khăn của doanh nghiệp cũng là khó khăn trong công tác điều hành của tỉnh”, lãnh đạo tỉnh Bắc Ninh luôn cam kết đẩy mạnh cải cách hành chính, cải thiện mạnh mẽ môi trường đầu tư kinh doanh; minh bạch, công khai, thuận lợi trong tiếp cận thông tin và thủ tục hành chính. Đồng thời, chủ động tiếp nhận, lắng nghe và xử lý khó khăn, vướng mắc; hỗ trợ tối đa cho doanh nghiệp; đồng hành với nhà đầu tư trong mọi giai đoạn trên tinh thần bảo vệ quyền và lợi ích chính đáng theo quy định pháp luật, góp phần đưa Bắc Ninh tiến nhanh, tiến vững chắc trong lộ trình xây dựng tỉnh trở thành thành phố trực thuộc Trung ương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Khái quát tình hình phát triển kinh tế - xã hội của tỉnh thời gian qua, Phó Chủ tịch UBND tỉnh nhấn mạnh tổng kim ngạch xuất nhập khẩu cả năm của tỉnh Bắc Ninh sau sáp nhập ước đạt 182 tỷ USD, tăng gần 70% so với năm 2021. Toàn tỉnh ước thu hút được 17,6 tỷ USD vốn đầu tư trong nước và vốn đầu tư trực tiếp nước ngoài, vượt kế hoạch đề ra, tiếp tục là một trong 02 địa phương có kim ngạch xuất nhập khẩu đứng đầu và chiếm 1/4 tổng kim ngạch xuất nhập khẩu cả nước. Những thành tựu trên có được nhờ sự nỗ lực vượt bậc của cộng đồng doanh nghiệp và sự đóng góp quan trọng của lực lượng Hải quan trên địa bàn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trong thời gian tới, để tiếp tục đưa Bắc Ninh dẫn đầu cả nước về thu hút đầu tư nước ngoài, khẳng định vai trò đặc biệt, định hình vị thế trong chiến lược phát triển vùng, quốc gia và khu vực, Phó Chủ tịch UBND tỉnh đề nghị Chi cục Hải quan khu vực V tiếp tục giữ vững truyền thống kỷ cương - chuyên nghiệp - hiện đại; đẩy mạnh ứng dụng công nghệ, chuyển đổi số theo định hướng Hải quan thông minh, tạo thuận lợi tối đa cho doanh nghiệp thông quan và tiếp cận dịch vụ hải quan.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh cũng mong muốn cộng đồng doanh nghiệp tiếp tục tin tưởng, đồng hành cùng tỉnh Bắc Ninh; phát huy tinh thần đổi mới, sáng tạo, nâng cao năng lực cạnh tranh, nắm bắt thời cơ mới để mở rộng đầu tư, sản xuất kinh doanh bền vững trên địa bàn.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/4-1.png/4892620f-4fa4-4076-6d12-6fb7b696fc06?t=1764840897152\" style=\"height: 570px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh, Cục Hải quan, Chi cục Hải quan khu vực V và doanh nghiệp tiêu biểu thực hiện nghi thức đánh dấu&nbsp;&nbsp;kim ngạch xuất nhập khẩu vượt mốc 200 tỷ USD.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhân dịp này, Chi cục Hải quan khu vực V vinh danh và trao kỷ niệm chương ghi nhận top 10 doanh nghiệp có kim ngạch xuất nhập khẩu lớn và top 10 doanh nghiệp có đóng góp số thu lớn cho ngân sách Nhà nước trên địa bàn 2 tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cũng trong khuôn khổ hội nghị, lãnh đạo Chi cục Hải quan khu vực V trực tiếp trao đổi, giải đáp, hướng dẫn xử lý vướng mắc cho các doanh nghiệp khi thực hiện thủ tục hải quan qua địa bàn; chỉ ra các sai sót, vi phạm của doanh nghiệp thường gặp phải trong quá trình làm thủ tục hải quan và đưa ra một số cảnh báo. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, giới thiệu trực tiếp đến cộng đồng doanh nghiệp về dự kiến Mô hình thông quan tập trung của Hải quan. Đây là mô hình đánh dấu bước chuyển trong quản lý hải quan từ phân tán sang tập trung, điện tử hóa các quy trình nghiệp vụ để nâng cao hiệu quả kiểm soát, tạo thuận lợi cho thương mại, góp phần thực hiện mục tiêu điện tử hóa toàn bộ quy trình tiếp nhận, xử lý hồ sơ, chuyển đổi sang thủ tục phi giấy tờ để giảm thời gian, chi phí cho doanh nghiệp. Dự kiến, mô hình sẽ triển khai thí điểm tại Chi cục Hải quan khu vực III (Hải Phòng) và Chi cục Hải quan khu vực V (Bắc Ninh) từ ngày 01/3/2026./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-12-04 09:33:00', 'https://bacninh.gov.vn/news/-/details/37632/hoi-nghi-hai-quan-doanh-nghiep-nam-2025-anh-dau-kim-ngach-xuat-nhap-khau-vuot-moc-200-ty-usd-cua-chi-cuc-hai-quan-khu-vuc-v-72235601', '', 'Linh Ngọc', 369, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:05.937164', 3, 11);
INSERT INTO `sync_articles` VALUES (303, '70235802', 'Đối tượng thuê nhà ở công vụ tại các địa phương thuộc diện sắp xếp đơn vị hành chính...', 'Đối tượng thuê nhà ở công vụ tại các địa phương thuộc diện sắp xếp đơn vị hành chính cấp tỉnh', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/3/edit-unnamed-17647477050552007130042.png', '<p>(BNP) - Phó Thủ tướng Trần Hồng Hà ký Quyết định số 45/2025/QĐ-TTg của Thủ tướng Chính phủ quy định đối tượng thuê nhà ở công vụ tại các địa phương thuộc diện sắp xếp đơn vị hành chính cấp tỉnh.</p>', '<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Đối tượng thuê nhà ở công vụ gồm:</b></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đối tượng thuê nhà ở công vụ thuộc điểm g khoản 1 Điều 45 Luật Nhà ở năm 2023 là cán bộ, công chức, viên chức do phải di chuyển chỗ làm đến trung tâm chính trị - hành chính mới tại các địa phương thuộc diện sắp xếp đơn vị hành chính cấp tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đối tượng quy định ở trên phải thuộc trường hợp chưa có nhà ở thuộc sở hữu của mình hoặc có nhà ở (bao gồm cả nhà ở xã hội) mà có khoảng cách theo chiều dài giao thông đường bộ ngắn nhất từ nhà ở thuộc sở hữu của mình đến địa điểm làm việc (gồm: trụ sở làm việc chính, chi nhánh hoặc văn phòng đại diện của cơ quan, tổ chức) từ 10 km trở lên tại khu vực miền núi, vùng sâu, vùng xa có điều kiện kinh tế khó khăn, khu vực biên giới, hải đảo và từ 30 km trở lên tại khu vực còn lại.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Về tiêu chuẩn diện tích và trang thiết bị nội thất nhà ở công vụ</b> </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quyết định quy định Trưởng phòng, Phó Trưởng phòng thuộc Sở và tương đương, công chức, viên chức tại các địa phương thuộc diện sắp xếp đơn vị hành chính cấp tỉnh được bố trí cho thuê một trong hai loại hình nhà ở công vụ, bao gồm:</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Căn hộ chung cư có diện tích sử dụng từ 45 m2 đến dưới 60 m2 được thiết kế không gian ở khép kín, có một hay nhiều không gian chức năng khác nhau như: Phòng khách, các phòng ngủ, phòng ăn, bếp, khu vệ sinh, ban công hoặc lô gia;</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Căn nhà có diện tích sử dụng từ 48 m2 đến dưới 60 m2 được xây dựng theo kiểu nhà 01 tầng có nhiều căn nhà sát nhau, từng căn nhà có công trình phụ khép kín.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Định mức kinh phí tối đa trang thiết bị nội thất cho nhà ở công vụ nêu trên là 120 triệu đồng.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ Xây dựng có trách nhiệm hướng dẫn, kiểm tra và đôn đốc các địa phương trên cả nước triển khai thực hiện Quyết định này.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND các tỉnh, thành phố trực thuộc Trung ương có trách nhiệm bố trí vốn từ ngân sách địa phương để đầu tư xây dựng, cải tạo, sửa chữa, mua trang thiết bị nội thất nhà ở công vụ theo quy định; chỉ đạo việc phát triển, quản lý, bố trí cho thuê nhà ở công vụ, chuyển đổi công năng quỹ nhà dôi dư sang nhà ở công vụ trên địa bàn theo quy định của pháp luật về nhà ở và phù hợp với điều kiện thực tế của địa phương.</span></span></span></p>', '2025-12-04 02:37:00', 'https://bacninh.gov.vn/news/-/details/37632/-oi-tuong-thue-nha-o-cong-vu-tai-cac-ia-phuong-thuoc-dien-sap-xep-on-vi-hanh-chinh-cap-tinh-70235802', '', 'BNP', 421, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:05.964771', 3, 11);
INSERT INTO `sync_articles` VALUES (304, '64964703', 'Bắc Ninh công bố số liệu thu nhập bình quân và giá trị tổng sản phẩm trên địa bàn các...', 'Bắc Ninh công bố số liệu thu nhập bình quân và giá trị tổng sản phẩm trên địa bàn các xã, phường năm 2025', '/documents/37632/41409701/IMG_1984.jpg/a1496db3-30ee-7c9d-e4ab-3044ca860110?t=1764749459521', '<p>(BNP) - UBND tỉnh Bắc Ninh vừa có thông báo số liệu thu nhập bình quân đầu người và giá trị tổng sản phẩm trên địa bàn các xã/phường năm 2025.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/41409701/z4759227797462_0eafd0a2192e2eca5cf717694a40b4d8.jpg/4cc255b0-3e97-8782-36d6-8382666ac42f?t=1764750532684\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, ước tính thu nhập bình quân đầu người của các xã, phường của tỉnh hơn 71 triệu đồng/người/năm. Giá trị tổng sản phẩm trên địa bàn các xã, phường (theo giá so sánh) ước tính hơn 2.267 nghìn tỷ đồng. Giá trị tổng sản phẩm trên địa bàn các xã, phường (theo giá hiện hành) ước tính hơn 2.705 nghìn tỷ đồng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quyết định nêu rõ, Thống kê tỉnh, các sở, ngành thuộc UBND tỉnh và UBND xã, phường khai thác và sử dụng các kết quả nêu trên phục vụ công tác quản lý nhà nước trên địa bàn tỉnh./.</span></span></span></p>', '2025-12-03 08:09:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-cong-bo-so-lieu-thu-nhap-binh-quan-va-gia-tri-tong-san-pham-tren-ia-ban-cac-xa-phuong-nam-2025-64964703', '', 'BNP', 1107, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:05.994878', 3, 11);
INSERT INTO `sync_articles` VALUES (305, '57945001', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải: Đẩy nhanh tiến độ cập nhật dữ liệu đất đai vào...', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải: Đẩy nhanh tiến độ cập nhật dữ liệu đất đai vào cơ sở dữ liệu quốc gia', '/documents/37632/41409701/5.jpg/a027d625-5164-fdc3-3820-f4bcde7a718b?t=1764657508889', '<p>(BNP) - Trưa 02/12, đồng chí Đào Quang Khải, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh chủ trì Hội nghị trực tuyến với các địa phương về triển khai tiến độ Chiến dịch “làm giàu, làm sạch” cơ sở dữ liệu (CSDL) đất đai trên địa bàn tỉnh Bắc Ninh. Dự hội nghị tại điểm cầu UBND tỉnh có...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/a3.jpg/cb7b0f7c-f641-1aa3-f9a7-5fad9f702d92?t=1764657193394\" style=\"height: 482px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh hội nghị tại điểm cầu UBND tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Theo báo cáo của Sở Nông nghiệp và Môi trường, đến nay, tỉnh đã tổng hợp 537.367 trường hợp cần làm sạch gửi Trung tâm Dữ liệu quốc gia về dân cư (C06, Bộ Công an), thực hiện đối soát làm sạch 513.422 trường hợp, đạt tỷ lệ 95,5% khối lượng công việc. Các trường hợp còn lại chưa làm sạch do không thể rà soát với Cơ sở dữ liệu quốc gia và do sai lệch thông tin. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Toàn tỉnh rà soát, phân loại được 684.245 thửa đất đảm bảo tiêu chí “đúng - đủ - sạch - sống”, tăng 221.076 thửa, tương ứng 47,7% (so với thời điểm kiểm điểm ngày 21/11). Việc làm sạch thông tin giúp loại bỏ sai lệch, đồng thời tạo cơ sở để thực hiện các thủ tục hành chính về đất đai một cách nhanh, chính xác. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/4.jpg/12c79b31-3b10-22fe-9e0c-29d3df438ea0?t=1764657325445\" style=\"height: 586px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Đại diện Công an tỉnh phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Trong công tác thu thập hồ sơ phục vụ làm giàu dữ liệu, các địa phương thu thập 174.150 thửa, đạt 126,5% khối lượng có thể thu thập; cập nhật thành công vào cơ sở dữ liệu đất đai quốc gia tỷ lệ 84,5%; nhiều xã, phường đạt tỷ lệ cập nhật 100%; tuy nhiên vẫn còn một số xã, phường có chất lượng nhập biểu dữ liệu chưa cao gồm: Biên Sơn 19,3%, Tân Tiến 18,4%, Hoàng Vân 15,9%, Xuân Cẩm 13,4%, Vân Hà 6,7%, Hiệp Hòa 5,3%, Hợp Thịnh 4,7%, Tự Lạn 1,0%.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/a2+%281%29.jpg/b15dbfaa-2512-af2c-764c-45368e0c353e?t=1764657393934\" style=\"height: 577px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Lãnh đạo Văn phòng Đăng ký đất đạo Bắc Ninh số 1 phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại hội nghị, các đại biểu thảo luận, đánh giá tiến độ thu thập, chuẩn hóa, số hóa, đồng bộ dữ liệu đất đai của toàn tỉnh; đồng thời phân tích nguyên nhân dẫn đến thu thập và nhập biểu dữ liệu đất đai tại một số địa phương đạt tỉ lệ thấp. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Theo đó, nguyên nhân chính là do quá trình nhập Biểu dữ liệu bị thiếu hoặc sai thông tin, sai cấu trúc; nhiều số liệu bị trùng do đã có trong CSDL, dẫn đến tỷ lệ được cập nhật thành công vào CSDL quốc gia còn thấp so với khối lượng đã thu thập. Trang thiết bị còn thiếu đồng bộ, hệ thống CSDL quốc gia còn chậm phản hồi trong thực hiện việc tổng hợp số liệu báo; chưa có công cụ chuyển đổi đối với dữ liệu được thu thập; dữ liệu được chuyển đổi từ hệ thống phần mềm CSDL quốc gia, cùng với việc chuyển dữ liệu 3 cấp sang 2 cấp chưa được kiểm tra, xác thực theo quy định…</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/5.jpg/a027d625-5164-fdc3-3820-f4bcde7a718b?t=1764657508889\" style=\"height: 558px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Đào Quang Khải&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">kết luận hội nghị.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Kết luận hội nghị, Phó Chủ tịch UBND tỉnh Đào Quang Khải biểu dương những xã, phường có khối lượng và có tỷ lệ cập nhật thành công CSDL quốc gia lớn; đồng thời, nhấn mạnh, CSDL đất đai liên quan trực tiếp đến quyền lợi của mỗi người dân, doanh nghiệp; việc xây dựng, hoàn thiện CSDL đất đai “đúng - đủ - sạch - sống” là yêu cầu bắt buộc, là một trong những nhiệm vụ trọng tâm nhằm tạo cơ sở thống nhất, dùng chung, góp phần thực hiện hiệu quả chuyển đổi số trong lĩnh vực tài nguyên và môi trường.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Để Chiến dịch <span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">hoàn thành&nbsp;</span></span></span>đảm bảo chất lượng, hiệu quả, đúng thời gian, Phó Chủ tịch UBND tỉnh yêu cầu, Sở Nông nghiệp và Môi trường tiếp tục chỉ đạo Văn phòng Đăng ký đất đai tích cực hướng dẫn các địa phương có tỷ lệ cập nhật thấp khẩn trương hoàn thiện các số liệu để đồng bộ dữ liệu&nbsp;lên CSDL quốc gia. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phó Chủ tịch UBND tỉnh cũng lưu ý, đây là nhiệm vụ trọng tâm của các địa phương, do đó đối với các địa phương bị chậm tiến độ, tiếp tục phối hợp với các sở, ngành, đơn vị liên quan kịp thời tháo gỡ khó khăn, vướng mắc phát sinh, cập nhật dữ liệu lên CSDL quốc gia; yêu cầu chậm nhất đến ngày 10/12/2025, các địa phương phải hoàn thành 100% tiến độ công việc giao. Nếu không đảm bảo tiến độ, lãnh đạo địa phương đó phải chịu trách nhiệm về kết quả đánh năng lực lãnh đạo, quản lý và điều kiện đánh giá công tác Đảng, công tác chính quyền tại các địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Sở Nông nghiệp và Môi trường, Công an tỉnh cử cán bộ, chia nhóm xuống cơ sở trực tiếp phối hợp, hướng dẫn các địa phương chậm tiến độ, có chất lượng nhập biểu dữ liệu chưa cao rà soát, cập nhật thông tin,&nbsp;đảm bảo đúng tiến độ của Chiến dịch “làm giàu, làm sạch” cơ sở dữ liệu đất đai trên địa bàn tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-12-02 06:30:00', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-ao-quang-khai-ay-nhanh-tien-o-cap-nhat-du-lieu-at-ai-vao-co-so-du-lieu-quoc-gia-57945001', '', 'Nguyễn Miền', 943, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:06.023197', 3, 11);
INSERT INTO `sync_articles` VALUES (306, '57880149', 'Thống nhất nội dung dự thảo Nghị quyết Quy định Bảng giá các loại đất trên địa bàn...', 'Thống nhất nội dung dự thảo Nghị quyết Quy định Bảng giá các loại đất trên địa bàn tỉnh Bắc Ninh', '/documents/37632/41409701/a1.jpg/72749346-4fd0-cb38-a040-7bfd2c51daec?t=1764656331121', '<p>(BNP) - Sáng 02/12, đồng chí Đào Quang Khải, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh chủ trì họp Hội đồng thẩm định Bảng giá đất nhằm xem xét, thống nhất nội dung dự thảo Nghị quyết quy định tiêu chí xác định vị trí từng loại đất và quyết định Bảng giá đất trên địa bàn tỉnh Bắc...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/a1.jpg/72749346-4fd0-cb38-a040-7bfd2c51daec?t=1764656331121\" style=\"height: 525px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tại hội nghị, đại diện lãnh đạo Sở Nông nghiệp và Môi trường cho biết, dự thảo Nghị quyết của HĐND “Quy định tiêu chí cụ thể để xác định vị trí đối với từng loại đất, số lượng vị trí đất trong bảng giá đất và quyết định bảng giá các loại đất trên địa bàn tỉnh Bắc Ninh” gồm 3 Chương, 6 Điều và 10 Phụ lục Bảng giá kèm theo. Dự thảo Nghị quyết được Sở Nông nghiệp và Môi trường tổ chức lấy ý kiến rộng rãi các sở, ngành, cơ quan, đơn vị, tổ chức chính trị - xã hội và Nhân dân. &nbsp;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Dự thảo Nghị quyết Quy định cụ thể Bảng giá các loại đất: Trồng cây hàng năm,&nbsp; trồng cây lâu năm, đất rừng sản xuất, đất nuôi trồng thủy sản, đất ở tại nông thôn, đất ở đô thị, đất tại các trục đường giao thông nông thôn, đất khu công nghiệp, cụm công nghiệp, đất thương mại, dịch vụ tại đô thị, đất phi nông nghiệp…</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/3.jpg/a7a76c59-2308-caf0-0cad-190b889671fb?t=1764656423193\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\">Lãnh đạo Sở Nông nghiệp và Môi trường phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Theo dự thảo Nghị quyết, Bảng giá đất lần này được xây dựng chi tiết với tối đa 4 vị trí đối với đất đô thị và các trục giao thông chính; đất nông thôn chia tối đa 3 khu vực và 3 vị trí trong mỗi khu. Đối với từng thửa đất, vị trí được xác định dựa trên điều kiện hạ tầng, khả năng sinh lợi, khoảng cách tới các trục giao thông, trung tâm kinh tế - thương mại.</span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/2.jpg/e69b6cb0-698e-be69-1177-0a5a7e1021f7?t=1764656694036\" style=\"height: 566px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Lãnh đạo Sở Tài chính phát biểu tại hội nghị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"></span></span></span>Thảo luận tại hội nghị, đại diện lãnh đạo các sở, ngành tập trung góp ý vào phương pháp xây dựng bảng giá, sự phù hợp với thực tiễn phát triển kinh tế - xã hội, tính đồng bộ giữa các khu vực và khả năng áp dụng trong công tác bồi thường, hỗ trợ tái định cư. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các đại biểu cũng cho rằng dự thảo đã bám sát quy định pháp luật và tình hình địa phương, tuy nhiên đơn vị chủ trì soạn thảo cần tiếp tục rà soát kỹ hơn, cân nhắc thêm về phương án xây dựng giá đất thương mại, giá đất dịch vụ, giá đất vùng giáp ranh, giá đất một số tuyến đường mới, khu đô thị mới và các khu vực hay có biến động về giá đất… </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/41409701/a4.jpg/b5ad85da-9a0c-9b1b-279b-ed2140ad1b56?t=1764656518119\" style=\"height: 578px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Đào Quang Khải&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">kết luận hội nghị.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Kết luận hội nghị, Phó Chủ tịch UBND tỉnh Đào Quang Khải nhấn mạnh tầm quan trọng việc xây dựng Bảng giá đất mới đối với sự phát triển kinh tế - xã hội của tỉnh. Xây dựng Bảng giá đất mới trên địa bàn tỉnh sẽ có sức lan tỏa lớn trong bối cảnh tỉnh thực hiện sắp xếp đơn vị hành chính, mở rộng đô thị, đầu tư hạ tầng và phát triển nhiều khu công nghiệp, khu tái định cư, dự án đấu giá quyền sử dụng đất.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phó Chủ tịch UBND tỉnh biểu dương tinh thần làm việc của đơn vị chủ trì là Sở Nông nghiệp và Môi trường và các thành viên hội đồng thẩm định Bảng giá đất tỉnh đã nỗ lực, quyết tâm hoàn thiện nội dung Bảng giá đất đúng thời gian quy định, đúng cơ sở pháp lý, cơ sở thực tiễn, phù hợp với Luật Đất đai và các quy định khác của Nhà nước.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phó Chủ tịch UBND tỉnh cũng cơ bản thống nhất các nội dung tại dự thảo Nghị quyết; đồng thời cho rằng, đối với một số địa phương đặc thù, việc xây dựng giá đất nông nghiệp phải đảm bảo tiệm cận với giá định cư và có lợi cho Nhân dân. Cùng đó, Bảng giá nông thôn cần thống nhất quan điểm chia thành 3 khu vực, nhằm góp phần phục cho việc đánh giá hạ tầng kinh tế khu vực nông thôn, đảm bảo lợi ích hài hòa giữa người dân và doanh nghiệp, đẩy mạnh thu hút đầu tư dự án khu vực nông thôn. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Trên cơ sở ý kiến đóng góp của các đại biểu, kế thừa nội dung Bảng Giá đất cũ, Phó Chủ tịch UBND tỉnh đề nghị Sở Nông nghiệp và Môi trường hoàn thiện tờ trình để báo cáo Ban Thường vụ Đảng ủy UBND tỉnh xem xét, hoàn thiện hồ sơ, sớm trình HĐND tỉnh xem xét, thẩm định thông qua tại kỳ họp HĐND sắp tới và được áp dụng từ ngày 01/01/2026 trên địa bàn tỉnh Bắc Ninh. </span></span></span></p>', '2025-12-02 06:13:00', 'https://bacninh.gov.vn/news/-/details/37632/thong-nhat-noi-dung-du-thao-nghi-quyet-quy-inh-bang-gia-cac-loai-at-tren-ia-ban-tinh-bac-ninh-57880149', '', 'Nguyễn Miền', 2369, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:06.049940', 3, 11);
INSERT INTO `sync_articles` VALUES (307, '57585003', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn làm việc với Tập đoàn Yangjie (Trung Quốc) về mở...', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn làm việc với Tập đoàn Yangjie (Trung Quốc) về mở rộng đầu tư của Công ty MCC Việt Nam tại Khu công nghiệp Yên Phong II-C', '/documents/37632/41409701/2-3.png/b00a3f73-2a8f-7b76-5b71-c24d8fbd9ac3?t=1764651731511', '<p>(BNP) - Sáng 02/12, đồng chí Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh tiếp và làm việc với ông Chen Rui Sheng, CEO Tập đoàn Yangjie (Trung Quốc) về việc hỗ trợ Công ty TNHH Micro Commercial Components (MCC) Việt Nam triển khai mở rộng hoạt động đầu tư tại Khu công nghiệp (KCN) Yên...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/41409701/2-3.png/b00a3f73-2a8f-7b76-5b71-c24d8fbd9ac3?t=1764651731511\" style=\"height: 650px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Phạm Hoàng Sơn tặng ông Chen Rui Sheng&nbsp;tranh dân gian Đông Hồ.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại buổi tiếp, bày tỏ vui mừng khi được thăm, làm việc tại tỉnh Bắc Ninh, ông Chen Rui Sheng trân trọng cảm ơn sự quan tâm, hỗ trợ, tạo điều kiện của tỉnh trong suốt thời gian qua đối với Công ty MCC Việt Nam. Đồng thời, giới thiệu khái quát về Dự án nhà máy thiết bị bán dẫn Micro Components của Công ty MCC Việt Nam tại tỉnh Bắc Ninh do Tập đoàn Yangzhou Yangjie Electronic Technology Co., Ltd đầu tư. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án được cấp Giấy chứng nhận đầu tư vào tháng 7/2023 tại KCN Yên Phong II-C, tổng vốn đầu tư đăng ký 90 triệu USD, đã đi vào hoạt động từ quý I/2025. Kim ngạch xuất khẩu năm 2025 là hơn 27 triệu USD, thị trường tiêu thụ chính ở các khu vực Châu Âu, Châu Mỹ, Nhật Bản, Hàn Quốc, Trung Quốc. Khách hàng toàn cầu chính như: Tesla, Hyundai, Toyota, GM, Samsung, Philips, LG, JA Solar…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/41409701/2-2.png/adb71392-20a5-be36-476d-a989a079eebf?t=1764651877897\" style=\"height: 620px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo chụp ảnh lưu niệm với đoàn công tác.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ông Chen Rui Sheng cũng cho biết Tập đoàn đang nghiên cứu, triển khai dự án mới tại Bắc Ninh là sản xuất wafer GPP phục vụ nhà máy MCC tại Việt Nam và cung cấp wafer bán dẫn cho thị trường toàn cầu với quy mô sản xuất 2.400.000 sản phẩm wafer/năm. Tổng vốn đầu tư dự kiến tăng thêm từ 30 - 40 triệu USD.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/41409701/2-1.png/c2721c4d-5e22-32e1-a77a-8df03fcf9583?t=1764652002518\" style=\"height: 608px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Phạm Hoàng Sơn trao đổi với ông Chen Rui Sheng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ông Chen Rui Sheng mong muốn tỉnh Bắc Ninh hướng dẫn cụ thể cơ quan đầu mối quản lý hóa chất cấp tỉnh do đặc thù công nghệ của dự án wafer có sử dụng một số loại hóa chất chuyên dụng; hướng dẫn thủ tục, trình tự hồ sơ pháp lý xây dựng công trình phụ trợ; hỗ trợ cung cấp nguồn điện ổn định và triển khai nhanh các thủ tục đặc thù về thẩm duyệt phòng cháy chữa cháy, hồ sơ môi trường…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/41409701/2-4.png/c2cf85c9-e481-13ba-2f17-a45d81d4efed?t=1764652036852\" style=\"height: 600px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh buổi tiếp và làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trên cơ sở ý kiến trao đổi của lãnh đạo các sở, ban, ngành, Chủ tịch UBND tỉnh Phạm Hoàng Sơn hoan nghênh ông Chen Rui Sheng, CEO Tập đoàn Yangjie đến làm việc tại tỉnh cũng như Công ty MCC Việt Nam mở rộng đầu tư dự án tại Bắc Ninh. Đồng thời, giới thiệu khái quát tình hình phát triển kinh tế - xã hội của tỉnh với nhiều chỉ tiêu trong nhóm dẫn đầu cả nước. Đặc biệt, tỉnh định hướng đưa bán dẫn trở thành một trong những trụ cột phát triển công nghệ cao, từ đó, đưa Bắc Ninh trở thành trung tâm bán dẫn hàng đầu cả nước. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trực tiếp trao đổi về những đề xuất, kiến nghị của Công ty MCC Việt Nam, Chủ tịch UBND tỉnh khẳng định tỉnh Bắc Ninh cam kết sẽ hỗ trợ, tạo mọi điều kiện thuận lợi để các doanh nghiệp nói chung, Công ty MCC Việt Nam nói riêng hoạt động ổn định và phát triển bền vững trên địa bàn tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí giao Ban Quản lý các Khu công nghiệp tỉnh chủ trì, phối hợp, hỗ trợ, giúp đỡ Công ty về các thủ tục và đầu mối với các sở, ngành liên quan. Đồng thời, trực tiếp theo dõi và triển khai nhanh nhất với các thủ tục hành chính. “Tỉnh Bắc Ninh là một trong những địa phương đi đầu cả nước về thực hiện các thủ tục hành chính thông thoáng” - Chủ tịch UBND tỉnh nhấn mạnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đối với các nguyên liệu phục vụ sản xuất của dự án mới, Chủ tịch UBND tỉnh đề nghị với những loại hóa chất chuyên dụng, có giấy phép đặc biệt thuộc thẩm quyền của UBND tỉnh, yêu cầu chỉ đạo xem xét, thực hiện ngay. Còn lại những loại thuộc thẩm quyền của các bộ, ngành Trung ương, tỉnh sẽ chỉ đạo để thúc đẩy triển khai trong thời gian sớm nhất.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh cũng giao Công an tỉnh triển khai, hỗ trợ, giúp đỡ Công ty về công tác phòng cháy, chữa cháy. Công ty Điện lực Bắc Ninh đảm bảo nguồn điện ổn định cho hoạt động sản xuất, kinh doanh của các doanh nghiệp trên địa bàn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh tin tưởng với sự đồng hành, hỗ trợ của tỉnh; năng lực của nhà đầu tư, dự án mới của Công ty MCC Việt Nam trên địa bàn tỉnh sẽ thành công, góp phần thúc đẩy sự phát triển của tỉnh trong tương lai./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-12-02 05:01:00', 'https://bacninh.gov.vn/news/-/details/37632/chu-tich-ubnd-tinh-pham-hoang-son-lam-viec-voi-tap-oan-yangjie-trung-quoc-ve-mo-rong-au-tu-cua-cong-ty-mcc-viet-nam-tai-khu-cong-nghiep-yen-phong-ii-c-57585003', '', 'Linh Ngọc', 1011, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:06.076393', 3, 11);
INSERT INTO `sync_articles` VALUES (308, '56819003', 'Bắc Ninh: Phê duyệt dự án Đầu tư xây dựng mở rộng cầu chui Y Na', 'Bắc Ninh: Phê duyệt dự án Đầu tư xây dựng mở rộng cầu chui Y Na', '/documents/37632/30456116/2-1.png/eb23ac8e-8f3f-7f4d-da94-d04d37a967f3?t=1764639577845', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Ngô Tân Phượng vừa ký Quyết định số 1574/QĐ-UBND phê duyệt dự án Đầu tư xây dựng mở rộng cầu chui Y Na (đoạn qua đường sắt Hà Nội - Lạng Sơn).</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456116/2-1.png/eb23ac8e-8f3f-7f4d-da94-d04d37a967f3?t=1764639577845\" style=\"height: 584px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Khu vực cầu chui Y Na, phường Kinh Bắc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án Đầu tư xây dựng mở rộng cầu chui Y Na (đoạn qua đường sắt Hà Nội - Lạng Sơn) có địa điểm tại phường Kinh Bắc, tỉnh Bắc Ninh. Hướng tuyến theo đồ án quy hoạch phân khu đô thị số 15 (Thị Cầu - Vũ Ninh - Suối Hoa - Kinh Bắc - Tiền An - Vệ An - Ninh Xá - Đại Phúc - Võ Cường), thành phố Bắc Ninh được UBND tỉnh Bắc Ninh phê duyệt tại Quyết định số 369/QĐ-UBND ngày 23/7/2024.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ đầu tư dự án là Ban Quản lý dự án xây dựng Kinh Bắc. Đây là dự án nhóm B; công trình giao thông đô thị, cấp II; thời hạn sử dụng theo thiết kế của công trình chính là 50 - 100 năm.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án nhằm từng bước cụ thể hóa mục tiêu quy hoạch đô thị của tỉnh Bắc Ninh trong giai đoạn 2030 tầm nhìn đến năm 2050; góp phần nâng cấp, hoàn chỉnh mạng lưới giao thông, tạo diện mạo đô thị hiện đại, đồng bộ. Đồng thời, giải quyết vấn đề ngập cục bộ, đáp ứng nhu cầu giao thông, tạo động lực thúc đẩy phát triển kinh tế - xã hội của địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án đầu tư xây dựng cải tạo, mở rộng đoạn từ đường Nguyễn Đăng Đạo đến đường Âu Cơ (điểm đầu tuyến gần nút giao giữa đường Nguyễn Đăng Đạo với đường Nguyễn Gia Thiều, điểm cuối tuyến gần nút giao giữa đường Âu cơ với đường Hồ Ngọc Lân) với chiều dài khoảng 517,3m (tuyến đường chính) gồm: Chiều dài hầm và tường chắn 330m; đường dẫn hai đầu hầm dài khoảng 187,3m. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, xây dựng các đường song hành dọc hai bên hầm giao thông và tường chắn vuốt nối đường Ngô Gia Tự, đường Nguyễn Công Hãng; thay thế cầu đường sắt cũ bằng cầu đường sắt mới, sử dụng kết cấu vòm thép; xây mới hầm dưới cầu đường sắt và dưới đường Ngô Gia Tự có tĩnh không đảm bảo H = 4,75m với tổng chiều dài hầm khoảng 309m; xây dựng nâng cấp, mở rộng tuyến đường Nguyễn Công Hãng tại vị trí kết nối với đường Âu Cơ theo mặt cắt ngang quy hoạch; đầu tư xây dựng đồng bộ các hạng mục theo quy định để đáp ứng đường đô thị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tổng mức đầu tư xây dựng, giá trị các khoản mục chi phí trong tổng mức đầu tư xây dựng của dự án khoảng 356 tỷ đồng từ vốn ngân sách tỉnh, bố trí theo tiến độ thực hiện dự án. Thời gian thực hiện dự án từ năm 2025 - 2028./.</span></span></span></p>', '2025-12-02 01:38:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-phe-duyet-du-an-au-tu-xay-dung-mo-rong-cau-chui-y-na-56819003', '', 'Linh Ngọc', 2179, 'Kinh tế', 3, '', '38762', '{}', '2025-12-08 08:18:06.103752', 3, 11);
INSERT INTO `sync_articles` VALUES (309, '80602801', 'Sắc màu Lễ hội trái cây Bắc Ninh 2025', 'Sắc màu Lễ hội trái cây Bắc Ninh 2025', '/documents/37632/200628/Lehoitraicay+Dai+bieu+tinh+chup+anh+luu+niem+truoc+gian+hang+1.jpg/2fd4711a-cd18-9821-4ffd-ce43db16fcde?t=1765029497379', '<p>(BNP) - Tối 5/12, Lễ hội trái cây Bắc Ninh 2025 khai mạc rực rỡ, thu hút hàng nghìn người dân và du khách trong, ngoài tỉnh đổ về tham quan, mua sắm và thưởng thức những sản vật đặc trưng của địa phương.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Lehoitraicay+Dai+bieu+tinh+chup+anh+luu+niem+truoc+gian+hang+1.jpg/2fd4711a-cd18-9821-4ffd-ce43db16fcde?t=1765029497379\" style=\"height: 622px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đồng chí lãnh đạo tỉnh chụp ảnh lưu niệm tại gian trưng bày ấn tượng của phường Chũ.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay trong đêm khai mạc, nhiều đại biểu và du khách đã bày tỏ sự thích thú trước các tác phẩm nghệ thuật được tạo hình tinh xảo từ trái cây. Dưới bàn tay khéo léo của những người làm vườn, từng loại quả quen thuộc được ghép nối, phối màu hài hòa, tạo nên các mô hình độc đáo, đẹp mắt, mang lại dấu ấn riêng cho Lễ hội trái cây Bắc Ninh năm nay.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Lehoitraicay+Dai+bieu+tinh+tham+quan+gian+hang+3.jpg/d2092bda-5bdf-8251-a8f2-3e4cb43f405a?t=1765029542989\" style=\"height: 653px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu ấn tượng với trái cây địa phương.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lễ hội diễn ra từ ngày 05 - 10/12/2025 tại Quảng trường trung tâm phường Chũ, với gần 200 gian hàng của các doanh nghiệp, hợp tác xã và nhà vườn. Năm nay, sự kiện có nhiều điểm mới với các không gian trưng bày trái cây, nông sản tiêu biểu của các tỉnh, thành như Hà Nội, Sơn La, Hưng Yên, Lạng Sơn, Hải Phòng, Cần Thơ…; khu giới thiệu nông cụ, máy móc, công nghệ sản xuất - bảo quản - chế biến; trình diễn thương mại điện tử; khu ẩm thực và các hoạt động văn hóa nghệ thuật đặc sắc như hát quan họ trên thuyền, hát then, sloong hao.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Lehoitraicay+gian+hang+cac+xa.jpg/2d6238ad-e5e7-fca1-7e89-ad6d2b145e1c?t=1765029584059\" style=\"height: 567px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Gian trưng bày của phường Chũ thu hút du khách.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại lễ hội, nhiều sản phẩm đặc trưng của các xã, phường được giới thiệu cùng các tác phẩm nghệ thuật độc đáo tạo hình từ trái cây. Nhiều loại quả đặc sản của địa phương như cam lòng vàng, cam ngọt, bưởi ngọt,… cũng được bày bán phong phú.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Lehoitraicay+gian+hang+cac+xa+2.jpg/70e04e9d-4839-ef3d-1568-b5577448730c?t=1765029642909\" style=\"height: 668px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ các trái cây địa phương, nhờ bàn tay khéo léo đã tạo lên những hình ảnh đẹp mắt.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sự phong phú và sáng tạo trong trưng bày đã thu hút hàng nghìn lượt khách tham quan, tạo nên không khí sôi động và hấp dẫn tại Lễ hội trái cây Bắc Ninh 2025.</span></span></span>&nbsp;</p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><em><strong><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một số hình ảnh các gian trưng bày tại Lễ hội trái cây Bắc Ninh 2025:</span></span></span></strong></em></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+2.jpg/7b5927a0-cdaa-0582-0a73-41f5a82e1844?t=1765030231440\" style=\"height: 584px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Gian trưng bày của xã Biển Động.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+7.jpg/ac076013-52af-7345-6acd-86d15b4aab91?t=1765030322388\" style=\"height: 631px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Gian trưng bày của xã Lục Ngạn.&nbsp;</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><br />\n<img src=\"/documents/37632/200628/Cac+gian+hang+9.jpg/f5da9f5b-057f-8f7a-8970-58c34bd7efb3?t=1765030351135\" style=\"height: 664px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cổng gian trưng bày của xã Lục Ngạn thu hút du khách tham quan và check in.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/cac+gian+hang.jpg/8468a343-21e3-3a3b-43f0-196024bf6ef8?t=1765030605370\" style=\"height: 646px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Gian trưng bày xã Sa Lý.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+1.jpg/60e18de9-c03a-b003-f1ec-df750d35a336?t=1765030761669\" style=\"height: 652px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+10.jpg/7f3f38c5-2426-78de-968f-9e60a3b92c44?t=1765032287187\" style=\"height: 683px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Gian trưng bày của xã Sơn Hải.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+5.jpg/3ff04bac-7042-3d9f-8786-6795ecfa30e9?t=1765030660945\" style=\"height: 629px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại các gian hàng còn trưng bày, bán rất nhiều loại trái cây đang trồng trên địa bàn.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cac+gian+hang+8.jpg/3f2a2847-c0db-24f5-f389-789f0c4eb381?t=1765030688320\" style=\"height: 589px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những sản phẩm nổi tiếng của địa phương cũng được bày bán tại Lễ hội.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Cacgian+hang+3.jpg/892b77d8-7328-dbb7-e68c-af8d99120033?t=1765032495153\" style=\"height: 641px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Du khách được tư vấn cách trồng cây, bảo vệ cây trồng.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/Du+khach+thamquannhavuon.jpg/06c2509b-f74f-8e39-49ca-5fed3d943cbc?t=1765033023813\" style=\"height: 724px; width: 1000px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Du khách tham quan một số khu, điểm du lịch, nhà vườn, hợp tác xã, làng nghề tiêu biểu như: Điểm du lịch sinh thái Bầu Tiên, Điểm du lịch Hoa Qủa Sơn, Làng văn hóa Đông Bắc, Hợp tác xã mỳ Chũ.</span></span></span></span></p>', '2025-12-06 14:30:00', 'https://bacninh.gov.vn/news/-/details/37632/sac-mau-le-hoi-trai-cay-bac-ninh-2025-80602801', '', 'Dương Thuỷ', 579, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:06.992485', 5, 11);
INSERT INTO `sync_articles` VALUES (310, '80187301', 'Hội nghị xúc tiến điểm đến du lịch năm 2025: Đưa Bắc Ninh trở thành điểm đến giàu bản...', 'Hội nghị xúc tiến điểm đến du lịch năm 2025: Đưa Bắc Ninh trở thành điểm đến giàu bản sắc và hấp dẫn của vùng Bắc Bộ và cả nước', '/documents/37632/200622/2+1+HNxuctienLDVH+chutrithaoluan.jpg/0af1687f-8831-68b5-1145-33cfff9bd5b1?t=1764996938143', '<p>(BNP) - Sáng 6/12, tại Hội trường Trung tâm phường Chũ (Bắc Ninh), Sở Văn hóa, Thể thao và Du lịch tổ chức Hội nghị xúc tiến điểm đến du lịch năm 2025. Đây là sự kiện hưởng ứng Lễ hội trái cây Bắc Ninh, đồng thời đánh giá tiềm năng, định hướng phát triển và tăng cường liên kết để đưa du lịch Bắc...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/2+1+HNxuctienLDVH+chutrithaoluan.jpg/0af1687f-8831-68b5-1145-33cfff9bd5b1?t=1764996938143\" style=\"height: 590px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đồng chí lãnh đạo Sở Văn hóa, Thể thao và Du lịch chủ trì hội nghị.</span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span>Bắc Ninh hiện sở hữu hệ thống di sản đa dạng với gần 4.000 di tích, trong đó có 1.415 di tích được xếp hạng, 11 di tích Quốc gia đặc biệt, 24 Bảo vật Quốc gia và 7 Di sản Văn hóa phi vật thể được UNESCO vinh danh. Cùng với đó là hệ sinh thái du lịch phong phú như Suối Mỡ, Khuôn Thần, Hồ Cấm Sơn, Tây Yên Tử… tạo nền tảng thuận lợi để phát triển các loại hình du lịch. Tại Lục Ngạn - địa điểm khảo sát của chương trình - nơi có lợi thế vùng cây ăn quả, vải thiều và văn hóa đa dân tộc tiếp tục mở ra tiềm năng lớn cho du lịch trải nghiệm.&nbsp;</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mục tiêu đến năm 2026 - 2027, Bắc Ninh&nbsp;</span></span></span>xác định du lịch trở thành ngành kinh tế mũi nhọn, thu hút 3 triệu lượt khách, doanh thu khoảng 3.000 tỷ đồng; đến năm 2030 phấn đấu đạt 10 triệu lượt khách và doanh thu 10.000 tỷ đồng. Chiến lược phát triển tập trung vào 4 nhóm sản phẩm chủ lực: du lịch văn hóa - di sản; du lịch sinh thái - nông thôn; du lịch đô thị - MICE; du lịch cộng đồng và làng nghề.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/2+HNxuctienDL+BauTien.jpg/e3b0c9fa-afc6-e5d4-25ea-2dcdee78d251?t=1764997213480\" style=\"height: 604px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện điểm&nbsp;Du lịch sinh thái Bầu Tiên (phường Phượng Sơn) phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại hội nghị, đại biểu đã xem phóng sự quảng bá du lịch Bắc Ninh và video giới thiệu các khu, điểm du lịch, tuyến tham quan nội tỉnh và tour liên kết vùng. Qua đó thể hiện&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">rõ thế mạnh của Bắc Ninh từ hệ thống di sản đặc sắc, không gian làng quê Kinh Bắc cho tới các vùng sinh thái giàu trải nghiệm, đặc biệt là loại hình du lịch nông nghiệp gắn với vườn cây ăn quả.&nbsp;</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại đây, đại diện các khu, điểm du lịch như Bầu Tiên, Neo Garden, Đông Đô Village, Senna Wellness Retreat trình bày tiềm năng, sản phẩm và dịch vụ đặc trưng, đồng thời</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">&nbsp;đóng góp các giải pháp, nhằm đồng hành hoàn thiện quy hoạch, xây dựng sản phẩm đặc trưng và khai thác hiệu quả các loại hình mới.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/3+HNxuctienLDVH+chutrithaoluan.jpg/d07b763e-15ee-c369-c6aa-c9bb11e5c49e?t=1764997754520\" style=\"height: 627px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện Công ty&nbsp;Công ty cổ phần Sunny Vietnam (Hà Nội) phát biểu tại hội nghị.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong phần thảo luận, đại diện doanh nghiệp du lịch và cơ quan truyền thông đánh giá cao cảnh quan, đặc biệt là các vườn cây trĩu quả và nhiều mô hình du lịch sáng tạo. Nhiều ý kiến đề xuất tháo gỡ khó khăn, phát triển sản phẩm mới, tăng cường liên kết vùng, đẩy mạnh chuyển đổi số và nâng cao chất lượng dịch vụ. Các doanh nghiệp lữ hành kiến nghị địa phương mở rộng cơ sở lưu trú, khu vui chơi giải trí chất lượng cao; đầu tư dịch vụ bài bản; nâng cấp hạ tầng tại làng tranh Đông Hồ, Đền Đô, chùa Vĩnh Nghiêm… nhằm thu hút và giữ chân du khách. Một số ý kiến cũng cho rằng một số điểm đến còn hạn chế về dịch vụ, phong cách phục vụ và biển chỉ dẫn; cần nâng cao tính chuyên nghiệp trong tổ chức, quảng bá và cung cấp dịch vụ; phát triển thêm sản phẩm dân gian, đa dạng chế biến từ hoa quả; bố trí hướng dẫn viên, mở rộng dịch vụ lưu trú, điểm bán sản phẩm địa phương và hoạt động giới thiệu du lịch. Đồng thời nhấn mạnh yêu cầu nâng cấp hạ tầng, nâng cao tính chuyên nghiệp và chất lượng dịch vụ, phát triển sản phẩm đặc trưng.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/1+HNxuctienDLPGD+So+VH.jpg/1987ea81-7873-1324-7aa7-ac31df5149ee?t=1764996892698\" style=\"height: 621px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Giám đốc Sở Văn hóa, Thể thao và Du lịch Đỗ Tuấn Khoa p<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">hát biểu tại hội nghị.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại hội nghị, Phó Giám đốc Sở Văn hóa, Thể thao và Du lịch Đỗ Tuấn Khoa ghi nhận và kỳ vọng sự phối hợp chặt chẽ giữa chính quyền, doanh nghiệp, cơ quan truyền thông và các tổ chức liên quan nhằm thúc đẩy du lịch Bắc Ninh phát triển bền vững. Đồng thời,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">khẳng định thời gian tới Bắc Ninh sẽ triển khai đồng bộ các cơ chế, chính sách, đầu tư hạ tầng và cơ sở vật chất để đáp ứng yêu cầu phát triển du lịch.&nbsp;</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đánh giá cao các ý kiến đóng góp và cho biết ngành sẽ tiếp tục tham mưu hoàn thiện quy hoạch, cơ chế và chính sách thu hút đầu tư; ưu tiên phát triển hạ tầng giao thông kết nối; đẩy mạnh sản phẩm du lịch đêm, du lịch cộng đồng và trải nghiệm. Đồng thời, tăng cường đổi mới phương thức truyền thông, ứng dụng công nghệ số trong xúc tiến, quảng bá; tạo môi trường thuận lợi để doanh nghiệp đồng hành đưa du lịch Bắc Ninh tăng tốc, trở thành điểm đến giàu bản sắc và hấp dẫn của vùng Bắc Bộ và cả nước.</span></span></span></p>', '2025-12-06 04:53:00', 'https://bacninh.gov.vn/news/-/details/37632/hoi-nghi-xuc-tien-iem-en-du-lich-nam-2025-ua-bac-ninh-tro-thanh-iem-en-giau-ban-sac-va-hap-dan-cua-vung-bac-bo-va-ca-nuoc-80187301', '', 'Dương Thuỷ', 221, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.018215', 5, 11);
INSERT INTO `sync_articles` VALUES (311, '77781902', 'Khai mạc Lễ hội trái cây Bắc Ninh – Tinh hoa nông sản Việt', 'Khai mạc Lễ hội trái cây Bắc Ninh – Tinh hoa nông sản Việt', '/documents/37632/18152201/LehoitraicayDaibieubamnut.jpg/9fb3b9de-4694-5790-b80e-04b586dbfadf?t=1764945787057', '<p>(BNP) – Tối 05/12, tại Quảng trường Trung tâm phường Chũ, Bộ Công Thương phối hợp với UBND tỉnh Bắc Ninh long trọng tổ chức khai mạc Lễ hội Trái cây tỉnh Bắc Ninh năm 2025 với chủ đề “Trái cây Bắc Ninh – Tinh hoa nông sản Việt”.</p>', '<p align=\"center\" style=\"text-align:center; margin-bottom:11px\"><img src=\"/documents/37632/18152201/Lehoitraicay+Dai+bieu.jpg/ad9f808d-2648-5029-dcc4-60397f40ea6b?t=1764942345429\" style=\"height: 362px; width: 900px;\" /></p>\n\n<p align=\"center\" style=\"text-align:center; margin-bottom:11px\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu tham dự buổi lễ.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Tham dự <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">khai mạc </span></span></span>Lễ hội&nbsp;</span>có các đồng chí:&nbsp;<span style=\"font-size:12pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Hồng Thái, Uỷ viên Trung ương Đảng, Bí thư Tỉnh uỷ; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh uỷ; Nguyễn Việt Oanh, Phó Bí thư Tỉnh uỷ, Chủ tịch HĐND tỉnh; Phạm Hoàng Sơn, Phó Bí thư Tỉnh uỷ, Chủ tịch UBND tỉnh; các đồng chí Uỷ viên Ban Thường vụ Tỉnh uỷ, lãnh đạo HĐND, UBND; đại diện lãnh đạo các Cục, Vụ thuộc các cơ quan Trung ương; <span lang=\"VI\">đại diện lãnh đạo</span> Sở Công Thương một số tỉnh; lãnh đạo các sở, ban, ngành, địa phương, </span></span><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">doanh nghiệp, hợp tác xã, nhà vườn cùng đông đảo Nhân dân, du khách.</span></span></span></span></span></span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:normal\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"> </span></span><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18152201/LehoitraicayTronghoi.jpg/654031ef-e877-55fc-a6c4-eeebc2dd64b8?t=1764942430063\" style=\"height: 575px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Màn trống hội mở màn khai mạc Lễ hội trái cây tỉnh Bắc Ninh năm 2025.</span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mở đầu chương trình là màn “Trống hội quê hương” kết hợp với múa lân, rồng tạo không khí tưng bừng mở ra không gian giàu bản sắc của vùng Kinh Bắc. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18152201/gianhang+phuong+Chu.jpg/a16027a7-b073-f869-ca40-bf56b0432ca1?t=1764947441769\" style=\"height: 544px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tác phẩm trái cây được trình bày đẹp mắt, ấn tượng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Lễ hội trái cây năm 2025</span> diễn ra từ ngày 05/12 – 10/12/2025 tại Quảng trường trung tâm phường Chũ, tỉnh Bắc Ninh với nhiều điểm mới nổi bật.&nbsp;</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lần đầu tiên không gian trưng bày được thiết kế theo hướng mở, hiện đại, kết hợp công nghệ trình chiếu, trải nghiệm trực quan để tôn vinh vẻ đẹp tự nhiên của trái cây Bắc Ninh. Quy mô lễ hội được mở rộng với sự tham gia của gần 200 gian hàng từ các doanh nghiệp, hợp tác xã, nhà vườn trong và ngoài tỉnh. Hoạt động thương mại được đẩy mạnh thông qua hoạt động livestream bán hàng, kết nối trực tuyến với các sàn thương mại điện tử; sự góp mặt của KOL, KOC và nhà sáng tạo nội dung số, tạo sức lan toả truyền thông mạnh mẽ cho sản phẩm nông sản địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không gian văn hóa Quan họ kết hợp cùng nghệ thuật sắp đặt trái cây, vừa truyền thống, vừa hiện đại. Các hoạt động trải nghiệm vườn cây, tour du lịch nông nghiệp, trình diễn chế biến nông sản, trò chơi dân gian… mang đến một Lễ hội vừa giàu bản sắc, vừa hấp dẫn đối với du khách.</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\"></span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18152201/LehoitraicayPCT+THinhpb.jpg/9470f0fd-3d44-6b33-9c1c-7a9aa8b044e9?t=1764945731502\" style=\"height: 595px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh phát biểu khai mạc buổi lễ.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Phát biểu khai mạc, </span>đồng chí <span lang=\"VI\">Phạm Văn Thịnh</span>, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn đại biểu Quốc hội tỉnh, Trưởng Ban Tổ chức Lễ hội nhấn mạnh: Lễ hội trái cây Bắc Ninh năm 2025 được tổ chức trong thời điểm toàn tỉnh đang nỗ lực thực hiện các mục tiêu Nghị quyết Đại hội Đảng bộ tỉnh lần thứ I, nhiệm kỳ 2025 – 2030; trong đó xác định phát triển nông nghiệp sinh thái, công nghệ cao, tuần hoàn là một trong những trụ cột quan trọng, góp phần nâng cao chất lượng cuộc sống Nhân dân và xây dựng nông thôn mới kiểu mẫu.</span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\"></span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Phó Chủ tịch UBND tỉnh cho biết, năm 2025, kinh tế – xã hội của tỉnh tiếp tục đạt nhiều kết quả tích cực; Quy mô GRDP đạt trên 522 nghìn tỷ đồng, tốc độ tăng trưởng 10,27% thuộc nhóm cao nhất cả nước. Tổng kim ngạch xuất nhập khẩu ước đạt 182 tỷ USD, tiếp tục dẫn đầu cả nước và chiếm khoảng 20% kim ngạch quốc gia. Thu ngân sách nhà nước ước đạt 72.497 tỷ đồng, vượt 30% so với dự toán và tăng 40% so với năm 2024.</span> Đặc biệt, <span lang=\"VI\">nông nghiệp chuyển dịch mạnh theo hướng hiện đại và xanh hơn, với gần 54 nghìn ha cây ăn quả, sản lượng hơn 80 nghìn tấn, nhiều vùng trồng đạt tiêu chuẩn VietGAP; hơn 780 sản phẩm OCOP đã khẳng định vị thế của nông sản Bắc Ninh trên thị trường.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Lễ hội năm nay có quy mô lớn, gần 200 gian hàng trưng bày các sản vật tiêu biểu, kết hợp hoạt động quảng bá, thương mại, trải nghiệm du lịch nông nghiệp, ứng dụng công nghệ số trong giới thiệu và tiêu thụ sản phẩm. Đây là cách làm mới, thể hiện quyết tâm của tỉnh trong hỗ trợ nông dân, hợp tác xã và doanh nghiệp mở rộng thị trường, nâng cao giá trị nông sản.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí <span lang=\"VI\">ghi nhận và cảm ơn sự phối hợp của các Bộ, ngành Trung ương; địa phương trong vùng; các doanh nghiệp, hợp tác xã, nghệ nhân nhà vườn; cùng sự hưởng ứng của Nhân dân đã tạo nên một lễ hội trang trọng, hiện đại, giàu bản sắc.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Trong không khí vui tươi của mùa quả chín, Phó Chủ tịch UBND tỉnh long trọng tuyên bố khai mạc Lễ hội trái cây Bắc Ninh năm 2025, đồng thời chúc các đại biểu, Nhân dân và du khách có những trải nghiệm phong phú, ý nghĩa tại Lễ hội.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align: center;\"><img src=\"/documents/37632/18152201/LehoitraicayDaibieubamnut.jpg/9fb3b9de-4694-5790-b80e-04b586dbfadf?t=1764945787057\" style=\"height: 514px; width: 900px;\" /></p>\n\n<p class=\"p1\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu thực hiện nghi thức khai mạc <span lang=\"VI\">Lễ hội trái cây tỉnh Bắc Ninh năm 2025.</span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại chương trình, các đại biểu thực hiện nghi thức khai mạc <span lang=\"VI\">Lễ hội trái cây tỉnh Bắc Ninh năm 2025</span> với chủ đề “Trái cây Bắc Ninh – Tinh hoa nông sản Việt”.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18152201/Traodaugia4+cay.jpg/ad4d08d9-f32e-e227-56ab-4960528302a2?t=1764945854117\" style=\"height: 582px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh tặng hoa chúc mừng chủ nhân 4 cây cam tham gia đấu giá ủng hộ tại chương trình.</span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khuôn khổ chương trình, Ban tổ chức tiến hành đấu giá 4 cây cam&nbsp;<span lang=\"VI\">được chăm sóc công phu,&nbsp;</span>thu về 500 triệu đồng để ủng hộ đồng bào miền Trung, Tây Nguyên khắc phục thiệt hại do thiên tai, qua đó lan tỏa tinh thần sẻ chia, tương thân tương ái của Đảng bộ, chính quyền và Nhân dân tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18152201/LehoitraicayTronghoi+2.jpg/918dc7d5-1342-f2fc-daf1-ac80bfc6fb10?t=1764943792681\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">C<span lang=\"VI\">hương trình nghệ thuật đặc sắc tại chương trình khai mạc.</span></span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó <span lang=\"VI\">là chương trình nghệ thuật đặc sắc</span>, <span lang=\"VI\">được dàn dựng công phu, kết hợp hài hòa giữa âm nhạc hiện đại và các giá trị văn hóa truyền thống. Những tiết mục như</span>: <span lang=\"VI\">“Miền trái ngọt”,</span> “Phùng quan tế hội”, “Về Bắc Ninh quê em”,<span lang=\"VI\"> “Lục Ngạn quê hương ân tình”, “Gửi về Quan họ”… được thể hiện bởi NSND Thúy Hường, ca sĩ Minh Ngọc, Lương Hải Yến, Minh Đức</span>…<span lang=\"VI\"> và các diễn viên Nhà hát Chèo Bắc Ninh, mang đến không khí rộn ràng, hấp dẫn.&nbsp; </span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align: center;\"><img src=\"/documents/37632/18152201/Lehoitraicay+Dai+bieu+tinh+tham+quan+gian+hang.jpg/18eff8d6-85a1-df38-e65d-dd5a84aa8575?t=1764937477952\" style=\"height: 499px; width: 900px;\" /></p>\n\n<p class=\"p1\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ trái qua: Chủ tịch HĐND tỉnh Nguyễn Việt Oanh, Bí thư Tỉnh ủy Nguyễn Hồng Thái, Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương, Chủ tịch UBND tỉnh Phạm Hoàng Sơn tham quan các gian trưng bày.</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết thúc chương trình, <span lang=\"VI\">các đại biểu và du khách tham quan các gian hàng trưng bày, thưởng thức sản vật địa phương và tham gia các hoạt động trải nghiệm tại Lễ hội.&nbsp;</span></span></span></span></p>\n\n<p class=\"p1\" style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '2025-12-05 15:00:00', 'https://bacninh.gov.vn/news/-/details/37632/khai-mac-le-hoi-trai-cay-bac-ninh-tinh-hoa-nong-san-viet-77781902', '', 'Nhóm PV', 798, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.047005', 5, 11);
INSERT INTO `sync_articles` VALUES (312, '75843301', 'Bắc Ninh triển khai tuyên truyền cổ động trực quan kỷ niệm 80 năm Ngày Tổng tuyển cử...', 'Bắc Ninh triển khai tuyên truyền cổ động trực quan kỷ niệm 80 năm Ngày Tổng tuyển cử đầu tiên bầu Quốc hội Việt Nam', '/documents/37632/200622/bau-cu-17648394688971282303876.jpg/55395b4e-f195-cc00-578e-c262114e0b2e?t=1764900965845', '<p>(BNP) - Văn phòng UBND tỉnh Bắc Ninh vừa ban hành <a href=\"/documents/37632/200622/5568+CV+UBND+KGVX.pdf/52ee6b24-1d4e-b7cc-8d04-a02292bdf2f2?t=1764900796839\">Công văn số 5568/UBND-KGVX</a>&nbsp;thông báo ý kiến chỉ đạo của Chủ tịch UBND tỉnh về triển khai công tác tuyên truyền cổ động trực quan...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/bau-cu-17648394688971282303876.jpg/55395b4e-f195-cc00-578e-c262114e0b2e?t=1764900965845\" style=\"height: 516px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ. Nguồn Internet.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thực hiện <a href=\"/documents/37632/0/6578_BVHTTDL_VHCSG_TV.zip/53f7ccb9-38d1-602a-17fa-d18f7f2476c2?t=1764900837555\">Công văn số 6578/BVHTTDL-VHCSGĐTV </a>của&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bộ Văn hóa, Thể thao và Du lịch về</span></span>&nbsp;công tác tuyên truyền cổ động trực quan phục vụ các hoạt động kỷ niệm và sự kiện bầu cử, <span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh yêu cầu&nbsp;</span></span></span></span>toàn tỉnh</span></span><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">&nbsp;chủ động tổ chức các hoạt động truyền thông, văn hóa tạo không khí vui tươi, phấn khởi trong nhân dân, đặc biệt tại vùng sâu, vùng xa, vùng dân tộc thiểu số, biên giới và hải đảo; đồng thời đáp ứng nhu cầu hưởng thụ văn hóa trong dịp kỷ niệm quan trọng của đất nước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, đẩy mạnh tuyên truyền về ý nghĩa, tầm quan trọng của cuộc bầu cử, quyền bầu cử và ứng cử của công dân theo Hiến pháp; phổ biến các nội dung cơ bản của Luật Tổ chức Quốc hội, Luật Tổ chức chính quyền địa phương, Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND cùng các văn bản hướng dẫn của Trung ương. Bên cạnh đó, tăng cường giáo dục truyền thống, tôn vinh đóng góp của các đại biểu Quốc hội qua các thời kỳ trong suốt 80 năm đồng hành cùng sự nghiệp xây dựng và bảo vệ Tổ quốc.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổ chức trang trí, cổ động trực quan bằng pa-nô, áp-phích, băng-rôn, bảng điện tử, màn hình LED tại trụ sở cơ quan, đơn vị và nơi công cộng, đặc biệt ở trung tâm đô thị, sân bay, bến tàu, nút giao thông và các tuyến phố chính. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, về mẫu tranh cổ động, gồm 35 mẫu phục vụ kỷ niệm 80 năm Tổng tuyển cử và 41 mẫu tuyên truyền bầu cử Quốc hội khóa XVI, HĐND các cấp nhiệm kỳ 2026–2031, trên cơ sở đó lựa chọn mẫu tranh phù hợp để triển khai tuyên truyền tại địa phương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, tăng cường kiểm tra, giám sát việc sử dụng khẩu hiệu, hình ảnh và tranh cổ động tại nơi công cộng và trên các phương tiện thông tin đại chúng, đảm bảo đúng chủ trương của Đảng, pháp luật của Nhà nước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các sở, ban, ngành, đoàn thể tỉnh; UBND các xã, phường, thị trấn căn cứ chức năng, nhiệm vụ được giao để tổ chức triển khai kịp thời, đầy đủ các nội dung theo chỉ đạo của Bộ Văn hóa, Thể thao và Du lịch.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trong quá trình thực hiện, nếu phát sinh khó khăn, vướng mắc, các đơn vị chủ động báo cáo Sở Văn hóa, Thể thao và Du lịch để tổng hợp, tham mưu UBND tỉnh xem xét và giải quyết.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh giao Sở Văn hóa, Thể thao và Du lịch chủ trì hướng dẫn các cơ quan, đơn vị và địa phương thực hiện công tác tuyên truyền cổ động trực quan theo đúng mẫu tranh, khẩu hiệu và yêu cầu chuyên môn do Bộ ban hành; đồng thời đôn đốc, kiểm tra tiến độ, kịp thời tổng hợp báo cáo và đề xuất UBND tỉnh chỉ đạo đối với nội dung vượt thẩm quyền.</span></span></span></p>', '2025-12-05 06:30:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-tuyen-truyen-co-ong-truc-quan-ky-niem-80-nam-ngay-tong-tuyen-cu-au-tien-bau-quoc-hoi-viet-nam-75843301', '', 'Dương Thuỷ', 109, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.075665', 5, 11);
INSERT INTO `sync_articles` VALUES (313, '49762101', 'Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn kiểm tra công tác tu bổ Cụm di tích Tiên...', 'Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn kiểm tra công tác tu bổ Cụm di tích Tiên Lục và khảo sát địa điểm khảo cổ chùa Hoành Mô', '/documents/37632/200622/Ktraditich+3.jpg/e0a1f7e5-3269-f656-6350-fac1fc8df3ad?t=1764243428897', '<p>(BNP) - Chiều 27/11, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh đã đi kiểm tra tình hình tu bổ Cụm di tích Đình - Đền - Chùa Tiên Lục và khảo sát một số di tích trên địa bàn xã Tiên Lục.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Ktraditich+1.jpg/7cc8285e-7d42-78b4-d74c-08b5d7405b11?t=1764243400999\" style=\"height: 631px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn kiểm tra thực tế tại </span></span><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụm di tích Tiên Lục.</span></span><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng đi có đại diện lãnh đạo Văn phòng UBND tỉnh, Sở Văn hóa, Thể thao và Du lịch, các phòng chuyên môn, lãnh đạo địa phương và đơn vị thi công.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span>Cụm di tích Tiên Lục là quần thể kiến trúc tín ngưỡng đặc sắc, gồm chùa Phúc Quang, đền Tiên Lục, đình Thuận Hòa, đình Viễn Sơn và cây Dã hương nghìn năm tuổi - từng được vua Lê Cảnh Hưng sắc phong “Quốc chúa Đô mộc Dã Đại vương”. Với giá trị nổi bật về lịch sử, văn hóa và kiến trúc nghệ thuật, Quần thể di tích Tiên Lục đã được Thủ tướng Chính phủ xếp hạng Di tích Quốc gia đặc biệt.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian qua, nhiều hạng mục trong quần thể bị xuống cấp, ảnh hưởng đến giá trị và cảnh quan di tích. Trên cơ sở thống nhất của cơ quan chuyên môn, xã Tiên Lục đã huy động khoảng 30 tỷ đồng từ nguồn xã hội hóa để triển khai tu bổ. Hiện đình Viễn Sơn - thuộc kế hoạch tu bổ năm 2025, đã hoàn thành phần lớn các hạng mục chính. Đồng thời, địa phương đang tiếp tục xây dựng kế hoạch trùng tu nhà truyền thống, cải tạo cảnh quan khu vực cây Dã hương và các hạng mục liên quan.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Ktraditich+3.jpg/e0a1f7e5-3269-f656-6350-fac1fc8df3ad?t=1764243428897\" style=\"height: 432px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn kiểm tra thực tế tại khu vực cây Dã hương.</span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Qua kiểm tra thực tế, Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn ghi nhận nỗ lực của Sở Văn hóa, Thể thao và Du lịch, chính quyền xã Tiên Lục và đơn vị thi công trong việc chủ động triển khai, đẩy nhanh tiến độ. Đồng chí nhấn mạnh, mọi hoạt động tu bổ phải tuân thủ nghiêm ngặt nguyên tắc bảo tồn, giữ gìn tối đa yếu tố gốc, không làm biến dạng giá trị lịch sử - nghệ thuật của các di tích.&nbsp;</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc lập hồ sơ các dự án tiếp theo phải đúng quy định của Luật Di sản văn hóa, đồng thời bảo đảm công khai, minh bạch về tổng mức đầu tư, tỷ lệ xã hội hóa và nguồn ngân sách hỗ trợ.&nbsp;</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí cũng đề nghị địa phương chú trọng hoàn thiện hệ thống hạ tầng thiết yếu như điện chiếu sáng, phòng cháy chữa cháy, khu vệ sinh, biển chỉ dẫn… nhằm nâng cao chất lượng phục vụ người dân và du khách, góp phần tăng sức hút của điểm đến.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí giao Sở Văn hóa, Thể thao và Du lịch rà soát tổng thể hiện trạng các di tích trên địa bàn, xây dựng kế hoạch tu bổ có trọng tâm, ưu tiên những công trình xuống cấp, nguy cơ mất an toàn; xác định rõ hạng mục có thể triển khai ngay và những hạng mục cần bổ sung hồ sơ khoa học.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Ktraditich+4.jpg/bd6f28c8-2029-bfb0-694d-4461a7544ac3?t=1764243469955\" style=\"height: 613px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn kiểm tra thực tế&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">địa điểm khảo cổ chùa Hoành Mô tại thôn Hoành Sơn (xã Lạng Giang).</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay sau đó, Phó Chủ tịch Thường trực UBND tỉnh đã đi kiểm tra địa điểm khảo cổ chùa Hoành Mô tại thôn Hoành Sơn (xã Lạng Giang). Năm 2024, từ hố khai quật diện tích 200 m², các chuyên gia đã thu được gần 1.300 di vật gồm gạch, ngói, gốm men, sành, tượng… có niên đại từ thời Trần đến thời Nguyễn. Nhiều nền móng kiến trúc thời Trần, Lê Trung Hưng và Nguyễn đã được phát hiện khi mở rộng khai quật, cho thấy chùa Hoành Mô từng là công trình lớn, cấu trúc rõ ràng, mang giá trị tiêu biểu của nghệ thuật kiến trúc thời Trần.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những kết quả này góp phần khẳng định vị trí của Bắc Ninh trong tiến trình hình thành và phát triển Phật giáo Trúc Lâm Yên Tử, đồng thời cho thấy đây là vùng đất giàu giá trị lịch sử, văn hóa và quân sự của quốc gia Đại Việt.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Ktraditich+5.jpg/480e40a4-944c-0e13-0d82-7f9c33e2821e?t=1764243497316\" style=\"height: 616px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn đánh giá cao giá trị khoa học của các phát hiện khảo cổ tại&nbsp;địa điểm khảo cổ chùa Hoành Mô, thôn Hoành Sơn (xã Lạng Giang).</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đánh giá cao giá trị khoa học của các phát hiện khảo cổ, đồng chí Mai Sơn giao Sở Văn hóa, Thể thao và Du lịch phối hợp các đơn vị liên quan tiếp tục nghiên cứu chuyên sâu, hoàn thiện hồ sơ khảo cổ; xây dựng kế hoạch bảo tồn tổng thể di tích và đề xuất phương án trưng bày, giới thiệu hiện vật gắn với phát triển du lịch văn hóa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn khẳng định tỉnh luôn quan tâm, ưu tiên nguồn lực cho công tác bảo tồn và phát huy giá trị hệ thống di tích - một phần quan trọng trong bản sắc văn hóa Bắc Ninh. Đồng chí đề nghị các cấp, ngành và địa phương thực hiện nghiêm trách nhiệm được giao, bảo đảm tiến độ, chất lượng và sự đồng thuận của Nhân dân trong quá trình triển khai.</span></span></span></p>', '2025-11-27 11:35:00', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-thuong-truc-ubnd-tinh-mai-son-kiem-tra-cong-tac-tu-bo-cum-di-tich-tien-luc-va-khao-sat-ia-iem-khao-co-chua-hoanh-mo-49762101', '', 'Dương Thuỷ', 755, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.101351', 5, 11);
INSERT INTO `sync_articles` VALUES (314, '49551102', 'Thường trực HĐND tỉnh khảo sát triển khai nhiệm vụ quản lý Nhà nước tại Sở Văn hoá,...', 'Thường trực HĐND tỉnh khảo sát triển khai nhiệm vụ quản lý Nhà nước tại Sở Văn hoá, Thể thao và Du lịch', '/documents/37632/30456130/a1+%281%29.jpg/88218db4-a61f-69a1-3bff-faaed84e421e?t=1764237446971', '<p>(BNP) - Chiều 27/11, Thường trực HĐND tỉnh tiến hành khảo sát tình hình thực hiện nhiệm vụ quản lý Nhà nước của Sở Văn hoá, Thể thao và Du lịch (VHTT&amp;DL). Dự buổi làm việc có đồng chí Trần Thị Hằng, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực HĐND tỉnh, đại diện lãnh đạo sở, cơ...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456130/a1+%281%29.jpg/88218db4-a61f-69a1-3bff-faaed84e421e?t=1764237446971\" style=\"height: 518px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Quang cảnh hội nghị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo báo cáo của Sở VHTT&amp;DL, sau sáp nhập, công tác quản lý nhà nước về VHTT&amp;DL tiếp tục được tăng cường. Sở tập trung tổ chức tốt các hoạt động phục vụ nhiệm vụ chính trị, các ngày lễ lớn và sự kiện trọng điểm của tỉnh. Các hoạt động văn hóa, văn nghệ, tuyên truyền được tổ chức phong phú, chất lượng ngày càng cao, đời sống tinh thần của Nhân dân được cải thiện; công tác bảo tồn, phát huy các giá trị di sản, được thực hiện hiệu quả gắn với phát triển du lịch bền vững; số hóa trong lĩnh vực di sản, văn hóa, du lịch được quan tâm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Toàn tỉnh hiện có 7 di sản văn hóa được UNESCO công nhận, ghi danh; 1.451 di tích được xếp hạng. Để bảo tồn, tu bổ, phát huy giá trị di tích, khai thác hiệu quả các loại hình di sản UNESCO trên địa bàn tỉnh, Sở đã phối hợp với các địa phương tổ chức nhiều hoạt động trải nghiệm, lễ hội truyền thống, thu hút hàng triệu lượt du khách mỗi năm. Ước tính lượng khách du lịch năm 2025 trên địa bàn tỉnh đạt hơn 6,3 triệu lượt khách, tăng 26% so với năm 2024 và đạt 112,5% so với kế hoạch năm 2025. Tổng doanh thu du lịch đạt 5.500 tỷ đồng tăng 13% so với năm 2024 và đạt 105% so với kế hoạch năm 2025. Nhiều chương trình kích cầu du lịch, khai thác các giá trị di sản văn hóa, danh lam thắng cảnh được triển khai.&nbsp;</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456130/a3.jpg/fc5e231a-b266-4021-5711-3bbe74f19a41?t=1764237633361\" style=\"height: 582px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí Nguyễn Xuân Cường, Phó trưởng Ban Văn hóa - Xã hội HĐND tỉnh trao đổi tại hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về lĩnh vực thể dục, thể thao, năm 2025, Sở đã đăng cai tổ chức thành công 07 giải thể thao quốc gia, 02 giải thể thao quốc tế, 12 giải thể thao cấp tỉnh và phối hợp tổ chức thành công nhiều giải thể thao của các sở, ngành, địa phương; tham gia nhiều giải thể thao thành tích cao toàn quốc và quốc tế. Bên cạnh đó, thể dục thể thao cho cộng đồng được duy trì, phát triển sâu rộng tại các địa bàn dân cư, góp phần đẩy mạnh hoạt động thể dục thể thao trên địa bàn tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phong trào “Toàn dân đoàn kết xây dựng đời sống văn hóa”, thực hiện nếp sống văn minh đi vào chiều sâu, hiệu quả thiết thực và phát huy giá trị truyền thống. Hệ thống báo chí, truyền thông thực hiện chuyển đổi số mạnh mẽ đáp ứng yêu cầu đổi mới hoạt động thông tin, tuyên truyền trên địa bàn tỉnh và công tác thông tin đối ngoại, tuyên truyền, quảng bá về tỉnh. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456130/a4+%281%29.jpg/5d2b2f1a-2918-1233-a221-d3ab28368304?t=1764237732650\" style=\"height: 566px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Giám đốc VHTT&amp;DL Bùi Thị Thu Thủy giải trình, làm rõ các nội dung Đoàn khảo sát quan tâm.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại hội nghị, các đại biểu đã trực tiếp trao đổi, làm rõ các nội dung, vấn đề Đoàn khảo sát quan tâm; trong đó nhấn mạnh đến các nội dung liên quan đến việc ban hành nghị quyết về chính sách hỗ trợ phát triển du lịch cộng đồng trên địa bàn tỉnh giai đoạn 2023- 2030; kinh phí bảo tồn và phát huy giá trị di sản văn hóa phi vật thể; chế độ đãi ngộ đối với huấn luyện viên, vận động viên và chế độ chi tiêu tài chính đối với các giải thể thao trên địa bàn tỉnh; chính sách đối với Nghệ nhân trong lĩnh vực di sản văn hóa phi vật thể và người làm việc tại Nhà hát Dân ca Quan họ Bắc Ninh, Nhà hát Chèo Bắc Ninh...</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456130/a2+%281%29.jpg/fa20c016-db95-5896-ea2b-a758a239d69c?t=1764237867352\" style=\"height: 530px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng kết luận hội nghị.</span><span style=\"font-family:Arial,Helvetica,sans-serif;\"> </span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết luận hội nghị, Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng ghi nhận, đánh giá cao những kết quả, nỗ lực của Sở VHTT&amp;DL đạt được trong thời gian qua.&nbsp;Phó Chủ tịch Thường trực HĐND tỉnh yêu cầu, thời gian tới, Sở VHTT&amp;DL tập trung tham mưu đề xuất về phát triển văn hóa, du lịch xứng tầm với tiềm năng, lợi thế của địa phương. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chỉ đạo đẩy mạnh công tác tuyên truyền Đại hội Đảng toàn quốc lần thứ XIV và tham mưu tổ chức lễ hội xuân, Festival về miền quan họ, các ngày lễ lớn của tỉnh trong năm 2026. Tham mưu UBND tỉnh trình HĐND tỉnh ban hành nghị quyết về hỗ trợ phát triển phát triển mạnh du lịch gắn với giá trị di sản văn hóa, giá trị di tích. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tăng cường chuyển đổi số; nâng cao chất lượng hoạt động thiết chế văn hoá cơ sở; chú trọng bảo tồn và phát huy bản sắc văn hoá Bắc Ninh. Quan tâm, phát triển phong trào thể dục thể thao quần chúng, có chiến lược đầu tư thể thao thành tích cao.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với các nghị quyết sắp tới sẽ ban hành, Phó Chủ tịch Thường trực HĐND tỉnh đề nghị Sở VHTT&amp;DL tiếp tục tham mưu, báo cáo UBND tỉnh để thống nhất, trình HĐND tỉnh xem xét, thông qua kỳ họp HĐND tỉnh sắp tới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\">&nbsp;</p>', '2025-11-27 09:56:00', 'https://bacninh.gov.vn/news/-/details/37632/thuong-truc-h-nd-tinh-khao-sat-trien-khai-nhiem-vu-quan-ly-nha-nuoc-tai-so-van-hoa-the-thao-va-du-lich-49551102', '', 'Nguyễn Miền', 529, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.141723', 5, 11);
INSERT INTO `sync_articles` VALUES (315, '43328828', 'Du lịch Bắc Ninh đón 6,3 triệu lượt khách, tăng 26% so với năm 2024', 'Du lịch Bắc Ninh đón 6,3 triệu lượt khách, tăng 26% so với năm 2024', '/documents/37632/200622/DL.jpg/64c9093f-384d-93ff-1b7c-0c0a6b35bb11?t=1764057238594', '<p>(BNP) - Năm 2025, du lịch Bắc Ninh ghi nhận nhiều dấu ấn tích cực, lượng du khách tăng mạnh, nhiều sự kiện quy mô lớn được tổ chức, góp phần quảng bá hình ảnh vùng Kinh Bắc tới du khách trong và ngoài nước.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/200622/DL.jpg/64c9093f-384d-93ff-1b7c-0c0a6b35bb11?t=1764057238594\" style=\"height: 524px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tính đến ngày 20/11/2025, Bắc Ninh đón tổng cộng 6,3 triệu lượt khách, tăng 26% so với năm 2024 và đạt 112,5% kế hoạch năm.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tính đến ngày 20/11/2025, Bắc Ninh đón tổng cộng 6,3 triệu lượt khách, tăng 26% so với năm 2024 và đạt 112,5% kế hoạch năm. Trong đó, khách quốc tế đạt 355.000 lượt, chủ yếu đến từ Trung Quốc, Đài Loan, Hàn Quốc… Khách nội địa đạt 5,945 triệu lượt, chủ yếu từ các tỉnh phía Bắc. Tổng thu du lịch ước đạt 5.500 tỷ đồng, tăng 13% so với năm trước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với tăng trưởng khách, cơ sở vật chất du lịch tiếp tục được củng cố với hơn 1.000 cơ sở lưu trú, trong đó có 5 khách sạn 5 sao và 38 điểm du lịch cấp tỉnh. Các hoạt động văn hóa - du lịch được tổ chức xuyên suốt trong năm, tạo sức hút mạnh mẽ cho thị trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Nhiều hoạt động kích cầu du lịch quy mô lớn</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong năm 2025, Sở Văn hoá, Thể thao và Du lịch đã triển khai nhiều chương trình quảng bá, xúc tiến du lịch theo các chỉ đạo của Chính phủ, Bộ Văn hoá, Thể thao và Du lịch và UBND tỉnh, tiêu biểu như: Tổ chức các lễ hội đầu Xuân tại 14 điểm du lịch; khai xuân Tây Yên Tử và Tuần Văn hóa - Du lịch Bắc Giang 2025.&nbsp;</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thực hiện các tour du lịch miễn phí, trong đó có hành trình theo các điểm xuất hiện trong MV “Bắc Bling” của ca sĩ Hòa Minzy và tour trải nghiệm tại triển lãm “80 năm Hành trình Độc lập - Tự do - Hạnh phúc”.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham gia hàng loạt sự kiện văn hóa - du lịch lớn tại Hà Nội, Huế, Hưng Yên, Hải Dương, Vĩnh Phúc… nhằm quảng bá văn hóa, ẩm thực và điểm đến Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổ chức Liên hoan du lịch ẩm thực Bắc Ninh tại phường Từ Sơn và Tuần văn hóa - du lịch “Gốm và làng nghề truyền thống”.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đẩy mạnh chuyển đổi số, ra mắt kênh “Go to Bac Ninh” trên 04 nền tảng mạng xã hội, phát hành phim quảng bá và cập nhật dữ liệu trên Cổng du lịch thông minh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, tỉnh đã phối hợp Tổng Công ty Đường sắt Việt Nam khai trương du lịch tàu 5 cửa ô tuyến Hà Nội - Từ Sơn, thu hút 24.000 lượt khách sau hơn 02 tháng hoạt động.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Tiếp tục thúc đẩy phát triển du lịch thời gian tới</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để tiếp tục thúc đẩy phát triển du lịch thời gian tới, Sở Văn hoá, Thể thao và Du lịch đưa ra 04 nhóm giải pháp trọng tâm, đó là: </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổ chức thêm nhiều sự kiện du lịch - văn hóa quy mô lớn, tạo sản phẩm hấp dẫn cho du khách. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tăng cường liên kết vùng, phát triển sản phẩm du lịch chuyên đề như </span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">du lịch kết hợp hội nghị, hội thảo, triển lãm, tổ chức sự kiện, du lịch khen thưởng (</span></span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">MICE), golf, du lịch cộng đồng, du lịch nông thôn, ẩm thực… </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tháo gỡ khó khăn cho doanh nghiệp, nhất là liên quan đến đầu tư, hạ tầng, thuế. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đẩy mạnh chuyển đổi số, xây dựng hệ sinh thái du lịch thông minh và phát triển cơ sở dữ liệu dùng chung.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với cách làm bài bản và sự phối hợp chặt chẽ giữa các đơn vị, chương trình kích cầu du lịch năm 2025 đã tạo sức lan tỏa, góp phần nâng cao hình ảnh và năng lực cạnh tranh của du lịch Bắc Ninh trên bản đồ du lịch Việt Nam.</span></span></span></p>', '2025-11-26 01:00:00', 'https://bacninh.gov.vn/news/-/details/37632/du-lich-bac-ninh-on-6-3-trieu-luot-khach-tang-26-so-voi-nam-2024-43328828', '', 'Dương Thuỷ', 414, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.167099', 5, 11);
INSERT INTO `sync_articles` VALUES (316, '39288801', 'Phường Quế Võ khai giảng lớp học hát Dân ca Quan họ Bắc Ninh', 'Phường Quế Võ khai giảng lớp học hát Dân ca Quan họ Bắc Ninh', '/documents/37632/200622/z7253463242386_b14254843062229c7e2c92828c80fba8+%281%29.jpg/00e2dc49-b8c5-5f44-1d16-0a824fa60174?t=1763890787088', '<p>(BNP) - Sáng 23/11, tại Nhà văn hóa khu phố Lựa, Trung tâm Cung ứng dịch vụ sự nghiệp công phường Quế Võ (tỉnh Bắc Ninh) phối hợp với Hội LHPN phường tổ chức khai giảng lớp học hát Dân ca Quan họ Bắc Ninh năm 2025.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200622/z7253463242386_b14254843062229c7e2c92828c80fba8+%281%29.jpg/00e2dc49-b8c5-5f44-1d16-0a824fa60174?t=1763890787088\" style=\"height: 585px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Phó Chủ tịch UBND phường Quế Võ</span>&nbsp;<span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Hoàng Minh Tuấn&nbsp;</span></span></span></span></span>(thứ 2 bên trái)&nbsp;<span lang=\"VI\">tặng</span> hoa chúc mừng lớp học.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Tham </span>dự có đồng chí <span lang=\"VI\">Hoàng Minh Tuấn, Ủy viên Ban Thường vụ Đảng ủy, Phó Chủ tịch UBND phường Quế Võ</span>; lãnh đạo Trung tâm Cung ứng dịch vụ <span lang=\"VI\">sự nghiệp công</span>; Hội LHPN phường cùng 65 học viên đến từ các tổ dân phố: Guột, Lựa, Can Vũ, Nghiêm Xá và một số thành viên CLB quan họ thực hành<span lang=\"VI\">.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Hiện nay phường Quế Võ đã có 05 làng Quan họ thực hành gồm: Tổ dân phố Guột, Tổ dân phố Đanh, Tổ dân phố Đỉnh, Tổ dân phố Đông, Tổ dân phố 4. Việc mở lớp dạy hát Quan họ không chỉ góp phần bảo tồn, gìn giữ và phát huy giá trị văn hóa truyền thống quý báu, mà còn là sân chơi để các tầng lớp nhân dân trong phường được giao lưu, học hỏi, lan tỏa tình yêu Quan họ trong đời sống đương đại.</span>&nbsp;</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200622/z7253463226175_91c3f4039983c04b8765cde615972e69+%281%29.jpg/260b3c86-93e4-098d-e9d4-ea1cfe73fd04?t=1763890751354\" style=\"height: 539px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Một</span> số tiết mục văn nghệ của các học viên chào mừng buổi khai giảng.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span lang=\"VI\"></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Tại lớp học, các học viên được nghe Thạc sĩ Chu Phương Anh, Trung tâm Văn hóa và xúc tiến du lịch tỉnh Bắc Ninh truyền dạy một số làn điệu quan họ và các kỹ thuật trong hát Dân ca Quan họ gồm: các lề lối hát quan họ, các chặng hát và vốn bài của quan họ; tìm hiểu các kỹ thuật của hát quan họ như vang, rền, nền, nảy… học cách hát đối đáp Quan họ cổ, hiểu được tầm quan trọng của việc giữ gìn vốn cổ của dân ca Quan họ. Kết thúc khóa học, các học viên đạt yêu cầu sẽ được Ban tổ chức cấp giấy chứng nhận.</span></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200622/z7253463240289_016879b449cfbdf22fbca70dde3c3c4c.jpg/bb535a4d-5374-2ba8-7b4c-b2fe17ff3f34?t=1763890720923\" style=\"height: 514px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Lãnh</span> đạo phường Quế Võ cùng Ban Tổ chức lớp học chụp ảnh lưu niệm cùng các học viên.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span lang=\"VI\">Lớp học hát được tổ chức với mục tiêu giúp cho các học viên hiểu hơn về nguồn gốc, ý nghĩa, đặc trưng nghệ thuật của Quan họ Bắc Ninh, đồng thời, trang bị cho các học viên những kiến thức, kỹ năng cơ bản trong biểu diễn hát Dân ca Quan họ, qua đó, góp phần gây dựng, gìn giữ và phát triển phong trào hát Dân ca Quan họ Bắc Ninh trên địa bàn phường.</span></span></span></span></p>', '2025-11-23 09:27:00', 'https://bacninh.gov.vn/news/-/details/37632/phuong-que-vo-khai-giang-lop-hoc-hat-dan-ca-quan-ho-bac-ninh-39288801', '', 'Trung tâm Cung ứng dịch vụ sự nghiệp công phường Quế Võ', 489, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.193191', 5, 11);
INSERT INTO `sync_articles` VALUES (317, '33358323', 'Chương trình Liên hoan hát Then, đàn Tính tỉnh Bắc Ninh lần thứ Nhất năm 2025', 'Chương trình Liên hoan hát Then, đàn Tính tỉnh Bắc Ninh lần thứ Nhất năm 2025', '/documents/37632/200622/Lien+hoan+hat+Then.jpg/23063b48-4371-103d-ce39-9370e6b18ee0?t=1763630528246', '<p>(BNP) - Liên hoan hát Then, đàn Tính tỉnh Bắc Ninh lần thứ Nhất năm 2025 sẽ diễn ra trong 2 ngày 26 - 27/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh, với chuỗi hoạt động biểu diễn, giao lưu và chấm giải được tổ chức liên tục, quy củ và chuyên nghiệp.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Lien+hoan+hat+Then.jpg/23063b48-4371-103d-ce39-9370e6b18ee0?t=1763630528246\" style=\"width: 900px; height: 511px;\" /><br />\n<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan hát Then, đàn Tính tỉnh Bắc Ninh lần thứ Nhất năm 2025&nbsp;diễn ra trong 2 ngày 26 - 27/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ban Tổ chức Liên hoan hát Then, đàn Tính tỉnh Bắc Ninh lần thứ Nhất, năm 2025 vừa ban hành Thông báo triệu tập các đoàn nghệ thuật thuộc 12 xã, phường đăng ký tham gia Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành phần được triệu tập gồm các đoàn nghệ thuật quần chúng thuộc các xã, phường: An Lạc, Vân Sơn, Biển Động, Lục Ngạn, Sơn Hải, Biên Sơn, Phượng Sơn, Trường Sơn, Nghĩa Phương, Kép, Yên Thế, Xuân Lương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nội dung tham gia thực hiện theo Kế hoạch số 119/KH-UBND ngày 31/10/2025 của UBND tỉnh và Quy chế hoạt động của Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ngày 26/11:</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi sáng (8h00 - 11h30) và chiều (13h30 - 17h00): Các đoàn chạy sân khấu, họp Trưởng đoàn, ổn định công tác chuẩn bị.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi tối (19h00 - 22h30): Khai mạc Liên hoan với chương trình nghệ thuật chào mừng; phát biểu khai mạc; công bố Ban Giám khảo; tặng hoa cho các đoàn; sau đó 03 đoàn đầu tiên biểu diễn theo thứ tự bốc thăm.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ngày 27/11:</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi sáng (7h30 - 11h30) và chiều (13h30 - 16h00): Các đoàn tiếp tục biểu diễn theo thứ tự đã bốc thăm (tổng 9 đoàn còn lại). Ban Giám khảo hội ý, giao lưu các đoàn.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi chiều (16h00 - 17h00): Bế mạc, đánh giá kết quả Liên hoan và trao giải.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xem Chương trình chi tiết dưới đây:</i></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200622/Th%C3%B4ng+B%C3%A1o+tri%E1%BB%87u+t%E1%BA%ADp-2.jpg/1c1bb4f8-e68d-a6ae-0811-c30cd9a3ac01?t=1763630668055\" style=\"height: 1519px; width: 1000px;\" /><br />\n<img src=\"/documents/37632/200622/Th%C3%B4ng+B%C3%A1o+tri%E1%BB%87u+t%E1%BA%ADp-3.jpg/6bcae90d-a955-532d-2848-cf1845ea1c2e?t=1763630691898\" style=\"height: 996px; width: 1000px;\" /><br />\n&nbsp;</p>', '2025-11-21 02:00:00', 'https://bacninh.gov.vn/news/-/details/37632/chuong-trinh-lien-hoan-hat-then-an-tinh-tinh-bac-ninh-lan-thu-nhat-nam-2025-33358323', '', 'Dương Thuỷ', 582, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.217035', 5, 11);
INSERT INTO `sync_articles` VALUES (318, '33080972', 'Bắc Ninh phát động Cuộc thi sáng tác Biểu trưng (logo) chính thức của tỉnh', 'Bắc Ninh phát động Cuộc thi sáng tác Biểu trưng (logo) chính thức của tỉnh', '/documents/37632/200622/logoBGBN.jpg/a9b04554-724d-ab10-e7ab-2907bade4527?t=1763603580074', '<p>(BNP) - UBND tỉnh Bắc Ninh vừa ban hành Kế hoạch số 140/KH-UBND tổ chức Cuộc thi sáng tác Biểu trưng (logo) tỉnh Bắc Ninh, triển khai từ tháng 11/2025 đến hết tháng 4/2026.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/200622/logoBGBN.jpg/a9b04554-724d-ab10-e7ab-2907bade4527?t=1763603580074\" style=\"height: 668px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Logo trước của 2 tỉnh Bắc Giang, Bắc Ninh trước khi sáp nhập.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Kế hoạch, Cuộc thi nhằm lựa chọn một biểu trưng có tính khái quát cao, đảm bảo thẩm mỹ và khả năng ứng dụng rộng rãi trong các hoạt động đối nội, đối ngoại, thông tin và tuyên truyền. Logo phải thể hiện bản sắc vùng đất Bắc Ninh - Kinh Bắc ngàn năm văn hiến, qua đó quảng bá hình ảnh tỉnh đến nhân dân cả nước và bạn bè quốc tế. Cuộc thi cũng là sân chơi khuyến khích, phát huy năng lực sáng tạo nghệ thuật của các tổ chức, cá nhân trong và ngoài nước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cuộc thi được tổ chức rộng rãi, không giới hạn độ tuổi (người dưới 18 tuổi cần có người giám hộ hợp pháp). Tác phẩm dự thi phải thể hiện trên khổ giấy A4, có mẫu phóng to - thu nhỏ, tối đa ba màu; kèm file mềm và bản thuyết minh không quá 300 từ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh giao Sở Văn hóa, Thể thao và Du lịch là cơ quan chủ trì, phối hợp với các sở, ngành, MTTQ, đoàn thể, cơ quan báo chí và địa phương để tuyên truyền và tổ chức cuộc thi.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian nhận tác phẩm: Từ khi phát động đến hết ngày 31/3/2026 (tác phẩm gửi bưu điện được tính theo dấu bưu điện).</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Địa điểm nhận hồ sơ: Thường trực Ban Tổ chức Cuộc thi “Sáng tác Biểu trưng (logo) tỉnh Bắc Ninh”, Phòng Quản lý Văn hóa và Gia đình - Sở Văn hóa, Thể thao và Du lịch Bắc Ninh, tầng 10 tòa nhà A, Khu liên cơ quan, Quảng trường 3/2, phường Bắc Giang, tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hệ: Bà Tạ Thị Hà - Chuyên viên Phòng Quản lý Văn hóa và Gia đình, ĐT: 0389.975.870.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự kiến phát động cuộc thi vào ngày 05/12/2025.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Phương thức xét chọn nhiều vòng</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ban Tổ chức sẽ đặt hàng 05 tác giả giàu kinh nghiệm, đã đạt thành tích cao tại các cuộc thi sáng tác logo trong thời gian gần đây; các tác phẩm đặt hàng không phải qua vòng sơ khảo.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vòng sơ khảo: Hội đồng giám khảo chọn 05 tác phẩm vào vòng chung khảo. Ban Tổ chức công khai 10 tác phẩm (05 đặt hàng + 05 sơ khảo) và tổ chức trưng bày lấy ý kiến Nhân dân trong 10 ngày. Sau đó tác giả hoàn thiện tác phẩm và nộp lại trong 5 ngày.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vòng chung khảo gồm 2 bước:</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bước 1: Tác giả thuyết trình, bảo vệ phương án; Hội đồng chọn 05 tác phẩm vào chung kết. 05 tác phẩm tiếp tục được trưng bày lấy ý kiến Nhân dân trong 10 ngày, tác giả chỉnh sửa và nộp lại trong 5 ngày.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bước 2 - Chung kết: Hội đồng chọn 01 tác phẩm đạt Giải Nhất và 04 tác phẩm Giải Khuyến khích.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tác phẩm đoạt giải sẽ được báo cáo UBND tỉnh trình Ban Thường vụ Tỉnh ủy xem xét lựa chọn làm biểu trưng chính thức của tỉnh. Ban Tổ chức có quyền yêu cầu chỉnh sửa chi tiết để đảm bảo yêu cầu sử dụng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Giải thưởng lên tới 200 triệu đồng</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">01 Giải Nhất: 200 triệu đồng và Bằng chứng nhận của Chủ tịch UBND tỉnh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">04 Giải Khuyến khích: mỗi giải 30 triệu đồng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hỗ trợ 05 tác phẩm vào vòng chung khảo không đạt giải: 10 triệu đồng/tác phẩm.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hỗ trợ 05 tác giả được đặt hàng: 20 triệu đồng/tác giả.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tác giả đạt giải phải tự thực hiện các nghĩa vụ thuế theo quy định.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tác phẩm được chọn làm logo chính thức sẽ thuộc sở hữu UBND tỉnh Bắc Ninh, được khai thác và đăng ký bảo hộ quyền tác giả theo quy định. Tác giả có trách nhiệm phối hợp cung cấp file gốc và chỉnh sửa khi được yêu cầu.</span></span></span>/.</p>', '2025-11-20 01:45:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-phat-ong-cuoc-thi-sang-tac-bieu-trung-logo-chinh-thuc-cua-tinh-33080972', '', 'Dương Thuỷ', 4305, 'Văn hóa', 5, '', '38762', '{}', '2025-12-08 08:18:07.246316', 5, 11);
INSERT INTO `sync_articles` VALUES (329, '80894158', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn: Xây dựng Kinh Bắc trở thành phường mẫu trên các...', 'Chủ tịch UBND tỉnh Phạm Hoàng Sơn: Xây dựng Kinh Bắc trở thành phường mẫu trên các lĩnh vực, xứng đáng là vị trí trung tâm của tỉnh, tạo lan tỏa cho khu vực', '/documents/37632/30456144/7-11.png/8026e74c-91de-cf1f-a289-6d6d45542633?t=1765087804890', '<p>(BNP) - Sáng 7/12, đồng chí Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh có buổi làm việc với phường Kinh Bắc về tình hình phát triển kinh tế - xã hội và thực hiện nhiệm vụ chính quyền địa phương 2 cấp trên địa bàn.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/7-7.png/f794c5d1-0a89-bd51-f4e4-9779ae63bfc4?t=1765088098563\" style=\"height: 617px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bí thư Đảng ủy Phường Kinh Bắc Tạ Đăng Đoan báo cáo kết quả thực hiện nhiệm vụ phát triển kinh tế - xã hội của địa phương.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng dự buổi làm việc có đồng chí Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; Tạ Đăng Đoan, Ủy viên Ban Thường vụ Tỉnh ủy, Bí thư Đảng ủy phường Kinh Bắc; lãnh đạo một số sở, ban, ngành của tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sau 05 tháng vận hành theo mô hình chính quyền 02 cấp, cả hệ thống chính trị phường Kinh Bắc đã nhanh chóng đi vào hoạt động ổn định, duy trì thông suốt, hiệu quả, góp phần thúc đẩy phát triển kinh tế - xã hội của địa phương.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/7-12.png/ad1f3b0e-1430-d241-5f57-d908c3d9163c?t=1765089037932\" style=\"width: 900px; height: 626px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi trao đổi tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hoạt động thương mại - dịch vụ tiếp tục phát triển mạnh, là lĩnh vực chủ lực của địa phương. Sản xuất nông nghiệp phù hợp quá trình đô thị hóa. Công tác tài chính - ngân sách được tăng cường. Tổng thu ngân sách Nhà nước trên địa bàn năm 2025 ước thực hiện 738.956 triệu đồng, đạt 121% so với dự toán. Tốc độ tăng tổng giá trị sản phẩm trên địa bàn phường ước tăng 9,2% so với năm 2024, vượt kế hoạch; thu nhập bình quân đầu người trên địa bàn ước tính năm 2025 đạt 85,8 triệu đồng/người/năm.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, phường chú trọng lập và quản lý quy hoạch đô thị; tăng cường công tác quản lý Nhà nước về trật tự đô thị, trật tự xây dựng, trật tự an toàn giao thông, đất đai, tài nguyên, môi trường. Tăng cường giám sát, xử lý rác thải, phế thải xây dựng, các điểm đổ thải trái phép gây ô nhiễm.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/7-8.png/4bc8cb00-6247-e5dd-3047-c155fc41c1d2?t=1765088233756\" style=\"height: 631px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giám đốc Sở Tài chính Nguyễn Đình Hiếu phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chất lượng hoạt động của Trung tâm phục vụ hành chính công phường ngày càng được nâng cao, phục vụ tốt nhu cầu của người dân, doanh nghiệp. Đã tiếp nhận và giải quyết 17.436 hồ sơ; trực tiếp hỗ trợ người dân, doanh nghiệp số hóa nộp hồ sơ trực tuyến. Đồng thời, tích cực triển khai phong trào hỗ trợ người dân thực hiện thủ tục hành chính trực tuyến tại nơi cư trú trong khoảng thời gian từ 19h đến 21h với 11 buổi hỗ trợ cho khoảng 160 người dân…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Công tác an sinh xã hội, văn hóa, giáo dục được chú trọng; công tác y tế, an toàn thực phẩm được đảm bảo. Thực hiện tốt công tác quốc phòng - quân sự địa phương, đảm bảo an ninh chính trị, trật tự an toàn xã hội trên địa bàn.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/7-9.png/936f3df6-994b-c063-9d5f-1f874d6017ea?t=1765088321781\" style=\"height: 647px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo UBND phường Kinh Bắc tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại hội nghị, Phó Chủ tịch UBND tỉnh Lê Xuân Lợi cùng lãnh đạo các sở, ngành của tỉnh trực tiếp trao đổi, làm rõ các đề xuất, kiến nghị của phường Kinh Bắc thuộc thẩm quyền liên quan đến một số vấn đề về quy hoạch một số dự án trên địa bàn; miễn giấy phép xây dựng; việc chuyển đổi, điều chỉnh một số trụ sở công cho phù hợp với công năng và quy hoạch; phân loại chợ, mô hình quản lý, vận hành khai thác, quy mô hoạt động của các chợ sau khi thực hiện mô hình chính quyền địa phương 2 cấp; phân bổ nguồn kinh phí để phường có cơ sở tổ chức đấu thầu và lựa chọn nhà thầu thực hiện nhiệm vụ sản phẩm công ích trên địa bàn; kiện toàn tổ chức bộ máy; đãi ngộ đối với đội ngũ bí thư chi bộ và tổ trưởng tổ dân phố…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/7-6.png/f5d3bba3-d964-968b-74db-4b057122f37e?t=1765087846020\" style=\"height: 612px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Phạm Hoàng Sơn kết luận buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trên cơ sở ý kiến của các đại biểu, kết luận buổi làm việc, Chủ tịch UBND tỉnh Phạm Hoàng Sơn đánh giá cao phường Kinh Bắc đã chủ động thực hiện các nhiệm vụ sau khi thực hiện mô hình chính quyền địa phương 02 cấp, đạt nhiều kết quả tích cực, góp phần vào sự phát triển chung của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trong thời gian tới, Chủ tịch UBND tỉnh đề nghị phường Kinh Bắc tiếp tục duy trì, giữ vững và phát huy các kết quả đạt được; tập trung cao độ cho giai đoạn “nước rút” trên tất cả các lĩnh vực, nhất là chú trọng phát triển kinh tế, văn hóa, xã hội, giải ngân vốn đầu tư công, thu ngân sách, quản lý đất đai, môi trường, đô thị và đảm bảo an ninh trật tự trên địa bàn… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, trên cơ sở quy hoạch, chiến lược phát triển dài hạn đã xác định của địa phương, chú trọng xây dựng phường Kinh Bắc trở thành phường mẫu trên tất cả các lĩnh vực phát triển kinh tế - xã hội, xứng đáng là vị trí trung tâm của tỉnh, tạo sức lan tỏa cho toàn khu vực. Không để xảy ra tình trạng chuyển trung tâm hành chính gây ảnh hưởng, tác động tiêu cực đến sự phát triển, qua đó, khẳng định tính đúng đắn của việc thực hiện mô hình chính quyền địa phương 2 cấp, vừa gần dân, phục vụ Nhân dân tốt hơn và phát triển kinh tế - xã hội chất lượng hơn. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh cũng chỉ đạo trực tiếp đối với từng nhóm đề xuất, kiến nghị cụ thể của phường. Trong đó, đối với nhóm đề xuất liên quan đến các quy định cụ thể của pháp luật trong lĩnh vực quy hoạch, đất đai, đồng chí giao Sở Nông nghiệp và Môi trường bám sát các quy định của Luật Đất đai mới để điều chỉnh cho phù hợp, tạo điều kiện cho địa phương trong triển khai thực hiện.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/7-11.png/8026e74c-91de-cf1f-a289-6d6d45542633?t=1765087804890\" style=\"height: 600px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tiếp thu ý kiến của các sở, ngành liên quan đến vấn đề xử lý trụ sở, tài sản công dôi dư, Chủ tịch UBND tỉnh giao Sở Tài chính chủ trì, phối hợp với các cơ quan, đơn vị liên quan khẩn trương rà soát tổng thể các trụ sở, tài sản công dôi dư trên địa bàn tỉnh nói chung, tham mưu UBND tỉnh để báo cáo Ban Thường vụ, Thường trực Tỉnh ủy về phương án xử lý, đảm bảo hiệu quả trên tinh thần theo thứ tự ưu tiên các lĩnh vực về giáo dục, y tế, văn hóa, không gian đô thị… phục vụ đời sống của Nhân dân.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh cũng đồng ý chủ trương mở rộng quảng trường khu vực tượng đài Lý Thái Tổ; xây dựng hồ Vạn An để đảm bảo tiêu, thoát nước và thực hiện đầu tư mở rộng các tuyến đường kết nối sang khu vực Tây Bắc của phường. Giao Sở Tài chính nghiên cứu kinh phí để triển khai thực hiện các dự án trên. Sở Xây dựng phối hợp với phường Kinh Bắc rà soát, triển khai các quy hoạch phân khu trên địa bàn, đảm bảo hợp lý. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đối với các vướng mắc, kiến nghị chưa được tháo gỡ, Chủ tịch UBND tỉnh yêu cầu các sở, ngành chuyên môn khẩn trương nghiên cứu, tham mưu, đề xuất UBND tỉnh phương án giải quyết cho triệt để, đạt hiệu quả./.</span></span></span></p>', '2025-12-07 06:09:00', 'https://bacninh.gov.vn/news/-/details/37632/chu-tich-ubnd-tinh-pham-hoang-son-xay-dung-kinh-bac-tro-thanh-phuong-mau-tren-cac-linh-vuc-xung-ang-la-vi-tri-trung-tam-cua-tinh-tao-lan-toa-cho-khu-vuc-80894158', '', 'Linh Ngọc', 673, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.289939', 7, 11);
INSERT INTO `sync_articles` VALUES (330, '76192707', 'Phường Đồng Nguyên phát động các hoạt động thiết thực chào mừng Đại hội đại biểu toàn...', 'Phường Đồng Nguyên phát động các hoạt động thiết thực chào mừng Đại hội đại biểu toàn quốc lần thứ XIV của Đảng', '/documents/37632/200628/IMG_9861+%281%29.jpg/170c4bd4-2fd9-396f-8017-fcfb58692ff9?t=1764911200355', '<p>(BNP) &nbsp;- Sáng 05/12, tại Khu di tích lịch sử - văn hóa Quốc gia đình, chùa Đồng Kỵ (phường Đồng Nguyên), Ủy ban MTTQ phường Đồng Nguyên, tỉnh Bắc Ninh tổ chức phát động các hoạt động thiết thực chào mừng Đại hội đại biểu toàn quốc lần thứ XIV của Đảng, Đại hội MTTQ và các tổ chức chính trị...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9861+%281%29.jpg/170c4bd4-2fd9-396f-8017-fcfb58692ff9?t=1764911200355\" style=\"height: 587px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đại biểu tham gia trồng, chăm sóc hoa, cây cảnh tại Chương trình.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham dự có đại diện lãnh đạo Ủy ban MTTQ tỉnh, Hội LHPN tỉnh cùng đông đảo cán bộ, đoàn viên, hội viên trên địa bàn phường.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Ủy ban MTTQ phường Đồng Nguyên tổ chức phát động sâu rộng trong cán bộ, đoàn viên, hội viên và các tầng lớp nhân dân chấp hành nghiêm các chủ trương, đường lối của Đảng, chính sách pháp luật của Nhà nước, các quy định của địa phương, nhất là ủng hộ các dự án đầu tư xây dựng, tham gia giữ gìn vệ sinh môi trường trên địa bàn dân cư; xây dựng, gìn giữ các nét đẹp văn hóa truyền thống của địa phương; xây dựng gia đình văn hóa, khu dân cư văn hóa, chăm lo các đối tượng gia đình chính sách, người yếu thế…</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9976+%281%29.jpg/1b4a6eb5-b39a-cfc1-9c05-71069097704f?t=1764911242389\" style=\"height: 620px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đông đảo đoàn viên, hội viên và nhân dân phường Đồng Nguyên tham gia trồng hoa tại khuôn viên Khu di tích đình, chùa Đồng Kỵ.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thông qua đợt phát động nhằm tuyên truyền, nâng cao ý thức của cán bộ, hội viên, đoàn viên cùng toàn thể nhân dân trong việc tích cực đẩy mạnh phát triển kinh tế - xã hội, tham gia bảo vệ môi trường bằng các công trình, phần việc cụ thể, ý nghĩa, góp phần làm đẹp thêm cảnh quan thiên nhiên, gìn giữ và phát triển các điểm di tích trên địa bàn. Đồng thời giúp mỗi người dân, mỗi gia đình nâng cao nhận thức và phát huy tốt vai trò trong thực hiện Cuộc vận động lớn của Ủy ban MTTQ Việt Nam “Đoàn kết xây dựng nông thôn mới, đô thị văn minh” cũng như các cuộc vận động, phong trào thi đua của các đoàn thể chính trị - xã hội phát động, hưởng ứng.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9915.jpg/da984325-9599-66f0-f339-9810693337ee?t=1764911275314\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cán bộ, nhân dân phường Đồng Nguyên tham gia quyét dọn, làm sạch môi trường tại Chương trình.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sau lễ phát động, gần 500 cán bộ, đoàn viên, hội viên và nhân dân trên địa bàn phường Đồng Nguyên ra quân trồng 4.000 cây hoa, cây xanh các loại, tạo cảnh quan; đồng thời, tham gia quét dọn, vệ sinh, chỉnh trang làm đẹp tại khuôn viên Khu di tích lịch sử - văn hóa đình, chùa Đồng Kỵ. Qua đó, góp phần tuyên truyền bảo vệ môi trường, gìn giữ, bảo tồn và quảng bá điểm đến di tích, xây dựng phường Đồng Nguyên phát triển xanh, sạch đẹp, văn minh, hiện đại.</span></span></span></p>', '2025-12-05 06:00:00', 'https://bacninh.gov.vn/news/-/details/37632/phuong-ong-nguyen-phat-ong-cac-hoat-ong-thiet-thuc-chao-mung-ai-hoi-ai-bieu-toan-quoc-lan-thu-xiv-cua-ang-76192707', '', 'Hữu Thắng', 188, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.314891', 7, 11);
INSERT INTO `sync_articles` VALUES (331, '76021501', 'Xã Liên Bão trao đổi, giải đáp kiến nghị của Nhân dân thôn Ngang Na về Dự án đấu giá...', 'Xã Liên Bão trao đổi, giải đáp kiến nghị của Nhân dân thôn Ngang Na về Dự án đấu giá quyền sử dụng đất khu nhà ở số 2, số 3 trên địa bàn', '/documents/37632/30456144/5-3.png/1050cd0c-9f71-233c-85fc-fb6aa0b62de7?t=1764906157815', '<p>(BNP) - Sáng 5/12, UBND xã Liên Bão tổ chức hội nghị trao đổi, giải đáp các ý kiến, kiến nghị của Nhân dân thôn Ngang Na liên quan đến Dự án đấu giá quyền sử dụng đất khu nhà ở số 2, số 3 thôn Ngang Na (xã Hiên Vân, huyện Tiên Du), nay là xã Liên Bão, tỉnh Bắc Ninh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/5-3.png/1050cd0c-9f71-233c-85fc-fb6aa0b62de7?t=1764906157815\" style=\"height: 603px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án đấu giá quyền sử dụng đất khu nhà ở số 2, số 3 thôn Ngang Na có tổng diện tích đất 61.410,5m<sup>2</sup>, được triển khai từ năm 2017. Tại hội nghị, đại diện lãnh đạo UBND xã Liên Bão thông báo các thông tin chi tiết, văn bản pháp lý về quy mô, tính chất của dự án và tình hình triển khai thực hiện dự án trên địa bàn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sau khi được thông báo các thông tin liên quan đến dự án, người dân có đất bị thu hồi trên địa bàn thôn Ngang Na nêu nhiều ý kiến, kiến nghị các cơ quan chức năng nhằm đảm bảo quyền lợi cho Nhân dân, liên quan đến: Chủ đầu tư của dự án, mục đích sử dụng đất tại khu vực thu hồi của dự án; việc chi trả tiền đền bù đất của dự án; kiểm tra, rà soát lại giá đền bù; hỗ trợ thêm giá bồi thường đất nông nghiệp và kinh phí để khắc phục sản xuất nông nghiệp do ảnh hưởng của dự án…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tổng hợp và tiếp thu các ý kiến của Nhân dân, Chủ tịch UBND xã Liên Bão Lưu Đắc Hùng trực tiếp trao đổi, làm rõ một số kiến nghị thuộc thẩm quyền. Trong đó nhấn mạnh, việc triển khai thực hiện dự án nằm trong xu thế phát triển chung, nhằm thúc đẩy sự phát triển kinh tế - xã hội của địa phương, theo đúng chủ trương, đường lối, pháp luật của Đảng, Nhà nước và của tỉnh. Việc thu hồi đất để thực hiện dự án đều được triển khai thực hiện theo đúng quy định của Luật Đất đai và các quy định của pháp luật. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Khẳng định xã Liên Bão sẽ tiếp thu đầy đủ các ý kiến của Nhân dân để đảm bảo việc triển khai thực hiện dự án theo đúng quy định của pháp luật, Chủ tịch UBND xã mong muốn Nhân dân trên địa bàn tiếp tục đồng thuận, ủng hộ thực hiện các chủ trương, chính sách của địa phương, góp phần chung tay xây dựng xã Liên Bão nói riêng, tỉnh Bắc Ninh nói chung ngày càng phát triển giàu mạnh hơn./.</span></span></span></p>', '2025-12-05 03:42:00', 'https://bacninh.gov.vn/news/-/details/37632/xa-lien-bao-trao-oi-giai-ap-kien-nghi-cua-nhan-dan-thon-ngang-na-ve-du-an-au-gia-quyen-su-dung-at-khu-nha-o-so-2-so-3-tren-ia-ban-76021501', '', 'Linh Ngọc', 88, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.439207', 7, 11);
INSERT INTO `sync_articles` VALUES (332, '72566601', 'Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương làm việc với Ban Thường vụ Đảng ủy...', 'Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương làm việc với Ban Thường vụ Đảng ủy phường Tam Sơn và Phù Khê', '/documents/37632/200628/IMG_9726456.jpg/d69ea143-7e59-fb74-303b-3d48dae89a28?t=1764843237861', '<p>(BNP) - Chiều 04/12, Đoàn công tác của Thường trực Tỉnh ủy do đồng chí Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy làm trưởng đoàn có buổi làm việc với Ban Thường vụ Đảng ủy phường Tam Sơn và phường Phù Khê để nắm bắt tình hình kết quả thực hiện nhiệm vụ chính trị từ ngày 01/7/2025 đến nay;...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9726456.jpg/d69ea143-7e59-fb74-303b-3d48dae89a28?t=1764843237861\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Toàn cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phường Tam Sơn được thành lập từ ngày 01/7/2025 trên cơ sở hợp nhất, sáp nhập nguyên trạng 02 phường Tam Sơn và Tương Giang, với diện tích14,11 km2; dân số 29.094 người, có 10 khu phố. Đảng bộ phường có 1.019 đảng viên, 28 chi bộ trực thuộc.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phường Phù Khê được thành lập trên cơ sở sáp nhập 03 phường: Phù Khê, Châu Khê, Hương Mạc với diện tích 14,3km2, có 16 tổ dân phố với số dân là 53.699 người. Đảng bộ phường có 1.061 đảng viên sinh hoạt tại 35 chi bộ.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9732111.jpg/054bf8c8-6294-65c6-2b7f-6428cbaeb6dd?t=1764843318431\" style=\"height: 610px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bí thư Đảng ủy phường Tam Sơn Nguyễn Tiến Vụ báo cáo tại Hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sau hơn 05 tháng vận hành mô hình chính quyền địa phương 02 cấp, Đảng ủy phường Tam Sơn và Phù Khê đã đoàn kết, nỗ lực, sử dụng có hiệu quả các nguồn lực và đạt được những kết quả tích cực trên các lĩnh vực; trọng tâm là bảo đảm mô hình chính quyền cấp phường mới vận hành ổn định, thông suốt, cơ bản đáp ứng tốt nhu cầu của người dân và doanh nghiệp, phục vụ nhiệm vụ phát triển kinh tế - xã hội của địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại phường Tam Sơn, tổng thu ngân sách Nhà nước trên địa bàn ước thực hiện năm 2025 là 304 tỷ đồng, đạt 246,7% so với dự toán. Tổng số vốn đã giải ngân tính đến ngày 26/11/2025 đạt hơn 89 tỷ đồng, đạt 95,5% kế hoạch. Công tác quản lý xây dựng, quy hoạch đất đai, bảo vệ môi trường có nhiều chuyển biến tích cực, dần đi vào nề nếp<span lang=\"PT-BR\">. Các l</span>ĩnh vực giáo dục - đào tạo, y tế, văn hóa, văn nghệ, TDTT, truyền thông... được chú trọng. An ninh - quốc phòng được tăng cường, giữ vững. Công tác xây dựng Đảng, chính quyền, MTTQ và các tổ chức chính trị - xã hội có nhiều chuyển biến tích cực.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9760123.jpg/7bee3e91-6606-3ddd-a106-dccacd47625a?t=1764843369343\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bí thư Đảng ủy phường Phù Khê Đỗ Văn Hà trình bày báo cáo tại buổi làm việc.<span lang=\"PT-BR\"></span></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Phường Tam Sơn kiến nghị </span>UBND tỉnh sớm ban hành Quy định xác định chi phí và quản lý dịch vụ công lĩnh vực xây dựng trên địa bàn tỉnh; Quyết định ban hành định mức kinh tế - kỹ thuật thu gom, vận chuyển, xử lý <span lang=\"PT-BR\">ch</span>ất thải rắn sinh hoạt, vệ sinh công cộng trên địa bàn tỉnh<span lang=\"PT-BR\">;</span> chỉ đạo giải quyết dứt điểm 05 công trình thuộc dự án BT trên địa bàn phường; bổ sung biên chế các vị trí phường còn thiếu...</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Tại phường Phù Khê, thu ngân sách 11 tháng năm 2025 ước đạt hơn 117 tỷ đồng&nbsp;</span><span lang=\"PT-BR\">(bằng 224% so dự toán giao). Công tác quản lý đầu tư công, quy hoạch, đô thị và bảo vệ môi trường, nhất là đối với các cơ sở sản xuất sắt thép tại cụm công nghiệp Châu Khê được </span>thực hiện nghiêm túc<span lang=\"PT-BR\">. Tập trung nguồn vốn, đẩy nhanh tiến độ thực hiện các dự án, công trình trọng điểm, như: Xây dựng khu trung tâm hành chính phường, khu trung tâm thể thao phường... Các lĩnh vực văn hóa - xã hội được quan tâm, đời sống vật chất tinh thần của người dân không ngừng được nâng cao. </span>Công tác quán triệt, triển khai Nghị quyết Đại hội Đảng bộ phường, Đại hội Đảng bộ tỉnh nhiệm kỳ 2025 - 2030 được chú trọng.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9777222.jpg/33db7276-281f-2673-7068-941dff71a046?t=1764843413095\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Trưởng Ban Tổ chức Tỉnh ủy Lê Hồng Phúc phát biểu tại buổi làm việc.<span lang=\"PT-BR\"></span></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Phường Phù Khê kiến nghị, đề xuất UBND tỉnh sớm có văn bản giao vốn đầu tư công trung hạn giai đoạn 2026-2030 để UBND phường có căn cứ lập kế hoạch đầu tư công trung hạn; đầu tư trang thiết bị <span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Trạm y tế phường&nbsp;</span></span></span></span>phục vụ nhu cầu khám chữa bệnh cho nhân dân; </span>chỉ đạo <span lang=\"PT-BR\">Sở Nông nghiệp và Môi trường có hướng dẫn xử lý rác tồn dư trên địa bàn phường; đẩy nhanh tiến độ dự án đường TL.277 đến Khu lưu niệm đồng chí Nguyễn Văn Cừ, dự án đường Trịnh Xá - Đa Hội …</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\"></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Thảo luận tại buổi làm việc, các đại biểu tập trung phân tích, làm rõ một số nội dung liên quan đến&nbsp;</span>công tác lập kế hoạch đầu tư công trung hạn giai đoạn 2026 - 2030; công tác bố trí sử dụng, đào tạo chuyên môn cho đội ngũ cán bộ công chức, viên chức theo phân cấp; công tác đảm bảo an sinh xã hội, chăm lo các hộ nghèo, gia đình chính sách; xử lý nước thải, rác thải sinh hoạt trên địa bàn dân cư...</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9785.jpg/389dddb8-bb6c-0a15-3610-05206f46a090?t=1764843450960\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Giám đốc Sở Nông nghiệp và Môi trường Nguyễn Anh Tuấn phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Kết luận buổi làm việc, đ<span lang=\"PT-BR\">ồng chí Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh</span> ủy ghi nhận những nỗ lực, kết quả toàn diện <span lang=\"PT-BR\">của phường </span>Tam Sơn và Phù Khê đạt được <span lang=\"PT-BR\">từ ngày 01/7/2025 đến nay</span>; hệ thống chính trị ổn định, đoàn kết thống nhất cao, kinh tế - xã hội tiếp tục chuyển dịch theo hướng tích cực, đóng góp vào sự phát triển chung của tỉnh Bắc Ninh. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thống nhất với những kiến nghị, đề xuất của 02 phường, Phó Bí thư Thường trực Tỉnh ủy trực tiếp phân tích, làm rõ một số nội dung thuộc thẩm quyền của Tỉnh ủy, UBND tỉnh; đề nghị phường Tam Sơn và Phù Khê tiếp tục phát huy tinh thần đoàn kết, sáng tạo, truyền thống cách mạnh, tổ chức <span lang=\"PT-BR\">quán triệt, tuyên truyền, triển khai thực hiện nghiêm túc các nghị quyết, chỉ thị, kết luận, quy định của Trung ương, của tỉnh về nâng cao hiệu quả hoạt động của hệ thống chính trị và mô hình chính quyền địa phương 02 cấp</span>, <span lang=\"PT-BR\">đặc biệt là “bộ tứ nghị quyết trụ cột” </span>và các Nghị quyết mới ban hành <span lang=\"PT-BR\">của </span>Trung ương; triển khai, đưa Nghị quyết Đại hội Đảng các cấp vào cuộc sống, <span lang=\"PT-BR\">tạo sự đồng thuận </span>cao <span lang=\"PT-BR\">trong cán bộ</span>,<span lang=\"PT-BR\"> đảng viên và </span>n<span lang=\"PT-BR\">hân dân</span>.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9711.jpg/47ea5094-303f-8f4c-dcbf-1204d1dbec7c?t=1764843507466\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương phát biểu kết luận buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\"></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Tập trung rà soát các nhiệm vụ, kế hoạch, chương trình công tác năm 2025, phấn đấu hoàn thành kế hoạch </span>đề ra; k<span lang=\"PT-BR\">hẩn trương nghiên cứu xây dựng kế hoạch phát triển kinh tế </span>- <span lang=\"PT-BR\">xã hội 5 năm giai đoạn 2026 - 2030 và năm 2026</span>. &nbsp;P<span lang=\"PT-BR\">hát huy tiềm năng, lợi thế, đẩy mạnh phát triển kinh tế </span>- <span lang=\"PT-BR\">xã hội</span> gắn với phát <span lang=\"PT-BR\">huy các giá trị văn hóa, lịch sử cách mạng</span> của địa phương. Ưu tiên đầu tư xây dựng các dự án, công trình trọng điểm, thiêt yếu, xác định <span lang=\"PT-BR\">rõ nguồn lực, đề xuất các cơ chế, chính sách phù hợp, tập trung rà soát, xây dựng lộ trình cụ thể, bảo đảm phù hợp, bám sát Chương trình xây dựng tỉnh Bắc Ninh trở thành thành phố trực thuộc Trung ương trước năm 2030.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\"></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Cùng với phát triển kinh tế, cần quan tâm đồng bộ các lĩnh vực văn hóa, giáo dục, y tế, đảm bảo an sinh xã hội, </span>đẩy mạnh ứng dụng CNTT,<span lang=\"PT-BR\"> chuyển đổi số;</span> quan tâm chủ động đào tạo, bồi dưỡng đội ngũ cán bộ, đáp ứng nhu cầu giải quyết TTHC của người dân và doanh nghiệp. Thực hiện tốt công tác tiếp dân, g<span lang=\"PT-BR\">iữ vững an ninh chính trị, trật tự an toàn xã hội, phục vụ phát triển kinh tế - xã hội bền vững. Chuẩn bị tổ chức tốt cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031; công tác tuyển quân năm 2026 và chăm lo Tết Nguyên đán Bính Ngọ - 2026 cho </span>n<span lang=\"PT-BR\">hân dân.</span>..</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Phó Bí thư Thường trực Tỉnh ủy đề nghị 0</span>2 phường <span lang=\"PT-BR\">tăng cường công tác xây dựng, chỉnh đốn Đảng và hệ thống chính trị </span>vững mạnh<span lang=\"PT-BR\">. Nâng cao năng lực lãnh đạo, điều hành của cấp ủy, chính quyền các cấp; siết chặt kỷ luật, kỷ cương hành chính,</span> phát huy trách nhiệm người đứng đầu, phân công rõ người, rõ việc, rõ kết quả<span lang=\"PT-BR\">. Chú trọng công tác giáo dục chính trị, tư tưởng, </span>tăng cường <span lang=\"PT-BR\">giám sát thường xuyên để </span>phòng ngừa, chấn chỉnh các vi phạm từ sớm, từ xa; nâng cao chất lượng hoạt động của MTTQ và các tổ chức chính trị - xã hội, chất lượng sinh hoạt Chi bộ; tổ chức hội nghị triển khai nhiệm vụ công tác năm 2025.</span></span></span></p>', '2025-12-04 10:12:00', 'https://bacninh.gov.vn/news/-/details/37632/pho-bi-thu-thuong-truc-tinh-uy-nguyen-thi-huong-lam-viec-voi-ban-thuong-vu-ang-uy-phuong-tam-son-va-phu-khe-72566601', '', 'Hữu Thắng', 604, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.472589', 7, 11);
INSERT INTO `sync_articles` VALUES (333, '70418901', 'Bắc Ninh phấn đấu gieo trồng vụ Xuân năm 2026 đạt 91.880 ha', 'Bắc Ninh phấn đấu gieo trồng vụ Xuân năm 2026 đạt 91.880 ha', '/documents/37632/30456144/b1.jpg/e90d02a5-7f16-c351-9bf0-ec2ecf84c027?t=1764818437789', '<p>(BNP) - &nbsp;Sở Nông nghiệp và Môi trường tỉnh vừa ban hành Kế hoạch triển khai sản xuất vụ Xuân năm 2026 với tổng diện tích gieo trồng 91.880 ha.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456144/b1.jpg/e90d02a5-7f16-c351-9bf0-ec2ecf84c027?t=1764818437789\" style=\"height: 582px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Trong đó, toàn tỉnh phấn đấu diện tích gieo trồng lúa đạt 71.800 ha, sản lượng ước đạt 450,6 nghìn tấn; diện tích <span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">sản xuất&nbsp;</span></span></span>cây ngô 3.750 ha, sản lượng ước đạt 16,1 nghìn tấn; diện tích sản xuất cây lạc 5.330 ha, sản lượng ước đạt 14,2 nghìn tấn; diện tích trồng khoai lang đạt 1.460 &nbsp;ha, sản lượng 16,5 nghìn tấn; diện tích rau các loại 7.750 ha; cây khác đạt 1.790 ha.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Để đảm bảo vụ Chiêm Xuân đạt năng xuất, chất lượng, Sở Nông nghiệp và Môi trường lưu ý các địa phương mở rộng tối đa diện tích trà xuân muộn bằng những giống lúa năng suất, chất lượng cao, chống chịu với sâu bệnh và điều kiện ngoại cảnh bất thuận, quy hoạch vùng sản xuất tập trung. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đối với lúa gieo thẳng ở những nơi có điều kiện, chủ động nước tưới tiêu, bằng các giống lúa ngắn ngày, phấn đấu cơ bản xong trước ngày 25/2/2026. Mỗi xã, phường nên lựa chọn 3-4 giống chủ lực chỉ đạo sản xuất thành vùng tập trung để nâng cao hiệu quả sản xuất. Riêng các xã miền núi có điều kiện đặc thù thì có thể điều chỉnh khung thời vụ gieo cấy cho phù hợp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Bên cạnh đó, các địa phương cần chủ động các phương án phòng, chống sâu bệnh gây hại ngay từ đầu vụ; quan tâm tới các đối tượng sinh vật hại: Bệnh lùn sọc đen, bệnh đạo ôn lá, đạo ôn cổ bông, sâu đục thân, rầy nâu - rầy lưng trắng, đặc biệt là chuột hại;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tăng cường luân canh cây rau các loại để hạn chế sinh vật hại và tăng hiệu quả sản xuất. Áp dụng cơ giới hóa đồng bộ nhằm giảm công lao động để tăng năng suất, chất lượng sản phẩm, nâng cao giá trị sản xuất.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Triển khai thực hiện có hiệu quả các chính sách hỗ trợ sản xuất của tỉnh; có chính sách hỗ trợ bổ sung phù hợp với điều kiện của địa phương để khuyến khích nông dân mở rộng sản xuất. Khuyến khích và tạo điều kiện cho các tổ chức, cá nhân mượn đất, thuê đất, quy vùng sản xuất tập trung để tạo sản phẩm nông sản hàng hoá mô lớn. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Sở Nông nghiệp và Môi trường giao Chi cục Trồng trọt và Bảo vệ thực vật chủ trì, phối hợp với các đơn vị liên quan kiểm tra, đôn đốc, nắm bắt tình hình sinh trưởng phát triển của cây trồng; thực hiện tốt công tác điều tra, dự tính dự báo diễn biến của các đối tượng sâu, bệnh hại trên đồng ruộng, chỉ đạo, hướng dẫn chăm sóc và phòng trừ kịp thời hiệu quả. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Trung tâm Khuyến nông tỉnh thực hiện tốt công tác tuyên truyền, tập huấn chuyển giao tiến bộ kỹ thuật trong sản xuất. Xây dựng các mô hình trình diễn, nhất là mô hình ứng dụng công nghệ cao nhằm đánh giá, lựa chọn những mô hình có hiệu quả để vào mở rộng áp dụng sản xuất.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '2025-12-04 03:19:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-phan-au-gieo-trong-vu-xuan-nam-2026-at-91-880-ha-70418901', '', 'Nguyễn Miền', 92, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.499517', 7, 11);
INSERT INTO `sync_articles` VALUES (334, '65113602', 'Triển khai Phong trào thi đua “Toàn dân bảo vệ an ninh Tổ quốc” trên địa bàn tỉnh Bắc...', 'Triển khai Phong trào thi đua “Toàn dân bảo vệ an ninh Tổ quốc” trên địa bàn tỉnh Bắc Ninh năm 2025', '/documents/37632/200628/Thidua.jpg/7fce2a67-928b-d17e-3cc0-2bf48a8686f0?t=1764751675559', '<p>(BNP) - Chủ tịch UBND tỉnh Bắc Ninh vừa ký ban hành <a href=\"/documents/37632/0/KH+thi+dua.pdf/8fd7560f-fb0e-6276-bfcb-59fde3e57716?t=1764751455263\">Kế hoạch số 152/KH-UBND</a> triển khai Phong trào thi đua “Toàn dân bảo vệ an ninh Tổ quốc” trên địa bàn tỉnh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/Thidua.jpg/7fce2a67-928b-d17e-3cc0-2bf48a8686f0?t=1764751675559\" style=\"height: 538px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch nhằm phát huy sức mạnh của cả hệ thống chính trị và Nhân dân trong sự nghiệp bảo vệ an ninh Tổ quốc; động viên các tập thể, cá nhân tích cực tham gia phong trào; tạo chuyển biến rõ nét về nhận thức, trách nhiệm của cấp ủy, chính quyền, MTTQ và các tổ chức đoàn thể đối với công tác bảo đảm an ninh trật tự.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nội dung trọng tâm của phong trào, các sở, ban, ngành, địa phương và doanh nghiệp thực hiện đồng bộ các nhiệm vụ bảo đảm an ninh trật tự; xây dựng chính quyền các cấp vững mạnh; nâng cao hiệu quả phong trào toàn dân bảo vệ an ninh Tổ quốc gắn với phát triển kinh tế - xã hội.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch nhấn mạnh yêu cầu nhân rộng mô hình tự quản, tự phòng, tự bảo vệ, tự hòa giải từ gia đình đến cộng đồng; đẩy mạnh ứng dụng khoa học - công nghệ và chuyển đổi số trong bảo đảm an toàn, an ninh mạng; củng cố lực lượng Công an nhân dân và lực lượng nòng cốt ở cơ sở.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch quy định <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">thi đua và khen thưởng đối với các cơ quan, đơn vị, địa phương và cá nhân khi</span></span></span>&nbsp;tham gia phong trào, từ công tác phối hợp, tuyên truyền, xây dựng mô hình, đến trách nhiệm trong bảo vệ an ninh trật tự.&nbsp;</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác khen thưởng được thực hiện hàng năm và tổng kết giai đoạn, bao gồm các hình thức: Cờ thi đua của Chính phủ, Cờ thi đua của UBND tỉnh, Huân chương Lao động, Bằng khen của Thủ tướng Chính phủ, Bằng khen của Chủ tịch UBND tỉnh và giấy khen của các sở, ngành, đoàn thể theo thẩm quyền.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phong trào được triển khai từ tháng 8/2025. Trong quý IV/2025, các sở, ban, ngành, đoàn thể và UBND các xã, phường ban hành kế hoạch cụ thể và tổ chức thực hiện; định kỳ hằng năm tiến hành sơ kết và tổng kết 5 năm/lần.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch yêu cầu tăng cường sự lãnh đạo của cấp ủy, chính quyền các cấp; đẩy mạnh tuyên truyền trên báo chí và mạng xã hội; phát hiện, biểu dương kịp thời các mô hình, cách làm sáng tạo. Hằng năm, Hội đồng Thi đua - Khen thưởng tỉnh sẽ tổ chức các đoàn kiểm tra, đánh giá tình hình thực hiện phong trào tại cơ sở.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban MTTQ Việt Nam tỉnh và các tổ chức chính trị - xã hội vận động hội viên tham gia phong trào. Ban Tuyên giáo và Dân vận Tỉnh ủy chỉ đạo công tác truyền thông. Công an tỉnh chủ trì đôn đốc, đánh giá việc triển khai và tổng hợp báo cáo UBND tỉnh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cơ quan báo chí của tỉnh mở chuyên trang, chuyên mục tuyên truyền phong trào. UBND các xã, phường ban hành văn bản chỉ đạo, tổ chức thực hiện và khen thưởng các điển hình tiêu biểu.</span></span></span></p>', '2025-12-04 00:30:00', 'https://bacninh.gov.vn/news/-/details/37632/trien-khai-phong-trao-thi-ua-toan-dan-bao-ve-an-ninh-to-quoc-tren-ia-ban-tinh-bac-ninh-nam-2025-65113602', '', 'Dương Thuỷ', 101, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.529335', 7, 11);
INSERT INTO `sync_articles` VALUES (335, '65477502', 'Phó Chủ tịch UBND tỉnh Phan Thế Tuấn: Liên minh HTX tỉnh cần phát huy vai trò nòng...', 'Phó Chủ tịch UBND tỉnh Phan Thế Tuấn: Liên minh HTX tỉnh cần phát huy vai trò nòng cốt trong tư vấn, hỗ trợ các HTX nâng cao hiệu quả sản xuất, kinh doanh', '/documents/37632/200628/IMG_9624.jpg/d2eeeff1-17e9-dc54-a9c7-20728c2bb8dc?t=1764755721850', '<p>(BNP) - Chiều 03/12, Liên minh Hợp tác xã (HTX) tỉnh Bắc Ninh tổng kết thực hiện Đề án&nbsp;“Hỗ trợ phát triển mô hình HTX ứng dụng công nghệ 4.0 trong quản lý điều hành hoạt động sản xuất kinh doanh (SXKD) và mô hình HTX nông nghiệp khởi nghiệp ứng dụng công nghệ cao trên địa bàn tỉnh Bắc Giang...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9624.jpg/d2eeeff1-17e9-dc54-a9c7-20728c2bb8dc?t=1764755721850\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch UBND tỉnh Phan Thế Tuấn (thứ 2 bên phải) tham quan gian hàng của các HTX trưng bày bên lề Hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham dự có đồng chí Phan Thế Tuấn, Phó chủ tịch UBND tỉnh; đại diện lãnh đạo một số Sở, ban, ngành liên quan, các xã, phường, HTX tiêu biểu trong tỉnh tham gia thực hiện 2 Đề án.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sau gần 05 năm triển khai, được sự quan tâm, tạo điều kiện của các sở, ngành địa phương, sự ủng hộ của các HTX và sự chủ động của Liên minh HTX tỉnh, nhiều nội dung của 2 Đề án hoàn thành cơ bản các mục tiêu đặt ra, góp phần hỗ trợ các HTX trong ứng dụng công nghệ thông tin, chuyển đổi số, nâng cao hiệu quả SXKD, tăng thu nhập cho các thành viên.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thực hiện Đề án 4.0 và khởi nghiệp, đến nay Liên minh HTX tỉnh phối hợp xây dựng được phần mềm App phục vụ công tác quản lý, điều hành hoạt động sản xuất kinh doanh của các HTX được cài đặt trên thiết bị thông minh (điện thoại, máy tính bảng, máy vi tính...) áp dụng cho 5 mô hình HTX ứng dụng công nghệ 4.0 của Đề án và nhân rộng được hơn 40 HTX trên địa bàn. Qua đó, hỗ trợ xây dựng cơ sở dữ liệu (số hóa) quy trình quản lý, điều hành hoạt động SXKD, giảm rủi ro, giảm hao hụt, tăng hiệu suất công việc, góp phần tạo tiền đề thực hiện số hóa trong hoạt động của các HTX trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9682.jpg/f50775de-8ebd-1df7-f134-8d0cd1e33ab6?t=1764755777658\" style=\"height: 590px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Phó Chủ tịch UBND tỉnh Phan Thế Tuấn</span> phát biểu chỉ đạo Hội nghị.<span lang=\"PT-BR\"></span></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span lang=\"PT-BR\">Ngoài ra, Đề án 4.0 và khởi nghiệp cũng hỗ trợ được 9 chủng loại máy móc cho 5 HTX với tổng kinh phí 2,5 tỷ đồng, hỗ trợ thu hút 17 lao động </span>trẻ <span lang=\"PT-BR\">về làm việc tại </span>các <span lang=\"PT-BR\">HTX với tổng kinh phí </span>1,3<span lang=\"PT-BR\"> t</span>ỷ đồng<span lang=\"PT-BR\">; hỗ trợ các HTX bán sản phẩm của đơn vị trên các sàn thương mại điện tử trong nước và quốc tế với tổng kinh phí 600 triệu đồng. </span>Nhiều <span lang=\"PT-BR\">HTX </span>hoạt động <span lang=\"PT-BR\">ngày một ổn định hiệu quả, </span>tiêu biểu <span lang=\"PT-BR\">như: HTX Nông nghiệp Thanh Hải, HTX sản xuất tiêu thụ vải sớm Phúc Hoà</span>, HTX nông nghiệp hữu cơ Bình Minh, <span lang=\"PT-BR\">HTX </span>nông nghiệp<span lang=\"PT-BR\"> Hồng Xuân</span> ...</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đối với Đề án quản trị, Liên minh HTX tỉnh đã tổ chức nhiều lớp tập huấn Luật HTX mới, phương án quản trị HTX, nghiệp vụ kế toán, kiểm toán đối với cán bộ và Ban kiểm soát trong các HTX tham gia Đề án và các HTX khác trên địa bàn tỉnh; hỗ trợ phần mềm quản lý các quỹ trong HTX, quản lý nguồn vốn, tài sản, phần mềm báo cáo theo các quy định hiện hành của Nhà nước, phầm mềm kế toán và các phần mềm quản lý chuyên dụng khác. 100% các HTX tham gia thực hiện Đề án thực hiện đúng các quy định của nhà nước về việc trích lập các loại quỹ bắt buộc khi phân phối thu nhập của HTX; thực hiện xây dựng lập các báo cáo kế toán, báo cáo thuế đầy đủ theo quy định của pháp luật hiện hành…</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9690222.jpg/261f29cb-df70-1022-eb2d-4136629c73c3?t=1764755808812\" style=\"height: 597px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch Liên minh HTX tỉnh Phạm Minh Hiền phát biểu tại Hội nghị.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham luận tại Hội nghị, các đại biểu tập trung đánh giá những kết quả đã đạt được sau gần 05 năm thực hiện 2 Đề án; chia sẻ những kinh nghiệm, phản ánh những khó khăn, vướng mắc và đề xuất giải pháp liên quan đến đẩy mạnh công tác tuyên truyền các chính sách của Trung ương, tỉnh về hỗ trợ các mô hình kinh tế tập thể; đẩy mạnh ứng dụng công nghệ thông tin, chuyển đổi số trong quản lý, hoạt động của các HTX; vai trò của cấp xã trong triển khai thực hiện 2 Đề án..</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phát biểu chỉ đạo tại Hội nghị, đồng chí Phan Thế Tuấn, Phó Chủ tịch UBND tỉnh biểu dương những kết quả Liên minh HTX tỉnh, các sở, ngành, địa phương và đặc biệt là các HTX đã tích cực tổ chức thực hiện, tham gia 02 Đề án, chủ động thay đổi tư duy, ứng dụng khoa học công nghệ, nâng cao hiệu quả quản lý, sản xuất, kinh doanh, tạo thu nhập, việc làm cho các thành viên HTX và nhân dân, góp phần thúc đẩy phát triển kinh tế - xã hội của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Để tiếp tục phát huy kết quả và đáp ứng yêu cầu phát triển của khu vực kinh tế tập thể trong bối cảnh hội nhập và chuyển đổi số, Phó Chủ tịch UBND tỉnh đề nghị Liên minh HTX tỉnh phát huy vai trò nòng cốt trong tư vấn, hỗ trợ HTX; tiếp tục bám sát cơ sở và xu hướng phát triển của xã hội để kịp thời tham mưu, đề xuất Tình ủy, UBND, HĐND, Ủy ban MTTQ tỉnh ban hành các chương trình, đề án hỗ trợ, tháo gỡ khó khăn, thúc đẩy các các HTX phát triển hiệu quả.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200628/IMG_9668.jpg/16a272fb-dc5a-250b-d6f8-b9a54e3b3c14?t=1764755843010\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Toàn cảnh Hội nghị.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trước mắt, tiến hành rà soát lại toàn bộ Chương trình, Đề án hỗ trợ HTX 02 tỉnh Bắc Ninh, Bắc Giang trước sáp nhập đã ban hành; trên cơ sở kết quả thực hiện giai đoạn 2021-2025, thực trạng, nhu cầu của các HTX, chủ động tham mưu UBND tỉnh ban hành các Chương trình, Đề án thực hiện trong giai đoạn 2026-2030; hoàn thành việc rà soát trong tháng 01/2026, báo cáo Chủ tịch UBND tỉnh xem xét, quyết định. Tăng cường đào tạo, tập huấn về quản trị HTX, kế toán, kiểm toán, chuyển đổi số; nhân rộng các mô hình HTX điển hình; đẩy mạnh xúc tiến thương mại tiêu thụ nông sản và chuẩn hóa quy trình sản xuất theo hướng bền vững.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các sở, ngành, chính quyền cơ sở tiếp tục tham mưu triển khai hiệu quả Luật Hợp tác xã. Chủ động bố trí nguồn lực từ ngân sách và lồng ghép các chương trình khác để tiếp tục hỗ trợ HTX, ưu tiên hỗ trợ và xây dựng mô hình HTX kiểu mới. Mặt khác, tăng cường công tác kiểm tra, đánh giá, kịp thời hỗ trợ tháo gỡ khó khăn cho các HTX trong quá trình triển khai nhiệm vụ mới; phát hiện, xử lý kịp thời các HTX hoạt động chưa tuân thủ quy định pháp luật, cạnh tranh thiếu lành mạnh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:normal\"><span style=\"font-family:Aptos,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đối với các HTX, cần phát huy tinh thần tự lực tự cường, chủ động đổi mới tư duy quản trị, tăng cường ứng dụng công nghệ 4.0 và chuyển đổi số trong mọi hoạt động; minh bạch tài chính, thực hiện đầy đủ chế độ kế toán, chế độ báo cáo và các nghĩa vụ tài chính đối với nhà nước theo quy định. Chủ động tìm kiếm thị trường, nâng cao năng lực xây dựng thương hiệu. Mở rộng liên kết, phát triển sản phẩm theo tiêu chuẩn chất lượng cao, hướng tới xuất khẩu đến thị trường toàn cầu trong bối cảnh thế giới phẳng như hiện nay</span></span></span>.</span></span></span></span></span></span></p>', '2025-12-03 09:53:00', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-phan-the-tuan-lien-minh-htx-tinh-can-phat-huy-vai-tro-nong-cot-trong-tu-van-ho-tro-cac-htx-nang-cao-hieu-qua-san-xuat-kinh-doanh-65477502', '', 'Hữu Thắng', 519, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.557847', 7, 11);
INSERT INTO `sync_articles` VALUES (336, '64955601', 'Samsung Việt Nam trao tặng 160 xe lăn cho người khuyết tật tỉnh Bắc Ninh', 'Samsung Việt Nam trao tặng 160 xe lăn cho người khuyết tật tỉnh Bắc Ninh', '/documents/37632/200628/Trao+xe+l%C4%83n+1.jpg/4c4482f3-53a9-73cb-256f-edeb467e8af4?t=1764749822556', '<p>(BNP) - Chiều 03/12, tại Trung tâm Kiểm soát bệnh tật Bắc Ninh số 1, Sở Y tế phối hợp với các Công ty Samsung tổ chức Chương trình Bánh xe nhân ái - Trao tặng xe lăn cho người khuyết tật trên địa bàn tỉnh Bắc Ninh năm 2025.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/Trao+xe+l%C4%83n+1.jpg/4c4482f3-53a9-73cb-256f-edeb467e8af4?t=1764749822556\" style=\"height: 468px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu trao tặng xe lăn và những phần quà cho người khuyết tật.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự chương trình có lãnh đạo Sở Y tế; lãnh đạo Văn phòng UBND tỉnh; đại diện các công ty: Samsung Electronics Việt Nam, Samsung SDV Việt Nam, Samsung Display Việt Nam và đại diện xã, phường, người khuyết tật trên địa bàn tỉnh.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span>Tại chương trình, lãnh đạo sở, ngành của tỉnh cùng đại diện 3 công ty thuộc Samsung Việt Nam đã trao 160 xe lăn và các phần quà cho người khuyết tật thuộc các xã, phường: Nhân Hòa, Võ Cường, Phật Tích, Liên Bão, Bố Hạ, Tam Tiến, Đa Mai và Cơ sở Bảo trợ xã hội tổng hợp tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những món quà thiết thực này thể hiện sự quan tâm, sẻ chia của Samsung Việt Nam, nhằm động viên, khích lệ người khuyết tật vượt qua khó khăn, hoà nhập cộng đồng, ổn định cuộc sống, góp phần thực hiện tốt chính sách an sinh xã hội trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2025 cũng là năm thứ 16 liên tiếp các công ty Samsung Việt Nam đồng hành cùng Bắc Ninh trong các hoạt động hỗ trợ người khuyết tật và các đối tượng yếu thế.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại chương trình, Phó Giám đốc Sở Y tế&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Văn Định</span></span></span>, cho biết toàn tỉnh hiện có gần 50.000 người khuyết tật đang hưởng trợ cấp xã hội hằng tháng, trong đó gần 12.000 người khuyết tật đặc biệt nặng và gần 38.000 người khuyết tật nặng.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/Trao+xe+l%C4%83n+2.jpg/af6df0a9-8b31-50c0-1fa2-a945bbb25244?t=1764749866679\" style=\"height: 563px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lãnh đạo Sở Y tế trao giấy chứng nhận tài trợ cho đại diện Công ty trách nhiệm hữu hạn Samsung Electronics Việt Nam.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian qua, Sở Y tế đã tham mưu, triển khai nhiều chương trình hỗ trợ người khuyết tật như: truyền thông, tư vấn - hỏi đáp, tập huấn kỹ năng sống để hòa nhập cộng đồng; tham mưu HĐND tỉnh mở rộng chính sách trợ giúp xã hội. Tỉnh đã ban hành nhiều nghị quyết quan trọng liên quan đến an sinh xã hội như: Quy định mức chuẩn trợ giúp xã hội; mức trợ cấp xã hội; hỗ trợ BHYT cho người mắc bệnh hiểm nghèo; hỗ trợ nhà ở cho hộ nghèo; chính sách trợ giúp các đối tượng bảo trợ xã hội và người cao tuổi có hoàn cảnh khó khăn.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí khẳng định, những năm qua, các công ty Samsung luôn là doanh nghiệp tiên phong đồng hành cùng tỉnh Bắc Ninh trong công tác an sinh xã hội: tạo hàng chục nghìn việc làm cho lao động địa phương; trao học bổng chương trình “Cặp lá yêu thương” trị giá từ 30-50 triệu đồng/học sinh nhằm hỗ trợ trẻ em có hoàn cảnh đặc biệt khó khăn tiếp tục đến trường. Đ</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">ồng thời mong muốn thời gian tới, tiếp tục nhận được sự đồng hành, hỗ trợ của Samsung Việt Nam, góp phần chung tay hỗ trợ người khuyết tật hòa nhập cộng đồng và ổn định cuộc sống.</span></span></span></p>', '2025-12-03 08:08:00', 'https://bacninh.gov.vn/news/-/details/37632/samsung-viet-nam-trao-tang-160-xe-lan-cho-nguoi-khuyet-tat-tinh-bac-ninh-64955601', '', 'Dương Thuỷ', 271, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.587765', 7, 11);
INSERT INTO `sync_articles` VALUES (337, '64848001', 'Triển khai hướng dẫn về một số cơ chế, chính sách đặc biệt tạo đột phá trong xây dựng...', 'Triển khai hướng dẫn về một số cơ chế, chính sách đặc biệt tạo đột phá trong xây dựng và tổ chức thi hành pháp luật', '/documents/37632/30456144/12.png/c879cebe-8119-db92-cab8-6ca00ba63faa?t=1764747754337', '<p>(BNP) – Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh vừa ký, ban hành văn bản số 5477/UBND-NC về việc triển khai thực hiện Nghị định số 289/2025/NĐ-CP của Chính phủ trên địa bàn tỉnh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/12.png/c879cebe-8119-db92-cab8-6ca00ba63faa?t=1764747754337\" style=\"height: 598px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tích cực tuyên truyền, quán triệt triển khai Nghị định số 289/2025/NĐ-CP đến toàn thể đội ngũ cán bộ, công chức, viên chức, người lao động thuộc quyền quản lý.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, để việc triển khai thực hiện Nghị định số 289/2025/NĐ-CP hướng dẫn thi hành Nghị quyết số 197/2025/QH15 của Quốc hội về một số cơ chế, chính sách đặc biệt tạo đột phá trong xây dựng và tổ chức thi hành pháp luật, đảm bảo đồng bộ, hiệu quả, kịp thời, Chủ tịch UBND tỉnh đề nghị các Sở, ngành, địa phương tổ chức tuyên truyền, phổ biến, quán triệt triển khai nội dung của Nghị định số 289/2025/NĐ-CP đến các phòng, đơn vị trực thuộc và toàn thể đội ngũ cán bộ, công chức, viên chức, người lao động thuộc quyền quản lý. Triển khai, thực hiện các nội dung theo quy định tại Nghị định phù hợp với chức năng, nhiệm vụ được giao.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, công tác xây dựng pháp luật thuộc nhiệm vụ chi ngân sách cấp nào do ngân sách cấp đó bảo đảm, hằng năm cùng với thời điểm lập dự toán ngân sách nhà nước, các cơ quan, đơn vị lập dự toán chi cho công tác xây dựng pháp luật gửi Sở Tài chính (đối với cấp tỉnh) và phòng Kinh tế (đối với cấp xã), phòng Kinh tế hạ tầng (đối với cấp phường) tổng hợp trình cấp có thẩm quyền bố trí kinh phí theo quy định.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Văn phòng Đoàn ĐBQH và HĐND tỉnh, Sở Tư pháp có trách nhiệm rà soát, lập danh sách người tham gia công tác xây dựng pháp luật, báo cáo Chủ tịch HĐND tỉnh, Chủ tịch UBND tỉnh phê duyệt làm cơ sở đề xuất cấp kinh phí cho năm 2025 và các năm tiếp theo.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch UBND tỉnh giao Sở Tư pháp có trách nhiệm hướng dẫn về các nhiệm vụ, hoạt động trong xây dựng pháp luật, tổ chức thi hành pháp luật được áp dụng cơ chế, chính sách đặc biệt quy định tại Nghị định; tổ chức các buổi tập huấn chuyên sâu về công tác xây dựng pháp luật. Đồng thời, chủ trì, phối hợp với các cơ quan, đơn vị có liên quan tham mưu một số cơ chế, chính sách đặc biệt tạo đột phá trong xây dựng và tổ chức thi hành pháp luật tại Nghị định số 289/2025/NĐ-CP trên địa bàn tỉnh; thực hiện theo dõi, đôn đốc việc triển khai thực hiện Nghị định số 289/2025/NĐ-CP và tổng hợp, đề xuất, báo cáo Bộ Tư pháp, Chủ tịch UBND tỉnh theo quy định./.</span></span></span></p>', '2025-12-03 07:41:00', 'https://bacninh.gov.vn/news/-/details/37632/trien-khai-huong-dan-ve-mot-so-co-che-chinh-sach-ac-biet-tao-ot-pha-trong-xay-dung-va-to-chuc-thi-hanh-phap-luat-64848001', '', 'Nguyễn Nhàn', 219, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.619588', 7, 11);
INSERT INTO `sync_articles` VALUES (338, '63796501', 'Phát triển Trung tâm Giáo dục quốc phòng và an ninh, Trường Cao đẳng Bắc Giang trở...', 'Phát triển Trung tâm Giáo dục quốc phòng và an ninh, Trường Cao đẳng Bắc Giang trở thành cơ sở trọng điểm của vùng Trung du và miền núi phía Bắc', '/documents/37632/30456144/3-2.png/e40f1a20-0ede-a0fb-bf0b-bb2116b1d3b2?t=1764730381880', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Lê Xuân Lợi vừa ký, ban hành <a href=\"/documents/37632/30456144/1594-Q%C4%90-UBND.pdf/ffcd8c17-1910-f216-4474-eff726775d5d?t=1764730567335\">Quyết định</a> số 1594/QĐ-UBND phê duyệt <a...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456144/3-2.png/e40f1a20-0ede-a0fb-bf0b-bb2116b1d3b2?t=1764730381880\" style=\"height: 642px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Buổi học GDQP&amp;AN của Trường Cao đẳng Bắc Giang.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Việc ban hành Đề án Phát triển Trung tâm Giáo dục quốc phòng và an ninh, Trường Cao đẳng Bắc Giang thời kỳ 2021 - 2030, tầm nhìn đến năm 2045 nhằm đảm bảo các điều kiện về vật chất, con người đáp ứng quy mô, nâng cao chất lượng đào tạo GDQP&amp;AN trong giai đoạn mới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Mục tiêu cụ thể đến năm 2030 là đầu tư cơ sở hạ tầng, vật chất; mở rộng quy mô, nâng cao chất lượng đào tạo và đầu tư ứng dụng công nghệ thông tin. Tầm nhìn đến năm 2045, phát triển Trung tâm GDQP&amp;AN Trường Cao đẳng Bắc Giang trở thành cơ sở GDQP&amp;AN trọng điểm của vùng Trung du và miền núi phía Bắc, liên kết đào tạo với các trường đại học, học viện; đạt chuẩn quốc gia về cơ sở vật chất, đội ngũ và chương trình.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đề án được chia thành hai giai đoạn chính. Giai đoạn 1 (Ưu tiên), từ năm 2025 - 2030 là giai đoạn trọng điểm, tập trung hoàn thành việc sử dụng nguồn vốn đầu tư phát triển và chuẩn hóa Trung tâm theo tiêu chuẩn quốc gia; hoàn thành toàn bộ thủ tục pháp lý để có thể chính thức khởi công và giải ngân vốn. Đồng thời, xây dựng cơ sở vật chất, mua sắm trang thiết bị, và phát triển nhân lực. Giai đoạn 2 (Tầm nhìn), từ năm 2031 - 2045, phát triển chiều sâu, bền vững, hiện đại hóa về quy mô đào tạo, hiện đại hóa trang thiết bị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đề án đưa ra các nhiệm vụ trọng tâm gồm: Xây dựng và hoàn thiện cơ sở vật chất, thao trường, bãi tập, ký túc xá; điều chỉnh lại các đơn vị trực thuộc Trung tâm; đổi mới chương trình, giáo trình đào tạo, tăng cường ứng dụng công nghệ hiện đại, làm chủ nền tảng công nghệ số; tổ chức giảng dạy, huấn luyện GDQP&amp;AN cho sinh viên Trường Cao đẳng Bắc Giang và các đơn vị liên kết; tăng cường công tác nghiên cứu khoa học, mỗi năm có từ 2 đến 3 đề tài, sáng kiến kinh nghiệm cấp cơ sở, cấp tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các nhóm giải pháp thực hiện gồm tăng cường giáo dục chính trị tư tưởng, kiện toàn bộ máy, phát triển đội ngũ giảng viên, hiện đại hóa hạ tầng, đa dạng hóa nguồn lực tài chính, đổi mới đào tạo và nâng cao nghiên cứu khoa học, đẩy mạnh truyền thông…/.</span></span></span></p>', '2025-12-03 02:52:00', 'https://bacninh.gov.vn/news/-/details/37632/phat-trien-trung-tam-giao-duc-quoc-phong-va-an-ninh-truong-cao-ang-bac-giang-tro-thanh-co-so-trong-iem-cua-vung-trung-du-va-mien-nui-phia-bac-63796501', '', 'Linh Ngọc', 498, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-12-08 08:18:09.648336', 7, 11);
INSERT INTO `sync_articles` VALUES (339, '75965903', 'Ngập lụt ở Lâm Đồng: Quốc lộ 1A bị phong tỏa, ứng cứu khẩn cấp 3 tàu bị trôi', 'Ngập lụt ở Lâm Đồng: Quốc lộ 1A bị phong tỏa, ứng cứu khẩn cấp 3 tàu bị trôi', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/z729022271479449c048b00bf6e4601ba6af1da4a0b4d3-17649019440201610017270.jpg', '<p>Mưa lớn kéo dài khiến nhiều khu vực ven biển Lâm Đồng chìm sâu trong nước, buộc lực lượng chức năng phong tỏa nhiều đoạn Quốc lộ 1A trong tối 4/12. Hơn 1.000 hộ dân phải di dời khẩn cấp; giao thông đường bộ, đường sắt và vận tải biển đều bị gián đoạn, nhiều tàu cá trôi dạt và hàng nghìn căn nhà...', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/z729022271479449c048b00bf6e4601ba6af1da4a0b4d3-17649019440201610017270.jpg\" target=\"_blank\" title=\"Cán bộ, chiến sĩ Ban CHQS xã Sông Lũy hỗ trợ người dân di dời tài sản tới nơi an toàn.\"><img alt=\"Ngập lụt ở Lâm Đồng: Quốc lộ 1A bị phong tỏa, ứng cứu khẩn cấp 3 tàu bị trôi- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/z729022271479449c048b00bf6e4601ba6af1da4a0b4d3-17649019440201610017270.jpg\" h=\"495\" height=\"495\" id=\"img_921228315468333056\" loading=\"lazy\" photoid=\"921228315468333056\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/z729022271479449c048b00bf6e4601ba6af1da4a0b4d3-17649019440201610017270.jpg\" title=\"Ngập lụt ở Lâm Đồng: Quốc lộ 1A bị phong tỏa, ứng cứu khẩn cấp 3 tàu bị trôi- Ảnh 1.\" type=\"photo\" w=\"870\" width=\"870\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cán bộ, chiến sĩ Ban CHQS xã Sông Lũy hỗ trợ người dân di dời tài sản tới nơi an toàn.</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tối ngày 4/12, lực lượng công an đã phong tỏa tuyến đường quốc lộ 1A do ngập sâu đoạn qua địa bàn xã Hàm Thắng (Lâm Đồng).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, đường quốc lộ 1A đoạn qua phường Hàm Thắng nhiều đoạn bị ngập sâu, các phương tiện không thể lưu thông. Để đảm bảo an toàn, lực lượng chức năng phong tỏa tuyến đường không cho các phương tiện lưu thông. Cùng với phường Hàm Thắng, tuyến quốc lộ 1A qua địa bàn xã Hồng Sơn, xã Lương Sơn cũng bị ngập khiến các phương tiện không thể lưu thông. Tại quốc lộ 28 đoạn qua địa bàn xã Hàm Liêm cũng bị ngập, các phương tiện lưu thông khó khăn; nhiều xe mô tô bị chết máy do ngập nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đến 19 giờ ngày 4/12, do ảnh hưởng mưa lớn kéo dài kết hợp với việc các hồ thủy lợi xả lũ, nhiều khu vực ven biển tại tỉnh Lâm Đồng như: Hàm Thuận, Hàm Thuận Bắc, Hàm Liêm, Lương Sơn, Hàm Thắng… tiếp tục ngập sâu trong nước.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lâm Đồng: Tạm ngừng tuyến vận tải hành khách từ Phan Thiết ra đặc khu Phú Quý</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Do tình hình thời tiết xấu, chiều 4/12, các tàu khai thác tuyến vận tải hành khách từ Phan Thiết ra đặc khu Phú Quý, tỉnh Lâm Đồng đã có thông báo tới hành khách về việc tạm ngưng và thay đổi lịch hoạt động.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể, theo thông báo của Công ty cổ phần Tàu cao tốc Superdong- Kiên Giang cho biết, theo bản tin dự báo thời tiết, tại khu vực biển Phan Thiết- Phú Quý đang có sóng cao, gió lớn vượt mức an toàn khai thác. Vì sự an toàn tuyệt đối của hành khách, Superdong tạm ngưng hoạt động tuyến Phan Thiết- Phú Quý trong hai ngày 6 và ngày 7/12.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với các khách hàng đã đặt cọc hoặc thanh toán 100% tiền vé, đến ngày khởi hành nếu tàu tạm ngừng hoạt động do thời tiết, Superdong sẽ hoàn lại phần tiền vé khách hàng đã thanh toán hoặc đổi vé qua ngày hoạt động tiếp theo. Superdong sẽ tiếp tục theo dõi tình hình và cập nhật lịch hoạt động mới nhất ngay khi thời tiết ổn định trở lại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, Công ty cổ phần Tàu cao tốc Phú Quốc cũng ra thông báo việc tạm dừng vận hành tuyến Phan Thiết- Phú Quý và ngược lại từ ngày 6- 8/12 vì lý do thời tiết xấu. Dự kiến ngày 9/12, đơn vị sẽ vận hành lại tuyến vận tải nói trên theo lịch đăng ký. Việc tạm dừng khai thác nhằm đảm bảo an toàn cho du khách trong quá trình di chuyển.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lâm Đồng cứu khẩn cấp 3 tàu trôi ra cửa biển Phú Hài</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng ngày 5/12, Trung tá Võ Duy Thạnh, Đồn trưởng Đồn biên phòng Thanh Hải xác nhận, đã hỗ trợ cấp cứu khẩn cấp 1 tàu dầu và 2 tàu hậu cần bị đứt neo, trôi ra cửa biển Phú Hài (phường Phú Thuỷ).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, vụ việc xảy ra lúc 4 giờ ngày 5/12. Dưới sức ép của dòng chảy nước lũ, các tàu đã bị đứt neo trôi dạt ra cửa biển Phú Hài. Các tàu gặp nạn gồm tàu dầu Hiệp Thịnh 07 và hai tàu hậu cần BTh 93989 TS; BTh 93999 TS. Nhận được tin báo, Đồn Biên phòng Thanh Hải đã huy động 2 tàu cá và 10 ngư dân làm nghề tìm kiếm trong khu vực vùng biển vịnh Phan Thiết hỗ trợ cứu tàu bị trôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đến 5h30 sáng, lực lượng biên phòng và ngư dân đã tìm thấy 3 tàu trôi. Chủ tàu đã tiếp cận phương tiện và lên tàu khắc phục sự cố. Hiện 3 tàu đang ở khu vực biển Đồi Dương cách bờ khoảng 400m, khu vực thời tiết gió nhẹ, biển êm, người và phương tiện đảm bảo an toàn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước đó, lực lượng Đồn Biên phòng Thanh Hải đã tập trung ứng cứu tàu cá BTh95456 TS bị trôi dạt vào bở biển Đồi Dương (phường Phan Thiết) mắc cạn. Đến 1 giờ 30 phút ngày 5/12, Đồn Biên phòng Thanh Hải đưa được tàu vào bờ an toàn.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Hơn 3.200 nhà bị ngập</b></span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng ngày 5/12, Ban Chỉ huy phòng thủ dân sự tỉnh Lâm Đồng có báo cáo nhanh tình hình thiệt hại do mưa lũ xảy ra trên địa bàn. Qua thống kê sơ bộ từ các địa phương, đến sáng ngày 5/12 có 1 người chết (ông Nguyễn Văn Tạc, 60 tuổi, công dân tổ 3 thôn Hội Nhơn, xã Hàm Liêm đã tự ý đi về nhà từ nơi xã bố trí nơi ở an toàn và đã đuối nước).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thống kê có khoảng 3.296 căn nhà bị ngập lụt, ảnh hưởng; nhiều tài sản bị hư hỏng. Hiện nay các khu vực vẫn đang tiếp tục ngập. Ngập nặng nhất là tại các xã, phường ven biển tỉnh Lâm Đồng như: Ngập nặng nhất là tại các xã, phường ven biển tỉnh Lâm Đồng như: Hàm Liêm, Lương Sơn, Liên Hương, Hàm Thắng… Có hơn 1.000 hộ dân bị ngập sâu trong nước phải di dời khẩn cấp đến nơi an toàn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thiệt hại về sản xuất nông nghiệp diễn ra trên diện rộng, tổng diện tích sản xuất nông nghiệp bị ngập lụt, ảnh hưởng 3.357 ha; tàu cá bị đứt neo, chìm 24 tàu; 4.053 con gia súc, gia cầm bị chết, cuốn trôi; thiệt hại 300m2 diện tích ao nuôi cá…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện các đơn vị đang tiếp tục duy trì chế độ trực ban nghiêm túc 24/24h, theo dõi chặt chẽ tình hình, diễn biến thời tiết trong khu vực, chủ động thông tin, thông báo, cảnh báo kịp đến chính quyền địa phương và người dân để phòng, tránh thiệt hại có thể xảy ra; kịp thời tổng hợp tình hình ảnh hưởng, thiệt hại và đôn đốc, hướng dẫn các địa phương trong công tác phòng, tránh và khắc phục hậu quả thiên tai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước đó, ứng phó với cơn bão số 15, tỉnh Lâm Đồng đã thực hiện lệnh cấm biển từ 7 giờ ngày 28/11 đến ngày 1/12. Tất cả tàu du lịch, tàu vận tải, phương tiện khai thác đánh bắt thủy hải sản đều bị cấm hoạt động trong thời điểm đó.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng tại Lâm Đồng chiều 4/12, cơ quan chức năng tỉnh Lâm Đồng cho biết, sau sự cố sạt lở trên một số tuyến đường vào Đà Lạt (trung tâm tỉnh lỵ Lâm Đồng), đến nay đã khắc phục và thông tuyến đối với đèo Mimosa. Sở Xây dựng Lâm Đồng hiện cấm người và phương tiện lưu thông qua đèo Prenn, nhưng có thể lưu thông bình thường qua các đèo Mimosa, Sacom và Tà Nung.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Lâm Đồng giải tỏa tàu qua khu gian đường sắt Ma Lâm - Long Thạnh tại Lâm Đồng. Cụ thể, đến 16 giờ ngày 4/12, ngành đường sắt đã rút 4 toa tàu hàng tải trọng gần 200 tấn án ngữ giữ cầu Km 1531+123 tại Lâm Đồng, đồng thời giải tỏa khu gian đường sắt Ma Lâm - Long Thạnh. Tàu SE7 tuyến Hà Nội - TP. Hồ Chí Minh chạy lại sau 90 phút nằm chờ tại ga Sông Mao.</span></span></span></p>', '2025-12-05 03:15:00', 'https://bacninh.gov.vn/news/-/details/37632/ngap-lut-o-lam-ong-quoc-lo-1a-bi-phong-toa-ung-cuu-khan-cap-3-tau-bi-troi-75965903', '', 'Theo Chinhphu.vn', 19, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.573118', 8, 11);
INSERT INTO `sync_articles` VALUES (340, '75961704', 'Lâm Đồng: Mưa lớn diện rộng gây ngập hơn 6.000 ngôi nhà', 'Lâm Đồng: Mưa lớn diện rộng gây ngập hơn 6.000 ngôi nhà', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/ngap-nuoc-10-17649015106601975394564.jpg', '<p>Ban Chỉ huy Phòng thủ dân sự tỉnh Lâm Đồng cho biết đã di dời 3.680 hộ dân đến nơi an toàn.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/ngap-nuoc-10-17649015106601975394564.jpg\" target=\"_blank\" title=\"Tỉnh Lâm Đồng cho biết đến nay đã ghi nhận hơn 17 điểm sạt lở, 4 cầu, cống dân sinh hư hỏng\"><img alt=\"Lâm Đồng: Mưa lớn diện rộng gây ngập hơn 6.000 ngôi nhà- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/ngap-nuoc-10-17649015106601975394564.jpg\" h=\"496\" id=\"img_921225954745790464\" loading=\"lazy\" photoid=\"921225954745790464\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/ngap-nuoc-10-17649015106601975394564.jpg\" style=\"width: 800px; height: 496px;\" title=\"Lâm Đồng: Mưa lớn diện rộng gây ngập hơn 6.000 ngôi nhà- Ảnh 1.\" type=\"photo\" w=\"800\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Lâm Đồng cho biết đến nay đã ghi nhận hơn 17 điểm sạt lở, 4 cầu, cống dân sinh hư hỏng</span></span></span></p>\n</figcaption>\n</figure>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lũ trên các sông giảm&nbsp;</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ đêm 3/12 đến sáng 4/12/2025, nhiều khu vực trên địa bàn tỉnh Lâm Đồng xuất hiện mưa to đến rất to. Một số nơi ghi nhận lượng mưa đặc biệt lớn như Tuy Phong 202 mm, Tân Hải 162 mm, Sơn Điền 148 mm, D\'Ran 143 mm, Hàm Thuận Bắc 122 mm, Phước Hội 119 mm, Xuân Trường (Đà Lạt) 118 mm…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ chiều 4/12 đến sáng 5/12, mưa giảm mạnh, nhiều nơi không ghi nhận mưa. Dự báo từ 5–10/12, toàn tỉnh chủ yếu không mưa, cục bộ có mưa nhỏ dưới 10 mm.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên sông Sông Lũy và sông Cam Ly, mực nước lũ tiếp tục xuống. Lúc 7h ngày 5/12, mực nước tại trạm Thanh Bình (sông Cam Ly) ở mức 832,85 m, trên báo động II 0,85 m (đỉnh lũ trước đó 834,3 m).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên thiệt hại cũng rất nặng nề, theo thống kê đến trưa 5/12, toàn tỉnh ghi nhận 6.195 căn nhà bị ngập lụt, ảnh hưởng, tăng mạnh so với ngày 4/12; trong đó 3 căn nhà bị hư hỏng. Nhiều địa phương vẫn ngập sâu như Hàm Liêm (400 nhà), Lương Sơn (794 nhà), Hàm Thuận Bắc (612 nhà, 2 nhà sập), Hàm Thuận (809 nhà), phường Hàm Thắng (2.800 nhà)… Đã có 1 người tử vong trong đợt ngập lụt này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thiệt hại nông nghiệp - thủy sản tiếp tục tăng. Tổng diện tích cây trồng bị ảnh hưởng khoảng 4.128 ha; nhiều khu vực ngập nặng như Hàm Thuận Bắc 865 ha, Hiệp Thạnh 400 ha, Lương Sơn 65 ha, Sông Lũy 300 ha…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thiệt hại về chăn nuôi và thủy sản gồm 4.053 con gia súc, gia cầm bị cuốn trôi, 24 tàu cá chìm, cùng 300 m² ao nuôi bị hư hại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều tuyến đường bị sạt lở, ách tắc. Tỉnh Lâm Đồng cho biết đến nay đã ghi nhận hơn 17 điểm sạt lở, 4 cầu, cống dân sinh hư hỏng; nhiều tuyến đường bị chia cắt. Một số điểm nghiêm trọng gồm: Quốc lộ 20 (Km226–Km265+500) sạt lở taluy dương, taluy âm; đèo Mimosa và Prenn bị đất đá vùi lấp, giao thông tê liệt; Quốc lộ 27 và 27C nhiều vị trí sạt lở lớn…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ước tổng thiệt hại bước đầu hơn 113 tỷ đồng, tiếp tục tăng khi các địa phương rà soát thêm.</span></span></span></p>\n\n<h4 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bảo đảm an toàn hồ chứa</span></span></span></h4>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một số hồ thủy lợi đang xả điều tiết như Sông Quao (46 m³/s), Suối Đá (31 m³/s), Lòng Sông (193 m³/s), Phan Dũng (189 m³/s). Lưu lượng nước về có xu hướng giảm, riêng hồ Sông Quao có thể tiếp tục tăng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hồ thủy điện vận hành theo quy trình, an toàn; hồ Đơn Dương đang xả 150 m³/s xuống hạ du.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các lực lượng công an, quân đội, dân quân được huy động trực 24/24h, tổ chức cảnh giới, phong tỏa khu vực nguy hiểm, hỗ trợ người dân di dời, cung cấp lương thực, nước uống tại các điểm tạm trú.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ban Chỉ huy Phòng thủ dân sự tỉnh Lâm Đồng đã yêu cầu các địa phương: Duy trì trực ban 24/24h, cập nhật diễn biến thời tiết; Tăng cường sơ tán tại khu vực ngập sâu, có nguy cơ sạt lở; Cắm biển cảnh báo, phân luồng giao thông, tạm cấm lưu thông tại điểm nguy hiểm; Tập trung khắc phục sạt lở, mở lại các tuyến đường huyết mạch; Theo dõi chặt chẽ việc vận hành hồ chứa thủy lợi, thủy điện; Tiếp tục thống kê thiệt hại và hỗ trợ người dân khắc phục.</span></span></span></p>', '2025-12-05 03:13:00', 'https://bacninh.gov.vn/news/-/details/37632/lam-ong-mua-lon-dien-rong-gay-ngap-hon-6-000-ngoi-nha-75961704', '', 'Theo Chinhphu.vn', 10, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.608828', 8, 11);
INSERT INTO `sync_articles` VALUES (341, '75935304', 'Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên...', 'Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/tiep-nhan-ung-ho-17648549630881026255749.jpg', '<p>Chiều 4/12, tại Hà Nội, bà Bùi Thị Minh Hoài, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam đã tiếp Đại sứ Trung Quốc tại Việt Nam, đồng thời tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai, lũ lụt.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/tiep-nhan-ung-ho-17648549630881026255749.jpg\" target=\"_blank\" title=\"Bà Bùi Thị Minh Hoài, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam tiếp nhận 500.000 USD từ Chính phủ Trung Quốc ủng hộ nhân dân Việt Nam khắc phục hậu quả thiên tai - Ảnh: VGP/Toàn Thắng\"><img alt=\"Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/tiep-nhan-ung-ho-17648549630881026255749.jpg\" h=\"432\" id=\"img_921030385239162880\" loading=\"lazy\" photoid=\"921030385239162880\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/tiep-nhan-ung-ho-17648549630881026255749.jpg\" style=\"width: 648px; height: 432px;\" title=\"Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai- Ảnh 1.\" type=\"photo\" w=\"648\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà Bùi Thị Minh Hoài, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam tiếp nhận 500.000 USD từ Chính phủ Trung Quốc ủng hộ nhân dân Việt Nam khắc phục hậu quả thiên tai - Ảnh: VGP/Toàn Thắng</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, Đại sứ Trung Quốc Hà Vĩ chuyển lời chào thân thiết, lời chúc tốt đẹp của Ủy viên Thường vụ Bộ Chính trị, Chủ tịch Chính hiệp toàn quốc Trung Quốc Vương Hộ Ninh đến Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Bùi Thị Minh Hoài; chúc mừng bà Bùi Thị Minh Hoài được hiệp thương cử giữ chức Chủ tịch Ủy ban Trung ương MTTQ Việt Nam khóa X.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước những thiệt hại nặng nề do mưa lũ gây ra đối với nhân dân các tỉnh miền Trung, Tây Nguyên, Chính phủ Trung Quốc đã gửi số tiền 500.000 USD thông qua Đại sứ quán Trung Quốc tại Việt Nam chuyển đến Ủy ban Trung ương MTTQ Việt Nam để hỗ trợ khắc phục hậu quả thiên tai, lũ lụt tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Hà Vĩ khẳng định, số tiền này tuy không lớn nhưng thể hiện tình cảm của nhân dân Trung Quốc gửi đến nhân dân Việt Nam, với mong muốn cùng góp phần \"chia ngọt sẻ bùi\", giúp nhân dân Việt Nam vượt qua khó khăn của bão lũ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Hà Vĩ nhắc tới chuyến thăm mang tính lịch sử của Tổng Bí thư, Chủ tịch nước Tập Cận Bình đến Việt Nam vào tháng 4/2025 và khẳng định chuyến thăm đã thắt chặt hơn nữa tình hữu nghị giữa hai Đảng, hai Nhà nước Trung Quốc và Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng theo Đại sứ Hà Vĩ, cùng với hoạt động trao đổi đoàn cấp cao, thời gian qua, nhiều doanh nghiệp Trung Quốc đã sang Việt Nam tìm kiếm cơ hội hợp tác đầu tư, tập trung vào lĩnh vực khoa học công nghệ cao, phát triển trí tuệ nhân tạo - điều này đang trở thành xu thế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều dự án hợp tác quy mô lớn giữa hai nước đang được triển khai như: Tuyến đường sắt Hà Nội - Lào Cai - Hải Phòng; dự án Cung hữu nghị Việt - Trung đang tiếp tục triển khai sửa chữa; hoạt động giao lưu nhân văn giữa hai nước đang triển khai tích cực, điển hình như việc triển khai \"Hành trình đỏ nghiên cứu, học tập của thanh niên\" tại Trung Quốc với sự tham gia của 1.000 đại biểu Việt Nam là cán bộ trẻ, văn nghệ sĩ trẻ, công nhân trẻ và thanh niên nông thôn tiêu biểu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đây là hoạt động đối ngoại có ý nghĩa quan trọng, góp phần tăng cường hiểu biết, bồi dưỡng lý tưởng và thắt chặt tình hữu nghị giữa tuổi trẻ hai nước Việt Nam - Trung Quốc.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khuôn khổ hợp tác giữa hai nước, với vai trò quan trọng của MTTQ Việt Nam, Đại sứ Hà Vĩ mong muốn Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Bùi Thị Minh Hoài tiếp tục phối hợp chặt chẽ với Đại sứ quán, Chính hiệp toàn quốc Trung Quốc để củng cố mối quan hệ giữa hai nước, nhất là trong lĩnh vực giao lưu nhân văn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Bùi Thị Minh Hoài gửi lời cảm ơn chân thành đối với Đảng, Nhà nước, nhân dân Trung Quốc đã dành sự quan tâm sâu sắc tới nhân dân Việt Nam trong thời điểm khó khăn do những hậu quả của thiên tai, bão lũ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhấn mạnh khoản hỗ trợ 500.000 USD được Đại sứ Hà Vĩ trao thực sự là món quà vô cùng ý nghĩa, không chỉ là sự hỗ trợ vật chất quan trọng tiếp thêm sức mạnh để nhân dân Việt Nam sớm vượt qua khó khăn, ổn định đời sống mà còn là lời động viên, sự sẻ chia của Đảng, Nhà nước, nhân dân Trung Quốc đối với nhân dân Việt Nam. Đó chính là biểu hiện của tình đoàn kết, hữu nghị thủy chung được dày công vun đắp bởi Chủ tịch Hồ Chí Minh và Chủ tịch Mao Trạch Đông.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Bùi Thị Minh Hoài nêu rõ, thời gian qua, quan hệ hai Đảng, hai nước duy trì đà phát triển mạnh mẽ, tích cực. Hoạt động trao đổi đoàn Lãnh đạo cấp cao giữa hai Đảng, hai nước được tăng cường, đặc biệt là các chuyến thăm song phương của Tổng Bí thư, Chủ tịch nước Tô Lâm (tháng 8/2024) và Tổng Bí thư, Chủ tịch nước Tập Cận Bình (tháng 4/2025), cũng như hoạt động tiếp xúc cấp cao vào cuối tháng 8 và đầu tháng 9/2025 khi lần đầu tiên trong lịch sử, 3 đồng chí Lãnh đạo chủ chốt hai bên thăm và dự các hoạt động kỷ niệm sự kiện đa phương quan trọng tại mỗi nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhấn mạnh tới hoạt động của&nbsp;Ủy ban Trung ương MTTQ Việt Nam và Chính hiệp toàn quốc Trung Quốc thời gian qua, Chủ tịch Bùi Thị Minh Hoài cho biết hai bên đã luôn duy trì hoạt động trao đổi đoàn cấp cao và phối hợp tổ chức các hội thảo chia sẻ kinh nghiệm và các hoạt động giao lưu nhân dân, nổi bật là Chương trình giao lưu hữu nghị giữa Ủy ban Trung ương MTTQ Việt Nam với Chính hiệp toàn quốc Trung Quốc và Mặt trận Tổ quốc - Chính hiệp các tỉnh/khu tự trị biên giới hai nước được tổ chức vào các năm 2019, 2023 và tháng 4/2025.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/trao-doi-1764855211907494592429.jpg\" target=\"_blank\" title=\"Bà Bùi Thị Minh Hoài, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam trao đổi với ông Hà Vĩ, Đại sứ Trung Quốc tại Việt Nam - Ảnh: VGP/Toàn Thắng\"><img alt=\"Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai- Ảnh 5.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/trao-doi-1764855211907494592429.jpg\" h=\"432\" height=\"432\" id=\"img_921031428164485120\" loading=\"lazy\" photoid=\"921031428164485120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/trao-doi-1764855211907494592429.jpg\" title=\"Tiếp nhận 500.000 USD từ Chính phủ Trung Quốc hỗ trợ Việt Nam khắc phục hậu quả thiên tai- Ảnh 5.\" type=\"photo\" w=\"648\" width=\"648\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà Bùi Thị Minh Hoài, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam trao đổi với ông Hà Vĩ, Đại sứ Trung Quốc tại Việt Nam - Ảnh: VGP/Toàn Thắng</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian tới, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Bùi Thị Minh Hoài mong muốn hai bên tiếp tục đẩy mạnh giao lưu nhân văn, ủng hộ các tổ chức xã hội, đoàn thể quần chúng tăng cường giao lưu, hợp tác.</span></span></span></p>', '2025-12-05 03:03:00', 'https://bacninh.gov.vn/news/-/details/37632/tiep-nhan-500-000-usd-tu-chinh-phu-trung-quoc-ho-tro-viet-nam-khac-phuc-hau-qua-thien-tai-75935304', '', 'Theo Chinhphu.vn', 9, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.644036', 8, 11);
INSERT INTO `sync_articles` VALUES (342, '75908604', 'Ngành nông nghiệp vực dậy sản xuất sau thiên tai', 'Ngành nông nghiệp vực dậy sản xuất sau thiên tai', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/vuonuom2-17648992733071765412862.jpg', '<p>Lĩnh vực trồng trọt và bảo vệ thực vật cùng với lĩnh vực thủy sản đã triển khai các hoạt động khôi phục sản xuất trên cả nước sau thời gian dài bão, lũ vừa qua.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/vuonuom2-17648992733071765412862.jpg\" target=\"_blank\" title=\"Vườn ươm giống cây lâm nghiệp - Ảnh: VGP/Đỗ Hương\"><img alt=\"Ngành nông nghiệp vực dậy sản xuất sau thiên tai- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/5/vuonuom2-17648992733071765412862.jpg\" h=\"1014\" id=\"img_921216573476536320\" loading=\"lazy\" photoid=\"921216573476536320\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/5/vuonuom2-17648992733071765412862.jpg\" style=\"width: 900px; height: 675px;\" title=\"Ngành nông nghiệp vực dậy sản xuất sau thiên tai- Ảnh 1.\" type=\"photo\" w=\"1352\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vườn ươm giống cây lâm nghiệp - Ảnh: VGP/Đỗ Hương</span></span></span></p>\n</figcaption>\n</figure>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Xuất cấp hơn 3.400 tấn giống cây trồng</b></span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ông Nguyễn Quốc Mạnh, Phó Cục trưởng Cục Trồng trọt và Bảo vệ thực vật, cho biết căn cứ Nghị định 09/2025/NĐ-CP về chính sách hỗ trợ khôi phục sản xuất nông nghiệp sau thiên tai, đơn vị đã tham mưu Bộ Nông nghiệp và Môi trường xuất cấp 3.400,025 tấn giống cho các địa phương bị thiệt hại. Trong đó, Thừa Thiên - Huế được hỗ trợ hai đợt với tổng cộng 292,09 tấn, Quảng Trị 190 tấn, Hà Tĩnh 340,06 tấn và Thanh Hóa 1.601,41 tấn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện Cục đang phối hợp với các Sở Nông nghiệp và Môi trường tại Đắk Lắk, Lâm Đồng, Quảng Ngãi và Đà Nẵng để rà soát chủng loại, số lượng và thời điểm giao giống từ nguồn dự trữ quốc gia, phục vụ khôi phục sản xuất sau bão số 13 và đợt mưa lũ cuối tháng 11 tại duyên hải Nam Trung Bộ và Tây Nguyên.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thực hiện thư ngỏ của Cục, nhiều doanh nghiệp và hiệp hội đã chủ động hỗ trợ giống cây trồng cho người dân vùng lũ. Theo Hiệp hội Thương mại giống cây trồng Việt Nam, các đơn vị đăng ký hỗ trợ gồm: Công ty TNHH Hạt giống C.P. Việt Nam (10 tấn ngô giống CP519 cho Gia Lai và Đắk Lắk); Công ty TNHH Phát triển nông nghiệp Việt Á (hàng chục nghìn gói giống dưa chuột VA.848, mướp Nhật lai VA.889, cải ngọt Samurai VA.68 và cải Tòa sại VA.318); Công ty CP Giống cây trồng Vật nuôi Thừa Thiên Huế (2 tấn lúa giống HG12 và 2 tấn HG244 cho Gia Lai); Công ty TNHH Cường Tân (3 tấn lúa thuần AYT77 cho Đắk Lắk).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mới đây, Cục đã gửi công văn đến Đà Nẵng và Đắk Lắk đề nghị tiếp tục rà soát, tham mưu UBND tỉnh xác định cụ thể nhu cầu giống lúa, ngô cần hỗ trợ để tổng hợp báo cáo Bộ xem xét xuất cấp từ nguồn dự trữ năm 2025.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ông Nguyễn Quốc Mạnh cho biết đơn vị đang theo dõi sát tình hình sản xuất, cập nhật thiệt hại và phối hợp địa phương triển khai giải pháp khôi phục. Các đơn vị được yêu cầu khẩn trương tiêu úng, khơi thông dòng chảy, tránh ngập kéo dài gây hư hại lúa, rau màu, cây ăn quả và cây công nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song song đó, Cục đang xây dựng kế hoạch sản xuất vụ Đông Xuân 2025- 2026, trong đó xem xét mở rộng diện tích cây trồng có lợi thế nhằm bù đắp thiệt hại và đáp ứng mục tiêu tăng trưởng toàn ngành.</span></span></span></p>\n\n<h4 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Xử lý môi trường sản xuất sau thiên tai</b></span></span></span></h4>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ở lĩnh vực thủy sản, ông Nhữ Văn Cẩn, Phó Cục trưởng Cục Thủy sản và Kiểm ngư, cho biết đơn vị đã cử đoàn công tác đến các địa phương trọng điểm như Khánh Hòa, Đắk Lắk và Gia Lai để phối hợp đánh giá mức độ thiệt hại sau thiên tai. Đồng thời, Cục chỉ đạo Viện Nghiên cứu Nuôi trồng thủy sản I và III cùng các địa phương quan trắc môi trường, đánh giá chất lượng nước làm cơ sở khôi phục và tái sản xuất thủy sản.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các nhiệm vụ trọng tâm tập trung vào khôi phục hoạt động nuôi trồng sau thiên tai, gồm: vệ sinh, thu gom thủy sản chết, tiêu độc khử trùng khu vực nuôi; thống kê thiệt hại, tu sửa ao đầm, lồng bè; đánh giá nhu cầu vật tư và con giống nhằm điều tiết nguồn cung. Cục cũng phối hợp hệ thống ngân hàng triển khai các biện pháp khoanh nợ, giãn nợ, hoãn nợ và hỗ trợ vốn cho người dân tái đầu tư; đồng thời thực hiện các giải pháp bình ổn thị trường, ngăn chặn tình trạng đầu cơ, tăng giá con giống và vật tư. Bên cạnh đó, các doanh nghiệp được vận động hỗ trợ giống, vật tư, lưới, bạt và thuốc thú y thủy sản để giúp người dân sớm ổn định sản xuất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo ông Nhữ Văn Cẩn, trước mắt các địa phương cần nhanh chóng hoàn thiện hồ sơ xác nhận thiệt hại để kịp thời hỗ trợ theo Nghị định 09/2025/NĐ-CP. Về kỹ thuật, ngành hướng dẫn người dân xử lý môi trường, xác định thời điểm thả giống phù hợp và ưu tiên các đối tượng nuôi có chu kỳ ngắn để đáp ứng nhu cầu thị trường dịp cuối năm. Ngành cũng sẽ tổ chức hội nghị cấp vùng nhằm kết nối nguồn lực hỗ trợ, bao gồm ngân hàng, quỹ tín dụng và doanh nghiệp cung ứng vật tư, con giống, thức ăn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về dài hạn, ngành thủy sản định hướng tổ chức lại sản xuất theo hướng thích ứng và bền vững. Các địa phương cần rà soát, quy hoạch lại nuôi lồng bè, kiểm soát mật độ nhằm giảm thiểu rủi ro; tiếp tục ưu tiên đầu tư hạ tầng cho vùng nuôi trọng điểm như bờ bao, hệ thống thoát nước và trạm quan trắc tự động. Công tác quan trắc, cảnh báo môi trường sẽ được tăng cường, cùng với thí điểm và mở rộng ứng dụng công nghệ số trong cảnh báo thiên tai và môi trường vùng nuôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về chính sách, ngành đang đề xuất các cơ chế tín dụng đặc thù và bảo hiểm rủi ro cho nuôi biển, hướng tới phát triển an toàn và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Nông nghiệp và Môi trường Phùng Đức Tiến nhấn mạnh rằng trong bối cảnh nhiều khó khăn, ngành nông nghiệp Việt Nam vẫn giữ đà tăng trưởng, tiến gần mục tiêu xuất khẩu 65-70 tỷ USD năm 2025. Đáng chú ý, thị trường Mỹ và Trung Quốc có sự phục hồi tích cực khi Trung Quốc chiếm hơn 22% thị phần, Mỹ đạt 20,5%, trong khi châu Âu tiếp tục tăng trưởng, cho thấy sự chuyển dịch tích cực về thị trường và chất lượng hàng xuất khẩu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu duy trì được mức tăng trưởng khoảng 6 tỷ USD trong tháng 12, kim ngạch xuất khẩu nông nghiệp năm 2025 có thể đạt xấp xỉ 70 tỷ USD. Dù còn nhiều thách thức từ xung đột thương mại và biến động toàn cầu, những kết quả hiện nay tạo nền tảng quan trọng cho giai đoạn phát triển 2026-2030.</span></span></span></p>', '2025-12-05 02:45:00', 'https://bacninh.gov.vn/news/-/details/37632/nganh-nong-nghiep-vuc-day-san-xuat-sau-thien-tai-75908604', '', 'Theo Chinhphu.vn', 3, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.676546', 8, 11);
INSERT INTO `sync_articles` VALUES (343, '75900601', 'Quốc hội xem xét cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030', 'Quốc hội xem xét cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/z7291737947428d2a543ff3dd84817046719b97a08c8d9-1764839834621360069596.jpg', '<p>Tập trung vào yêu cầu hoàn thiện cơ chế, chính sách để phát triển đồng bộ các loại hình năng lượng, tháo gỡ điểm nghẽn pháp lý và bảo đảm an ninh năng lượng quốc gia - là cơ sở quan trọng để Quốc hội xem xét, quyết định các cơ chế mới nhằm đáp ứng yêu cầu phát triển nhanh, bền vững trong giai...', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/z7291737947428d2a543ff3dd84817046719b97a08c8d9-1764839834621360069596.jpg\" target=\"_blank\" title=\"Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên trình bày Tờ trình về việc ban hành Nghị quyết của Quốc hội về cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030 - Ảnh: VGP/Nhật Bắc\"><img alt=\"Quốc hội xem xét cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/z7291737947428d2a543ff3dd84817046719b97a08c8d9-1764839834621360069596.jpg\" h=\"1333\" id=\"img_920967816216125440\" loading=\"lazy\" photoid=\"920967816216125440\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/z7291737947428d2a543ff3dd84817046719b97a08c8d9-1764839834621360069596.jpg\" style=\"width: 900px; height: 600px;\" title=\"Quốc hội xem xét cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên trình bày Tờ trình về việc ban hành Nghị quyết của Quốc hội về cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030 - Ảnh: VGP/Nhật Bắc</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 4/12, Quốc hội nghe Tờ trình và Báo cáo thẩm tra dự thảo Nghị quyết về cơ chế, chính sách phát triển năng lượng quốc gia giai đoạn 2026-2030. Việc xây dựng Nghị quyết nhằm tháo gỡ vướng mắc, tạo đột phá cho các dự án năng lượng quan trọng, bảo đảm an ninh năng lượng và đáp ứng yêu cầu phát triển bền vững của đất nước trong giai đoạn mới.</span></span></span></p>\n\n<h3 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tập trung tháo gỡ điểm nghẽn thể chế, thúc đẩy các dự án năng lượng trọng điểm</span></span></span></h3>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trình bày Tờ trình trước Quốc hội, Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên cho biết, việc ban hành Nghị quyết là cần thiết để giải quyết kịp thời những điểm nghẽn về thể chế, cơ chế và chính sách đang cản trở tiến độ các dự án năng lượng quy mô lớn. Mục tiêu cao nhất được xác định là bảo đảm an ninh năng lượng quốc gia vững chắc, phục vụ phát triển kinh tế-xã hội giai đoạn 2026-2030 và các mục tiêu phát triển bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo Nghị quyết gồm 8 Chương, 24 Điều, tập trung vào các cơ chế đặc thù để khơi thông nguồn lực và tạo hành lang pháp lý thống nhất cho triển khai các dự án năng lượng. Nội dung bao quát các lĩnh vực trọng tâm như điều chỉnh quy hoạch phát triển điện lực; phương án phát triển mạng lưới truyền tải/phân phối điện; cơ chế đầu tư xây dựng dự án điện; phát triển điện gió ngoài khơi; mua bán điện trực tiếp; đầu tư các dự án dầu khí, than và chính sách dự trữ xăng dầu quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghị quyết cũng quy định rõ nguyên tắc điều chỉnh quy hoạch linh hoạt cùng trách nhiệm của Bộ Công Thương trong việc hướng dẫn hồ sơ, quy trình và thẩm quyền điều chỉnh. Một số dự án lưới điện được đề xuất áp dụng cơ chế thay thế quyết định chấp thuận chủ trương đầu tư, nhằm rút ngắn thời gian chuẩn bị và đẩy nhanh tiến độ thực hiện.</span></span></span></p>\n\n<h3 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Làm rõ cơ chế liên quan đến quy hoạch và thủ tục đầu tư</span></span></span></h3>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thẩm tra Tờ trình, Chủ nhiệm Ủy ban Kinh tế và Tài chính Phan Văn Mãi cho biết, Ủy ban cơ bản tán thành với sự cần thiết ban hành Nghị quyết, nhằm cụ thể hóa Nghị quyết số 70-NQ/TW của Bộ Chính trị về phát triển năng lượng quốc gia. Đây là yêu cầu trọng tâm để đáp ứng mục tiêu phát triển nhanh và bền vững của đất nước trong giai đoạn mới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban đề nghị rà soát kỹ nội dung dự thảo, chỉ quy định những vấn đề thuộc thẩm quyền của Quốc hội, tránh đưa vào các nội dung thuộc thẩm quyền ban hành văn bản dưới luật của Chính phủ, bộ, ngành hoặc địa phương. Việc này nhằm đảm bảo sự thống nhất với tinh thần đổi mới xây dựng pháp luật được nêu tại Nghị quyết số 66-NQ/TW.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ được đề nghị giải trình rõ hơn đối với các cơ chế mới để bảo đảm tính khả thi và tránh rủi ro trong quá trình thực hiện.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo thẩm tra nêu rõ một số nội dung cần Chính phủ giải thích đầy đủ. Trong đó có đề xuất miễn thủ tục chấp thuận chủ trương đầu tư đối với các dự án lưới điện nằm trong Quy hoạch điện lực hoặc phương án mạng lưới cấp điện của Quy hoạch tỉnh. Tuy nhiên, theo dự thảo Luật Quy hoạch (sửa đổi), các quy hoạch này mang tính định hướng, không liệt kê danh mục dự án cụ thể. Vì vậy, việc xác định dự án thuộc hay không thuộc quy hoạch cần được làm rõ để đảm bảo tính hợp lý và khả thi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với đề xuất sử dụng quyết định phê duyệt quy hoạch thay thế văn bản chấp thuận chủ trương đầu tư, Ủy ban đề nghị đánh giá thận trọng, tránh xung đột với phương pháp tiếp cận mới của Luật Quy hoạch (sửa đổi), vốn tập trung vào định hướng và không xác định danh sách dự án cụ thể.</span></span></span></p>\n\n<h4 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Yêu cầu minh bạch trong giao dự án, bảo đảm đúng đối tượng và đúng quy định</span></span></span></h4>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên quan đến cơ chế giao trực tiếp một số dự án nhằm bảo đảm tiến độ, Ủy ban Kinh tế và Tài chính đề nghị xác định rõ điều kiện và tiêu chí áp dụng để bảo đảm cơ chế đặc thù này được sử dụng đúng mục đích.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc xác lập tiêu chí cũng giúp phân biệt rõ giữa các dự án được giao trực tiếp và những dự án bắt buộc phải đấu thầu lựa chọn nhà đầu tư theo quy trình thông thường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cơ chế liên quan đến điện gió ngoài khơi, dầu khí, lưới điện và dự trữ xăng dầu cần được xem xét đồng bộ, đảm bảo tính phù hợp với năng lực triển khai của bộ, ngành, địa phương và doanh nghiệp, đồng thời bảo đảm kiểm soát rủi ro trong thực tiễn.</span></span></span></p>', '2025-12-05 02:42:00', 'https://bacninh.gov.vn/news/-/details/37632/quoc-hoi-xem-xet-co-che-chinh-sach-phat-trien-nang-luong-quoc-gia-giai-oan-2026-2030-75900601', '', 'Theo Chinhphu.vn', 2, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.704895', 8, 11);
INSERT INTO `sync_articles` VALUES (344, '75915903', 'Giá xăng tăng, dầu giảm', 'Giá xăng tăng, dầu giảm', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/giaxang2-17648339835321091315377.jpeg', '<p>Chiều 4/12, Liên Bộ Công Thương – Tài chính thông báo về việc điều chỉnh giá bán lẻ các mặt hàng xăng dầu, áp dụng từ 15h cùng ngày.</p>', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/giaxang2-17648339835321091315377.jpeg\" target=\"_blank\" title=\"Giá xăng E5RON92 tăng 534 đồng/lít so với giá cơ sở hiện hành - Ảnh minh họa\"><img alt=\"Giá xăng tăng, dầu giảm- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/giaxang2-17648339835321091315377.jpeg\" h=\"440\" id=\"img_920943269668601856\" loading=\"lazy\" photoid=\"920943269668601856\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/giaxang2-17648339835321091315377.jpeg\" style=\"width: 660px; height: 440px;\" title=\"Giá xăng tăng, dầu giảm- Ảnh 1.\" type=\"photo\" w=\"660\" /></a></span></span></span></span></span></span></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá xăng E5RON92 tăng 534 đồng/lít so với giá cơ sở hiện hành - Ảnh minh họa</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, sau khi thực hiện việc trích lập và chi sử dụng Quỹ Bình ổn giá xăng dầu, giá bán các mặt hàng này phổ biến trên thị trường như sau:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá xăng E5RON92 không cao hơn 19.822 đồng/lít (tăng 534 đồng/lít so với giá cơ sở hiện hành), thấp hơn xăng RON95-III 638 đồng/lít.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá xăng RON95-III không cao hơn 20.460 đồng/lít (tăng 451 đồng/lít so với giá cơ sở hiện hành).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá dầu diesel 0.05S không cao hơn 18.380 đồng/lít (giảm 420 đồng/lít so với giá cơ sở hiện hành).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá dầu hỏa không cao hơn 18.893 đồng/lít (giảm 580 đồng/lít so với giá cơ sở hiện hành).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giá dầu mazut 180CST 3.5S: không cao hơn 13.436 đồng/kg (giảm 52 đồng/kg so với giá cơ sở hiện hành).</span></span></span></p>', '2025-12-04 10:00:00', 'https://bacninh.gov.vn/news/-/details/37632/gia-xang-tang-dau-giam-75915903', '', 'Theo Chinhphu.vn', 4, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.736887', 8, 11);
INSERT INTO `sync_articles` VALUES (345, '75911801', '66% tổng số cơ sở nhà, đất dôi dư đã được sắp xếp', '66% tổng số cơ sở nhà, đất dôi dư đã được sắp xếp', '', '<p>Đến ngày 1/12/2025 đã có 17.496 cơ sở nhà, đất được xử lý, chiếm 66% tổng số cơ sở dôi dư cần sắp xếp.</p>', '<figure class=\"VCSortableInPreviewMode\" style=\"box-sizing:border-box; padding:0px; display:inline-block; flex-direction:column; position:relative; transition:0.3s ease-in-out; width:777px; z-index:96; overflow-wrap:break-word; cursor:default; color:#333333; font-family:NotoSerif; font-size:17px; font-style:normal; font-variant-ligatures:normal; font-weight:400; text-align:start; white-space:normal; background-color:#ffffff; text-decoration-thickness:initial; text-decoration-style:initial; text-decoration-color:initial; margin-bottom:15px\" type=\"Photo\">\n<div style=\"padding:0px\"><span style=\"box-sizing:border-box\"><span style=\"position:relative\"></span></span>\n<p style=\"text-align: center;\"><span style=\"box-sizing:border-box\"><span style=\"position:relative\"><a class=\"detail-img-lightbox\" data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/toancanh2-1764836197334612065684.jpg\" style=\"box-sizing:border-box; padding:0px; text-decoration:none; color:-webkit-link; cursor:zoom-in; display:block; outline:none !important\" target=\"_blank\" title=\"Bộ Tài chính tổ chức hội nghị trực tuyến toàn quốc về bố trí, sắp xếp và xử lý trụ sở, tài sản công theo mô hình chính quyền địa phương hai cấp - Ảnh: VGP/HT\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img alt=\"66% tổng số cơ sở nhà, đất dôi dư đã được sắp xếp- Ảnh 1.\" class=\"lightbox-content\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/toancanh2-1764836197334612065684.jpg\" h=\"1334\" id=\"img_920952553057935360\" loading=\"lazy\" photoid=\"920952553057935360\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/toancanh2-1764836197334612065684.jpg\" style=\"box-sizing: border-box; padding: 0px; width: 900px; max-width: 100%; display: inline-block; height: 600px; vertical-align: top;\" title=\"66% tổng số cơ sở nhà, đất dôi dư đã được sắp xếp- Ảnh 1.\" type=\"photo\" w=\"2000\" /></span></span></span></a></span></span></p>\n\n<div class=\"button-dowload-img\" style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"position:relative\"><span style=\"box-sizing:border-box\"><span style=\"position:absolute\"><span style=\"bottom:10px\"><span style=\"right:10px\"></span></span></span></span></span></span></span></span></span></div>\n</div>\n\n<figcaption class=\"PhotoCMS_Caption\" style=\"box-sizing:border-box; padding:5px 8px; background:#e9e9e9; margin-bottom:24px\">\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"padding: 0px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style:normal\"><span style=\"font-variant:normal\"><span style=\"font-size-adjust:none\"><span style=\"font-kerning:auto\"><span style=\"font-optical-sizing:auto\"><span style=\"font-feature-settings:normal\"><span style=\"font-variation-settings:normal\"><span style=\"font-weight:normal\"><span style=\"font-stretch:normal\">Bộ Tài chính tổ chức hội nghị trực tuyến toàn quốc về bố trí, sắp xếp và xử lý trụ sở, tài sản công theo mô hình chính quyền địa phương hai cấp - Ảnh: VGP/HT</span></span></span></span></span></span></span></span></span></span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Ngày 4/12, Bộ Tài chính tổ chức hội nghị trực tuyến toàn quốc về bố trí, sắp xếp và xử lý trụ sở, tài sản công theo mô hình chính quyền địa phương hai cấp.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<h2 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><b style=\"box-sizing:border-box; padding:0px\"><font style=\"box-sizing:border-box; padding:0px; font-size:22px\">Gần 17,5 nghìn cơ sở nhà, đất đã được xử lý</font></b></span></span></span></span></span></span></span></span></span></span></span></span></h2>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Hội nghị được tổ chức nhằm rà soát kết quả triển khai tại các địa phương, làm rõ khó khăn, vướng mắc trong quá trình thực hiện và thống nhất giải pháp nhằm đẩy nhanh tiến độ xử lý tài sản công dôi dư, bảo đảm đúng quy định và yêu cầu của Trung ương.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Phát biểu tại hội nghị, Thứ trưởng Bộ Tài chính Đỗ Thành Trung cho biết việc sắp xếp tổ chức bộ máy và đơn vị hành chính theo chủ trương của Trung ương đặt ra yêu cầu cấp bách trong công tác quản lý, sử dụng và xử lý tài sản công.&nbsp;</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Nhờ sự chỉ đạo quyết liệt của cấp ủy, chính quyền các địa phương, nhiều nơi đã đạt kết quả rõ nét. Các xã mới hình thành sau sắp xếp cơ bản được bảo đảm xe ô tô phục vụ công tác chung; máy móc, thiết bị làm việc được bổ sung, nâng cấp. Số lượng cơ sở nhà, đất dôi dư được xử lý tăng lên đáng kể, đặc biệt tại các địa phương như Nghệ An, An Giang, Điện Biên, Quảng Ninh.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Tuy nhiên, tính đến ngày 1/12/2025, cả nước vẫn còn 9.056 cơ sở nhà, đất dôi dư cần tiếp tục xử lý. Trước yêu cầu phải hoàn thành xử lý theo các kết luận của Bộ Chính trị, Ban Bí thư và chỉ đạo của Thủ tướng Chính phủ, Bộ Tài chính tổ chức hội nghị nhằm rà soát kết quả thực hiện, xác định những tồn tại, đồng thời thống nhất giải pháp trong thời gian tới.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Hội nghị có sự tham dự của đại diện các bộ, ngành gồm: Nông nghiệp và Phát triển nông thôn; Tài nguyên và Môi trường; Xây dựng; Nội vụ; Quốc phòng; Công an; Giáo dục và Đào tạo; Y tế. Sự phối hợp liên ngành được xác định là yếu tố then chốt trong việc tháo gỡ các vướng mắc liên quan đến quy hoạch, pháp lý đất đai, bố trí công năng sử dụng và tổ chức bộ máy sau sắp xếp.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><span style=\"box-sizing:border-box; padding:0px\">Báo cáo tại hội nghị, ông Nguyễn Tân Thịnh, Cục trưởng Cục Quản lý công sản (Bộ Tài chính), cho biết đến ngày 1/12/2025 đã có 17.496 cơ sở nhà, đất được xử lý, chiếm 66% tổng số cơ sở dôi dư cần sắp xếp.</span></span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Trong đó, 798 cơ sở được bố trí cho lĩnh vực y tế; 4.002 cơ sở cho giáo dục; 1.314 cơ sở cho văn hóa – thể thao; 7.952 cơ sở làm trụ sở làm việc hoặc cơ sở hoạt động sự nghiệp.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Cũng theo báo cáo, đến thời điểm này đã có hơn 97,3% đơn vị hành chính cấp xã được trang bị xe ô tô phục vụ nhiệm vụ chung; 100% các đơn vị báo cáo đã được trang bị đầy đủ máy móc, thiết bị.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<h3 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Đề nghị địa phương sát sao, chủ động triển khai</span></span></span></span></span></span></span></span></span></span></span></span></h3>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Tại hội nghị, đại diện UBND TP Hà Nội cho biết thành phố đã triển khai nhiệm vụ sắp xếp, bố trí, xử lý trụ sở, tài sản công ngay sau khi Trung ương ban hành các kết luận và nghị quyết liên quan.&nbsp;</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">UBND TP Hà Nội đã phê duyệt nhiều phương án xử lý, gồm: điều chuyển cho đơn vị có nhu cầu; chuyển đổi công năng sang mục đích văn hóa, thể thao, công cộng; bàn giao cho cơ quan Trung ương; chuyển giao cho đơn vị sự nghiệp; thu hồi giao cơ quan tài nguyên và môi trường.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Tỉnh Nghệ An cũng là địa phương có kết quả nổi bật. Tỉnh ban hành đầy đủ kế hoạch, quy định để triển khai rà soát, xử lý tài sản công; ban hành các văn bản về phân cấp quản lý, tiêu chuẩn, định mức và phân bổ phương tiện cho các đơn vị.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Tuy nhiên, tỉnh Nghệ An cũng nêu rõ các khó khăn như thiếu hồ sơ pháp lý; quy hoạch chưa đồng bộ; địa bàn rộng; khoảng cách đi lại xa; tình trạng thừa - thiếu biên chế cục bộ. Tỉnh cho biết tiếp tục rà soát, hoàn thiện hồ sơ và xử lý theo quy định.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Ngoài Nghệ An và Hà Nội, các địa phương như Ninh Bình, Tây Ninh, Lai Châu, Quảng Ninh và một số bộ cũng báo cáo chi tiết về tiến độ và khó khăn trong quá trình thực hiện.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Kết luận hội nghị, Thứ trưởng Đỗ Thành Trung yêu cầu chủ tịch UBND các tỉnh, thành phố sớm ban hành quy định phân cấp thẩm quyền xử lý tài sản theo Nghị định 186/2025/NĐ-CP. Khi thẩm quyền rõ ràng, tiến độ xử lý tài sản dôi dư sẽ được rút ngắn đáng kể.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Các địa phương tiếp tục rà soát đầy đủ các cơ sở nhà, đất dôi dư, nhất là cấp xã; đồng thời khẩn trương lập, cập nhật kế hoạch xử lý. Sau khi có quyết định của cấp có thẩm quyền, các đơn vị phải tổ chức bàn giao, tiếp nhận, thanh lý hoặc điều chuyển đúng thời hạn.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Việc mua sắm, điều chuyển tài sản phải căn cứ tiêu chuẩn, định mức, dự toán được giao; xử lý nghiêm các trường hợp lãng phí hoặc sử dụng sai mục đích.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Thứ trưởng Đỗ Thành Trung cũng đề nghị lãnh đạo UBND các tỉnh, thành phố báo cáo trực tiếp bí thư tỉnh ủy, thành ủy để tăng cường lãnh đạo, chỉ đạo công tác xử lý tài sản công theo Kết luận 221-KL/TW của Bộ Chính trị và Ban Bí thư.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Bộ Tài chính đề nghị các bộ, ngành phối hợp chặt chẽ, hướng dẫn kịp thời những nội dung liên quan đến quy hoạch, đất đai, xây dựng, y tế, giáo dục và an ninh trật tự nhằm tháo gỡ khó khăn phát sinh tại cơ sở.</span></span></span></span></span></span></span></span></span></span></span></p>', '2025-12-04 09:30:00', 'https://bacninh.gov.vn/news/-/details/37632/66-tong-so-co-so-nha-at-doi-du-a-uoc-sap-xep-75911801', '', 'Theo Chinhphu.vn', 4, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.768622', 8, 11);
INSERT INTO `sync_articles` VALUES (346, '75985401', 'Thiên tai cực kỳ dị thường, khả năng còn 1-2 cơn bão trên Biển Đông', 'Thiên tai cực kỳ dị thường, khả năng còn 1-2 cơn bão trên Biển Đông', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/lut-17648309438321378113088.jpg', '<p>Tại Việt Nam, năm 2025 được ghi nhận là một năm có diễn biến thiên tai cực kỳ bất thường và dị thường. Trong tháng 12/2025, trên khu vực Biển Đông có khả năng xuất hiện từ 1-2 cơn bão/ATNĐ.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/lut-17648309438321378113088.jpg\" target=\"_blank\" title=\"Năm 2025 được ghi nhận là một năm có diễn biến thiên tai cực kỳ bất thường và dị thường, gây ra những thiệt hại nghiêm trọng trên cả nước\"><img alt=\"Thiên tai cực kỳ dị thường, khả năng còn 1-2 cơn bão trên Biển Đông- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/4/lut-17648309438321378113088.jpg\" h=\"950\" id=\"img_920930518321741824\" loading=\"lazy\" photoid=\"920930518321741824\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/4/lut-17648309438321378113088.jpg\" style=\"width: 900px; height: 427px;\" title=\"Thiên tai cực kỳ dị thường, khả năng còn 1-2 cơn bão trên Biển Đông- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2025 được ghi nhận là một năm có diễn biến thiên tai cực kỳ bất thường và dị thường, gây ra những thiệt hại nghiêm trọng trên cả nước</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">&nbsp;<b>Năm 2025 là năm thiên tai dị thường nhất lịch sử</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đánh giá của Tổ chức Khí tượng Thế giới, năm 2025 đã chứng kiến nhiều kỷ lục về thiên tai khí tượng thủy văn được ghi nhận, trên thế giới, nhiều kỷ lục về nhiệt độ cao nhất tại nhiều nơi được ghi nhận vượt 48<sup>o</sup>C, thiết lập kỷ lục mới về số ngày liên tiếp có nhiệt độ cực đại (Hoa Kỳ, Thổ Nhĩ Kỳ, tháng 7/2025). Năm 2025 cũng đã ghi nhận 10 cơn bão lớn (cấp 3 trở lên), vượt qua các kỷ lục trước đó, hiện tượng bão tăng cường độ nhanh chóng đã trở nên phổ biến, siêu bão \"Phượng Hoàng\" ở Tây Bắc Thái Bình Dương đã tăng từ cấp 1 lên cấp 5 (sức gió trên 250 km/h chỉ trong vòng 24 giờ (9/2025).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, nhiều đợt lũ, ngập lụt và lũ quét cũng được ghi nhận, đặc biệt là các đợt lũ lụt và sạt lở đất vô cùng nghiêm trọng như tại Sumatra, Indonesia (11-12/2025) khiến trên 700 người thiệt mạng và hàng trăm người mất tích, Pakistan (6-6/2025) khiến hơn 1.000 người thiệt mạng…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đáng chú ý, trạm Bạch Mã (Việt Nam) đã ghi nhận lượng mưa cực đoan lên tới 1.739 mm chỉ trong vòng 24 giờ (10/2025). Tổ chức Khí tượng Thế giới đang xác nhận đây là một trong những sự kiện mưa 24 giờ lớn nhất được biết đến trên thế giới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Việt Nam,<b>&nbsp;</b>năm 2025 được ghi nhận là một năm có diễn biến thiên tai cực kỳ bất thường và dị thường, gây ra những thiệt hại nghiêm trọng trên cả nước.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tính đến hết tháng 11/2025, đã có 21 cơn bão/ATNĐ (15 bão, 6 ATNĐ) hoạt động trên Biển Đông và 2025 trở thành năm có số lượng bão/ATNĐ hoạt động nhiều nhất trên Biển Đông kể từ khi có số liệu quan trắc (từ năm 1961). Trước đó, năm nhiều nhất là 2017 với 20 cơn bão/ATNĐ (16 bão, 4 ATNĐ).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngoài kỷ lục về số lượng bão/ATNĐ, mùa bão năm 2025 còn ghi nhận một số tính chất đặc biệt, bất thường và cực đoan như: Cơn bão số 1 (WUTIP) là cơn bão đầu tiên xuất hiện trên Biển Đông trong tháng 6 sau hơn 40 năm. Cơn bão số 9 (RAGASA) với cường độ mạnh cấp 17, giật trên cấp 17 đã trở thành cơn bão mạnh nhất từng hoạt động trên khu vực Biển Đông; ATNĐ cuối tháng 11, bắt nguồn từ cơn bão Senyar di chuyển từ khu vực Ấn Độ Dương sang khu vực Tây Bắc Thái Bình Dương (trong quá khứ đã từng có áp thấp nhiệt đới hoặc bão đi từ Tây Thái Bình Dương sang Ấn Độ Dương, nhưng chiều ngược lại thì chưa từng ghi nhận trong lịch sử khí tượng).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong năm 2025, tình hình lũ lụt nghiêm trọng đã xảy ra trên diện rộng, với mực nước đỉnh lũ trên các sông vượt mốc lịch sử ở cả Bắc Bộ, Trung Bộ, cao nguyên Trung Bộ, hạ lưu sông Cửu Long. Chưa năm nào ghi nhận lũ đặc biệt lớn, lũ lịch sử cùng xuất hiện trong 1 năm tại 20 con sông như sông Cầu (Thái Nguyên, Bắc Ninh), sông Thuơng (Bắc Ninh), sông Chung (Lạng Sơn), sông Bằng Giang (Cao Bằng), sông Lô (Tuyên Quang), sông Ngòi Hút, Ngòi Thia (Lào Cai), thượng lưu sông Mã và sông Bưởi, sông Yên (Thanh Hóa), thượng lưu sông Cả (Nghệ An), sông Bồ (Tp Huế), sông Vu Gia-Thu Bồn (Đà Nẵng), sông Kỳ Lộ, sông Ba (Đắk Lắk), sông Dinh Ninh Hòa (Khánh Hòa), sông Lũy (Lâm Đồng), hạ lưu sông Tiền (Vĩnh Long, Đồng Tháp), hạ lưu sông Hậu (An Giang, Cần Thơ).</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt nghiêm trọng là trận lũ lụt lịch sử tại Phú Yên (nay là khu vực phía đông tỉnh Đắk Lắk), được đánh giá là vượt qua đỉnh lũ lịch sử năm 1993 trên lưu vực sông Ba.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo ông Hoàng Đức Cường, Phó Cục trưởng Cục Khí tượng thủy văn, Bộ NN&amp;MT, hoạt động bão bất thường, lũ lớn nghiêm trọng, diện rộng bất thường trong năm 2025 tại Việt Nam cũng như trên thế giới là một minh chứng rõ ràng cho thấy quy luật lũ truyền thống đang thay đổi, phản ánh xu hướng thời tiết ngày càng cực đoan, khó lường do tác động của biến đổi khí hậu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Dự báo diễn biến thiên tai tháng cuối năm 2025 và đầu năm 2026</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Trung tâm Dự báo Khí tượng thủy văn Quốc gia, từ tháng 12/2025 đến tháng 2/2026, ENSO có khả năng cao sẽ tiếp tục duy trì trạng thái La Nina, sau đó từ tháng 3-5/2026, ENSO có khả năng quay trở lại trạng thái trung tính. Trong tháng 12/2025, trên khu vực Biển Đông có khả năng xuất hiện từ 1-2 cơn bão/ATNĐ. Từ tháng 1-5/2026, ít có khả năng xuất hiện bão/ATNĐ trên khu vực Biển Đông.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện nay, ở vùng biển phía đông của khu vực miền Trung Philippines đang tồn tại một áp thấp nhiệt đới có vị trí ở vào khoảng 14 độ Vĩ Bắc -135 độ Kinh Đông, di chuyển chậm theo hướng bắc tây bắc. Dự báo khoảng ngày 6-7/12 áp thấp nhiệt đới này có khả năng vượt qua khu vực miền Trung của Philippines và đi vào Biển Đông, có khả năng mạnh lên thành bão (cơn bão số 16). Bão có khả năng ảnh hưởng trực tiếp đến đất liền khu vực Trung và Nam Trung Bộ, gây ra một đợt mưa vừa, mưa to ở các tỉnh từ TP. Huế trở vào đến khu vực Khánh Hòa.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong tháng 12/2025 ở khu vực Trung và Nam Trung Bộ có khả năng xuất hiện từ 1-2 đợt mưa vừa, mưa to trên diện rộng, trong đó lượng mưa ở khu vực từ Nam Quảng Trị trở vào đến khu vực phía bắc của duyên hải Nam Trung Bộ có xu hướng cao hơn so với trung bình nhiều năm, cần đề phòng nguy cơ xảy ra lũ quét và trượt lở đất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong tháng 12/2025, không khí lạnh tiếp tục có xu hướng gia tăng về tần suất, cường độ và có thể xuất hiện tình trạng rét đậm, rét hại ở miền Bắc nhưng tập trung tại khu vực vùng núi phía bắc. Không khí lạnh tiếp tục hoạt động mạnh trong các tháng 1 và 2 năm 2026, gây ra các đợt rét đậm, rét hại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Khu vực Nam Bộ có khả năng xuất hiện nắng nóng từ khoảng đầu tháng 3/2026 ở miền Đông Nam Bộ; sau đó từ cuối tháng 3 đến đầu tháng 4/2026, nắng nóng có xu hướng gia tăng cường độ và mở rộng dần sang khu vực Tây Nam Bộ (tương đương với trung bình nhiều năm). Khu vực Tây Bắc Bộ và khu vực từ Thanh Hóa đến Huế có khả năng xuất hiện nắng nóng từ khoảng tháng 4/2026.</span></span></span></p>', '2025-12-04 08:00:00', 'https://bacninh.gov.vn/news/-/details/37632/thien-tai-cuc-ky-di-thuong-kha-nang-con-1-2-con-bao-tren-bien-ong-75985401', '', 'Theo Chinhphu.vn', 2, 'Tin trong nước', 8, '', '38762', '{}', '2025-12-08 08:18:11.803026', 8, 11);
INSERT INTO `sync_articles` VALUES (347, '64594701', 'Tổ chức Khí tượng thế giới đánh giá tình hình mưa lớn \'kỷ lục\' tại Việt Nam', 'Tổ chức Khí tượng thế giới đánh giá tình hình mưa lớn \'kỷ lục\' tại Việt Nam', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/3/mualu-17617993894182058546565-17647257729011864534010.jpg', '<p>Người phát ngôn của Tổ chức Khí tượng thế giới (WMO) Clare Nullis cho biết, tháng 10 vừa qua, một trạm khí tượng ở miền Trung của Việt Nam đã ghi nhận lượng mưa kỷ lục trên cả nước trong 24 giờ là 1.739 mm, và theo bà, đây là con số \"thực sự khủng khiếp\".</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/3/mualu-17617993894182058546565-17647257729011864534010.jpg\" target=\"_blank\" title=\"Miền Trung Việt Nam vừa đối diện đợt mưa lũ nghiêm trọng\"><img alt=\"Tổ chức Khí tượng thế giới đánh giá tình hình mưa lớn \'kỷ lục\' tại Việt Nam- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/12/3/mualu-17617993894182058546565-17647257729011864534010.jpg\" h=\"950\" id=\"img_920489393800491008\" loading=\"lazy\" photoid=\"920489393800491008\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/12/3/mualu-17617993894182058546565-17647257729011864534010.jpg\" style=\"width: 700px; height: 332px;\" title=\"Tổ chức Khí tượng thế giới đánh giá tình hình mưa lớn \'kỷ lục\' tại Việt Nam- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Miền Trung Việt Nam vừa đối diện đợt mưa lũ nghiêm trọng</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu trong cuộc họp báo ngày 2/12, bà Clare Nullis đã công bố thông tin về tình hình mưa lũ ở châu Á thời gian qua. Theo đó, trên nhiều khu vực ở Đông Nam Á, những trận mưa kỷ lục và lũ lụt do các cơn bão nhiệt đới liên tiếp hoành hành đã cướp đi sinh mạng của hàng trăm sinh mạng và gây ra sự tàn phá cũng như khiến nhiều cộng đồng phải di dời.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mưa lớn kỷ lục ở Việt Nam</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo bà Clare Nullis, Indonesia, Philippines, Sri Lanka, Thái Lan và Việt Nam nằm trong số những quốc gia bị ảnh hưởng nặng nề nhất. Bà nói: \"Vấn đề xảy ra khi lượng mưa liên quan đến gió mùa kết hợp với hoạt động của xoáy thuận nhiệt đới. Châu Á đang rất dễ tổn thương trước mưa lũ\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên quan tới Việt Nam, bà Nullis cho biết quốc gia Đông Nam Á này đã \"chịu tác động nghiêm trọng trong nhiều tuần\" và vẫn phải đối diện với nguy cơ có \"những trận mưa lớn nữa\". Bà nói: \"Những trận mưa lớn bất thường trong vài tuần qua đã gây ngập lụt các di tích lịch sử, các khu du lịch nổi tiếng và gây ra thiệt hại nặng nề ở Việt Nam\". Tháng 10 vừa qua, một trạm khí tượng ở miền Trung của Việt Nam đã ghi nhận lượng mưa kỷ lục trên cả nước trong 24 giờ là 1.739 mm, và theo bà Nullis, đây là con số \"thực sự khủng khiếp\". Bà cho biết thêm: \"Đây là tổng lượng mưa trong 24 giờ cao thứ hai được biết đến trên thế giới\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện số liệu mới này đang được ủy ban đánh giá cực đoan của WMO xem xét. Theo WMO, lượng mưa trên 1.700 mm sẽ lập kỷ lục cho khu vực Bắc Bán cầu và châu Á.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng ta đang chứng kiến lượng mưa cực đoan hơn</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bình luận về cường độ của các hiện tượng thời tiết tàn khốc thời gian qua, quan chức của WMP giải thích rằng nhiệt độ tăng cao \"làm tăng nguy cơ tiềm ẩn của các trận mưa cực đoan hơn vì bầu khí quyển ấm hơn giữ nhiều độ ẩm hơn\". Bà Nullis đánh giá: \"Đó là quy luật vật lý… chúng ta đang chứng kiến lượng mưa cực đoan hơn và sẽ tiếp tục như vậy trong tương lai\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng trong cuộc họp báo ở Geneva, ông Ricardo Pires – người phát ngôn của Quỹ Nhi đồng Liên Hợp Quốc (UNICEF) – đã đề cập tới các hoạt động hỗ trợ nhân đạo tại những khu vực bị ảnh hưởng bởi mưa lũ ở châu Á. Cụ thể, ông thông tin về tình hình tại Sri Lanka, nơi bão Ditwah đổ bộ vào nước này hồi tuần trước, ảnh hưởng đến khoảng 1,4 triệu người, trong đó có 275.000 trẻ em.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ông Ricardo Pires cho biết: \"Do thông tin liên lạc bị gián đoạn và các tuyến đường bị ảnh hưởng, số trẻ em thực sự bị ảnh hưởng có thể còn cao hơn nữa. Nhà cửa bị cuốn trôi, toàn bộ cộng đồng bị cô lập, và các dịch vụ thiết yếu mà trẻ em cần, chẳng hạn như nước sạch, chăm sóc sức khỏe và trường học, đã bị gián đoạn nghiêm trọng. Nhu cầu hiện nay vượt xa các nguồn lực hiện có ở Sri Lanka. Do đó, chúng tôi đưa ra lời kêu gọi bổ sung nguồn tài trợ nhân đạo và hỗ trợ cho những người dễ bị tổn thương nhất\".</span></span></span></p>', '2025-12-03 06:40:00', 'https://bacninh.gov.vn/news/-/details/37632/to-chuc-khi-tuong-the-gioi-anh-gia-tinh-hinh-mua-lon-ky-luc-tai-viet-nam-64594701', '', 'chinhphu.vn', 13, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.470594', 9, 11);
INSERT INTO `sync_articles` VALUES (348, '64581101', 'Động thái của các hãng hàng không thế giới trước việc cập nhật phần mềm máy bay...', 'Động thái của các hãng hàng không thế giới trước việc cập nhật phần mềm máy bay Airbus khẩn cấp', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/29/may-bay-17644306461241024844926.jpg', '<p>Ngày 29/11, các hãng hàng không trên khắp châu Á đối mặt tình trạng gián đoạn lớn sau khi nhà sản xuất máy bay Airbus ban hành lệnh triệu hồi khẩn cấp đối với khoảng 6.000 máy bay thuộc dòng A320 – chiếm hơn 1/2 đội bay A320 đang hoạt động trên toàn thế giới.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/29/may-bay-17644306461241024844926.jpg\" target=\"_blank\" title=\"American Airlines - hãng khai thác dòng máy bay A320 lớn nhất thế giới, cho biết khoảng 340 trong số 480 chiếc A320 của họ cần sửa. Ảnh:Avgeekery.com\"><img alt=\"Động thái của các hãng hàng không thế giới trước việc cập nhật phần mềm máy bay Airbus khẩn cấp- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/29/may-bay-17644306461241024844926.jpg\" h=\"618\" id=\"img_919251536196337664\" loading=\"lazy\" photoid=\"919251536196337664\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/29/may-bay-17644306461241024844926.jpg\" style=\"width: 700px; height: 466px;\" title=\"Động thái của các hãng hàng không thế giới trước việc cập nhật phần mềm máy bay Airbus khẩn cấp- Ảnh 1.\" type=\"photo\" w=\"928\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">American Airlines - hãng khai thác dòng máy bay A320 lớn nhất thế giới, cho biết khoảng 340 trong số 480 chiếc A320 của họ cần sửa. Ảnh:Avgeekery.com</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Cơ quan An toàn Hàng không Liên minh châu Âu (EASA), lỗi phần mềm liên quan hệ thống điều khiển thăng bằng và cánh lái (ELAC) có thể bị nhiễu bởi bức xạ Mặt Trời mạnh, dẫn tới nguy cơ máy bay bất ngờ thay đổi quỹ đạo. Cùng với nhiều cơ quan quản lý trên thế giới, các nước châu Á đã ra lệnh buộc các hãng hoàn tất cập nhật hoặc quay lại phiên bản phần mềm cũ trước khi tiếp tục khai thác.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Ấn Độ, cơ quan quản lý hàng không cho biết 338 máy bay bị ảnh hưởng và việc cập nhật dự kiến hoàn tất trong ngày 30/11. IndiGo - hãng có đội bay A320 lớn nhất tại nước này, cho biết đã cập nhật 160/200 chiếc. Air India cũng đã xử lý 42 trong tổng số 113 máy bay gặp lỗi và cảnh báo nguy cơ chậm, đổi chuyến trong ngày.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cơ quan hàng không Đài Loan (Trung Quốc) cho biết khoảng gần 70% trong số 67 máy bay A320/A321 của đảo này phải cập nhật. Về phần mình, chính quyền Macau (Trung Quốc) cũng yêu cầu hãng Air Macau điều chỉnh lịch bay để hạn chế ảnh hưởng tới hành khách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Hàn Quốc, Bộ Đất đai, Hạ tầng và Giao thông cho biết hơn 50% số máy bay dòng A320 thuộc 5 hãng, gồm Korean Air, Asiana Airlines, Air Busan, Air Seoul và Aero K, nằm trong diện triệu hồi. Tuy nhiên, quá trình cập nhật - chỉ dưới 1 giờ cho mỗi máy bay - gần như hoàn tất và dự kiến toàn bộ sẽ được xử lý trước 9h ngày 30/11. Vì vậy, Hàn Quốc gần như không ghi nhận hủy chuyến quy mô lớn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">ANA Holdings, hãng khai thác đội A320 lớn nhất Nhật Bản, đã hủy 95 chuyến bay nội địa trong ngày 29/11, ảnh hưởng khoảng 13.500 hành khách tại các sân bay Haneda, Akita, Saga, Tottori và nhiều địa phương khác. ANA có 34 máy bay thuộc diện phải cập nhật. Trong khi đó, Japan Airlines không bị ảnh hưởng do đội bay chủ yếu là Boeing.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Philippines, 3 hãng hàng không gồm Philippine Airlines, Cebu Pacific và AirAsia Philippines phải hủy ít nhất 82 chuyến sau khi 93 máy bay bị yêu cầu cập nhật. Cơ quan Hàng không Dân dụng Philippines (CAAP) khẳng định việc dừng bay là biện pháp phòng ngừa, đồng thời cho biết nhiều máy bay đã hoàn tất cập nhật và toàn bộ dự kiến xong trong ngày 30/11.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ở Australia, Jetstar - hãng hàng không giá rẻ thuộc Qantas - cảnh báo một số chuyến bay bị ảnh hưởng, trong khi truyền thông nước này ghi nhận tình trạng chậm chuyến đáng kể tại sân bay Melbourne.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguồn tin trong ngành cho biết chính sự cố ngày 30/10 – khi một chiếc A320 của JetBlue bay từ Cancun (Mexico) đến Newark (Mỹ) bất ngờ giảm độ cao mạnh khiến nhiều hành khách bị thương - đã thúc đẩy Airbus mở cuộc kiểm tra và ban hành đợt triệu hồi được đánh giá là lớn nhất trong 55 năm lịch sử hãng. Airbus cho rằng nguyên nhân liên quan đến bức xạ Mặt Trời mạnh làm nhiễu dữ liệu quan trọng trong hệ thống ELAC, dẫn đến yêu cầu cập nhật phần mềm trên toàn cầu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dù biện pháp sửa lỗi được đánh giá là \"đơn giản nhưng bắt buộc\", các cơ quan quản lý nhấn mạnh tất cả máy bay phải hoàn tất cập nhật trước khi được phép cất cánh trở lại, nhằm đảm bảo an toàn tuyệt đối cho hành khách.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh hưởng hàng không toàn cầu</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">A320 là dòng máy bay được sử dụng phổ biến trên toàn cầu. Sự việc này có thể ảnh hưởng hơn một nửa đội bay trên thế giới, đe dọa gây xáo trộn việc di chuyển cuối tuần.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đây là một trong những vụ triệu hồi lớn nhất trong lịch sử 55 năm hoạt động của Airbus. Động thái này diễn ra đúng thời điểm cao điểm du lịch cuối năm, gây gián đoạn nghiêm trọng tại Mỹ, châu Âu, Nam Mỹ và châu Á, buộc hàng loạt hãng hàng không phải tạm dừng khai thác hoặc hủy chuyến.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">American Airlines - hãng khai thác dòng máy bay A320 lớn nhất thế giới, cho biết khoảng 340 trong số 480 chiếc A320 của họ cần chỉnh sửa. Họ dự kiến phần lớn hoàn tất trước ngày 29/11, với khoảng hai giờ sửa cho mỗi phi cơ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hãng Avianca của Colombia thông báo triệu hồi ảnh hưởng hơn 70% đội bay, buộc hãng tạm dừng bán vé cho các ngày bay đến 8/12.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện có khoảng 11.300 chiếc A320 đang hoạt động trên toàn cầu. Bốn trong 10 hãng khai thác A320 lớn nhất thế giới đến từ Mỹ, gồm American Airlines, Delta Air Lines, JetBlue và United Airlines. Các hãng bay Trung Quốc, châu Âu và Ấn Độ cũng là khách hàng lớn của dòng này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Airbus, việc sửa chữa chủ yếu là cài lại phiên bản phần mềm trước đó và tương đối đơn giản, song phải được thực hiện trước khi máy bay bay trở lại.</span></span></span></p>', '2025-12-03 06:38:00', 'https://bacninh.gov.vn/news/-/details/37632/-ong-thai-cua-cac-hang-hang-khong-the-gioi-truoc-viec-cap-nhat-phan-mem-may-bay-airbus-khan-cap-64581101', '', 'chinhphu.vn', 10, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.500810', 9, 11);
INSERT INTO `sync_articles` VALUES (349, '64569905', 'Chuyên gia Đức ấn tượng về sự vươn mình của nền kinh tế Việt Nam', 'Chuyên gia Đức ấn tượng về sự vươn mình của nền kinh tế Việt Nam', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/29/tphcm-viet-nam-17643792047812094853169.jpg', '<p>Theo nhà báo Đức Sabine Balk, Việt Nam giờ đây không còn là quốc gia nghèo nhất châu Á như ba thập kỷ trước. Trái lại, đất nước đã vươn lên trở thành một trong những nền kinh tế có tốc độ tăng trưởng ấn tượng nhất khu vực.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/29/tphcm-viet-nam-17643792047812094853169.jpg\" target=\"_blank\" title=\"iệt Nam đang nổi lên như một trung tâm sản xuất, công nghệ và năng lượng sạch mới của châu Á, trở thành mắt xích quan trọng trong chiến lược thương mại của EU.\"><img alt=\"Chuyên gia Đức ấn tượng về sự vươn mình của nền kinh tế Việt Nam - Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/29/tphcm-viet-nam-17643792047812094853169.jpg\" h=\"708\" id=\"img_919035777189535744\" loading=\"lazy\" photoid=\"919035777189535744\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/29/tphcm-viet-nam-17643792047812094853169.jpg\" style=\"width: 700px; height: 431px;\" title=\"Chuyên gia Đức ấn tượng về sự vươn mình của nền kinh tế Việt Nam - Ảnh 1.\" type=\"photo\" w=\"1152\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam đang nổi lên như một trung tâm sản xuất, công nghệ và năng lượng sạch mới của châu Á, trở thành mắt xích quan trọng trong chiến lược thương mại của EU.</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhờ sự ổn định chính trị, lực lượng lao động trẻ, khát vọng đi lên và chính sách mở cửa, Việt Nam đang nổi lên như một trung tâm sản xuất, công nghệ và năng lượng sạch mới của châu Á, trở thành mắt xích quan trọng trong chiến lược thương mại của EU.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam là nền kinh tế thị trường năng động nhất Đông Nam Á</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau sự kiện \"Vietnam Dialogue\" vừa được tổ chức tại Frankfurt am Main, nhà báo Sabine Balk đã đăng tải bài phân tích trên FAZ, một trong những nhật báo quan trọng nhất của Cộng hòa Liên bang Đức. Trong bài viết, bà nhấn mạnh rằng Việt Nam đã bước ra khỏi vị thế của một nước nghèo trước đây và đang nổi lên như một nền kinh tế đầy năng động.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ông Oliver Massmann – luật sư người Đức đã sống ở Việt Nam 25 năm và hiện là Giám đốc điều hành hãng luật Duane Morris – cho rằng mô hình kinh tế của Việt Nam đã có mức độ thị trường rất cao, thậm chí \"thị trường hơn nhiều nước thị trường\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">\"Tôi không biết nước nào ở Đông Nam Á có môi trường kinh doanh thị trường tự do và cởi mở như Việt Nam\", luật sư Oliver Massmann chia sẻ quan điểm.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khuôn khổ sự kiện \"Vietnam Dialogue\" tại Frankfurt, nơi kết nối giữa lãnh đạo doanh nghiệp và các nhà hoạch định chính sách của hai nước, ông Massmann cũng nhấn mạnh rằng Việt Nam đang sở hữu hàng loạt yếu tố mà doanh nghiệp Đức đặc biệt quan tâm: môi trường pháp lý ổn định, lực lượng lao động trẻ và đầy khát vọng, sự trỗi dậy của các ngành công nghiệp công nghệ cao và quy mô tầng lớp trung lưu tăng nhanh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dù hệ thống hạ tầng chưa đồng đều, nhưng lĩnh vực năng lượng – đặc biệt là năng lượng tái tạo – đang nổi lên như một điểm sáng lớn. Riêng năm 2022, Việt Nam đã bổ sung 18 GW điện Mặt trời – một tốc độ mở rộng hiếm thấy tại khu vực châu Á. Cùng lúc, Chính phủ tiếp tục điều chỉnh khung pháp lý nhằm thu hút dòng vốn mới vào lĩnh vực năng lượng sạch.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam đặt mục tiêu chiến lược trở thành quốc gia công nghiệp. Năm 1990, thu nhập bình quân đầu người chỉ ở mức 98 USD, thấp hơn cả nhiều nước châu Phi. Đến nay, con số này đã vươn lên khoảng 5.000 USD/năm. Dù mức này vẫn còn khiêm tốn, nhưng sự tăng trưởng đó thể hiện một bước nhảy kinh tế lớn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quá trình trỗi dậy bắt đầu từ thập niên 1990, thời điểm Việt Nam tiến hành Đổi mới và mở cửa nền kinh tế, từ đó từng bước thu hút dòng vốn đầu tư nước ngoài. Hiện Việt Nam được đánh giá là nền kinh tế thị trường năng động nhất Đông Nam Á.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mắt xích quan trọng trong chiến lược thương mại của EU</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều tập đoàn lớn của Đức như Siemens, Bosch, Adidas, Mercedes-Benz hay Heidelberger Druckmaschinen đã hoạt động lâu năm tại Việt Nam. Làn sóng đầu tư trong lĩnh vực công nghệ hiện vẫn tiếp tục tăng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đáng chú ý là dự án của SAP – tập đoàn phần mềm lớn nhất châu Âu. Mùa hè vừa qua, SAP công bố thành lập trung tâm đổi mới số SAP Labs tại TP.HCM với kế hoạch đầu tư 150 triệu euro trong vòng 5 năm. Đại diện của SAP cho biết Việt Nam không chỉ là nơi làm gia công đơn thuần.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo ông Arjun Kumar Rao, điều phối chuỗi cung ứng SAP, \"Việt Nam có đội ngũ kỹ sư công nghệ thông tin trình độ cao. Họ học từ chúng tôi, nhưng chúng tôi cũng học được rất nhiều từ họ\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ông Florian Witt (ODDO BHF) nhấn mạnh Việt Nam là đối tác thương mại lớn nhất của EU trong khối ASEAN. Trong khuôn khổ sáng kiến Global Gateway hỗ trợ quá trình chuyển đổi năng lượng công bằng (JETP), EU đã dành 430 triệu euro cho dự án thủy điện tích năng – một dự án trọng điểm.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngoài ra, Việt Nam và Ngân hàng Đầu tư châu Âu (EIB) đã ký khoản vay trị giá 500 triệu euro, cùng 142 triệu euro hỗ trợ ngân sách cho cải cách năng lượng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhờ ổn định chính trị, lực lượng lao động trẻ, khát vọng đi lên và chính sách mở cửa, Việt Nam đang nổi lên như một trung tâm sản xuất, công nghệ và năng lượng sạch mới của châu Á, đồng thời trở thành đối tác ngày càng quan trọng của Đức và Liên minh châu Âu.</span></span></span></p>', '2025-12-03 06:36:00', 'https://bacninh.gov.vn/news/-/details/37632/chuyen-gia-uc-an-tuong-ve-su-vuon-minh-cua-nen-kinh-te-viet-nam-64569905', '', 'chinhphu.vn', 16, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.532022', 9, 11);
INSERT INTO `sync_articles` VALUES (350, '64458205', 'Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ...', 'Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/dai-su-nb-1764242226433203097324.jpeg', '<p>Đại sứ Nhật Bản tại Việt Nam ITO Naoki khẳng định điều này khi gặp gỡ báo chí, chia sẻ về những tiến triển mới trong quan hệ hợp tác song phương nhân dịp kỷ niệm 2 năm Việt Nam và Nhật Bản thiết lập quan hệ Đối tác chiến lược toàn diện vì hòa bình và ổn định tại châu Á và trên thế giới (CSP)...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/dai-su-nb-1764242226433203097324.jpeg\" target=\"_blank\" title=\"Đại sứ Nhật Bản tại Việt Nam ITO Naoki tại cuộc gặp gỡ báo chí ngày 27/11 - Ảnh: TH\"><img alt=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/dai-su-nb-1764242226433203097324.jpeg\" h=\"1157\" id=\"img_918461256592146432\" loading=\"lazy\" photoid=\"918461256592146432\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/dai-su-nb-1764242226433203097324.jpeg\" style=\"width: 700px; height: 405px;\" title=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Nhật Bản tại Việt Nam ITO Naoki tại cuộc gặp gỡ báo chí ngày 27/11 - Ảnh: TH</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ ITO Naoki cho biết, dưới sự lãnh đạo của Thủ tướng Takaichi Sanae, chính quyền mới của Nhật Bản \"không thay đổi bất kỳ chủ trương nào đối với Việt Nam\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay sau khi nhậm chức cuối tháng 10, Thủ tướng Takaichi Sanae đã có 3 cuộc gặp gỡ với lãnh đạo cấp cao của Việt Nam tại các diễn đàn đa phương. Cụ thể, Thủ tướng Takaichi Sanae hội kiến Chủ tịch nước Lương Cường tại Hội nghị Thượng đỉnh APEC; hội kiến Thủ tướng Phạm Minh Chính tại Hội nghị Thượng đỉnh ASEAN ở Kuala Lumpur và Hội nghị Thượng đỉnh G20 ở Nam Phi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại các cuộc gặp, Thủ tướng Takaichi đã tái khẳng định tầm quan trọng của mối quan hệ Đối tác chiến lược toàn diện vì hòa bình và ổn định tại châu Á và trên thế giới giữa Nhật Bản và Việt Nam. Hai bên cam kết tiếp tục duy trì, tăng cường và phát triển hơn nữa mối quan hệ đối tác này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Diễn đàn Hợp tác địa phương Việt Nam – Nhật Bản diễn ra hôm 25/11 tại Quảng Ninh, Thủ tướng Phạm Minh Chính tham dự và đưa ra nhiều định hướng hợp tác mới và Thủ tướng Takaichi Sanae gửi thông điệp khẳng định tầm quan trọng của giao lưu địa phương trong tổng thể quan hệ song phương.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/ttgttgnb-26-10-176424230642568327428.jpg\" target=\"_blank\" title=\"Thủ tướng Phạm Minh Chính gặp Thủ tướng Nhật Bản Takaichi Sanae tại Hội nghị Thượng đỉnh ASEAN ở Kuala Lumpur ngày 26/10\"><img alt=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/ttgttgnb-26-10-176424230642568327428.jpg\" h=\"518\" id=\"img_918461588197056512\" loading=\"lazy\" photoid=\"918461588197056512\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/ttgttgnb-26-10-176424230642568327428.jpg\" style=\"width: 700px; height: 467px;\" title=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 2.\" type=\"photo\" w=\"777\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" id=\"\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Phạm Minh Chính gặp Thủ tướng Nhật Bản Takaichi Sanae tại Hội nghị Thượng đỉnh ASEAN ở Kuala Lumpur ngày 26/10</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vào tháng 4 năm nay, Thủ tướng Ishiba Shigeru đã đến thăm Việt Nam và khẳng định với các nhà lãnh đạo Việt Nam rằng Nhật Bản ủng hộ định hướng cải cách mà Việt Nam đang thúc đẩy để bước vào \"kỷ nguyên mới\", đồng thời nhấn mạnh Nhật Bản sẽ tiếp tục là đối tác không thể thay thế, đồng hành vì sự phát triển mạnh mẽ hơn nữa của Việt Nam. Các nhà lãnh đạo Nhật Bản đều khẳng định quyết tâm duy trì và củng cố mối quan hệ vững chắc với Việt Nam.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Bán dẫn và đổi mới sáng tạo: Trụ cột hợp tác Việt Nam – Nhật Bản</b></span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điểm lại những thành tựu hợp tác song phương trong hai năm qua, Đại sứ ITO Naoki cho biết các lĩnh vực chuyển đổi số và chuyển đổi xanh, bán dẫn và đổi mới sáng tạo đều đã đạt được những bước tiến quan trọng và được xác định là trụ cột hợp tác của hai bên.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong lĩnh vực bán dẫn, Việt Nam đặt mục tiêu đào tạo 500 nghiên cứu sinh tiến sĩ từ nay đến năm 2030. Nhật Bản đã tuyên bố sẽ tiếp nhận khoảng một nửa trong số đó, tương đương 250 người, thông qua các chương trình nghiên cứu hợp tác quốc tế. Trong 3 năm rưỡi tới, Nhật Bản sẽ tiếp nhận 63 nghiên cứu sinh tiến sĩ Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Trường Đại học Việt – Nhật, từ tháng 10 năm nay đã khai giảng khóa cử nhân ngành bán dẫn, hiện có 106 sinh viên theo học, góp phần hình thành lực lượng nhân sự cốt lõi cho ngành công nghệ mũi nhọn mà Việt Nam đang hướng tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong lĩnh vực đổi mới sáng tạo, JICA đang hỗ trợ các doanh nghiệp startup Việt Nam để giúp họ thu hút đầu tư và hoàn thiện hệ sinh thái khởi nghiệp.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng hành chuyển đổi xanh, tăng cường kết nối kinh tế và an ninh khu vực</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, chuyển đổi xanh và năng lượng là lĩnh vực được hai nước thúc đẩy mạnh mẽ. Trong khuôn khổ Sáng kiến \"Cộng đồng phát thải ròng bằng 0 châu Á\" (AZEC) , Nhật Bản phối hợp cùng Việt Nam phát triển điện gió ngoài khơi, năng lượng tái tạo và các dự án LNG. Khoảng 15 dự án năng lượng sạch trị giá 20 tỷ USD đang được triển khai. JICA dự kiến cung cấp khoản vay 300 triệu USD hỗ trợ ứng phó biến đổi khí hậu và chuyển đổi xanh tại Đồng bằng sông Cửu Long, giúp giảm phát thải, tăng năng suất và tăng cường khả năng chống chịu thiên tai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Đại sứ&nbsp;ITO Naoki, hạ tầng chiến lược là dấu mốc nổi bật trong quan hợp tác Việt Nam – Nhật Bản. Nhiều dự án lớn đang được triển khai gồm: Metro số 1 TPHCM, Metro số 2 Hà Nội, Thành phố thông minh phía bắc Hà Nội, Nhà máy xử lý nước thải Yên Xá, dự án điện gió Quảng Trị, Nhà máy điện Ô Môn 4, Aeon Mall Hải Dương...</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ cho biết, trong năm nay, Thủ tướng Phạm Minh Chính đã tổ chức hai lần đối thoại </span>với doanh nghiệp Nhật Bản nhằm cải thiện môi trường đầu tư. Các vấn đề về gia hạn giấy phép đầu tư đã được tháo gỡ, tạo niềm tin cho cộng đồng doanh nghiệp. Hiện có khoảng 2.000 doanh nghiệp Nhật hoạt động tại Việt Nam; theo khảo sát của JETRO, 60% trong số này muốn mở rộng đầu tư.</span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/27-11ttgdiendan-1764242786627136617375.jpg\" target=\"_blank\" title=\"Diễn đàn Hợp tác địa phương Việt Nam – Nhật Bản diễn ra hôm 25/11 tại Quảng Ninh thu hút đại diện 16 địa phương Nhật Bản và hơn 30 tỉnh, thành phố của Việt Nam - Ảnh: VGP/Nhật Bắc\"><img alt=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/27-11ttgdiendan-1764242786627136617375.jpg\" h=\"1333\" id=\"img_918463603569401856\" loading=\"lazy\" photoid=\"918463603569401856\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/27-11ttgdiendan-1764242786627136617375.jpg\" style=\"width: 700px; height: 467px;\" title=\"Đại sứ ITO Naoki: Chính quyền mới của Nhật Bản mong muốn duy trì và mở rộng quan hệ với Việt Nam- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Diễn đàn Hợp tác địa phương Việt Nam – Nhật Bản diễn ra hôm 25/11 tại Quảng Ninh thu hút đại diện 16 địa phương Nhật Bản và hơn 30 tỉnh, thành phố của Việt Nam - Ảnh: VGP/Nhật Bắc</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thương mại song phương năm nay đạt 42,5 tỷ USD, tăng 11% so với cùng kỳ; dự kiến có thể đạt mốc 50 tỷ USD trong năm tới. Đầu tư Nhật Bản vào Việt Nam đạt 2,6 tỷ USD, tăng 18% so với năm ngoái.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ tháng 1 đến tháng 10 năm nay, 580.000 du khách Việt Nam đến Nhật Bản, trong khi khoảng 680.000 người Nhật Bản sang Việt Nam, lần lượt tăng 10% và 16% so với cùng kỳ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tháng 12 tới, Việt Nam và Nhật Bản sẽ lần đầu tiên tổ chức Hội nghị 2+2 ở cấp Thứ trưởng Ngoại giao – Quốc phòng tại Tokyo. Đây sẽ là cơ hội để các cơ quan ngoại giao và quốc phòng hai nước thảo luận về các vấn đề chiến lược trong khu vực, trao đổi cởi mở về hợp tác công nghiệp quốc phòng, chuyển giao trang thiết bị cũng như tình hình quốc tế. Hai bên hướng tới mục tiêu hợp tác để góp phần duy trì hòa bình và ổn định trong khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm nay, tàu Hải quân Nhật Bản đã thăm Việt Nam và tàu Cảnh sát biển Việt Nam giao lưu tại Nhật Bản. Nhật Bản tiếp tục theo đuổi chiến lược Ấn Độ Dương – Thái Bình Dương tự do và rộng mở, đề cao luật pháp quốc tế và trật tự dựa trên luật lệ. Nhật Bản mong muốn hợp tác cùng Việt Nam nỗ lực hơn nữa để hiện thực hóa mục tiêu này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ ITO Naoki cho biết, năm nay, lần đầu tiên Việt Nam và Nhật Bản thực hiện dẫn độ tội phạm dựa trên hiệp định ký năm 2020, đánh dấu bước tiến mới trong hợp tác pháp lý – tư pháp. Đây cũng là một hình thức hợp tác mới đang tiến triển giữa hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, Đại sứ gửi lời chia sẻ, thăm hỏi chân thành và mong người dân vùng lũ lụt miền Trung sớm vượt qua khó khăn, ổn định cuộc sống.</span></span></span></p>', '2025-12-02 06:08:00', 'https://bacninh.gov.vn/news/-/details/37632/-ai-su-ito-naoki-chinh-quyen-moi-cua-nhat-ban-mong-muon-duy-tri-va-mo-rong-quan-he-voi-viet-nam-64458205', '', 'chinhphu.vn', 7, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.556617', 9, 11);
INSERT INTO `sync_articles` VALUES (351, '64046901', 'Cộng đồng quốc tế đã hỗ trợ Việt Nam gần 16 triệu USD khắc phục hậu quả bão lũ', 'Cộng đồng quốc tế đã hỗ trợ Việt Nam gần 16 triệu USD khắc phục hậu quả bão lũ', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/bao-lu-17642351167061124757298.jpg', '<p>Việt Nam đã nhận được gần 16 triệu USD hỗ trợ khắc phục hậu quả của cộng đồng quốc tế. Chính phủ và nhân dân Việt Nam luôn trân trọng và biết ơn sự ủng hộ, giúp đỡ kịp thời, thiết thực và quý báu này.</p>', '<h1 data-role=\"title\" style=\"text-align: justify;\">&nbsp;</h1>\n\n<figure type=\"Photo\">\n<p><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/bao-lu-17642351167061124757298.jpg\" target=\"_blank\" title=\"Tình hình mưa lũ tại miền Trung vẫn diễn biến phức tạp\"><img alt=\"Cộng đồng quốc tế đã hỗ trợ Việt Nam gần 16 triệu USD khắc phục hậu quả bão lũ- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/bao-lu-17642351167061124757298.jpg\" h=\"950\" id=\"img_918431433055510528\" loading=\"lazy\" photoid=\"918431433055510528\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/bao-lu-17642351167061124757298.jpg\" style=\"width: 700px; height: 332px;\" title=\"Cộng đồng quốc tế đã hỗ trợ Việt Nam gần 16 triệu USD khắc phục hậu quả bão lũ- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tình hình mưa lũ tại miền Trung vẫn diễn biến phức tạp</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vừa qua, nhiều địa phương của Việt Nam đã phải hứng chịu các đợt mưa lũ lịch sử và thiên tai liên tiếp gây thiệt hại nghiêm trọng về người và tài sản. Tại họp báo thường kỳ Bộ Ngoại giao chiều 27/11, người phát ngôn Bộ ngoại giao Phạm Thu Hằng cho biết: Trước những mất mát hết sức nặng nề này, cho đến nay Việt Nam đã nhận được sự chia sẻ, động viên và hỗ trợ về tài chính cùng với các nhu yếu phẩm, các trang thiết bị từ cộng đồng quốc tế, các nước và từ các tổ chức quốc tế, ước tính cho tới thời điểm này là gần 16 triệu USD.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguồn lực này sẽ được các cơ quan chức năng của Việt Nam phân phối trực tiếp đến các khu vực bị ảnh hưởng và đến tận tay người dân bị ảnh hưởng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những ngày qua, chúng ta đã chứng kiến nhiều câu chuyện xúc động: Bạn bè quốc tế và du khách nước ngoài cùng người dân, chính quyền tại nhiều tỉnh, thành phố ở Việt Nam chung tay hỗ trợ người dân gặp khó khăn bằng nhiều hình thức khác nhau, bà Phạm Thu Hằng cho biết.&nbsp;</span></span></span></p>\n\n<p id=\"\" style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đây là sự động viên to lớn, thể hiện tinh thần tương trợ quốc tế, tinh thần đoàn kết quốc tế, nhằm giúp nhân dân các địa phương của Việt Nam bị thiệt hại sớm vượt qua khó khăn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ và nhân dân Việt Nam luôn trân trọng và biết ơn sự ủng hộ, giúp đỡ kịp thời, thiết thực và quý báu này.</span></span></span></p>', '2025-12-02 04:08:00', 'https://bacninh.gov.vn/news/-/details/37632/cong-ong-quoc-te-a-ho-tro-viet-nam-gan-16-trieu-usd-khac-phuc-hau-qua-bao-lu-64046901', '', 'chinhphu.vn', 4, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.588767', 9, 11);
INSERT INTO `sync_articles` VALUES (352, '64037008', 'Đông Nam Á đóng vai trò trung tâm đối với tương lai của New Zealand', 'Đông Nam Á đóng vai trò trung tâm đối với tương lai của New Zealand', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/mfa-photo-1764231538526586101154.jpg', '<p>Bộ trưởng Ngoại giao New Zealand Winston Peters nhấn mạnh, \"chúng tôi đặt nhiều kỳ vọng hơn vào làm sâu sắc hơn quan hệ đối tác trong toàn khu vực Đông Nam Á bởi đây là khu vực đóng vai trò trung tâm đối với tương lai của New Zealand\".</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/mfa-photo-1764231538526586101154.jpg\" target=\"_blank\" title=\"Bộ trưởng Ngoại giao New Zealand Winston Peters\"><img alt=\"Đông Nam Á đóng vai trò trung tâm đối với tương lai của New Zealand- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/27/mfa-photo-1764231538526586101154.jpg\" h=\"1510\" id=\"img_918416429447094272\" loading=\"lazy\" photoid=\"918416429447094272\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/27/mfa-photo-1764231538526586101154.jpg\" style=\"width: 700px; height: 529px;\" title=\"Đông Nam Á đóng vai trò trung tâm đối với tương lai của New Zealand- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Ngoại giao New Zealand Winston Peters.</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhận lời mời của Bộ trưởng Ngoại giao Lê Hoài Trung, Bộ trưởng Ngoại giao New Zealand Winston Peters có chuyến thăm chính thức Việt Nam và đồng chủ trì Hội nghị Bộ trưởng Ngoại giao Việt Nam-New Zealand lần thứ 3 trong hai ngày 25-26/11. Nhân dịp này, Bộ trưởng Winston Peters đã có bài viết với tiêu đề: “Việt Nam – New Zealand: Kiến tạo tương lai chung”.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Bộ trưởng Ngoại giao New Zealand, trong 18 tháng qua, hai bên đã nỗ lực tăng cường hợp tác và \"chúng ta vui mừng nâng cấp quan hệ lên Đối tác Chiến lược Toàn diện, một dấu mốc quan trọng nhân dịp kỷ niệm 50 năm thiết lập quan hệ ngoại giao\". Đây là một cam kết nghiêm túc và thiết thực để cùng nhau nỗ lực hơn nữa. Trong khuôn khổ chuyến thăm, hai bên đã ký kết Chương trình Hành động, thúc đẩy các sáng kiến cụ thể trên tất cả các lĩnh vực trong 5 năm tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Winston Peters nhấn mạnh rằng New Zealand đặt nhiều kỳ vọng hơn vào làm sâu sắc hơn quan hệ đối tác trong toàn khu vực Đông Nam Á bởi đây là khu vực đóng vai trò trung tâm đối với tương lai của New Zealand. Thế giới đang thay đổi, cạnh tranh toàn cầu gia tăng, chuỗi cung ứng dịch chuyển và các quy tắc chi phối thương mại, công nghệ và an ninh đang được viết lại.</span></span></span></p>\n\n<p id=\"\" style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Winston Peters cho biết, 18 tháng trước, New Zealand đã điều chỉnh chính sách đối ngoại, tập trung hơn, nhịp độ nhanh hơn và kỳ vọng cao hơn với các đối tác chủ chốt. Đây là những hợp tác thiết thực mang lại thịnh vượng và an ninh cho cả hai quốc gia. Và hợp tác với Việt Nam đóng vai trò trung tâm trong nỗ lực này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình Hành động vừa ký kết xác lập các trụ cột quan trọng trong quan hệ song phương: Tăng cường khả năng chống chịu, hợp tác khoa học và công nghệ, quốc phòng và an ninh. Các lĩnh vực này nhằm mang lại kết quả thiết thực. Hai bên cũng đặt mục tiêu thương mại hai chiều đạt 3 tỷ USD vào năm 2026, nhấn mạnh kỳ vọng tăng trưởng quy mô hợp tác kinh tế giữa hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với tốc độ tăng trưởng khoảng 6%, Việt Nam đang cho thấy lộ trình rõ ràng để đạt được vị thế thu nhập cao. Các khoản đầu tư của Việt Nam vào cơ sở hạ tầng kỹ thuật số, sản xuất tiên tiến và kinh tế xanh phù hợp với thế mạnh của New Zealand về hệ thống nông nghiệp – thực phẩm, năng lượng tái tạo và công nghệ. Các doanh nghiệp xuất khẩu New Zealand tìm thấy cơ hội trong thực phẩm và đồ uống chất lượng cao, giáo dục và dịch vụ tại Việt Nam, trong khi các doanh nghiệp đổi mới sáng tạo nhìn thấy tiềm năng trong thương mại kỹ thuật số và các giải pháp ứng phó biến đổi khí hậu. Hai chính phủ cùng cam kết về mở cửa thị trường và phát triển bền vững, tạo triển vọng hợp tác kinh tế đầy hấp dẫn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, hợp tác về an ninh cũng là lĩnh vực trọng yếu. Giao lưu nhân dân là nền tảng của quan hệ song phương. Các chương trình học bổng đã đưa sinh viên xuất sắc Việt Nam sang New Zealand, mạng lưới cựu sinh viên, các chương trình thực tập và giao lưu biến trải nghiệm một lần thành mối quan hệ trọn đời. Du lịch và kết nối hàng không cũng gắn kết xã hội hai nước. Cộng đồng kiều bào New Zealand gốc Đông Nam Á đóng vai trò cầu nối, giúp tăng cường niềm tin và hiểu biết thực tiễn về khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Winston Peters nhấn mạnh, việc điều chỉnh chính sách đối ngoại không chỉ vì tương lai New Zealand, mà còn nhằm xây dựng các mối quan hệ đối tác mang lại lợi ích cho cả hai quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với kỳ vọng, sự tin cậy lẫn nhau và các kết quả thực tiễn, New Zealand sẵn sàng đồng hành cùng Việt Nam, vạch ra lộ trình chung hướng tới thịnh vượng, an ninh và khả năng chống chịu trong một khu vực có ý nghĩa chiến lược đối với cả hai nước./.&nbsp;</span></span></span></p>', '2025-12-02 04:06:00', 'https://bacninh.gov.vn/news/-/details/37632/-ong-nam-a-ong-vai-tro-trung-tam-oi-voi-tuong-lai-cua-new-zealand-64037008', '', 'chinhphu.vn', 8, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.622475', 9, 11);
INSERT INTO `sync_articles` VALUES (353, '64016501', 'UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới', 'UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/26/ba-june-kunugi-17641433718261608598094.jpg', '<p>Phát biểu tại Lễ kỷ niệm 50 năm hợp tác giữa Việt Nam và Quỹ Nhi đồng Liên Hợp Quốc (UNICEF), 35 năm Việt Nam phê chuẩn Công ước Liên Hợp Quốc về quyền trẻ em, bà June Kunugi, Giám đốc UNICEF khu vực Đông Á-Thái Bình Dương nhấn mạnh: \"Cùng nhau, chúng ta có thể biến tham vọng thành hành động và...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/26/ba-june-kunugi-17641433718261608598094.jpg\" target=\"_blank\" title=\"Bà June Kunugi, Giám đốc UNICEF khu vực Đông Á-Thái Bình Dương: &quot;Cùng nhau, chúng ta có thể biến tham vọng thành hành động và đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới&quot; - Ảnh: VGP/Đức Tuân\"><img alt=\"UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/26/ba-june-kunugi-17641433718261608598094.jpg\" h=\"1283\" id=\"img_918046628864524288\" loading=\"lazy\" photoid=\"918046628864524288\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/26/ba-june-kunugi-17641433718261608598094.jpg\" style=\"width: 700px; height: 449px;\" title=\"UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà June Kunugi, Giám đốc UNICEF khu vực Đông Á-Thái Bình Dương: \"Cùng nhau, chúng ta có thể biến tham vọng thành hành động và đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới\" - Ảnh: VGP/Đức Tuân</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những kết quả phi thường sau 50 năm hợp tác</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà June Kunugi nhấn mạnh: \"50 năm trước, Việt Nam vừa thoát khỏi chiến tranh, nhưng ngày nay, Việt Nam đã đạt những bước tiến rất ấn tượng, là đất nước nơi trẻ em được sống, được học tập và phát triển\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam đã giảm tỉ lệ tử vong trẻ dưới 5 tuổi từ hơn 100 ca/1.000 ca sinh sống xuống còn 16,9 ca, đạt nhiều thành tựu trong dinh dưỡng, phòng chống bệnh bại liệt và chiến dịch tiêm vaccine phòng COVID-19. Hơn 96% dân số đã được tiếp cận nước sạch và vệ sinh cơ bản, tỉ lệ trẻ suy dinh dưỡng, thấp còi đã giảm từ gần 30% xuống còn 18%. Việt Nam đã hoàn thành phổ cập giáo dục tiểu học vào năm 2000 và phổ cập THCS vào năm 2010; đạt bình đẳng giới về tỉ lệ nhập học và duy trì ở cấp tiểu học và trung học.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp cận giáo dục mầm non được mở rộng, trong đó chú trọng trẻ em khuyết tật và trẻ em dân tộc thiểu số. Khung quốc gia về học tập số được hình thành. Hệ thống bảo vệ trẻ em được tăng cường nhằm phòng ngừa và bảo vệ trẻ em khỏi bạo lực, xâm hại. Các dịch vụ xã hội thân thiện khí hậu tiếp tục được củng cố, hỗ trợ trẻ em có một tương lai bền vững hơn...</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ba lĩnh vực UNICEF tiếp tục hỗ trợ Việt Nam</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước bối cảnh thế giới thay đổi nhanh chóng, UNICEF xác định ba lĩnh vực trọng tâm hỗ trợ Việt Nam và trẻ em Việt Nam.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ nhất, đầu tư vào trẻ em và phát triển nguồn vốn con người, trong đó tiếp tục cung cấp các dịch vụ y tế, giáo dục, bảo vệ trẻ em và bảo trợ xã hội như những nền tảng để xây dựng một hệ thống và nền kinh tế bền vững, ổn định và kiên cường hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai, bảo đảm an toàn và trao quyền cho mọi trẻ em, đồng thời củng cố các cơ chế lập kế hoạch, phân bổ ngân sách nhằm duy trì những thành tựu đã đạt được trong bối cảnh già hóa dân số.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ ba, trước tác động của biến đổi khí hậu và ô nhiễm môi trường, cần tăng cường bảo vệ và nâng cao khả năng chống chịu của trẻ em và cộng đồng. Việc đầu tư vào hệ thống giảm thiểu rủi ro thiên tai và tăng khả năng chống chịu của hệ thống bảo trợ xã hội nhạy cảm với cú sốc là hết sức quan trọng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà June Kunugi nhấn mạnh, UNICEF chúc mừng Việt Nam vì những cải cách mạnh mẽ và những mục tiêu đầy tham vọng. Kỷ nguyên vươn mình là cơ hội để đầu tư vào nguồn nhân lực hơn bao giờ hết. Chúng ta cần xây dựng một thế hệ mạnh khỏe, được giáo dục và được trao quyền. UNICEF sẽ tiếp tục sát cánh cùng Việt Nam để hiện thực hóa tầm nhìn này thông qua việc chia sẻ chuyên môn toàn cầu, các giải pháp dựa trên bằng chứng và các quan hệ đối tác sáng tạo\".</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà khẳng định, UNICEF sẽ tiếp tục hợp tác và hỗ trợ Chính phủ cùng các đối tác nhằm thu hẹp những khoảng trống còn tồn tại; tận dụng cơ hội kỹ thuật số một cách an toàn để giới trẻ sẵn sàng cho nền kinh tế tương lai; bảo đảm khả năng chống chịu biến đổi khí hậu và hòa nhập xã hội được đặt ở trọng tâm của mọi chính sách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">\"Cùng nhau, chúng ta có thể biến tham vọng thành hành động và đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới\", bà June Kunugi nhấn mạnh.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/26/ba-sopio-kiladze-17641433718351418958333.jpg\" target=\"_blank\" title=\"Chủ tịch Ủy ban Liên Hợp Quốc về quyền trẻ em Sophie Kiladze: Những thành tựu của Việt Nam không chỉ nằm ở hệ thống pháp luật mà còn được thể hiện trong cuộc sống của trẻ em - Ảnh: VGP/Đức Tuân\"><img alt=\"UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/26/ba-sopio-kiladze-17641433718351418958333.jpg\" h=\"1294\" id=\"img_918046628529692672\" loading=\"lazy\" photoid=\"918046628529692672\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/26/ba-sopio-kiladze-17641433718351418958333.jpg\" style=\"width: 700px; height: 453px;\" title=\"UNICEF: Đưa Việt Nam trở thành hình mẫu về quyền trẻ em trong khu vực và trên thế giới- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" id=\"\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Ủy ban Liên Hợp Quốc về quyền trẻ em Sophie Kiladze: Những thành tựu của Việt Nam không chỉ nằm ở hệ thống pháp luật mà còn được thể hiện trong cuộc sống của trẻ em - Ảnh: VGP/Đức Tuân</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khi đó, bà Sophie Kiladze, Chủ tịch Ủy ban Liên Hợp Quốc về quyền trẻ em nêu rõ: 35 năm trước, Việt Nam đã làm nên lịch sử khi trở thành quốc gia đầu tiên ở châu Á và quốc gia thứ hai trên thế giới phê chuẩn Công ước Liên Hợp Quốc về quyền trẻ em. Bước tiến này không chỉ phản ánh cam kết sâu sắc của Việt Nam đối với trẻ em, mà còn thể hiện tầm nhìn về một tương lai được xây dựng trên nền tảng tôn trọng đầy đủ phẩm giá của trẻ em và coi trẻ em là những chủ thể có quyền.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ thời điểm quan trọng đó tới nay, Việt Nam không chỉ dừng lại ở cam kết trên giấy tờ mà đã biến những cam kết đó thành kết quả thực chất cho trẻ em. Việt Nam đã thiết lập khuôn khổ pháp lý và chính sách toàn diện nhằm hiện thực hóa các cam kết của Công ước đối với mọi trẻ em.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều này thể hiện rõ qua việc quy định quyền trẻ em trong Hiến pháp; ban hành Luật Trẻ em năm 2016; sửa đổi Luật Giáo dục, Bộ luật Lao động, Luật Thống kê… tạo nền tảng vững chắc cho bảo vệ, phát triển và sự tham gia của trẻ em trên toàn quốc.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những thành tựu của Việt Nam không chỉ nằm ở hệ thống pháp luật mà còn được thể hiện trong cuộc sống của trẻ em. Trong hơn 3,5 thập kỷ qua, Việt Nam đã đạt tiến bộ đáng kể trong giảm tỉ lệ tử vong trẻ em, giảm nghèo trẻ em, tăng cường tiếp cận giáo dục chất lượng, phòng chống lao động trẻ em, tảo hôn, cải thiện tiếp cận nước sạch và vệ sinh, đặc biệt tại vùng nông thôn, vùng sâu, vùng xa. Việt Nam cũng đã củng cố hệ thống tư pháp trẻ em và tập trung hỗ trợ trẻ em ở những cộng đồng khó khăn thông qua các chương trình mục tiêu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bà Sophie Kiladze chia sẻ: \"Tôi đến từ một quốc gia nhỏ từng trải qua xung đột vũ trang, nên tôi hiểu rằng những thành tựu này không phải tự nhiên mà có, mà được tạo dựng từ những nỗ lực bền bỉ trong suốt thời gian dài\".</span></span></span></p>', '2025-12-02 04:00:00', 'https://bacninh.gov.vn/news/-/details/37632/unicef-ua-viet-nam-tro-thanh-hinh-mau-ve-quyen-tre-em-trong-khu-vuc-va-tren-the-gioi-64016501', '', 'chinhphu.vn', 4, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.653538', 9, 11);
INSERT INTO `sync_articles` VALUES (354, '63999105', 'Tổng thống Nga Putin gửi lời chia buồn với Việt Nam về thiệt hại do lũ lụt', 'Tổng thống Nga Putin gửi lời chia buồn với Việt Nam về thiệt hại do lũ lụt', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/25/image-17640451359301587576572-1764047172476865564166.jpg', '<p>Ngày 24/11 Tổng thống Nga Vladimir Putin gửi tới Tổng Bí thư Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam Tô Lâm và Chủ tịch nước Lương Cường điện chia buồn về thiệt hại do lũ lụt vừa qua tại miền Trung Việt Nam.</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/25/image-17640451359301587576572-1764047172476865564166.jpg\" target=\"_blank\" title=\"Đợt mưa lũ vừa qua làm nhiều khu vực tại Gia Lai bị ngập sâu - Ảnh: An Nhiên\"><img alt=\"Tổng thống Nga Putin gửi lời chia buồn với Việt Nam về thiệt hại do lũ lụt- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/11/25/image-17640451359301587576572-1764047172476865564166.jpg\" h=\"480\" id=\"img_917643136995885056\" loading=\"lazy\" photoid=\"917643136995885056\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/11/25/image-17640451359301587576572-1764047172476865564166.jpg\" style=\"width: 700px; height: 525px;\" title=\"Tổng thống Nga Putin gửi lời chia buồn với Việt Nam về thiệt hại do lũ lụt- Ảnh 1.\" type=\"photo\" w=\"640\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đợt mưa lũ vừa qua làm nhiều khu vực tại Gia Lai bị ngập sâu - Ảnh: An Nhiên</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo nội dung bức điện được đăng tải trên Trang web chính thức của Điện Kremlin, Tổng thống Putin nhấn mạnh mức độ nghiêm trọng của tình hình tại các khu vực miền Trung Việt Nam và gửi lời chia buồn chân thành nhất về những hậu quả của lũ lụt ở các khu vực miền Trung của Việt Nam. \"Xin gửi lời chia buồn và sự hỗ trợ tới gia đình và bạn bè của các nạn nhân, cũng như lời chúc tất cả những người bị ảnh hưởng bởi thảm họa thiên nhiên này sớm bình phục\". Điện thăm hỏi của Tổng thống Putin được nhiều tờ báo của Nga đăng tải.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Miền Trung Việt Nam đã bị thiệt hại nặng nề do lũ lụt lớn xảy ra vì mưa lớn. Theo báo chí Nga, có khoảng 70 công dân Nga có mặt tại tỉnh Khánh Hòa của Việt Nam khi xảy ra lũ lụt.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo báo cáo mới đây từ Bộ Nông nghiệp và Môi trường Việt Nam, đợt mưa lũ kéo dài tại miền Trung đã gây thiệt hại kinh tế sơ bộ gần 14.000 tỷ đồng, 102 người chết và mất tích, hàng trăm nghìn ngôi nhà bị ngập…</span></span></span></p>', '2025-12-02 03:58:00', 'https://bacninh.gov.vn/news/-/details/37632/tong-thong-nga-putin-gui-loi-chia-buon-voi-viet-nam-ve-thiet-hai-do-lu-lut-63999105', '', 'chinhphu.vn', 1, 'Tin quốc tế', 9, '', '38762', '{}', '2025-12-08 08:18:12.680193', 9, 11);
INSERT INTO `sync_articles` VALUES (355, '80467301', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 29/11 – 5/12/2025', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 29/11 – 5/12/2025', '/documents/37632/80512902/6-1.png/2595f5b4-8d9c-5ea7-c6d0-0f1242b051a1?t=1765017950048', '<p>(BNP) - Kỷ niệm 117 năm Ngày sinh đồng chí Ngô Gia Tự; Đại hội đại biểu Phụ nữ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 – 2030; tôn vinh trí thức Bắc Ninh tiêu biểu, trao Giải thưởng Khoa học và Công nghệ; khai mạc Lễ hội Trái cây tỉnh Bắc Ninh năm 2025… là những hoạt động nổi bật của lãnh đạo...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200616/IMG_9409+%281%29.jpg/11260514-1db5-c554-1495-c0af1ca7065d?t=1764725770292\" style=\"width: 900px; height: 606px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân kỷ niệm 117 năm Ngày sinh đồng chí Ngô Gia Tự (03/12/1908 - 03/12/2025), sáng 03/12, Đoàn đại biểu Tỉnh ủy - HĐND - UBND - Ủy ban MTTQ - Đoàn ĐBQH tỉnh Bắc Ninh đến dâng hương tưởng niệm tại tượng đài đồng chí Ngô Gia Tự (phường Tam Sơn và&nbsp; phường Bắc Giang, tỉnh Bắc Ninh). Tham dự Lễ dâng hương có các đồng chí:&nbsp;Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy;&nbsp;Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy;&nbsp;Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí trong Ban Thường vụ Tỉnh ủy, Thường trực HĐND, UBND, Ủy ban MTTQ tỉnh; lãnh đạo các Sở, ban, ngành, đoàn thể tỉnh, phường Tam Sơn, phường Bắc Giang; đại diện gia đình, dòng họ đồng chí Ngô Gia Tự; các thầy cô giáo và học sinh Trường THPT Ngô Gia Tự.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/30456130/29-8.png/281ccb05-ed18-b0fb-2fb6-d62425d5a6b8?t=1764389188186\" style=\"width: 900px; height: 557px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 29/11, tại Trung tâm hội nghị tỉnh diễn ra phiên chính thức Đại hội đại biểu Phụ nữ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030. Dự và chúc mừng Đại hội có các đồng chí: Nguyễn Thị Tuyến, Ủy viên Trung ương Đảng, Phó Chủ tịch Ủy ban Trung ương MTTQ Việt Nam, Chủ tịch Hội Liên hiệp Phụ nữ (LHPN) Việt Nam; Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy, Thường trực HĐND, lãnh đạo UBND, Ủy ban MTTQ, Đoàn đại biểu Quốc hội tỉnh; các Mẹ Việt Nam Anh hùng; đại diện lãnh đạo các sở, ban, ngành địa phương trong tỉnh cùng 298 đại biểu tiêu biểu đại diện cho gần 618.000 hội viên phụ nữ trong tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/30456112/30-11-2.png/cc031e02-b55f-5e7a-38ec-9bfb00f1db36?t=1764482461974\" style=\"width: 900px; height: 572px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 30/11, tại Trung tâm Hội nghị tỉnh, UBND tỉnh tổ chức Lễ tôn vinh trí thức Bắc Ninh tiêu biểu, trao Giải thưởng Khoa học và Công nghệ (KHCN), Hội thi Sáng tạo kỹ thuật tỉnh Bắc Ninh, lần thứ Nhất, năm 2025. Dự hội nghị có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh; Nguyễn Quyết Chiến, Tổng thư ký Liên hiệp các Hội Khoa học và Kỹ thuật Việt Nam; GS.TS Dương Xuân Ngọc, nguyên Phó Giám đốc Học viện Báo chí và Tuyên truyền, Chủ tịch Hội các nhà Khoa học Bắc Giang tại Hà Nội; đại diện lãnh đạo các sở, ngành, địa phương, cơ quan, đơn vị và 68 trí thức đạt danh hiệu Trí thức Bắc Ninh tiêu biểu, 155 tác giả và cộng sự của 16 công trình đạt Giải thưởng KHCN, 51 giải pháp đạt giải Hội thi Sáng tạo kỹ thuật tỉnh Bắc Ninh năm 2025.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/54780701/b1+%281%29.jpg/c6fa2dbf-ceac-4b54-c810-cd3e8f248373?t=1764901567720\" style=\"width: 900px; height: 521px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 5/12, Ban Chấp hành Đảng bộ tỉnh Bắc Ninh khóa I tổ chức Hội nghị lần thứ hai, nhiệm kỳ 2025-2030. Đồng chí Nguyễn Hồng Thái, Ủy viên Ban Chấp hành Trung ương Đảng, Bí thư Tỉnh ủy chủ trì hội nghị. Dự hội nghị có các đồng chí: Nguyễn Văn Tùng, Vụ trưởng Vụ địa phương I, Ban Tổ chức Trung ương; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; đại diện lãnh đạo một số Ban Đảng Trung ương và các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy, Ban Chấp hành Đảng bộ tỉnh. Tại hội nghị, &nbsp;Ban Chấp hành Đảng bộ tỉnh đã thông qua Tờ trình của Ban Thường vụ Tỉnh ủy Bắc Ninh về việc bầu cử chức danh Phó Bí thư Tỉnh ủy nhiệm kỳ 2025-2030. Theo đó, đồng chí Trần Huy Phương, Ủy viên Ban Thường vụ Tỉnh ủy, Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy Bắc Ninh được giới thiệu để bầu vào chức danh Phó Bí thư Tỉnh ủy Bắc Ninh nhiệm kỳ 2025- 2030. Đồng chí Trần Huy Phương được tín nhiệm với số phiếu tuyệt đối 67/67 (đạt 100%).</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/18152201/Lehoitraicay+Dai+bieu+tinh+tham+quan+gian+hang.jpg/18eff8d6-85a1-df38-e65d-dd5a84aa8575?t=1764937477952\" style=\"width: 900px; height: 499px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tối 05/12, tại Quảng trường Trung tâm phường Chũ, Bộ Công Thương phối hợp với UBND tỉnh Bắc Ninh long trọng tổ chức khai mạc Lễ hội Trái cây tỉnh Bắc Ninh năm 2025 với chủ đề “Trái cây Bắc Ninh – Tinh hoa nông sản Việt”. <span lang=\"VI\">Tham dự&nbsp;khai mạc&nbsp;Lễ hội&nbsp;</span>có các đồng chí:&nbsp;Nguyễn Hồng Thái, Uỷ viên Trung ương Đảng, Bí thư Tỉnh uỷ; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh uỷ; Nguyễn Việt Oanh, Phó Bí thư Tỉnh uỷ, Chủ tịch HĐND tỉnh; Phạm Hoàng Sơn, Phó Bí thư Tỉnh uỷ, Chủ tịch UBND tỉnh; các đồng chí Uỷ viên Ban Thường vụ Tỉnh uỷ, lãnh đạo HĐND, UBND; đại diện lãnh đạo các Cục, Vụ thuộc các cơ quan Trung ương;&nbsp;<span lang=\"VI\">đại diện lãnh đạo</span>&nbsp;Sở Công Thương một số tỉnh; lãnh đạo các sở, ban, ngành, địa phương,&nbsp;<span lang=\"VI\">doanh nghiệp, hợp tác xã, nhà vườn cùng đông đảo Nhân dân, du khách.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200628/IMG_9726456.jpg/d69ea143-7e59-fb74-303b-3d48dae89a28?t=1764843237861\" style=\"width: 900px; height: 600px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 04/12, Đoàn công tác của Thường trực Tỉnh ủy do đồng chí Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy làm trưởng đoàn có buổi làm việc với Ban Thường vụ Đảng ủy phường Tam Sơn và phường Phù Khê để nắm bắt tình hình kết quả thực hiện nhiệm vụ chính trị từ ngày 01/7/2025 đến nay; nhiệm vụ trọng tâm trong thời gian tới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200628/CTlvSoXD+1.jpg/250974b5-f20a-a89d-b28f-e5c5f7d1b9e7?t=1764390991784\" style=\"width: 900px; height: 542px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 29/11, Chủ tịch UBND tỉnh Phạm Hoàng Sơn chủ trì buổi làm việc với Sở Xây dựng để nắm bắt tiến độ triển khai các quy hoạch quan trọng và tình hình thực hiện các dự án giao thông trọng điểm trên địa bàn tỉnh. Dự buổi làm việc có lãnh đạo Văn phòng UBND tỉnh, Sở Xây dựng, Sở Tài chính.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/41409701/2-4.png/c2cf85c9-e481-13ba-2f17-a45d81d4efed?t=1764652036852\" style=\"width: 900px; height: 600px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 02/12, đồng chí Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh tiếp và làm việc với ông Chen Rui Sheng, CEO Tập đoàn Yangjie (Trung Quốc) về việc hỗ trợ Công ty TNHH Micro Commercial Components (MCC) Việt Nam triển khai mở rộng hoạt động đầu tư tại Khu công nghiệp (KCN) Yên Phong II-C. Cùng dự có Thiếu tướng Bùi Duy Hưng, Ủy viên Ban Thường vụ Tỉnh ủy, Giám đốc Công an tỉnh; lãnh đạo một số sở, ban, ngành liên quan.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/54780701/5.jpg/86441bc5-0130-5b08-ed4a-79c6fd45e89d?t=1764742561039\" style=\"width: 900px; height: 507px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trưa 3/12, UBND tỉnh tổ chức Lễ ký kết Bản ghi nhớ hợp tác hữu nghị giữa tỉnh Bắc Ninh (Việt Nam) với tỉnh Gyeongsangbuk (Hàn Quốc). Dự Lễ Ký kết có đồng chí Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; ngài Lee Cheol Woo, Tỉnh trưởng tỉnh Gyeongsangbuk; đại diện lãnh đạo sở, cơ quan, đơn vị liên quan hai tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/30456144/4-5.png/adf4b837-8779-fe7c-0555-e60e36fcb6e7?t=1764841791116\" style=\"width: 900px; height: 570px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 04/12, tại Trung tâm Văn hóa Kinh Bắc (phường Vũ Ninh, tỉnh Bắc Ninh), Chi cục Hải quan khu vực V tổ chức hội nghị Hải quan - Doanh nghiệp năm 2025, đánh dấu kim ngạch xuất nhập khẩu vượt mốc 200 tỷ USD và vinh danh các doanh nghiệp tiêu biểu trên địa bàn quản lý (2 tỉnh Bắc Ninh, Thái Nguyên). Dự hội nghị có các đồng chí: Phạm Hoàng Sơn, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Bắc Ninh; Nguyễn Thanh Bình, Phó Bí thư Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh Thái Nguyên; Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh Bắc Ninh; Trần Đức Hùng, Phó Cục trưởng Cục Hải quan; đại diện lãnh đạo một số sở, ban, ngành của tỉnh cùng hơn 120 doanh nghiệp đại diện cho cộng đồng doanh nghiệp của 02 tỉnh Bắc Ninh, Thái Nguyên.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/54780701/z7291792412903_1722ec13d63bff8637521342354c9d8c.jpg/a9f81b1b-6fd6-696f-9331-2962570fa018?t=1764836949866\" style=\"width: 900px; height: 600px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 04/12, Thường trực HĐND tỉnh tổ chức Họp báo về Kỳ họp thứ 8 (kỳ họp thường lệ) HĐND tỉnh Bắc Ninh khóa XIX, nhiệm kỳ 2021 - 2026. Các đồng chí: Trần Thị Hằng, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch Thường trực HĐND tỉnh; Nguỵ Văn Tuyên, Chánh Văn phòng Đoàn đại biểu Quốc hội (ĐBQH) và HĐND tỉnh chủ trì họp báo. Dự buổi họp báo có đại diện lãnh đạo&nbsp;các sở, ban, ngành liên quan; lãnh đạo, phóng viên các cơ quan thông tấn, báo chí địa phương và Trung ương thường trú trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/30456144/hn2.png/68e8577c-9a3d-8c14-c0cb-5990bdc8fa74?t=1764586501113\" style=\"width: 900px; height: 530px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 01/12, tại thành phố Hà Nội, đồng chí Nguyễn Thanh Tịnh, Thứ trưởng Bộ Tư pháp chủ trì hội nghị trực tuyến hướng dẫn thực hiện rà soát, chuẩn hóa toàn bộ thủ tục hành chính (TTHC) ở 3 cấp chính quyền. Dự và chủ trì tại điểm cầu Bắc Ninh có đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh. Cùng dự có lãnh đạo một số sở, ngành liên quan.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/41409701/a1.jpg/72749346-4fd0-cb38-a040-7bfd2c51daec?t=1764656331121\" style=\"width: 900px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 02/12, đồng chí Đào Quang Khải, Uỷ viên Ban Thường vụ Tỉnh uỷ, Phó Chủ tịch UBND tỉnh chủ trì họp Hội đồng thẩm định Bảng giá đất nhằm xem xét, thống nhất nội dung dự thảo Nghị quyết quy định tiêu chí xác định vị trí từng loại đất và quyết định Bảng giá đất trên địa bàn tỉnh Bắc Ninh giai đoạn mới. Dự hội nghị có đại diện lãnh đạo sở, ngành, đơn vị, địa phương trong tỉnh. Trưa 02/12, Phó Chủ tịch UBND tỉnh Đào Quang Khải chủ trì Hội nghị trực tuyến với các địa phương về triển khai tiến độ Chiến dịch “làm giàu, làm sạch” cơ sở dữ liệu (CSDL) đất đai trên địa bàn tỉnh Bắc Ninh. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/54780701/1.png/6c2efa74-5314-414d-6e00-94bacdcef5e4?t=1764744982596\" style=\"width: 900px; height: 586px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 03/12, đồng chí Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh về dự sinh hoạt với các đảng viên Chi bộ Tổ dân phố Hoàng Văn Thụ, phường Bắc Giang, tỉnh Bắc Ninh. Chiều 03/12, Phó Chủ tịch UBND tỉnh Ngô Tân Phượng về dự sinh hoạt chi bộ thường kỳ tháng 12/2025 với đảng viên Tổ dân phố Tân Mai, phường Đa Mai, tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200628/IMG_9624.jpg/d2eeeff1-17e9-dc54-a9c7-20728c2bb8dc?t=1764755721850\" style=\"width: 900px; height: 600px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 03/12, Liên minh Hợp tác xã (HTX) tỉnh Bắc Ninh tổng kết thực hiện Đề án “Hỗ trợ phát triển mô hình HTX ứng dụng công nghệ 4.0 trong quản lý điều hành hoạt động sản xuất kinh doanh (SXKD) và mô hình HTX nông nghiệp khởi nghiệp ứng dụng công nghệ cao trên địa bàn tỉnh Bắc Giang giai đoạn 2021-2025” (Đề án 4.0 và khởi nghiệp) và Đề án “Hỗ trợ nâng cao năng lực quản trị và hiệu quả hoạt động kế toán, kiểm toán trong các HTX trên địa bàn tỉnh Bắc Giang giai đoạn 2022-2025 và tầm nhìn đến năm 2030” (Đề án quản trị). Tham dự có đồng chí Phan Thế Tuấn, Phó chủ tịch UBND tỉnh; đại diện lãnh đạo một số Sở, ban, ngành liên quan, các xã, phường, HTX tiêu biểu trong tỉnh tham gia thực hiện 2 Đề án.</span></span></span></p>', '2025-12-05 09:29:00', 'https://bacninh.gov.vn/news/-/details/37632/hoat-ong-noi-bat-cua-lanh-ao-tinh-tu-ngay-29-11-5-12-2025-80467301', '', 'BNP', 191, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.260528', 6, 11);
INSERT INTO `sync_articles` VALUES (356, '77181001', 'Bắc Ninh đảm bảo an ninh trật tự, giao thông thông suốt và vệ sinh phục vụ Lễ hội...', 'Bắc Ninh đảm bảo an ninh trật tự, giao thông thông suốt và vệ sinh phục vụ Lễ hội trái cây 2025', '/documents/37632/200628/ATGTLehoi.jpg/edb32835-cb85-84b2-80bb-44d617ed61d3?t=1764926266918', '<p>(BNP) - Tại&nbsp;<a href=\"/documents/37632/200628/5572+CV+UBND+KTTH.pdf/92870868-6bae-e99d-857b-2f4f7f052212?t=1764926219843\">Công văn số 5572/UBND-KTTH</a>, Chủ tịch UBND tỉnh yêu cầu&nbsp;đảm bảo an ninh trật tự, phân luồng giao thông và vệ sinh môi trường tại các khu vực trong thời gian diễn...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/ATGTLehoi.jpg/edb32835-cb85-84b2-80bb-44d617ed61d3?t=1764926266918\" style=\"height: 559px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm đảm bảo an ninh trật tự và giao thông thông suốt trong thời gian Lễ hội diễn ra từ ngày 05 đến ngày 10/12/2025, Chủ tịch UBND tỉnh giao Công an tỉnh chủ trì, chỉ đạo các lực lượng chức năng phối hợp với UBND phường Chũ và các đơn vị liên quan xây dựng phương án đảm bảo an ninh trật tự tại các khu vực của Lễ hội, gồm: Quảng trường trung tâm thị trấn Chũ, Hội trường và phòng họp UBND phường Chũ, các nhà vườn phục vụ du khách tham quan, sân khấu tổ chức các hoạt động chính của Lễ hội…</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, bố trí phương án phân luồng và điều tiết giao thông, tránh ùn tắc tại các điểm trọng yếu như dọc Quốc lộ 31, các trục đường chính quanh Quảng trường thị trấn Chũ và những tuyến đường nông thôn dẫn vào các điểm du lịch.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đảng uỷ, UBND các xã, phường: Chũ, Lục Ngạn, Nghĩa Phương, Phượng Sơn, Lục Sơn, Nam Dương phối hợp chặt chẽ với Công an tỉnh trong công tác giữ gìn an ninh trật tự và phân luồng giao thông tại địa phương; nghiên cứu bố trí lực lượng cắm biển cảnh báo đối với xe ô tô quá khổ tại các khu vực dễ ùn tắc, đồng thời hướng dẫn người dân và du khách di chuyển theo lộ trình hợp lý. Các địa phương tiếp tục tăng cường công tác đảm bảo vệ sinh trên toàn bộ khu vực tổ chức Lễ hội.</span></span></span></p>', '2025-12-05 09:16:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-am-bao-an-ninh-trat-tu-giao-thong-thong-suot-va-ve-sinh-phuc-vu-le-hoi-trai-cay-2025-77181001', '', 'Dương Thuỷ', 200, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.298238', 6, 11);
INSERT INTO `sync_articles` VALUES (357, '75851213', 'Phụ nữ tỉnh Bắc Ninh chung tay hướng về đồng bào miền Trung, Tây Nguyên', 'Phụ nữ tỉnh Bắc Ninh chung tay hướng về đồng bào miền Trung, Tây Nguyên', '/documents/37632/30456144/pn5.jpg/3f3cbb44-f13f-f945-d698-abfbac0d332c?t=1764901141096', '<p>(BNP) - Với tinh thần \"tương thân tương ái\" và trách nhiệm cộng đồng, các cấp Hội phụ nữ tỉnh Bắc Ninh đã và đang tiếp tục triển khai các đợt vận động, quyên góp, chung tay hướng về đồng bào miền Trung và Tây Nguyên, những nơi vừa gánh chịu hậu quả nặng nề của thiên tai, bão lũ.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/pn5.jpg/3f3cbb44-f13f-f945-d698-abfbac0d332c?t=1764901141096\" style=\"height: 609px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cấp Hội Phụ nữ tỉnh Bắc Ninh chung tay ủng hộ đồng bào bị ảnh hưởng bởi lũ lụt.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại phường Tiền Phong, thực hiện chỉ đạo của Hội LHPN tỉnh, Hội LHPN phường Tiền Phong đã vận động được 300kg gạo, 70 thùng mì, 600kg rau, củ quả, 50 bịch nước, 120 chăn, màn, 40 bao quần áo, với tổng trị giá 130 triệu đồng để chuyển đến hỗ trợ Nhân dân phường Phú Yên bị ảnh hưởng bởi bão, lũ.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/30456144/2192538005987710726.jpg/74499d98-a093-4b1e-d9fb-dcbcdd5f32aa?t=1764902908932\" style=\"height: 675px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội LHPN phường Kinh Bắc gửi tặng các nhu yếu phẩm cho bà con Nhân dân&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">tỉnh <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đắk Lắk</span><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"> </span></span></span><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">bị ảnh hưởng bởi bão, lũ.</span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thực hiện sự chỉ đạo của Hội LHPN tỉnh, Hội LHPN phường Kinh Bắc đã tích cực phối hợp với Tổ dân phố triển khai vận động cán bộ, hội viên và Nhân dân ủng hộ đồng bào bị thiệt hại do bão lũ gây ra với số tiền hơn 440 triệu đồng. Bên cạnh đó, Chi hội Phụ nữ Suối Hoa đã kết nối và trao gửi 23.000 vở mới và nhu yếu phẩm đến bà con vùng lũ tỉnh Đắk Lắk.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/pt.jpg/ac5caeb9-8c78-be3b-317b-42075a0ed55e?t=1764902280230\" style=\"height: 625px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\">Hội viên, phụ nữ thôn Nghĩa Chỉ tích cực chuẩn bị các nhu yếu phẩm để gửi tặng&nbsp;bà con Nhân dân các tỉnh Khánh Hòa, Đắk Lắc bị ảnh hưởng bởi bão, lũ.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Còn tại xã Phật Tích, trong 3 ngày (</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">từ ngày 23 - 24/11/2025), Chi hội Phụ nữ thôn Nghĩa Chỉ đã phối hợp cùng các mạnh thường quân quyên góp được 25 tấn gạo, hơn 3.600 thùng mì tôm, 785 thùng sữa, 1.652 thùng nước lọc cùng nhiều nhu yếu phẩm và chăn, sách vở, bút, quần áo cũ mới các loại để chuyển đến ủng hộ bà con, Nhân dân các tỉnh Khánh Hòa, Đắk Lắk bị ảnh hưởng bởi bão, lũ.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/3.png/966ac527-8f70-b1ce-f079-265973bfb7d5?t=1764902044301\" style=\"height: 733px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cán bộ, hội viên Phụ nữ phường Yên Dũng tích cực&nbsp;chuẩn bị quần áo công sở còn mới, sạch sẽ để gửi tặng các thầy cô đang gặp khó khăn do mưa lũ tại phường Phú Yên, tỉnh <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đắk Lắk.</span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại phường Yên Dũng, những ngày qua, với tinh thần “tương thân tương ái” lan tỏa rộng khắp ở 35 tổ dân phố trên địa bàn phường. Chị em phụ nữ đã tích cực chuẩn bị quần áo công sở còn mới, sạch sẽ; phân loại, giặt là, gấp gọn và đóng gói cẩn thận để gửi tặng các thầy cô đang gặp khó khăn do mưa lũ tại phường Phú Yên, tỉnh <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đắk Lắk</span></span></span>. Hoạt động nhận - phân loại - đóng gói diễn ra sôi nổi, thể hiện tấm lòng sẻ chia của phụ nữ Yên Dũng đối với ngành giáo dục tại vùng lũ.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/pn1.jpg/c5ce1837-bb7d-7b87-6ec5-b8c1969453c8?t=1764901991454\" style=\"height: 603px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Toàn bộ số áo dài quyên góp được&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội LHPN phường Đa Mai </span></span>được Hội đóng thùng và kịp thời gửi đến phụ nữ xã Tuy An Tây.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong khí đó, Hội LHPN phường Đa Mai đã triển khai đợt vận động đầy ý nghĩa đó là phát động phong trào quyên góp áo dài gửi tặng cho cán bộ Hội phụ nữ cơ sở và giáo viên xã Tuy An Tây, tỉnh Đắk Lắk - nơi vừa phải gánh chịu nhiều thiệt hại nặng nề sau trận lũ lịch sử.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chỉ sau hai ngày phát động, phong trào đã nhận được sự hưởng ứng mạnh mẽ của đông đảo cán bộ, hội viên phụ nữ trên địa bàn phường. Với tinh thần “lá lành đùm lá rách”, các chị đã gửi về Hội gần 300 bộ áo dài còn mới, chất lượng tốt. Mỗi bộ áo dài là một sự chia sẻ, một tấm lòng được gửi gắm trong từng gói quà nhỏ nhưng chứa đầy tình cảm. Toàn bộ số áo dài trên được Hội đóng thùng và kịp thời gửi đến phụ nữ xã Tuy An Tây trong ngày 03/12/2025. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/30456144/pn3.jpg/15151367-ca03-cdf9-068c-568c51638ef0?t=1764901964527\" style=\"height: 599px; width: 900px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chung tay cùng các cấp hội Phụ nữ trong tỉnh, vừa qua, Hội Phụ nữ Công an tỉnh đã tổ chức vận động cán bộ chiến sĩ, các nhà hảo tâm trong và ngoài lực lượng, quyên góp được 12 tấn quần áo nam, nữ, trẻ em và chăn ấm, cùng với 70 thùng sữa, các nhu yếu phẩm cần thiết khác và 120 triệu đồng, góp phần giúp đỡ bà con Đắk Lắk vượt qua khó khăn trong thời gian tới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hoạt động ý nghĩa này tiếp tục khẳng định vai trò nòng cốt của Mặt trận và tổ chức Hội LHPN trong việc phát huy sức mạnh đại đoàn kết toàn dân, góp phần tiếp thêm sức mạnh, giúp đồng bào vùng bão lũ sớm vượt qua khó khăn, ổn định cuộc sống./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '2025-12-05 02:18:00', 'https://bacninh.gov.vn/news/-/details/37632/phu-nu-tinh-bac-ninh-chung-tay-huong-ve-ong-bao-mien-trung-tay-nguyen-75851213', '', 'Nguyễn Nhàn', 70, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.325275', 6, 11);
INSERT INTO `sync_articles` VALUES (358, '71029006', 'Đảm bảo tiến độ, chất lượng trong xây dựng Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn...', 'Đảm bảo tiến độ, chất lượng trong xây dựng Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025 - 2030, tầm nhìn đến 2035', '/documents/37632/30456116/1.jpg/abfbb683-3750-591a-c181-733a401e278d?t=1764824911483', '<p>(BNP) - Sáng 4/12, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh chủ trì buổi làm việc về xây dựng dự thảo Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025 - 2030, tầm nhìn đến 2035. Dự buổi làm việc có đại diện Trung tâm Dữ liệu quốc gia (Bộ Công an), Tập...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456116/a2.jpg/1e49794f-3b64-32d0-7e78-ac07bdbeaf23?t=1764824521657\" style=\"height: 501px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh buổi làm việc.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo báo cáo của Sở Khoa học và Công nghệ (<span style=\"background:white\">KH&amp;CN</span>), việc xây dựng dự thảo Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025-2030, tầm nhìn đến 2035 được triển khai trên cơ sở hệ thống các văn bản chỉ đạo của Chính phủ, đặc biệt là những văn bản mới ban hành, nhằm thúc đẩy quá trình chuyển đổi số, xây dựng Chính phủ số và phát triển dữ liệu thành một tài nguyên mới.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288663/a4+%281%29.jpg/e011af4c-ed72-7650-165c-4cf314aba43c?t=1764824813402\" style=\"height: 586px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Đồng chí Nguyễn Gia Phong, Phó Giám đốc Sở Khoa học và Công nghệ tỉnh phát biểu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quá trình xây dựng dự thảo Chiến lược, Sở KH&amp;CN đã nghiên cứu, tham khảo kinh nghiệm xây dựng chiến lược dữ liệu của nhiều địa phương; đồng thời đối chiếu với các định hướng tại Chiến lược dữ liệu quốc gia, thực trạng của địa phương, bảo đảm tính thống nhất, phù hợp với thực tiễn phát triển của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo Quyết định phê duyệt Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025 - 2030, tầm nhìn đến năm 2035, gồm 3 Điều với các nội dung chính: Quan điểm, tầm nhìn, nguyên tắc, mục tiêu, nhiệm vụ trọng tâm và giải pháp xây dựng chiến lược dữ liệu tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456112/a3+%283%29.jpg/a99347c4-d519-02aa-c9e2-25e5856fda0f?t=1764824581569\" style=\"height: 568px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Đại tá Nguyễn Thành Vĩnh, Phó Giám đốc Trung tâm Dữ liệu quốc gia&nbsp;<span style=\"line-height:1.3;\">(Bộ Công an) phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, đại diện Trung tâm Dữ liệu quốc gia (Bộ Công an) đã báo cáo về việc triển khai Luật Dữ liệu và các văn bản ban hành. Đồng thời khẳng định sẽ đồng hành cùng tỉnh Bắc Ninh xây dựng Chiến lược dữ liệu tỉnh, nhất là trong đ<span style=\"background:white\">iều chỉnh toàn diện về hoạt động xử lý, quản trị, điều phối dữ liệu, xác định rõ công tác quản lý nhà nước về dữ liệu.</span> Qua đó, góp phần xây dựng hệ thống dữ liệu thống nhất, an toàn, kết nối toàn diện; biến dữ liệu thành nguồn lực chiến lược, hỗ trợ chuyển đổi cơ cấu kinh tế, nâng cao hiệu lực quản lý nhà nước, mang lại lợi ích thiết thực cho công dân và doanh nghiệp.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456116/a5.jpg/4d715cf6-f556-f12d-1497-4ace4f15d430?t=1764824693224\" style=\"height: 617px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\">Đồng chí Nguyễn Ngọc Nam, Phó Chánh Văn phòng UBND tỉnh, Giám đốc&nbsp;Trung tâm phục vụ Hành chính công tỉnh phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thảo luận tại buổi làm việc, các đại biểu đã trao đổi làm rõ các nội dung còn khó khăn, vướng mắc trong xây dựng, chuẩn hóa dữ liệu như: Sự thống nhất từ điển dữ liệu của cơ sở dữ liệu quốc gia; giải pháp tổng thể xây dựng từ điển dữ liệu của địa phương thống nhất với quốc gia; chuẩn hóa dữ liệu của các sở, ngành, đơn vị trong tỉnh; tính thừa kế từ điển dữ liệu của quốc gia; các quy định tiêu chuẩn dữ liệu... </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456116/1.jpg/abfbb683-3750-591a-c181-733a401e278d?t=1764824911483\" style=\"height: 571px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh&nbsp;<span style=\"line-height:1.3;\">kết luận buổi làm việc.</span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết luận buổi làm việc, đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh ghi nhận các ý kiến trao đổi, đóng góp của đại diện các Bộ, ngành, cơ quan Trung ương đối với các nội dung dự thảo Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025 - 2030, tầm nhìn đến 2035. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để các nội dung dự thảo Chiến lược dữ liệu tỉnh Bắc Ninh giai đoạn 2025 - 2030, tầm nhìn đến 2035 sớm hoàn thiện, đảm bảo phù hợp với chủ trương của Đảng, các quy định pháp luật, Phó Chủ tịch Thường trực UBND tỉnh yêu cầu Sở KH&amp;CN chủ trì phối hợp với Công an tỉnh và các sở, ngành tiếp thu đầy đủ các ý kiến của đại diện các bộ, ngành, cơ quan Trung ương tổng hợp, bổ sung vào nội dung dự thảo Chiến lược dữ liệu tỉnh theo tinh thần “6 rõ”: Rõ mục tiêu, rõ nhiệm vụ, rõ sản phẩm, rõ tiến độ, rõ nguồn lực và rõ trách nhiệm thực hiện. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh nhấn mạnh, dự thảo Chiến lược không chỉ dừng ở định hướng mà phải được cụ thể hóa thành hệ thống kế hoạch, chương trình hành động, khi áp dụng đảm bảo tính thông suốt. Do đó, nội dung dự thảo Chiến lược không chung chung, không dàn trải, phải đảm bảo bám sát khung kiến trúc dữ liệu quốc gia, các quy định mới ban hành, đặc biệt là yêu cầu trong quản trị dữ liệu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh cũng lưu ý, với đặc thù là tỉnh công nghiệp phát triển mạnh, Bắc Ninh cần đặc biệt quan tâm đến Chiến lược dữ liệu doanh nghiệp - một bộ phận trọng yếu trong hệ sinh thái dữ liệu của tỉnh. Việc xây dựng khung dữ liệu doanh nghiệp thống nhất sẽ tạo nền tảng để kết nối, phân tích, hỗ trợ hoạch định chính sách và đồng hành với doanh nghiệp trong chiến lược sản xuất - kinh doanh, nhất là trong bối cảnh cạnh tranh toàn cầu và xu hướng sản xuất thông minh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ các ý kiến trao đổi, thảo luận, Phó Chủ tịch Thường trực UBND tỉnh mong muốn các Bộ, ngành, cơ quan chuyên môn Trung ương tiếp tục phối hợp, đồng hành với tỉnh Bắc Ninh xây dựng Chiến lược dữ liệu đảm bảo tiến độ, chất lượng và là một trong những địa phương triển khai mô hình điểm về tạo lập cơ sở dữ liệu trong giai đoạn chuyển đổi số toàn diện hiện nay.</span></span></span></p>', '2025-12-04 05:00:00', 'https://bacninh.gov.vn/news/-/details/37632/-am-bao-tien-o-chat-luong-trong-xay-dung-chien-luoc-du-lieu-tinh-bac-ninh-giai-oan-2025-2030-tam-nhin-en-2035-71029006', '', 'Nguyễn Miền', 312, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.351466', 6, 11);
INSERT INTO `sync_articles` VALUES (359, '65347203', 'Bắc Ninh triển khai kế hoạch hỗ trợ hệ sinh thái khởi nghiệp đổi mới sáng tạo giai...', 'Bắc Ninh triển khai kế hoạch hỗ trợ hệ sinh thái khởi nghiệp đổi mới sáng tạo giai đoạn 2025 - 2030', '/documents/37632/30456112/b2+%281%29.jpg/85ac4086-a41e-3e4f-624c-aaff10522bac?t=1764753599563', '<p>(BNP) - Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh vừa ký Kế hoạch số 151/KH-UBND về việc hỗ trợ hệ sinh thái khởi nghiệp đổi mới sáng tạo tỉnh Bắc Ninh giai đoạn 2025 - 2030, định hướng đến năm 2045.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/30456112/b2+%281%29.jpg/85ac4086-a41e-3e4f-624c-aaff10522bac?t=1764753599563\" style=\"height: 595px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Hỗ trợ khởi nghiệp nông nghiệp công nghệ cao, nông nghiệp sạch, nông nghiệp số.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Kế hoạch nhằm tạo lập môi trường thuận lợi để thúc đẩy, hỗ trợ quá trình hình thành và phát triển loại hình doanh nghiệp có khả năng tăng trưởng nhanh dựa trên khai thác tài sản trí tuệ, công nghệ, mô hình kinh doanh mới. Hỗ trợ phát triển hệ sinh thái khởi nghiệp đổi mới sáng tạo của tỉnh phát triển ngang tầm khu vực, nâng cao năng lực cạnh tranh của doanh nghiệp, phát triển sản phẩm chủ lực của tỉnh, góp phần nâng cao tỷ trọng đóng góp của năng suất các nhân tố tổng hợp vào GRDP đến năm 2030 đạt từ 45%.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phấn đấu giai đoạn 2025 - 2030, tỉnh có từ 40% tỷ lệ doanh nghiệp có hoạt động đổi mới sáng tạo; khoảng 30% doanh nghiệp có hoạt động đổi mới quy trình, mô hình kinh doanh; có từ 30 dự án đổi mới sáng tạo được hỗ trợ từ ngân sách của tỉnh; có từ 20 sáng chế, giải pháp hữu ích có địa chỉ tại tỉnh; số lượng đơn đăng ký sáng chế, văn bằng bảo hộ sáng chế tăng trung bình đạt 16%/năm;…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Định hướng đến 2045, tỉnh có từ 800 doanh nghiệp khởi nghiệp sáng tạo; khoảng 25 vườn ươm/trung tâm đổi mới sáng tạo; có từ 50 - 70 dự án khởi nghiệp sáng tạo; 40% tỷ lệ doanh nghiệp có hoạt động đổi mới sáng tạo; 90% doanh nghiệp có hoạt động đổi mới quy trình, mô hình kinh doanh; số lượng đơn đăng ký sáng chế, văn bằng bảo hộ sáng chế tăng trung bình đạt 18%/năm…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Để đạt được các mục tiêu trên, UBND tỉnh tập trung các giải pháp về đẩy mạnh truyền thông, phổ biến về chính sách, cơ chế hỗ trợ, các hoạt động khởi nghiệp đổi mới sáng. Hoàn thiện thể chế, cơ chế, chính sách thúc đẩy khởi nghiệp đổi mới sáng tạo.&nbsp;Hỗ trợ khởi nghiệp nông nghiệp công nghệ cao, nông nghiệp sạch, nông nghiệp số. Hoàn thiện thể chế, khơi thông các điểm nghẽn đang cản trở khởi nghiệp đổi mới sáng tạo, khuyến khích được mọi nguồn lực xã hội đầu tư cho khởi nghiệp đổi mới sáng tạo tạo của tỉnh Bắc Ninh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phát huy vai trò của các trường đại học, cao đẳng (đặc biệt là các cơ sở có năng lực đào tạo công nghệ cao) xây dựng không gian sáng tạo mở, phòng thí nghiệm công nghệ và vườn ươm khởi nghiệp. Hỗ trợ kinh phí cho các đơn vị tuyển chọn, triển khai ươm tạo các ý tưởng khởi nghiệp đổi mới sáng tạo hàng năm. Hỗ trợ phát triển tăng tốc các doanh nghiệp khởi nghiệp đổi mới sáng tạo. Thúc đẩy hoạt động hợp tác quốc tế về khởi nghiệp đổi mới sáng tạo; kết nối mạng lưới, mở rộng quan hệ hợp tác với nước ngoài.&nbsp;</span></span></span><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Xây dựng văn hóa khởi nghiệp, tinh thần doanh nhân, tư duy đổi mới sáng tạo ngay tại các trường đại học; tạo nền tảng để hình thành và nâng cao chất lượng các ý tưởng khởi nghiệp tiềm năng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">UBND tỉnh giao Sở Khoa học và Công nghệ chủ trì, phối hợp với các sở, ngành, địa phương và các đơn vị có liên quan tổ chức triển khai kế hoạch; hỗ trợ xây dựng thương hiệu, nhãn hiệu, chỉ dẫn địa lý cho sản phẩm khởi nghiệp. Hướng dẫn các thủ tục pháp lý liên quan đến công bố sản phẩm, mã vạch, mã QR, xây dựng tiêu chuẩn cơ sở cho các sản phẩm, các dự án khởi nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các sở, ban, ngành và UBND xã, phường căn cứ chức năng nhiệm vụ, quyền hạn phối hợp với Sở Khoa học và Công nghệ tổ chức thực hiện Kế hoạch; vận động, hình thành các hệ sinh thái đổi mới sáng tạo chuyên ngành, nhất là các ngành trọng điểm và nhóm sản phẩm chủ lực. Chủ động xác định nhu cầu đổi mới sáng tạo của doanh nghiệp để phối hợp với Sở Khoa học và Công nghệ kết nối với cộng đồng hệ sinh thái đổi mới sáng tạo./.</span></span></span></p>', '2025-12-03 09:19:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-ke-hoach-ho-tro-he-sinh-thai-khoi-nghiep-oi-moi-sang-tao-giai-oan-2025-2030-65347203', '', 'Nguyễn Miền', 413, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.376097', 6, 11);
INSERT INTO `sync_articles` VALUES (360, '63698306', 'Hơn 3.500 lượt học sinh, giáo viên, công nhân được tuyên truyền, phổ biến pháp luật...', 'Hơn 3.500 lượt học sinh, giáo viên, công nhân được tuyên truyền, phổ biến pháp luật về an toàn giao thông', '/documents/37632/200628/ATGT+tuan1+12.jpg/67d7613f-924d-d8fd-4931-69b1712b2d2c?t=1764728918632', '<p>(BNP) - Phòng Cảnh sát giao thông Công an tỉnh Bắc Ninh cho biết, tuần từ ngày 24/11 đến 30/11/2025, toàn tỉnh xảy ra 14 vụ tai nạn giao thông đường bộ, làm 9 người chết và 6 người bị thương. Nguyên nhân chủ yếu do người tham gia giao thông vi phạm quy định pháp luật về trật tự an toàn giao...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/ATGT+tuan1+12.jpg/67d7613f-924d-d8fd-4931-69b1712b2d2c?t=1764728918632\" style=\"height: 566px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong tuần, Phòng Cảnh sát giao thông đã đẩy mạnh công tác tuyên truyền, phổ biến pháp luật về an toàn giao thông với 12 buổi tuyên truyền cho hơn 3.500 lượt học sinh, giáo viên, công nhân; cấp phát 500 tờ gấp; đăng tải 25 tin bài tuyên truyền; phối hợp với các cơ quan truyền thông xây dựng 3 tin bài phản ánh tình hình và kết quả công tác bảo đảm trật tự an toàn giao thông.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lực lượng Cảnh sát giao thông tổ chức tuần tra, kiểm soát, tập trung xử lý các hành vi vi phạm là nguyên nhân trực tiếp gây tai nạn như vi phạm nồng độ cồn, ma túy, chạy quá tốc độ, tránh vượt sai quy định, điều khiển phương tiện đi sai phần đường, làn đường, không chấp hành đèn tín hiệu giao thông, chở hàng quá tải, quá khổ…</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với chuyên đề nồng độ cồn, Cảnh sát giao thông phối hợp với công an cơ sở lập các tổ, chốt kiểm soát trên các tuyến đường theo tinh thần “không có vùng cấm, không có ngoại lệ”.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả, lực lượng tổ chức 728 ca tuần tra, huy động 2.776 lượt cán bộ chiến sĩ, xử lý hơn 3.800 trường hợp vi phạm, tạm giữ 1.325 phương tiện, tước quyền sử dụng giấy phép lái xe 105 trường hợp, trừ điểm giấy phép lái xe 805 trường hợp. Thông qua hệ thống camera giám sát và thiết bị nghiệp vụ, lực lượng phát hiện 180 trường hợp vi phạm.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên tuyến đường thủy, lực lượng chức năng kiểm tra, lập biên bản 13 trường hợp vi phạm; phát hiện và bắt giữ 6 trường hợp sử dụng kích điện khai thác thủy sản trên sông Thương, sông Cầu và sông Lục Nam, lực lượng Cảnh sát đường thủy đã bàn giao cho công an địa phương xử lý.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phòng Cảnh sát giao thông cũng cho biết, nguyên nhân tai nạn chủ yếu vẫn xuất phát từ sự chủ quan của người tham gia giao thông. Người dân cần chấp hành nghiêm các quy định về tốc độ, phần đường, làn đường; tuân thủ đèn tín hiệu; giảm tốc khi đi qua điểm giao cắt không có đèn; đội mũ bảo hiểm khi điều khiển mô tô, xe gắn máy; không giao phương tiện cho người chưa đủ điều kiện điều khiển.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong điều kiện thời tiết mưa nhỏ, sương mù, tầm nhìn hạn chế, người điều khiển phương tiện cần bật đèn chiếu sáng phù hợp, đảm bảo tốc độ an toàn và giữ khoảng cách với xe phía trước để hạn chế tai nạn.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với lĩnh vực đường thủy, lực lượng chức năng khuyến cáo người dân tuyệt đối không sử dụng kích điện, thuốc nổ, hóa chất để khai thác thủy sản; khi phát hiện vi phạm cần báo ngay cho Công an xã, phường hoặc Cảnh sát đường thủy để xử lý kịp thời.</span></span></span></p>', '2025-12-03 02:24:00', 'https://bacninh.gov.vn/news/-/details/37632/hon-3-500-luot-hoc-sinh-giao-vien-cong-nhan-uoc-tuyen-truyen-pho-bien-phap-luat-ve-an-toan-giao-thong-63698306', '', 'Dương Thuỷ', 397, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.398875', 6, 11);
INSERT INTO `sync_articles` VALUES (361, '63661701', 'Thời tiết ngày 3/12: Không khí lạnh ảnh hưởng đến Bắc Bộ, vùng núi cao có nơi rét đậm', 'Thời tiết ngày 3/12: Không khí lạnh ảnh hưởng đến Bắc Bộ, vùng núi cao có nơi rét đậm', 'https://img.baobacninhtv.vn/Medias/565/2025/12/02/1%20copy.jpg', '<p>(BNP) - Theo Trung tâm Dự báo khí tượng thủy văn quốc gia, khoảng gần sáng và sáng 3/12, một đợt không khí lạnh tăng cường sẽ ảnh hưởng đến khu vực Đông Bắc Bộ, Bắc Trung Bộ và một số nơi ở phía Tây Bắc Bộ; sau đó ảnh hưởng đến các nơi khác ở Tây Bắc Bộ và một số nơi ở Trung Trung Bộ. Trên đất...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://img.baobacninhtv.vn/Medias/565/2025/12/02/1%20copy.jpg\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa. (nguồn Báo và Phát thanh, truyền hình Bắc Ninh)</span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ đêm 3/12, thời tiết tại Bắc Bộ và Bắc Trung Bộ chuyển rét, vùng núi cao có nơi rét đậm. Nhiệt độ thấp nhất phổ biến 15-18 độ C; vùng núi 13-15 độ C và một số khu vực núi cao có thể xuống dưới 11 độ C. Tại Hà Nội, đêm 3/12 trở lạnh rõ rệt, nền nhiệt dao động 15-18 độ C.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ở khu vực Bắc Bộ và bắc Trung Bộ có mưa, mưa nhỏ rải rác. Từ đêm 3/12 trời rét, vùng núi cao của Bắc Bộ có nơi rét đậm.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên biển, ngày và đêm 3/12, vùng biển phía tây khu vực giữa Biển Đông và vùng biển từ nam Quảng Trị đến Cà Mau có mưa rào và dông rải rác; trong mưa dông có khả năng xảy ra lốc xoáy và gió giật mạnh cấp 6–7.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không chỉ gây rét, không khí lạnh tăng cường khi kết hợp với hoàn lưu vùng áp thấp suy yếu từ bão số 15 và nhiễu động gió Đông trên cao sẽ làm xuất hiện đợt mưa vừa đến mưa to kéo dài từ đêm 2 đến 5/12. Khu vực chịu ảnh hưởng mạnh gồm Quảng Trị - Đà Nẵng, phía Đông các tỉnh từ Quảng Ngãi đến Đắk Lắk và Khánh Hòa.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đợt rét và mưa này có nguy cơ gây ảnh hưởng đến vật nuôi, cây trồng; đồng thời làm gia tăng nguy cơ ngập úng tại vùng trũng thấp, lũ quét trên các sông suối nhỏ và sạt lở đất ở khu vực miền núi. Ở trên biển, gió mạnh và sóng lớn sẽ gây nguy hiểm cho tàu thuyền hoạt động.</span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"></span></span></span></p>', '2025-12-03 02:15:00', 'https://bacninh.gov.vn/news/-/details/37632/thoi-tiet-ngay-3-12-khong-khi-lanh-anh-huong-en-bac-bo-vung-nui-cao-co-noi-ret-am-63661701', '', 'BNP', 234, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.421677', 6, 11);
INSERT INTO `sync_articles` VALUES (362, '63604503', 'Bắc Ninh: Điều chỉnh 12 tuyến đường huyện (cũ) thành đường tỉnh', 'Bắc Ninh: Điều chỉnh 12 tuyến đường huyện (cũ) thành đường tỉnh', '/documents/37632/30456116/3-1.png/b6a134d3-966a-caa2-ea5e-1d1364314c71?t=1764727048689', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Phan Thế Tuấn vừa ký, ban hành Quyết định số 478/QĐ-UBND điều chỉnh các tuyến đường huyện (cũ) trên địa bàn tỉnh Bắc Ninh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/30456116/3-1.png/b6a134d3-966a-caa2-ea5e-1d1364314c71?t=1764727048689\" style=\"height: 622px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tuyến đường gom bên trái tuyến cao tốc Hà Nội - Bắc Giang (hướng từ Hà Nội đi Lạng Sơn).</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cụ thể, điều chỉnh 12 tuyến đường huyện (cũ) dài 181,42 km thành đường tỉnh và đặt số hiệu mới cho các tuyến đường tỉnh sau khi điều chỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Tam Dị - Đông Phú - Đông Hưng điều chỉnh thành ĐT.290B; </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Nam Dương - Đèo Gia - Tuấn Đạo điều chỉnh thành ĐT.291B; </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến đường từ Trung tâm Y tế huyện Lạng Giang (cũ) đi Mỹ Hà điều chỉnh thành ĐT.292B; </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến đường từ thị trấn Bố Hạ qua xã Đông Sơn, huyện Yên Thế (cũ) đi trường Cao đẳng Nghề Đông Bắc điều chỉnh thành ĐT.292C;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Đại Lâm - An Hà; Vôi - Mỹ Thái - Tiên Lục điều chỉnh thành ĐT.293B;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Tuyến Cao Thượng - Phúc Hòa và Đường nối ĐT.294 với ĐT.292 điều chỉnh thành ĐT.294C;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến đường trục Bắc Nam, huyện Hiệp Hòa điều chỉnh thành ĐT.296B;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Hồng Thái - ĐT.298 - QL.37 - ĐT.398 - Cầu Hà Bắc 1 điều chỉnh thành ĐT.298B;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến ĐH.5B và đoạn qua KCN Quang Châu điều chỉnh thành ĐT.398;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến Kép - Nghĩa Hưng - Tiên Lục và đoạn từ ĐT.398 đến Cầu Hà Bắc 2 điều chỉnh thành ĐT.398B;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến đường gom bên trái tuyến cao tốc Hà Nội - Bắc Giang (hướng từ Hà Nội đi Lạng Sơn) điều chỉnh thành ĐT.398C;</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">- Tuyến đường gom bên phải tuyến cao tốc Hà Nội - Bắc Giang (hướng từ Hà Nội đi Lạng Sơn) điều chỉnh thành ĐT.398D.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Ngoài ra, điều chỉnh 214 tuyến đường huyện (cũ) còn lại dài 1.169,24 km thành đường xã theo địa giới hành chính của cấp xã. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">UBND tỉnh giao Sở Xây dựng phối hợp với UBND cấp xã và các chủ đầu tư kiểm kê tài sản hiện trạng trên các tuyến đường và lập biên bản bàn giao các đường huyện (cũ) điều chỉnh thành đường tỉnh (trừ hệ thống điện chiếu sáng, đèn tín hiệu giao thông, cây xanh trên tuyến) về Sở Xây dựng quản lý theo quy định. Riêng các đoạn tuyến đang được đầu tư xây dựng, Sở Xây dựng tiếp nhận quản lý sau khi dự án hoàn thành.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">UBND các xã, phường tiếp tục tổ chức quản lý, vận hành, khai thác, bảo trì đối với các tuyến đường huyện (cũ) điều chỉnh đường xã theo địa giới hành chính của cấp xã theo quy định.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Sở Tài chính hàng năm tham mưu UBND tỉnh bố trí kinh phí để thực hiện công tác quản lý, vận hành, khai thác, bảo trì đối với các tuyến đường theo quy định./.</span></span></span></p>', '2025-12-03 01:56:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-ieu-chinh-12-tuyen-uong-huyen-cu-thanh-uong-tinh-63604503', '', 'Linh Ngọc', 6740, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.444518', 6, 11);
INSERT INTO `sync_articles` VALUES (363, '54813504', 'Bắc Ninh: Danh sách 211 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 23 -...', 'Bắc Ninh: Danh sách 211 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 23 - 30/11/2025', '/documents/37632/18835561/591721213_122158318124804369_551062495658550868_n.jpg/8e5ea3ba-a6a2-94a3-588c-a4afca0c7c95?t=1764589323411', '<p>(BNP) - Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 23/11/2025 đến 30/11/2025, ghi nhận 211 trường hợp xe ô tô vi phạm bị phạt nguội.</p>', '<p style=\"text-align: center;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span><img src=\"/documents/37632/18835561/591721213_122158318124804369_551062495658550868_n.jpg/8e5ea3ba-a6a2-94a3-588c-a4afca0c7c95?t=1764589323411\" style=\"height: 509px; width: 900px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>22 trường hợp ô tô không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/3011+o+to+1.png/88b77b98-b482-ce6f-020a-c13558d6f8b2?t=1764589348979\" style=\"height: 186px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>61 trường hợp ô tô không chấp hành hiệu lệnh, chỉ dẫn của vạch kẻ đường:</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+o+to+2.png/1f1af74c-cfe0-44d5-3b7b-e613bd748b8c?t=1764589360918\" style=\"height: 440px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>97 trường hợp ô tô điều khiển xe chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+o+to+bieu+3.png/8ea9de24-2a0d-5eb7-df8a-28cd007bec3a?t=1764589374542\" style=\"height: 695px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>15 trường hợp ô tô rẽ trái tại nơi có biển cấm:<span lang=\"VI\"></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+o+to+4.png/c67b0117-233c-3cee-5e8b-29ff12a5f53e?t=1764589386513\" style=\"height: 141px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 12 trường hợp ô tô dừng xe dưới gầm cầu vượt: </span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+o+to+5.png/127d1fab-7990-8d71-b479-7cdcaeb73308?t=1764589399071\" style=\"height: 138px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 01 trường hợp quay đầu xe ở phần đường dành cho người đi bộ qua đường: 99A-637.48.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định.</span> <span lang=\"VI\">Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định.</span>/.</span></span></span> <span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></p>', '2025-12-02 00:30:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-211-truong-hop-xe-o-to-vi-pham-bi-phat-nguoi-tu-ngay-23-30-11-2025-54813504', '', 'BNP', 3000, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.468589', 6, 11);
INSERT INTO `sync_articles` VALUES (364, '54813154', 'Bắc Ninh: Danh sách 66 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 23...', 'Bắc Ninh: Danh sách 66 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 23 - 30/11/2025', '/documents/37632/18835561/591718863_122158318088804369_6188264476537353811_n.jpg/ae747ff5-14d6-6c50-39c4-af528c8de7b6?t=1764589220288', '<p>(BNP)- Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 23/11/2025 đến 30/11/2025, ghi nhận 66 trường hợp xe mô tô (xe máy)<strong> </strong>vi phạm phạt nguội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/591718863_122158318088804369_6188264476537353811_n.jpg/ae747ff5-14d6-6c50-39c4-af528c8de7b6?t=1764589220288\" style=\"height: 506px; width: 900px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>61 trường hợp mô tô (xe máy) không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+xe+may+bieu+1.png/465f69a2-fa9e-0cdd-d84a-3b211a83175e?t=1764589243350\" style=\"height: 462px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 05 trường hợp mô tô (xe máy) chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/18835561/3011+xe+may+bieu+2.png/9101f463-a7f1-7717-f93b-c49e65596db0?t=1764589270206\" style=\"height: 111px; width: 800px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định. Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định./. </span></span></span></p>', '2025-12-01 11:39:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-66-truong-hop-xe-mo-to-xe-may-vi-pham-bi-phat-nguoi-tu-ngay-23-30-11-2025-54813154', '', 'BNP', 2672, 'Xã hội', 6, '', '38762', '{}', '2025-12-08 08:20:41.492435', 6, 11);

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `age` int(11) NOT NULL,
  `created_at` datetime(6) NULL DEFAULT NULL,
  `created_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `gender` enum('FEMALE','MALE','OTHER') CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `refresh_token` mediumtext CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL,
  `updated_at` datetime(6) NULL DEFAULT NULL,
  `updated_by` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `company_id` bigint(20) NULL DEFAULT NULL,
  `role_id` bigint(20) NULL DEFAULT NULL,
  `is_admin` bit(1) NULL DEFAULT NULL,
  `phone` varchar(255) CHARACTER SET utf8 COLLATE utf8_vietnamese_ci NULL DEFAULT NULL,
  `app_id` bigint(20) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `FKin8gn4o1hpiwe6qe4ey7ykwq7`(`company_id`) USING BTREE,
  INDEX `FKp56c1712k691lhsyewcssf40f`(`role_id`) USING BTREE,
  INDEX `FKo38sepgtwex7a8g44tt5utnts`(`app_id`) USING BTREE,
  CONSTRAINT `FKin8gn4o1hpiwe6qe4ey7ykwq7` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FKo38sepgtwex7a8g44tt5utnts` FOREIGN KEY (`app_id`) REFERENCES `apps` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `FKp56c1712k691lhsyewcssf40f` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8 COLLATE = utf8_vietnamese_ci ROW_FORMAT = DYNAMIC;

